-- Raccoon City: Reunited  (v0.1.0-NonRT)
-- A co-op partner for Resident Evil 2 (2019): local shared-screen co-op with HUNK as
-- player 2, and networked co-op (LAN / internet) via the rcu network plugin. Requires REFramework.
--
-- How the controller split works: the game reads input through static InputSystem
-- functions that always use the "active" pad. The mod tags the update methods of the
-- player and weapon components with which character is running, and when HUNK's code
-- asks for input it answers from the second controller instead.
--
-- Settings: REFramework menu (Insert) -> Script Generated UI -> "Raccoon City: Reunited".
-- Don't save the game while HUNK is spawned.

local HUNK_PREFAB = "ObjectRoot/Prefab/Character/Player/pl4000.pfb"
local HUNK_NAME = "pl4000"
local SURVIVOR_PL4000 = 4
local ROLE_PLAYER = 1

local st = {
    enabled_route = true,
    pin_p1_pad = true,
    hunk = nil,              -- via.GameObject
    pending = nil,           -- via.Prefab while loading
    fix_at = nil, verify_at = nil, fix_tries = 0,
    owners = {},             -- component address -> player GameObject name
    stacks = {},             -- thread id -> context stack
    unit2 = nil, pad2dev_addr = nil, p2_src = nil, kstate = {},
    pad_maps = {},           -- controller model -> player 2's button mapping (co-op menu > Controllers)
    p1_pick = "", p2_pick = "",   -- chosen controllers ("" = automatic, "kbm", "none", or a controller id)
    -- physical controllers by UniqueId (stable while connected); the game's InputUnit
    -- slots can be reshuffled at any time, so we never trust slot numbers
    p1_uid = nil, p2_uid = nil, p1_dev = nil, swaps_fixed = 0,
    frame = 0, msg = "",
    force_on = {},           -- InputDefine.Kind -> true: press it for HUNK (used by B reload)
    -- HUNK's aim while it is driven by the mod (sub-weapon stick aim / facing the crosshair)
    vaim = { active = false, yaw = 0, pitch = 0 },
    aim_speed = 2.2, invert_x = false, invert_y = false,
    infinite_ammo = true,
    -- face buttons used by the mod are hidden from the game for HUNK (Y 16, A 32, X 64, B 128, Decide, Cancel)
    reserved_buttons = 16 | 32 | 64 | 128 | 131072 | 262144, kind_btn = {},
    heal_amount = 400, heal_cooldown = 20, resupply_cooldown = 30,
    next_heal = 0, next_resupply = 0, toast = nil,
    show_hud = true, pick_radius = 1.6,
    pick = nil, force_trig_addr = nil,
    -- sub-weapon aim: while HUNK holds the knife / grenade, pad 2's right stick turns and
    -- tilts him independently of P1's camera (yaw via his aim direction, pitch via his spine)
    sub_aim = true, spine_w = 0, max_pitch = 1.0,
    -- shared aim: while HUNK aims a gun his body turns and tilts to face P1's crosshair point
    p2_cutscene_fun = false, -- "Player 2 In Cutscenes (Fun)": seen and playable in cutscenes (off: hidden and still)
    p2_autoaim = false,      -- Tank Controls: auto-aim for player 2 even when the Classic Cameras mod's own is off
    offscreen_ind = true,    -- arrow on the screen edge towards HUNK when he's off screen
    sfx = true,              -- sound effects (played by the re2r_mp_sfx.dll plugin)
    sfx_abilities = false,   -- (v420) the heal / resupply sounds too (off by default since v420)
    hud_alpha = 0xB8,        -- HUD icon opacity (0-255)
    p2_model = "hunk",       -- player 2's character model: hunk / leon / claire / ada
    costume_leon = 1, costume_claire = 0, costume_ada = 1,   -- SurvivorDefine.Costume per model
    costume_sherry = 0, costume_tofu = 0, costume_hunk = 0, costume_trucker = 0,
    -- player 2's weapons (EquipmentDefine.WeaponType) on d-pad up / left / right; the knife
    -- is always kept and the throwable is the flash grenade (66) or the hand grenade (65)
    weapon_up = 11, weapon_left = 7, weapon_right = 23, throwable = 66,
    -- experimental split screen: Leon's view and a camera of player 2's own
    split = false, split_layout = 1, p2cam_dist = 2.4, split_hud = 80, split_bloom = false, keep_p2_area = true, p2_fov_pct = 100, p2_dist_pct = 100, p2_side = 0, p1_fov_pct = 100, p1_side = 0, p1_dist_pct = 100,   -- layout 1 side by side, 2 top / bottom
    -- experimental AI partner: HUNK follows Leon, shoots enemies and uses his support abilities
    ai = false, ai_range = 15, ai_heal_pct = 50, ai_resupply = true, ai_follow_dist = 2.0,
    own_rig = true,          -- player 2 is built from the chosen character's own prefab (skeleton, voice)
    -- player 2 (a person on a pad) follows the Fixed Camera mod's controls when it is installed
    p2_cc = true,
    p2_laser = true,
    p1_laser = false,        -- (v385) a laser sight on player 1's gun too
    p2_free_aim = true,      -- player 2 aims by hand with the right stick on one screen (the mod's own)
    p2_aggro = 4,            -- (v388) how much enemies go for player 2 / the AI: 1 less, 2 normal, 3 more, 4 most (default Most since v409)
    aggro_rev = 0,           -- (v409) 1 once a config saved with the old default (Normal) has been moved to Most
    -- AI behaviours (each can be switched off in the co-op menu > AI partner)
    ai_ranges = true, ai_backoff = true, ai_knife = true, ai_dodge = true, ai_clear_shot = true,
    ai_mirror = true, ai_unstuck = true, ai_wheel = true, wheel_slow = true,
    -- what's drawn on screen (co-op menu > Display)
    hud_cooldowns = true, hud_weapons = true, ai_markers = true, ai_callouts = true, wheel_hint = true,
    -- player 1 on keyboard + mouse, player 2 on a controller
    p1_kbm = false,
}
-- (NonRT) which game build: the Non-RT (DX11) version runs older game data (TDB 66; the RT
-- version is 70). Set here, before anything that checks it. Every Non-RT-only change in this
-- build is gated on st.NON_RT, so on the RT game this file behaves as the RT release.
do
    local ok, v = pcall(function() return sdk.get_tdb_version() end)
    st.TDB = ok and v or nil
    st.NON_RT = type(st.TDB) == "number" and st.TDB < 70
end
-- (NonRT-5) Is this input device the empty one? The RT game has Device.get_Null; on Non-RT (TDB 66)
-- that getter doesn't exist (the call gives nil), so every controller counted as "not a real
-- device": no controllers were found at all (st.pads empty), and every menu driven by a
-- controller never opened. There the empty device is GamePad's NullDevice (or one that isn't
-- connected). On RT get_Null answers and nothing changes.
-- (NonRT-12) draw.world_to_screen in the Non-RT REFramework build (v1.5.9 TDB66) answers (0, 0) for
-- everything, so every marker placed in the world (the AI partner's order spot, the off-screen
-- arrows' on-screen test) was drawn in the top-left corner or not at all. There it's worked out
-- from the main camera's ViewProjMatrix over the whole screen (what the RT build gives); nil when
-- the point is behind the camera.
if st.NON_RT and draw and draw.world_to_screen then
    draw.world_to_screen = function(p)
        local cam = sdk.get_primary_camera()
        if cam == nil or p == nil then return nil end
        local ok, vp = pcall(function() return cam:call("get_ViewProjMatrix") end)
        if not ok or vp == nil then return nil end
        local a = vp * Vector4f.new(p.x, p.y, p.z, 1.0)
        if a.w <= 1e-4 then return nil end
        local ds = imgui.get_display_size()
        return Vector2f.new((a.x / a.w + 1) / 2 * ds.x, (1 - a.y / a.w) / 2 * ds.y)
    end
end
-- (NonRT-6) Text sizes. The Non-RT REFramework build (v1.5.9 TDB66) has no imgui.push_font_size /
-- pop_font_size, so every menu's text came out at one small size. There they're made from
-- load_font + push_font / pop_font, one font per pixel size. load_font(nil, size) gives the
-- built-in font at its one fixed size whatever is asked, so a real file is used:
-- reframework/fonts/reunited_ui.ttf (Rajdhani, SIL OFL; bundled with Raccoon City: Reunited).
if st.NON_RT and imgui and imgui.push_font_size == nil and imgui.load_font and imgui.push_font and imgui.pop_font then
    local fonts, pushed = {}, {}
    imgui.push_font_size = function(sz)
        sz = math.max(8, math.floor((tonumber(sz) or 16) + 0.5))
        local f = fonts[sz]
        if f == nil then
            local ok, r = pcall(imgui.load_font, "reunited_ui.ttf", sz)
            f = ok and r or false
            fonts[sz] = f
        end
        if f then
            local ok = pcall(imgui.push_font, f)
            pushed[#pushed + 1] = ok
        else
            pushed[#pushed + 1] = false
        end
    end
    imgui.pop_font_size = function()
        if table.remove(pushed) then pcall(imgui.pop_font) end
    end
    st.font_shim = true
end
function st.dev_null(d)
    if d == nil then return true end
    local ok, v = pcall(function() return d:call("get_Null") end)
    if ok and v ~= nil then return v == true end
    if not st.NON_RT then return false end
    local ok2, nd = pcall(function()
        return sdk.call_native_func(nil, sdk.find_type_definition("via.hid.GamePad"), "get_NullDevice")
    end)
    if ok2 and nd and nd:get_address() == d:get_address() then return true end
    local ok3, c = pcall(function() return d:call("get_Connecting") end)
    return not (ok3 and c == true)
end

local function safe(fn, ...)
    local ok, r = pcall(fn, ...)
    if ok then return r end
    return nil
end

local function say(m)
    st.msg = m
    log.info("[reunited] " .. m)
end

-- component lookups are cached per GameObject; the cache is dropped every second
-- and whenever HUNK spawns / despawns so a recycled address can't return a stale one
local comp_cache = {}
local type_cache = {}
local function comp(go, tname)
    if go == nil then return nil end
    local addr = go:get_address()
    local per = comp_cache[addr]
    if per == nil then per = {}; comp_cache[addr] = per end
    local c = per[tname]
    if c == nil then
        local t = type_cache[tname]
        if t == nil then t = sdk.typeof(tname); type_cache[tname] = t end
        c = safe(function() return go:call("getComponent(System.Type)", t) end) or false
        per[tname] = c
    end
    return c or nil
end
local function clear_comp_cache() comp_cache = {} end

local function players()
    local out = {}
    local pm = sdk.get_managed_singleton("app.ropeway.PlayerManager")
    local l = pm and safe(function() return pm:get_field("PlayerList") end)
    local n = l and safe(function() return l:call("get_Count") end) or 0
    for i = 0, n - 1 do
        local pc = safe(function() return l:call("get_Item", i) end)
        local go = pc and safe(function() return pc:call("get_GameObject") end)
        if go then out[#out + 1] = go end
    end
    if #out == 0 then
        -- the manager's list can be empty after some reloads: find the players in the scene
        local scene = safe(function()
            return sdk.call_native_func(sdk.get_native_singleton("via.SceneManager"), sdk.find_type_definition("via.SceneManager"), "get_CurrentScene")
        end)
        local comps = scene and safe(function() return scene:call("findComponents(System.Type)", sdk.typeof("app.ropeway.survivor.player.PlayerCondition")) end)
        local cn = comps and safe(function() return comps:call("get_Count") end) or 0
        for i = 0, cn - 1 do
            local go = safe(function() return comps:call("get_Item", i):call("get_GameObject") end)
            if go then out[#out + 1] = go end
        end
    end
    return out
end

local function p1_go()
    local pm = sdk.get_managed_singleton("app.ropeway.PlayerManager")
    return pm and safe(function() return pm:call("get_CurrentPlayer") end)
end

-- Context tracking ------------------------------------------------------------

local tid = thread.get_id
local function stack()
    local id = tid()
    local s = st.stacks[id]
    if s == nil then s = {}; st.stacks[id] = s end
    return s
end

-- owner codes for components of the two players and their child objects
local OWN_P1, OWN_P1W, OWN_HUNK, OWN_HUNKW = 1, 2, 3, 4
local KEY_MUL = 4096   -- stack entry = owner * KEY_MUL + hooked-method index

-- innermost player-owned frame: returns owner code (or nil) and hooked-method index
local function current_owner()
    local s = stack()
    for i = #s, 1, -1 do
        local e = s[i]
        if e >= KEY_MUL then return e // KEY_MUL, e % KEY_MUL end
    end
    return nil, 0
end

local hooked_keys = {}
local hooked_types = {}
local n_context_hooks = 0
local context_installed = false


local function is_context_method(n, weapon)
    if n == "update" or n == "lateUpdate" or n == "onUpdate"
        or (n:match("^do") ~= nil and n:match("Update$") ~= nil) or n:match("^update") ~= nil then
        return true
    end
    -- weapon objects fire and pick targets outside their update methods
    return weapon and (n:match("^execute") ~= nil or n:match("[Ff]ire") ~= nil or n:match("^generate") ~= nil)
end

-- Only player-logic types can read input / aim for HUNK. Profiling showed every
-- HUNK input and camera read happens inside app.ropeway.survivor.* or the weapon
-- (app.ropeway.implement.*) components; effects, audio, collision etc. were ~1,700
-- hooked calls per frame for nothing. Base classes outside these namespaces are never
-- hooked, since hooking them would catch every object in the game.
local CONTEXT_NS = { "^app%.ropeway%.survivor%.", "^app%.ropeway%.implement%." }
local function context_type(name)
    for _, pat in ipairs(CONTEXT_NS) do if name:match(pat) then return true end end
    return false
end

local function hook_type_context(td, weapon)
    local tkey = td:get_full_name() .. (weapon and "#w" or "")
    if hooked_types[tkey] then return end
    hooked_types[tkey] = true
    local t = td
    while t ~= nil and context_type(t:get_full_name()) do
        for _, m in ipairs(t:get_methods()) do
            local key = t:get_full_name() .. "::" .. m:get_name() .. "/" .. m:get_num_params()
            if not m:is_static() and not hooked_keys[key] and is_context_method(m:get_name(), weapon) then
                hooked_keys[key] = true
                local idx = n_context_hooks + 1
                sdk.hook(m, function(args)
                    local s = stack()
                    s[#s + 1] = (st.owners[sdk.to_int64(args[2])] or 0) * KEY_MUL + idx
                end, function(r)
                    local s = stack()
                    s[#s] = nil
                    return r
                end)
                n_context_hooks = n_context_hooks + 1
            end
        end
        t = t:get_parent_type()
    end
end

local function child_objects(go, acc, depth)
    if depth > 3 then return acc end
    local xf = safe(function() return go:call("get_Transform") end)
    local c = xf and safe(function() return xf:call("get_Child") end)
    local guard = 0
    while c ~= nil and guard < 200 do
        guard = guard + 1
        local cg = safe(function() return c:call("get_GameObject") end)
        if cg then
            acc[#acc + 1] = cg
            child_objects(cg, acc, depth + 1)
        end
        c = safe(function() return c:call("get_Next") end)
    end
    return acc
end

local has_loadout   -- defined with the loadout below
local function refresh_owners()
    local owners = {}
    -- Player 2 is the GameObject the mod spawned (st.hunk). Only when it isn't known yet (after a
    -- script reset) is a "pl4000" adopted, and never the game's own player: in The 4th Survivor
    -- player 1 is HUNK, also named pl4000, and was taken for player 2.
    local p1 = p1_go()
    local p1a = p1 and safe(function() return p1:get_address() end)
    local ha = st.hunk and safe(function() return st.hunk:get_address() end)
    for _, go in ipairs(players()) do
        local name = safe(function() return go:call("get_Name") end)
        local addr = safe(function() return go:get_address() end)
        local is_p2
        if ha then is_p2 = addr == ha
        else is_p2 = name == HUNK_NAME and p1a ~= nil and addr ~= p1a end
        local arr = safe(function() return go:call("get_Components") end)
        for _, c in ipairs(arr and arr:get_elements() or {}) do
            owners[c:get_address()] = is_p2 and OWN_HUNK or OWN_P1
            if context_installed then
                local td = c:get_type_definition()
                if td:get_full_name():match("^app%.") then pcall(hook_type_context, td, false) end
            end
        end
        -- child objects (weapon, flashlight, body parts) count as the same player
        for _, cg in ipairs(child_objects(go, {}, 0)) do
            local carr = safe(function() return cg:call("get_Components") end)
            for _, c in ipairs(carr and carr:get_elements() or {}) do
                owners[c:get_address()] = is_p2 and OWN_HUNKW or OWN_P1W
                if context_installed then
                    local td = c:get_type_definition()
                    if td:get_full_name():match("^app%.") then pcall(hook_type_context, td, true) end
                end
            end
        end
        -- (not the HUNK just removed: the game lists him until he's gone, and adopting him
        -- again made the mod act on a dying player 2)
        local gone = st.despawned and st.despawned.addr == addr and st.frame < st.despawned.until_frame
        if is_p2 and st.hunk == nil and not st.unloading and not gone then
            st.hunk = go:add_ref()
            if st.detect_rig then st.rig = st.detect_rig(go) end
            local hinv = comp(go, "app.ropeway.survivor.Inventory")
            st.loadout_given = hinv ~= nil and st.infinite_ammo and has_loadout(hinv) or false
            say("HUNK has joined the mission")
        end
    end
    st.owners = owners
end

local function install_context_hooks(go)
    local arr = go:call("get_Components")
    for _, c in ipairs(arr:get_elements()) do
        local td = c:get_type_definition()
        if td:get_full_name():match("^app%.") then hook_type_context(td, false) end
    end
    context_installed = true
    say("Ready. Press Start + Back on the second controller to deploy HUNK.")
end

local function is_hunk_owner(o)
    return o == OWN_HUNK or o == OWN_HUNKW
end

-- Input routing ---------------------------------------------------------------

local IS = sdk.find_type_definition("app.ropeway.InputSystem")

-- controller brands (via.hid.DeviceKindDetails): display name and face-button style
local PAD_NAMES = { [5] = "DualShock 4", [6] = "DualShock 4", [8] = "DualSense", [9] = "DualSense",
    [10] = "Xbox controller", [11] = "Arcade stick", [12] = "Xbox controller", [13] = "Controller",
    [14] = "Controller", [15] = "Stadia controller", [16] = "Joy-Con", [17] = "Switch Pro controller" }
local PAD_STYLE = { [5] = "ps", [6] = "ps", [8] = "ps", [9] = "ps", [16] = "nin", [17] = "nin" }
-- what the positional buttons are called on each brand (Switch has A and B swapped)
local BTN_NAMES = {
    xbox = { A = "A", B = "B", X = "X", Y = "Y", BACK = "View", START = "Menu", L3 = "LS", R3 = "RS" },
    ps = { A = "Cross", B = "Circle", X = "Square", Y = "Triangle", BACK = "Share", START = "Options", L3 = "L3", R3 = "R3" },
    nin = { A = "B", B = "A", X = "Y", Y = "X", BACK = "-", START = "+", L3 = "LS", R3 = "RS" },
}
-- Controllers -------------------------------------------------------------------------
-- Player 2 can use any pad: the ones the game supports itself (XInput / Xbox, DualShock 4,
-- DualSense, Switch Pro), read straight from via.hid whether or not the game gave them an
-- input slot, and any other USB pad Windows knows (generic DirectInput pads, PS3 pads,
-- arcade sticks...) through the reunited_pads plugin. Whatever it is, player 2 plays
-- through a virtual Xbox pad (st.pad.vpad): each of its buttons and sticks is mapped from
-- the real controller, like an emulator (co-op menu > Controllers > Map player 2's
-- controls). The rest of the mod only ever reads that virtual pad.
st.pad = { ext = { trusted = false, list = {}, last_alive = nil, alive_t = 0, next_read = 0 }, maps_default = {} }
;(function()
    local PD = st.pad
    local GP = sdk.find_type_definition("via.hid.GamePad")

    -- the virtual pad's controls, in mapper order. bit = via.hid.GamePadButton bit(s)
    PD.CTRLS = {
        { id = "LUP", label = "Left stick up", stick = "LY", dir = 1 },
        { id = "LDOWN", label = "Left stick down", stick = "LY", dir = -1 },
        { id = "LLEFT", label = "Left stick left", stick = "LX", dir = -1 },
        { id = "LRIGHT", label = "Left stick right", stick = "LX", dir = 1 },
        { id = "RUP", label = "Right stick up", stick = "RY", dir = 1 },
        { id = "RDOWN", label = "Right stick down", stick = "RY", dir = -1 },
        { id = "RLEFT", label = "Right stick left", stick = "RX", dir = -1 },
        { id = "RRIGHT", label = "Right stick right", stick = "RX", dir = 1 },
        { id = "A", label = "A (interact / pick up)", bit = 32 | 131072 },
        { id = "B", label = "B (reload)", bit = 128 | 262144 },
        { id = "X", label = "X (refill player 1's magazine)", bit = 64 },
        { id = "Y", label = "Y (heal player 1)", bit = 16 },
        { id = "LB", label = "LB (knife / grenade)", bit = 256 },
        { id = "RB", label = "RB", bit = 1024 },
        { id = "LT", label = "LT (aim)", bit = 512, analog = "L" },
        { id = "RT", label = "RT (shoot)", bit = 2048, analog = "R" },
        { id = "DUP", label = "D-pad up", bit = 1 },
        { id = "DDOWN", label = "D-pad down", bit = 2 },
        { id = "DLEFT", label = "D-pad left", bit = 4 },
        { id = "DRIGHT", label = "D-pad right", bit = 8 },
        { id = "BACK", label = "Back / Share", bit = 16384 },
        { id = "START", label = "Start / Options", bit = 32768 },
        { id = "L3", label = "L3 (left stick click)", bit = 4096 },
        { id = "R3", label = "R3 (right stick click)", bit = 8192 },
    }
    PD.CTRL = {}
    for _, c in ipairs(PD.CTRLS) do PD.CTRL[c.id] = c end

    -- sources: { t = "b", i = button bit index } | { t = "a", i = axis 1..6, s = +-1, r = rest }
    --          | { t = "h", d = 1..4 (hat up / right / down / left) }
    -- game pads: buttons are via.hid bits; axes 1-4 = left x / y, right x / y, 5-6 = triggers
    local function b(i) return { t = "b", i = i } end
    local function a(i, s, r) return { t = "a", i = i, s = s, r = r or 0 } end
    local function h(d) return { t = "h", d = d } end
    PD.maps_default.game = {
        LUP = a(2, 1), LDOWN = a(2, -1), LLEFT = a(1, -1), LRIGHT = a(1, 1),
        RUP = a(4, 1), RDOWN = a(4, -1), RLEFT = a(3, -1), RRIGHT = a(3, 1),
        A = b(5), B = b(7), X = b(6), Y = b(4), LB = b(8), RB = b(10), LT = a(5, 1), RT = a(6, 1),
        DUP = b(0), DDOWN = b(1), DLEFT = b(2), DRIGHT = b(3), BACK = b(14), START = b(15), L3 = b(12), R3 = b(13),
    }
    -- the usual layout of generic DirectInput pads (PlayStation-style numbering)
    PD.maps_default.ext = {
        LUP = a(2, -1), LDOWN = a(2, 1), LLEFT = a(1, -1), LRIGHT = a(1, 1),
        RUP = a(4, -1), RDOWN = a(4, 1), RLEFT = a(3, -1), RRIGHT = a(3, 1),
        X = b(0), A = b(1), B = b(2), Y = b(3), LB = b(4), RB = b(5), LT = b(6), RT = b(7),
        BACK = b(8), START = b(9), L3 = b(10), R3 = b(11),
        DUP = h(1), DRIGHT = h(2), DDOWN = h(3), DLEFT = h(4),
    }

    -- plugin -------------------------------------------------------------------------
    -- reunited_pads.txt: "addr N", "alive N", "pad id vid pid xinput nbuttons naxes name"
    function PD.read_ext()
        local E = PD.ext
        if st.frame < E.next_read then return end
        E.next_read = st.frame + 60
        local ok, txt = pcall(fs.read, "reunited_pads.txt")
        if not ok or type(txt) ~= "string" or txt == "" then
            if os.clock() - E.alive_t > 4 then E.trusted = false end
            return
        end
        local addr = tonumber(txt:match("addr (%d+)"))
        local alive = tonumber(txt:match("alive (%d+)"))
        local list = {}
        for id, vid, pid, xi, nb, na, name in txt:gmatch("pad (%d+) (%x+) (%x+) (%d) (%d+) (%d+) ([^\r\n]*)") do
            list[#list + 1] = { idx = tonumber(id), vid = vid, pid = pid, xinput = xi == "1",
                nbuttons = tonumber(nb), naxes = tonumber(na), name = name }
        end
        -- only trust the address once the plugin is seen ticking in this session
        if alive and alive ~= E.last_alive then
            if E.last_alive ~= nil and addr and addr == E.addr then E.trusted = true end
            E.last_alive, E.alive_t = alive, os.clock()
        end
        if os.clock() - E.alive_t > 4 then E.trusted = false end
        if addr ~= E.addr then E.trusted = false end
        E.addr = addr
        E.list = list
    end
    -- one pad's raw state from the plugin's memory block (64 bytes per pad after a header)
    local raw_cache = {}
    function PD.ext_raw(idx)
        local E = PD.ext
        if not E.trusted or E.addr == nil then return nil end
        local c = raw_cache[idx]
        if c and c.frame == st.frame then return c end
        local ok, vt = pcall(sdk.to_valuetype, E.addr + 64 * (idx + 1), "via.mat4")
        if not ok or vt == nil then return nil end
        local flags = vt:read_dword(0)
        if flags & 1 == 0 then return nil end
        c = { frame = st.frame, buttons = vt:read_dword(4), pov = vt:read_dword(8), axes = {} }
        for i = 1, 6 do c.axes[i] = vt:read_float(12 + 4 * i) end
        raw_cache[idx] = c
        return c
    end
    local function game_raw(dev)
        local c = { buttons = safe(function() return dev:call("get_Button") end) or 0, pov = 0xFFFF, axes = {} }
        local l = safe(function() return dev:call("get_AxisL") end)
        local r = safe(function() return dev:call("get_AxisR") end)
        c.axes[1], c.axes[2] = l and l.x or 0, l and l.y or 0
        c.axes[3], c.axes[4] = r and r.x or 0, r and r.y or 0
        c.axes[5] = safe(function() return dev:call("get_AnalogL") end) or 0
        c.axes[6] = safe(function() return dev:call("get_AnalogR") end) or 0
        return c
    end
    -- the chosen device's raw state (buttons / axes / hat)
    function PD.raw(src)
        if src == nil then return nil end
        if src.kind == "ext" then return PD.ext_raw(src.idx) end
        return src.dev and game_raw(src.dev) or nil
    end

    -- every controller ------------------------------------------------------------------
    local PAD_NAMES = { [5] = "DualShock 4", [6] = "DualShock 4", [8] = "DualSense", [9] = "DualSense",
        [10] = "Xbox controller", [11] = "Arcade stick", [12] = "Xbox controller", [13] = "Controller",
        [14] = "Controller", [15] = "Stadia controller", [16] = "Joy-Con", [17] = "Switch Pro controller" }
    PD.all = {}
    function PD.list()
        PD.read_ext()
        local out = {}
        local devs = GP and safe(function() return sdk.call_native_func(nil, GP, "get_ConnectingDevices") end)
        local n = devs and safe(function() return devs:call("get_Count") end) or 0
        local count = {}
        for i = 0, n - 1 do
            local d = safe(function() return devs:call("get_Item", i) end)
            if d and safe(function() return d:call("get_DeviceKind") end) == 1 and safe(function() return d:call("get_Merged") end) ~= true
                and not st.dev_null(d) then
                local det = safe(function() return d:call("get_DeviceKindDetails") end) or 0
                local base = PAD_NAMES[det] or "Controller"
                count[base] = (count[base] or 0) + 1
                local uid = safe(function() return d:call("get_UniqueId") end) or d:get_address()
                out[#out + 1] = { kind = "game", dev = d, uid = uid, addr = d:get_address(), det = det,
                    name = base .. " " .. count[base], key = "game" }
            end
        end
        local seen = {}
        for _, e in ipairs(PD.ext.list) do
            if not e.xinput or PD.show_all then
                local id = e.vid .. ":" .. e.pid
                seen[id] = (seen[id] or 0) + 1
                out[#out + 1] = { kind = "ext", idx = e.idx, uid = "ext:" .. id .. ":" .. seen[id], key = "ext:" .. id,
                    name = e.name .. (seen[id] > 1 and (" " .. seen[id]) or "") }
            end
        end
        PD.all = out
        return out
    end
    function PD.find(uid)
        if uid == nil then return nil end
        for _, e in ipairs(PD.all) do if e.uid == uid then return e end end
        return nil
    end

    -- mapping ----------------------------------------------------------------------------
    function PD.map_for(src)
        if src == nil then return PD.maps_default.game end
        local m = st.pad_maps[src.key]
        if type(m) == "table" then return m end
        return src.kind == "ext" and PD.maps_default.ext or PD.maps_default.game
    end
    -- how far a source is "in": 0..1 (axes measured from their rest position)
    local HAT = { [1] = { 31500, 0, 4500 }, [2] = { 4500, 9000, 13500 }, [3] = { 13500, 18000, 22500 }, [4] = { 22500, 27000, 31500 } }
    local function level(raw, s)
        if s == nil or raw == nil then return 0 end
        if s.t == "b" then return (raw.buttons >> s.i) & 1 end
        if s.t == "a" then
            local v = (raw.axes[s.i] or 0) * s.s
            local r = (s.r or 0) * s.s
            if r < -0.5 then return math.max(0, math.min(1, (v + 1) / 2)) end   -- rests at one end (trigger axis)
            return math.max(0, math.min(1, v))
        end
        if s.t == "h" then
            local p = raw.pov
            if p == nil or p == 0xFFFF or p > 36000 then return 0 end
            local hd = HAT[s.d]
            if s.d == 1 then return (p >= hd[1] or p <= hd[3]) and 1 or 0 end
            return (p >= hd[1] and p <= hd[3]) and 1 or 0
        end
        return 0
    end
    PD.level = level

    -- the virtual pad -----------------------------------------------------------------------
    local V = { b = 0, prev = 0, lx = 0, ly = 0, rx = 0, ry = 0, lt = 0, rt = 0, frame = -1 }
    PD.vpad = V
    local function v2(x, y) return Vector2f.new(x, y) end
    function V:call(m)
        PD.update()
        -- (v419) player 2's wheel (st.p2w): RB held back from the game while the wheel can
        -- open (a quick tap is handed on afterwards, st.p2w.inj), the right stick while it's open
        local W2 = st.p2w
        if W2 and (W2.hide_rb or W2.inj) and (m == "get_Button" or m == "get_ButtonDown" or m == "get_ButtonUp") then
            local b, p = V.b, V.prev
            if W2.hide_rb then b, p = b & ~1024, p & ~1024 end
            local inj = W2.inj
            if inj then
                if st.frame >= inj.on and st.frame < inj.off then b = b | 1024 end
                if st.frame - 1 >= inj.on and st.frame - 1 < inj.off then p = p | 1024 end
                if st.frame > inj.off + 1 then W2.inj = nil end
            end
            if m == "get_Button" then return b end
            if m == "get_ButtonDown" then return b & ~p end
            return p & ~b
        end
        if W2 and W2.open and (m == "get_AxisR" or m == "get_RawAxisR") then return v2(0, 0) end
        if m == "get_Button" then return V.b end
        if m == "get_ButtonDown" then return V.b & ~V.prev end
        if m == "get_ButtonUp" then return V.prev & ~V.b end
        if m == "get_AxisL" or m == "get_RawAxisL" then return v2(V.lx, V.ly) end
        if m == "get_AxisR" or m == "get_RawAxisR" then return v2(V.rx, V.ry) end
        if m == "get_AnalogL" then return V.lt end
        if m == "get_AnalogR" then return V.rt end
        return nil
    end
    function V:get_address() return 0x7E2C0 end
    -- (v419) the pad as it is, for player 2's wheel itself
    function V.raw() PD.update(); return V.b, V.rx, V.ry end
    local function stick(raw, m, pos, neg, ext)
        local v = level(raw, m[pos]) - level(raw, m[neg])
        return v
    end
    function PD.update()
        if V.frame == st.frame then return end
        V.frame = st.frame
        V.prev = V.b
        -- networked co-op: player 2 is the remote player (their input), not a local pad
        if RE2R_MP_NET and RE2R_MP_NET.apply_remote_input and RE2R_MP_NET.apply_remote_input(V) then return end
        local src = st.p2_src
        local raw = PD.raw(src)
        if raw == nil or (PD.capture and PD.capture.src == src) then
            V.b, V.lx, V.ly, V.rx, V.ry, V.lt, V.rt = 0, 0, 0, 0, 0, 0, 0
            return
        end
        local m = PD.map_for(src)
        local bits = 0
        for _, c in ipairs(PD.CTRLS) do
            if c.bit and level(raw, m[c.id]) > 0.5 then bits = bits | c.bit end
        end
        V.lt = level(raw, m.LT)
        V.rt = level(raw, m.RT)
        if V.lt > 0.35 then bits = bits | 512 end
        if V.rt > 0.35 then bits = bits | 2048 end
        V.lx, V.ly = stick(raw, m, "LRIGHT", "LLEFT"), stick(raw, m, "LUP", "LDOWN")
        V.rx, V.ry = stick(raw, m, "RRIGHT", "RLEFT"), stick(raw, m, "RUP", "RDOWN")
        if src.kind == "ext" then
            -- other pads have no dead zone of their own
            for _, k in ipairs({ { "lx", "ly" }, { "rx", "ry" } }) do
                local x, y = V[k[1]], V[k[2]]
                local l = math.sqrt(x * x + y * y)
                if l < 0.18 then V[k[1]], V[k[2]] = 0, 0
                elseif l > 1 then V[k[1]], V[k[2]] = x / l, y / l end
            end
        end
        V.b = bits
    end

    -- mapper: wait for one new input on player 2's controller ---------------------------------
    -- Steady and deliberate only: it first waits for the pad to be at rest and measures how
    -- much each axis wobbles on its own, then needs the same input held for a few frames.
    PD.CTRL.__autoA = { label = "the BOTTOM face button (A / Cross)", pseudo = true, button_only = true }
    PD.CTRL.__autoR = { label = "the RIGHT stick to the right", pseudo = true, stick = true }
    PD.rest = {}   -- controller uid -> axis rest positions seen while nothing was pressed
    function PD.start_capture(id, done)
        local src = st.p2_src
        if PD.raw(src) == nil then return false end
        PD.capture = { id = id, src = src, t0 = os.clock(), done = done, phase = "calm", calm_t = os.clock(),
            lo = {}, hi = {}, cand = nil, cand_n = 0 }
        return true
    end
    local function same(a, b)
        return a and b and a.t == b.t and a.i == b.i and a.s == b.s and a.d == b.d
    end
    function PD.update_capture()
        local C = PD.capture
        if C == nil then return end
        if os.clock() - C.t0 > 10 then PD.capture = nil; if C.done then C.done(nil) end; return end
        local raw = PD.raw(C.src)
        if raw == nil then return end
        local ctrl = PD.CTRL[C.id] or {}
        local rest = PD.rest[C.src.uid]
        local hat_on = raw.pov ~= 0xFFFF and raw.pov <= 36000
        if C.phase == "calm" then
            -- everything let go (buttons, hat, and sticks back where they rest) for a moment
            local calm = raw.buttons == 0 and not hat_on
            if calm and rest then
                for i = 1, 6 do if math.abs((raw.axes[i] or 0) - rest[i]) > 0.35 then calm = false end end
            end
            if not calm then C.calm_t, C.lo, C.hi = os.clock(), {}, {}; return end
            for i = 1, 6 do
                local v = raw.axes[i] or 0
                C.lo[i] = math.min(C.lo[i] or v, v)
                C.hi[i] = math.max(C.hi[i] or v, v)
            end
            if os.clock() - C.calm_t < 0.35 then return end
            C.center, C.noise = {}, {}
            for i = 1, 6 do C.center[i] = (C.lo[i] + C.hi[i]) / 2; C.noise[i] = C.hi[i] - C.lo[i] end
            PD.rest[C.src.uid] = C.center
            C.phase = "listen"
            return
        end
        -- listening: buttons, then the hat, then the axis that moved the most
        local found
        if raw.buttons ~= 0 and not ctrl.stick then
            for i = 0, 31 do if (raw.buttons >> i) & 1 == 1 then found = { t = "b", i = i }; break end end
        end
        if not found and hat_on and not ctrl.stick and not ctrl.button_only then
            local p = raw.pov
            local d = (p >= 31500 or p <= 4500) and 1 or (p <= 13500 and 2) or (p <= 22500 and 3) or 4
            found = { t = "h", d = d }
        end
        if not found and not ctrl.button_only then
            local best, bd = nil, 0
            for i = 1, 6 do
                local d = (raw.axes[i] or 0) - C.center[i]
                local need = math.max(0.6, C.noise[i] * 3 + 0.3)
                if math.abs(d) > need and math.abs(d) > bd then best, bd = i, math.abs(d) end
            end
            if best then
                local d = (raw.axes[best] or 0) - C.center[best]
                local r = C.center[best]
                r = (r > 0.8 and 1) or (r < -0.8 and -1) or 0
                found = { t = "a", i = best, s = d > 0 and 1 or -1, r = r }
            end
        end
        -- the same input for 5 frames in a row
        if found and same(found, C.cand) then C.cand_n = C.cand_n + 1 else C.cand, C.cand_n = found, found and 1 or 0 end
        if C.cand_n < 5 then return end
        found = C.cand
        PD.capture = nil
        if not ctrl.pseudo then
            local key = C.src.key
            if type(st.pad_maps[key]) ~= "table" then
                local m = {}
                for k, v in pairs(PD.map_for(C.src)) do m[k] = v end
                st.pad_maps[key] = m
            end
            st.pad_maps[key][C.id] = found
        end
        if C.done then C.done(found) end
    end

    -- auto-map --------------------------------------------------------------------------------
    -- The game's own pads already have the right layout. Other pads come in a few families
    -- that differ in where the face buttons start; two presses tell them apart: the bottom face
    -- button, and the right stick pushed right (which axis the right stick uses varies too).
    local function family_map(a_index, nbuttons, rs_axis, rs_sign)
        local m = {}
        for k, v in pairs(PD.maps_default.ext) do m[k] = v end
        if a_index == 0 then                -- Xbox style (A B X Y first)
            m.A, m.B, m.X, m.Y, m.LB, m.RB = b(0), b(1), b(2), b(3), b(4), b(5)
            if (nbuttons or 0) >= 12 then
                m.LT, m.RT, m.BACK, m.START, m.L3, m.R3 = b(6), b(7), b(8), b(9), b(10), b(11)
            else                            -- triggers on one shared axis (Z)
                m.BACK, m.START, m.L3, m.R3 = b(6), b(7), b(8), b(9)
                m.LT, m.RT = a(3, 1), a(3, -1)
            end
        elseif a_index == 2 then            -- Triangle Circle Cross Square (many generic pads)
            m.Y, m.B, m.A, m.X = b(0), b(1), b(2), b(3)
        else                                -- Square Cross Circle Triangle (PlayStation style)
            m.X, m.A, m.B, m.Y = b(0), b(1), b(2), b(3)
        end
        if rs_axis then
            -- the right stick's other axis: R goes with Z, R goes with U (Xbox style), V with U
            local other = ({ [3] = 4, [4] = 3, [5] = 4, [6] = 5 })[rs_axis] or 4
            m.RRIGHT, m.RLEFT = a(rs_axis, rs_sign), a(rs_axis, -rs_sign)
            m.RUP, m.RDOWN = a(other, -1), a(other, 1)
            -- a shared trigger axis can't also be the right stick
            if m.LT and m.LT.t == "a" and (m.LT.i == rs_axis or m.LT.i == other) then
                m.LT, m.RT = b(6), b(7)
            end
        end
        return m
    end
    -- well-known pads that need no presses (VID:PID)
    local KNOWN = {
        ["046D:C216"] = { 1, 12, 3, 1 }, ["046D:C218"] = { 1, 12, 3, 1 }, ["046D:C219"] = { 1, 12, 3, 1 },   -- Logitech DirectInput mode
    }
    function PD.automap(done)
        local src = st.p2_src
        if src == nil then return end
        if src.kind == "game" then st.pad_maps[src.key] = nil; if done then done(true) end; return end
        local info
        for _, e in ipairs(PD.ext.list) do if e.idx == src.idx then info = e end end
        local known = info and KNOWN[(info.vid .. ":" .. info.pid):upper()]
        if known then
            st.pad_maps[src.key] = family_map(known[1], known[2], known[3], known[4])
            if done then done(true) end
            return
        end
        PD.start_capture("__autoA", function(fa)
            if fa == nil or fa.t ~= "b" then if done then done(false) end; return end
            PD.start_capture("__autoR", function(fr)
                if fr == nil or fr.t ~= "a" then if done then done(false) end; return end
                st.pad_maps[src.key] = family_map(fa.i, info and info.nbuttons, fr.i, fr.s)
                if done then done(true) end
            end)
        end)
    end
    -- is this control pressed on the virtual pad right now (mapper "test" highlight)
    function PD.active(id)
        local c = PD.CTRL[id]
        if c == nil then return false end
        PD.update()
        if c.bit then return (V.b & c.bit) ~= 0 end
        local v = (c.stick == "LX" and V.lx) or (c.stick == "LY" and V.ly) or (c.stick == "RX" and V.rx) or V.ry
        return v * c.dir > 0.5
    end
    function PD.reset_map(src)
        if src then st.pad_maps[src.key] = nil end
    end
    -- "Button 3", "Axis 2 +", "Hat up", "A" ...
    local GBIT = { [0] = "D-pad up", "D-pad down", "D-pad left", "D-pad right", "Y", "A", "X", "B", "LB", "LT", "RB", "RT", "L3", "R3", "Back", "Start" }
    local GAX = { "Left stick X", "Left stick Y", "Right stick X", "Right stick Y", "LT", "RT" }
    local EAX = { "X axis", "Y axis", "Z axis", "R axis", "U axis", "V axis" }
    local HATN = { "D-pad up", "D-pad right", "D-pad down", "D-pad left" }
    function PD.describe(src, s)
        if s == nil then return "-" end
        local game = src == nil or src.kind == "game"
        if s.t == "b" then return game and (GBIT[s.i] or ("Button " .. s.i)) or ("Button " .. (s.i + 1)) end
        if s.t == "a" then return (game and GAX[s.i] or EAX[s.i] or ("Axis " .. s.i)) .. (s.s > 0 and " +" or " -") end
        if s.t == "h" then return "Hat " .. (HATN[s.d] or "?"):gsub("D%-pad ", "") end
        return "?"
    end
    -- player 2's controller: the chosen one, or (auto) the first one that isn't player 1's
    local function busy(e)
        local r = PD.raw(e)
        if r == nil then return false end
        if r.buttons ~= 0 then return true end
        return math.abs(r.axes[1] or 0) > 0.5 or math.abs(r.axes[2] or 0) > 0.5
    end
    PD.busy = busy
    function PD.choose_p2(p1uid, kbm)
        local p1s = p1uid ~= nil and tostring(p1uid) or nil
        local function ok(e) return e and tostring(e.uid) ~= p1s end
        local pick = (st.p2_pick or "") ~= "" and PD.find_s(st.p2_pick) or nil
        if st.p2_pick == "none" then return nil end
        if ok(pick) then return pick end
        local cur = PD.find_s(st.p2_uid ~= nil and tostring(st.p2_uid) or nil)
        if not ok(cur) then cur = nil end
        if kbm and (cur == nil or not busy(cur)) then
            for _, e in ipairs(PD.all) do if ok(e) and busy(e) then cur = e; break end end
        end
        if cur == nil then for _, e in ipairs(PD.all) do if ok(e) then cur = e; break end end end
        return cur
    end
    function PD.find_s(s)
        if s == nil then return nil end
        for _, e in ipairs(PD.all) do if tostring(e.uid) == s then return e end end
        return nil
    end
    -- the controllers the co-op menu listens to: the game's, plus player 2's other pad
    function st.menu_pads()
        local out = {}
        for _, p in ipairs(st.pads or {}) do out[#out + 1] = p end
        local src = st.p2_src
        if src and src.kind == "ext" then
            out[#out + 1] = { dev = V, uid = src.uid, name = src.name, style = "xbox", vpad = true }
        end
        return out
    end
end)()

local GAMEPAD_TD = sdk.find_type_definition("via.hid.GamePad")
local assign_tried = {}
local function pad_list(is)
    local out, have = {}, {}
    for kind = 1, 4 do
        local u = safe(function() return is:call("getInputUnit", kind) end)
        local d = u and safe(function() return u:call("get_Device") end)
        if d and not st.dev_null(d) and safe(function() return d:call("get_Connecting") end) then
            local uid = safe(function() return d:call("get_UniqueId") end) or d:get_address()
            local det = safe(function() return d:call("get_DeviceKindDetails") end) or 0
            out[#out + 1] = { unit = u, dev = d, uid = uid, addr = d:get_address(),
                name = PAD_NAMES[det] or "Controller", style = PAD_STYLE[det] or "xbox" }
            have[d:get_address()] = true
        end
    end
    -- a connected controller the game hasn't given an input slot (it only auto-assigns some
    -- brands): ask it to, then it shows up above on the next refresh
    local devs = GAMEPAD_TD and safe(function() return sdk.call_native_func(nil, GAMEPAD_TD, "get_ConnectingDevices") end)
    local n = devs and safe(function() return devs:call("get_Count") end) or 0
    for i = 0, n - 1 do
        local d = safe(function() return devs:call("get_Item", i) end)
        if d and not have[d:get_address()] and safe(function() return d:call("get_DeviceKind") end) == 1
            and safe(function() return d:call("get_Merged") end) ~= true then
            local key = d:get_address()
            if st.kbm_on then
                -- keyboard + mouse player 1: the controller goes in a slot that isn't P1's
                local au = safe(function() return is:call("getActiveUserInputUnit") end)
                for kind = 1, 4 do
                    local u = safe(function() return is:call("getInputUnit", kind) end)
                    local ud = u and safe(function() return u:call("get_Device") end)
                    if u and (au == nil or u:get_address() ~= au:get_address())
                        and (ud == nil or st.dev_null(ud)) then
                        safe(function() u:call("changeDevice", d) end)
                        break
                    end
                end
            elseif (assign_tried[key] or 0) < os.clock() then
                assign_tried[key] = os.clock() + 5
                safe(function() is:call("assignInputUnit", d, false) end)
            end
        end
    end
    -- if two controllers report the same id, fall back to the device object itself
    local seen, dup = {}, false
    for _, e in ipairs(out) do if seen[e.uid] then dup = true end; seen[e.uid] = true end
    if dup then for _, e in ipairs(out) do e.uid = e.addr end end
    return out
end

local function find_pad(list, uid)
    if uid == nil then return nil end
    for _, e in ipairs(list) do if e.uid == uid then return e end end
    return nil
end

-- Keep "which physical controller is whose" fixed. Runs every few frames:
--  * (re)identify the pads if one is missing: P1 = the game's active pad, P2 = the other
--  * route HUNK to whichever InputUnit currently holds P2's controller
--  * if the game made P2's controller the active one, hand it back to P1's controller
local function refresh_unit()
    local is = sdk.get_managed_singleton("app.ropeway.InputSystem")
    if is == nil then return end
    -- keyboard + mouse player 1 only splits the controllers off when a person plays player 2;
    -- with the AI partner nobody uses player 2's pad, so player 1 keeps keyboard AND pad
    local kbm = st.p1_kbm and not st.ai_partner()
    if st.kbm_on and not kbm then
        -- give player 1's slot a controller back (the one player 2 had)
        st.kbm_on = false
        local p2pad = st.p2_src and st.p2_src.kind == "game" and st.p2_src.dev or nil
        st.p1_uid, st.p2_uid, st.pad2dev_addr, st.unit2, st.p2_dev = nil, nil, nil, nil, nil
        local au = safe(function() return is:call("getActiveUserInputUnit") end)
        local null = GAMEPAD_TD and safe(function() return sdk.call_native_func(nil, GAMEPAD_TD, "get_NullDevice") end)
        if au and p2pad then
            for kind = 1, 4 do   -- take it out of its own slot first
                local u = safe(function() return is:call("getInputUnit", kind) end)
                local ud = u and safe(function() return u:call("get_Device") end)
                if u and ud and ud:get_address() == p2pad:get_address() and u:get_address() ~= au:get_address() and null then
                    safe(function() u:call("changeDevice", null) end)
                end
            end
            safe(function() au:call("changeDevice", p2pad) end)
            safe(function() is:call("changeActiveUserDevice", p2pad) end)
        else
            safe(function() is:call("updateAutoAssignInputUnit") end)
        end
    end
    st.kbm_on = kbm
    if st.kbm_on then
        -- player 1's input slot keeps the keyboard and mouse but no controller
        local au = safe(function() return is:call("getActiveUserInputUnit") end)
        local aud = au and safe(function() return au:call("get_Device") end)
        if aud and not st.dev_null(aud) then
            local null = GAMEPAD_TD and safe(function() return sdk.call_native_func(nil, GAMEPAD_TD, "get_NullDevice") end)
            if null then safe(function() au:call("changeDevice", null) end) end
        end
    end
    local pads = pad_list(is)
    st.pads = pads
    st.pad.list()
    if st.kbm_on then
        -- player 2: the chosen controller, or (automatic) whichever one is being used
        st.p1_uid, st.p1_dev = "kbm", nil
        st.set_p2(is, pads, st.pad.choose_p2(nil, true))
        return
    end
    if st.p1_uid == "kbm" then st.p1_uid = nil end
    -- player 1's slot left without a controller (keyboard mode was switched off): put one back
    do
        local au = safe(function() return is:call("getActiveUserInputUnit") end)
        local aud = au and safe(function() return au:call("get_Device") end)
        local empty = aud == nil or st.dev_null(aud)
        if au and empty and #pads > 0 then
            local pick = find_pad(pads, st.p1_uid)
            if pick == nil then for _, e in ipairs(pads) do if e.uid ~= st.p2_uid then pick = e; break end end end
            if pick == nil and (st.ai_partner() or #pads == 1) then pick = pads[1] end
            if pick then
                local null = GAMEPAD_TD and safe(function() return sdk.call_native_func(nil, GAMEPAD_TD, "get_NullDevice") end)
                if null and pick.unit and pick.unit:get_address() ~= au:get_address() then
                    safe(function() pick.unit:call("changeDevice", null) end)
                end
                if st.pad2dev_addr == pick.addr then st.pad2dev_addr = nil end
                safe(function() au:call("changeDevice", pick.dev) end)
                safe(function() is:call("changeActiveUserDevice", pick.dev) end)
                st.p1_uid = pick.uid
                if st.p2_uid == pick.uid then st.p2_uid = nil end
                pads = pad_list(is)
                st.pads = pads
            end
        end
    end
    local active = safe(function() return is:call("get_ActiveUserDevice") end)
    local active_addr = active and active:get_address() or nil
    -- player 1's chosen controller
    if (st.p1_pick or "") ~= "" and st.p1_pick ~= "kbm" then
        for _, e in ipairs(pads) do
            if tostring(e.uid) == st.p1_pick and st.p1_uid ~= e.uid then
                st.p1_uid = e.uid
                if active_addr ~= e.addr then
                    safe(function() is:call("changeActiveUserDevice", e.dev) end)
                    active = safe(function() return is:call("get_ActiveUserDevice") end)
                    active_addr = active and active:get_address() or nil
                end
            end
        end
    end
    local p1, p2 = find_pad(pads, st.p1_uid), find_pad(pads, st.p2_uid)
    if p2 == nil or (p1 == nil and #pads >= 2) then
        -- first run or a controller (re)connected: P1 keeps the active pad when we can tell
        p1, p2 = nil, nil
        for _, e in ipairs(pads) do if e.addr == active_addr then p1 = e end end
        if p1 == nil then p1 = find_pad(pads, st.p1_uid) end
        for _, e in ipairs(pads) do if e ~= p1 and p2 == nil then p2 = e end end
        st.p1_uid = p1 and p1.uid or nil
        st.p2_uid = p2 and p2.uid or nil
    end
    st.pad2dev_addr = p2 and p2.addr or nil
    st.p1_dev = p1 and p1.dev or nil
    if st.pin_p1_pad and p1 and p2 and not st.ai_partner() then
        local au = safe(function() return is:call("getActiveUserInputUnit") end)
        local aud = au and safe(function() return au:call("get_Device") end)
        if active_addr == p2.addr or (aud and aud:get_address() == p2.addr) then
            safe(function() is:call("changeActiveUserDevice", p1.dev) end)
            local now_active = safe(function() return is:call("get_ActiveUserDevice") end)
            if now_active == nil or now_active:get_address() ~= p1.addr then
                safe(function() is:call("set_ActiveUserDevice", p1.dev) end)
            end
            st.swaps_fixed = st.swaps_fixed + 1
            say("The game swapped the controllers; Leon's controller was given back")
            -- the game re-binds its input slots when the active pad changes: look again
            p2 = find_pad(pad_list(is), st.p2_uid)
        end
    end
    st.set_p2(is, pads, st.pad.choose_p2(st.p1_uid, false))
    if RE2R_MP_NET and RE2R_MP_NET.ensure_p2 then RE2R_MP_NET.ensure_p2(is, pads) end
end

-- player 2 plays through the virtual pad; st.unit2 is only used for the game's button
-- layout (which button each action is on) and which stick each action reads
st.set_p2 = function(is, pads, src)
    st.p2_src = src
    st.p2_uid = src and src.uid or nil
    st.p2_dev = src and st.pad.vpad or nil
    st.pad2dev_addr = (src and src.kind == "game") and src.addr or nil
    local unit = nil
    if src and src.kind == "game" then
        for _, e in ipairs(pads) do if e.addr == src.addr then unit = e.unit end end
    end
    if unit == nil and src then
        unit = safe(function() return is:call("getActiveUserInputUnit") end)
            or safe(function() return is:call("getInputUnit", 1) end)
    end
    -- a different slot or controller: forget the per-action lookups made on the old one
    local key = tostring(unit and unit:get_address()) .. "|" .. tostring(st.p2_uid)
    if key ~= st.unit2_key then
        st.unit2_key = key
        st.kind_btn = {}
        st.unit2_epoch = (st.unit2_epoch or 0) + 1
    end
    st.unit2 = unit
end

-- switch player 1 between controller and keyboard + mouse
st.set_p1_kbm = function(on)
    st.p1_kbm = on
    local is = sdk.get_managed_singleton("app.ropeway.InputSystem")
    if not on then
        st.p1_uid, st.p2_uid = nil, nil   -- let the game hand out its slots again, then re-identify
        if is then safe(function() is:call("updateAutoAssignInputUnit") end) end
    end
    refresh_unit()
end

local function swap_controllers()
    -- only two of the game's own controllers can trade places (player 1 needs one the game reads)
    if st.kbm_on or (st.p2_src and st.p2_src.kind ~= "game") then return end
    st.p1_uid, st.p2_uid = st.p2_uid, st.p1_uid
    if (st.p1_pick or "") ~= "" or (st.p2_pick or "") ~= "" then
        st.p1_pick = st.p1_uid and tostring(st.p1_uid) or ""
        st.p2_pick = st.p2_uid and tostring(st.p2_uid) or ""
    end
    refresh_unit()
end

-- choosing each player's controller (co-op menu and REFramework menu)
st.pick_p1 = function(new)   -- "kbm" or a controller id
    st.p1_pick = new
    if new == "kbm" then st.set_p1_kbm(true); return end
    if tostring(st.p2_uid) == new then st.p2_pick = "" end
    local e = st.pad.find_s(new)
    st.p1_uid = e and e.uid or nil
    local is = sdk.get_managed_singleton("app.ropeway.InputSystem")
    if e and is then safe(function() is:call("changeActiveUserDevice", e.dev) end) end
    st.p1_kbm = false
    st.set_p1_kbm(false)
    st.p1_uid = e and e.uid or st.p1_uid
    pcall(refresh_unit)
end
st.pick_p2 = function(new)   -- a controller id, "none", or "" (automatic)
    st.p2_pick = new
    pcall(refresh_unit)
end
-- the choices, in list order: { id, label }
st.p1_choices = function()
    local out = { { "kbm", "Keyboard & mouse" } }
    for _, e in ipairs(st.pad.all or {}) do if e.kind == "game" then out[#out + 1] = { tostring(e.uid), e.name } end end
    return out
end
st.p2_choices = function()
    local p1 = st.p1_kbm and "kbm" or tostring(st.p1_uid)
    local out = {}
    for _, e in ipairs(st.pad.all or {}) do if tostring(e.uid) ~= p1 then out[#out + 1] = { tostring(e.uid), e.name } end end
    out[#out + 1] = { "none", "None" }
    return out
end

-- Player 2's camera for split screen (see "Split screen" further down)
local p2c = { active = false, yaw = 0, pitch = -0.1, zoom = 0, sticks = {}, stick_frame = {},
    own_yaw = true }   -- the game sees player 2's camera yaw for HUNK (camera hooks), so his stick isn't pre-turned
-- Is the AI partner playing player 2? The AI only drives HUNK when split screen is off (it
-- stands down while player 2's own view is up), so with split screen on, player 2 is a person
-- even if the AI partner setting is on: their controller keeps Start (player 2 menu), Back
-- (swap) and the pad-2 combos, and stays player 2's. (Before, a saved "AI partner: On" left
-- player 2's Start and Back dead in split screen.)
function st.ai_partner() return st.ai == true and not st.split end
-- AI-controlled player 2 (see "AI partner" further down)
local ai = { active = false, keys = {}, prev = {}, stick = nil, aim_pos = nil,
    -- player 1's orders (command wheel): move = follow / hold / goto / guard / regroup,
    -- fire = free / sync (shoot when player 1 shoots) / hold
    order = { move = "follow", fire = "free" },
    wheel = { open = false, block_rb = false, rstick_kinds = { [2] = true } } }
-- in-game co-op menu (see "Co-op menu" further down); while it is open the game gets no pad input
local menu = { open = false }

-- In split screen, player 2's left stick moves HUNK relative to player 2's camera: the
-- game turns it by Leon's camera yaw, so it is pre-turned by the difference.
-- Our own stick objects (player 2's sticks, Tank Controls, the AI) are handed to the game in
-- place of its own. Made with create_instance they can be freed under us: after player 2's
-- controller was unplugged and plugged back in, player 2's left stick object was gone ("not a
-- managed object") and HUNK ignored the stick while buttons still worked. They are now made
-- with a permanent reference and checked once a frame before use; a dead one is replaced
-- (counted in st.stick_rebuilds).
st.STICK_T = "app.ropeway.InputSystem.AnalogStick"
function st.new_stick()
    local s = sdk.create_instance(st.STICK_T)
    if s == nil then return nil end
    pcall(s.call, s, ".ctor")
    if s.add_ref_permanent then pcall(s.add_ref_permanent, s) else pcall(s.add_ref, s) end
    return s
end
function st.stick_ok(s)
    if s == nil then return false end
    local ok, good = pcall(function()
        local a = s:get_address()
        if a == nil or a == 0 or not sdk.is_managed_object(a) then return false end
        local td = s:get_type_definition()
        return td ~= nil and td:get_full_name() == st.STICK_T
    end)
    return ok and good == true
end
-- a live stick for this slot (tbl[key]): the old one if it's still good, else a new one
function st.live_stick(tbl, key)
    local s = tbl[key]
    if s ~= nil and st.stick_ok(s) then return s end
    if s ~= nil then
        st.stick_rebuilds = (st.stick_rebuilds or 0) + 1
        log.info("[reunited] a stick object was freed; made a new one (" .. tostring(key) .. ")")
    end
    s = st.new_stick()
    tbl[key] = s
    return s
end

local function p2_move_stick(u, kind)
    local src = p2c.kbm_pad_stick(u, kind)
    if src == nil then return nil end
    local own = p2c.sticks[kind]
    if own == nil or p2c.stick_frame[kind] ~= st.frame then own = st.live_stick(p2c.sticks, kind) end
    if own == nil then return nil end
    if p2c.stick_frame[kind] ~= st.frame then
        p2c.stick_frame[kind] = st.frame
        local a, r = src:call("get_Axis"), src:call("get_RawAxis")
        local d = p2c.delta or 0
        local c, sn = math.cos(d), math.sin(d)
        own:call("update", Vector2f.new(a.x * c - a.y * sn, a.x * sn + a.y * c), Vector2f.new(r.x * c - r.y * sn, r.x * sn + r.y * c))
    end
    return own
end

-- player 2's sticks straight from the controller (keyboard + mouse player 1, see route)
p2c.kbm_sticks, p2c.kbm_frame, p2c.kbm_which = {}, {}, {}
function p2c.kbm_pad_stick(u, kind)
    if p2c.which_epoch ~= st.unit2_epoch then p2c.kbm_which, p2c.which_epoch = {}, st.unit2_epoch end
    local which = p2c.kbm_which[kind]
    if which == nil then
        -- the slot's StickDictionary says which stick a Kind reads (1 left, 2 right)
        local sd = safe(function() return u:get_field("<StickDictionary>k__BackingField") end)
        local v = sd and safe(function() return sd:call("ContainsKey", kind) and sd:call("get_Item", kind) end)
        which = (v == 1 and "L") or (v == 2 and "R") or false
        if sd ~= nil then p2c.kbm_which[kind] = which end   -- (not remembered when the slot couldn't be read)
    end
    if not which then return nil end
    local own = p2c.kbm_sticks[which]
    if own == nil or p2c.kbm_frame[which] ~= st.frame then own = st.live_stick(p2c.kbm_sticks, which) end
    if own == nil then return nil end
    if p2c.kbm_frame[which] ~= st.frame then
        p2c.kbm_frame[which] = st.frame
        local a = safe(function() return st.p2_dev:call("get_Axis" .. which) end)
        local raw = safe(function() return st.p2_dev:call("get_RawAxis" .. which) end)
        if a and raw then own:call("update", a, raw) end
    end
    return own
end

local zero_stick = nil
-- the stick handed to the game when input is blocked (menu, L3 + R3 hold, player 2 without a
-- pad): the InputSystem's own DummyStick. A stick made with create_instance went bad after a
-- second or so of being returned (v214: the camera read magnitudes like -8.9 / 3915267 from
-- it and spun to random angles, slamming the pitch to its limit: the L3 + R3 camera jerk).
st.zero_stick = function()
    if st._zs_frame ~= st.frame then
        st._zs_frame = st.frame
        local is = sdk.get_managed_singleton("app.ropeway.InputSystem")
        local d = is and safe(function() return is:get_field("DummyStick") end)
        st._zs = (d ~= nil and sdk.is_managed_object(d)) and d or nil
        -- keep it at rest: if anything left a value in it, clear it (counted in st.zs_fixes)
        local z = st._zs or zero_stick
        if z then
            local m = safe(function() return z:get_field("<Magnitude>k__BackingField") end)
            if m ~= nil and m ~= 0 then
                st.zs_fixes = (st.zs_fixes or 0) + 1
                safe(function() z:call("update(via.vec2, via.vec2)", Vector2f.new(0, 0), Vector2f.new(0, 0)) end)
            end
        end
    end
    if st._zs then return st._zs end
    if not st.stick_ok(zero_stick) then zero_stick = st.new_stick() end
    return zero_stick
end
-- AI: the buttons and stick the AI is "pressing" this frame
local function ai_route(short, kind)
    if st.force_on[kind] and short ~= "getStick" and short ~= "isUp" then return sdk.to_ptr(1) end
    if short == "getStick" then
        if kind ~= 2 and ai.stick then return sdk.to_ptr(ai.stick) end
        return sdk.to_ptr(st.zero_stick())
    end
    local on, was = ai.keys[kind] == true, ai.prev[kind] == true
    if short == "isOn" then return sdk.to_ptr(on and 1 or 0) end
    if short == "isDown" then return sdk.to_ptr((on and not was) and 1 or 0) end
    return sdk.to_ptr((was and not on) and 1 or 0)   -- isUp
end

local function route(short, kind)
    if (st.cut_hide and st.cut_hide.on) or st.p2_down then   -- hidden for a cutscene / downed: player 2 stands still
        if short == "getStick" then return sdk.to_ptr(st.zero_stick()) end
        return sdk.to_ptr(0)
    end
    if ai.active then return ai_route(short, kind) end
    if menu.p2_lock then   -- player 2's menu is open: HUNK stands still, player 2's buttons are the menu's
        if short == "getStick" then
            return sdk.to_ptr(st.zero_stick())
        end
        return sdk.to_ptr(0)
    end
    local T = st.tank
    if T and T.on then
        -- Fixed Camera mod controls: the movement stick and MOVE come from st.tank
        if T.override then
            if short == "getStick" and kind ~= 2 then return sdk.to_ptr(T.stick) end
            if kind == 1 then   -- MOVE
                local on, was = T.move_on, T.move_was
                if short == "isOn" then return sdk.to_ptr(on and 1 or 0) end
                if short == "isDown" then return sdk.to_ptr((on and not was) and 1 or 0) end
                return sdk.to_ptr((was and not on) and 1 or 0)
            end
        end
        -- running: the game's quick turn is off (Classic Cameras' running quick turn instead)
        if T.no_qt and (kind == 32 or kind == 2048) and short ~= "getStick" then return sdk.to_ptr(0) end
        -- no running backwards (the Fixed Camera mod's tank run)
        if T.block_jog and (kind == 8 or kind == 16) and short ~= "getStick" then return sdk.to_ptr(0) end
        -- the d-pad walks: weapon shortcuts only with the shortcut button (R3) held
        if T.dpad_block and (kind == 17179869184 or kind == 34359738368 or kind == 68719476736 or kind == 137438953472) then
            return sdk.to_ptr(0)
        end
    end
    -- HUNK Classic: d-pad down swaps the sub-weapon (update_combos), it isn't the game's
    -- d-pad-down weapon shortcut
    if kind == 34359738368 and short ~= "getStick" and st.classic_controls and st.classic_controls() then return sdk.to_ptr(0) end
    local u = st.unit2
    if u == nil or st.p2_dev == nil then
        -- no second pad: HUNK gets no input rather than mirroring P1
        if st.force_on[kind] and short ~= "getStick" and short ~= "isUp" then return sdk.to_ptr(1) end
        if short == "getStick" then
            return sdk.to_ptr(st.zero_stick())
        end
        return sdk.to_ptr(0)
    end
    -- player 2 is always read from the virtual pad (st.pad.vpad): whatever controller it
    -- is, and whether or not the game gave it an input slot
    if short == "getStick" then
        local own
        if p2c.active and kind ~= 2 and not p2c.own_yaw then   -- 2 = WATCH (right stick): drives the camera
            own = p2_move_stick(u, kind)
        else
            own = p2c.kbm_pad_stick(u, kind)
        end
        if own then return sdk.to_ptr(own) end
        return sdk.to_ptr(st.zero_stick())
    end
    if st.force_on[kind] and short ~= "isUp" then return sdk.to_ptr(1) end
    if st.reserved_buttons ~= 0 then
        local btn = st.kind_btn[kind]
        if btn == nil then
            btn = safe(function() return u:call("getGamePadButton", kind) end) or 0
            st.kind_btn[kind] = btn
        end
        if (btn & st.reserved_buttons) ~= 0 then return sdk.to_ptr(0) end
    end
    do
        -- the game's button for this action, pressed on the virtual pad
        local mask = st.kind_btn[kind]
        if mask == nil then
            mask = safe(function() return u:call("getGamePadButton", kind) end) or 0
            st.kind_btn[kind] = mask
        end
        if mask ~= 0 then
            local f = short == "isOn" and "get_Button" or (short == "isDown" and "get_ButtonDown" or "get_ButtonUp")
            local b = safe(function() return st.p2_dev:call(f) end) or 0
            return sdk.to_ptr((b & mask) ~= 0 and 1 or 0)
        end
        -- no button behind it (a stick-driven kind such as MOVE): use the controller's stick
        local own = p2c.kbm_pad_stick(u, kind)
        if own == nil then return sdk.to_ptr(0) end
        local ks = st.kstate[kind]
        if ks == nil then ks = { frame = -1, on = false, prev = false }; st.kstate[kind] = ks end
        if ks.frame ~= st.frame then
            local m = safe(function() return own:call("get_Magnitude") end) or 0
            ks.frame, ks.prev, ks.on = st.frame, ks.on, m > 0.2
        end
        if short == "isOn" then return sdk.to_ptr(ks.on and 1 or 0) end
        if short == "isDown" then return sdk.to_ptr((ks.on and not ks.prev) and 1 or 0) end
        return sdk.to_ptr((ks.prev and not ks.on) and 1 or 0)
    end
end

for _, sig in ipairs({ "isOn(app.ropeway.InputDefine.Kind)", "isDown(app.ropeway.InputDefine.Kind)",
                       "isUp(app.ropeway.InputDefine.Kind)", "getStick(app.ropeway.InputDefine.Kind)" }) do
    local short = sig:match("^(%w+)")
    sdk.hook(IS:get_method(sig), function(args)
        local block = menu.open or menu.blocking   -- the co-op menu has the controllers: the game sees nothing pressed
        -- player 1's item box screen (split screen) has player 1's controller: Leon gets nothing
        if not block and st.p1_block and not is_hunk_owner(current_owner()) then block = true end
        if not block and (menu.pending_p1 or menu.pending_p2) then   -- L3 + R3 held towards the menu
            local h = is_hunk_owner(current_owner())
            block = (h and menu.pending_p2) or (not h and menu.pending_p1)
        end
        if block then
            local ret = sdk.to_ptr(0)
            if short == "getStick" then
                ret = sdk.to_ptr(st.zero_stick())
            end
            thread.get_hook_storage().ret = ret
            return sdk.PreHookResult.SKIP_ORIGINAL
        end
        if not st.enabled_route or st.hunk == nil then return end
        local owner = current_owner()
        if not is_hunk_owner(owner) then
            -- player 1 downed: her moving / aiming / using do nothing (menus still work)
            if st.p1_down and st.p1_down_block(sdk.to_int64(args[2])) then
                thread.get_hook_storage().ret = short == "getStick" and sdk.to_ptr(st.zero_stick()) or sdk.to_ptr(0)
                return sdk.PreHookResult.SKIP_ORIGINAL
            end
            -- player 2 downed and player 1 at his side: her action button helps him up
            if short ~= "getStick" and st.p2_down and sdk.to_int64(args[2]) == 8192 and st.p2_down_action() then
                thread.get_hook_storage().rv = true
                return
            end
            -- player 2 held by an enemy (and player 1 isn't): the counter-attack check (DEFENSE,
            -- LB) runs outside HUNK's own components, so it reads player 2's controller then
            if st.p2_held_only and short ~= "getStick" and sdk.to_int64(args[2]) == 4096 then
                local ok, ret = pcall(route, short, 4096)
                if ok and ret ~= nil then
                    thread.get_hook_storage().ret = ret
                    return sdk.PreHookResult.SKIP_ORIGINAL
                end
            end
            -- AI partner on: player 1's RB opens the command wheel (walk / change-bullet
            -- stay with the game while aiming), and the camera holds still while choosing
            if ai.active and owner ~= nil and (ai.wheel.block_rb or ai.wheel.open) then
                local kind = sdk.to_int64(args[2])
                local ret
                if short == "getStick" then
                    if ai.wheel.open and ai.wheel.rstick_kinds[kind] then
                        ret = sdk.to_ptr(st.zero_stick())
                    end
                elseif kind == 262144 and ai.wheel.tap_frame == st.frame then
                    -- a quick RB tap while aiming still changes ammo type
                    ret = sdk.to_ptr(short == "isUp" and 0 or 1)
                elseif kind == 4 or kind == 32768 or kind == 262144 then   -- WALK, GIMMICK_EX, CHANGE_BULLET (RB)
                    ret = sdk.to_ptr(0)
                elseif ai.wheel.open and (kind == 17179869184 or kind == 34359738368 or kind == 68719476736 or kind == 137438953472) then
                    ret = sdk.to_ptr(0)   -- SHORTCUT_* (d-pad / number keys) choose orders instead of weapons
                elseif ai.wheel.open and (kind == 8192 or kind == 4194304) then
                    ret = sdk.to_ptr(0)   -- ACTION / DECIDE: A opens the AI's inventory from the wheel
                end
                if ret then
                    thread.get_hook_storage().ret = ret
                    return sdk.PreHookResult.SKIP_ORIGINAL
                end
            end
            return
        end
        local ok, ret = pcall(route, short, sdk.to_int64(args[2]))
        if not ok or ret == nil then return end
        thread.get_hook_storage().ret = ret
        return sdk.PreHookResult.SKIP_ORIGINAL
    end, function(r)
        local hs = thread.get_hook_storage()
        if hs.ret ~= nil then
            local x = hs.ret
            hs.ret = nil
            return x
        end
        if hs.rv then
            hs.rv = nil
            if short ~= "isUp" and (sdk.to_int64(r) & 0xFF) ~= 0 and st.p2_down then st.p2_down.press = st.frame end
            return sdk.to_ptr(0)
        end
        return r
    end)
end

-- Command wheel open: the camera reads player 1's right stick straight from the input
-- slot, so hold that still too (the stick is choosing an order, not turning the view).
do
    local ut = sdk.find_type_definition("app.ropeway.InputUnit")
    for _, m in ipairs(ut and ut:get_methods() or {}) do
        local pt = m:get_name() == "getStick" and m:get_num_params() == 1 and m:get_param_types()[1]
        if pt and pt:get_full_name() == "app.ropeway.InputDefine.AnalogStick.Kind" then
            sdk.hook(m, function(args)
                if not ai.wheel.open and not st.p1_block then return end
                if sdk.to_int64(args[3]) ~= 2 then return end   -- 2 = right stick
                local is = sdk.get_managed_singleton("app.ropeway.InputSystem")
                local au = is and safe(function() return is:call("getActiveUserInputUnit") end)
                if au == nil or sdk.to_int64(args[2]) ~= au:get_address() then return end
                thread.get_hook_storage().ret = sdk.to_ptr(st.zero_stick())
                return sdk.PreHookResult.SKIP_ORIGINAL
            end, function(r)
                local hs = thread.get_hook_storage()
                if hs.ret ~= nil then local x = hs.ret; hs.ret = nil; return x end
                return r
            end)
        end
    end
end

-- Keep the second pad from becoming P1's "active user" device.
sdk.hook(IS:get_method("changeActiveUserDevice"), function(args)
    if st.kbm_on then return sdk.PreHookResult.SKIP_ORIGINAL end   -- P1 has no controller
    if st.ai_partner() then return end   -- AI partner: nobody plays player 2, any pad may drive player 1
    if not st.pin_p1_pad or st.pad2dev_addr == nil then return end
    if sdk.to_int64(args[3]) == st.pad2dev_addr then
        return sdk.PreHookResult.SKIP_ORIGINAL
    end
end, function(r) return r end)


-- with player 1 on keyboard + mouse the mod places the controllers itself
sdk.hook(IS:get_method("updateAutoAssignInputUnit"), function()
    if st.kbm_on then return sdk.PreHookResult.SKIP_ORIGINAL end
end, function(r) return r end)

-- HUNK aim (sub-weapon stick aim / facing P1's crosshair) ------------------------

local function vaim_dir()
    local cp, sp = math.cos(st.vaim.pitch), math.sin(st.vaim.pitch)
    -- camera looks down -Z: dir = Ry(yaw) * Rx(pitch) * (0,0,-1)
    return -cp * math.sin(st.vaim.yaw), sp, -cp * math.cos(st.vaim.yaw)
end


-- Aim direction for HUNK: written into his PlayerActionOrderer after it updates
-- (WatchDir / CharDir). This alone turns him; an earlier virtual
-- camera (CameraStatus clone + getter rewrites) was removed as a crash risk.

-- Vertical aim: HUNK's aim direction lives in PlayerActionOrderer.WatchDir/CharDir
-- (3D vectors). After his orderer updates, write the virtual aim vector in.
do
    local m = sdk.find_type_definition("app.ropeway.survivor.player.PlayerActionOrderer"):get_method("doSurvivorActionOrdererUpdate")
    sdk.hook(m, function(args)
        thread.get_hook_storage().this = args[2]
    end, function(r)
        if st.vaim.active and st.hunk then
            local this = thread.get_hook_storage().this
            if this and st.owners[sdk.to_int64(this)] == OWN_HUNK then
                local x, y, z = vaim_dir()
                local o = sdk.to_managed_object(this)
                local v = Vector3f.new(x, y, z)
                pcall(function()
                    o:set_field("<WatchDir>k__BackingField", v)
                    o:set_field("<CharDir>k__BackingField", v)
                end)
            end
        elseif st.tank and st.tank.dir and st.hunk then
            -- Fixed Camera mod controls: HUNK faces his own heading, not Leon's camera
            local this = thread.get_hook_storage().this
            if this and st.owners[sdk.to_int64(this)] == OWN_HUNK then
                local d = st.tank.dir
                local o = sdk.to_managed_object(this)
                local v = Vector3f.new(d[1], 0, d[2])
                pcall(function()
                    o:set_field("<WatchDir>k__BackingField", v)
                    o:set_field("<CharDir>k__BackingField", v)
                end)
            end
        end
        return r
    end)
    -- Split screen: the orderer's own update / lateUpdate refill WatchDir / CharDir from the
    -- main camera (Leon's) after the hook above, natively. For HUNK they're rewritten at the end
    -- of both: his aim while he aims, otherwise where player 2's camera looks (the game does
    -- the same for Leon with his camera). Without this HUNK snaps to Leon's crosshair.
    local sao = sdk.find_type_definition("app.ropeway.survivor.SurvivorActionOrderer")
    for _, nm in ipairs({ "update", "lateUpdate" }) do
        sdk.hook(sao:get_method(nm), function(args)
            thread.get_hook_storage().so = args[2]
        end, function(r)
            local fa = st.tank and st.tank.fa_aim and st.vaim.active
            if ((p2c.active and p2c.fwd) or fa) and st.hunk then
                local this = thread.get_hook_storage().so
                if this and st.owners[sdk.to_int64(this)] == OWN_HUNK then
                    local v
                    if st.vaim.active then local x, y, z = vaim_dir(); v = Vector3f.new(x, y, z)
                    else local f = p2c.fwd; v = Vector3f.new(f[1], f[2], f[3]) end
                    local o = sdk.to_managed_object(this)
                    pcall(function()
                        o:set_field("<WatchDir>k__BackingField", v)
                        o:set_field("<CharDir>k__BackingField", v)
                    end)
                    -- aiming: the body-turn controller's target too (after a sprint it can be left
                    -- on the run direction, leaving him stuck facing away from the crosshair)
                    if st.vaim.active and nm == "update" then pcall(st.split_turn, math.atan(v.x, v.z)) end
                end
            end
            return r
        end)
    end
end

-- Split screen: HUNK's upper-body look-at (PlayerLookAt's Main work, which is what aims a
-- player's gun at the crosshair point) gets the point under player 2's crosshair. Left alone
-- it is fed player 1's crosshair point: once that point is in front of HUNK his upper body
-- twists toward it (gun off to one side of player 2's crosshair) and stays twisted until he
-- lowers the gun. Normal co-op (one camera) is left as the game has it.
do
    local td = sdk.find_type_definition("app.ropeway.survivor.player.PlayerLookAt")
    local m = td and td:get_method("onMainUpdateLookAtPosition")
    if m then
        sdk.hook(m, function(args)
            local s = thread.get_hook_storage()
            s.law = nil
            if (p2c.active or (st.tank and st.tank.fa_aim)) and st.hunk and st.target_point then
                local la = comp(st.hunk, "app.ropeway.survivor.player.PlayerLookAt")
                if la and la:get_address() == sdk.to_int64(args[2]) then s.law = sdk.to_managed_object(args[3]) end
            end
        end, function(r)
            local w = thread.get_hook_storage().law
            if w and (p2c.active or (st.tank and st.tank.fa_aim)) and st.hunk then
                pcall(function()
                    local t = st.target_point()
                    local hp = st.hunk:call("get_Transform"):call("get_Position")
                    local dx, dy, dz = t[1] - hp.x, t[2] - (hp.y + 1.45), t[3] - hp.z
                    local p
                    if math.sqrt(dx * dx + dz * dz) + math.abs(dy) < 1.5 then
                        -- crosshair right at his chest (on Leon up close): straight along the aim
                        local f = p2c.fwd
                        if st.vaim.active then local x, y, z = vaim_dir(); f = { x, y, z } end
                        if f == nil then local T = st.tank; f = { math.sin(T.aim_yaw or 0), 0, math.cos(T.aim_yaw or 0) } end
                        p = Vector3f.new(hp.x + f[1] * 10, hp.y + 1.45 + f[2] * 10, hp.z + f[3] * 10)
                    else
                        p = Vector3f.new(t[1], t[2], t[3])
                    end
                    w:get_field("LookAtPosition"):call("setTargetPosition", p)
                end)
            end
            return r
        end)
    end
    -- how much of that look-at is applied right now (0..1)
    function st.la_rate()
        local la = st.hunk and comp(st.hunk, "app.ropeway.survivor.player.PlayerLookAt")
        local w = la and safe(function() return la:get_field("Main") end)
        return w and safe(function() return w:call("get_WorkBlendRate") end) or 0
    end
end

-- Split screen: player 2's flashlight. Every player's FlashLight (app.ropeway.FlashLight)
-- aims at a point taken from the main camera, so HUNK's beam pointed wherever player 1 was
-- looking: with player 1 in another part of the room it lit nothing in player 2's half, his
-- view's auto exposure opened up on the dark and the room turned a washed-out blue (it came
-- back as soon as player 1 walked over and her own light was in his view). After the game
-- places HUNK's flashlight (applyTransform), its lights are turned onto player 2's crosshair
-- point, and they take player 1's flashlight settings (the game sets those per area: this
-- room's beam is dim and yellow, HUNK's own defaults are 8x brighter). Off in normal co-op.
do
    local FL = { at = -1000 }
    local function flashlights()
        if st.frame - FL.at < 120 and FL.h and safe(function() return FL.h:call("get_GameObject"):call("get_Valid") end) == true then return FL.h, FL.p end
        FL.at, FL.h, FL.p = st.frame, nil, nil
        local scene = sdk.call_native_func(sdk.get_native_singleton("via.SceneManager"), sdk.find_type_definition("via.SceneManager"), "get_CurrentScene")
        local arr = scene and scene:call("findComponents(System.Type)", sdk.typeof("app.ropeway.FlashLight"))
        local p1 = p1_go()
        for i = 0, (arr and arr:call("get_Length") or 0) - 1 do
            pcall(function()
                local c = arr:call("GetValue", i)
                local par = c:call("get_GameObject"):call("get_Transform"):call("get_Parent")
                local owner = par and par:call("get_GameObject")
                if owner and st.hunk and owner:get_address() == st.hunk:get_address() then FL.h = c:add_ref()
                elseif owner and p1 and owner:get_address() == p1:get_address() then FL.p = c:add_ref() end
            end)
        end
        return FL.h, FL.p
    end
    -- (v431) + Radius, IlluminanceThreshold, ShadowNearPlane: HUNK's own IES light has Radius 0.03,
    -- IlluminanceThreshold 1.2 and ShadowNearPlane 0.15 (Leon's 0.3, 115, 0.01), and with those it
    -- lit nothing past a couple of metres: only its small FakeGI point light glowed on a near
    -- wall. Copied, his beam lights what it points at like player 1's (checked side by side,
    -- each light alone). They aren't reset by the game, but a new HUNK has his defaults again.
    local COPY = { "Intensity", "Color", "Cone", "Spread", "Falloff", "ReferenceEffectiveRange", "BounceIntensity",
        "Radius", "IlluminanceThreshold", "ShadowNearPlane" }
    -- (v432) st.p2_flash_bright: player 2's flashlight brightness in % of player 1's (REFramework
    -- panel slider, saved), applied to the copied Intensity
    -- (v436/v437) Sherry (a child player 2, light in her hand, see FL.child_hand): her hands, gun
    -- and head are right by the light, so nothing within 80 cm of it casts a shadow (player 1's
    -- light keeps 1 cm). v436's 40 cm flickered: her head sits ~43 cm from the light and kept
    -- crossing the cutoff; and the twice-a-second copy below briefly put player 1's 1 cm back.
    -- Applied here, in the copy itself, so no frame ever gets player 1's value.
    local CHILD_NEAR = 0.8
    local function copy_light(from, to)
        if from == nil or to == nil then return end
        local k = math.max(0, (st.p2_flash_bright or 100) / 100)
        local child = st.sherry_light_hand ~= false and st.p2_child and st.p2_child()
        for _, key in ipairs(COPY) do
            local ok, v = pcall(from.call, from, "get_" .. key)
            if ok and v ~= nil then
                if key == "Intensity" and type(v) == "number" then v = v * k end
                if key == "ShadowNearPlane" and child and type(v) == "number" then v = math.max(v, CHILD_NEAR) end
                pcall(to.call, to, "set_" .. key, v)
            end
        end
    end
    -- (v433) the visible beam (via.render.LightShaft): HUNK's has FogDensity 0.2, RayleighCoef 0.2,
    -- FilterTransparency 1 and 64 samples (Leon's 0.05, 1, 0.0001, 256): a beam four times as
    -- dense, hard to see through. Player 1's values are copied; st.p2_beam_pct (REFramework panel,
    -- saved) scales the fog density (% of player 1's).
    local SHAFT = { "FogDensity", "RayleighCoef", "FilterTransparency", "NumSamples", "MieCoef", "Dissipation" }
    function FL.copy_shaft(from, to)
        if from == nil or to == nil then return end
        local k = math.max(0, (st.p2_beam_pct or 100) / 100)
        for _, key in ipairs(SHAFT) do
            local ok, v = pcall(from.call, from, "get_" .. key)
            if ok and v ~= nil then
                if key == "FogDensity" and type(v) == "number" then v = v * k end
                pcall(to.call, to, "set_" .. key, v)
            end
        end
    end
    -- (v435) Sherry (a child player 2, her own skeleton): the game places the flashlight for an
    -- adult's pose, and while she aims it ended up at her left shoulder, behind her head, so
    -- her own shadow fell into the beam. After the game places it, the light goes to her left
    -- wrist (l_arm_wrist), 8 cm out along the beam. st.sherry_light_hand = false: off.
    function FL.child_hand()
        if st.sherry_light_hand == false or not (st.p2_child and st.p2_child()) or FL.h == nil then return end
        local wj = st.hunk:call("get_Transform"):call("getJointByName", "l_arm_wrist")
        if wj == nil then return end
        local wp = wj:call("get_Position")
        local fxf = FL.h:call("get_GameObject"):call("get_Transform")
        local ies = FL.h:call("get_IESLight")
        local ixf = ies and ies:call("get_GameObject"):call("get_Transform")
        local d = ixf and (ixf:call("get_Rotation") * Vector3f.new(0, 0, -1)) or Vector3f.new(0, 0, 0)
        fxf:call("set_Position", Vector3f.new(wp.x + d.x * 0.08, wp.y + d.y * 0.08, wp.z + d.z * 0.08))
    end
    local function fix()
        local h, p = flashlights()
        if h == nil then return end
        -- settings
        if p then
            copy_light(p:call("get_IESLight"), h:call("get_IESLight"))
            copy_light(p:call("get_FakeGI"), h:call("get_FakeGI"))
            FL.copy_shaft(p:call("get_LightShaft"), h:call("get_LightShaft"))
        end
        -- aim: each light under the flashlight is turned so its beam axis points at the target
        -- (the IES light shines along -Z, the light shaft, glow effect and bounce light along
        -- +Z). Absolute, not "the IES light's correction applied to all": the game resets the
        -- IES light every frame but not the shaft, so a shared correction piled up on the
        -- shaft and spun it round (the flashing beam). Target smoothed a little, as the game's.
        local t = st.target_point()
        local tp = Vector3f.new(t[1], t[2], t[3])
        if FL.tp then tp = FL.tp + (tp - FL.tp) * 0.35 end
        FL.tp = tp
        local ch = h:call("get_GameObject"):call("get_Transform"):call("get_Child")
        while ch do
            local axis = ch:call("get_GameObject"):call("get_Name") == "IESLight" and -1 or 1
            local rot = ch:call("get_Rotation")
            local pos = ch:call("get_Position")
            local d = tp - pos
            local L = d:length()
            if L > 0.3 then
                d = d * (1 / L)
                local c = rot * Vector3f.new(0, 0, axis)
                local ax = Vector3f.new(c.y * d.z - c.z * d.y, c.z * d.x - c.x * d.z, c.x * d.y - c.y * d.x)
                local w = 1 + c.x * d.x + c.y * d.y + c.z * d.z
                if w > 1e-4 then
                    local n = math.sqrt(w * w + ax.x * ax.x + ax.y * ax.y + ax.z * ax.z)
                    ch:call("set_Rotation", Quaternion.new(w / n, ax.x / n, ax.y / n, ax.z / n) * rot)
                end
            end
            ch = ch:call("get_Next")
        end
    end
    st.p2_flashlight_fix = fix
    local td = sdk.find_type_definition("app.ropeway.FlashLight")
    local m = td and td:get_method("applyTransform")
    if m then
        sdk.hook(m, function(args)
            local s = thread.get_hook_storage()
            s.fl = false
            -- (v435) player 2's light on any way of play (for Sherry's hand fix below)
            s.mine = FL.h ~= nil and st.hunk ~= nil and sdk.to_int64(args[2]) == FL.h:get_address()
            if p2c.active and st.hunk and st.target_point and st.p2_flashlight ~= false and FL.h then
                s.fl = sdk.to_int64(args[2]) == FL.h:get_address()
                -- (v419d) the hand holding it out points at player 2's crosshair too, not at
                -- player 1's (the game's TargetPosition comes from the main camera)
                if s.fl then
                    pcall(function()
                        local t = st.target_point()
                        FL.h:call("set_TargetPosition", Vector3f.new(t[1], t[2], t[3]))
                    end)
                end
            end
        end, function(r)
            local s = thread.get_hook_storage()
            if s.mine then s.mine = nil; pcall(FL.child_hand) end
            if s.fl then pcall(fix) end
            return r
        end)
    end
    -- (finds the flashlights, so the hook has HUNK's to compare against)
    re.on_frame(function()
        if p2c.active and st.hunk then pcall(flashlights) else FL.tp = nil end
        -- (v431) the light settings on every way of play (split screen also copies them every
        -- frame in the hook above), twice a second
        if st.hunk and st.frame % 30 == 0 and st.p2_flashlight ~= false then
            pcall(function()
                local h, p = flashlights()
                if h and p then
                    copy_light(p:call("get_IESLight"), h:call("get_IESLight"))
                    copy_light(p:call("get_FakeGI"), h:call("get_FakeGI"))
                    FL.copy_shaft(p:call("get_LightShaft"), h:call("get_LightShaft"))
                end
            end)
        end
    end)
end

-- split screen aiming: keep HUNK's body-turn controller (PlayerController.CharAngle, angle =
-- atan2(x, z) of his facing) on the aim; if his body is still well off after a moment, the
-- game isn't going to turn him, so turn him the rest of the way
function st.split_turn(want)
    local pc = comp(st.hunk, "app.ropeway.survivor.player.PlayerController")
    local ca = pc and safe(function() return pc:get_field("<CharAngle>k__BackingField") end)
    if ca == nil then return end
    pcall(function() ca:set_field("_Target", want) end)
    local xf = st.hunk:call("get_Transform")
    local f = xf:call("get_Rotation") * Vector3f.new(0, 0, 1)
    local cur = math.atan(f.x, f.z)
    local diff = math.atan(math.sin(want - cur), math.cos(want - cur))
    local now = os.clock()
    -- the game's own turn stops short once the body is within ~10-15 degrees of the aim
    -- (after a sprint it can also stall far off), which leaves the gun pointing beside the
    -- crosshair: after a short moment the rest of the turn is finished here, smoothly
    if math.abs(diff) < 0.02 then st.split_turn_t = nil; return end
    st.split_turn_t = st.split_turn_t or now
    if now - st.split_turn_t > 0.12 then
        local step = math.max(-0.35, math.min(0.35, diff * 0.35))
        if math.abs(step) < 0.01 then step = diff end
        local y = cur + step
        xf:call("set_Rotation", Quaternion.new(math.cos(y / 2), 0, math.sin(y / 2), 0))
        pcall(function() ca:set_field("<Current>k__BackingField", y) end)
    end
end

local function hunk_is_aiming()
    local cond = comp(st.hunk, "app.ropeway.survivor.player.PlayerCondition")
    return cond and (safe(function() return cond:call("get_IsHold") end) or safe(function() return cond:call("get_IsHoldStart") end)) or false
end

local function hunk_sub_holding()
    local cond = comp(st.hunk, "app.ropeway.survivor.player.PlayerCondition")
    return cond ~= nil and safe(function() return cond:call("get_IsSupportHold") end) == true
end

local function update_vaim(dt)
    if st.hunk == nil then st.vaim.active = false; return end
    local sub = (st.sub_aim or ai.active) and hunk_sub_holding()
    local gun = not sub and hunk_is_aiming()   -- (gun aims face the crosshair point; was the face_target option, default on)
    if p2c.active then   -- split screen: everything aims at player 2's crosshair
        gun = hunk_is_aiming() or hunk_sub_holding()
        sub = false
    end
    local aiming = sub or gun
    if aiming and not st.vaim.active then
        -- start aiming along HUNK's facing, level
        local rot = st.hunk:call("get_Transform"):call("get_Rotation")
        local f = rot * Vector3f.new(0, 0, 1)
        st.vaim.yaw = math.atan(-f.x, -f.z)
        st.vaim.pitch = 0
        st.vaim.active = true
    elseif not aiming then
        st.vaim.active = false
    end
    st.vaim.sub = sub
    st.vaim.gun = gun
    if st.vaim.active and (gun or (ai.active and sub and ai.aim_pos)) and st.target_point then
        -- face the point under the crosshair (P1's, or player 2's own in split screen), from
        -- HUNK's chest
        local hp = st.hunk:call("get_Transform"):call("get_Position")
        local t = st.target_point()
        local dx, dy, dz = t[1] - hp.x, t[2] - (hp.y + 1.45), t[3] - hp.z
        local horiz = math.sqrt(dx * dx + dz * dz)
        if p2c.active and p2c.fwd and horiz + math.abs(dy) < 1.5 then
            -- split screen, target right at his chest: aim straight along player 2's view
            st.vaim.yaw = p2c.yaw
            st.vaim.pitch = math.max(-st.max_pitch, math.min(st.max_pitch, p2c.pitch))
        elseif horiz + math.abs(dy) > 0.3 then
            st.vaim.yaw = math.atan(-dx, -dz)
            st.vaim.pitch = math.max(-st.max_pitch, math.min(st.max_pitch, math.atan(dy, horiz)))
        end
    elseif st.vaim.active and st.p2_dev and not menu.p2_lock then
        local dev = st.p2_dev
        local ax = dev and safe(function() return dev:call("get_AxisR") end)
        if ax then
            local x = st.invert_x and -ax.x or ax.x
            local y = st.invert_y and -ax.y or ax.y
            if math.abs(x) < 0.15 then x = 0 end
            if math.abs(y) < 0.15 then y = 0 end
            st.vaim.yaw = st.vaim.yaw - x * st.aim_speed * dt
            st.vaim.pitch = math.max(-st.max_pitch, math.min(st.max_pitch, st.vaim.pitch + y * st.aim_speed * 0.6 * dt))
        end
    end
    -- ease the spine tilt in and out so entering / leaving the stance doesn't snap
    local want = (st.vaim.active and (sub or gun)) and 1 or 0
    st.spine_w = st.spine_w + (want - st.spine_w) * math.min(1, dt * 10)
end

-- Pitch: the game never tilts HUNK's upper body from the virtual camera, so after
-- the animation and IK have run we rotate his spine about his right axis.
local SPINE = { { "spine_0", 0.3 }, { "spine_1", 0.35 }, { "spine_2", 0.35 } }   -- arms hang off spine_2, so the gun follows
local function q_conj(q) return Quaternion.new(q.w, -q.x, -q.y, -q.z) end
local function apply_spine_pitch()
    if st.hunk == nil or st.spine_w < 0.01 then return end
    local angle = -st.vaim.pitch * st.spine_w   -- positive bends forward (looks down)
    -- split screen: the game's own look-at already aims him at player 2's crosshair (see
    -- PlayerLookAt below), pitch included up to about +0.38 / -0.5 rad; only add what it
    -- leaves out: the part beyond its limits, and whatever part of it is blended out
    if (p2c.active or (st.tank and st.tank.fa_aim)) and st.la_rate then
        local r, p = math.max(0, math.min(1, st.la_rate())), st.vaim.pitch
        local excess = p - math.max(-0.5, math.min(0.38, p))
        angle = -(p * (1 - r) + excess * r) * st.spine_w
    end
    if math.abs(angle) < 0.002 then return end
    local xf = st.hunk:call("get_Transform")
    local right = xf:call("get_Rotation") * Vector3f.new(1, 0, 0)
    for _, e in ipairs(SPINE) do
        local j = xf:call("getJointByName", e[1])
        local parent = j and j:call("get_Parent")
        if parent then
            local a = angle * e[2]
            local s = math.sin(a / 2)
            local qp = Quaternion.new(math.cos(a / 2), right.x * s, right.y * s, right.z * s)
            local pq = parent:call("get_Rotation")
            j:call("set_LocalRotation", q_conj(pq) * qp * pq * j:call("get_LocalRotation"))
        end
    end
end
re.on_application_entry("LateUpdateBehavior", function() pcall(apply_spine_pitch) end)


-- Raycast / crosshair target ---------------------------------------------------

local PHYS = sdk.find_type_definition("via.physics.System")
local TERRAIN_LAYER = 2

local function cast_ray(a, b)
    local q = sdk.create_instance("via.physics.CastRayQuery")
    local res = sdk.create_instance("via.physics.CastRayResult")
    q:call("setRay(via.vec3, via.vec3)", a, b)
    q:call("clearOptions"); q:call("enableAllHits"); q:call("enableNearSort")
    local fi = q:call("get_FilterInfo")
    fi:call("set_Group", 0); fi:call("set_MaskBits", 0xFFFFFFFF & ~1); fi:call("set_Layer", TERRAIN_LAYER)
    q:call("set_FilterInfo", fi)
    sdk.call_native_func(sdk.get_native_singleton("via.physics.System"), PHYS,
        "castRay(via.physics.CastRayQuery, via.physics.CastRayResult)", q, res)
    local n = res:call("get_NumContactPoints")
    if n and n > 0 then return res:call("getContactPoint(System.UInt32)", 0):get_field("Position") end
    return nil
end

-- P1's crosshair ray (shared aim: HUNK's bullets follow P1's camera)
local function aim_ray()
    if p2c.active and p2c.pos then
        -- split screen: player 2's crosshair ray, started level with HUNK instead of at the
        -- camera (it sits behind his shoulder), so a railing or wall between the camera and
        -- HUNK is never what he aims at
        local f = p2c.fwd
        local o = { p2c.pos.x, p2c.pos.y, p2c.pos.z }
        local hp = st.hunk and safe(function() return st.hunk:call("get_Transform"):call("get_Position") end)
        if hp then
            local t0 = (hp.x - o[1]) * f[1] + (hp.y + 1.45 - o[2]) * f[2] + (hp.z - o[3]) * f[3]
            if t0 > 0 then o = { o[1] + f[1] * t0, o[2] + f[2] * t0, o[3] + f[3] * t0 } end
        end
        return o, { f[1], f[2], f[3] }
    end
    local cs = sdk.get_managed_singleton("app.ropeway.camera.CameraSystem")
    local p, d = cs:call("get_CameraPosition"), cs:call("get_CameraDirection")
    return { p.x, p.y, p.z }, { d.x, d.y, d.z }
end

local target_cache = { frame = -1 }
local function target_point()
    -- networked co-op: HUNK aims where the REMOTE player aims (their crosshair point), not the
    -- local player's. The sending machine lifts its own point with st.net_local_ask set (see the
    -- RE2R_MP_NET module), which momentarily disables this override.
    if RE2R_MP_NET and RE2R_MP_NET.remote_aim_point and not st.net_local_ask then
        local ap = RE2R_MP_NET.remote_aim_point()
        if ap then return ap, true end
    end
    if ai.active and ai.aim_pos then return ai.aim_pos, true end   -- AI: the enemy it is shooting
    if st.tank and st.tank.aim_pos then return st.tank.aim_pos, true end   -- tank aim / auto-aim
    if target_cache.frame == st.frame then return target_cache.p, target_cache.hit end
    local o, d = aim_ray()
    local a = Vector3f.new(o[1], o[2], o[3])
    local b = Vector3f.new(o[1] + d[1] * 60, o[2] + d[2] * 60, o[3] + d[3] * 60)
    local ok, hp = pcall(cast_ray, a, b)
    local p, hit
    if ok and hp then p, hit = { hp.x, hp.y, hp.z }, true else p, hit = { b.x, b.y, b.z }, false end
    -- the terrain ray passes through enemies: if the crosshair is on an enemy, stop there
    local tmax = math.sqrt((p[1] - o[1]) ^ 2 + (p[2] - o[2]) ^ 2 + (p[3] - o[3]) ^ 2)
    local em = sdk.get_managed_singleton("app.ropeway.EnemyManager")
    local list = em and safe(function() return em:call("get_ActiveEnemyList") end)
    local best = nil
    local spots = {}
    for i = 0, (list and (safe(function() return list:call("get_Count") end) or 0) or 0) - 1 do
        spots[#spots + 1] = safe(function() return list:call("get_Item", i):call("get_GameObject"):call("get_Transform"):call("get_Position") end)
    end
    -- in split screen player 2 can put the crosshair on Leon too: stop there as well, or HUNK
    -- (aiming from his chest, not the camera) lines up on the wall behind him and looks off to the side
    if p2c.active then
        local p1 = p1_go()
        spots[#spots + 1] = p1 and safe(function() return p1:call("get_Transform"):call("get_Position") end)
    end
    for _, ep in pairs(spots) do
        if ep then
            for _, h in ipairs({ 0.3, 0.9, 1.5 }) do
                local q = { ep.x - o[1], ep.y + h - o[2], ep.z - o[3] }
                local t = q[1] * d[1] + q[2] * d[2] + q[3] * d[3]
                if t > 0.5 and t < tmax and (best == nil or t < best) then
                    local px, py, pz = q[1] - d[1] * t, q[2] - d[2] * t, q[3] - d[3] * t
                    if px * px + py * py + pz * pz < 0.25 then best = t end
                end
            end
        end
    end
    if best then p, hit = { o[1] + d[1] * best, o[2] + d[2] * best, o[3] + d[3] * best }, true end
    target_cache.frame, target_cache.p, target_cache.hit = st.frame, p, hit
    return p, hit
end

st.target_point = target_point

-- Projectile weapons: the game fires every shot from P1's camera along the crosshair ray.
-- That's invisible for bullets, but rockets, grenades, flames and the minigun's tracers
-- would leave from Leon's camera. For those, HUNK's shot is moved to his muzzle and
-- pointed at the crosshair point.
local REDIRECT = { wp4100 = 42, wp4200 = 43, wp4300 = 44, wp4400 = 45, wp4600 = 49, wp4700 = 50 }
local gen_info = {}   -- generator address -> { wt, weapon transform } or false
local MUZZLE_HASH = sdk.find_type_definition("app.ropeway.EquipmentDefine"):get_method("getMuzzleJointHash(app.ropeway.EquipmentDefine.WeaponType)")
local function generator_weapon(addr, gen)
    local info = gen_info[addr]
    if info == nil then
        info = false
        local wxf = safe(function() return gen:call("get_GameObject"):call("get_Transform"):call("get_Parent") end)
        local name = wxf and safe(function() return wxf:call("get_GameObject"):call("get_Name") end)
        local wt = name and REDIRECT[name]
        if wt then
            local h = MUZZLE_HASH and safe(function() return MUZZLE_HASH:call(nil, wt) end)
            info = { wt = wt, xf = wxf, hash = h }
        end
        gen_info[addr] = info
    end
    return info or nil
end
local function muzzle_pos(info)
    local j = info.hash and safe(function() return info.xf:call("getJointByHash", info.hash) end)
    return (j and safe(function() return j:call("get_Position") end)) or safe(function() return info.xf:call("get_Position") end)
end
-- rewrite a shot matrix (mat4 at args[i]) so the shot leaves player 2's gun / chest towards
-- target_point(): projectile weapons from the muzzle; bullets (whose hits the game works
-- out from this matrix, i.e. from player 1's camera) only for the AI / split screen
-- (v418) a player 2 shot that kept the game's matrix in split screen flies along player 1's
-- camera (it matches player 2's crosshair only while both look the same way). Each such skip is
-- written to the player 2 log with its reason (at most one line a second), and a generator the
-- owner table doesn't know yet (refreshed every 30 frames) counts as his when his weapon is the
-- one running (current_owner), with the table refreshed at once.
st.shot_log = st.shot_log or { n = 0, skips = 0, last = -1000, fixed = 0 }
function st.shot_skip(why)   -- (a field: main chunk at 200 locals)
    local L = st.shot_log
    L.skips = L.skips + 1
    if not p2c.active then return end
    if st.frame - L.last < 60 then return end
    L.last = st.frame
    if st.p2log then pcall(st.p2log, "split shot not aimed (" .. why .. "), " .. L.skips .. " so far") end
end
local function redirect_shot_matrix(args, i)
    if st.hunk == nil then return end
    local addr = sdk.to_int64(args[2])
    local cur = current_owner()
    st.last_gen = { frame = st.frame, owner = st.owners[addr], cur = cur }   -- (dev bridge)
    local own = st.owners[addr]
    if own == nil and cur == OWN_HUNKW then
        -- a generator of his the table hasn't caught up with (a new gun): his
        own = OWN_HUNKW
        st.shot_log.fixed = st.shot_log.fixed + 1
        pcall(refresh_owners)
    end
    if own ~= OWN_HUNKW then
        if p2c.active and is_hunk_owner(cur) then st.shot_skip("generator owner " .. tostring(own)) end
        return
    end
    st.shot_log.n = st.shot_log.n + 1
    -- plain co-op keeps the game's shot (HUNK fires where player 1 aims, as always);
    -- only the AI partner and split screen shoot from player 2's side
    if not (ai.active or (p2c.active and p2c.pos) or (st.tank and st.tank.aim_pos)) then
        if st.split then st.shot_skip(p2c.active and "no camera position" or "split view down") end
        return
    end
    local ok, err = pcall(function()
        local gen = sdk.to_managed_object(args[2])
        local info = generator_weapon(addr, gen)
        local mp
        if info then
            mp = muzzle_pos(info)
        else
            local fam = gen:get_type_definition():get_name()
            if fam:find("^Throw") then
                -- thrown grenades: the game throws from his hand along player 1's camera; keep
                -- the hand, throw towards player 2's crosshair (split screen / AI / fixed cameras)
                local m3 = st.m4get and st.m4get[4]:call(sdk.to_int64(args[i]))
                if m3 == nil then return end
                mp = Vector3f.new(m3.x, m3.y, m3.z)
            elseif fam ~= "BulletDefaultGenerator" and fam ~= "BulletShotGunGenerator" and fam ~= "BulletSparkGenerator" then
                st.shot_skip("generator " .. tostring(fam))
                return
            end
            local t = target_point()
            if mp then
                -- (the throw's hand position, set above)
            elseif p2c.active and p2c.pos then
                -- from the crosshair ray where it passes HUNK (not from behind him at the camera)
                local o, d = aim_ray()
                mp = Vector3f.new(o[1] + d[1] * 0.2, o[2] + d[2] * 0.2, o[3] + d[3] * 0.2)
            elseif ((ai.active and ai.aim_pos) or (st.tank and st.tank.aim_pos)) and t then
                local hp = st.hunk:call("get_Transform"):call("get_Position")
                local dx, dy, dz = t[1] - hp.x, t[2] - (hp.y + 1.4), t[3] - hp.z
                local dl = math.max(0.01, math.sqrt(dx * dx + dy * dy + dz * dz))
                mp = Vector3f.new(hp.x + dx / dl * 0.6, hp.y + 1.4 + dy / dl * 0.6, hp.z + dz / dl * 0.6)
            else
                st.shot_skip("no aim source")
                return
            end
        end
        local t = target_point()
        if mp == nil or t == nil then st.shot_skip("no target point"); return end
        local fx, fy, fz = t[1] - mp.x, t[2] - mp.y, t[3] - mp.z
        local len = math.sqrt(fx * fx + fy * fy + fz * fz)
        if len < 1.0 then
            -- target right at the muzzle: keep the game's shot (split screen: straight along
            -- player 2's view, the game's shot would come from Leon's camera)
            if not (p2c.active and p2c.fwd) then return end
            fx, fy, fz = p2c.fwd[1], p2c.fwd[2], p2c.fwd[3]
        else
            fx, fy, fz = fx / len, fy / len, fz / len
        end
        -- rows: right, up, forward, position (matches the game's shot matrix)
        local rl = math.sqrt(fz * fz + fx * fx)
        if rl < 0.05 then st.shot_skip("straight up / down"); return end   -- straight up/down
        local rx, ry, rz = fz / rl, 0, -fx / rl
        local ux, uy, uz = fy * rz - fz * ry, fz * rx - fx * rz, fx * ry - fy * rx
        -- the matrix is the caller's: write it in place through via.mat4's own setters
        -- (a ValueType from sdk.to_valuetype is a copy, so writing that changes nothing)
        local ptr = sdk.to_int64(args[i])
        st.last_shot = { frame = st.frame, from = { mp.x, mp.y, mp.z }, dir = { fx, fy, fz }, target = t }
        st.m4set[1]:call(ptr, Vector4f.new(rx, ry, rz, 0))
        st.m4set[2]:call(ptr, Vector4f.new(ux, uy, uz, 0))
        st.m4set[3]:call(ptr, Vector4f.new(fx, fy, fz, 0))
        st.m4set[4]:call(ptr, Vector4f.new(mp.x, mp.y, mp.z, 1))
    end)
    if not ok then st.shot_skip("error " .. tostring(err)) end
end
st.m4set = (function()
    local t = sdk.find_type_definition("via.mat4")
    return { t:get_method("set_m0"), t:get_method("set_m1"), t:get_method("set_m2"), t:get_method("set_m3") }
end)()
st.m4get = (function()
    local t = sdk.find_type_definition("via.mat4")
    return { t:get_method("get_m0"), t:get_method("get_m1"), t:get_method("get_m2"), t:get_method("get_m3") }
end)()
do
    local td = sdk.find_type_definition("app.ropeway.weapon.generator.ShellGeneratorBase")
    for _, m in ipairs(td and td:get_methods() or {}) do
        local pt = m:get_name() == "generate" and m:get_num_params() >= 1 and m:get_param_types()[1]
        if pt and pt:get_full_name() == "via.mat4" then   -- written in place: only hook a real mat4
            sdk.hook(m, function(args) redirect_shot_matrix(args, 3) end, function(r) return r end)
        end
    end
    -- bullets go straight to generateShellProcess(mat4): the ballistic flight follows that matrix
    for _, gn in ipairs({ "BulletDefaultGenerator", "BulletShotGunGenerator", "BulletSparkGenerator", "ThrowGrenadeGenerator" }) do
        local gt = sdk.find_type_definition("app.ropeway.weapon.generator." .. gn)
        for _, m in ipairs(gt and gt:get_methods() or {}) do
            local pt = m:get_name() == "generateShellProcess" and m:get_num_params() == 1 and m:get_param_types()[1]
            if pt and pt:get_full_name() == "via.mat4" then
                sdk.hook(m, function(args) redirect_shot_matrix(args, 3) end, function(r) return r end)
            end
        end
    end
end

-- (v438, v439) Friendly fire (Extras > Experimental: st.friendly_fire, off by default; st.ff_pct, the
-- hit in % of what it does to an enemy, 50 by default). The game never lets a player's attack
-- touch a player: player 1's shots at player 2 gave no onHitDamage at all, and the attack data's
-- own FriendlyFire flag sits behind the physics filters. So the hits are worked out here and
-- given the game's way: HitPointController.addDamage(-n) on the other player and a damage
-- reaction (SurvivorCondition.setDamageAction). Both ways, every weapon:
-- - bullets (BulletDefault / ShotGun / Spark generators, generateShellProcess(mat4), read after
--   the redirect above has aimed player 2's shot): a ray along the shot matrix against the other
--   player's body (a capsule from 0.2 m above the root to the head, 0.28 m), stopped by walls
--   (terrain ray) and by an enemy in the way. Started where the ray passes the shooter: player
--   1's own shots leave from her camera, behind her. Damage: the shell's own base damage
--   (ShellUserData.AttackSetting.Normal.Damage). The shotgun fires once for all its pellets:
--   a centre pellet and its ring (Normal: 8 at 2.5 degrees), each tested and added up.
-- - flames (RadiateDefaultGenerator pulses every 12 frames while firing): a 4.5 m cone.
-- - the knife: PlayerCondition.IsKnifeAction (true ~0.4 s a swing): once a swing, the other
--   player within 1.35 m in front (70 degrees), nothing between. (IsKnifeAction is true for a
--   grenade throw too: not with a grenade (65 / 66) as the sub weapon.)
-- - grenades (ThrowGrenadeGenerator's <generateShellProcess>b__1_0(GameObject): the thrown
--   RigidGrenade): followed until it goes (it explodes), then a blast there: 4.5 m, falling
--   off to 30 % at the edge, not through walls. The flash grenade (WeaponType 66): the Flash
--   reaction within 8 m, no damage.
-- Never on Sherry (st.p2_child), nor on player 2 with Invincible on, nor on a downed player.
-- A hit that would kill player 1 is her death (st.p1_let_die), or her going down where the
-- downed rules apply; player 2 goes down as from any hit (the damage hooks above).
st.ff = { log = {}, n = 0, react_at = {}, nades = {}, gi = {}, kn = { p1 = {}, p2 = {} } }
;(function()
    local FF = st.ff
    local nk_td = sdk.find_type_definition("System.Nullable`1<app.ropeway.EnemyDefine.KindID>")
    local DT = { small = 16843008, medium = 16908544, exp_s = 16843776, exp_m = 16909312, exp_l = 16974848,
        flash = 16778496, electric = 16779008 }
    FF.DT = DT
    local HPC, SC = "app.ropeway.HitPointController", "app.ropeway.survivor.player.PlayerCondition"
    local function on() return st.friendly_fire == true and st.hunk ~= nil and not (st.in_cutscene and st.in_cutscene()) end
    FF.on = on
    local function log(s)
        FF.n = FF.n + 1
        local L = FF.log
        L[#L + 1] = string.format("[%d] %s", st.frame, s)
        if #L > 40 then table.remove(L, 1) end
    end
    -- owner code of the attack -> shooter, victim, "p1" / "p2" (who is hit)
    local function sides(own)
        local p1 = p1_go()
        if p1 == nil or st.hunk == nil then return nil end
        if own == OWN_P1W or own == OWN_P1 then return p1, st.hunk, "p2" end
        if own == OWN_HUNKW or own == OWN_HUNK then return st.hunk, p1, "p1" end
        return nil
    end
    local function hurtable(victim, which)
        if which == "p2" then
            if (st.p2_child and st.p2_child()) or st.invulnerable or st.p2_down then return false end
        elseif st.p1_down then
            return false
        end
        local hpc = comp(victim, HPC)
        if hpc == nil then return false end
        if safe(function() return hpc:call("get_Invincible") end) == true or safe(function() return hpc:call("get_NoDamage") end) == true then return false end
        return true, hpc
    end
    local function hit(shooter, victim, which, dmg, react, from, what)
        local ok, hpc = hurtable(victim, which)
        if not ok then return end
        local n = math.floor(dmg * math.max(0, st.ff_pct or 50) / 100 + 0.5)
        if n <= 0 and react ~= DT.flash then return end
        local cur = safe(function() return hpc:call("get_CurrentHitPoint") end) or 0
        log(string.format("%s hit by %s: %s, %d (hp %d)", which, which == "p2" and "p1" or "p2", what, n, cur))
        local lethal = n > 0 and cur - n < 1
        if n > 0 then
            if lethal and which == "p1" and not (st.p1_down_active and st.p1_down_active()) then
                if st.p1_let_die then pcall(st.p1_let_die) end
                return
            end
            pcall(hpc.call, hpc, "addDamage", -n)
        end
        if lethal then return end   -- (going down plays its own fall)
        -- the reaction: at most one every half second (a submachine gun would stun-lock)
        if st.frame - (FF.react_at[which] or -1000) < 30 then return end
        FF.react_at[which] = st.frame
        local cond = comp(victim, SC)
        if cond == nil then return end
        local vp = victim:call("get_Transform"):call("get_Position")
        local dx, dz = from.x - vp.x, from.z - vp.z   -- (towards where the hit came from)
        local l = math.sqrt(dx * dx + dz * dz)
        if l < 0.01 then
            local f = victim:call("get_Transform"):call("get_Rotation") * Vector3f.new(0, 0, 1)
            dx, dz, l = f.x, f.z, math.max(0.01, math.sqrt(f.x * f.x + f.z * f.z))
        end
        pcall(cond.call, cond, "setDamageAction", react, Vector3f.new(dx / l, 0, dz / l), false, nk_td and ValueType.new(nk_td))
    end
    FF.hit = hit
    -- the other player's body: a capsule from 0.2 m above the root to the top of the head
    local function body(victim)
        local xf = victim:call("get_Transform")
        local p = xf:call("get_Position")
        local h = xf:call("getJointByName", "head")
        local hp = h and h:call("get_Position")
        local top = hp and Vector3f.new(hp.x, hp.y + 0.1, hp.z) or Vector3f.new(p.x, p.y + 1.7, p.z)
        return Vector3f.new(p.x, p.y + 0.2, p.z), top
    end
    local function dot(a, b) return a.x * b.x + a.y * b.y + a.z * b.z end
    -- closest approach of o + d t (t0..t1, d unit) and segment a-b: t, distance
    local function ray_seg(o, d, t0, t1, a, b)
        local v = Vector3f.new(b.x - a.x, b.y - a.y, b.z - a.z)
        local w = Vector3f.new(o.x - a.x, o.y - a.y, o.z - a.z)
        local e, bb, c, f = dot(v, v), dot(d, v), dot(d, w), dot(v, w)
        local den = e - bb * bb
        local t = den > 1e-6 and (bb * f - c * e) / den or t0
        t = math.max(t0, math.min(t1, t))
        local s = e > 1e-6 and (f + bb * t) / e or 0
        s = math.max(0, math.min(1, s))
        t = math.max(t0, math.min(t1, bb * s - c))
        local px, py, pz = o.x + d.x * t - (a.x + v.x * s), o.y + d.y * t - (a.y + v.y * s), o.z + d.z * t - (a.z + v.z * s)
        return t, math.sqrt(px * px + py * py + pz * pz)
    end
    local function enemy_spots()
        if FF.spots_f == st.frame then return FF.spots end
        local spots = {}
        local em = sdk.get_managed_singleton("app.ropeway.EnemyManager")
        local list = em and safe(function() return em:call("get_ActiveEnemyList") end)
        for i = 0, (list and (safe(function() return list:call("get_Count") end) or 0) or 0) - 1 do
            -- (live ones only: a body on the floor between the players stopped every shot)
            local e = safe(function() return list:call("get_Item", i) end)
            if e and safe(function() return e:call("get_IsLive") end) ~= false then
                spots[#spots + 1] = safe(function() return e:call("get_GameObject"):call("get_Transform"):call("get_Position") end)
            end
        end
        FF.spots_f, FF.spots = st.frame, spots
        return spots
    end
    -- does a shot along o + d reach the victim (before range, walls and enemies)
    local function reaches(shooter, victim, o, d, range)
        local a, b = body(victim)
        -- (from where the ray passes the shooter: player 1's shots leave from her camera)
        local sp = shooter:call("get_Transform"):call("get_Position")
        local ts = math.max(0, dot(Vector3f.new(sp.x - o.x, sp.y + 1.2 - o.y, sp.z - o.z), d) - 0.3)
        local t, dist = ray_seg(o, d, ts, range, a, b)
        FF.why = string.format("miss %.2f m at %.1f m", dist, t)
        if dist > 0.28 then return false end
        local okr, wall = pcall(cast_ray, Vector3f.new(o.x + d.x * ts, o.y + d.y * ts, o.z + d.z * ts), Vector3f.new(o.x + d.x * t, o.y + d.y * t, o.z + d.z * t))
        FF.why = "wall"
        if okr and wall then return false end
        FF.why = "enemy"
        for _, ep in pairs(enemy_spots()) do
            for _, h in ipairs({ 0.3, 0.9, 1.5 }) do
                local q = Vector3f.new(ep.x - o.x, ep.y + h - o.y, ep.z - o.z)
                local te = dot(q, d)
                if te > ts and te < t - 0.3 then
                    local px, py, pz = q.x - d.x * te, q.y - d.y * te, q.z - d.z * te
                    if px * px + py * py + pz * pz < 0.35 * 0.35 then return false end
                end
            end
        end
        return true
    end
    -- what a generator's shell does to an enemy (cached per generator)
    local function gen_info(gen, addr)
        local c = FF.gi[addr]
        if c then return c end
        c = { fam = gen:get_type_definition():get_name(), dmg = 150, range = 60 }
        pcall(function()
            local ud = gen:get_field("_TGeneratorUserDataBase")
            local gs = ud and ud:get_field("BulletGenerateSetting")
            if gs == nil then return end
            local function shell_vals(sp)
                local su = sp and sp:get_field("ShellUserData")
                local as = su and su:get_field("AttackSetting")
                local dm = as and as:get_field("Normal"):get_field("Damage"):get_field("_BaseValue")
                local bs = su and su:get_field("BallisticSetting")
                if bs then c.speed, c.grav = bs:get_field("_Speed"), bs:get_field("_Gravity") end
                return dm, bs and bs:get_field("_FiringRange")
            end
            if c.fam == "BulletShotGunGenerator" then
                c.dmg, c.range = shell_vals(gs:get_field("Center"))
                c.around = shell_vals(gs:get_field("Around"))
                local nrm = gs:get_field("Normal")
                c.n, c.deg = nrm:get_field("AroundBulletNum"), nrm:get_field("AroundBulletDegree")
            else
                for _, f in ipairs(gs:get_type_definition():get_fields()) do
                    if not f:is_static() and f:get_type():get_full_name():find("ShellPrefabSetting") then
                        local dm, fr = shell_vals(f:get_data(gs))
                        if dm then c.dmg, c.range = dm, fr; break end   -- (the grenade launcher: its acid round's)
                    end
                end
            end
        end)
        pcall(function()
            local par = gen:call("get_GameObject"):call("get_Transform"):call("get_Parent")
            local g = par and par:call("get_GameObject"):call("getComponent(System.Type)", sdk.typeof("app.ropeway.implement.Implement"))
            c.wt = g and g:call("get_WeaponType")
        end)
        c.dmg = tonumber(c.dmg) or 150
        c.range = (tonumber(c.range) or 0) > 0 and c.range or 60
        log(string.format("gun %s wt %s: damage %s, range %s, speed %s, gravity %s, pellets %s x %s", c.fam, tostring(c.wt), tostring(c.dmg), tostring(c.range), tostring(c.speed), tostring(c.grav), tostring(c.n), tostring(c.around)))
        FF.gi[addr] = c
        return c
    end
    local function unit(x, y, z)
        local l = math.sqrt(x * x + y * y + z * z)
        if l < 1e-6 then return nil end
        return Vector3f.new(x / l, y / l, z / l)
    end
    function FF.on_fire(own, gen, ptr, gn)
        local shooter, victim, which = sides(own)
        if victim == nil or not hurtable(victim, which) then return end
        local r0, r1, r2, r3 = st.m4get[1]:call(ptr), st.m4get[2]:call(ptr), st.m4get[3]:call(ptr), st.m4get[4]:call(ptr)
        local o = Vector3f.new(r3.x, r3.y, r3.z)
        local d = unit(r2.x, r2.y, r2.z)
        if d == nil then return end
        if gn == "RadiateDefaultGenerator" then
            -- (v439) from the shooter's chest, not the shot matrix: player 1's flame matrix
            -- starts at her camera, and the 4.5 m cone from there fell short of anyone in front
            -- of her. The stream reaches ~6 m.
            local sp = shooter:call("get_Transform"):call("get_Position")
            local so = Vector3f.new(sp.x, sp.y + 1.2, sp.z)
            local a, b = body(victim)
            local mid = Vector3f.new((a.x + b.x) / 2, (a.y + b.y) / 2, (a.z + b.z) / 2)
            local q = Vector3f.new(mid.x - so.x, mid.y - so.y, mid.z - so.z)
            local t = dot(q, d)
            if t < -0.3 or t > 6.0 then if FF.debug then log(string.format("flames: %.1f m along", t)) end return end
            local px, py, pz = q.x - d.x * t, q.y - d.y * t, q.z - d.z * t
            local off = math.sqrt(px * px + py * py + pz * pz)
            if off > 0.5 + math.max(0, t) * 0.35 then if FF.debug then log(string.format("flames: %.1f m off at %.1f m", off, t)) end return end
            local okr, wall = pcall(cast_ray, so, mid)
            if okr and wall then return end
            hit(shooter, victim, which, 60, DT.small, so, "flames")
            return
        end
        if gn == "BulletRocketGenerator" or gn == "BulletGrenadeGenerator" then
            return FF.launch(own, shooter, victim, which, gen, o, d, gn)
        end
        local c = gen_info(gen, gen:get_address())
        if c.fam == "BulletShotGunGenerator" then
            local rt, up = Vector3f.new(r0.x, r0.y, r0.z), Vector3f.new(r1.x, r1.y, r1.z)
            local total, n = 0, 0
            if reaches(shooter, victim, o, d, c.range) then total, n = c.dmg, 1 end
            local cnt = tonumber(c.n) or 8
            local tn = math.tan(math.rad(tonumber(c.deg) or 2.5))
            for k = 0, cnt - 1 do
                local ang = 2 * math.pi * k / cnt
                local cs, sn = math.cos(ang) * tn, math.sin(ang) * tn
                local pd = unit(d.x + rt.x * cs + up.x * sn, d.y + rt.y * cs + up.y * sn, d.z + rt.z * cs + up.z * sn)
                if pd and reaches(shooter, victim, o, pd, c.range) then total, n = total + (tonumber(c.around) or c.dmg * 0.5), n + 1 end
            end
            if n > 0 then hit(shooter, victim, which, total, DT.medium, o, "shotgun, " .. n .. " pellets") end
            return
        end
        local r = reaches(shooter, victim, o, d, c.range)
        if not r and FF.debug then log("no hit: " .. tostring(FF.why)) end
        if r then
            local react = c.fam == "BulletSparkGenerator" and DT.electric or (c.dmg >= 300 and DT.medium or DT.small)
            hit(shooter, victim, which, c.dmg, react, o, c.fam == "BulletSparkGenerator" and "spark shot" or ("gun " .. tostring(c.wt)))
        end
    end
    for _, gn in ipairs({ "BulletDefaultGenerator", "BulletShotGunGenerator", "BulletSparkGenerator", "RadiateDefaultGenerator",
        "BulletRocketGenerator", "BulletGrenadeGenerator" }) do
        local gt = sdk.find_type_definition("app.ropeway.weapon.generator." .. gn)
        for _, m in ipairs(gt and gt:get_methods() or {}) do
            local pt = m:get_name() == "generateShellProcess" and m:get_num_params() == 1 and m:get_param_types()[1]
            if pt and pt:get_full_name() == "via.mat4" then
                -- (after the redirect hook on the same method: player 2's shot is already aimed)
                FF.hooked = (FF.hooked or "") .. gn .. " "
                sdk.hook(m, function(args)
                    if not on() then return end
                    local own = st.owners[sdk.to_int64(args[2])]
                    if own ~= OWN_P1W and own ~= OWN_HUNKW then return end
                    local ok, err = pcall(FF.on_fire, own, sdk.to_managed_object(args[2]), sdk.to_int64(args[3]), gn)
                    if not ok then log("error " .. tostring(err)) end
                end, function(r) return r end)
            end
        end
    end
    -- (v439) the anti-tank rocket (BulletRocketGenerator: speed 20, no drop) and the grenade
    -- launcher (BulletGrenadeGenerator: speed 50, gravity 8; its rounds' own damage is 0, the
    -- blast does it): the flight is worked out from the shot matrix, a step a frame, until it
    -- meets a wall (terrain ray), the other player or a live enemy; the blast goes off there
    -- when the round would have arrived.
    FF.pending = {}
    local BLAST = { BulletRocketGenerator = { dmg = 3000, r = 5.0, what = "rocket" },
        BulletGrenadeGenerator = { dmg = 1000, r = 3.5, what = "grenade round" } }
    function FF.launch(own, shooter, victim, which, gen, o, d, gn)
        local c = gen_info(gen, gen:get_address())
        local v = tonumber(c.speed) or (gn == "BulletRocketGenerator" and 20 or 50)
        local g = tonumber(c.grav) or 0
        local range = math.min(tonumber(c.range) or 80, 80)
        local a, b = body(victim)
        local spots = enemy_spots()
        local p = o
        local vx, vy, vz = d.x * v, d.y * v, d.z * v
        local dt, travelled, steps = 1 / 60, 0, 0
        local hitp
        while travelled < range and steps < 600 do
            steps = steps + 1
            vy = vy - g * dt
            local n = Vector3f.new(p.x + vx * dt, p.y + vy * dt, p.z + vz * dt)
            local seg = math.sqrt((n.x - p.x) ^ 2 + (n.y - p.y) ^ 2 + (n.z - p.z) ^ 2)
            local sd = unit(n.x - p.x, n.y - p.y, n.z - p.z)
            if sd then
                local tv, dv = ray_seg(p, sd, 0, seg, a, b)
                if dv < 0.3 then hitp = Vector3f.new(p.x + sd.x * tv, p.y + sd.y * tv, p.z + sd.z * tv); break end
                for _, ep in pairs(spots) do
                    for _, h in ipairs({ 0.3, 0.9, 1.5 }) do
                        local q = Vector3f.new(ep.x - p.x, ep.y + h - p.y, ep.z - p.z)
                        local te = dot(q, sd)
                        if te >= 0 and te <= seg then
                            local px, py, pz = q.x - sd.x * te, q.y - sd.y * te, q.z - sd.z * te
                            if px * px + py * py + pz * pz < 0.4 * 0.4 then hitp = Vector3f.new(p.x + sd.x * te, p.y + sd.y * te, p.z + sd.z * te) end
                        end
                    end
                end
                if hitp then break end
                local okr, wall = pcall(cast_ray, p, n)
                if okr and wall then
                    -- (a little back from the wall, so the blast's line of sight starts in the room)
                    hitp = Vector3f.new(wall.x - sd.x * 0.25, wall.y - sd.y * 0.25, wall.z - sd.z * 0.25)
                    break
                end
            end
            travelled = travelled + seg
            p = n
        end
        if hitp == nil then if FF.debug then log(gn .. ": no impact") end return end
        local bl = BLAST[gn]
        FF.pending[#FF.pending + 1] = { at = st.frame + steps, p = hitp, own = own, dmg = bl.dmg, r = bl.r, what = bl.what }
        if FF.debug then log(string.format("%s lands in %d frames", bl.what, steps)) end
    end
    local function blast_at(own, bp, dmg, R, what)
        local shooter, victim, which = sides(own)
        if victim == nil then return end
        local a, b = body(victim)
        local mid = Vector3f.new((a.x + b.x) / 2, (a.y + b.y) / 2, (a.z + b.z) / 2)
        -- (the nearest point of the body: a blast at the feet counts as close)
        local _, dist = ray_seg(bp, Vector3f.new(0, 1, 0), 0, 0, a, b)
        log(string.format("%s went off %.1f m from %s", what, dist, which))
        if dist > R then return end
        local okr, wall = pcall(cast_ray, bp, mid)
        if okr and wall then
            local okr2, wall2 = pcall(cast_ray, bp, Vector3f.new(a.x, a.y + 0.3, a.z))
            if okr2 and wall2 then return end
        end
        local react = dist < 1.5 and DT.exp_l or (dist < 3 and DT.exp_m or DT.exp_s)
        hit(shooter, victim, which, dmg * (1 - 0.7 * dist / R), react, bp, what)
    end
    FF.blast_at = blast_at
    -- thrown grenades: the RigidGrenade the generator makes, followed until it goes off
    local tg = sdk.find_type_definition("app.ropeway.weapon.generator.ThrowGrenadeGenerator")
    -- (NonRT-4) On Non-RT (TDB 66) the <generateShellProcess>b__1_0 lambda can't be hooked
    -- (REFramework: "Failed to hook ... unknown exception"; it resolves onto onRigidInstantiate).
    -- There the grenade is caught where the generator is handed its shell instead:
    -- setRigidObjet(IShell) (the shell's GameObject). RT keeps the lambda.
    if st.NON_RT and tg then
        local function add_nade(gen_ptr, go)
            local own = st.owners[sdk.to_int64(gen_ptr)]
            if own ~= OWN_P1W and own ~= OWN_HUNKW then return end
            if go == nil or FF.nades[go:get_address()] then return end
            local c = gen_info(sdk.to_managed_object(gen_ptr), sdk.to_int64(gen_ptr))
            FF.nades[go:get_address()] = { go = go:add_ref(), own = own, wt = c.wt, t = st.frame }
            FF.nade_seen = (FF.nade_seen or 0) + 1
        end
        local m = tg:get_method("setRigidObjet")
        if m then
            sdk.hook(m, function(args)
                if not on() then return end
                pcall(function()
                    local shell = sdk.to_managed_object(args[3])
                    local go = shell and shell:call("get_GameObject")
                    add_nade(args[2], go)
                end)
            end, function(r) return r end)
            FF.hooked = (FF.hooked or "") .. "setRigidObjet "
        end
    end
    for _, m in ipairs((not st.NON_RT) and tg and tg:get_methods() or {}) do
        if m:get_name():find("^<generateShellProcess>") and m:get_num_params() == 1 then
            sdk.hook(m, function(args)
                if not on() then return end
                local own = st.owners[sdk.to_int64(args[2])]
                if own ~= OWN_P1W and own ~= OWN_HUNKW then return end
                pcall(function()
                    local go = sdk.to_managed_object(args[3])
                    if go == nil then return end
                    local c = gen_info(sdk.to_managed_object(args[2]), sdk.to_int64(args[2]))
                    FF.nades[go:get_address()] = { go = go:add_ref(), own = own, wt = c.wt, t = st.frame }
                end)
            end, function(r) return r end)
            FF.hooked = (FF.hooked or "") .. "ThrowGrenade "
        end
    end
    function FF.blast(g)
        local shooter, victim, which = sides(g.own)
        if victim == nil then return end
        local a, b = body(victim)
        local mid = Vector3f.new((a.x + b.x) / 2, (a.y + b.y) / 2, (a.z + b.z) / 2)
        local bp = Vector3f.new(g.p.x, g.p.y + 0.3, g.p.z)
        local dist = math.sqrt((mid.x - bp.x) ^ 2 + (mid.y - bp.y) ^ 2 + (mid.z - bp.z) ^ 2)
        local flash = g.wt == 66
        local R = flash and 8 or 4.5
        log(string.format("grenade (wt %s) went off %.1f m from %s", tostring(g.wt), dist, which))
        if dist > R then return end
        local okr, wall = pcall(cast_ray, bp, mid)
        if okr and wall then return end
        if flash then hit(shooter, victim, which, 0, DT.flash, bp, "flash grenade"); return end
        local react = dist < 1.5 and DT.exp_l or (dist < 3 and DT.exp_m or DT.exp_s)
        hit(shooter, victim, which, 1500 * (1 - 0.7 * dist / R), react, bp, "grenade")
    end
    local KNIFE = { { own = OWN_P1W, key = "p1" }, { own = OWN_HUNKW, key = "p2" } }
    function FF.tick()
        if not on() then
            if next(FF.nades) then FF.nades = {} end
            if #FF.pending > 0 then FF.pending = {} end
            return
        end
        -- rockets / grenade rounds landing
        for i = #FF.pending, 1, -1 do
            local pb = FF.pending[i]
            if st.frame >= pb.at then
                table.remove(FF.pending, i)
                pcall(blast_at, pb.own, pb.p, pb.dmg, pb.r, pb.what)
            end
        end
        -- knives: once a swing, the other player close in front
        for _, sd in ipairs(KNIFE) do
            local shooter, victim, which = sides(sd.own)
            local k = FF.kn[sd.key]
            local cond = shooter and comp(shooter, SC)
            local act = cond ~= nil and safe(function() return cond:call("get_IsKnifeAction") end) == true
            -- (IsKnifeAction is any sub-weapon action: a grenade throw too. The knife only.)
            if act and not k.on then
                local inv = comp(shooter, "app.ropeway.survivor.Inventory")
                local swt = inv and safe(function() return inv:call("get_SubSlot"):call("get_WeaponType") end)
                k.on, k.done, k.t = true, swt == 65 or swt == 66, st.frame
            end
            if not act then k.on = false end
            if act and not k.done and st.frame - k.t >= 4 and victim then
                local sxf = shooter:call("get_Transform")
                local sp, vp = sxf:call("get_Position"), victim:call("get_Transform"):call("get_Position")
                local dx, dz = vp.x - sp.x, vp.z - sp.z
                local dist = math.sqrt(dx * dx + dz * dz)
                if dist < 1.35 and math.abs(vp.y - sp.y) < 1.2 then
                    local f = sxf:call("get_Rotation") * Vector3f.new(0, 0, 1)
                    local fl = math.max(0.01, math.sqrt(f.x * f.x + f.z * f.z))
                    if dist < 0.3 or (f.x * dx + f.z * dz) / (fl * dist) > 0.34 then
                        local okr, wall = pcall(cast_ray, Vector3f.new(sp.x, sp.y + 1.0, sp.z), Vector3f.new(vp.x, vp.y + 1.0, vp.z))
                        if not (okr and wall) then
                            k.done = true
                            hit(shooter, victim, which, 150, DT.small, sp, "knife")
                        end
                    end
                end
            end
        end
        -- grenades in the air
        for addr, g in pairs(FF.nades) do
            local valid = safe(function() return g.go:call("get_Valid") end) == true
            if valid then
                local p = safe(function() return g.go:call("get_Transform"):call("get_Position") end)
                if p then g.p = p end
                if st.frame - g.t > 900 then FF.nades[addr] = nil end
            else
                FF.nades[addr] = nil
                if g.p then pcall(FF.blast, g) end
            end
        end
    end
    re.on_frame(function() local ok, err = pcall(FF.tick); if not ok then log("tick error " .. tostring(err)) end end)
end)()

-- Player 2's shots shake / kick the shared camera as if player 1 fired. While one of
-- player 2's components is running (his gun firing), the camera's recoil and shake
-- entries are skipped.
;(function()
    local skipped = false
    for _, spec in ipairs({ { "app.ropeway.camera.CameraSystem", "entryCameraShake" }, { "app.ropeway.camera.CameraSystem", "entryCameraRecoil" },
        { "app.ropeway.camera.PlayerCameraController", "syncRecoil" }, { "app.ropeway.camera.PlayerCameraController", "entryRecoil" } }) do
        local td = sdk.find_type_definition(spec[1])
        for _, m in ipairs(td and td:get_methods() or {}) do
            if m:get_name() == spec[2] then
                local rt = m:get_return_type()
                local void = rt == nil or rt:get_full_name() == "System.Void"
                sdk.hook(m, function(args)
                    skipped = false
                    if st.hunk ~= nil and is_hunk_owner((current_owner())) then
                        skipped = true
                        return sdk.PreHookResult.SKIP_ORIGINAL
                    end
                end, function(r)
                    if skipped and not void then skipped = false; return sdk.to_ptr(0) end
                    skipped = false
                    return r
                end)
            end
        end
    end
    -- while player 1 aims, player 2's gun hands the aiming camera a fresh recoil kick
    -- (a CameraRecoilParam built during player 2's update and stored on the camera). Mark
    -- the ones built for player 2 and zero their kick before the camera applies it.
    local from_p2 = {}
    local rt = sdk.find_type_definition("app.ropeway.camera.CameraRecoilParam")
    for _, m in ipairs(rt and rt:get_methods() or {}) do
        if m:get_name() == ".ctor" then
            sdk.hook(m, function(args)
                local a = sdk.to_int64(args[2]) & 0xFFFFFFFFFFFF
                if st.hunk ~= nil and is_hunk_owner((current_owner())) then
                    from_p2[a] = st.frame
                else
                    from_p2[a] = nil   -- reused for player 1's own kick
                end
            end, function(r) return r end)
        end
    end
    local ct = sdk.find_type_definition("app.ropeway.camera.PlayerCameraController")
    for _, m in ipairs(ct and ct:get_methods() or {}) do
        if m:get_name() == "updateRecoil" then
            sdk.hook(m, function(args)
                if next(from_p2) == nil then return end
                pcall(function()
                    local rp = sdk.to_managed_object(args[2]):get_field("RecoilParam")
                    if rp and from_p2[rp:get_address() & 0xFFFFFFFFFFFF] then
                        rp:set_field("Yaw", 0.0)
                        rp:set_field("Pitch", 0.0)
                    end
                end)
                -- forget old ones (the game reuses the memory)
                if st.frame % 120 == 0 then
                    for a, f in pairs(from_p2) do if st.frame - f > 300 then from_p2[a] = nil end end
                end
            end, function(r) return r end)
        end
    end
end)()

-- Minigun tracers: the minigun's muzzle effect (the "gatling" element of the shared
-- muzzle effect) includes tracer streaks along the barrel, which on HUNK points a little
-- off the crosshair. HUNK's minigun plays the machine-gun muzzle flash instead: same
-- kind of flash, no streaks.
local tracer = { gun = nil, done = nil }
st.minigun_flash = "smg"   -- dev: "orig" puts the game's gatling flash back
local function update_tracers()
    if st.hunk == nil then return end
    local gun = tracer.gun
    if gun == nil or not safe(function() return gun:call("get_Valid") end) then
        gun = nil
        tracer.done, tracer.orig = nil, nil
        local c = safe(function() return st.hunk:call("get_Transform"):call("get_Child") end)
        local guard = 0
        while c and guard < 80 do
            guard = guard + 1
            local go = safe(function() return c:call("get_GameObject") end)
            if go and safe(function() return go:call("get_Name") end) == "wp4700" then gun = go break end
            c = safe(function() return c:call("get_Next") end)
        end
        tracer.gun = gun and gun:add_ref() or nil
        if gun == nil then return end
    end
    if tracer.done == st.minigun_flash then return end
    local epv = comp(gun, "app.ropeway.effect.script.EPVExpertMuzzleFlashCustom")
    if epv == nil then return end
    pcall(function()
        local play = epv:get_field("PlayElements")
        local elems = epv:get_field("DataList"):call("get_Item", 0):get_field("Elements")
        if tracer.orig == nil then tracer.orig = play:call("get_Item", 0):add_ref() end
        local pick = tracer.orig
        if st.minigun_flash == "smg" then
            for i = 0, elems:call("get_Count") - 1 do
                local e = elems:call("get_Item", i)
                if e:get_field("TargetID") == "マシンガン" then pick = e break end   -- "machine gun"
            end
        end
        play:call("set_Item", 0, pick)
        if not epv:call("get_Enabled") then epv:call("set_Enabled", true) end   -- older versions switched it off
        tracer.done = st.minigun_flash
    end)
end

-- The flamethrower's flame stream only restarts after the game ends the previous one,
-- which never happens for HUNK. End it once he has stopped firing for a moment.
local flame = { last = {}, gens = {} }
do
    local td = sdk.find_type_definition("app.ropeway.weapon.generator.RadiateDefaultGenerator")
    local m = td and td:get_method("generateShellProcess")
    if m then
        sdk.hook(m, function(args)
            -- any new flame (HUNK's or Leon's) gets back the lights switched off after the last one
            if flame.lights_off then
                for _, l in ipairs(flame.lights_off) do pcall(l.call, l, "set_Enabled", true) end
                flame.lights_off = nil
            end
            local addr = sdk.to_int64(args[2])
            if st.hunk and st.owners[addr] == OWN_HUNKW then
                if flame.gens[addr] == nil then flame.gens[addr] = sdk.to_managed_object(args[2]):add_ref() end
                flame.last[addr] = st.frame
                if st.frame > (flame.firing_until or -1) then flame.once_done = false end   -- a new burst
                flame.firing_until = st.frame + 14   -- the game pulses this every 12 frames while firing
            end
        end, function(r) return r end)
    end
    -- The flame stream's shell checks the trigger itself every frame and sees P1's (idle)
    -- trigger, so it only shows a flash on each pulse. Keep it lit while HUNK is firing.
    local rd = sdk.find_type_definition("app.ropeway.weapon.shell.RadiateDefault")
    local rel = rd and rd:get_method("onReleaseTrigger")
    if rel then
        sdk.hook(rel, function(args)
            if st.hunk == nil or st.frame > (flame.firing_until or -1) then return end
            local skip = false
            pcall(function()
                local gun = sdk.to_managed_object(args[2]):get_field("GunComp")
                skip = gun ~= nil and st.owners[gun:get_address()] == OWN_HUNKW
            end)
            if skip then return sdk.PreHookResult.SKIP_ORIGINAL end
        end, function(r) return r end)
    end
    -- each pulse would also start a fresh flame effect (and light) on top of the burning
    -- one; those never get cleaned up, so only the first pull of a burst goes through
    local function hunk_shell(this)
        local mine = false
        pcall(function()
            local gun = sdk.to_managed_object(this):get_field("GunComp")
            mine = gun ~= nil and st.owners[gun:get_address()] == OWN_HUNKW
        end)
        return mine
    end
    local pm = rd and rd:get_method("onTriggerOnce")
    if pm then
        sdk.hook(pm, function(args)
            if st.hunk == nil or not hunk_shell(args[2]) then return end
            if flame.once_done then return sdk.PreHookResult.SKIP_ORIGINAL end
            flame.once_done = true
        end, function(r) return r end)
    end
end
local function forget_weapons()
    gen_info = {}
    tracer.gun, tracer.orig, tracer.done = nil, nil, nil
    flame.last, flame.gens = {}, {}
end
-- lights the flame effect leaves behind: HUNK's finished flame effects stay alive (held), and
-- their point lights keep glowing. Hiding the object isn't enough; the light itself is switched
-- off, and switched back on when the next flame starts (hook above).
-- finish = true: the flame effects themselves (fire, heat haze, the screen tint and blur near
-- them) are told to finish and fade out, the way they do when Leon lets go of the trigger
local function flame_lights_off(finish)
    local sc = sdk.call_native_func(sdk.get_native_singleton("via.SceneManager"), sdk.find_type_definition("via.SceneManager"), "get_CurrentScene")
    local root = sc and safe(function() return sc:call("findGameObject(System.String)", "RadiateSpread_RingBufferController") end)
    if root == nil or st.hunk == nil then return end
    local hunk_addr = st.hunk:get_address()
    local off = flame.lights_off or {}
    local el = safe(function() return root:call("get_Transform"):call("get_Child") end)
    local guard = 0
    while el and guard < 64 do
        guard = guard + 1
        local ego = safe(function() return el:call("get_GameObject") end)
        local hc = ego and comp(ego, "app.Collision.HitController")
        local owner = hc and safe(function() return hc:call("get_AttackOwner") end)
        if owner and owner:get_address() == hunk_addr then
            local fx = safe(function() return el:call("get_Child") end)
            local g2 = 0
            while fx and g2 < 32 do
                g2 = g2 + 1
                if finish then
                    local fgo = safe(function() return fx:call("get_GameObject") end)
                    local ep = fgo and safe(function() return fgo:call("getComponent(System.Type)", sdk.typeof("via.effect.EffectPlayer")) end)
                    local state = ep and safe(function() return ep:call("get_State") end)
                    if state == 1 or state == 2 then pcall(ep.call, ep, "set_Action", 3) end   -- Start/Running -> Finish
                end
                local lc = safe(function() return fx:call("get_Child") end)
                local g3 = 0
                while lc and g3 < 8 do
                    g3 = g3 + 1
                    local lgo = safe(function() return lc:call("get_GameObject") end)
                    local l = lgo and safe(function() return lgo:call("getComponent(System.Type)", sdk.typeof("via.render.PointLight")) end)
                    if not finish and l and safe(function() return l:call("get_Enabled") end) then
                        pcall(l.call, l, "set_Enabled", false)
                        off[#off + 1] = l:add_ref()
                    end
                    lc = safe(function() return lc:call("get_Next") end)
                end
                fx = safe(function() return fx:call("get_Next") end)
            end
        end
        el = safe(function() return el:call("get_Next") end)
    end
    if #off > 0 then flame.lights_off = off end
end
local function hide_flame_lights(g)
    local so = safe(function() return g:get_field("ShellObject") end)
    if so == nil then return end
    local function walk(xf, depth)
        local c = safe(function() return xf:call("get_Child") end)
        local guard = 0
        while c and guard < 200 do
            guard = guard + 1
            local go = safe(function() return c:call("get_GameObject") end)
            local name = go and safe(function() return go:call("get_Name") end)
            if name and name:find("^PointLight") then
                if safe(function() return go:call("get_DrawSelf") end) then pcall(go.call, go, "set_DrawSelf", false) end
            elseif depth < 3 then
                walk(c, depth + 1)
            end
            c = safe(function() return c:call("get_Next") end)
        end
    end
    walk(so:call("get_Transform"), 0)
end
local function update_flame()
    for addr, last in pairs(flame.last) do
        local g = flame.gens[addr]
        local idle = st.frame - last
        if idle > 20 and flame.finished ~= last then
            flame.finished = last
            if g and safe(function() return g:get_field("isEmit") end) then
                pcall(g.call, g, "TriggerFinish")
            end
            pcall(flame_lights_off, true)
        elseif idle > 90 then   -- the flame has died down by now
            if g then pcall(hide_flame_lights, g) end
            pcall(flame_lights_off)
            flame.last[addr] = nil
        end
    end
end

-- Weapon -----------------------------------------------------------------------

local SETSLOT_SIG = "setSlot(System.Int32, app.ropeway.EquipmentDefine.WeaponType, app.ropeway.EquipmentDefine.WeaponParts, app.ropeway.gamemastering.Item.ID, System.Int32, app.ropeway.gamemastering.InventoryManager.ItemExData)"

-- HUNK loadout ------------------------------------------------------------------
-- Inventory slots (HUNK has 8): 0/1/5 = d-pad up/left/right guns, 2 = knife, 6 = throwable,
-- 3/4/7 = reserve ammo for the chosen guns. Shortcut enum: Up 0, Down 1, Left 2, Right 3.
-- Weapon list from the in-game probe (every one equips and is held in the right hand).
-- num = full magazine, ammo = Item.ID of its reserve rounds (nil = none).
local WEAPONS = {
    { wt = 7,  num = 16,   ammo = 15, name = "MUP pistol" },
    { wt = 1,  num = 12,   ammo = 15, name = "Matilda" },
    { wt = 2,  num = 7,    ammo = 15, name = "M19" },
    { wt = 3,  num = 13,   ammo = 15, name = "JMB Hp3" },
    { wt = 8,  num = 9,    ammo = 15, name = "Broom Hc" },
    { wt = 4,  num = 6,    ammo = 26, name = "Quickdraw Army" },
    { wt = 9,  num = 5,    ammo = 27, name = "SLS 60" },
    -- DLC Samurai Edges (wp7000-wp7030): handgun ammo, 15 rounds
    { wt = 82, num = 15,   ammo = 15, name = "Samurai Edge (Original)" },
    { wt = 83, num = 15,   ammo = 15, name = "Samurai Edge (Chris)" },
    { wt = 84, num = 15,   ammo = 15, name = "Samurai Edge (Jill)" },
    { wt = 85, num = 15,   ammo = 15, name = "Samurai Edge (Albert)" },
    { wt = 31, num = 7,    ammo = 18, name = "Lightning Hawk" },
    { wt = 11, num = 4,    ammo = 16, name = "W-870 shotgun" },
    { wt = 21, num = 24,   ammo = 17, name = "MQ 11" },
    { wt = 23, num = 32,   ammo = 17, name = "LE 5" },
    { wt = 42, num = 1,    ammo = 22, name = "GM 79 grenade launcher" },
    { wt = 43, num = 400,  ammo = 25, name = "Chemical flamethrower" },
    { wt = 44, num = 7,    ammo = 24, name = "Spark Shot" },
    { wt = 45, num = 1,    ammo = nil, name = "ATM-4 rocket launcher" },
    { wt = 49, num = 4,    ammo = 28, name = "Anti-tank rocket" },
    { wt = 50, num = 1000, ammo = 29, name = "Minigun" },
}
local WEAPON_BY_WT = {}
for _, w in ipairs(WEAPONS) do WEAPON_BY_WT[w.wt] = w end
local THROWABLES = { { wt = 66, name = "Flash grenade" }, { wt = 65, name = "Hand grenade" } }
local MAIN_SLOTS = {   -- d-pad direction -> inventory slot / shortcut / setting
    { key = "weapon_up",    slot = 0, shortcut = 0, label = "D-pad up" },
    { key = "weapon_left",  slot = 1, shortcut = 2, label = "D-pad left" },
    { key = "weapon_right", slot = 5, shortcut = 3, label = "D-pad right" },
}
local KNIFE_SLOT, FLASH_SLOT = 2, 6
local AMMO_SLOTS = { 3, 4, 7 }
local SETITEM_SIG = "setSlot(System.Int32, app.ropeway.gamemastering.Item.ID, System.Int32, app.ropeway.gamemastering.InventoryManager.PrimitiveItem, app.ropeway.gamemastering.InventoryManager.ItemExData)"
st.default_weapon_slot = 1   -- start on the d-pad left gun

local function throwable_name(wt)
    for _, t in ipairs(THROWABLES) do if t.wt == wt then return t.name end end
    return "grenade"
end

-- the current loadout, built from the settings (bad or duplicate values fall back to defaults)
local LOADOUT, AMMO = {}, {}
local function build_loadout()
    LOADOUT, AMMO = {}, {}
    local used, ammo_seen = {}, {}
    local defaults = { weapon_up = 11, weapon_left = 7, weapon_right = 23 }
    for _, m in ipairs(MAIN_SLOTS) do
        local w = WEAPON_BY_WT[st[m.key]]
        if w == nil or used[w.wt] then w = WEAPON_BY_WT[defaults[m.key]] end
        if used[w.wt] then   -- default already taken too: first free weapon
            for _, c in ipairs(WEAPONS) do if not used[c.wt] then w = c; break end end
        end
        st[m.key] = w.wt
        used[w.wt] = true
        LOADOUT[#LOADOUT + 1] = { slot = m.slot, wt = w.wt, parts = 0, bullet = w.ammo or 0, num = w.num, shortcut = m.shortcut, name = w.name }
        if w.ammo and not ammo_seen[w.ammo] and #AMMO < #AMMO_SLOTS then
            ammo_seen[w.ammo] = true
            AMMO[#AMMO + 1] = { slot = AMMO_SLOTS[#AMMO + 1], item = w.ammo, num = 999, name = w.name .. " ammo" }
        end
    end
    LOADOUT[#LOADOUT + 1] = { slot = KNIFE_SLOT, wt = 46, parts = 0, num = 1000, sub = true, name = "combat knife" }
    if st.throwable ~= 65 and st.throwable ~= 66 then st.throwable = 66 end
    LOADOUT[#LOADOUT + 1] = { slot = FLASH_SLOT, wt = st.throwable, parts = 0, num = 3, name = throwable_name(st.throwable) }
end
build_loadout()

-- does HUNK's inventory already hold this loadout? (used after a script reset)
has_loadout = function(hinv)
    for _, w in ipairs(LOADOUT) do
        if w.shortcut ~= nil then
            local sl = safe(function() return hinv:call("getSlot(System.Int32)", w.slot) end)
            if sl == nil or safe(function() return sl:call("get_WeaponType") end) ~= w.wt then return false end
        end
    end
    return true
end

-- A player 2 made after the game has loaded a save (game over and Continue, loading a save,
-- our own respawn after a load screen) gets an Inventory with no slots at all (_Slots empty):
-- the game fills inventories from the save while loading, and player 2 wasn't there. setSlot
-- then quietly does nothing (no weapons). An empty inventory.Data with player 2's
-- SurvivorType, given to loadData, makes the slots (8 + the box's 12).
local function ensure_inventory(hinv)
    local slots = safe(function() return hinv:get_field("_Slots") end)
    local n = slots and safe(function() return slots:call("get_Count") end)
    if n == nil or n > 0 then return true end
    local ok = pcall(function()
        local d = sdk.create_instance("app.ropeway.inventory.Data"):add_ref()
        d:call(".ctor")
        d:call("set_CurrentSlotSize", hinv:get_field("_CurrentSlotSize") or 8)
        local cond = hinv:get_field("<Condition>k__BackingField")
        local stype = cond and cond:call("get_SurvivorType")
        if stype then d:call("set_SurvivorType", stype) end
        hinv:call("loadData", d)
    end)
    n = slots and safe(function() return slots:call("get_Count") end)
    if ok and n and n > 0 then say("Player 2's inventory set up") end
    return n ~= nil and n > 0
end
st.ensure_inventory = ensure_inventory

-- equip_slot: slot to hold afterwards (default: the d-pad left gun)
local function give_loadout(equip_slot, quiet)
    if st.hunk == nil then return end
    if not st.infinite_ammo and st.p2inv then
        -- player 2's own inventory: the weapon settings only shape his starter kit
        if st.loadout_given then build_loadout(); return end
        return st.p2inv.provision(quiet)
    end
    local hinv = comp(st.hunk, "app.ropeway.survivor.Inventory")
    if hinv == nil then return end
    if not ensure_inventory(hinv) then st.loadout_given = false; return end
    build_loadout()
    local log = {}
    for _, w in ipairs(LOADOUT) do
        -- the loaded round type matters: the GM 79 fires nothing without one
        local ok = pcall(hinv.call, hinv, SETSLOT_SIG, w.slot, w.wt, w.parts, w.bullet or 0, w.num, nil)
        local ok2 = true
        if w.sub or w.wt == 65 or w.wt == 66 then   -- knife / grenades: LB + d-pad (the game picks the direction)
            ok2 = pcall(hinv.call, hinv, "setSubShortcutSlot(System.Int32, System.Boolean)", w.slot, true)
        elseif w.shortcut ~= nil then
            ok2 = pcall(hinv.call, hinv, "setShortcutSlot(System.Int32, app.ropeway.EquipmentDefine.Shortcut)", w.slot, w.shortcut)
        end
        log[#log + 1] = w.name .. (ok and "" or " (slot failed)") .. (ok2 and "" or " (shortcut failed)")
    end
    -- reserve ammo for the chosen guns; unused ammo slots are emptied
    local filled = {}
    for _, a in ipairs(AMMO) do
        local ok = pcall(hinv.call, hinv, SETITEM_SIG, a.slot, a.item, a.num, nil, nil)
        if not ok then log[#log + 1] = a.name .. " (failed)" end
        filled[a.slot] = true
    end
    for _, s in ipairs(AMMO_SLOTS) do
        if not filled[s] then pcall(hinv.call, hinv, SETSLOT_SIG, s, -1, 0, 0, -1, nil) end
    end
    if equip_slot ~= false then pcall(hinv.call, hinv, "equipSlot(System.Int32)", equip_slot or st.default_weapon_slot) end
    st.loadout_given = true
    st.hunk_weapon = nil
    if not quiet then say("HUNK is ready") end
    return log
end

-- Rookie chosen: whatever player 2 carried goes and the configured loadout (Weapons
-- settings) comes in; Infinite ammo keeps it full from then on
function st.give_infinite_kit()
    if st.hunk == nil then return end
    local hinv = comp(st.hunk, "app.ropeway.survivor.Inventory")
    if hinv == nil then return end
    local n = safe(function() return hinv:get_field("_Slots"):call("get_Count") end) or 0
    for i = 0, n - 1 do pcall(hinv.call, hinv, SETSLOT_SIG, i, -1, 0, 0, -1, nil) end
    st.loadout_given = false
    give_loadout(nil, true)
    if st.anim and st.anim.check then pcall(st.anim.check) end
end

-- keep ammo stacks and knife durability topped up (HUNK reloads from his own stacks)
local function refill_ammo()
    if st.hunk == nil then return end
    local hinv = comp(st.hunk, "app.ropeway.survivor.Inventory")
    if hinv == nil then return end
    local function top(slot_index)
        local sl = safe(function() return hinv:call("getSlot(System.Int32)", slot_index) end)
        if sl == nil then return end
        local max = safe(function() return sl:call("get_MaxNumber") end)
        local n = safe(function() return sl:call("get_Number") end)
        if max and max > 0 and n and n < max then safe(function() sl:call("set_Number", max) end) end
    end
    for _, w in ipairs(LOADOUT) do
        local sl = safe(function() return hinv:call("getSlot(System.Int32)", w.slot) end)
        if sl and safe(function() return sl:call("get_WeaponType") end) == w.wt then
            top(w.slot)   -- magazines stay full
            -- weapons given by an older version may have no round type loaded (GM 79 fires nothing)
            if w.bullet and w.bullet ~= 0 and safe(function() return sl:call("get_BulletID") end) == 0 then
                pcall(sl.call, sl, "set_BulletID", w.bullet)
            end
        end
    end
    for _, a in ipairs(AMMO) do top(a.slot) end
end

-- Player 2's own inventory (Infinite ammo off) ----------------------------------------------
-- HUNK has a real game inventory (app.ropeway.survivor.Inventory: 8 slots, the same Slot objects
-- as Leon's; he reloads from his own stacks). With Infinite ammo on, the mod fills it with the
-- configured loadout and keeps it topped up (as before). With it off, it is player 2's real
-- inventory: rounds are spent and nothing is refilled. The game neither saves player 2 nor
-- keeps his GameObject (area changes, loads and game overs make a new HUNK), so the mod keeps
-- what he carries (reunited_p2_inventory.json):
--  * live: what he carries now (read every half second, written when it changes); put back
--    whenever a new HUNK is made;
--  * saves[index]: a copy of live taken each time the game writes a save (manual, autosave,
--    checkpoint), under that save file's index; it becomes live when that save is loaded, so
--    an older save gives player 2 what he had then (no duplicates, nothing lost).
-- A record is only used in the playthrough it came from (MainFlowManager SaveGUID) and never
-- from "the future" (its play time past the game clock: a new game). No usable record: the
-- loadout of the difficulty (st.p2_difficulty):
--  * "boy"    (unused since Rookie became Infinite ammo; kept for the item box
--             station) the Weapons settings (three guns, knife, grenades) with two
--             magazines of spare rounds each and a support item; at an item box he can change
--             any of his guns, his grenades and support item and restock (st.p2inv station);
--  * "friend" Operative: HUNK's gear from The 4th Survivor (LE 5, W-870, Lightning Hawk,
--             MUP, knife, 3 hand + 3 flash grenades, 100 SMG rounds, 6 shells, 6 magnum
--             rounds, a first aid spray, three mixed herbs; 20 slots);
--  * "war"    Veteran: a knife and a Matilda (one magazine).
st.p2_difficulty = "friend"
st.p2_support = 2   -- Rookie's support item (Item.ID: 1 first aid spray, 2 green herb, 5 G+G herb)
;(function()
    local P = { file = "reunited_p2_inventory.json", data = { live = nil, saves = {} }, hold = false, log = {} }
    st.p2inv = P
    local SC_SIG = "getSlot(app.ropeway.EquipmentDefine.Shortcut)"
    local function note(t)
        P.log[#P.log + 1] = string.format("%d %s", st.frame or 0, t)
        if #P.log > 40 then table.remove(P.log, 1) end
        log.info("[reunited] p2 inventory: " .. t)
    end
    local function clock_s()
        local gc = sdk.get_managed_singleton("app.ropeway.GameClock")
        local us = gc and safe(function() return gc:call("get_GameElapsedTime") end)
        return us and math.floor(us / 1000000) or nil
    end
    local function save_guid()
        local mf = sdk.get_managed_singleton("app.ropeway.gamemastering.MainFlowManager")
        -- (v398: from the Guid's fields. ToString without "()" never ran - nil, and a REFramework
        -- warning twice a second - and ToString() on the copy gives an address-like string)
        return mf and safe(function()
            local g = mf:call("get_SaveGUID")
            local a, b, c = g:get_field("mData1"), g:get_field("mData2"), g:get_field("mData3")
            if a == nil then return nil end
            return string.format("%s-%s-%s", tostring(a), tostring(b), tostring(c))
        end) or nil
    end
    local function copy(t)
        if type(t) ~= "table" then return t end
        local c = {}
        for k, v in pairs(t) do c[k] = copy(v) end
        return c
    end
    do   -- the file
        local ok, t = pcall(json.load_file, P.file)
        if ok and type(t) == "table" then
            P.data.live = type(t.live) == "table" and t.live or nil
            P.data.saves = type(t.saves) == "table" and t.saves or {}
        end
    end
    local function write()
        local ok, s = pcall(json.dump_string, P.data)
        if ok and s == P.last_written then return end
        if pcall(json.dump_file, P.file, P.data) then P.last_written = ok and s or nil end
    end
    local function slot_index(s) return s and safe(function() return s:call("get_Index") end) or nil end
    local function hunk_inv()
        return st.hunk and comp(st.hunk, "app.ropeway.survivor.Inventory") or nil
    end
    -- Slots are addressed by their Index (the grid position getSlot / setSlot / removeSlot /
    -- equipSlot use), not by their place in the _Slots list: the game reorders that list
    -- (player 1's knife can be list item 6 with Index 5). index_map: Index -> Slot
    local function index_map(inv)
        local map = {}
        local slots = inv and safe(function() return inv:get_field("_Slots") end)
        local n = slots and safe(function() return slots:call("get_Count") end) or 0
        for p = 0, n - 1 do
            local sl = safe(function() return slots:call("get_Item", p) end)
            local idx = sl and safe(function() return sl:call("get_Index") end)
            if idx and idx >= 0 and map[idx] == nil then map[idx] = sl end
        end
        return map, n
    end
    P.index_map = index_map
    local function slot_at(inv, i) return safe(function() return inv:call("getSlot(System.Int32)", i) end) end
    P.slot_at = slot_at
    -- player 2's list can end up with a slot that has no Index or two slots claiming the same
    -- one (seen after a grenade slot ran out), and older versions could leave junk items (the
    -- minigun's internal ammo id) in it. Junk is cleared; a broken list is rebuilt: what he
    -- carries (by Index, each slot once) goes into a fresh set of slots (loadData)
    local function junk_item(id)
        if id == nil or id <= 0 then return false end
        local n = safe(function() return sdk.get_managed_singleton("app.ropeway.gamemastering.ItemManager"):call("getItemName", id) end)
        return n == nil or tostring(n):find("Invalid", 1, true) ~= nil
    end
    function P.repair(inv)
        if inv == nil or P.repairing then return 0 end
        local slots = safe(function() return inv:get_field("_Slots") end)
        local n = slots and safe(function() return slots:call("get_Count") end) or 0
        if n == 0 then return 0 end
        local seen, bad = {}, 0
        for p = 0, n - 1 do
            local sl = slots:call("get_Item", p)
            local idx = safe(function() return sl:call("get_Index") end)
            if idx == nil or idx < 0 or idx >= n or seen[idx] then bad = bad + 1 else seen[idx] = true end
            if junk_item(safe(function() return sl:call("get_ItemID") end)) and idx and idx >= 0 then
                pcall(inv.call, inv, SETSLOT_SIG, idx, -1, 0, 0, -1, nil)
                P.log[#P.log + 1] = "cleared a junk item in slot " .. idx
            end
        end
        if bad == 0 then return P.fix_layout(inv) end
        P.repairing = true
        pcall(function()
            local rec = P.capture(inv)
            local d = sdk.create_instance("app.ropeway.inventory.Data"):add_ref()
            d:call(".ctor")
            d:call("set_CurrentSlotSize", (rec and rec.size) or 8)
            local cond = inv:get_field("<Condition>k__BackingField")
            local stype = cond and cond:call("get_SurvivorType")
            if stype then d:call("set_SurvivorType", stype) end
            inv:call("loadData", d)
            if rec then P.apply(inv, rec) end
        end)
        P.repairing = false
        P.log[#P.log + 1] = "rebuilt the slot list (" .. bad .. " bad)"
        return bad
    end
    -- two-slot items (Slot.IsFatSlot: the LE 5, ...) cover the slot to their right
    -- (Inventory.isDeadSlot); an item filed there (older kits / versions) is moved to a free
    -- slot, and so is a two-slot item in the last column
    function P.fix_layout(inv)
        if inv == nil or P.repairing then return 0 end
        local size = safe(function() return inv:get_field("_CurrentSlotSize") end) or 8
        local map = index_map(inv)
        local function filled(i) local sl = map[i]; return sl and ((sl:call("get_ItemID") or 0) > 0 or (sl:call("get_WeaponType") or -1) > 0) end
        local function dead(i) return safe(function() return inv:call("isDeadSlot", i) end) == true end
        local function fat(i) return map[i] and safe(function() return map[i]:call("get_IsFatSlot") end) == true end
        local moved = 0
        for i = 0, size - 1 do
            local edge = fat(i) and (i % 4 == 3 or i + 1 >= size)
            if filled(i) and (dead(i) or edge) then
                local sl = map[i]
                local wt, id = sl:call("get_WeaponType") or -1, sl:call("get_ItemID") or 0
                local parts, bullet, num = sl:call("get_WeaponParts") or 0, sl:call("get_BulletID") or 0, sl:call("get_Number") or 1
                local isfat = fat(i)
                local to
                for j = 0, size - 1 do
                    if j ~= i and not filled(j) and not dead(j) then
                        if not isfat then to = j; break end
                        if j % 4 ~= 3 and j + 1 < size and not filled(j + 1) and j + 1 ~= i then to = j; break end
                    end
                end
                if to then
                    pcall(inv.call, inv, SETSLOT_SIG, i, -1, 0, 0, -1, nil)
                    if wt > 0 then pcall(inv.call, inv, SETSLOT_SIG, to, wt, parts, bullet, num, nil)
                    else pcall(inv.call, inv, SETITEM_SIG, to, id, num, nil, nil) end
                    moved = moved + 1
                    map = index_map(inv)
                end
            end
        end
        if moved > 0 then
            P.log[#P.log + 1] = "moved " .. moved .. " item(s) out of covered slots"
            local h = hunk_inv()
            if h and h:get_address() == inv:get_address() then pcall(P.fix_shortcuts, inv) end   -- (player 2's d-pad rules only)
        end
        return moved
    end
    function P.count(hinv)
        local slots = safe(function() return hinv:get_field("_Slots") end)
        return slots and safe(function() return slots:call("get_Count") end) or 0
    end
    -- what player 2 carries now
    function P.capture(hinv)
        local slots = hinv:get_field("_Slots")
        local n = slots and slots:call("get_Count") or 0
        if n == 0 then return nil end
        local rec = { slots = {}, shortcuts = {}, guid = save_guid(), t = clock_s(), size = safe(function() return hinv:get_field("_CurrentSlotSize") end) }
        local map = index_map(hinv)
        for i = 0, n - 1 do
            local sl = map[i]
            local item = sl and safe(function() return sl:call("get_ItemID") end) or 0
            if sl == nil then item = 0 end
            local wt = sl and safe(function() return sl:call("get_WeaponType") end) or -1
            if item > 0 or wt > 0 then
                rec.slots[#rec.slots + 1] = { i = i, item = item, wt = wt, parts = sl:call("get_WeaponParts") or 0,
                    bullet = sl:call("get_BulletID") or 0, num = sl:call("get_Number") or 0 }
            end
        end
        for sc = 0, 3 do
            local idx = slot_index(safe(function() return hinv:call(SC_SIG, sc) end))
            if idx and idx >= 0 then rec.shortcuts[tostring(sc)] = idx end
        end
        rec.main = slot_index(safe(function() return hinv:get_field("_MainSlot") end))
        rec.sub = slot_index(safe(function() return hinv:get_field("_SubSlot") end))
        -- (his health too: a load / game over gives him what he had at that save)
        local hpc = st.hunk and comp(st.hunk, "app.ropeway.HitPointController")
        rec.hp = hpc and safe(function() return hpc:call("get_CurrentHitPoint") end) or nil
        return rec
    end
    -- put a record into HUNK's inventory (every slot is set: empty ones are cleared)
    -- take a d-pad direction (up 0, left 2, right 3) off whatever it points at. setShortcutSlot
    -- has no "none": an unused direction holds a blank Slot (Index -1) in the inventory's
    -- shortcut dictionary, and every direction must stay in it (a removed key can't be set again)
    -- (a fresh blank each time: setShortcutSlot later writes the gun into the very Slot object
    -- the dictionary holds, so a cached blank would stop being blank. Kept alive for good, as the
    -- game holds it and a Lua-owned reference could free it under the game.)
    local function clear_dir(hinv, sc, field)
        pcall(function()
            local b = sdk.create_instance("app.ropeway.inventory.Slot", true)
            if b == nil then return end
            if b.add_ref_permanent then pcall(b.add_ref_permanent, b) else pcall(b.add_ref, b) end
            pcall(b.call, b, ".ctor")
            hinv:get_field(field or "_MainShortcutSlots"):call("set_Item", sc, b)
        end)
    end
    local function clear_dirs(hinv)
        for sc = 0, 3 do clear_dir(hinv, sc); clear_dir(hinv, sc, "_SubShortcutSlots") end
    end
    P.clear_dir = clear_dir
    function P.apply(hinv, rec)
        if not ensure_inventory(hinv) then return false end
        P.repair(hinv)
        local slots = hinv:get_field("_Slots")
        local n = slots:call("get_Count")
        -- (every slot is written with the pouch at full size: setSlot ignores slots past the
        -- current size, which left a bigger kit's items hidden there, to reappear when it grew)
        pcall(hinv.set_field, hinv, "_CurrentSlotSize", n)
        local at = {}
        for _, s in ipairs(rec.slots or {}) do at[s.i] = s end
        for i = 0, n - 1 do
            local s = at[i]
            if s == nil then
                pcall(hinv.call, hinv, SETSLOT_SIG, i, -1, 0, 0, -1, nil)
            elseif (s.wt or -1) > 0 then
                pcall(hinv.call, hinv, SETSLOT_SIG, i, s.wt, s.parts or 0, s.bullet or 0, s.num or 0, nil)
            else
                pcall(hinv.call, hinv, SETITEM_SIG, i, s.item, s.num or 1, nil, nil)
            end
        end
        if rec.size and rec.size >= 8 and rec.size <= n then pcall(hinv.set_field, hinv, "_CurrentSlotSize", rec.size) end
        clear_dirs(hinv)
        for sc, idx in pairs(rec.shortcuts or {}) do
            pcall(hinv.call, hinv, "setShortcutSlot(System.Int32, app.ropeway.EquipmentDefine.Shortcut)", idx, tonumber(sc))
        end
        for _, s in ipairs(rec.slots or {}) do
            if s.wt == 46 or s.wt == 65 or s.wt == 66 then pcall(hinv.call, hinv, "setSubShortcutSlot(System.Int32, System.Boolean)", s.i, true) end
        end
        if rec.sub and at[rec.sub] then P.equip_sub(hinv, rec.sub) end
        if rec.main and at[rec.main] then pcall(hinv.call, hinv, "equipSlot(System.Int32)", rec.main) end
        return true
    end
    -- the loadout of a difficulty as a record
    local FRIEND = {   -- The 4th Survivor
        size = 20,
        slots = {
            { i = 0, wt = 23, bullet = 17, num = 32 },   -- LE 5 (a two-slot item: 0 and 1)
            { i = 2, wt = 11, bullet = 16, num = 4 },    -- W-870
            { i = 3, wt = 31, bullet = 18, num = 7 },    -- Lightning Hawk
            { i = 4, wt = 7, bullet = 15, num = 16 },    -- MUP
            { i = 5, wt = 46, num = 1000 },              -- combat knife
            { i = 6, wt = 65, num = 3 },                 -- hand grenades
            { i = 7, wt = 66, num = 3 },                 -- flash grenades
            { i = 8, item = 17, num = 100 },             -- SMG ammo
            { i = 9, item = 16, num = 6 },               -- shotgun shells
            { i = 10, item = 18, num = 6 },              -- MAG ammo
            { i = 11, item = 1, num = 1 },               -- first aid spray
            { i = 12, item = 10, num = 1 },              -- mixed herb (G+R+B)
            { i = 13, item = 7, num = 1 },               -- mixed herb (G+B)
            { i = 14, item = 11, num = 1 },              -- mixed herb (R+B)
        },
        shortcuts = { ["2"] = 0, ["0"] = 2, ["3"] = 3, ["1"] = 4 }, main = 0, sub = 5,
    }
    local WAR = {
        size = 8,
        slots = { { i = 0, wt = 1, bullet = 15, num = 12 }, { i = 1, wt = 46, num = 1000 } },   -- Matilda, knife
        shortcuts = { ["2"] = 0 }, main = 0, sub = 1,
    }
    local function boy_kit()
        build_loadout()
        local rec = { size = 8, slots = {}, shortcuts = {} }
        local reserve, order = {}, {}
        for _, w in ipairs(LOADOUT) do
            rec.slots[#rec.slots + 1] = { i = w.slot, item = 0, wt = w.wt, parts = 0, bullet = w.bullet or 0, num = w.num }
            if w.shortcut ~= nil then rec.shortcuts[tostring(w.shortcut)] = w.slot end
            if w.sub then rec.sub = w.slot end
            if w.shortcut == 2 then rec.main = w.slot end
            if w.bullet and w.bullet > 0 and not w.sub and w.wt ~= 65 and w.wt ~= 66 and not junk_item(w.bullet) then
                if reserve[w.bullet] == nil then order[#order + 1] = w.bullet end
                reserve[w.bullet] = (reserve[w.bullet] or 0) + w.num * 2
            end
        end
        local free = { 3, 4, 7 }
        for k, item in ipairs(order) do
            if free[k] then rec.slots[#rec.slots + 1] = { i = free[k], item = item, wt = -1, num = reserve[item] } end
        end
        if #order < 3 then rec.slots[#rec.slots + 1] = { i = free[#order + 1], item = st.p2_support or 2, wt = -1, num = 1 } end
        return rec
    end
    local function filled(rec)   -- (fill in the defaults of a hand-written record)
        local r = { size = rec.size, slots = {}, shortcuts = {}, main = rec.main, sub = rec.sub }
        for _, s in ipairs(rec.slots) do r.slots[#r.slots + 1] = { i = s.i, item = s.item or 0, wt = s.wt or -1, parts = s.parts or 0, bullet = s.bullet or 0, num = s.num or 1 } end
        for k, v in pairs(rec.shortcuts or {}) do r.shortcuts[k] = v end
        return r
    end
    -- Loadouts (Operative / Veteran; Rookie keeps the Weapons settings). Each
    -- character has a default for Friend (characters without their own share one: the Leon
    -- look-alikes Leon's, the Claire look-alikes Claire's), War is always a knife and a gun on
    -- basic handgun ammo, and each character has Custom 1 and Custom 2 (lists of entries, built
    -- in the Character tab or saved from what player 2 carries). Which one each difficulty uses
    -- is chosen per character. Kept in reunited_loadouts.json:
    --   { custom = { [model] = { ["1"] = { entries }, ["2"] = ... } }, use = { [model] = { friend = "default" / "1" / "2", war = ... } } }
    -- entry: { wt = weapon type, num = rounds loaded } or { id = item id, num = count }
    local LO = { file = "reunited_loadouts.json", data = { custom = {}, use = {} } }
    P.LO = LO
    do
        local ok, t = pcall(json.load_file, LO.file)
        if ok and type(t) == "table" then
            LO.data.custom = type(t.custom) == "table" and t.custom or {}
            LO.data.use = type(t.use) == "table" and t.use or {}
        end
    end
    function LO.save() pcall(json.dump_file, LO.file, LO.data) end
    -- whose default a character uses
    LO.GROUP = { hunk = "hunk", tofu = "tofu", ada = "ada",
        leon = "leon", kendo = "leon", daniel = "leon", irons = "leon", ben = "leon", marvin = "leon", pilot = "leon", rpd = "leon",
        claire = "claire", katherine = "claire", annette = "claire", sherry = "claire" }
    local AMMO_OF = {}
    for _, w in ipairs(WEAPONS) do AMMO_OF[w.wt] = w.ammo end
    local function W(wt, num) return { wt = wt, num = num } end
    local function I(id, num) return { id = id, num = num } end
    -- (item ids: 1 first aid spray, 2 green herb, 5 mixed G+G, 7 G+B, 10 G+R+B, 11 R+B; ammo
    -- 15 handgun, 16 shotgun shells, 17 SMG, 18 MAG, 22 grenade launcher acid rounds)
    LO.DEFAULT = {
        leon = { W(1, 12), W(11, 4), W(31, 7), W(46, 1000), W(65, 2), W(66, 1),
            I(15, 30), I(16, 8), I(18, 6), I(1, 1), I(10, 1), I(5, 1) },
        claire = { W(2, 7), W(21, 24), W(42, 1), W(46, 1000), W(65, 1), W(66, 2),
            I(15, 30), I(17, 60), I(22, 4), I(1, 1), I(10, 1), I(5, 1) },
        ada = { W(8, 9), W(46, 1000), W(66, 2), I(15, 45), I(1, 1), I(10, 1), I(5, 1) },
        tofu = { W(46, 1000), W(46, 1000), W(46, 1000), W(46, 1000), W(46, 1000), W(1, 12), I(15, 15), I(1, 1), I(1, 1) },
    }
    LO.WAR_GUN = { hunk = 7, leon = 1, claire = 2, ada = 8, tofu = 1 }   -- MUP, Matilda, M19, Broom Hc
    function LO.group(model) return LO.GROUP[model or st.p2_model] or "leon" end
    -- a character's default Operative loadout as entries (HUNK's from his record)
    function LO.default_entries(model)
        local g = LO.group(model)
        if g == "hunk" then
            local out = {}
            for _, sl in ipairs(FRIEND.slots) do
                if (sl.wt or -1) > 0 then out[#out + 1] = W(sl.wt, sl.num) else out[#out + 1] = I(sl.item, sl.num) end
            end
            return out
        end
        return LO.DEFAULT[g] or LO.DEFAULT.leon
    end
    -- the entries a difficulty gives this character (nil: HUNK's own hand-made records below)
    function LO.entries(model, d)
        model = model or st.p2_model
        local use = (LO.data.use[model] or {})[d] or "default"
        local c = (LO.data.custom[model] or {})[use]
        if use ~= "default" and type(c) == "table" and #c > 0 then return c end
        local g = LO.group(model)
        if d == "war" then
            local gw = LO.WAR_GUN[g] or 1
            return { W(gw, (WEAPON_BY_WT[gw] or { num = 12 }).num), W(46, 1000) }   -- (one magazine, nothing spare)
        end
        if g == "hunk" then return nil end
        return LO.DEFAULT[g] or LO.DEFAULT.leon
    end
    -- entries -> a record: guns first (d-pad left, up, right, down in that order), two-slot
    -- guns never in the last column, then knives / grenades, then the items
    function LO.pack(entries)
        local rec = { slots = {}, shortcuts = {} }
        local used = {}
        local function free_at(fat)
            for i = 0, 19 do
                if not used[i] and (not fat or (i % 4 ~= 3 and not used[i + 1])) then return i end
            end
        end
        local order = {}
        local function cls(e)
            if (e.wt or -1) > 0 and e.wt ~= 46 and e.wt ~= 65 and e.wt ~= 66 then return 1 end
            if (e.wt or -1) > 0 then return 2 end
            return 3
        end
        for k, e in ipairs(entries) do order[#order + 1] = { e = e, k = k } end
        table.sort(order, function(a, b) local x, y = cls(a.e), cls(b.e); if x ~= y then return x < y end return a.k < b.k end)
        local dirs = { 2, 0, 3, 1 }
        local ndir = 0
        for _, o in ipairs(order) do
            local e = o.e
            if (e.wt or -1) > 0 then
                local fat = P.fat_weapon and P.fat_weapon(e.wt, 0) or false
                local i = free_at(fat)
                if i then
                    used[i] = true
                    if fat then used[i + 1] = true end
                    local bullet = (e.wt == 46 or e.wt == 65 or e.wt == 66) and 0 or (AMMO_OF[e.wt] or 0)
                    rec.slots[#rec.slots + 1] = { i = i, item = 0, wt = e.wt, parts = 0, bullet = bullet, num = e.num or 1 }
                    if cls(e) == 1 then
                        ndir = ndir + 1
                        if dirs[ndir] then rec.shortcuts[tostring(dirs[ndir])] = i end
                        if rec.main == nil then rec.main = i end
                    elseif e.wt == 46 and rec.sub == nil then rec.sub = i end
                end
            elseif (e.id or 0) > 0 then
                local i = free_at(false)
                if i then used[i] = true; rec.slots[#rec.slots + 1] = { i = i, item = e.id, wt = -1, parts = 0, bullet = 0, num = e.num or 1 } end
            end
        end
        local top = 0
        for i in pairs(used) do top = math.max(top, i + 1) end
        rec.size = math.max(8, math.min(20, math.ceil(top / 2) * 2))
        return rec
    end
    -- what player 2 carries now, as entries
    function LO.from_inventory(hinv)
        local out = {}
        for _, e in ipairs(hinv and P.list(hinv) or {}) do
            if e.wt > 0 then out[#out + 1] = W(e.wt, e.num) elseif e.id > 0 and not junk_item(e.id) then out[#out + 1] = I(e.id, e.num) end
        end
        return out
    end
    function P.starter()
        local d = st.p2_difficulty
        if d == "boy" then return boy_kit() end
        local ent = LO.entries(st.p2_model, d)
        if ent then return LO.pack(ent) end
        if d == "war" then return filled(WAR) end
        return filled(FRIEND)
    end
    P.DIFF_NAMES = { boy = "Rookie", friend = "Operative", war = "Veteran" }
    -- give player 2 the loadout of the current difficulty now (a difficulty preset)
    function P.rekit()
        local hinv = hunk_inv()
        if st.infinite_ammo then return false end
        -- no HUNK right now (unspawned, loading) or one that's still being set up (just
        -- spawned, not provisioned yet): he gets this kit when he's provisioned
        if hinv == nil or P.prov_addr ~= st.hunk:get_address() or st.pending then P.want_kit = true; return false end
        if not P.apply(hinv, P.starter()) then P.want_kit = true; return false end
        P.want_kit = nil
        P.prov_addr, P.hold = st.hunk:get_address(), false
        pcall(P.fix_shortcuts, hinv)
        local cap = P.capture(hinv)
        if cap then P.data.live = cap; write() end
        if st.anim and st.anim.check then pcall(st.anim.check) end
        note("rekit (" .. tostring(st.p2_difficulty) .. ")")
        return true
    end
    function P.valid(rec)
        if type(rec) ~= "table" or type(rec.slots) ~= "table" then return false, "none" end
        local g, t = save_guid(), clock_s()
        -- (v428) A save slot's record, just loaded with that save (load menu, Continue after a game
        -- over, the title screen): it is that save's player 2, so it's used as it is. The
        -- playthrough check below threw these out ("another playthrough": MainFlowManager
        -- .SaveGUID read when saving isn't the one the game has after loading that save), and
        -- player 2 got the starting kit after every load. The only check: the record must be
        -- from this very save, its play time the loaded game's (a slot saved over while the mod
        -- wasn't keeping player 2 has an older record: that one isn't used).
        if rec.from_save then
            if rec.t and t and (t < rec.t - 10 or t > rec.t + 600) then
                return false, string.format("slot %s kept from another save (%ss, game at %ss)", tostring(rec.from_save), tostring(rec.t), tostring(t))
            end
            return true
        end
        -- (v398) the playthrough decides when both are known. The play clock is only the
        -- fallback: the game rolls it back when it reloads by itself around a cutscene, which
        -- made the record "newer than this game" and gave player 2 the starting kit again.
        if rec.guid and g then
            if rec.guid ~= g then return false, "another playthrough" end
            return true
        end
        if rec.t and t and rec.t > t + 5 then return false, "newer than this game" end
        return true
    end
    local KIT_NAME = { boy = "the rookie loadout", friend = "the operative loadout", war = "the veteran loadout (a knife and a Matilda)" }
    -- give the HUNK that just appeared what player 2 carries (or the starter kit)
    function P.provision(quiet)
        local hinv = hunk_inv()
        if hinv == nil then return end
        if not ensure_inventory(hinv) then st.loadout_given = false; return end
        local rec = P.data.live
        local ok, why = P.valid(rec)
        if P.want_kit then ok, why = false, "difficulty chosen" end
        local done
        if ok then
            done = P.apply(hinv, rec)
            note((rec.from_save and ("restored save " .. tostring(rec.from_save)) or "restored live") .. " (" .. #rec.slots .. " slots; kept at "
                .. tostring(rec.t) .. "s, game at " .. tostring(clock_s()) .. "s)")
            local hpc = comp(st.hunk, "app.ropeway.HitPointController")
            if hpc and type(rec.hp) == "number" and rec.hp > 0 and not st.invulnerable then
                pcall(hpc.call, hpc, "set_CurrentHitPoint", math.floor(rec.hp))
                note("health " .. math.floor(rec.hp))
            end
            if not quiet then say("Player 2's inventory is back") end
        else
            rec = P.starter()
            done = P.apply(hinv, rec)
            note("starter kit (" .. tostring(st.p2_difficulty) .. "), live record: " .. tostring(why))
            say("Player 2 starts with " .. (KIT_NAME[st.p2_difficulty] or "a starter kit"))
        end
        P.hold = false
        P.prov_addr = st.hunk:get_address()
        if done then P.want_kit = nil; pcall(P.fix_shortcuts, hinv) end
        st.loadout_given = done
        st.hunk_weapon = nil
        local cap = done and P.capture(hinv)
        if cap then P.data.live = cap; write() end
        if done and st.anim and st.anim.check then pcall(st.anim.check) end
    end
    -- (v398) what he carries right now into live (before he's removed for a load / reload),
    -- when he's the HUNK this session set up and it's his own inventory
    function P.snapshot()
        if st.infinite_ammo or P.hold or st.hunk == nil or P.prov_addr ~= st.hunk:get_address() then return false end
        local hinv = hunk_inv()
        if hinv == nil or P.count(hinv) == 0 then return false end
        local cap = P.capture(hinv)
        if cap then P.data.live = cap; write(); return true end
        return false
    end
    -- every frame (from the main loop)
    function P.tick()
        pcall(P.unlock_tick)
        local finite = not st.infinite_ammo
        if P.mode ~= nil and P.mode ~= finite and st.hunk and not st.pending then
            -- switched: finite gets player 2's own inventory back, infinite the loadout
            note(finite and "infinite ammo off" or "infinite ammo on")
            if finite then P.provision(true) else st.loadout_given = false; pcall(give_loadout, nil, true) end
        end
        P.mode = finite
        if not finite or st.hunk == nil or st.pending or P.hold then return end
        pcall(P.pickup_tick)
        local addr = st.hunk:get_address()
        if P.prov_addr ~= addr then
            -- a HUNK this session hasn't provisioned (a script reset): once he has settled
            if P.seen_addr ~= addr then P.seen_addr, P.seen_at = addr, st.frame end
            if st.verify_at == nil and st.frame - P.seen_at > 90 then P.provision(true) end
            return
        end
        if st.frame % 30 ~= 0 then return end
        local hinv = hunk_inv()
        if hinv == nil or P.count(hinv) == 0 then return end
        if P.repair(hinv) > 0 then pcall(P.fix_shortcuts, hinv) end
        local cap = P.capture(hinv)
        if cap then P.data.live = cap; write() end
    end
    -- Player 2's pickups (st.p2_pickups, Infinite ammo off): ammo, healing items and weapons he
    -- picks up go into his inventory; everything else (keys, story items, gunpowder, files...)
    -- still goes to player 1 through the game's pick-up screen, as before. A world item is taken
    -- (vanishes, recorded in the save) before the game's pick-up screen opens
    -- (GUIMaster.openInventoryGetItemMode); that screen only places the item in player 1's
    -- inventory (and puts the world item back on cancel). For player 2's items the screen is
    -- skipped and the item goes straight into his inventory: no screen for player 1 to answer.
    -- Nothing is picked up if player 2 has no room.
    st.p2_pickups = true
    local function im() return sdk.get_managed_singleton("app.ropeway.gamemastering.ItemManager") end
    local function leon_inv()
        local p1 = p1_go()
        return p1 and comp(p1, "app.ropeway.survivor.Inventory") or nil
    end
    -- player 2 may carry this (also what can be traded): healing items, ammo, weapons, and
    -- (v445) these type-3 items: Red Herb (3, 13), Ink Ribbon (32), Wooden Boards (33),
    -- Gunpowder / Gunpowder (Large) / High-Grade Gunpowder Yellow / White (36-39)
    P.P2_EXTRA = { [3] = true, [13] = true, [32] = true, [33] = true, [36] = true, [37] = true, [38] = true, [39] = true }
    function P.p2_item(id, wt)
        if wt and wt > 0 then return true end
        if not id or id <= 0 then return false end
        if P.P2_EXTRA[id] then return true end
        local ty = safe(function() return im():call("getItemType", id) end)
        return ty == 1 or ty == 2
    end
    local function item_name(id, wt)
        if wt and wt > 0 then return safe(function() return im():call("getWeaponName", wt, 0) end) or "weapon" end
        return safe(function() return im():call("getItemName", id) end) or "item"
    end
    local function size_of(hinv) return safe(function() return hinv:get_field("_CurrentSlotSize") end) or 8 end
    -- room in an inventory for an item (stack space) / free slots
    function P.room(hinv, id, wt)
        local map = index_map(hinv)
        local n, free = 0, 0
        for i = 0, size_of(hinv) - 1 do
            local sl = map[i]
            local sid, swt = sl and sl:call("get_ItemID") or 0, sl and sl:call("get_WeaponType") or -1
            if sid <= 0 and swt <= 0 then free = free + 1
            elseif not (wt and wt > 0) and sid == id then n = n + math.max(0, safe(function() return sl:call("get_VacancyNumber") end) or 0) end
        end
        return n, free
    end
    local function first_free(hinv)
        local map = index_map(hinv)
        for i = 0, size_of(hinv) - 1 do
            local sl = map[i]
            if sl and (sl:call("get_ItemID") or 0) <= 0 and (sl:call("get_WeaponType") or -1) <= 0
                and safe(function() return hinv:call("isDeadSlot", i) end) ~= true then return i end
        end
        return nil
    end
    -- put n of an item into player 2's inventory (existing stacks first); returns how many fit
    function P.put_item(hinv, id, n)
        local map = index_map(hinv)
        local left = n
        for i = 0, size_of(hinv) - 1 do
            if left <= 0 then break end
            local sl = map[i]
            if sl and sl:call("get_ItemID") == id then
                local v = math.max(0, safe(function() return sl:call("get_VacancyNumber") end) or 0)
                local k = math.min(v, left)
                if k > 0 then sl:call("set_Number", sl:call("get_Number") + k); left = left - k end
            end
        end
        local guard = 0
        while left > 0 and guard < 8 do
            guard = guard + 1
            local i = first_free(hinv)
            if i == nil then break end
            pcall(hinv.call, hinv, SETITEM_SIG, i, id, left, nil, nil)
            local sl = slot_at(hinv, i)
            if sl == nil then break end
            local max = safe(function() return sl:call("get_MaxNumber") end) or left
            local got = math.min(left, max > 0 and max or left)
            sl:call("set_Number", got)
            left = left - got
        end
        return n - left
    end
    -- a weapon into player 2's inventory, onto a free d-pad direction if there is one
    -- two-slot weapons: the game's own rule (InventoryManager.isFatWeapon: the LE 5, launchers,
    -- the minigun... always; most guns only with certain parts fitted, e.g. a W-870 with its stock)
    local FAT = sdk.find_type_definition("app.ropeway.gamemastering.InventoryManager"):get_method("isFatWeapon")
    local function fat_weapon(wt, parts)
        return FAT ~= nil and safe(function() return FAT:call(nil, wt, parts or 0) end) == true
    end
    P.fat_weapon = fat_weapon
    -- a free place for a two-slot item: this slot and the one to its right, not in the last
    -- column
    local function first_free_fat(hinv)
        local map = index_map(hinv)
        local size = size_of(hinv)
        local function free(i)
            local sl = map[i]
            return sl and (sl:call("get_ItemID") or 0) <= 0 and (sl:call("get_WeaponType") or -1) <= 0
                and safe(function() return hinv:call("isDeadSlot", i) end) ~= true
        end
        for i = 0, size - 2 do
            if i % 4 ~= 3 and free(i) and free(i + 1) then return i end
        end
        return nil
    end
    function P.weapon_room(hinv, wt, parts)
        if fat_weapon(wt, parts) then return first_free_fat(hinv) ~= nil end
        return first_free(hinv) ~= nil
    end
    function P.put_weapon(hinv, w)
        local i
        if fat_weapon(w.wt, w.parts) then i = first_free_fat(hinv) else i = first_free(hinv) end
        if i == nil then return false end
        pcall(hinv.call, hinv, SETSLOT_SIG, i, w.wt, w.parts or 0, w.bullet or 0, w.num or 0, nil)
        if w.wt == 46 or w.wt == 65 or w.wt == 66 then
            pcall(hinv.call, hinv, "setSubShortcutSlot(System.Int32, System.Boolean)", i, true)
        else
            for _, sc in ipairs(P.SC_ORDER) do
                local taken = safe(function() return hinv:call(SC_SIG, sc):call("get_Index") end)
                if taken == nil or taken < 0 then
                    pcall(hinv.call, hinv, "setShortcutSlot(System.Int32, app.ropeway.EquipmentDefine.Shortcut)", i, sc)
                    break
                end
            end
        end
        return true
    end
    -- move an item to another slot (player 2's inventory screen): whatever is in the way swaps
    -- into the slot it came from, or (several items / no room there) goes to the first free
    -- place it fits; two-slot items take their slot and the one to its right, never the last
    -- column. Nothing changes if it can't all fit. d-pad / LB shortcuts and what's in his hands
    -- follow the items.
    function P.move_item(hinv, from, to)
        if hinv == nil then return false end
        -- the game's own exchange (what Leon's menu uses): swaps, moves a two-slot item over two
        -- others, and carries the shortcuts and the equipped weapons along. Rebuilding the whole
        -- inventory (below) is only for what it refuses.
        if safe(function() return hinv:call("enableExchangeSlot(System.Int32, System.Int32)", from, to) end) == true
            and safe(function() return hinv:call("exchangeSlot(System.Int32, System.Int32)", from, to) end) == true then
            pcall(P.fix_shortcuts, hinv)
            pcall(P.saved)
            return true
        end
        local rec = P.capture(hinv)
        if rec == nil then return false end
        local size = rec.size or size_of(hinv)
        local function isfat(e) return (e.wt or -1) > 0 and fat_weapon(e.wt, e.parts) end
        local function fits(e, at)
            if at < 0 or at >= size then return false end
            if isfat(e) and (at % 4 == 3 or at + 1 >= size) then return false end
            return true
        end
        local function cells(e, at) if isfat(e) then return { at, at + 1 } end return { at } end
        local A
        for _, e in ipairs(rec.slots) do if e.i == from then A = e end end
        if A == nil then return false end
        -- a two-slot item can't start in the last column: place it one to the left
        if isfat(A) and to % 4 == 3 then to = to - 1 end
        if not fits(A, to) then return false, "It doesn't fit there" end
        local occ = {}
        for _, e in ipairs(rec.slots) do for _, c in ipairs(cells(e, e.i)) do occ[c] = e end end
        local moved, seen = {}, {}
        for _, c in ipairs(cells(A, to)) do
            local e = occ[c]
            if e and e ~= A and not seen[e] then seen[e] = true; moved[#moved + 1] = e end
        end
        table.sort(moved, function(a, b) return a.i < b.i end)
        -- the new layout: everything but A and the displaced items stays put
        local new = {}
        for _, e in ipairs(rec.slots) do
            if e ~= A and not seen[e] then for _, c in ipairs(cells(e, e.i)) do new[c] = e end end
        end
        local function free(e, at)
            if not fits(e, at) then return false end
            for _, c in ipairs(cells(e, at)) do if new[c] then return false end end
            return true
        end
        if not free(A, to) then return false, "It doesn't fit there" end
        for _, c in ipairs(cells(A, to)) do new[c] = A end
        local where = { [A] = to }
        for k, e in ipairs(moved) do
            local at
            if k == 1 and free(e, from) then at = from end
            if at == nil then for j = 0, size - 1 do if free(e, j) then at = j; break end end end
            if at == nil then return false, "No room to move that there" end
            for _, c in ipairs(cells(e, at)) do new[c] = e end
            where[e] = at
        end
        -- old Index -> new Index for everything that moved; the record gets the new layout
        local map = {}
        for e, at in pairs(where) do map[e.i] = at end
        for _, e in ipairs(rec.slots) do if map[e.i] then e.i = map[e.i] end end
        local function remap(i) if i == nil then return nil end return map[i] or i end
        for k, v in pairs(rec.shortcuts) do rec.shortcuts[k] = remap(v) end
        rec.main, rec.sub = remap(rec.main), remap(rec.sub)
        P.apply(hinv, rec)
        pcall(P.fix_shortcuts, hinv)
        if P.saved then pcall(P.saved) end
        return true
    end
    -- Player 2's inventory, item by item (his menu's Inventory page and the co-op menu's) ------
    local SUBW = { [46] = true, [65] = true, [66] = true }   -- knife, hand / flash grenade
    P.SUBW = SUBW
    -- d-pad directions (EquipmentDefine.Shortcut): a gun on each, like player 1; knife and
    -- grenades are on LB + d-pad (the game's sub-weapon shortcuts: knife up, hand grenade
    -- left, flash grenade right)
    P.SC_NAMES = { [0] = "d-pad up", [1] = "d-pad down", [2] = "d-pad left", [3] = "d-pad right" }
    P.SC_ORDER = { 2, 0, 3, 1 }   -- free directions are handed out left, up, right, down
    function P.hunk_inv() return hunk_inv() end
    function P.leon_inv() return leon_inv() end
    function P.item_name(id, wt) return item_name(id, wt) end
    -- the filled slots of an inventory (within its size)
    function P.list(inv)
        local out = {}
        if inv == nil then return out end
        local map = index_map(inv)
        for i = 0, size_of(inv) - 1 do
            local sl = map[i]
            local id, wt = sl and sl:call("get_ItemID") or 0, sl and sl:call("get_WeaponType") or -1
            if sl and (id > 0 or wt > 0) then
                out[#out + 1] = { i = i, id = id, wt = wt, num = sl:call("get_Number") or 0, parts = sl:call("get_WeaponParts") or 0,
                    bullet = sl:call("get_BulletID") or 0, name = item_name(id, wt) }
            end
        end
        return out
    end
    function P.size(inv) return size_of(inv) end
    function P.main_index(inv) return slot_index(safe(function() return inv:get_field("_MainSlot") end)) end
    function P.sub_index(inv) return slot_index(safe(function() return inv:get_field("_SubSlot") end)) end
    function P.shortcut_of(inv, i)
        for sc, _ in pairs(P.SC_NAMES) do
            if slot_index(safe(function() return inv:call(SC_SIG, sc) end)) == i then return sc end
        end
        return nil
    end
    local function saved()   -- (P.saved: the same, for functions defined above)
        local hinv = hunk_inv()
        local cap = hinv and P.capture(hinv)
        if cap and not st.infinite_ammo then P.data.live = cap; write() end
        if st.anim and st.anim.check then pcall(st.anim.check) end   -- a new gun's moves
    end
    P.saved = saved
    -- make a knife / grenade (by Index) the one in his off hand
    function P.equip_sub(hinv, i)
        local sl = slot_at(hinv, i)
        if sl == nil then return false end
        if not pcall(hinv.call, hinv, "equipSubSlot(app.ropeway.inventory.Slot)", sl) then
            safe(function() hinv:call("set_SubSlot", sl) end)
        end
        return true
    end
    local SUB_SIG = "getSlotSubShortcut(app.ropeway.EquipmentDefine.Shortcut)"
    P.SUB_SIG = SUB_SIG
    -- every gun gets a d-pad direction while one is free (left, up, right, down); every knife /
    -- grenade gets its LB + d-pad shortcut; directions left on something else are freed; the
    -- off hand always holds a knife or grenade if he has one
    function P.fix_shortcuts(hinv)
        hinv = hinv or hunk_inv()
        if hinv == nil then return end
        local used, has, gun, byi = {}, {}, {}, {}
        local list = P.list(hinv)
        for _, e in ipairs(list) do
            byi[e.i] = e
            if e.wt > 0 and not SUBW[e.wt] then gun[e.i] = true end
        end
        for sc, _ in pairs(P.SC_NAMES) do
            local i = slot_index(safe(function() return hinv:call(SC_SIG, sc) end))
            if i and i >= 0 then
                -- a direction left on a knife, a grenade, an emptied slot or a second copy is freed
                if gun[i] and not has[i] then used[sc], has[i] = i, true else clear_dir(hinv, sc) end
            end
        end
        -- LB + d-pad: an entry whose slot no longer holds that weapon is freed
        local sub_has = {}
        for sc = 0, 3 do
            local v = safe(function() return hinv:call(SUB_SIG, sc) end)
            local i = slot_index(v)
            if i and i >= 0 then
                local wt = safe(function() return v:call("get_WeaponType") end)
                local e = byi[i]
                if e and SUBW[e.wt] and e.wt == wt and not sub_has[i] then sub_has[i] = true
                else clear_dir(hinv, sc, "_SubShortcutSlots") end
            end
        end
        local subs = {}
        for _, e in ipairs(list) do
            if SUBW[e.wt] then
                subs[#subs + 1] = e
                if not sub_has[e.i] then pcall(hinv.call, hinv, "setSubShortcutSlot(System.Int32, System.Boolean)", e.i, true) end
            elseif e.wt > 0 and not has[e.i] then
                for _, sc in ipairs(P.SC_ORDER) do
                    if used[sc] == nil then
                        pcall(hinv.call, hinv, "setShortcutSlot(System.Int32, app.ropeway.EquipmentDefine.Shortcut)", e.i, sc)
                        used[sc], has[e.i] = e.i, true
                        break
                    end
                end
            end
        end
        local cur = P.sub_index(hinv)
        local ok = false
        for _, e in ipairs(subs) do if e.i == cur then ok = true end end
        if not ok and subs[1] then P.equip_sub(hinv, subs[1].i) end
    end
    -- the next knife / grenade he has (the co-op menu's sub-weapon switch; on the pad it's LB +
    -- d-pad, the game's own)
    function P.next_sub()
        local hinv = hunk_inv()
        if hinv == nil then return nil end
        local subs = {}
        for _, e in ipairs(P.list(hinv)) do if SUBW[e.wt] then subs[#subs + 1] = e end end
        if #subs == 0 then return nil, "no knife or grenade" end
        local cur, pos = P.sub_index(hinv), 0
        for k, e in ipairs(subs) do if e.i == cur then pos = k end end
        local nxt = subs[pos % #subs + 1]
        P.equip_sub(hinv, nxt.i)
        return nxt
    end
    function P.equip(i)
        local hinv = hunk_inv()
        if hinv == nil then return end
        local e
        for _, x in ipairs(P.list(hinv)) do if x.i == i then e = x end end
        if e == nil or e.wt <= 0 then return end
        if SUBW[e.wt] then
            P.equip_sub(hinv, i)
        else
            pcall(hinv.call, hinv, "equipSlot(System.Int32)", i)
            st.default_weapon_slot = i
        end
        saved()
    end
    -- the LB + d-pad direction a knife / grenade (by Index) is on, if any
    function P.sub_shortcut_of(inv, i)
        for sc = 0, 3 do
            if slot_index(safe(function() return inv:call(SUB_SIG, sc) end)) == i then return sc end
        end
        return nil
    end
    function P.assign(i, sc)
        local hinv = hunk_inv()
        if hinv == nil then return end
        pcall(hinv.call, hinv, "setShortcutSlot(System.Int32, app.ropeway.EquipmentDefine.Shortcut)", i, sc)
        saved()
    end
    local function equipped(inv, i) return P.main_index(inv) == i or P.sub_index(inv) == i end
    -- move a whole stack / weapon between the players' inventories (from -> to); returns how
    -- many moved and why not
    local function move(from, to, i, refuse_equipped)
        local e
        for _, x in ipairs(P.list(from)) do if x.i == i then e = x end end
        if e == nil then return 0, "nothing there" end
        if not P.p2_item(e.id, e.wt) then return 0, "that can't be traded" end
        if refuse_equipped and equipped(from, i) then return 0, "that's in " .. st.p1_name() .. "'s hands" end
        if e.wt > 0 then
            if not P.weapon_room(to, e.wt, e.parts) then return 0, "no room" end
            local was_main = P.main_index(from) == i
            P.put_weapon(to, e)
            pcall(from.call, from, "removeSlot(System.Int32)", i)
            if was_main then   -- (his hands are empty now: the next gun he has)
                for _, x in ipairs(P.list(from)) do
                    if x.wt > 0 and not SUBW[x.wt] then pcall(from.call, from, "equipSlot(System.Int32)", x.i); break end
                end
            end
            return 1
        end
        local moved = P.put_item(to, e.id, e.num)
        if moved <= 0 then return 0, "no room" end
        local slot = slot_at(from, i)
        if slot == nil then return moved end
        if moved >= e.num then pcall(from.call, from, "removeSlot(System.Int32)", i)
        else pcall(slot.call, slot, "set_Number", e.num - moved) end
        return moved
    end
    function P.give_to_p1(i)
        local hinv, leon = hunk_inv(), leon_inv()
        if hinv == nil or leon == nil then return 0, "no one to give to" end
        local n, why = move(hinv, leon, i, false)
        P.fix_shortcuts(hinv)
        saved()
        return n, why
    end
    function P.take_from_p1(i)
        local hinv, leon = hunk_inv(), leon_inv()
        if hinv == nil or leon == nil then return 0, "no one to take from" end
        local n, why = move(leon, hinv, i, true)
        P.fix_shortcuts(hinv)
        saved()
        return n, why
    end
    -- a healing item used on player 1 (his healing ability, from player 2's own supplies)
    function P.use_on_p1(i)
        local hinv = hunk_inv()
        local e
        for _, x in ipairs(P.list(hinv)) do if x.i == i then e = x end end
        if e == nil or safe(function() return im():call("getItemType", e.id) end) ~= 1 then return false, "not a healing item" end
        local p1 = p1_go()
        local hp = p1 and comp(p1, "app.ropeway.HitPointController")
        local pm = sdk.get_managed_singleton("app.ropeway.PlayerManager")
        if hp == nil or pm == nil then return false, "no " .. st.p1_name() end
        local cur, max = hp:call("get_CurrentHitPoint"), hp:call("get_DefaultHitPoint")
        if cur >= max then return false, st.p1_name() .. " is already at full health" end
        local v = safe(function() return im():call("getItemEffectiveValue", e.id) end) or 0
        local amount = math.floor(math.min(v > 0 and v or st.heal_amount, max - cur))   -- (v413: Int32, see heal_self)
        pm:call("recoveryCurrentPlayer", amount)
        local slot = slot_at(hinv, i)
        if slot and e.num > 1 then pcall(slot.call, slot, "set_Number", e.num - 1) else pcall(hinv.call, hinv, "removeSlot(System.Int32)", i) end
        saved()
        return true, string.format("%s used %s on %s (+%d HP)", st.p2_name(), e.name, st.p1_name(), amount)
    end
    -- Rookie: the item box station. Pressing A at an item box (the typewriter gimmick
    -- the game puts by every item box) opens it in player 2's menu: change the gun on any
    -- d-pad direction to any weapon, the grenade type and the support item, and restock.
    local box_cache, box_frame = {}, -1000
    function P.near_box()
        if st.hunk == nil then return false end
        if st.frame - box_frame > 60 then
            box_frame, box_cache = st.frame, {}
            pcall(function()
                local scene = sdk.call_native_func(sdk.get_native_singleton("via.SceneManager"), sdk.find_type_definition("via.SceneManager"), "get_CurrentScene")
                -- (the item boxes themselves: GimmickItemLocker; RE2 calls the item box a locker)
                local l = scene:call("findComponents(System.Type)", sdk.typeof("app.ropeway.gimmick.action.GimmickItemLocker"))
                for i = 0, l:call("get_Count") - 1 do
                    local p = l:call("get_Item", i):call("get_GameObject"):call("get_Transform"):call("get_Position")
                    box_cache[#box_cache + 1] = { p.x, p.y, p.z }
                end
            end)
        end
        local hp = st.hunk:call("get_Transform"):call("get_Position")
        for _, b in ipairs(box_cache) do
            if math.abs(b[2] - hp.y) < 1.6 and (b[1] - hp.x) ^ 2 + (b[3] - hp.z) ^ 2 < 2.5 ^ 2 then return true end
        end
        return false
    end
    -- A at an item box: Rookie's station (v411: also with Infinite ammo, where it sets the
    -- d-pad guns and the grenade, as Player 2 > Weapons does; before, A did nothing there),
    -- otherwise the item box itself (his own inventory)
    function P.box_action()
        if st.ai_partner() or not P.near_box() then return false end
        if not st.ig then return false end
        return st.ig.open_box((st.infinite_ammo or st.p2_difficulty == "boy") and "boy" or "box") or false
    end
    P.DIR_KEY = { [0] = "weapon_up", [2] = "weapon_left", [3] = "weapon_right" }
    local function slot_of_sc(hinv, sc) return slot_index(safe(function() return hinv:call(SC_SIG, sc) end)) end
    local function slot_obj(hinv, i) return slot_at(hinv, i) end
    -- spare rounds for a gun: at least two magazines
    local function top_reserve(hinv, w)
        if not w or not w.ammo or junk_item(w.ammo) then return end
        local have = safe(function() return hinv:call("getNumber(app.ropeway.gamemastering.Item.ID)", w.ammo) end) or 0
        if have < w.num * 2 then P.put_item(hinv, w.ammo, w.num * 2 - have) end
    end
    function P.station_set_gun(sc, wt)
        local hinv = hunk_inv()
        local w = WEAPON_BY_WT[wt]
        if hinv == nil or w == nil then return end
        local i = slot_of_sc(hinv, sc)
        local have
        for _, e in ipairs(P.list(hinv)) do if e.wt == wt then have = e.i end end
        if have and have == i then
            -- already there
        elseif have then
            -- he carries that gun: it takes this direction, and the gun that was here gets the
            -- direction it had (no second copy of a gun)
            local other = P.shortcut_of(hinv, have)
            pcall(hinv.call, hinv, "setShortcutSlot(System.Int32, app.ropeway.EquipmentDefine.Shortcut)", have, sc)
            if other and other ~= sc then
                if i and i >= 0 then pcall(hinv.call, hinv, "setShortcutSlot(System.Int32, app.ropeway.EquipmentDefine.Shortcut)", i, other)
                else clear_dir(hinv, other) end
                local oe
                for _, e in ipairs(P.list(hinv)) do if e.i == i then oe = e end end
                if P.DIR_KEY[other] then st[P.DIR_KEY[other]] = oe and oe.wt or st[P.DIR_KEY[other]] end
            end
        elseif i and i >= 0 then
            local old_wt = safe(function() return slot_obj(hinv, i):call("get_WeaponType") end)
            pcall(hinv.call, hinv, SETSLOT_SIG, i, wt, 0, w.ammo or 0, w.num, nil)
            pcall(hinv.call, hinv, "setShortcutSlot(System.Int32, app.ropeway.EquipmentDefine.Shortcut)", i, sc)
            -- the gun he left in the box takes its spare rounds with it (when no other gun of his
            -- uses them), so there's room for the new gun's
            local ow = old_wt and WEAPON_BY_WT[old_wt]
            if ow and ow.ammo and ow.ammo ~= w.ammo then
                local used = false
                for _, e in ipairs(P.list(hinv)) do local x = WEAPON_BY_WT[e.wt]; if x and x.ammo == ow.ammo then used = true end end
                if not used then
                    for _, e in ipairs(P.list(hinv)) do
                        if e.id == ow.ammo and e.wt <= 0 then pcall(hinv.call, hinv, "removeSlot(System.Int32)", e.i) end
                    end
                end
            end
        else
            -- a direction with no gun yet (d-pad down): Rookie's 8 slots are all in use, so
            -- his pouch grows two slots at a time until the gun (and a stack of its rounds) fits
            local cap = safe(function() return hinv:get_field("_Slots"):call("get_Count") end) or 8
            local function grow()
                local from = size_of(hinv)
                pcall(hinv.set_field, hinv, "_CurrentSlotSize", math.min(cap, from + 2))
                for k = from, size_of(hinv) - 1 do pcall(hinv.call, hinv, SETSLOT_SIG, k, -1, 0, 0, -1, nil) end   -- (nothing left over there)
            end
            for _ = 1, 6 do
                if P.weapon_room(hinv, wt, 0) or size_of(hinv) >= cap then break end
                grow()
            end
            if not P.weapon_room(hinv, wt, 0) then st.toast = { text = "No room for another gun", until_t = os.clock() + 2.5 }; return end
            P.put_weapon(hinv, { wt = wt, parts = 0, bullet = w.ammo or 0, num = w.num })
            if w.ammo and not junk_item(w.ammo) then
                local stack, free = P.room(hinv, w.ammo)
                if stack <= 0 and free <= 0 and size_of(hinv) < cap then grow() end
            end
            local j
            for _, e in ipairs(P.list(hinv)) do if e.wt == wt then j = e.i end end
            if j then pcall(hinv.call, hinv, "setShortcutSlot(System.Int32, app.ropeway.EquipmentDefine.Shortcut)", j, sc) end
        end
        top_reserve(hinv, w)
        if P.DIR_KEY[sc] then st[P.DIR_KEY[sc]] = wt end
        P.fix_shortcuts(hinv)
        saved()
    end
    function P.station_set_grenade(wt)
        local hinv = hunk_inv()
        if hinv == nil then return end
        local g
        for _, e in ipairs(P.list(hinv)) do if e.wt == 65 or e.wt == 66 then g = e end end
        if g then pcall(hinv.call, hinv, SETSLOT_SIG, g.i, wt, 0, 0, 3, nil)
        else P.put_weapon(hinv, { wt = wt, parts = 0, bullet = 0, num = 3 }) end
        st.throwable = wt
        P.fix_shortcuts(hinv)
        saved()
    end
    -- full magazines, two magazines of spare rounds for every gun, three grenades, a new
    -- knife, and the support item if he has none
    function P.restock()
        local hinv = hunk_inv()
        if hinv == nil then return false end
        local knife = false
        for _, e in ipairs(P.list(hinv)) do if e.wt == 46 then knife = true end end
        if not knife then P.put_weapon(hinv, { wt = 46, parts = 0, bullet = 0, num = 1000 }) end
        for _, e in ipairs(P.list(hinv)) do
            local sl = slot_obj(hinv, e.i)
            if e.wt == 65 or e.wt == 66 then pcall(sl.call, sl, "set_Number", 3)
            elseif e.wt > 0 then
                local max = safe(function() return sl:call("get_MaxNumber") end)
                if max and max > 0 then pcall(sl.call, sl, "set_Number", max) end
                top_reserve(hinv, WEAPON_BY_WT[e.wt])
            end
        end
        local sup = st.p2_support or 2
        if (safe(function() return hinv:call("getNumber(app.ropeway.gamemastering.Item.ID)", sup) end) or 0) == 0 then P.put_item(hinv, sup, 1) end
        P.fix_shortcuts(hinv)
        saved()
        return true
    end
    -- called when player 2 presses A at an item: false = don't pick it up
    function P.before_pickup(si)
        P.expect = nil
        if st.infinite_ammo or st.p2_pickups == false or st.ai_partner() then return true end
        local hinv = hunk_inv()
        if hinv == nil or P.prov_addr ~= (st.hunk and st.hunk:get_address()) then return true end
        local function f(k, d) return safe(function() return si:get_field(k) end) or d end
        local e = { id = f("Type", 0), wt = f("WeaponType", -1), parts = f("WeaponParts", 0), bullet = f("BulletId", 0), count = f("Count", 1),
            add_id = f("AdditionalItemId", 0), add_wt = f("AdditionalWeaponId", -1), add_count = f("AdditionalItemCount", 0) }
        if not P.p2_item(e.id, e.wt) then return true end   -- (to player 1, as before)
        local n, free = P.room(hinv, e.id, e.wt)
        if free == 0 and (e.wt > 0 or n < e.count) then
            st.toast = { text = st.p2_name() .. "'s inventory is full", until_t = os.clock() + 2.5 }
            return false
        end
        e.give_up = st.frame + 90
        e.si = si   -- (v414b: the world item, made to vanish once it's his)
        P.expect = e
        return true
    end
    -- what player 2 picked up goes into his inventory (what doesn't fit: player 1's)
    local function grant(e)
        local hinv, leon = hunk_inv(), leon_inv()
        local got = {}
        local function give(id, wt, num, parts, bullet)
            if wt and wt > 0 then
                if hinv and P.put_weapon(hinv, { wt = wt, parts = parts, bullet = bullet, num = num }) then got[#got + 1] = item_name(nil, wt); return end
                if leon then P.put_weapon(leon, { wt = wt, parts = parts, bullet = bullet, num = num }); got[#got + 1] = item_name(nil, wt) .. " (to " .. st.p1_name() .. ")" end
            elseif id and id > 0 and num > 0 then
                local moved = (hinv and P.p2_item(id, -1)) and P.put_item(hinv, id, num) or 0
                local rest = num - moved
                if rest > 0 and leon then rest = rest - P.put_item(leon, id, rest) end
                got[#got + 1] = item_name(id) .. " x" .. num .. (moved < num and (" (" .. (num - moved - rest) .. " to " .. st.p1_name() .. ")") or "")
                if rest > 0 then note("pickup: " .. rest .. " of item " .. id .. " had nowhere to go") end
            end
        end
        give(e.id, e.wt, e.count, e.parts, e.bullet)
        if (e.add_id or 0) > 0 or (e.add_wt or -1) > 0 then give(e.add_id, e.add_wt, e.add_count or 1, 0, 0) end
        if hinv then pcall(P.fix_shortcuts, hinv) end
        st.toast = { text = st.p2_name() .. " took " .. table.concat(got, ", "), until_t = os.clock() + 2.5 }
        note("pickup: " .. table.concat(got, ", "))
        local cap = hinv and P.capture(hinv)
        if cap then P.data.live = cap; write() end
    end
    -- (v414) The pick-up locks the game's interactions for player 1 until its screen closes
    -- (InteractManager.requestTriggerLockForGetItem: _TriggerLockOwnerForItem = the world item,
    -- IsTriggerLock true). With the screen skipped, nothing released it: player 1 stayed in a
    -- pick-up (InteractManager restriction "Invincible" on her, no pause or inventory, and no
    -- enemy grabbed anyone). Released a couple of frames after the item is his, and again over
    -- the next 2 s in case the pick-up's own sequence locks it a second time.
    -- (v414b) A knife pulled from an enemy (WP4500FromEnemy) only leaves the world when the
    -- screen takes it, and our A press was still being held on its trigger (st.force_trig_addr,
    -- st.pick: 6 frames): once the lock went, the pick-up ran again and opened player 1's
    -- screen for a second knife. Now the press ends at once and the world item is vanished
    -- (SetItem.setVanish) if it's still there.
    local function release_pick_lock()
        local imgr = sdk.get_managed_singleton("app.ropeway.gimmick.action.InteractManager")
        local owner = imgr and safe(function() return imgr:get_field("_TriggerLockOwnerForItem") end)
        if owner == nil then return false end
        pcall(imgr.call, imgr, "clearTriggerLock(via.GameObject)", owner)
        return true
    end
    P.release_pick_lock = release_pick_lock
    do
        local m = sdk.find_type_definition("app.ropeway.gui.GUIMaster"):get_method("openInventoryGetItemMode")
        if m then
            sdk.hook(m, function(args)
                local e = P.expect
                if e == nil or st.frame > e.give_up then return end
                P.expect = nil
                local ok, err = pcall(grant, e)
                if not ok then note("pickup error: " .. tostring(err)) end
                -- our A press on the trigger ends here (held on, it ran the pick-up again)
                st.pick, st.force_trig_addr = nil, nil
                -- the world item goes, if the game hasn't taken it already (a knife from an enemy)
                if e.si then
                    pcall(function()
                        local go = e.si:call("get_GameObject")
                        if go and go:call("get_DrawSelf") then
                            e.si:call("setVanish")
                            note("pickup: world item vanished (" .. tostring(go:call("get_Name")) .. ")")
                        end
                    end)
                end
                P.unlock_from, P.unlock_until = st.frame + 2, st.frame + 120
                return sdk.PreHookResult.SKIP_ORIGINAL
            end, function(r) return r end)
        end
    end
    -- (runs every frame from main, whatever the ammo mode: v414)
    function P.unlock_tick()
        if P.unlock_until == nil then return end
        if st.frame > P.unlock_until then P.unlock_until = nil; return end
        if st.frame < (P.unlock_from or 0) then return end
        if (st.frame == P.unlock_from or st.frame % 10 == 0) and release_pick_lock() then note("pickup: released player 1's pick-up lock") end
    end
    function P.pickup_tick()
        local e = P.expect
        if e and st.frame > e.give_up then P.expect = nil end
    end
    -- Which save file: the request names it (mode + slot; slot 0 is the autosave), the write /
    -- read that follows doesn't (SaveGameDataIndex still held the last manual slot during an
    -- autosave). Keyed by the game's own save data index for that mode and slot.
    local sdm_td = sdk.find_type_definition("app.ropeway.gamemastering.SaveDataManager")
    local function sdm() return sdk.get_managed_singleton("app.ropeway.gamemastering.SaveDataManager") end
    local function i32(a) return sdk.to_int64(a) & 0xFFFFFFFF end
    local function key_of(mode, slot)
        local idx = safe(function() return sdm():call("getSaveDataIndex", mode, slot) end)
        return tostring(idx or slot) .. "@" .. tostring(mode)
    end
    local function cur_mode() return safe(function() return sdm():call("getSaveModeFromCurrentScenarioType") end) or 0 end
    local function hook(name, pre)
        local m = sdm_td and sdm_td:get_method(name)
        if m then sdk.hook(m, function(args) pcall(pre, args) end, function(r) return r end) else note("no " .. name) end
    end
    hook("requestSaveGameData", function(args) P.save_key = key_of(i32(args[3]), i32(args[4])) end)
    hook("requestSaveGameDataAuto", function() P.save_key = key_of(cur_mode(), 0) end)
    hook("requestLoadGameData", function(args) P.load_key = key_of(i32(args[3]), i32(args[4])) end)
    hook("requestLoadLatestGameData", function(args)
        local mode = i32(args[3])
        P.load_key = key_of(mode, sdm():call("getLastTimeStampSlotIndex", mode))
    end)
    hook("requestLoadLastUseGameDataSenario", function()
        local mode = cur_mode()
        P.load_key = key_of(mode, sdm():call("getLastUseSlotIndex", mode))
    end)
    -- the game writes a save: keep what player 2 carries with it
    hook("saveGameSaveData", function()
        local key = P.save_key or ("?" .. tostring(safe(function() return sdm():call("get_SaveGameDataIndex") end)))
        P.save_key = nil
        local hinv = not st.infinite_ammo and not P.hold and P.prov_addr and st.hunk and st.hunk:get_address() == P.prov_addr and hunk_inv()
        local cap = hinv and P.capture(hinv)
        if cap then P.data.live = cap end
        local rec = copy(P.data.live)
        if rec then rec.t, rec.guid = clock_s(), save_guid() end   -- (the save's own clock / playthrough)
        P.data.saves[key] = rec
        write()
        note("save " .. key .. ": " .. (rec and (#rec.slots .. " slots") or "nothing"))
    end)
    -- the game loads a save (load menu, continue after a game over, title screen): player 2
    -- gets what was kept with that save (nothing kept: the starter kit)
    -- (v398) Only a load the player asked for (a request* call above: the load menu, Continue,
    -- the title screen) swaps in the save's record. The game also saves and loads by itself
    -- around some cutscenes (Marvin sending you back to the main hall): no request, and the save
    -- and load indices it uses don't match ("?-1" saved, "?0" loaded), so player 2 got an old
    -- record back - the full starting kit, spent rounds and a handed-over knife returned. For
    -- those he keeps what he carries now (live, snapshotted first).
    hook("loadGameSaveData", function()
        local asked = P.load_key
        P.load_key = nil
        -- (a game over or the title screen on the way here is the player's load too)
        local why = tostring(st.load_why or "")
        if asked == nil and st.unloading and (why:find("^goGameOver") or why:find("^goTitle")) then
            asked = "?" .. tostring(safe(function() return sdm():call("get_LoadGameDataIndex") end))
        end
        pcall(P.snapshot)
        P.hold = true          -- (no reading the old HUNK until the new one is set up)
        P.prov_addr = nil
        if asked == nil then
            -- (the clock goes back with this load: the record isn't "from the future")
            if P.data.live then P.data.live.t = nil; P.data.live.from_save = "the game's own load" end   -- (v428: kept as it is)
            write()
            note("load (the game's own, " .. tostring(safe(function() return sdm():call("get_LoadGameDataIndex") end)) .. "): live kept, "
                .. (P.data.live and (#(P.data.live.slots or {}) .. " slots") or "nothing"))
            return
        end
        local rec = P.data.saves[asked]
        P.data.live = copy(rec)
        if P.data.live then P.data.live.from_save = asked end   -- (v428: see P.valid)
        write()
        note("load " .. asked .. ": " .. (rec and (#(rec.slots or {}) .. " slots kept") or "nothing kept"))
    end)
end)()

-- switch HUNK's sub-weapon to the next knife / grenade (dev bridge; on the pad it's LB + d-pad)
local function toggle_sub_weapon()
    if st.hunk == nil then return end
    -- the next knife / grenade HUNK actually has (any slot), not fixed slots: with his own
    -- inventory the knife isn't always in slot 2 and there may be no grenade at all (switching
    -- to an empty slot left him with nothing in that hand, and stuck)
    local nxt, why = st.p2inv.next_sub()
    if nxt then say("HUNK sub-weapon: " .. tostring(nxt.name):lower()) elseif why then say("HUNK has " .. why) end
end

-- invulnerability ----------------------------------------------------------------
st.invulnerable = true
st.no_grab = true
-- (v406) Child characters (Sherry, both versions: MODELS entries with child = true) are always
-- invincible and can't be grabbed, whatever the settings, the way of play, the difficulty or
-- the AI say. Locked while she is chosen for player 2 or her body (pl3000) is still the one in
-- the game. "Invincible" / "Can't be grabbed" show On and can't be changed then (both menus and
-- the REFramework panel). Anything that sets them meanwhile (a way of play, a difficulty) is
-- kept as the player's choice (st.child_pref, also what gets saved) and comes back when
-- player 2 is someone else. On top of the settings: damage, grabs' killing check and hit
-- reactions on her are refused in the damage hooks (st.child_target), every frame.
st.CHILD_MODELS = st.CHILD_MODELS or {}
function st.p2_child()
    return st.rig == "pl3000" or st.CHILD_MODELS[st.p2_model] == true
end
function st.child_guard()
    local child = st.p2_child()
    if child then
        local pr = st.child_pref
        if pr == nil then
            st.child_pref = { invulnerable = st.invulnerable, no_grab = st.no_grab }
        else
            if st.invulnerable ~= true then pr.invulnerable = st.invulnerable end
            if st.no_grab ~= true and not (st.bb_on and st.bb_on()) then pr.no_grab = st.no_grab end
        end
        st.invulnerable = true
        st.no_grab = not (st.bb_on and st.bb_on())   -- (v407: Biohazard Babysitting, the one exception)
    elseif st.child_pref then
        st.invulnerable = st.child_pref.invulnerable
        st.no_grab = st.child_pref.no_grab
        st.child_pref = nil
    end
    return child
end
local function keep_invulnerable()
    local child = st.child_guard()
    if st.hunk == nil then return end
    local hp = comp(st.hunk, "app.ropeway.HitPointController")
    if hp then
        local on = child or st.invulnerable or st.p2_down ~= nil or (st.p2_down_grace or 0) > st.frame
        -- Invincible also makes grabs miss; with grabs allowed he is only NoDamage (and kept at
        -- full health), so enemies can still take hold of him
        local inv = on and (st.no_grab or child)
        -- (v407) Biohazard Babysitting: Sherry can be grabbed and hits reach the damage hooks
        -- (which refuse them and end the game: st.bb.fail), so neither flag is set
        local bb = child and st.bb_on and st.bb_on()
        if bb then on, inv = false, false end
        safe(function()
            if hp:call("get_Invincible") ~= inv then hp:call("set_Invincible", inv) end
            if hp:call("get_NoDamage") ~= on then hp:call("set_NoDamage", on) end
            if st.invulnerable or child then
                local def = hp:call("get_DefaultHitPoint")
                if hp:call("get_CurrentHitPoint") < def then hp:call("set_CurrentHitPoint", def) end
            end
        end)
    end
    local cond = comp(st.hunk, "app.ropeway.survivor.player.PlayerCondition")
    if cond then safe(function() cond:set_field("<IgnoreGrapple>k__BackingField", (child and not (st.bb_on and st.bb_on())) or st.no_grab or st.p2_down ~= nil) end) end
end

-- Player 2 downed (v316). With Invulnerable off, the hit that would kill HUNK leaves him on 1 HP
-- and knocked to the floor instead: no death. Every way to his death is caught on his own
-- components: HitPointController addDamage / set_CurrentHitPoint taking him to 0 (kept at 1),
-- dead(), SurvivorCondition deadHitPoint(), and setDamageAction(type, dir, isDead = true, kind)
-- (played as a normal hit). He's then knocked down with the game's own heavy fall
-- (setDamageAction TossLarge: DAMAGE_REACTION.DAMAGE.TOSS.LARGE, bank 6 mot 210, 215 frames; flat
-- on his back from frame ~57, up again by ~190) and held there: layer 0 stopped at frame 57.
-- While down he can't be hurt or grabbed and player 2's controller does nothing. Player 1 at
-- his side (1.4 m) pressing her action button helps him up: the motion runs on (he sits up and
-- stands), and he has a quarter of his health, two seconds' grace before he can be hurt again.
do
local DN = { req = nil }
st.down = DN   -- (dev bridge)
local TOSS_LARGE, DOWN_FRAME, MOT = 16974336, 57, 210
local nk_td = sdk.find_type_definition("System.Nullable`1<app.ropeway.EnemyDefine.KindID>")
local addr_cache = {}
local function hunk_comp_addr(tn)
    local e = addr_cache[tn]
    if e and e.frame == st.frame and e.hunk == st.hunk then return e.addr end
    local c = st.hunk and comp(st.hunk, tn)
    e = { frame = st.frame, hunk = st.hunk, addr = c and (c:get_address() & 0xFFFFFFFFFFFF) or nil }
    addr_cache[tn] = e
    return e.addr
end
local function is_hunk(args, tn)
    if st.hunk == nil or st.invulnerable then return false end
    local a = hunk_comp_addr(tn)
    return a ~= nil and (sdk.to_int64(args[2]) & 0xFFFFFFFFFFFF) == a
end
local function int_arg(a)
    local n = sdk.to_int64(a) & 0xFFFFFFFF
    if n >= 0x80000000 then n = n - 0x100000000 end
    return n
end
local HPC, SC = "app.ropeway.HitPointController", "app.ropeway.survivor.player.PlayerCondition"
local htd = sdk.find_type_definition(HPC)
-- (addDamage takes the change: a bite is addDamage(-272), via SurvivorCondition.addDamageHitPoint)
pcall(sdk.hook, htd:get_method("addDamage"), function(args)
    if not is_hunk(args, HPC) then return end
    local n = int_arg(args[3])
    if n >= 0 then return end
    if st.p2_down then return sdk.PreHookResult.SKIP_ORIGINAL end
    local hpc = sdk.to_managed_object(args[2])
    local cur = hpc:call("get_CurrentHitPoint")
    if cur + n < 1 then
        args[3] = sdk.to_ptr((math.min(0, 1 - cur)) & 0xFFFFFFFF)
        DN.req = st.frame
    end
end, function(r) return r end)
-- "would this hit kill him" (checkHitDamage asks it with the hit's damage before applying it):
-- never, for HUNK. A yes is what turns an enemy's grab into its killing version (the zombie
-- eats him), which ends the game whoever the victim is.
pcall(sdk.hook, htd:get_method("checkDead"), function(args)
    thread.get_hook_storage().nd = is_hunk(args, HPC)
end, function(r)
    if thread.get_hook_storage().nd then return sdk.to_ptr(0) end
    return r
end)
pcall(sdk.hook, htd:get_method("set_CurrentHitPoint"), function(args)
    if not is_hunk(args, HPC) then return end
    if int_arg(args[3]) <= 0 then
        args[3] = sdk.to_ptr(1)
        DN.req = st.frame
    end
end, function(r) return r end)
pcall(sdk.hook, htd:get_method("dead"), function(args)
    if not is_hunk(args, HPC) then return end
    DN.req = st.frame
    return sdk.PreHookResult.SKIP_ORIGINAL
end, function(r) return r end)
local ctd = sdk.find_type_definition("app.ropeway.survivor.SurvivorCondition")
pcall(sdk.hook, ctd:get_method("deadHitPoint"), function(args)
    if not is_hunk(args, SC) then return end
    DN.req = st.frame
    return sdk.PreHookResult.SKIP_ORIGINAL
end, function(r) return r end)
pcall(sdk.hook, ctd:get_method("setDamageAction"), function(args)
    if DN.own or not is_hunk(args, SC) then return end
    if (sdk.to_int64(args[5]) & 0xFF) ~= 0 then
        args[5] = sdk.to_ptr(0)   -- (a death blow: played as a hit, then he goes down)
        DN.req = st.frame
    end
end, function(r) return r end)

-- (v406) child player 2 (st.p2_child): no damage, never "would this kill", no hit reactions
function st.child_target(args, tn)
    if st.hunk == nil or not st.p2_child() then return false end
    local a = hunk_comp_addr(tn)
    return a ~= nil and (sdk.to_int64(args[2]) & 0xFFFFFFFFFFFF) == a
end
-- (v407) Biohazard Babysitting (st.bb): anything that would hurt her is refused all the same, and
-- ends the game (st.bb.fail)
local function bb_fail(why) if st.bb and st.bb_on and st.bb_on() then pcall(st.bb.fail, why) end end
pcall(sdk.hook, htd:get_method("addDamage"), function(args)
    if st.child_target(args, HPC) and int_arg(args[3]) < 0 then bb_fail("damage " .. int_arg(args[3])); return sdk.PreHookResult.SKIP_ORIGINAL end
end, function(r) return r end)
pcall(sdk.hook, htd:get_method("checkDead"), function(args)
    thread.get_hook_storage().cnd = st.child_target(args, HPC)
end, function(r)
    if thread.get_hook_storage().cnd then return sdk.to_ptr(0) end
    return r
end)
pcall(sdk.hook, htd:get_method("set_CurrentHitPoint"), function(args)
    if not st.child_target(args, HPC) then return end
    local hpc = sdk.to_managed_object(args[2])
    local cur = hpc and hpc:call("get_CurrentHitPoint")
    if cur and int_arg(args[3]) < cur then bb_fail("hit points lowered"); return sdk.PreHookResult.SKIP_ORIGINAL end
end, function(r) return r end)
pcall(sdk.hook, htd:get_method("dead"), function(args)
    if st.child_target(args, HPC) then bb_fail("dead"); return sdk.PreHookResult.SKIP_ORIGINAL end
end, function(r) return r end)
pcall(sdk.hook, ctd:get_method("deadHitPoint"), function(args)
    if st.child_target(args, SC) then return sdk.PreHookResult.SKIP_ORIGINAL end
end, function(r) return r end)
pcall(sdk.hook, ctd:get_method("setDamageAction"), function(args)
    -- (in Babysitting a hit is judged at PlayerCondition.onHitDamage, st.bb: a grab's lunge comes
    -- through here with no damage and must not end the game)
    if st.child_target(args, SC) then return sdk.PreHookResult.SKIP_ORIGINAL end
end, function(r) return r end)

local function knock_down()
    local cond = comp(st.hunk, SC)
    if cond == nil then return false end
    local f = st.hunk:call("get_Transform"):call("get_Rotation") * Vector3f.new(0, 0, 1)
    DN.own = true
    local ok = pcall(cond.call, cond, "setDamageAction", TOSS_LARGE, Vector3f.new(f.x, 0, f.z), false, nk_td and ValueType.new(nk_td))
    DN.own = false
    return ok
end
local function layer0()
    local mo = comp(st.hunk, "via.motion.Motion")
    return mo and mo:call("getLayer", 0)
end
-- Crawling (v320). The zombie's legless motions (em0000_1000_Lost.motlist: 1000 Lost_Idle_Loop,
-- 1101 Lost_Walk_Loop_A, ...) play on HUNK's skeleton: the list is added to his Motion as a
-- DynamicMotionBank (it lands in bank 0, which players don't use) and played on layer 0 with
-- TreeLayer.changeMotion(bank, id, start, blend, mode, curve). His motion tree stays in the
-- TOSS.LARGE damage node meanwhile, and the walk loop's root motion moves him (~0.4 m/s, against
-- walls like any move). Player 2's left stick (camera-relative) turns him and crawls; let go, he
-- lies still (the zombie's crawl idle). Doors open as he crawls into them; ladders, jumps and
-- everything else on his A stay out of reach (his A does nothing while down).
local CRAWL_LIST = "SectionRoot/Animation/Enemy/em0000/list/em0000_1000_Lost.motlist"
local CRAWL_WALK, CRAWL_IDLE = 1101, 1000
local cm_method
do
    for _, m in ipairs(sdk.find_type_definition("via.motion.TreeLayer"):get_methods()) do
        if m:get_name() == "changeMotion" and #m:get_param_types() == 6 then cm_method = m end
    end
end
local function crawl_bank(go)
    go = go or st.hunk
    local mo = go and comp(go, "via.motion.Motion")
    if mo == nil then return false end
    for i = 0, (safe(function() return mo:call("getActiveMotionBankCount") end) or 0) - 1 do
        local b = safe(function() return mo:call("getActiveMotionBank", i) end)
        if b and safe(function() return b:call("get_Name") end) == "em0000_1000_Lost" then return true end
    end
    DN.bank_tries = DN.bank_tries or {}
    local key = go:get_address()
    if st.frame - (DN.bank_tries[key] or -1000) < 30 then return false end
    DN.bank_tries[key] = st.frame
    return pcall(function()
        if DN.crawl_holder == nil then
            local res = sdk.create_resource("via.motion.MotionListResource", CRAWL_LIST)
            DN.crawl_res = res:add_ref()
            DN.crawl_holder = DN.crawl_res:create_holder("via.motion.MotionListResourceHolder"):add_ref()
        end
        local dm = sdk.create_instance("via.motion.DynamicMotionBank"):add_ref()
        dm:call("set_MotionList", DN.crawl_holder)
        DN.crawl_dms = DN.crawl_dms or {}
        DN.crawl_dms[key] = dm
        local n = mo:call("getDynamicMotionBankCount")
        mo:call("setDynamicMotionBankCount", n + 1)
        mo:call("setDynamicMotionBank", n, dm)
    end) and false
end
local function play(ly, bank, id, start, blend)
    if cm_method == nil then return false end
    local ok = pcall(cm_method.call, cm_method, ly, bank, id, start or 0.0, blend or 15.0, 0, 0)
    pcall(ly.call, ly, "set_Speed", 1.0)
    return ok
end
-- player 2's left stick, as a world direction (his camera's in split screen, else the game's)
local function crawl_dir()
    local dev = st.p2_dev
    local a = dev and safe(function() return dev:call("get_AxisL") end)
    if st.crawl_fake then a = { x = st.crawl_fake[1], y = st.crawl_fake[2] } end   -- (dev bridge: a pushed stick)
    if a == nil or (a.x * a.x + a.y * a.y) < 0.09 then return nil end
    local yaw = p2c.active and p2c.yaw or nil
    if yaw == nil then
        local cam = sdk.get_primary_camera()
        local m = cam and safe(function() return cam:call("get_GameObject"):call("get_Transform"):call("get_WorldMatrix") end)
        if m == nil then return nil end
        yaw = math.atan(m[2].x, m[2].z)   -- (forward = -Z)
    end
    local fx, fz = -math.sin(yaw), -math.cos(yaw)
    local rx, rz = math.cos(yaw), -math.sin(yaw)
    return rx * a.x + fx * a.y, rz * a.x + fz * a.y
end
-- (his motion tree leaves the damage node ~25 frames before a motion's end and stands him up,
-- then he's knocked down again: the crawl loops are wound back to their start before that)
-- (restarted with changeMotion, not set_Frame: jumping the frame back replays the loop's root
-- motion backwards, which threw him back along his path, a "teleport")
local function wind(D, ly, mot)
    local e, f = ly:call("get_EndFrame"), ly:call("get_Frame")
    if e and f and e > 60 and f >= e - 40 and st.frame - (D.wound or -100) > 20 then
        D.wound = st.frame
        play(ly, 0, mot, 0.0, 10.0)
    end
end
-- (go / dir_fn / busy: whose body, the stick as a world direction, menu up; player 2's by default,
-- player 1's crawl uses the same: st.crawl_step)
local function crawl_tick(D, ly, mot, bank, go, dir_fn, busy)
    go = go or st.hunk
    if go == st.hunk and st.ai_partner() then return false end
    local ours = bank == 0 and mot >= 1000 and mot < 2000
    if ours then pcall(wind, D, ly, mot) end
    -- (his inventory open: he stays as he is, lying or crawl-resting)
    if busy == nil then busy = st.ig and st.ig.open end
    if busy then
        if ours and mot ~= CRAWL_IDLE then play(ly, 0, CRAWL_IDLE, 0.0, 20.0) end
        D.crawl = false
        return ours
    end
    local dx, dz = (dir_fn or crawl_dir)()
    if dx then
        if not crawl_bank(go) then return ours end
        if not (ours and mot == CRAWL_WALK) then play(ly, 0, CRAWL_WALK, 0.0, 15.0) end
        D.crawl = true
        -- turn toward the stick (2.5 rad/s)
        local xf = go:call("get_Transform")
        local f = xf:call("get_Rotation") * Vector3f.new(0, 0, 1)
        local cur, want = math.atan(f.x, f.z), math.atan(dx, dz)
        local d = (want - cur + math.pi) % (2 * math.pi) - math.pi
        local stp = 2.5 * math.min(0.05, safe(function() return sdk.call_native_func(sdk.get_native_singleton("via.Application"), sdk.find_type_definition("via.Application"), "get_ElapsedSecond") end) or 0.016)
        local y = cur + math.max(-stp, math.min(stp, d))
        xf:call("set_Rotation", Quaternion.new(math.cos(y / 2), 0, math.sin(y / 2), 0))
        return true
    end
    D.crawl = false
    if ours then
        if mot ~= CRAWL_IDLE then play(ly, 0, CRAWL_IDLE, 0.0, 20.0) end
        return true
    end
    return false
end
st.crawl_step = crawl_tick
st.crawl_play = play
function st.p2_go_down()
    if st.hunk == nil or st.p2_down then return end
    st.p2_down = { since = st.frame, tries = 0, last_try = st.frame }
    pcall(knock_down)
    pcall(st.update_enemy_sense)   -- (enemies leave him at once)
end
-- player 1 helps him up
-- (healed: he gets up with what the heal gave him)
function st.p2_revive(healed)
    local D = st.p2_down
    if D == nil or D.rising then return end
    D.rising = st.frame
    D.crawl = false
    local ly = layer0()
    if ly then
        -- (from a crawl: back into the fall's getting-up part)
        if ly:call("get_MotionBankID") == 0 then play(ly, 6, MOT, DOWN_FRAME, 20.0) end
        pcall(ly.call, ly, "set_Speed", 1.0)
    end
    local hpc = comp(st.hunk, HPC)
    if hpc and not healed then pcall(function() hpc:call("set_CurrentHitPoint", math.max(1, math.floor(hpc:call("get_DefaultHitPoint") * 0.25))) end) end
    st.p2_down_grace = st.frame + 120
end
function st.p2_down_tick()
    if DN.req and st.p2_down == nil then
        DN.req = nil
        if st.hunk and not st.invulnerable then st.p2_go_down() end
    end
    local D = st.p2_down
    if D == nil then return end
    -- (a new HUNK: a load / game over made him again)
    if st.hunk == nil or st.invulnerable or (D.hunk_addr and st.hunk:get_address() ~= D.hunk_addr) then st.p2_down = nil; return end
    D.hunk_addr = D.hunk_addr or st.hunk:get_address()
    local hpc = comp(st.hunk, HPC)
    local hp = hpc and safe(function() return hpc:call("get_CurrentHitPoint") end)
    if hpc and not D.rising and hp and hp < 1 then pcall(hpc.call, hpc, "set_CurrentHitPoint", 1); hp = 1 end
    -- healed from his own inventory: up again
    if not D.rising and hp and hp > 1 and st.frame - D.since > 30 then st.p2_revive(true); return end
    local ly = layer0()
    if ly == nil then return end
    local mot, fr = ly:call("get_MotionID"), ly:call("get_Frame")
    local bank = ly:call("get_MotionBankID")
    if D.rising then
        -- (up: the fall motion has played out, or 4 s at most)
        if (mot ~= MOT and st.frame - D.rising > 10) or st.frame - D.rising > 240 then st.p2_down = nil end
        return
    end
    -- crawling (or lying still after a crawl)
    local okc, crawling = false, false
    if D.held and st.crawl ~= false then okc, crawling = pcall(crawl_tick, D, ly, mot, bank); DN.crawl_err = not okc and crawling or nil end
    if okc and crawling then
        -- (nothing else: the zombie motion is his)
    elseif mot == MOT and fr >= DOWN_FRAME then
        ly:call("set_Speed", 0.0)
        D.held = true
    elseif mot ~= MOT and st.frame - D.last_try > 45 then
        -- (something else took over his body: knocked down again)
        D.last_try, D.tries, D.held = st.frame, D.tries + 1, false
        pcall(knock_down)
    end
    -- player 1 at his side
    local p1 = p1_go()
    local near = false
    if p1 then
        local a = p1:call("get_Transform"):call("get_Position")
        local b = st.hunk:call("get_Transform"):call("get_Position")
        near = math.abs(a.y - b.y) < 1.0 and ((a.x - b.x) ^ 2 + (a.z - b.z) ^ 2) < 1.4 * 1.4
    end
    D.near = near and D.held
    -- (her action button, read off her own input unit: the game only asks for it when something
    -- it knows of is in reach, so nothing asks while she stands over him)
    if D.near then
        local is = sdk.get_managed_singleton("app.ropeway.InputSystem")
        local u = is and safe(function() return is:call("getActiveUserInputUnit") end)
        if u and safe(function() return u:call("isDown", 8192) end) == true then D.press = st.frame end
    end
    if D.near and D.press and D.press >= st.frame - 1 then st.p2_revive() end
    D.press = nil
end
-- (player 1's action button while she's next to him: his, not the game's)
function st.p2_down_action(short)
    local D = st.p2_down
    if not (D and D.near and not D.rising) then return nil end
    return true
end
end

-- Player 1 downed too (v338, split screen with a human player 2): the hit that would kill her
-- leaves her on 1 HP, knocked down with the same heavy fall and held on her back, as for player 2
-- (same catches on her own HitPointController / condition, the "would this kill" check answered
-- no). While she's down she can't be hurt or grabbed, her controller only reaches her menus (her
-- inventory: a heal gets her up), and the enemies go for player 2. Player 2 at her side (1.4 m)
-- pressing A helps her up (a quarter of her health). Both down at once: the game is over - she's
-- let die (the game's own death and YOU ARE DEAD). No player 2, the AI partner or one screen:
-- none of this, she dies as in the game. st.p1_downed = false: off.
do
local D1N = { req = nil }
st.down1 = D1N   -- (dev bridge)
local TOSS_LARGE, DOWN_FRAME, MOT = 16974336, 57, 210
local nk_td = sdk.find_type_definition("System.Nullable`1<app.ropeway.EnemyDefine.KindID>")
local HPC, SC = "app.ropeway.HitPointController", "app.ropeway.survivor.player.PlayerCondition"
local function active()
    return st.p1_downed ~= false and st.split and not st.ai_partner() and st.hunk ~= nil and not D1N.let_die
end
st.p1_down_active = active
local addr_cache = {}
local function p1_addr(tn)
    local e = addr_cache[tn]
    if e and e.frame == st.frame then return e.addr end
    local p1 = p1_go()
    local c = p1 and comp(p1, tn)
    e = { frame = st.frame, addr = c and (c:get_address() & 0xFFFFFFFFFFFF) or nil }
    addr_cache[tn] = e
    return e.addr
end
local function is_p1(args, tn)
    if not active() then return false end
    local a = p1_addr(tn)
    return a ~= nil and (sdk.to_int64(args[2]) & 0xFFFFFFFFFFFF) == a
end
local function int_arg(a)
    local n = sdk.to_int64(a) & 0xFFFFFFFF
    if n >= 0x80000000 then n = n - 0x100000000 end
    return n
end
local htd = sdk.find_type_definition(HPC)
pcall(sdk.hook, htd:get_method("addDamage"), function(args)
    if not is_p1(args, HPC) then return end
    local n = int_arg(args[3])
    if n >= 0 then return end
    if st.p1_down then return sdk.PreHookResult.SKIP_ORIGINAL end
    local hpc = sdk.to_managed_object(args[2])
    local cur = hpc:call("get_CurrentHitPoint")
    if cur + n < 1 then
        args[3] = sdk.to_ptr((math.min(0, 1 - cur)) & 0xFFFFFFFF)
        D1N.req = st.frame
    end
end, function(r) return r end)
pcall(sdk.hook, htd:get_method("checkDead"), function(args)
    thread.get_hook_storage().nd1 = is_p1(args, HPC)
end, function(r)
    if thread.get_hook_storage().nd1 then return sdk.to_ptr(0) end
    return r
end)
pcall(sdk.hook, htd:get_method("set_CurrentHitPoint"), function(args)
    if not is_p1(args, HPC) then return end
    if int_arg(args[3]) <= 0 then args[3] = sdk.to_ptr(1); D1N.req = st.frame end
end, function(r) return r end)
pcall(sdk.hook, htd:get_method("dead"), function(args)
    if not is_p1(args, HPC) then return end
    D1N.req = st.frame
    return sdk.PreHookResult.SKIP_ORIGINAL
end, function(r) return r end)
local ctd = sdk.find_type_definition("app.ropeway.survivor.SurvivorCondition")
pcall(sdk.hook, ctd:get_method("deadHitPoint"), function(args)
    if not is_p1(args, SC) then return end
    D1N.req = st.frame
    return sdk.PreHookResult.SKIP_ORIGINAL
end, function(r) return r end)
pcall(sdk.hook, ctd:get_method("setDamageAction"), function(args)
    if D1N.own or not is_p1(args, SC) then return end
    if (sdk.to_int64(args[5]) & 0xFF) ~= 0 then args[5] = sdk.to_ptr(0); D1N.req = st.frame end
end, function(r) return r end)

local function damage_action(go, dead)
    local cond = comp(go, SC)
    if cond == nil then return false end
    local f = go:call("get_Transform"):call("get_Rotation") * Vector3f.new(0, 0, 1)
    D1N.own = true
    local ok = pcall(cond.call, cond, "setDamageAction", TOSS_LARGE, Vector3f.new(f.x, 0, f.z), dead == true, nk_td and ValueType.new(nk_td))
    D1N.own = false
    return ok
end
local function layer0(go)
    local mo = go and comp(go, "via.motion.Motion")
    return mo and mo:call("getLayer", 0)
end
-- her left stick (read off her own input unit: the game's own reads of it are blocked while she's
-- down), as a world direction from her camera
local function p1_dir()
    local a
    if st.crawl_fake1 then a = { x = st.crawl_fake1[1], y = st.crawl_fake1[2] } end   -- (dev bridge)
    if a == nil then
        local is = sdk.get_managed_singleton("app.ropeway.InputSystem")
        local u = is and safe(function() return is:call("getActiveUserInputUnit") end)
        local stick = u and safe(function() return u:call("getStick", 1) end)
        a = stick and safe(function() return stick:call("get_Axis") end)
    end
    if a == nil and st.p1_dev then a = safe(function() return st.p1_dev:call("get_AxisL") end) end
    if a == nil or (a.x * a.x + a.y * a.y) < 0.09 then return nil end
    local cam = sdk.get_primary_camera()
    local m = cam and safe(function() return cam:call("get_GameObject"):call("get_Transform"):call("get_WorldMatrix") end)
    if m == nil then return nil end
    local yaw = math.atan(m[2].x, m[2].z)
    local fx, fz = -math.sin(yaw), -math.cos(yaw)
    local rx, rz = math.cos(yaw), -math.sin(yaw)
    return rx * a.x + fx * a.y, rz * a.x + fz * a.y
end
-- her protection while down (and a short grace after). Off is plain off: nothing else in the game
-- or the mod sets these on player 1, and saving "what she had" picked up the mod's own protection
-- after a script reset while she was down (she stayed invincible and ungrabbable once up).
-- the enemies turned onto him while she was down: let go of him again (their own senses and the
-- mod's sight rules pick between the two players from here), and told she's there
local function unboost()
    local B = D1N.boosted
    D1N.boosted = nil
    if B == nil then return end
    local p1 = p1_go()
    for _, hc in pairs(B) do
        pcall(function()
            if st.hunk then hc:call("lose", st.hunk) end
            if p1 then hc:call("find", p1, 5) end
        end)
    end
end
st.p1_unboost = unboost
local function guard(on)
    local p1 = p1_go()
    if p1 == nil then return end
    local hpc = comp(p1, HPC)
    local cond = comp(p1, SC)
    if hpc then pcall(hpc.call, hpc, "set_NoDamage", on); pcall(hpc.call, hpc, "set_Invincible", on) end
    if cond then pcall(cond.set_field, cond, "<IgnoreGrapple>k__BackingField", on) end
    D1N.guarded = on
end
function st.p1_go_down()
    local p1 = p1_go()
    if p1 == nil or st.p1_down then return end
    st.p1_down = { since = st.frame, last_try = st.frame, addr = p1:get_address() }
    guard(true)
    pcall(damage_action, p1, false)
end
function st.p1_revive(healed)
    local D = st.p1_down
    if D == nil or D.rising then return end
    D.rising = st.frame
    D.crawl = false
    pcall(unboost)
    local p1 = p1_go()
    local ly = layer0(p1)
    if ly then
        -- (from a crawl: back into the fall's getting-up part, as for player 2)
        if ly:call("get_MotionBankID") == 0 and st.crawl_play then st.crawl_play(ly, 6, MOT, DOWN_FRAME, 20.0) end
        pcall(ly.call, ly, "set_Speed", 1.0)
    end
    local hpc = p1 and comp(p1, HPC)
    if hpc and not healed then pcall(function() hpc:call("set_CurrentHitPoint", math.max(1, math.floor(hpc:call("get_DefaultHitPoint") * 0.25))) end) end
    D1N.grace = st.frame + 120
end
-- both down: the game takes it from here (her real death, the game over). Her health goes to 0
-- before the fall is called as a death (called at 1 it's only a knock-down and she got up again),
-- and the grab guard (which puts back her health while he's held) is told to stand off. If the
-- game doesn't start its own game over, it's started directly.
local function mf_over()
    local mf = sdk.get_managed_singleton("app.ropeway.gamemastering.MainFlowManager")
    if mf == nil then return nil, nil end
    local over = safe(function() return mf:call("get_IsInGameOver") end) == true
    local stt = safe(function() return mf:get_field("_CurrentMainState") end)
    return mf, over or stt == 7
end
local function let_die()
    D1N.let_die, D1N.died_at, D1N.over_seen, D1N.forced = true, st.frame, false, false
    if st.grab_guard then st.grab_guard.until_f, st.grab_guard.hp, st.grab_guard.addr = nil, nil, nil end
    guard(false)
    local p1 = p1_go()
    if p1 == nil then return end
    D1N.died_addr = p1:get_address()
    local ly = layer0(p1)
    if ly then pcall(ly.call, ly, "set_Speed", 1.0) end
    local hpc = comp(p1, HPC)
    if hpc then
        pcall(hpc.call, hpc, "set_NoDamage", false); pcall(hpc.call, hpc, "set_Invincible", false)
        pcall(hpc.call, hpc, "set_CurrentHitPoint", 0)
    end
    local cond = comp(p1, SC)
    if cond then pcall(cond.call, cond, "deadHitPoint") end
    if hpc then pcall(hpc.call, hpc, "dead") end
    pcall(damage_action, p1, true)
    st.p1_down = nil
end
st.p1_let_die = let_die   -- (dev bridge)
function st.p1_down_tick()
    -- (once after the script starts: protection left on her by a run before a reset goes, unless
    -- she's down; a downed state picked up again sets it again)
    if not D1N.cleaned and p1_go() then
        D1N.cleaned = true
        if st.p1_down == nil then guard(false) end
    end
    if D1N.let_die then
        -- (the game over / reload makes her again: ready once she's back in play, alive and well)
        local p1 = p1_go()
        local mf, over = mf_over()
        if over then D1N.over_seen = true end
        local stt = mf and safe(function() return mf:get_field("_CurrentMainState") end)
        if (D1N.over_seen or (p1 and p1:get_address() ~= D1N.died_addr)) and stt == 6 then
            local hpc = p1 and comp(p1, HPC)
            local hp = hpc and safe(function() return hpc:call("get_CurrentHitPoint") end)
            if hp and hp > 1 then D1N.let_die, D1N.died_addr = nil, nil end
            return
        end
        -- (no game over yet: she stays at 0. The game's own death plays out if it started (6 s at
        -- most); if she's only in the fall, she stays down on the floor and the game over is
        -- started directly)
        if not D1N.over_seen and p1 and p1:get_address() == D1N.died_addr then
            local hpc = comp(p1, HPC)
            local hp = hpc and safe(function() return hpc:call("get_CurrentHitPoint") end)
            if hp and hp > 0 then pcall(hpc.call, hpc, "set_CurrentHitPoint", 0) end
            local ly = layer0(p1)
            local mot = ly and safe(function() return ly:call("get_MotionID") end)
            local fr = ly and safe(function() return ly:call("get_Frame") end)
            local falling = ly ~= nil and mot == MOT and ly:call("get_MotionBankID") == 6
            if falling and fr and fr >= DOWN_FRAME then pcall(ly.call, ly, "set_Speed", 0.0) end
            local wait = falling and 90 or 360
            D1N.died_mot = mot
            if not D1N.forced and st.frame - (D1N.died_at or st.frame) > wait and mf then
                D1N.forced = true
                pcall(mf.call, mf, "goGameOver", nil)
            end
        end
        return
    end
    if D1N.grace and st.frame > D1N.grace then D1N.grace = nil; if st.p1_down == nil then guard(false) end end
    if D1N.req and st.p1_down == nil then
        D1N.req = nil
        if active() then st.p1_go_down() end
    end
    local D = st.p1_down
    if D == nil then return end
    local p1 = p1_go()
    -- (a load / game over made her again, or the co-op mode changed: back to normal)
    if p1 == nil or p1:get_address() ~= D.addr or not active() then
        st.p1_down = nil
        guard(false)
        pcall(unboost)
        return
    end
    if not D.rising then guard(true) end
    local hpc = comp(p1, HPC)
    local hp = hpc and safe(function() return hpc:call("get_CurrentHitPoint") end)
    if hpc and not D.rising and hp and hp < 1 then pcall(hpc.call, hpc, "set_CurrentHitPoint", 1); hp = 1 end
    if not D.rising and hp and hp > 1 and st.frame - D.since > 30 then st.p1_revive(true); return end
    local ly = layer0(p1)
    if ly == nil then return end
    local mot, fr = ly:call("get_MotionID"), ly:call("get_Frame")
    if D.rising then
        if (mot ~= MOT and st.frame - D.rising > 10) or st.frame - D.rising > 240 then
            st.p1_down = nil
            D1N.grace = math.max(D1N.grace or 0, st.frame + 60)   -- (a moment more, then she can be hurt)
        end
        return
    end
    -- crawling (as player 2 does: st.crawl_step with her stick and her camera)
    local okc, crawling = false, false
    if D.held and st.crawl ~= false and st.crawl_step then
        okc, crawling = pcall(st.crawl_step, D, ly, mot, ly:call("get_MotionBankID"), p1, p1_dir, (p2c.menu_open and p2c.menu_open()) or false)
        D1N.crawl_err = not okc and crawling or nil
    end
    if okc and crawling then
        -- (the zombie motion is hers)
    elseif mot == MOT and fr >= DOWN_FRAME then
        ly:call("set_Speed", 0.0)
        D.held = true
    elseif mot ~= MOT and st.frame - D.last_try > 45 then
        D.last_try, D.held = st.frame, false
        pcall(damage_action, p1, false)
    end
    -- both down (and both settled on the floor): game over
    if D.held and st.p2_down and st.p2_down.held then let_die(); return end
    -- player 2 at her side
    local near = false
    if st.hunk and not st.p2_down then
        local a = p1:call("get_Transform"):call("get_Position")
        local b = st.hunk:call("get_Transform"):call("get_Position")
        near = math.abs(a.y - b.y) < 1.0 and ((a.x - b.x) ^ 2 + (a.z - b.z) ^ 2) < 1.4 * 1.4
    end
    D.near = near and D.held
    -- the enemies go for him: every few frames each one near is told it sees him, and he
    -- outranks her on its list
    if st.frame % 6 == 0 and st.hunk and not st.p2_down then
        D1N.boosted = D1N.boosted or {}
        pcall(function()
            local em = sdk.get_managed_singleton("app.ropeway.EnemyManager")
            local list = em:call("get_ActiveEnemyList")
            local ha, la = st.hunk:get_address(), p1:get_address()
            for i = 0, list:call("get_Count") - 1 do
                pcall(function()
                    local ctrl = list:call("get_Item", i)
                    if ctrl:call("get_IsLive") == false then return end
                    local hc = comp(ctrl:call("get_GameObject"), "app.ropeway.EnemyHateController")
                    if hc == nil then return end
                    -- (his hate kept a set margin over hers, not piled up: it's undone when she's up)
                    hc:call("find", st.hunk, 5)
                    local l = hc:get_field("<HateTargetList>k__BackingField")
                    local h2e, h1 = nil, 0
                    for j = 0, (l and l:call("get_Count") or 0) - 1 do
                        local h = l:call("get_Item", j)
                        local t = h and h:call("get_TargetGameObject")
                        if t and t:get_address() == ha then h2e = h elseif t and t:get_address() == la then h1 = h:call("get_Hate") or 0 end
                    end
                    if h2e then h2e:call("set_Hate", h1 + 200.0) else hc:call("addHate", st.hunk, h1 + 200.0) end
                    D1N.boosted[hc:get_address()] = hc:add_ref()
                end)
            end
        end)
    end
end
-- her controller while she's down: moving, aiming, shooting, using things all do nothing; menus
-- (inventory, map, pause) still open and work
local BLOCK = { [1] = true, [4] = true, [8] = true, [16] = true, [32] = true, [64] = true, [128] = true, [256] = true,
    [512] = true, [2048] = true, [4096] = true, [8192] = true, [32768] = true, [262144] = true,
    [17179869184] = true, [34359738368] = true, [68719476736] = true, [137438953472] = true }
function st.p1_down_block(kind)
    local D = st.p1_down
    return D ~= nil and not D.rising and BLOCK[kind] == true
end
end

-- Player 2 grabbed / bitten: the game's grab damage goes to "the player", so player 1 lost
-- health while an enemy had hold of HUNK. While HUNK is held (and player 1 isn't), and for a
-- second after, damage to player 1 is refused (HitPointController addDamage / lowering
-- set_CurrentHitPoint) and anything that still got through is put back each frame. What was
-- refused is counted in st.p2_grab_damage (for a health system for player 2 later).
-- Player 1 left held by a dead enemy. A dog's floor grab (and other holds) only ends through the
-- game's own escape / finish, which nothing in single player can interrupt. When player 2 kills the
-- enemy mid-hold, player 1's JackDominator stays "jacked" by a corpse and she can't move again.
-- If player 1 is held by an enemy that is dead (or gone) for 0.75 s, the hold is released, more
-- firmly each try: rejectSelf, then a release request for that owner, then the jack action is
-- force-terminated too. st.p1_release.log keeps what happened (last 20 entries).
do
    local W = { since = nil, tries = 0, next_at = 0, log = {} }
    st.p1_release = W
    local function note(t)
        W.log[#W.log + 1] = string.format("[%d] %s", st.frame, t)
        if #W.log > 20 then table.remove(W.log, 1) end
    end
    function st.p1_release_tick()
        local p1 = p1_go()
        local jd = p1 and comp(p1, "app.ropeway.JackDominator")
        if jd == nil then W.since = nil; return end
        if safe(function() return jd:call("get_Jacked") end) ~= true then
            if W.since then note("player 1 free again after " .. W.tries .. " tries"); W.since, W.tries = nil, 0 end
            return
        end
        local info = safe(function() return jd:get_field("<JackOwner>k__BackingField") end)
        local ec = info and safe(function() return info:call("get_EnemyController") end)
        if ec == nil then W.since = nil; return end   -- not held by an enemy (ladders, gimmicks...)
        local live = safe(function() return ec:call("get_IsLive") end)
        local go = safe(function() return ec:call("get_GameObject") end)
        local valid = go ~= nil and safe(function() return go:call("get_Valid") end) ~= false
        if live ~= false and valid then W.since = nil; return end
        if W.since == nil then W.since, W.tries, W.next_at = st.frame, 0, st.frame + 45; note("held by a dead enemy") end
        if st.frame < W.next_at then return end
        W.tries = W.tries + 1
        W.next_at = st.frame + 20
        local owner = safe(function() return info:call("get_Object") end) or go
        if W.tries == 1 then
            note("rejectSelf")
            pcall(jd.call, jd, "rejectSelf")
        elseif W.tries == 2 then
            note("requestReleaseJack")
            pcall(function()
                local req = sdk.create_instance("app.ropeway.JackDominator.ReleaseJackRequest")
                req:call(".ctor(via.GameObject, app.ropeway.JackDominator.ExecutePhase)", owner, 0)
                jd:call("requestReleaseJack", req)
            end)
        elseif W.tries <= 4 then
            note("forceTerminate + rejectSelf")
            local sj = comp(p1, "app.ropeway.survivor.jack.SurvivorJackActionController")
            if sj then pcall(sj.call, sj, "forceTerminate") end
            pcall(jd.call, jd, "rejectSelf")
        elseif W.tries == 5 then
            note("gave up")
        end
    end
end
st.p2_grab_damage = 0
st.grab_log = {}
do
    local G = { until_f = nil, hp = nil, addr = nil }
    st.grab_guard = G
    local function held(go)
        local c = go and comp(go, "app.ropeway.survivor.player.PlayerCondition")
        return c ~= nil and safe(function() return c:call("get_IsJack") or c:call("get_IsJackFromEnemy") end) == true
    end
    local function note(t)
        local l = st.grab_log
        l[#l + 1] = string.format("[%d] %s", st.frame, t)
        if #l > 40 then table.remove(l, 1) end
    end
    function st.grab_guard_tick()
        -- (both players down: her death isn't undone)
        if st.down1 and st.down1.let_die then G.until_f, G.hp, G.addr = nil, nil, nil; return end
        local p1 = p1_go()
        local on = st.hunk ~= nil and p1 ~= nil and held(st.hunk) and not held(p1)
        if on then G.until_f = st.frame + 60 end
        if G.until_f and (st.frame > G.until_f or p1 == nil or held(p1)) then G.until_f, G.hp, G.addr = nil, nil, nil end
        if G.until_f == nil then return end
        local hpc = comp(p1, "app.ropeway.HitPointController")
        if hpc == nil then return end
        G.addr = hpc:get_address()
        local cur = safe(function() return hpc:call("get_CurrentHitPoint") end)
        if type(cur) ~= "number" then return end
        if G.hp == nil or cur > G.hp then G.hp = cur
        elseif cur < G.hp then
            st.p2_grab_damage = st.p2_grab_damage + (G.hp - cur)
            note(string.format("restored player 1 %d -> %d", cur, G.hp))
            pcall(hpc.call, hpc, "set_CurrentHitPoint", G.hp)
        end
    end
    local function guarding(args)
        return G.addr ~= nil and G.until_f ~= nil and (sdk.to_int64(args[2]) & 0xFFFFFFFFFFFF) == (G.addr & 0xFFFFFFFFFFFF)
    end
    local td = sdk.find_type_definition("app.ropeway.HitPointController")
    local ad = td and td:get_method("addDamage")
    if ad then
        sdk.hook(ad, function(args)
            if not guarding(args) then return end
            local n = sdk.to_int64(args[3]) & 0xFFFFFFFF
            if n >= 0x80000000 then n = n - 0x100000000 end
            if n > 0 then
                st.p2_grab_damage = st.p2_grab_damage + n
                note("refused addDamage " .. n .. " to player 1")
                return sdk.PreHookResult.SKIP_ORIGINAL
            end
        end, function(r) return r end)
    end
    local sc = td and td:get_method("set_CurrentHitPoint")
    if sc then
        sdk.hook(sc, function(args)
            if not guarding(args) or G.hp == nil then return end
            local n = sdk.to_int64(args[3]) & 0xFFFFFFFF
            if n >= 0x80000000 then n = n - 0x100000000 end
            if n < G.hp then
                st.p2_grab_damage = st.p2_grab_damage + (G.hp - n)
                note(string.format("refused set_CurrentHitPoint %d (was %d) for player 1", n, G.hp))
                return sdk.PreHookResult.SKIP_ORIGINAL
            end
        end, function(r) return r end)
    end
end

-- Enemies and player 2 --------------------------------------------------------------
-- The game's enemies only ever sense the current player (Leon / Claire): their sensor looks at
-- EnemyManager.CurrentPlayerObject. Their hate controller (EnemyHateController) keeps a list
-- of targets, though, and chases and attacks whichever one it hates most (its ActionTarget
-- follows; HUNK counts as a player there). So:
-- * visible (st.p2_invisible false): every few frames each enemy near player 2 is given what
--   its own senses would have told it: seeing him (in its view cone and sight range, clear line
--   from its eyes), touching him (right next to it) or hearing his shots. That is find() plus
--   some hate, the same calls the game makes for player 1; the enemy then picks between the
--   two players by its own rules.
-- * invisible: player 2 is taken off every enemy's list (as before this option existed).
st.p2_invisible = true
do
    local SIGHT, TOUCH, HEAR = 14.0, 1.8, 18.0
    local CONE = math.cos(math.rad(65))
    -- (v388) Enemy attention (st.p2_aggro): how far / wide they notice player 2, the head
    -- start in metres player 2 gets when an enemy picks the closer player (normal: player 2
    -- must be 1 m closer), how far ahead of player 1's hate he's put when he wins, and the
    -- share of her hate he keeps when she wins. Most: whenever sensed, player 2 wins.
    local AGGRO = {
        { sight = 10, hear = 12, cone = 55, bias = -3.0, win = 30, keep = 0.3 },
        { sight = 14, hear = 18, cone = 65, bias = -1.0, win = 50, keep = 0.5 },
        { sight = 18, hear = 24, cone = 75, bias = 2.0, win = 150, keep = 0.8 },
        { sight = 24, hear = 30, cone = 85, bias = 1e9, win = 400, keep = 1.0 },
    }
    st.AGGRO_NAMES = { "Less", "Normal", "More", "Most" }
    local SRC = { sound = 3, touch = 4, sight = 5 }   -- HateTargetInfo.FindSourceType
    -- the enemy's hate for player 2 and for player 1 (nil: not on its list)
    local function hates(hc, p1)
        local l = hc:get_field("<HateTargetList>k__BackingField")
        local h2, h1, e2
        for j = 0, (l and l:call("get_Count") or 0) - 1 do
            local h = l:call("get_Item", j)
            local t = h and h:call("get_TargetGameObject")
            if t then
                local a = t:get_address()
                if a == st.hunk:get_address() then h2, e2 = h:call("get_Hate"), h
                elseif p1 and a == p1:get_address() then h1 = h:call("get_Hate") end
            end
        end
        return h2, h1, e2
    end
    st.engaged = {}
    -- Enemies set to go for player 2 only (the debug mod's "hates player 2" spawns): keyed by
    -- GameObject address. Each frame they're told they see him, hate him and not player 1,
    -- whatever Invisible says; dead or gone ones are dropped.
    st.p2_hunters = st.p2_hunters or {}
    function st.p2_hunt(go)
        local hc = go and comp(go, "app.ropeway.EnemyHateController")
        local ctrl = go and comp(go, "app.ropeway.EnemyController")
        if hc == nil or ctrl == nil then return false end
        st.p2_hunters[go:get_address()] = { go = go:add_ref(), hc = hc:add_ref(), ctrl = ctrl:add_ref() }
        return true
    end
    function st.refresh_hunters()
        if st.hunk == nil then return end
        local p1 = p1_go()
        local downed = st.p2_down ~= nil
        for k, e in pairs(st.p2_hunters) do
            if safe(function() return e.go:call("get_Valid") end) ~= true or safe(function() return e.ctrl:call("get_IsLive") end) == false then
                st.p2_hunters[k] = nil
            else
                pcall(function()
                    -- (player 2 downed: unseen, it goes for player 1 until he's up)
                    if downed then
                        if hates(e.hc) ~= nil then e.hc:call("lose", st.hunk) end
                        if p1 then e.hc:call("find", p1, SRC.sight) end
                        return
                    end
                    e.hc:call("find", st.hunk, SRC.sight)
                    local h2, h1 = hates(e.hc, p1)
                    if (h2 or 0) < 1000 then e.hc:call("addHate", st.hunk, 1000 - (h2 or 0)) end
                    if h1 ~= nil and p1 then e.hc:call("lose", p1) end
                end)
            end
        end
    end
    -- (v389) Dormant: the enemy's senses are off (EnemyController SensorOff, or its EnemySensor
    -- not enabled). EnemyController.IsStandby is NOT dormancy: in the city streets every enemy
    -- has it set, chasing ones included (they're "spawn standby" there), and skipping those left
    -- player 2 ignored by everything. As a safety net, an enemy that keeps dropping him as soon
    -- as it's told about him (the game emptying its list) is left alone for 3 s.
    local function dormant(ctrl)
        if safe(function() return ctrl:call("get_SensorOff") end) == true then return true end
        local sn = safe(function() return ctrl:call("get_Sensor") end)
        return sn ~= nil and safe(function() return sn:call("get_SensorEnabled") end) == false
    end
    st.sense_skip = st.sense_skip or {}
    function st.refresh_engaged()
        if st.hunk == nil or st.p2_invisible or st.p2_down then st.engaged = {}; return end
        for k, e in pairs(st.engaged) do
            if st.frame > e.till or safe(function() return e.ctrl:call("get_IsLive") end) == false or dormant(e.ctrl) then
                st.engaged[k] = nil
            else
                pcall(function()
                    -- (not on its list since last frame though we put him there: it threw him out)
                    if e.seen and hates(e.hc) == nil then
                        e.drops = (e.drops or 0) + 1
                        if e.drops >= 6 then st.engaged[k] = nil; st.sense_skip[k] = st.frame + 180; return end
                    end
                    e.hc:call("find", st.hunk, e.src)
                    local h2 = hates(e.hc)
                    e.seen = h2 ~= nil
                    if (h2 or 0) < e.want then e.hc:call("addHate", st.hunk, e.want - (h2 or 0)) end
                end)
            end
        end
    end
    function st.update_enemy_sense()
        if st.hunk == nil then return end
        local em = sdk.get_managed_singleton("app.ropeway.EnemyManager")
        local list = em and em:call("get_ActiveEnemyList")
        if list == nil then return end
        local hp = st.hunk:call("get_Transform"):call("get_Position")
        local chest = Vector3f.new(hp.x, hp.y + 1.3, hp.z)
        local p1 = p1_go()
        local lp = p1 and p1:call("get_Transform"):call("get_Position")
        local shot = st.p2_shot_frame ~= nil and st.frame - st.p2_shot_frame < 12
        local A = AGGRO[st.p2_aggro] or AGGRO[2]
        SIGHT, HEAR, CONE = A.sight, A.hear, math.cos(math.rad(A.cone))
        for i = 0, list:call("get_Count") - 1 do
            pcall(function()
                local ctrl = list:call("get_Item", i)
                local go = ctrl:call("get_GameObject")
                local hc = comp(go, "app.ropeway.EnemyHateController")
                if hc == nil then return end
                -- dead, or a scripted set piece (NoDamage): leave it alone (prodding a dead
                -- one's senses left it standing rigid and shaking)
                if safe(function() return ctrl:call("get_IsLive") end) == false
                    or safe(function() return ctrl:call("get_NoDamage") end) == true then
                    st.engaged[go:get_address()] = nil
                    return
                end
                if st.p2_hunters[go:get_address()] then return end   -- (refresh_hunters has it)
                -- (unseen: the Invisible option, or downed - enemies leave him for player 1)
                if (st.p2_invisible and not st.p1_down) or st.p2_down then
                    if hates(hc) ~= nil then hc:call("lose", st.hunk) end
                    return
                end
                -- dormant (senses off; v389: no longer IsStandby, see dormant()): the game empties
                -- its target list every few frames, for player 1 too (one stood 3 m in front of
                -- Claire and never noticed her). Reporting HUNK to it anyway made it start a turn
                -- toward him, lose him, and start again: the twitching. Leave it to the game,
                -- like player 1; a gunshot it hears or the game waking it brings it back here.
                local key = go:get_address()
                if dormant(ctrl) or (st.sense_skip[key] and st.frame < st.sense_skip[key]) then
                    st.engaged[key] = nil
                    return
                end
                local xf = go:call("get_Transform")
                local p = xf:call("get_Position")
                local dx, dy, dz = hp.x - p.x, hp.y - p.y, hp.z - p.z
                local d = math.sqrt(dx * dx + dy * dy + dz * dz)
                if d > HEAR then return end
                local src
                if d < TOUCH then
                    src = SRC.touch
                elseif d < SIGHT then
                    local f = xf:call("get_Rotation") * Vector3f.new(0, 0, 1)
                    local h = math.sqrt(dx * dx + dz * dz)
                    if h > 0.01 and (f.x * dx + f.z * dz) / h >= CONE then
                        local sensor = comp(go, "app.ropeway.enemy.sensor.EnemySensor")
                        local eye = sensor and safe(function() return sensor:call("getEyeWorldMatrix")[3] end)
                        local from = eye and Vector3f.new(eye.x, eye.y, eye.z) or Vector3f.new(p.x, p.y + 1.6, p.z)
                        if sensor == nil or safe(function() return sensor:call("isThroughSight", from, chest) end) ~= false then src = SRC.sight end
                    end
                end
                if src == nil and shot then src = SRC.sound end
                if src then
                    -- which player it goes for: the closer one it senses (player 1 by the game's
                    -- own senses, player 2 by these), so it doesn't flip-flop between near-equals
                    local h2, h1, e2 = hates(hc, p1)
                    local d1 = lp and math.sqrt((lp.x - p.x) ^ 2 + (lp.y - p.y) ^ 2 + (lp.z - p.z) ^ 2) or 1e9
                    local want
                    if h1 == nil or h1 <= 0 then want = 100
                    elseif d < d1 + A.bias then want = h1 + A.win
                    else want = h1 * A.keep end
                    if src == SRC.sound and h1 == nil then want = math.max(want, 100) end
                    hc:call("find", st.hunk, src)
                    local cur = h2 or 0
                    if cur < want then hc:call("addHate", st.hunk, want - cur)
                    elseif e2 and d > d1 + A.bias + 2.0 then e2:call("set_Hate", want) end   -- player 1 is the closer one now
                    -- its senses keep reporting him every frame until the next look (the game
                    -- drops a target its senses stop reporting within a few frames)
                    st.engaged[go:get_address()] = { hc = hc, ctrl = ctrl, src = src, want = want, till = st.frame + 12 }
                end
            end)
        end
    end
end

-- Enemy LOD: enemies update and animate less the farther they are from player 1
-- (EnemyManager.getLOD: levels by distance, 4 / 8 / 12 / 17 / 25 m), so near player 2 alone
-- they ran choppy and slow to react. An enemy now gets the better of the two levels: by
-- player 1's distance (the game's) or by player 2's.
do
    local m = sdk.find_type_definition("app.ropeway.EnemyManager"):get_method("getLOD")
    if m then
        sdk.hook(m, function(args)
            thread.get_hook_storage().lc = st.hunk and args[3] or nil
        end, function(r)
            local c = thread.get_hook_storage().lc
            if c == nil or st.hunk == nil then return r end
            local ok, out = pcall(function()
                local cur = sdk.to_int64(r) & 0xFFFFFFFF
                local em = sdk.get_managed_singleton("app.ropeway.EnemyManager")
                local prm = em and em:get_field("LODParam")
                if prm == nil then return nil end
                local ctrl = sdk.to_managed_object(c)
                local p = ctrl:call("get_GameObject"):call("get_Transform"):call("get_Position")
                local hp = st.hunk:call("get_Transform"):call("get_Position")
                local d = math.sqrt((p.x - hp.x) ^ 2 + (p.y - hp.y) ^ 2 + (p.z - hp.z) ^ 2)
                local lv = 5
                for i, f in ipairs({ "Level0Distance", "Level1Distance", "Level2Distance", "Level3Distance", "Level4Distance" }) do
                    if d < prm:get_field(f) then lv = i - 1; break end
                end
                if lv < cur then return sdk.to_ptr(lv) end
                return nil
            end)
            if ok and out then return out end
            return r
        end)
    end
end

-- Spawning ----------------------------------------------------------------------

local function beside_p1(dist_back, dist_side, go)
    go = go or p1_go()
    local xf = go and go:call("get_Transform")
    if xf == nil then return nil end
    local pos = xf:call("get_Position")
    local rot = xf:call("get_Rotation")
    local f = rot * Vector3f.new(0, 0, 1)
    local r = rot * Vector3f.new(1, 0, 0)
    return Vector3f.new(pos.x - f.x * dist_back + r.x * dist_side, pos.y, pos.z - f.z * dist_back + r.z * dist_side)
end

local function spawn()
    if st.hunk or st.pending then return end
    local rig = st.rig_for and st.rig_for(st.p2_model) or "pl4000"
    local pfb = sdk.create_instance("via.Prefab"):add_ref()
    safe(function() pfb:call(".ctor") end)
    pfb:call("set_Path", rig == "pl4000" and HUNK_PREFAB or ("ObjectRoot/Prefab/Character/Player/" .. rig .. ".pfb"))
    pfb:call("set_Standby", true)
    st.pending = pfb
    st.pending_rig, st.pending_t = rig, os.clock()
    say("Loading player 2...")
end

-- defined further down (teleport section); declared here so spawning can use them
local spot_near_p1, teleport_to_p1

local function finish_spawn()
    local pfb = st.pending
    st.pending = nil
    st.spawned_at = st.frame   -- (NonRT-1) before instantiate too: its signal can come from inside it
    local pos = spot_near_p1()
    if st.respawn_pos then   -- a rig change: same spot (the game moves a fresh player to its start point: hold him there)
        pos, st.respawn_pos = st.respawn_pos, nil
        st.pin = { pos = pos, rot = st.respawn_rot, until_frame = st.frame + 150 }
        st.respawn_rot = nil
    end
    if pos == nil then say("Load a save first, then spawn HUNK"); return end
    local sm = sdk.get_managed_singleton("app.ropeway.SurvivorManager")
    local folder = sm and safe(function() return sm:call("getInstantiateFolder", ROLE_PLAYER) end)
    local go
    if folder then go = safe(function() return pfb:call("instantiate(via.vec3, via.Folder)", pos, folder) end) end
    if go == nil then go = safe(function() return pfb:call("instantiate(via.vec3)", pos) end) end
    if go == nil then say("HUNK can't be deployed here; try another room"); return end
    -- whatever prefab it came from, to the game and the mod this is player 2 (HUNK):
    -- the mod finds him by name, and the game's survivor type keeps his own inventory
    safe(function() go:call("set_Name", HUNK_NAME) end)
    local cond0 = safe(function() return go:call("getComponent(System.Type)", sdk.typeof("app.ropeway.survivor.player.PlayerCondition")) end)
    if cond0 then safe(function() cond0:set_field("<SurvivorType>k__BackingField", SURVIVOR_PL4000) end) end
    st.rig = st.pending_rig or "pl4000"
    do   -- (v423c) the body's own voice (see st.voice_map_go)
        st.voice_dirty = nil
        local ok, r = pcall(st.voice_map_go, go, st.rig)
        st.voice_note = tostring(r)
        log.info("[reunited] voice: " .. tostring(r))
    end
    st.hunk = go:add_ref()
    st.spawned_at = st.frame   -- (NonRT-1) see before_load
    st.despawned = nil
    clear_comp_cache()
    st.fix_at = st.frame + 10
    st.fix_tries = 0
    say("Deploying HUNK...")
end

-- Player 2's model. The character itself is always HUNK (his moves, his loadout); only
