    { key = "kendo", label = "Robert Kendo", type = 6, anim = 0, prefab = "pl5000", donor = "pl0000" },
    { key = "katherine", label = "Katherine Warren", type = 20, anim = 1, prefab = "pl6400", donor = "pl1000",
      bare = "pl64", wanim = 20, wfolder = "pl20" },
    -- costume 1: Daniel as he starts in the Ghost Survivors (costume 0 has the bitten, bloody neck)
    { key = "daniel", label = "Daniel Cortini", type = 31, costume = 1, anim = 0, prefab = "pl7500", donor = "pl0000" },
    -- story characters
    { key = "irons", label = "Chief Irons", type = 7, anim = 0, prefab = "pl5100", donor = "pl0000" },
    { key = "ben", label = "Ben Bertolucci", type = 8, anim = 0, prefab = "pl5200", donor = "pl0000" },
    { key = "annette", label = "Annette Birkin", type = 9, anim = 1, prefab = "pl5300", donor = "pl1000" },
    { key = "marvin", label = "Marvin Branagh", type = 13, anim = 0, prefab = "pl5700", donor = "pl0000" },
    -- background characters with full bodies but no player prefab: Leon's skeleton and moves
    { key = "pilot", label = "Helicopter pilot", type = 27, anim = 0, prefab = "pl0000" },
    { key = "rpd", label = "Elliot Edward", type = 34, anim = 0, prefab = "pl0000" },
    -- (v415) more background characters (no player prefab; adult male bodies, SurvivorDefine
    -- motion type Male: Leon's moves). The truck driver has two looks: pl7300 "Trucker" and
    -- pl8600 "Driver" (costumes). Checked in game on HUNK's body (s2118).
    -- (v424) Built on Chief Irons' prefab like Irons (his skeleton and voice, Leon's moves),
    -- Leon's as the fallback; Doctor Guy is "Doctor Harold Guy".
    { key = "trucker", label = "Truck Driver", type = 29, anim = 0, prefab = "pl5100", donor = "pl0000" },
    { key = "jerry", label = "Jerry", type = 36, anim = 0, prefab = "pl5100", donor = "pl0000" },
    { key = "doctor", label = "Doctor Harold Guy", type = 41, anim = 0, prefab = "pl5100", donor = "pl0000" },
}
for _, m in ipairs(MODELS) do if m.child then st.CHILD_MODELS[m.key] = true end end   -- (v406) st.p2_child
local MODEL_FALLBACK = { leon = 0, claire = 1, ada = 2, hunk = SURVIVOR_PL4000 }
-- costume ids that load a distinct outfit (checked in game; the others repeat these)
-- { id, name } or { id, name, t = another survivor type, c = its costume } (ids from 100 up
-- for those, e.g. Ghost: HUNK's body with the USS Ghost's head)
-- (v415) prefab: that costume's own player prefab (Ghost: pl5600, his voice and grunts instead
-- of HUNK's; it falls back like a model's prefab); name: what player 2 is called in it
-- (messages, prompts)
local COSTUMES = {
    hunk = { { 0, "HUNK" }, { 100, "Ghost", t = 12, c = 0, prefab = "pl5600", name = "Ghost" } },
    trucker = { { 0, "Trucker" }, { 100, "Driver", t = 42, c = 0 } },
    leon = { { 1, "RPD uniform" }, { 0, "Prologue jacket" }, { 3, "Tank top" }, { 8, "Survivors" },
             { 5, "Classic uniform" }, { 13, "Leon '98" }, { 10, "Noir" }, { 11, "Arklay Sheriff" } },
    claire = { { 0, "Biker jacket" }, { 3, "Tank top" }, { 8, "Survivors" }, { 5, "Classic jacket" },
               { 13, "Claire '98" }, { 11, "Military" }, { 10, "Noir" }, { 12, "Elza Walker" } },
    ada = { { 1, "Red dress" }, { 0, "Trench coat" } },
    -- (v415) Emma Kendo (pl7700, a child body like Sherry's): on Sherry's skeleton, fit and
    -- protection, as a Sherry costume
    sherry = { { 0, "School uniform" }, { 2, "Survivors" }, { 7, "Classic jacket" }, { 5, "Classic school uniform" },
               { 100, "Emma Kendo", t = 33, c = 0, name = "Emma" },
               -- (v434) HUNK's body (small, on her skeleton) with Sherry's own head and hair
               { 101, "Agent: SHERRY", mix = { body = 4, bc = 0, head = 3, hc = 0 } } },
    tofu = { { 0, "Tofu" }, { 1, "Konjac" }, { 3, "Uiro-mochi" }, { 4, "Flan" }, { 2, "Annin Tofu" } },
}
local function model_costume(key)
    local list = COSTUMES[key]
    if list == nil then
        for _, m in ipairs(MODELS) do if m.key == key and m.costume then return m.costume end end
        return 0
    end
    local want = st["costume_" .. key]
    for _, c in ipairs(list) do if c[1] == want then return want end end
    return list[1][1]
end
local survivor_types = nil
local function survivor_type(key)
    for _, m in ipairs(MODELS) do if m.key == key and m.type then return m.type end end
    if survivor_types == nil then
        survivor_types = {}
        local td = sdk.find_type_definition("app.ropeway.SurvivorDefine.SurvivorType")
        for _, f in ipairs(td and td:get_fields() or {}) do
            if f:is_static() then
                local ok, v = pcall(function() return f:get_data(nil) end)
                if ok and type(v) == "number" then survivor_types[f:get_name():lower()] = v end
            end
        end
    end
    for name, v in pairs(survivor_types) do
        if name:find(key, 1, true) then return v end
    end
    return MODEL_FALLBACK[key] or SURVIVOR_PL4000
end
local function model_label(key)
    for _, m in ipairs(MODELS) do if m.key == key then return m.label end end
    return "HUNK"
end
-- (v415) the chosen costume's entry for a model (nil: the model has no costume list)
function st.costume_entry(key)   -- (a field: the main chunk is at its 200-local limit)
    local want = model_costume(key)
    for _, c in ipairs(COSTUMES[key] or {}) do if c[1] == want then return c end end
    return nil
end
-- the player prefab to build player 2 from: the character's own (their skeleton, voice and
-- sounds) unless that's switched off or it failed to load, then the donor, then HUNK
function st.rig_for(key)
    for _, m in ipairs(MODELS) do
        if m.key == key then
            if not st.own_rig then return "pl4000" end
            -- (v415) a costume with a prefab of its own (Ghost), unless it failed to load.
            -- (v422) Off by default (st.costume_rigs): reported after 1.4.2 that every player 2
            -- character sounded like Ghost; his own prefab was the only voice change since 1.4.1.
            -- Ghost is HUNK's body and voice with Ghost's looks again, as in 1.4.1.
            local c = st.costume_entry(key)
            if st.costume_rigs and c and c.prefab and not (st.rig_failed and st.rig_failed[c.prefab]) then return c.prefab end
            if st.rig_failed and st.rig_failed[m.prefab] then return (m.donor and not st.rig_failed[m.donor]) and m.donor or "pl4000" end
            return m.prefab or "pl4000"
        end
    end
    return "pl4000"
end
-- (v423c) Player 2's voice. The game picks a survivor's voice lines with the Wwise switch
-- PL_LOCAL_CHARACTER_TYPE, which the body's WwiseSwitchList sets from SurvivorCondition
-- .SurvivorType through a table of elements (Define = SurvivorType name, SwitchId; e.g. PL1000 ->
-- pl1000, PL5600 Ghost -> pl5700, PL7500 Daniel -> pl5400; no element: SwitchIdInCaseOfUnmatch,
-- pl0000). Player 2's SurvivorType is always PL4000 (HUNK: his own inventory slot), so every
-- character asked their voice bank for HUNK's lines (s2184 / s2188). Right after player 2 is
-- instantiated (before the list starts), the PL4000 element on HUNK's own copy is pointed at the
-- switch of the character the body belongs to (st.rig), so the game's own list sets the right
-- voice. (v423 called WwiseManager.setSwitch(param, UInt32) itself: that crashed the game on
-- player 2's next voice line, re2.exe+0x1F60373. Nothing here calls Wwise.)
-- st.voice_map = false: off.
-- (v425) Silent (st.p2_silent, Player 2 > Character): the element points at another
-- character's switch whose lines the body's voice bank doesn't have (any rig but HUNK's: left
-- on pl4000, as before v423c; HUNK's: pl1000), so no voice lines play. Footsteps, weapons and
-- hits are other sounds and stay.
function st.voice_map_go(go, rig)
    if go == nil or rig == nil then return "skip" end
    if st.p2_silent then
        if rig ~= "pl4000" then return "silent (left on pl4000)" end
        rig = "pl1000"
    elseif st.voice_map == false or rig == "pl4000" then
        return "skip"
    end
    local c = comp(go, "via.wwise.WwiseSwitchList") or safe(function() return go:call("getComponent(System.Type)", sdk.typeof("via.wwise.WwiseSwitchList")) end)
    if c == nil then return "no list" end
    local want = rig:upper()
    for i = 0, (safe(function() return c:call("getSwitchParamCount") end) or 0) - 1 do
        local p = safe(function() return c:call("getSwitchParam", i) end)
        if p and safe(function() return p:call("get_SwitchGroupIdName") end) == "PL_LOCAL_CHARACTER_TYPE" then
            local n = safe(function() return p:call("getSwitchElementCount") end) or 0
            local mine, target, tname
            for j = 0, n - 1 do
                local e = safe(function() return p:call("getSwitchElement", j) end)
                local d = e and safe(function() return e:call("get_Define") end)
                if d == "PL4000" then mine = e end
                if d == want then target, tname = safe(function() return e:call("get_SwitchId") end), safe(function() return e:call("get_SwitchIdName") end) end
            end
            if target == nil and rig == "pl0000" then
                target, tname = safe(function() return p:call("get_SwitchIdInCaseOfUnmatch") end), safe(function() return p:call("get_SwitchIdNameInCaseOfUnmatch") end)
            end
            if mine == nil or target == nil then return "no element (" .. want .. ")" end
            pcall(mine.call, mine, "set_SwitchId", target)
            if tname then pcall(mine.call, mine, "set_SwitchIdName", tname) end
            return "PL4000 -> " .. tostring(tname)
        end
    end
    return "no param"
end
-- which prefab an existing player 2 was built from (after a script reset), from his
-- voice bank: plXXXX_vo_media (Ghost uses pl5700's, Daniel pl5400's, Annette has none)
function st.detect_rig(go)
    local bl = comp(go, "via.wwise.WwiseBankList")
    local b = bl and safe(function() return bl:call("getBankParam", 0):call("get_BankName") end)
    if b == nil then return nil end
    local code = b:match("^(pl%d%d%d%d)_vo")
    if code == "pl5400" then return "pl7500" end
    if code == "pl5700" then
        local pl = comp(go, "via.wwise.WwisePackageList")
        local n = pl and safe(function() return pl:call("getPackageParamCount") end) or 0
        return n > 0 and "pl5700" or "pl5600"
    end
    if code then return code end
    if b == "pl_base_se_all_media" then return "pl5300" end
    return nil
end
-- the survivor type player 2's animations are loaded as
function st.anim_type(key)
    for _, m in ipairs(MODELS) do if m.key == key and m.anim then return m.anim end end
    return survivor_type(key)
end
-- who player 1 is playing (from the game's survivor type), and player 2's chosen model
st.p1_cache = { frame = -1000, name = "Player 1" }
function st.p1_name()
    local c = st.p1_cache
    if st.frame - c.frame < 120 then return c.name end
    c.frame = st.frame
    local go = p1_go()
    local cond = go and comp(go, "app.ropeway.survivor.player.PlayerCondition")
    local t = cond and safe(function() return cond:call("get_SurvivorType") end)
    if t == nil then return c.name end
    -- the same survivor types as player 2's models (Ghost Survivors included)
    local SHORT = { [6] = "Kendo", [20] = "Katherine", [31] = "Daniel", [12] = "Ghost", [7] = "Irons", [8] = "Ben", [9] = "Annette", [13] = "Marvin", [27] = "Pilot", [34] = "Elliot" }
    c.name = "Player 1"
    if SHORT[t] then c.name = SHORT[t] end
    for _, m in ipairs(MODELS) do if m.type == t and not SHORT[t] and not m.exp then c.name = m.label end end
    return c.name
end
function st.p2_name()
    local c = st.costume_entry(st.p2_model)   -- (v415) Ghost, Emma
    return (c and c.name) or model_label(st.p2_model)
end
-- per-model touch-ups the costume changer can undo (checked twice a second)
function st.model_fixups()
    if st.hunk == nil then return end
    local want_chain = true
    for _, m in ipairs(MODELS) do if m.key == st.p2_model and m.no_chain then want_chain = false end end
    local c = safe(function() return st.hunk:call("get_Transform"):call("get_Child") end)
    local guard = 0
    while c and guard < 80 do
        guard = guard + 1
        local g = safe(function() return c:call("get_GameObject") end)
        local name = g and safe(function() return g:call("get_Name") end)
        if name == "Body" and not (want_chain and not st.chain_off) then
            local ch = comp(g, "via.motion.Chain")
            if ch and safe(function() return ch:call("get_Enabled") end) ~= want_chain then
                safe(function() ch:call("set_Enabled", want_chain) end)
            end
        elseif name == "Viscera" and safe(function() return g:call("get_DrawSelf") end) then
            -- Elliot's dangling guts (pl7880): a separate physics mesh on his hip. Hidden, and its
            -- chain stopped so it costs nothing. No other model has one, so a leftover is hidden too.
            safe(function() g:call("set_DrawSelf", false) end)
            local ch = comp(g, "via.motion.Chain")
            if ch then safe(function() ch:call("set_Enabled", false) end) end
        end
        c = safe(function() return c:call("get_Next") end)
    end
    st.chain_off = not want_chain
end

local function fix_costume()
    local go = st.hunk
    local cond = comp(go, "app.ropeway.survivor.player.PlayerCondition")
    local cc = comp(go, "app.ropeway.survivor.SurvivorCostumeChanger")
    if cond then safe(function() cond:set_field("<SurvivorType>k__BackingField", SURVIVOR_PL4000) end) end
    if cc then
        local t = survivor_type(st.p2_model)
        st.model_applied = st.p2_model
        local costume = model_costume(st.p2_model)
        -- (v434) a mixed costume: built in two changes (st.mix_tick)
        local entry = st.costume_entry and st.costume_entry(st.p2_model)
        if entry and entry.mix and st.mix_start then
            st.fix_tries = st.fix_tries + 1
            st.verify_at = nil
            st.mix_start(cc, entry.mix)
            return
        end
        for _, c in ipairs(COSTUMES[st.p2_model] or {}) do
            if c[1] == costume and c.t then t, costume = c.t, c.c or 0 end   -- another survivor's look
        end
        safe(function() cc:call("change(app.ropeway.SurvivorDefine.SurvivorType, app.ropeway.SurvivorDefine.Costume)", t, costume) end)
    end
    st.fix_tries = st.fix_tries + 1
    st.verify_at = st.frame + 120
end

-- (v434, experimental) Mixing costume parts (Agent: SHERRY: HUNK's body with Sherry's head).
-- SurvivorCostumeChanger.change(type, costume) asks for each part that differs
-- (onRequestAction(Parts): Body 1, Face 2, Hair 4, Other 8), instantiates it
-- (onInstantiateAction(GameObject, Parts)) and deletes the old one
-- (onDeleteDiscardedPartsAction(Parts)). While st.ccx.skip has a part's bit, that part is
-- neither requested nor deleted on player 2: the part already there stays. st.ccx.trace logs
-- the calls (dev).
do
    local td = sdk.find_type_definition("app.ropeway.survivor.SurvivorCostumeChanger")
    st.ccx = { trace = {}, skip = nil }
    local X = st.ccx
    local function mine(args)
        local cc = st.hunk and comp(st.hunk, "app.ropeway.survivor.SurvivorCostumeChanger")
        return cc ~= nil and (sdk.to_int64(args[2]) & 0xFFFFFFFFFFFF) == (cc:get_address() & 0xFFFFFFFFFFFF)
    end
    local function note(t)
        X.trace[#X.trace + 1] = string.format("%d %s", st.frame or 0, t)
        if #X.trace > 60 then table.remove(X.trace, 1) end
    end
    for _, sig in ipairs({ "onRequestAction(app.ropeway.SurvivorDefine.Parts)", "onDeleteDiscardedPartsAction(app.ropeway.SurvivorDefine.Parts)" }) do
        local m = td and td:get_method(sig)
        if m then
            sdk.hook(m, function(args)
                if not mine(args) then return end
                local part = sdk.to_int64(args[3]) & 0xFFFFFFFF
                local skip = X.skip ~= nil and (X.skip & part) ~= 0
                note(sig:match("^(%w+)") .. " " .. part .. (skip and " SKIPPED" or ""))
                if skip then return sdk.PreHookResult.SKIP_ORIGINAL end
            end, function(r) return r end)
        end
    end
    -- (v434) a mixed costume: 1) change to the head's character (face, hair, body), 2) the
    -- changer forgets that face / hair (its Face / Hair fields cleared, "discarded" hair / other
    -- not deleted) and changes to the body's character: its body and face come in, her face and
    -- hair stay on; 3) her face / hair become the changer's parts again, so st.cleanup_parts
    -- removes the body character's face (HUNK's mask and helmet) and keeps hers.
    local CSIG = "change(app.ropeway.SurvivorDefine.SurvivorType, app.ropeway.SurvivorDefine.Costume)"
    function st.mix_start(cc, mix)
        X.job = { cc = cc, mix = mix, stage = 0, at = st.frame }
        pcall(cc.call, cc, CSIG, mix.head, mix.hc or 0)
        note("mix: head " .. tostring(mix.head))
    end
    function st.mix_tick()
        local J = X.job
        if J == nil then return end
        if st.hunk == nil or st.frame - J.at > 900 then X.job, X.skip = nil, nil; return end
        local cc = J.cc
        local busy = safe(function() return cc:call("get_NowChanging") end) == true
        if busy or st.frame - J.at < 20 then return end
        if J.stage == 0 then
            J.face = safe(function() return cc:get_field("<Face>k__BackingField") end)
            J.hair = safe(function() return cc:get_field("<Hair>k__BackingField") end)
            if J.face then J.face = J.face:add_ref() end
            if J.hair then J.hair = J.hair:add_ref() end
            pcall(cc.set_field, cc, "<Face>k__BackingField", nil)
            pcall(cc.set_field, cc, "<Hair>k__BackingField", nil)
            X.skip = 4 + 8
            pcall(cc.call, cc, CSIG, J.mix.body, J.mix.bc or 0)
            J.stage, J.at = 1, st.frame
            note("mix: body " .. tostring(J.mix.body))
        elseif J.stage == 1 then
            X.skip = nil
            local hf = safe(function() return cc:get_field("<Face>k__BackingField") end)
            if J.face then pcall(cc.set_field, cc, "<Face>k__BackingField", J.face) end
            if J.hair then pcall(cc.set_field, cc, "<Hair>k__BackingField", J.hair) end
            -- the body character's face (not one of the changer's parts any more) goes now
            if hf and J.face and hf:get_address() ~= J.face:get_address() then
                pcall(function() local g = hf:call("get_GameObject"); g:call("destroy(via.GameObject)", g) end)
            end
            note("mix: done")
            X.job = nil
            st.verify_at = st.frame + 10
        end
    end
    re.on_frame(function() pcall(st.mix_tick) end)
    local mi = td and td:get_method("onInstantiateAction(via.GameObject, app.ropeway.SurvivorDefine.Parts)")
    if mi then
        sdk.hook(mi, function(args)
            if not mine(args) then return end
            local part = sdk.to_int64(args[4]) & 0xFFFFFFFF
            local nm = "?"
            pcall(function() nm = sdk.to_managed_object(args[3]):call("get_Name") end)
            note("onInstantiateAction " .. part .. " " .. tostring(nm))
        end, function(r) return r end)
    end
end
-- Character animations: the game picks a survivor's animation set from its motion type
-- (SurvivorDefine.getMotionType: Leon and HUNK "Male" = pl00, Claire "Female" = pl10,
-- Ada "Female2" = pl20). Player 2 stays HUNK to the game (SurvivorType PL4000, which
-- keeps the rest of the game logic happy), so his weapon animation sets are loaded with
-- the chosen character's type and his bare-hand (walk / run / idle) bank is swapped to
-- that character's folder.
st.anim = { holders = {}, applied = nil }
st.anim.folder = { [1] = "pl00", [2] = "pl00", [4] = "pl10", [8] = "pl20", [32] = "pl30", [64] = "pl10" }
st.anim.motion_type = function()
    local td = sdk.find_type_definition("app.ropeway.SurvivorDefine")
    local m = td and td:get_method("getMotionType")
    local t = st.anim_type(st.p2_model)
    return (m and safe(function() return m:call(nil, t) end)) or 1
end
-- (v416) what player 2's animations come from: weapon sets (wtype, their folder wfolder), the
-- fallback for weapons that type has no set for (ftype / ffolder: the model's anim), and the
-- bare-hand bank's folder. Own-move entries (bare / wanim) apply only on the model's own rig.
st.anim.spec = function()
    local ftype = st.anim_type(st.p2_model)
    local ffolder = st.anim.folder[st.anim.motion_type()] or "pl00"
    local sp = { wtype = ftype, wfolder = ffolder, ftype = ftype, ffolder = ffolder, bare = ffolder }
    for _, m in ipairs(MODELS) do
        if m.key == st.p2_model and st.rig == m.prefab then
            if m.bare then sp.bare = m.bare end
            if m.wanim then sp.wtype, sp.wfolder = m.wanim, m.wfolder or ffolder end
        end
    end
    return sp
end
do
    local td = sdk.find_type_definition("app.ropeway.survivor.SurvivorDynamicMotionController")
    local m = td and td:get_method("addMotionResource")
    if m then
        sdk.hook(m, function(args)
            if st.hunk == nil then return end
            -- (v416) the type to load as: a fallback load's (st.anim.load_type), else the spec's
            local lt = st.anim.load_type
            if lt == nil then
                local ok, sp = pcall(st.anim.spec)
                lt = ok and sp.wtype or st.anim_type(st.p2_model)
            end
            if lt == SURVIVOR_PL4000 then return end
            local sdmc = comp(st.hunk, "app.ropeway.survivor.SurvivorDynamicMotionController")
            if sdmc == nil or sdk.to_int64(args[2]) ~= sdmc:get_address() then return end
            -- load this weapon's animations as the chosen character, then put HUNK back
            local cond = comp(st.hunk, "app.ropeway.survivor.player.PlayerCondition")
            if cond then
                safe(function() cond:set_field("<SurvivorType>k__BackingField", lt) end)
                thread.get_hook_storage().cond = cond
            end
        end, function(r)
            local cond = thread.get_hook_storage().cond
            if cond then
                thread.get_hook_storage().cond = nil
                safe(function() cond:set_field("<SurvivorType>k__BackingField", SURVIVOR_PL4000) end)
            end
            return r
        end)
    end
end
-- the weapon types player 2 carries: his own inventory with Infinite ammo off (difficulty
-- kits, pickups, item box guns), else the configured loadout
st.anim.carried = function()
    local wts, seen = {}, {}
    local function add(wt) if wt and wt > 0 and not seen[wt] then seen[wt] = true; wts[#wts + 1] = wt end end
    if not st.infinite_ammo and st.p2inv then
        local hinv = st.hunk and comp(st.hunk, "app.ropeway.survivor.Inventory")
        for _, e in ipairs(hinv and st.p2inv.list(hinv) or {}) do add(e.wt) end
    end
    if #wts == 0 then for _, w in ipairs(LOADOUT) do add(w.wt) end end
    return wts
end
-- reload player 2's animation sets for the current model
-- (v416) load one weapon's set as the spec's weapon type. The handle list fills in a few
-- frames later, so whether that type had a set is only known then: the watchdog (check)
-- loads the fallback for a weapon still missing 30+ frames after its try (st.anim.tried).
st.anim.tried = {}
st.anim.add = function(sdmc, wt, sp, fallback)
    if fallback then st.anim.load_type = sp.ftype end
    safe(function() sdmc:call("addMotionResource", wt) end)
    st.anim.load_type = nil
    st.anim.tried[wt] = { frame = st.frame, fb = fallback == true, model = st.p2_model }
end
st.anim.apply = function()
    if st.hunk == nil then return end
    local sp = st.anim.spec()
    local folder = sp.bare
    -- weapon animations: drop the loaded sets and load them again (the hook above picks the type)
    local sdmc = comp(st.hunk, "app.ropeway.survivor.SurvivorDynamicMotionController")
    if sdmc then
        -- every weapon player 2 carries (the loaded list can be empty after a model change)
        local wts = st.anim.carried()
        safe(function() sdmc:call("clearHandleList") end)
        st.anim.tried = {}
        for _, wt in ipairs(wts) do st.anim.add(sdmc, wt, sp) end
    end
    -- walk / run / idle: the bare-hand bank
    local mot = comp(st.hunk, "via.motion.Motion")
    local n = mot and safe(function() return mot:call("getDynamicMotionBankCount") end) or 0
    for i = 0, n - 1 do
        local b = safe(function() return mot:call("getDynamicMotionBank", i) end)
        local cur = b and safe(function() return b:call("get_MotionBank"):call("ToString") end)
        if cur and cur:find("/bank/BareHand.motbank", 1, true) and not cur:find("/" .. folder .. "/", 1, true) then
            local path = "SectionRoot/Animation/Player/" .. folder .. "/bank/BareHand.motbank"
            local holder = st.anim.holders[path]
            if holder == nil then
                local res = sdk.create_resource("via.motion.MotionBankResource", path)
                holder = res and res:add_ref():create_holder("via.motion.MotionBankResourceHolder")
                if holder then holder = holder:add_ref(); st.anim.holders[path] = holder end
            end
            if holder then
                safe(function() b:call("set_MotionBank", holder) end)
                safe(function() mot:call("setDynamicMotionBank", i, b) end)
            end
        end
    end
    st.anim.applied = st.p2_model
end
-- watchdog: every carried weapon needs its animation set loaded, from the right character.
-- (Swapping a weapon in can drop its set, and then the game plays another weapon's moves,
-- e.g. knife swings with a gun.)
st.anim.check = function()
    if st.hunk == nil or st.pending or #LOADOUT == 0 then return end
    local sdmc = comp(st.hunk, "app.ropeway.survivor.SurvivorDynamicMotionController")
    local hl = sdmc and safe(function() return sdmc:get_field("HandleList") end)
    if hl == nil then return end
    local sp = st.anim.spec()
    local have, wrong = {}, false
    for i = 0, (safe(function() return hl:call("get_Count") end) or 0) - 1 do
        local h = safe(function() return hl:call("get_Item", i) end)
        local wt = h and safe(function() return h:get_field("WeaponType") end)
        local inst = h and safe(function() return h:get_field("Instance") end)
        local name = inst and safe(function() return inst:call("get_Name") end)
        if wt then
            have[wt] = true
            local pre = name and name:sub(1, 4)
            if pre and pre ~= sp.wfolder and pre ~= sp.ffolder then wrong = true end
        end
    end
    if wrong then pcall(st.anim.apply); return end   -- another character's sets: reload all
    for _, wt in ipairs(st.anim.carried()) do
        if not have[wt] then
            have[wt] = true
            local t = st.anim.tried[wt]
            if t and t.model == st.p2_model and st.frame - t.frame < 30 then
                -- (still loading)
            elseif t and t.model == st.p2_model and not t.fb and sp.wtype ~= sp.ftype then
                st.anim.add(sdmc, wt, sp, true)   -- that type has no set for it: the fallback's
            else
                st.anim.add(sdmc, wt, sp, t ~= nil and t.fb and t.model == st.p2_model)
            end
        end
    end
end

-- Sherry's fit (v402, the "Experimental Sherry"; since v408 the only Sherry) -------------------
-- Sherry (MODELS key sherry): Sherry's own prefab (pl3000, her child skeleton) with Claire's
-- full moveset (anim = 1: walk, run, guns, knife), without the stretching the plain version had. Claire's animations carry an adult's bone lengths
-- (tibia 0.396 m, Sherry's 0.319 m), which pulled Sherry's limbs to adult length. After the
-- game has posed her each frame, every body bone here is put back to Sherry's own length
-- (its local position: the angle from Claire's animation is kept, only the length is hers),
-- and the hips (COG) are lowered by Sherry's / Claire's standing hip height (0.734 / 0.969).
-- The lengths were recorded from Sherry playing her own animations (constant, reunited_sherry_
-- bones.txt). Cloth / chain bones (shorts flaps, tie, back flap) and the weapon joints are left
-- to the game. Only player 2 while this model is chosen is touched: Claire's animation files
-- are only read, and player 1 (or a "Claire" player 2) never goes through this.
-- (Without this block she'd be the old stretched Sherry again.)
;(function()
    local X = { joints = nil, addr = nil, on_frames = 0 }
    st.xsherry = X
    function X.on() return st.p2_model == "sherry" and st.hunk ~= nil and not st.pending end
    X.HIP_K = 0.73392 / 0.96900
    X.BONES = {
        l_leg_femur = { 0.06143, -0.03926, -0.00371 }, l_leg_tibia = { -0.00000, -0.31889, 0.00000 }, l_leg_ankle = { 0.00000, -0.30584, -0.00000 },
        l_leg_ball = { 0.00000, -0.04853, 0.09093 }, r_leg_femur = { -0.06143, -0.03926, -0.00371 }, r_leg_tibia = { -0.00000, -0.31889, -0.00000 },
        r_leg_ankle = { 0.00000, -0.30584, -0.00000 }, r_leg_ball = { -0.00000, -0.04853, 0.09093 }, spine_0 = { 0.00000, 0.00000, 0.00000 },
        spine_1 = { 0.00000, 0.11943, 0.00000 }, spine_2 = { -0.00000, 0.11870, -0.00000 }, l_arm_clavicle = { 0.01913, 0.10174, 0.04760 },
        l_arm_humerus = { 0.10897, 0.00000, -0.00000 }, l_arm_radius = { 0.20500, 0.00000, 0.00000 }, l_arm_wrist = { 0.19000, 0.00000, 0.00000 },
        l_hand_thumb_0 = { 0.01933, -0.00417, 0.01947 }, l_hand_thumb_1 = { 0.03154, -0.00000, -0.00000 }, l_hand_thumb_2 = { 0.02336, 0.00000, -0.00000 },
        l_hand_index_0 = { 0.06644, 0.00535, 0.02026 }, l_hand_index_1 = { 0.03147, 0.00000, 0.00000 }, l_hand_index_2 = { 0.01729, -0.00000, 0.00000 },
        l_hand_middle_0 = { 0.06693, 0.00904, 0.00396 }, l_hand_middle_1 = { 0.03504, 0.00000, -0.00000 }, l_hand_middle_2 = { 0.02265, 0.00000, -0.00000 },
        l_hand_ring_0 = { 0.02004, 0.00157, -0.00422 }, l_hand_ring_1 = { 0.04328, 0.00000, -0.00000 }, l_hand_ring_2 = { 0.03193, -0.00000, 0.00000 },
        l_hand_ring_3 = { 0.02096, 0.00000, -0.00000 }, l_hand_little_0 = { 0.02064, -0.00011, -0.01388 }, l_hand_little_1 = { 0.03608, -0.00000, -0.00000 },
        l_hand_little_2 = { 0.02787, 0.00000, -0.00000 }, l_hand_little_3 = { 0.01494, -0.00000, -0.00000 }, l_scapula_0 = { 0.11330, 0.00542, -0.01353 },
        r_arm_clavicle = { -0.01913, 0.10174, 0.04760 }, r_arm_humerus = { -0.10897, 0.00000, 0.00000 }, r_arm_radius = { -0.20500, -0.00000, -0.00000 },
        r_arm_wrist = { -0.19000, -0.00000, 0.00000 }, r_hand_thumb_0 = { -0.01933, -0.00417, 0.01947 }, r_hand_thumb_1 = { -0.03154, 0.00000, 0.00000 },
        r_hand_thumb_2 = { -0.02336, -0.00000, 0.00000 }, r_hand_index_0 = { -0.06644, 0.00535, 0.02026 }, r_hand_index_1 = { -0.03147, -0.00000, -0.00000 },
        r_hand_index_2 = { -0.01729, 0.00000, -0.00000 }, r_hand_middle_0 = { -0.06693, 0.00904, 0.00396 }, r_hand_middle_1 = { -0.03504, -0.00000, 0.00000 },
        r_hand_middle_2 = { -0.02265, 0.00000, -0.00000 }, r_hand_ring_0 = { -0.02004, 0.00157, -0.00422 }, r_hand_ring_1 = { -0.04328, 0.00000, -0.00000 },
        r_hand_ring_2 = { -0.03193, 0.00000, 0.00000 }, r_hand_ring_3 = { -0.02096, -0.00000, -0.00000 }, r_hand_little_0 = { -0.02064, -0.00011, -0.01388 },
        r_hand_little_1 = { -0.03608, 0.00000, -0.00000 }, r_hand_little_2 = { -0.02787, 0.00000, -0.00000 }, r_hand_little_3 = { -0.01494, -0.00000, 0.00000 },
        r_scapula_0 = { -0.11304, 0.00560, -0.01347 }, neck_0 = { 0.00000, 0.12076, 0.00044 }, neck_1 = { 0.00000, 0.06101, -0.00000 },
        head = { -0.00006, 0.06168, 0.00031 },
    }
    local function gather()
        local xf = st.hunk:call("get_Transform")
        local list = {}
        for name, v in pairs(X.BONES) do
            local j = safe(function() return xf:call("getJointByName", name) end)
            if j then list[#list + 1] = { j = j, p = Vector3f.new(v[1], v[2], v[3]) } end
        end
        X.cog = safe(function() return xf:call("getJointByName", "COG") end)
        X.joints, X.addr = list, st.hunk:get_address()
    end
    -- (v404) Order matters. Each frame the animation (UpdateMotion) sets Claire's hip height and
    -- knee bend, then the foot IK (UpdateConstraintsBegin) plants the feet. Fitted only after
    -- that (v402), the IK had solved for hips at Claire's height (0.94 m) on Sherry's short legs:
    -- knees locked straight and toes pointed down to reach the floor (seen standing still while
    -- aiming, where the IK holds the feet). So the fit runs just before the IK, which then plants
    -- her feet for her own size. It runs again at LateUpdateBehavior in case anything wrote the
    -- bone lengths in between.
    -- (v405) The hips are shrunk exactly once per pose the animation writes: UpdateMotion is
    -- watched, and X.fresh is set only when it changed the COG. (v404 compared the COG with the
    -- value it had set, but the IK nudges the hips by ~1 mm, so the late pass shrank them again
    -- and she dropped ~18 cm into the floor for a few frames.) A paused animation writes nothing,
    -- so nothing is shrunk twice.
    local function ready() return X.on() and X.joints ~= nil and X.cog ~= nil and X.addr == st.hunk:get_address() end
    re.on_pre_application_entry("UpdateMotion", function()
        X.cog_before = nil
        pcall(function() if ready() then X.cog_before = X.cog:call("get_LocalPosition") end end)
    end)
    re.on_application_entry("UpdateMotion", function()
        pcall(function()
            local b = X.cog_before
            if b == nil or not ready() then return end
            local p = X.cog:call("get_LocalPosition")
            if p.x ~= b.x or p.y ~= b.y or p.z ~= b.z then X.fresh = true end
        end)
    end)
    function X.fit(stage)
        if not X.on() or st.rig ~= "pl3000" then X.joints = nil; return end
        if X.joints == nil or X.addr ~= st.hunk:get_address() then gather(); X.fresh = true end
        for _, e in ipairs(X.joints) do e.j:call("set_LocalPosition", e.p) end
        local c = X.cog
        if c and X.fresh then
            X.fresh = false
            local p = c:call("get_LocalPosition")
            c:call("set_LocalPosition", Vector3f.new(p.x * X.HIP_K, p.y * X.HIP_K, p.z * X.HIP_K))
            if stage ~= "pre" then X.late_scaled = (X.late_scaled or 0) + 1 end
        end
        if stage == "pre" then X.pre_frames = (X.pre_frames or 0) + 1 else X.on_frames = X.on_frames + 1 end
    end
    re.on_pre_application_entry("UpdateConstraintsBegin", function()
        local ok, err = pcall(X.fit, "pre")
        if not ok then X.err = tostring(err); X.joints = nil end
    end)
    re.on_application_entry("LateUpdateBehavior", function()
        local ok, err = pcall(X.fit, "late")
        if not ok then X.err = tostring(err); X.joints = nil end
    end)
end)()

-- After a model / costume change the game can leave the previous body, face and hair
-- attached next to the new ones (the two models look "merged"). Remove every Body / Face /
-- Hair object that isn't one of the costume changer's current parts.
st.cleanup_parts = function()
    if st.hunk == nil then return 0 end
    local cc = comp(st.hunk, "app.ropeway.survivor.SurvivorCostumeChanger")
    if cc == nil or safe(function() return cc:call("get_NowChanging") end) then return 0 end
    local keep = {}
    for _, f in ipairs({ "Body", "Face", "Hair", "SheathKnife", "Other" }) do
        local o = safe(function() return cc:get_field("<" .. f .. ">k__BackingField") end)
        local go = o and (safe(function() return o:call("get_GameObject") end) or o)
        if go then keep[go:get_address()] = true end
    end
    local body = safe(function() return cc:call("get_BodyObject") end)
    if body then keep[body:get_address()] = true end
    local stale, found = {}, {}
    local c = safe(function() return st.hunk:call("get_Transform"):call("get_Child") end)
    local guard = 0
    while c and guard < 80 do
        guard = guard + 1
        local go = safe(function() return c:call("get_GameObject") end)
        local name = go and safe(function() return go:call("get_Name") end)
        if name == "Body" or name == "Face" or name == "Hair" then
            if keep[go:get_address()] then found[name] = true else stale[#stale + 1] = go end
        end
        c = safe(function() return c:call("get_Next") end)
    end
    -- only when the current body was recognised among the children (never strip the model bare)
    if not found.Body then return 0 end
    for _, go in ipairs(stale) do safe(function() go:call("destroy(via.GameObject)", go) end) end
    return #stale
end

local function verify_costume()
    local cc = comp(st.hunk, "app.ropeway.survivor.SurvivorCostumeChanger")
    if cc and safe(function() return cc:call("get_NowChanging") end) then
        st.verify_at = st.frame + 30          -- still loading the model
        return
    end
    local body = cc and safe(function() return cc:call("get_BodyObject") end)
    if body then
        say("Player 2 is ready (" .. model_label(st.model_applied) .. ")")
        pcall(st.cleanup_parts)
        st.cleanup_at = st.frame + 90   -- and once more after the new parts settle
        pcall(st.anim.apply)
        if not st.loadout_given then pcall(give_loadout) end
        if st.model_switch then st.model_switch = nil else pcall(teleport_to_p1) end   -- settle next to P1 after a spawn
    elseif st.fix_tries < 3 then
        say("Loading player 2...")
        fix_costume()
    elseif st.p2_model ~= "hunk" then
        -- that model wouldn't load on HUNK: go back to HUNK's own
        say(model_label(st.p2_model) .. "'s model couldn't be loaded; using HUNK")
        st.p2_model = "hunk"
        st.fix_tries = 0
        fix_costume()
    else
        say("HUNK's model didn't load; extract him and deploy again")
    end
end

-- Another character's body has no holster points for HUNK's knife / grenade, so the game
-- leaves them hanging at his feet. Hide weapon objects that aren't attached to a joint
-- (holstered somewhere that doesn't exist) and show them again once they're in a hand.
local gear = { frame = -1000, list = {}, hidden = {} }
gear.in_hand = { r_weapon = true, l_weapon = true }
-- a weapon object and everything under it (scopes, magazines and other mesh parts)
function gear.parts(go, out)
    out[#out + 1] = go
    local c = safe(function() return go:call("get_Transform"):call("get_Child") end)
    local guard = 0
    while c and guard < 16 do
        guard = guard + 1
        local cg = safe(function() return c:call("get_GameObject") end)
        if cg then gear.parts(cg, out) end
        c = safe(function() return c:call("get_Next") end)
    end
    return out
end
function gear.show(go, show)
    for _, part in ipairs(gear.parts(go, {})) do
        local a = part:get_address()
        if show then
            if gear.hidden[a] then safe(function() part:call("set_DrawSelf", true) end); gear.hidden[a] = nil end
        elseif safe(function() return part:call("get_DrawSelf") end) then
            safe(function() part:call("set_DrawSelf", false) end)
            gear.hidden[a] = part
        end
    end
end
local function update_gear()
    if st.hunk == nil then return end
    if st.cut_hide and st.cut_hide.on then return end   -- (player 2 hidden for a cutscene)
    if st.p2_model == "hunk" then
        if next(gear.hidden) then
            for _, part in pairs(gear.hidden) do safe(function() part:call("set_DrawSelf", true) end) end
            gear.hidden = {}
        end
        return
    end
    -- other characters' bodies don't have HUNK's holsters: a gun on his back floats off
    -- theirs and the knife / grenade end up at their feet. Show weapons only in a hand.
    if st.frame - gear.frame >= 60 then
        gear.frame = st.frame
        gear.list = {}
        local c = safe(function() return st.hunk:call("get_Transform"):call("get_Child") end)
        local guard = 0
        while c and guard < 80 do
            guard = guard + 1
            local go = safe(function() return c:call("get_GameObject") end)
            if go and (comp(go, "app.ropeway.implement.Melee") or comp(go, "app.ropeway.implement.Gun")
                or (safe(function() return go:call("get_Name") end) or ""):match("^wp%d%d%d%d$")) then
                gear.list[#gear.list + 1] = go
            end
            c = safe(function() return c:call("get_Next") end)
        end
    end
    for _, go in ipairs(gear.list) do
        local joint = safe(function() return go:call("get_Transform"):call("get_ParentJoint") end)
        pcall(gear.show, go, joint ~= nil and gear.in_hand[joint] == true)
    end
end

-- right before the frame is drawn too, so a holster the game re-shows never flashes up
re.on_pre_application_entry("BeginRendering", function() pcall(update_gear) end)

-- switching model while player 2 is in the game
local function apply_model()
    if st.hunk == nil or st.pending then return end
    if st.rig_for(st.p2_model) ~= (st.rig or "pl4000") or st.voice_dirty then
        -- another skeleton / voice: rebuild player 2 from that character's prefab, same spot
        -- (v425: also for Silent, which is only applied when player 2 is built)
        st.voice_dirty = nil
        local xf = st.hunk:call("get_Transform")
        st.respawn_pos = xf:call("get_Position")
        st.respawn_rot = xf:call("get_Rotation")
        st.model_switch = true
        st.do_despawn()
        spawn()
        return
    end
    st.fix_tries = 0
    st.model_switch = true
    say("Changing player 2's model...")
    fix_costume()
end

-- candidate spots around P1 (metres behind, metres to the right), closest first
-- Teleport / spawn placement -------------------------------------------------------
-- Candidate spots around P1 as (metres behind, metres to the right), side-by-side first.
-- A spot is used only if there's no wall between P1 and it (chest and knee height) and
-- there is floor under it at P1's level; otherwise HUNK goes onto P1's own spot and the
-- character controllers push them apart. HUNK is then moved with his character
-- controller's warp(), which is what kept snapping him away / out of the map before.
local TELEPORT_SPOTS = { { 0, 0.65 }, { 0, -0.65 }, { 0.6, 0 }, { 0.45, 0.45 }, { 0.45, -0.45 },
                         { -0.4, 0.6 }, { -0.4, -0.6 }, { 0.9, 0 } }
local function floor_at(x, y, z)
    local ok, hit = pcall(cast_ray, Vector3f.new(x, y + 1.0, z), Vector3f.new(x, y - 1.2, z))
    if ok and hit and math.abs(hit.y - y) < 0.4 then return hit.y end
    return nil
end
-- a free spot beside a character (player 1 by default)
function st.spot_near(go)
    go = go or p1_go()
    local base = go and go:call("get_Transform"):call("get_Position")
    if base == nil then return nil end
    for _, o in ipairs(TELEPORT_SPOTS) do
        local pos = beside_p1(o[1], o[2], go)
        if pos then
            local clear = true
            for _, h in ipairs({ 1.2, 0.45 }) do
                local ok, hit = pcall(cast_ray, Vector3f.new(base.x, base.y + h, base.z), Vector3f.new(pos.x, pos.y + h, pos.z))
                if ok and hit then clear = false end
            end
            local fy = clear and floor_at(pos.x, base.y, pos.z)
            if fy then return Vector3f.new(pos.x, fy, pos.z) end
        end
    end
    return Vector3f.new(base.x, base.y, base.z)
end
spot_near_p1 = function() return st.spot_near(p1_go()) end

function st.warp_go(go, pos, rot)
    local xf = go:call("get_Transform")
    xf:call("set_Position", pos)
    if rot then xf:call("set_Rotation", rot) end
    local cc = comp(go, "via.physics.CharacterController")
    if cc then safe(function() cc:call("warp") end) end
end
local function warp_hunk(pos, rot) st.warp_go(st.hunk, pos, rot) end

-- (v430) Climbing: a character in a gimmick's hands (ladder, climbing up / down a ledge, a jump
-- down: JackDominator Jacked with a JackOwner that has a GimmickBody; not an enemy's grab), or
-- player 2 in the first moments of a ladder he was just put on. No teleport takes a climbing
-- player 2 anywhere, and player 1 isn't brought to player 2 while either of them climbs
-- (warping someone out of the middle of a climb leaves the gimmick and the character stuck).
function st.climbing(go)
    if go == nil then return false end
    if st.hunk and go:get_address() == st.hunk:get_address() and st.climb_until and os.clock() < st.climb_until then return true end
    local jd = comp(go, "app.ropeway.JackDominator")
    if not (jd and safe(function() return jd:call("get_Jacked") end) == true) then return false end
    local own = safe(function() return jd:get_field("<JackOwner>k__BackingField") end)
    return own ~= nil and safe(function() return own:get_field("<GimmickBody>k__BackingField") end) ~= nil
end
function st.climb_refused(t)   -- (a field: the main chunk is at its 200-local limit)
    if (st.climb_toast_at or 0) > os.clock() then return end
    st.climb_toast_at = os.clock() + 2
    say(t)
end
-- The other way round, for soft locks (player 1 stuck somewhere): player 1 goes to a free spot
-- beside HUNK, facing his way. Same warp and one re-warp two frames later.
function st.teleport_p1_to_p2()
    local p1 = p1_go()
    if st.hunk == nil or p1 == nil then return false end
    if st.climbing(st.hunk) then st.climb_refused("Can't bring " .. st.p1_name() .. " over while " .. st.p2_name() .. " is climbing"); return false end
    if st.climbing(p1) then st.climb_refused("Can't bring " .. st.p1_name() .. " over while they're climbing"); return false end
    local pos = st.spot_near(st.hunk)
    if pos == nil then return false end
    local rot = st.hunk:call("get_Transform"):call("get_Rotation")
    st.warp_go(p1, pos, rot)
    st.rewarp1 = { pos = pos, rot = rot, frame = st.frame + 2 }
    return true
end

teleport_to_p1 = function()
    if st.hunk == nil then return false end
    if st.climbing(st.hunk) then st.climb_refused(st.p2_name() .. " can't teleport while climbing"); return false end   -- (v430)
    local pos = spot_near_p1()
    if pos == nil then return false end
    local p1 = p1_go()
    local rot = p1 and p1:call("get_Transform"):call("get_Rotation")
    warp_hunk(pos, rot)
    -- some systems re-apply last frame's position once; warp again next frame
    st.rewarp = { pos = pos, rot = rot, frame = st.frame + 2 }
    return true
end

local function update_rewarp()
    local r1 = st.rewarp1
    if r1 and st.frame >= r1.frame then
        st.rewarp1 = nil
        local p1 = p1_go()
        if p1 and (p1:call("get_Transform"):call("get_Position") - r1.pos):length() > 0.5 then pcall(st.warp_go, p1, r1.pos, r1.rot) end
    end
    local r = st.rewarp
    if r and st.frame >= r.frame then
        st.rewarp = nil
        if st.hunk then
            local hp = st.hunk:call("get_Transform"):call("get_Position")
            if (hp - r.pos):length() > 0.5 then warp_hunk(r.pos, r.rot) end
        end
    end
end

local function despawn(reason)
    if st.hunk == nil then return end
    if st.p2log then st.p2log("player 2 removed: " .. tostring(reason or "asked")) end
    local go = st.hunk
    st.despawned = { addr = safe(function() return go:get_address() end), until_frame = st.frame + 300 }
    st.hunk = nil
    forget_weapons()
    st.loadout_given = false
    st.owners = {}
    st.vaim.active = false
    st.spine_w = 0
    st.pick = nil
    st.force_trig_addr = nil
    clear_comp_cache()
    safe(function() go:call("destroy(via.GameObject)", go) end)
    say("HUNK extracted")
end
st.do_despawn = despawn

-- Load screens ------------------------------------------------------------------------
-- Player 2 is a player character the game didn't make. Left in place through the game's own
-- reloads (game over and Continue, loading a save, back to the title or into another game
-- mode) the load could hang forever. So player 2 is removed the moment the game starts one
-- (the MainFlowManager calls that start one, RELOAD_ON below; traced on a
-- game over: goGameOver, resetGamePreprocessing, resetGame, clearManagers, goLoadGameData),
-- or when its state shows game over / loading / title, and is brought back once the game has
-- been in play with player 1 for 2 s (not in a cutscene). The AI partner comes back the same
-- way. While a load is under way HUNK isn't re-adopted (refresh_owners) or spawned.
st.unloading, st.back_frames, st.reload = false, 0, nil
-- (v410) Player 2 log: every removal and load signal, with the reason, in the REFramework log
-- ([reunited] lines) and reframework/data/reunited_p2_log.txt (last 150 lines), for reports.
do
    local L = {}
    function st.p2log(t)
        local line = string.format("[%s f%d] %s", os.date("%H:%M:%S"), st.frame or 0, t)
        log.info("[reunited] " .. t)
        L[#L + 1] = line
        if #L > 150 then table.remove(L, 1) end
        pcall(fs.write, "reunited_p2_log.txt", table.concat(L, "\n"))
    end
end
-- (v410) The Non-RT (DX11) version of the game runs older game data (TDB below 70; the current
-- RT version is 70). A report from it: player 2 is removed the moment they spawn, every time.
-- On that version only, a load signal that turns out to be false (3 s later player 1 is the
-- same object, in play: no load happened) is ignored from then on while player 1 is in play.
-- A real load (game over, Continue, loading a save, the title) makes player 1 again, so it is
-- never taken for a false one. Everything is logged (st.p2log) either way.
do
    local ok, v = pcall(function() return sdk.get_tdb_version() end)
    st.TDB = ok and v or nil
    st.NON_RT = type(st.TDB) == "number" and st.TDB < 70
    st.false_loads = {}
end
do
-- Only calls that start a load. Not resetGamePreprocessing / goShowAccountPicker: the game calls
-- those every frame while it's paused (our co-op menu stops time), so player 2 was removed each
-- time the menu opened. Nor goPause, goInGame / goInGameInitialize (also called inside
-- goGameOver), resetForXB1.
local RELOAD_ON = { goGameOver = true, goGameOverSimple = true, goGameOverWhite = true, goTitle = true,
    goExtraMenu = true, goWakeUp = true, goLoadGameData = true, resetGame = true, clearManagers = true,
    goEnding = true, goResult = true, goStaffRoll = true, goRogueBaseArea = true, goRogueResult = true,
    goLModeSetup = true, goResetToLModeInGame = true }
local function before_load(why)
    local p1 = p1_go()
    -- (v410, Non-RT only) a signal already shown to be false, while player 1 is in play
    local mf = st.NON_RT and sdk.get_managed_singleton("app.ropeway.gamemastering.MainFlowManager")
    local in_play = mf and safe(function() return mf:call("get_IsInGame") end) == true and safe(function() return mf:call("get_IsInGameOver") end) ~= true
    -- (NonRT-1) On Non-RT, making player 2 (prefab instantiate in finish_spawn) itself runs code
    -- merged with goLModeSetup: player 2 was removed the moment he appeared, came back 2 s later,
    -- removed again... ("player 2 takes so long to load in"). A hooked signal within 90 frames of
    -- our own spawn, with player 1 in play, is ours: ignored. (The state poll still catches real
    -- loads: game over, loading, title.)
    if in_play and p1 ~= nil and st.spawned_at and st.frame - st.spawned_at <= 90 and not tostring(why):find("^state ") then
        st.spawn_signals = (st.spawn_signals or 0) + 1
        if st.spawn_signals <= 3 or st.spawn_signals % 50 == 0 then st.p2log("ignored load signal " .. tostring(why) .. " (fired by player 2's own spawn, x" .. st.spawn_signals .. ")") end
        return
    end
    if in_play and p1 ~= nil and st.false_loads[why] then
        st.false_loads[why] = st.false_loads[why] + 1
        if st.false_loads[why] % 300 == 2 then st.p2log("ignored load signal " .. why .. " (false on this version, x" .. st.false_loads[why] .. ")") end
        return
    end
    if not st.unloading then
        st.p2log("load signal: " .. tostring(why) .. (st.hunk and " (player 2 in the game)" or "") .. (st.NON_RT and " [Non-RT, TDB " .. tostring(st.TDB) .. "]" or ""))
        st.load_check = { why = why, p1 = p1 and p1:get_address(), t = os.clock() }
    end
    if not st.unloading then st.load_why = why end
    st.unloading, st.back_frames = true, 0
    -- (v398) what player 2 carries this moment, not up to half a second ago
    if st.hunk and st.p2inv and st.p2inv.snapshot then pcall(st.p2inv.snapshot) end
    if st.hunk or st.pending then
        st.reload = st.reload or { human = not st.ai }
        st.pending = nil
        if st.hunk then pcall(despawn, "load signal " .. tostring(why)) end
    end
end
st.before_load = before_load
do
    local td = sdk.find_type_definition("app.ropeway.gamemastering.MainFlowManager")
    -- (v412) Several of these small methods can be one and the same code in the game's exe (the
    -- compiler merges identical bodies). Hooking one then hooks them all, and on the Non-RT
    -- version (TDB 66) a merged body is also called during normal play: a user's log showed
    -- goLModeSetup, goResetGameToRogueResult, goRogueBaseArea, goEnding, goResetGameTo... all
    -- "firing" in turn from the same call, removing player 2 each time. Methods are grouped by
    -- code address; on Non-RT a group of more than one is not hooked (those loads are still
    -- caught by the state poll, st.load_watch). The RT version is hooked as before. The groups
    -- found are logged once (st.p2log).
    local wanted, by_addr = {}, {}
    for _, m in ipairs(td and td:get_methods() or {}) do
        local n = m:get_name()
        if not m:is_static() and (RELOAD_ON[n] or n:find("^goResetGameTo")) then
            local ok, f = pcall(function() return m:get_function() end)
            local key = ok and f and tostring(f) or ("?" .. n)
            wanted[#wanted + 1] = { m = m, n = n, key = key }
            by_addr[key] = by_addr[key] or {}
            table.insert(by_addr[key], n)
        end
    end
    local skipped, shared = {}, {}
    for key, names in pairs(by_addr) do if #names > 1 then shared[#shared + 1] = table.concat(names, "/") end end
    for _, w in ipairs(wanted) do
        -- (NonRT-2) On Non-RT these hooks fire far outside loads: spawning player 2 alone set off
        -- goLModeSetup, goResetGameTo..., goRogueBaseArea, goWakeUp... 150+ times in one frame
        -- (their bodies are shared with common game code, not only with each other). None are
        -- hooked there; loads are caught by the state poll (st.load_watch: not in game, game over,
        -- loading a save, title).
        if st.NON_RT then
            skipped[#skipped + 1] = w.n
        else
            local n = w.n
            pcall(sdk.hook, w.m, function() pcall(before_load, n) end, function(r) return r end)
        end
    end
    st.load_hooks = { hooked = #wanted - #skipped, skipped = skipped, shared = shared }
    if #shared > 0 or #skipped > 0 then
        pcall(st.p2log, "load hooks: " .. #wanted .. " methods; sharing code: " .. table.concat(shared, ", ") ..
            (#skipped > 0 and ("; not hooked on this version: " .. table.concat(skipped, ", ")) or ""))
    end
end
function st.load_watch()
    local mf = sdk.get_managed_singleton("app.ropeway.gamemastering.MainFlowManager")
    if mf == nil then return end
    local in_game = safe(function() return mf:call("get_IsInGame") end) == true
    if not in_game then
        local away = nil
        for _, g in ipairs({ "get_IsInGameOver", "get_IsInLoadGameData", "get_IsInTitle", "get_IsInResetTitle" }) do
            if safe(function() return mf:call(g) end) == true then away = g end
        end
        if away then before_load("state " .. away:gsub("^get_", "")) end
    end
    -- (v410) was the last load signal real? Watched for 4 s: real if at any frame the game wasn't
    -- in play (not IsInGame, or game over / loading / title), player 1 was gone or a new object,
    -- or player 1 had no health left. Otherwise it was false. (When IsInGame can't be read the
    -- signal always counts as real: nothing is ever ignored on a guess.)
    local lc = st.load_check
    if lc then
        local p1 = p1_go()
        local real = not in_game or p1 == nil or lc.p1 == nil or p1:get_address() ~= lc.p1
        if not real then
            for _, g in ipairs({ "get_IsInGameOver", "get_IsInLoadGameData", "get_IsInTitle", "get_IsInResetTitle" }) do
                if safe(function() return mf:call(g) end) == true then real = true end
            end
            local hpc = comp(p1, "app.ropeway.HitPointController")
            local hp = hpc and safe(function() return hpc:call("get_CurrentHitPoint") end)
            if hp ~= nil and hp <= 0 then real = true end
        end
        if real then lc.real = true end
        if os.clock() - lc.t > 4 then
            st.load_check = nil
            if not lc.real then
                st.p2log("load signal " .. tostring(lc.why) .. " was false (no load happened)" .. (st.NON_RT and "; ignored from now on while player 1 is in play" or ""))
                if st.NON_RT then st.false_loads[lc.why] = 1 end
            else
                st.p2log("load signal " .. tostring(lc.why) .. ": a real load")
            end
        end
    end
    if not st.unloading then return end
    if in_game and p1_go() ~= nil and not st.in_cutscene() then st.back_frames = st.back_frames + 1 else st.back_frames = 0 end
    if st.back_frames < 120 then return end
    st.unloading = false
    local r = st.reload
    st.reload = nil
    if r and r.human and not st.ai and st.hunk == nil and st.pending == nil then
        pcall(refresh_owners)
        if st.hunk == nil then pcall(spawn) end
    end
end
end

-- Shared screen: player 2 in a room the game isn't running (another player 1 walked away
-- from, left Standby or unloaded) made the map glitch. Each room has an
-- EnvironmentStandbyController (CurrentStep 11 = Active). When player 2's room
-- (StayAreaController StaySceneMapID) isn't player 1's and isn't Active, or isn't in player
-- 1's location at all, for 1.5 s, player 2 is moved to a free spot next to player 1. Split
-- screen keeps player 2's rooms running itself (st.area_update), so this is shared screen only.
do
    local W = { bad = 0 }
    st.unloaded_watch_state = W
    function st.unloaded_watch()
        if st.split or st.ai or st.hunk == nil or st.unloading or st.pending or st.in_cutscene() then W.bad = 0; return end
        local p1 = p1_go()
        local m = sdk.get_managed_singleton("app.ropeway.EnvironmentStandbyManager")
        local em = sdk.get_managed_singleton("app.ropeway.EnemyManager")
        local sa = comp(st.hunk, "app.ropeway.StayAreaController")
        if p1 == nil or m == nil or em == nil or sa == nil then W.bad = 0; return end
        local phase = m:get_field("CurrentPhase")
        if phase ~= 0 and phase ~= 1 then W.bad = 0; return end   -- (the game is changing location)
        local r1 = em:get_field("<LastPlayerStaySceneID>k__BackingField")
        local r2 = sa:get_field("<StaySceneMapID>k__BackingField")
        local bad, why = false, nil
        if r2 == nil or r2 == 0 then
            bad, why = true, "no room"
        elseif r2 ~= r1 then
            local c1 = r1 and r1 ~= 0 and m:call("getStandbyController", r1)
            local c2 = m:call("getStandbyController", r2)
            local loc = c1 and c1:get_field("MyLocation")
            if c2 == nil or (loc and c2:get_field("MyLocation") ~= loc) then
                bad, why = true, "room not loaded"
            elseif (c2:get_field("<CurrentStep>k__BackingField") or 0) < 11 then
                bad, why = true, "room not active"
            end
        end
        if not bad then W.bad = 0; return end
        W.bad = W.bad + 1
        W.why = why
        if W.bad < 30 then return end   -- (checked every 3rd frame: 1.5 s)
        W.bad = 0
        W.moves = (W.moves or 0) + 1
        W.last = { frame = st.frame, why = why, room = r2, p1room = r1 }
        pcall(teleport_to_p1)
    end
end



-- Support abilities (pad 2 face buttons) --------------------------------------------

local function toast(text)
    st.toast = { text = text, until_t = os.clock() + 2.5 }
    log.info("[reunited] " .. text)
end

-- Sound effects: the Lua side can't play audio, so it writes "<n> <name>" to
-- data/reunited_sfx.txt and the re2r_mp_sfx.dll plugin plays data/reunited_sfx/<name>.wav.
local sfx_n = 0
local function play_sfx(name)
    if not st.sfx then return end
    sfx_n = sfx_n + 1
    pcall(fs.write, "reunited_sfx.txt", tostring(sfx_n) .. " " .. name)
end

-- Player 2's heal / resupply abilities (the cooldown boxes): set by the difficulty for the way
-- of play (st.p2_abilities, st.DIFF_SETS). The AI partner: always.
function st.cooldowns_on()
    if st.ai_partner() then return true end
    return st.p2_abilities == true
end
local function heal_p1()
    if st.hunk == nil then return end
    local now = os.clock()
    if now < st.next_heal then toast(string.format("Heal ready in %ds", math.ceil(st.next_heal - now))); return end
    local pm = sdk.get_managed_singleton("app.ropeway.PlayerManager")
    local p1 = p1_go()
    local hp = p1 and comp(p1, "app.ropeway.HitPointController")
    if pm == nil or hp == nil then return end
    local cur, max = hp:call("get_CurrentHitPoint"), hp:call("get_DefaultHitPoint")
    if cur >= max then toast(st.p1_name() .. " is already at full health"); return end
    local amount = math.floor(math.min(st.heal_amount, max - cur))   -- (v413: Int32)
    pm:call("recoveryCurrentPlayer", amount)
    st.next_heal = now + st.heal_cooldown
    toast(string.format("%s healed %s +%d HP", st.p2_name(), st.p1_name(), amount))
    if st.sfx_abilities then play_sfx("heal") end
end

local function resupply_p1()
    if st.hunk == nil then return end
    local now = os.clock()
    if now < st.next_resupply then toast(string.format("Resupply ready in %ds", math.ceil(st.next_resupply - now))); return end
    local p1 = p1_go()
    local inv = p1 and comp(p1, "app.ropeway.survivor.Inventory")
    local main = inv and safe(function() return inv:call("get_MainSlot") end)
    if main == nil or not safe(function() return main:call("get_IsWeapon") end) then toast(st.p1_name() .. " has no gun equipped"); return end
    -- only the magazine of the gun Leon is holding; his spare ammo is not touched
    local max, n = safe(function() return main:call("get_MaxNumber") end), safe(function() return main:call("get_Number") end)
    if not (max and n and max > 0) then toast(st.p1_name() .. "'s weapon can't be reloaded"); return end
    if n >= max then toast(st.p1_name() .. "'s magazine is already full"); return end
    main:call("set_Number", max)
    st.next_resupply = now + st.resupply_cooldown
    toast(string.format("%s reloaded %s's %s (+%d)", st.p2_name(), st.p1_name(), tostring(safe(function() return main:call("get_WeaponName") end) or "gun"), max - n))
    if st.sfx_abilities then play_sfx("resupply") end
end

local KIND_RELOAD = 512
local function reload_hunk()
    if st.hunk == nil then return end
    local heq = comp(st.hunk, "app.ropeway.survivor.Equipment")
    local hinv = comp(st.hunk, "app.ropeway.survivor.Inventory")
    local wt = heq and safe(function() return heq:call("get_EquipType") end)
    -- (v399) his own inventory (Operative, Veteran): only the game's reload, which takes
    -- the rounds from his stacks. The infinite-ammo top-up below (stacks at fixed loadout slots
    -- set full, the magazine set full 40 frames on) used to run here too: magazines refilled
    -- with no animation and his ammo never went down. (The shotgun loads shell by shell and
    -- wasn't in the loadout slot it looked at, so it was spared.)
    if not st.infinite_ammo then
        st.force_on[KIND_RELOAD] = true
        st.reload_release = st.frame + 8
        st.reload_fill = nil
        return
    end
    -- make sure the reserve stacks are full, then let the game play its reload
    for _, a in ipairs(AMMO) do
        local sl = safe(function() return hinv:call("getSlot(System.Int32)", a.slot) end)
        local max = sl and safe(function() return sl:call("get_MaxNumber") end)
        if max and max > 0 then safe(function() sl:call("set_Number", max) end) end
    end
    st.force_on[KIND_RELOAD] = true
    st.reload_release = st.frame + 8
    -- and top the magazine up directly in case the reload animation is skipped
    for _, w in ipairs(LOADOUT) do
        if w.wt == wt then
            local sl = safe(function() return hinv:call("getSlot(System.Int32)", w.slot) end)
            st.reload_fill = { slot = sl, frame = st.frame + 40 }
        end
    end
end

local function update_reload()
    if st.reload_release and st.frame >= st.reload_release then
        st.force_on[KIND_RELOAD] = nil
        st.reload_release = nil
    end
    local f = st.reload_fill
    if f and st.infinite_ammo == false then st.reload_fill, f = nil, nil end
    if f and st.frame >= f.frame then
        st.reload_fill = nil
        local max = f.slot and safe(function() return f.slot:call("get_MaxNumber") end)
        if max and max > 0 then safe(function() f.slot:call("set_Number", max) end) end
    end
end

-- cooldown HUD (top right): medic bag = heal (Y), ammo bag = resupply (X) ----------
local HUD = {}

st.hud_panel_alpha = 0x70    -- backing panel opacity

local function grey(c)
    local b, g, r = (c >> 16) & 0xFF, (c >> 8) & 0xFF, c & 0xFF
    local v = math.floor((r * 0.3 + g * 0.59 + b * 0.11) * 0.75)
    return (v << 16) | (v << 8) | v
end

-- shapes on a 64x64 grid, scaled by k and offset to (ox, oy). Colours are 0xBBGGRR and
-- get the HUD alpha applied; shapes of one colour never overlap so transparency is even.
local function painter(ox, oy, k, dim, alpha)
    local P = {}
    local A = (alpha or st.hud_alpha) << 24
    local function col(c) c = c & 0xFFFFFF; return A | (dim and grey(c) or c) end
    local function X(x) return ox + x * k end
    local function Y(y) return oy + y * k end
    function P.rect(x, y, w, h, c) draw.filled_rect(X(x), Y(y), w * k, h * k, col(c)) end
    function P.quad(x1, y1, x2, y2, x3, y3, x4, y4, c)
        draw.filled_quad(X(x1), Y(y1), X(x2), Y(y2), X(x3), Y(y3), X(x4), Y(y4), col(c))
    end
    -- pie slice from angle a0 to a1 (degrees, screen space: 0 = right, 90 = down)
    local function fan(cx, cy, r, a0, a1, c)
        local n = 6
        local pts = {}
        for i = 0, n do
            local a = math.rad(a0 + (a1 - a0) * i / n)
            pts[i] = { X(cx + math.cos(a) * r), Y(cy + math.sin(a) * r) }
        end
        for i = 0, n - 2, 2 do
            draw.filled_quad(X(cx), Y(cy), pts[i][1], pts[i][2], pts[i + 1][1], pts[i + 1][2], pts[i + 2][1], pts[i + 2][2], col(c))
        end
    end
    -- half disc (top half) for bullet tips
    function P.dome(cx, cy, r, c) fan(cx, cy, r, 180, 360, c) end
    -- rounded rect; corners = "tl tr br bl" flags (default all rounded)
    function P.rrect(x, y, w, h, r, c, corners)
        corners = corners or { true, true, true, true }
        P.rect(x + r, y, w - 2 * r, h, c)
        P.rect(x, y + r, r, h - 2 * r, c)
        P.rect(x + w - r, y + r, r, h - 2 * r, c)
        local cs = { { x + r, y + r, 180, 270, x, y }, { x + w - r, y + r, 270, 360, x + w - r, y },
                     { x + w - r, y + h - r, 0, 90, x + w - r, y + h - r }, { x + r, y + h - r, 90, 180, x, y + h - r } }
        for i, cdef in ipairs(cs) do
            if corners[i] then fan(cdef[1], cdef[2], r, cdef[3], cdef[4], c)
            else P.rect(cdef[5], cdef[6], r, r, c) end
        end
    end
    -- rounded outline of thickness t
    function P.ring(x, y, w, h, r, t, c)
        P.rect(x + r, y, w - 2 * r, t, c); P.rect(x + r, y + h - t, w - 2 * r, t, c)
        P.rect(x, y + r, t, h - 2 * r, c); P.rect(x + w - t, y + r, t, h - 2 * r, c)
        local cs = { { x + r, y + r, 180 }, { x + w - r, y + r, 270 }, { x + w - r, y + h - r, 0 }, { x + r, y + h - r, 90 } }
        for _, cdef in ipairs(cs) do
            local n = 6
            for i = 0, n - 1 do
                local a1, a2 = math.rad(cdef[3] + 90 * i / n), math.rad(cdef[3] + 90 * (i + 1) / n)
                local ri = r - t
                draw.filled_quad(X(cdef[1] + math.cos(a1) * r), Y(cdef[2] + math.sin(a1) * r),
                                 X(cdef[1] + math.cos(a2) * r), Y(cdef[2] + math.sin(a2) * r),
                                 X(cdef[1] + math.cos(a2) * ri), Y(cdef[2] + math.sin(a2) * ri),
                                 X(cdef[1] + math.cos(a1) * ri), Y(cdef[2] + math.sin(a1) * ri), col(c))
            end
        end
    end
    function P.handle(c)
        P.rect(20, 6, 24, 5, c); P.rect(20, 11, 5, 6, c); P.rect(39, 11, 5, 6, c)
    end
    return P
end

-- muted palette (0xBBGGRR)
function HUD.medic_bag(ox, oy, k, dim)
    local p = painter(ox, oy, k, dim)
    p.handle(0x1E1E46)
    p.rrect(6, 17, 52, 41, 7, 0x24247A)
    p.rect(27, 24, 10, 28, 0xBEC6CE)
    p.rect(18, 33, 9, 10, 0xBEC6CE)
    p.rect(37, 33, 9, 10, 0xBEC6CE)
end

function HUD.ammo_bag(ox, oy, k, dim)
    local p = painter(ox, oy, k, dim)
    p.handle(0x1A241B)
    p.rrect(6, 17, 52, 13, 6, 0x223424, { true, true, false, false })
    p.rrect(6, 30, 52, 28, 6, 0x2E4630, { false, false, true, true })
    p.rect(28, 24, 8, 6, 0x4C7E92)
    for _, cx in ipairs({ 19, 32, 45 }) do
        p.dome(cx, 38, 4.5, 0x3C5A86)
        p.rect(cx - 4.5, 38, 9, 12, 0x5089A2)
        p.rect(cx - 4.5, 50, 9, 3, 0x36566A)
    end
end

-- one HUD slot: panel + rim + icon + cooldown shade; adds label requests
function HUD.slot(icon, ox, oy, S, remaining, total, badge, badge_col, badge_txt_col, labels)
    local k = S / 64
    local ready = remaining <= 0
    local p = painter(ox, oy, k, false)
    local panel = painter(ox, oy, k, false, st.hud_panel_alpha)
    panel.rrect(-5, -5, 74, 74, 9, 0x101010)
    p.ring(-7, -7, 78, 78, 10, 2.5, ready and 0x5E8E5E or 0x404040)
    icon(ox, oy, k, not ready)
    if not ready then
        local f = math.max(0, math.min(1, remaining / math.max(total, 1)))
        draw.filled_rect(ox - 5 * k, oy - 5 * k, 74 * k, 74 * k * f, 0x50000000)
        labels[#labels + 1] = { x = ox + 32 * k, y = oy + 32 * k, text = tostring(math.ceil(remaining)), size = math.floor(S * 0.5), col = 0xE6E6E6E6 }
    end
    if badge then   -- player 2's button for it (none with the AI partner: it uses the wheel)
        painter(ox, oy, k, false, 0xD0).rrect(53, 53, 18, 18, 9, badge_col)
        labels[#labels + 1] = { x = ox + 62 * k, y = oy + 62 * k, text = badge, size = math.floor(S * 0.24), col = badge_txt_col }
    end
end

-- centred text, drawn in one transparent click-through window
local LABEL_FLAGS = 1 | 2 | 4 | 8 | 128 | 256 | 512 | 4096 | 8192 | 786432
function HUD.flush_labels(labels)
    if #labels == 0 then return end
    local ds = imgui.get_display_size()
    imgui.set_next_window_pos(Vector2f.new(0, 0), 1, Vector2f.new(0, 0))
    imgui.set_next_window_size(Vector2f.new(ds.x, ds.y), 1)
    if imgui.begin_window("reunited_labels", true, LABEL_FLAGS) then
        for _, l in ipairs(labels) do
            local pushed = pcall(imgui.push_font_size, l.size)
            local ts = imgui.calc_text_size(l.text)
            local x, y = l.x - ts.x / 2, l.y - ts.y / 2
            imgui.set_cursor_screen_pos(Vector2f.new(x + 2, y + 2))
            imgui.text_colored(l.text, 0xFF000000)
            imgui.set_cursor_screen_pos(Vector2f.new(x, y))
            imgui.text_colored(l.text, l.col)
            if pushed then imgui.pop_font_size() end
        end
        imgui.end_window()
    end
end


-- Weapon silhouettes on a 64x32 grid, muzzle to the right. Pieces never overlap so the
-- semi-transparent white stays even. Picked by weapon family.
local WEAPON_SHAPES = {
    pistol = function(p, c)
        p.rect(14, 7, 34, 7, c); p.rect(48, 8, 3, 5, c); p.rect(18, 14, 26, 3, c)
        p.quad(18, 17, 26, 17, 23, 29, 15, 29, c)
        p.rect(34, 17, 2, 5, c); p.rect(26, 22, 10, 2, c)
    end,
    shotgun = function(p, c)
        p.quad(4, 12, 16, 10, 16, 17, 4, 21, c)
        p.rect(16, 9, 14, 8, c); p.rect(30, 9, 30, 3, c)
        p.rect(30, 12, 4, 2, c); p.rect(34, 12, 13, 4, c); p.rect(47, 12, 10, 2, c)
        p.rect(20, 17, 7, 2, c)
    end,
    smg = function(p, c)
        p.rect(6, 10, 12, 2, c); p.rect(6, 12, 3, 7, c)
        p.rect(18, 8, 26, 8, c); p.rect(44, 10, 12, 3, c); p.rect(56, 9, 2, 5, c)
        p.rect(27, 16, 5, 12, c)
        p.quad(19, 16, 24, 16, 22, 25, 17, 25, c)
    end,
    knife = function(p, c)
        p.rect(6, 13, 14, 6, c); p.rect(20, 10, 3, 12, c)
        p.quad(23, 12, 52, 12, 58, 15, 23, 19, c)
    end,
    grenade = function(p, c)
        p.rrect(24, 10, 16, 19, 5, c)
        p.rect(27, 5, 10, 5, c)
        p.quad(37, 6, 41, 7, 42, 21, 40, 21, c)
        p.ring(16, 2, 8, 8, 4, 1.6, c)
    end,
    launcher = function(p, c)
        p.quad(4, 12, 16, 10, 16, 17, 4, 21, c)
        p.rect(16, 10, 12, 7, c); p.rect(28, 8, 26, 11, c)
        p.rect(20, 17, 5, 9, c)
    end,
    rocket = function(p, c)
        p.rect(2, 11, 4, 7, c); p.rect(6, 10, 50, 9, c); p.rect(56, 8, 4, 13, c)
        p.rect(26, 5, 8, 5, c)
        p.rect(22, 19, 4, 8, c); p.rect(34, 19, 4, 6, c)
    end,
    flamer = function(p, c)
        p.rrect(4, 8, 13, 17, 4, c)
        p.rect(17, 12, 11, 6, c); p.rect(28, 13, 24, 3, c); p.rect(52, 11, 5, 7, c)
        p.rect(22, 18, 4, 8, c)
    end,
    minigun = function(p, c)
        p.rrect(8, 7, 22, 15, 3, c)
        p.rect(30, 8, 28, 2, c); p.rect(30, 12, 28, 3, c); p.rect(30, 17, 28, 2, c)
        p.rect(14, 22, 5, 7, c); p.rect(14, 3, 10, 4, c)
    end,
}
local FAMILY = { [31] = "pistol", [82] = "pistol", [83] = "pistol", [84] = "pistol", [85] = "pistol", [42] = "launcher", [44] = "launcher", [43] = "flamer",
    [45] = "rocket", [49] = "rocket", [50] = "minigun" }
local function weapon_family(wt)
    if wt == nil or wt <= 0 then return nil end
    if FAMILY[wt] then return FAMILY[wt] end
    if wt <= 10 then return "pistol" end
    if wt <= 20 then return "shotgun" end
    if wt <= 30 then return "smg" end
    if wt >= 46 and wt <= 48 then return "knife" end
    if wt >= 63 and wt <= 66 then return "grenade" end
    return nil
end
function HUD.weapon_icon(wt, ox, oy, S, active)
    local shape = WEAPON_SHAPES[weapon_family(wt) or ""]
    if shape == nil then return end
    local k = S / 64
    local a = active and st.hud_alpha or math.floor(st.hud_alpha * 0.45)
    shape(painter(ox + 1.5 * k, oy + 1.5 * k, k, false, math.floor(a * 0.5)), 0x000000)   -- soft shadow
    shape(painter(ox, oy, k, false, a), 0xFFFFFF)
end

local hud_weapons = { frame = -100, main = nil, sub = nil }
local function hunk_weapons()
    if st.frame - hud_weapons.frame >= 10 then
        hud_weapons.frame = st.frame
        local hinv = comp(st.hunk, "app.ropeway.survivor.Inventory")
        local heq = comp(st.hunk, "app.ropeway.survivor.Equipment")
        local ms = hinv and safe(function() return hinv:call("get_MainSlot") end)
        hud_weapons.main = ms and safe(function() return ms:call("get_WeaponType") end) or nil
        hud_weapons.sub = heq and safe(function() return heq:call("get_SubType") end) or nil
    end
    return hud_weapons.main, hud_weapons.sub
end

-- Experimental: off-screen indicator ---------------------------------------------------
-- When HUNK is outside the view, a soft chevron sits on the screen edge pointing at him.
-- Closer = bigger and a little stronger; it fades in/out instead of popping.
local ind = { a = 0, dx = 0, dy = 1 }
local function draw_offscreen()
    local show, d, near = false, nil, 0
    -- not in Fixed Camera Mode: the fixed cameras show both players most of the time
    if st.offscreen_ind and st.hunk and not (st.p2_cc and st.cc and st.cc.get()) then
        local cs = sdk.get_managed_singleton("app.ropeway.camera.CameraSystem")
        local cp = cs and safe(function() return cs:call("get_CameraPosition") end)
        local cr = cs and safe(function() return cs:call("get_CameraRotation") end)
        local hp = safe(function() return st.hunk:call("get_Transform"):call("get_Position") end)
        if cp and cr and hp then
            local t = Vector3f.new(hp.x, hp.y + 1.2, hp.z)
            local ds = imgui.get_display_size()
            local m = ds.y * 0.06
            local sp = draw.world_to_screen(t)
            local v = t - cp
            local fwd = cr * Vector3f.new(0, 0, -1)
            local inside = sp ~= nil and (v.x * fwd.x + v.y * fwd.y + v.z * fwd.z) > 0
                and sp.x > m and sp.x < ds.x - m and sp.y > m and sp.y < ds.y - m
            if not inside then
                local right, up = cr * Vector3f.new(1, 0, 0), cr * Vector3f.new(0, 1, 0)
                local x = v.x * right.x + v.y * right.y + v.z * right.z
                local y = -(v.x * up.x + v.y * up.y + v.z * up.z)    -- screen y points down
                local l = math.sqrt(x * x + y * y)
                if l < 1e-3 then x, y, l = 0, 1, 1 end            -- straight behind: bottom edge
                show, d = true, v:length()
                near = 1 - math.max(0, math.min(1, (d - 2) / 23))  -- 1 at <=2 m, 0 at >=25 m
                -- smooth the direction so it glides along the edge
                local k = 0.25
                ind.dx = ind.dx + (x / l - ind.dx) * k
                ind.dy = ind.dy + (y / l - ind.dy) * k
                ind.near = near
            end
        end
    end
    ind.a = ind.a + ((show and 1 or 0) - ind.a) * 0.15
    if ind.a < 0.02 then return end
    local ds = imgui.get_display_size()
    local dl = math.sqrt(ind.dx * ind.dx + ind.dy * ind.dy)
    if dl < 1e-3 then return end
    local dx, dy = ind.dx / dl, ind.dy / dl
    local n = ind.near or 0
    local size = ds.y * (0.018 + 0.03 * n)
    local m = ds.y * 0.05 + size
    local cx, cy = ds.x * 0.5, ds.y * 0.5
    local t = math.min((ds.x * 0.5 - m) / math.max(math.abs(dx), 1e-3), (ds.y * 0.5 - m) / math.max(math.abs(dy), 1e-3))
    local px, py = cx + dx * t, cy + dy * t
    local alpha = math.floor((0x60 + 0x50 * n) * ind.a)
    local col = (alpha << 24) | 0xC8E6C8        -- pale green-white (0xBBGGRR)
    local qx, qy = -dy, dx                         -- perpendicular
    local tipx, tipy = px + dx * size, py + dy * size
    local lx, ly = px - dx * size * 0.55 + qx * size * 0.75, py - dy * size * 0.55 + qy * size * 0.75
    local rx, ry = px - dx * size * 0.55 - qx * size * 0.75, py - dy * size * 0.55 - qy * size * 0.75
    local nx, ny = px - dx * size * 0.05, py - dy * size * 0.05
    draw.filled_quad(tipx, tipy, lx, ly, nx, ny, nx, ny, col)
    draw.filled_quad(tipx, tipy, nx, ny, rx, ry, rx, ry, col)
    draw.filled_circle(px - dx * size * 0.95, py - dy * size * 0.95, size * 0.22, (math.floor(alpha * 0.8) << 24) | 0xC8E6C8, 16)
end

-- Player 2's shortcut cross: pops up when he presses the d-pad (like player 1's), with the gun
-- on each direction, or with LB held his knife / grenades; the one in his hands is framed.
-- Bottom right of his half in split screen, under his HUD boxes on a shared screen.
st.p2cross = nil
function st.draw_p2cross(labels, right, top, bottom, below)
    local c = st.p2cross
    if c == nil or st.p2inv == nil then return end
    -- (the game-styled cross, st.dual.sc, replaces this drawn one once it has been built)
    if st.p2_shortcut_gui ~= false and st.dual and st.dual.sc and st.dual.sc.el then return end
    local age = os.clock() - c.t
    if age > 2.6 then st.p2cross = nil; return end
    local fade = age < 2.2 and 1 or math.max(0, 1 - (age - 2.2) / 0.4)
    local hinv = st.p2inv.hunk_inv()
    if hinv == nil then return end
    local P = st.p2inv
    local ds = imgui.get_display_size()
    local S = math.floor(ds.y * 0.062)
    local d = math.floor(S * 1.1)
    local margin = math.floor(S * 0.9)
    local cx, cy
    if p2c.active then
        cx, cy = right - margin - d - S / 2, bottom - margin - d - S / 2
    else
        cx, cy = right - margin - d - S / 2, below + d + S / 2
    end
    local held = c.sub and P.sub_index(hinv) or P.main_index(hinv)
    local sig = c.sub and P.SUB_SIG or "getSlot(app.ropeway.EquipmentDefine.Shortcut)"
    local POS = { [0] = { 0, -1 }, [1] = { 0, 1 }, [2] = { -1, 0 }, [3] = { 1, 0 } }
    local old_alpha = st.hud_alpha
    st.hud_alpha = math.floor(old_alpha * fade)
    local pa = math.floor(0xB0 * fade)
    for sc = 0, 3 do
        local x, y = cx + POS[sc][1] * d - S / 2, cy + POS[sc][2] * d - S / 2
        local k = S / 64
        local idx = safe(function() return hinv:call(sig, sc):call("get_Index") end)
        local sl = idx and idx >= 0 and P.slot_at(hinv, idx) or nil
        local wt = sl and safe(function() return sl:call("get_WeaponType") end) or -1
        local on = idx ~= nil and idx >= 0 and idx == held and wt > 0
        painter(x, y, k, false, pa).rrect(0, 0, 64, 64, 9, 0x101010)
        if on then painter(x, y, k, false, math.floor(0xE0 * fade)).ring(-3, -3, 70, 70, 11, 3, 0x7EC8E6) end
        if wt > 0 then
            HUD.weapon_icon(wt, x + 3 * k, y + 14 * k, S * 0.9, true)
            local n = safe(function() return sl:call("get_Number") end)
            if n and wt ~= 46 then
                labels[#labels + 1] = { x = x + 48 * k, y = y + 52 * k, text = tostring(n), size = math.floor(S * 0.3),
                    col = (math.floor(0xF0 * fade) << 24) | 0xE6E6E6 }
            end
        end
    end
    -- centre: LB when it's his knife / grenades
    if c.sub then
        labels[#labels + 1] = { x = cx, y = cy, text = "LB", size = math.floor(S * 0.32), col = (math.floor(0xF0 * fade) << 24) | 0xE6E6E6 }
    else
        painter(cx - S * 0.12, cy - S * 0.12, S / 64, false, pa).rrect(0, 0, 15, 15, 4, 0x101010)
    end
    st.hud_alpha = old_alpha
end

local function draw_hud(labels)
    -- shown with the AI partner too: her heal / reload orders share these cooldowns
    if not st.show_hud or st.hunk == nil then return end
    if st.ig and st.ig.open then return end   -- (his inventory screen is up)
    local ds = imgui.get_display_size()
    local S = math.floor(ds.y * 0.065)
    local gap, margin = math.floor(S * 0.35), math.floor(S * 0.4)
    local now = os.clock()
    -- split screen: it's player 2's HUD, so it goes in the top right of player 2's half
    local right, top = ds.x, 0
    if p2c.active then
        local r = (p2c.regions[st.split_layout] or p2c.regions[1]).p2
        right, top = r[3] * ds.x, r[2] * ds.y
    end
    local x2 = right - margin - S
    local x1 = x2 - gap - S
    local cool = st.hud_cooldowns
    if cool then
        local human = not ai.active
        HUD.slot(HUD.medic_bag, x1, top + margin, S, st.next_heal - now, st.heal_cooldown, human and "Y" or nil, 0x3CA4BE, 0xF0141414, labels)
        HUD.slot(HUD.ammo_bag, x2, top + margin, S, st.next_resupply - now, st.resupply_cooldown, human and "X" or nil, 0xA86A3C, 0xF0E8E8E8, labels)
    end
    if not st.hud_weapons then return end
    -- HUNK's main weapon (left) and sub-weapon (right) under the boxes; the one in his
    -- hands is bright, the other dimmed
    local main, sub = hunk_weapons()
    local sub_up = hunk_sub_holding()
    local wy = top + (cool and margin + S + math.floor(S * 0.3) or margin)
    HUD.weapon_icon(main, x1, wy, S, not sub_up)
    HUD.weapon_icon(sub, x2, wy, S, sub_up)
    local bottom = ds.y
    if p2c.active then
        local r = (p2c.regions[st.split_layout] or p2c.regions[1]).p2
        bottom = r[4] * ds.y
    end
    pcall(st.draw_p2cross, labels, right, top, bottom, wy + S)
end

-- Gimmick areas (ladders, ledges, event zones...) only react to player 1. The game's trigger areas
-- check every player-like object inside them (TriggerArea.checkAreaLimitter(GameObject), called
-- each frame per occupant), and HUNK counted: with him standing at the top of a ladder its
-- "ClimbDown" key stayed armed, and player 1 pushing the stick anywhere ran it for her, walking
-- her back from across the room and down the ladder again. HUNK is refused here, so his presence
-- arms nothing; his own A-button pickups and doors don't go through these areas.
do
    local ta = sdk.find_type_definition("app.ropeway.gimmick.action.TriggerArea")
    local m = ta and ta:get_method("checkAreaLimitter")
    if m then
        sdk.hook(m, function(args)
            local hs = thread.get_hook_storage()
            hs.no = false
            if st.hunk == nil then return end
            if (sdk.to_int64(args[3]) & 0xFFFFFFFFFFFF) == (st.hunk:get_address() & 0xFFFFFFFFFFFF) then
                hs.no = true
                return sdk.PreHookResult.SKIP_ORIGINAL
            end
        end, function(r)
            if thread.get_hook_storage().no then return sdk.to_ptr(0) end
            return r
        end)
    end
end

-- A: pick up the item nearest HUNK for Leon ------------------------------------------
-- World items are SetItem gimmicks with a "PickUp" TriggerKey. We activate that trigger
-- with Leon as the activator and report its button as pressed for a few frames; the
-- game then runs its normal pickup (item screen, inventory-full handling, save flags)
-- for Leon, wherever he is standing.
local ADDR_MASK = 0xFFFFFFFFFFFF
local TK = sdk.find_type_definition("app.ropeway.gimmick.action.TriggerKey")
for _, mn in ipairs({ "checkButtonDown", "checkButtonOn" }) do
    sdk.hook(TK:get_method(mn), function(args)
        local hs = thread.get_hook_storage()
        hs.force = st.force_trig_addr ~= nil and (sdk.to_int64(args[2]) & ADDR_MASK) == st.force_trig_addr
    end, function(r)
        if thread.get_hook_storage().force then return sdk.to_ptr(1) end
        return r
    end)
end

-- (NonRT-14) On Non-RT the pick-up only goes through with player 1 near the item: the trigger's
-- player-distance check (TriggerKey RANGE_MAX_PL_DIST_CHECK 1.5 m from player 1) refused player
-- 2's A from anywhere else ("can't pick it up" with room in his inventory; a test with player 1
-- teleported next to him picked it up). For the trigger our A press is holding, the validity
-- checks pass and its distance from player 1 counts as zero.
if st.NON_RT then
    local function forced(args) return st.force_trig_addr ~= nil and (sdk.to_int64(args[2]) & ADDR_MASK) == st.force_trig_addr end
    for _, spec in ipairs({ { "app.ropeway.gimmick.action.TriggerKey", "checkValid" }, { "app.ropeway.gimmick.action.TriggerKey", "checkValidOnlyKey" },
        { "app.ropeway.gimmick.action.Trigger", "checkValid" } }) do
        local td = sdk.find_type_definition(spec[1])
        for _, m in ipairs(td and td:get_methods() or {}) do
            if m:get_name() == spec[2] then
                pcall(sdk.hook, m, function(args)
                    thread.get_hook_storage().fv = forced(args)
                end, function(r)
                    if thread.get_hook_storage().fv then return sdk.to_ptr(1) end
                    return r
                end)
            end
        end
    end
    -- the world item's own checks of player 1 (inside its area, same map): passed for the item
    -- our A press is on (st.force_si_addr, set with st.force_trig_addr)
    local function forced_si(args) return st.force_trig_addr ~= nil and st.force_si_addr ~= nil and (sdk.to_int64(args[2]) & ADDR_MASK) == st.force_si_addr end
    local SI = sdk.find_type_definition("app.ropeway.gimmick.action.SetItem")
    for _, m2 in ipairs(SI and SI:get_methods() or {}) do
        local n = m2:get_name()
        if n == "isValidTrigger" or n == "checkSameMapIdWithPlayer" or n:find("^<getTriggerFuncCheckValid>") then
            pcall(sdk.hook, m2, function(args)
                thread.get_hook_storage().fs = forced_si(args)
            end, function(r)
                if thread.get_hook_storage().fs then return sdk.to_ptr(1) end
                return r
            end)
        end
    end
    local m = TK:get_method("calcLengthSqFromPl")
    if m and sdk.float_to_ptr then
        pcall(sdk.hook, m, function(args)
            thread.get_hook_storage().fl = forced(args)
        end, function(r)
            if thread.get_hook_storage().fl then return sdk.float_to_ptr(0.0) end
            return r
        end)
    end
end

local item_cache, item_cache_frame = {}, -1000
local function scan_items()
    local scene = sdk.call_native_func(sdk.get_native_singleton("via.SceneManager"),
        sdk.find_type_definition("via.SceneManager"), "get_CurrentScene")
    local list = scene and scene:call("findComponents(System.Type)", sdk.typeof("app.ropeway.gimmick.action.SetItem"))
    local out = {}
    if list then
        for i = 0, list:call("get_Count") - 1 do out[#out + 1] = list:call("get_Item", i) end
    end
    item_cache = out
end

local function pick_trigger(si)
    local go = si:call("get_GameObject")
    local ib = comp(go, "app.ropeway.gimmick.action.InteractBehavior")
    local trs = ib and ib:get_field("MyInteract") and ib:get_field("MyInteract"):get_field("Triggers")
    if trs == nil then return nil end
    for i = 0, trs:call("get_Count") - 1 do
        local t = trs:call("get_Item", i)
        local tn = t and t:get_type_definition():get_full_name() or ""
        if tn:find("TriggerKey", 1, true) and t:call("get_IsEnabled") then return t end
    end
    return nil
end

local function find_pick_target()
    if st.hunk == nil then return nil end
    if st.frame - item_cache_frame >= 20 then item_cache_frame = st.frame; pcall(scan_items) end
    local hp = st.hunk:call("get_Transform"):call("get_Position")
    local best, bd = nil, st.pick_radius
    for _, si in ipairs(item_cache) do
        local ok, d = pcall(function()
            local go = si:call("get_GameObject")
            if not (go:call("get_DrawSelf") and go:call("get_UpdateSelf")) or si:call("get_DisableInteract") then return nil end
            local pos = si:call("get_Position")
            if math.abs(pos.y - hp.y) > 1.6 then return nil end
            return math.sqrt((pos.x - hp.x) ^ 2 + (pos.z - hp.z) ^ 2)
        end)
        if ok and d and d < bd then best, bd = si, d end
    end
    return best
end

-- Doors only ever open for Leon (the game's door logic looks at Leon alone), so when
-- HUNK presses A at an unlocked door he steps through to the other side instead.
local door_cache, door_cache_frame = {}, -1000
local function find_door()
    if st.frame - door_cache_frame >= 60 then
        door_cache_frame = st.frame
        door_cache = {}
        local scene = sdk.call_native_func(sdk.get_native_singleton("via.SceneManager"),
            sdk.find_type_definition("via.SceneManager"), "get_CurrentScene")
        local l = scene and scene:call("findComponents(System.Type)", sdk.typeof("app.ropeway.gimmick.action.GimmickDoorBase"))
        for i = 0, (l and l:call("get_Count") or 0) - 1 do door_cache[#door_cache + 1] = l:call("get_Item", i) end
    end
    local hp = st.hunk:call("get_Transform"):call("get_Position")
    local best, bd = nil, 1.6
    for _, d in ipairs(door_cache) do
        local c = safe(function() return d:call("get_Center") end)
        if c and math.abs(c.y - hp.y) < 1.8 then
            local dist = math.sqrt((c.x - hp.x) ^ 2 + (c.z - hp.z) ^ 2)
            if dist < bd then best, bd = d, dist end
        end
    end
    return best
end

-- Ladders (GimmickLadder: _PosLow / _PosHigh the two ends, LadderHeight). startJack(ClimbType,
-- GameObject) puts any survivor on it: HUNK climbs with the game's own animation (ladder_pl00
-- motions through the gimmick's MotionJack) and steps off at the other end, as player 1 does;
-- tried on the library ladder, 5.2 m up in about 6 s. ClimbType UP = 0, DOWN = 1. checkUsable()
-- is false while the ladder isn't in place (the library ladder before it's pushed) or in use.
do
local ladder_cache, ladder_cache_frame = {}, -1000
local function ladder_list()
    if st.frame - ladder_cache_frame >= 120 then
        ladder_cache_frame = st.frame
        ladder_cache = {}
        pcall(function()
            local scene = sdk.call_native_func(sdk.get_native_singleton("via.SceneManager"), sdk.find_type_definition("via.SceneManager"), "get_CurrentScene")
            local l = scene:call("findComponents(System.Type)", sdk.typeof("app.ropeway.gimmick.action.GimmickLadder"))
            for i = 0, l:call("get_Count") - 1 do ladder_cache[#ladder_cache + 1] = l:call("get_Item", i):add_ref() end
        end)
    end
    return ladder_cache
end
st.ladder_list = ladder_list
-- the ladder end HUNK stands at: ladder, ClimbType (0 up from the bottom, 1 down from the top), end position
local function find_ladder()
    if st.hunk == nil then return nil end
    local hp = st.hunk:call("get_Transform"):call("get_Position")
    local best, bd, bt, bpos = nil, 0.9, nil, nil
    for _, lad in ipairs(ladder_list()) do
        for ct, f in pairs({ [0] = "_PosLow", [1] = "_PosHigh" }) do
            local p = safe(function() return lad:get_field(f):call("get_Transform"):call("get_Position") end)
            if p and math.abs(p.y - hp.y) < 0.6 then
                local d = math.sqrt((p.x - hp.x) ^ 2 + (p.z - hp.z) ^ 2)
                if d < bd and safe(function() return lad:call("checkUsable") end) == true then best, bd, bt, bpos = lad, d, ct, p end
            end
        end
    end
    return best, bt, bpos
end
st.find_ladder = find_ladder
local function ladder_climb(lad, ct)
    if st.climb_until and os.clock() < st.climb_until then return true end
    local ok, r = pcall(lad.call, lad, "startJack", ct, st.hunk)
    if ok and r then
        st.climb_until = os.clock() + 2.0   -- (A again during the climb does nothing)
        st.climb_lad = lad:get_address()
        return true
    end
    toast(st.p2_name() .. " can't use the ladder right now")
    return true
end
st.ladder_climb = ladder_climb
-- (v382) one at a time: player 1 starting a ladder (or a jump-down, any player jack) that
-- player 2 is on got her stuck on it. While player 2 is in a gimmick's hands, that gimmick
-- refuses player 1: its startJack / execPlayerJack for her does nothing, and its checkUsable
-- reads false (no prompt). Player 2 can't take one player 1 is on already (checkUsable is
-- false while she's on it, and find_ladder needs it).
function st.gimmick_held_by_p2(gb)
    local h = st.hunk
    if h == nil or gb == nil then return false end
    local addr = gb:get_address()
    if st.climb_lad == addr and st.climb_until and os.clock() < st.climb_until then return true end
    local jd = comp(h, "app.ropeway.JackDominator")
    if not (jd and safe(function() return jd:call("get_Jacked") end) == true) then return false end
    local own = safe(function() return jd:get_field("<JackOwner>k__BackingField") end)
    local g = own and safe(function() return own:get_field("<GimmickBody>k__BackingField") end)
    return g ~= nil and g:get_address() == addr
end
do
    local function is_p1(go_ptr)
        local p1 = p1_go()
        return p1 ~= nil and go_ptr ~= nil and sdk.to_int64(go_ptr) == p1:get_address()
    end
    local function refuse_for_p1(tname, mname, go_arg)
        local td = sdk.find_type_definition(tname)
        local m = td and td:get_method(mname)
        if m == nil then return end
        sdk.hook(m, function(args)
            local s = thread.get_hook_storage()
            s.refused = false
            if st.hunk == nil or not is_p1(args[go_arg]) then return end
            local gb = sdk.to_managed_object(args[2])
            if st.gimmick_held_by_p2(gb) then
                s.refused = true
                return sdk.PreHookResult.SKIP_ORIGINAL
            end
        end, function(r)
            if thread.get_hook_storage().refused then return sdk.to_ptr(0) end
            return r
        end)
    end
    -- startJack(ClimbType, GameObject): args 2 this, 3 type, 4 player
    refuse_for_p1("app.ropeway.gimmick.action.GimmickLadder", "startJack", 4)
    -- execPlayerJack(PlayerJackParam, GameObject)
    refuse_for_p1("app.ropeway.gimmick.action.PlayerJackBase", "execPlayerJack", 4)
    local td = sdk.find_type_definition("app.ropeway.gimmick.action.GimmickLadder")
    local cu = td and td:get_method("checkUsable")
    if cu then
        sdk.hook(cu, function(args)
            thread.get_hook_storage().busy = st.hunk ~= nil and st.gimmick_held_by_p2(sdk.to_managed_object(args[2]))
        end, function(r)
            if thread.get_hook_storage().busy then return sdk.to_ptr(0) end
            return r
        end)
    end
end
-- (v371, v381) a gimmick move (ladder, jump-down, any player jack) sometimes doesn't let go of
-- player 2 at its end: he's back standing but the gimmick still holds his jack (JackDominator's
-- owner the gimmick, motion layer 3 left on JACKED), so he won't move. The gimmick's
-- endPlayerJack lets him go (tried at the library ladder's top).
-- How it's told apart from a move still going on: he hasn't moved (5 cm) for 1.5 s, at least
-- 2 s in. (v371 went by motion layer 0 reading STAND for a second, but it reads STAND.IDLE for
-- the whole climb too, the climb plays on layer 3: it cut every climb off after a second and
-- he dropped back to the floor.)
local W = { since = nil, owner = nil, still_from = nil, ref = nil }
st.jack_watch = W   -- (dev bridge)
re.on_application_entry("LateUpdateBehavior", function()
    pcall(function()
        local h = st.hunk
        local jd = h and comp(h, "app.ropeway.JackDominator")
        local own = jd and jd:get_field("<JackOwner>k__BackingField")
        local gb = own and own:get_field("<GimmickBody>k__BackingField")
        if gb == nil or not gb:get_type_definition():is_a("app.ropeway.gimmick.action.PlayerJackBase") then
            W.since, W.owner, W.still_from, W.ref = nil, nil, nil, nil
            return
        end
        local now = os.clock()
        local p = h:call("get_Transform"):call("get_Position")
        if W.owner ~= gb:get_address() then
            W.owner, W.since, W.still_from, W.ref = gb:get_address(), now, now, p
            return
        end
        if (p - W.ref):length() > 0.05 then W.still_from, W.ref = now, p; return end
        if now - W.since >= 2.0 and now - W.still_from >= 1.5 then
            W.since, W.owner, W.still_from, W.ref = nil, nil, nil, nil
            gb:call("endPlayerJack", h)
            st.climb_until = nil
            W.released = (W.released or 0) + 1
        end
    end)
end)
end

-- Jump-downs, drops and other one-way moves player 1 makes through a gimmick (v315). Every such
-- move is a "player jack": the gimmick calls PlayerJackBase.execPlayerJack(PlayerJackParam,
-- player GameObject) and the player plays the jack's motion (StateName, interpolated to the
-- gimmick's InterpPos / InterpRot); endPlayerJack when it's over (traced on the library ladder:
-- StartClimbDown2). Each one player 1 makes is remembered with her start point, the jack's
-- parameters and where she ended up. A move that took her up or down a floor (> 1 m) or 2 m+
-- across is one player 2 can follow: his A at that start point (within 0.9 m) runs the same jack
-- on HUNK, so he plays the same motion; if the gimmick won't take him, he's put where she landed
-- (the rooms there made drawn first). Ladders keep their own handling (startJack). Not yet tried
-- on a real jump-down (none in the police station).
do
local JK = { list = {} }
st.jack_follow = JK   -- (dev bridge)
local EXCLUDE = { ["app.ropeway.gimmick.action.GimmickLadder"] = true }
JK.exclude = EXCLUDE   -- (dev bridge)
local jtd = sdk.find_type_definition("app.ropeway.gimmick.action.PlayerJackBase")
pcall(sdk.hook, jtd:get_method("execPlayerJack"), function(args)
    if JK.replay then return end   -- (our own call for HUNK)
    pcall(function()
        local p1 = p1_go()
        if p1 == nil or (sdk.to_int64(args[4]) & ADDR_MASK) ~= (p1:get_address() & ADDR_MASK) then return end
        local body = sdk.to_managed_object(args[2])
        local tn = body:get_type_definition():get_full_name()
        if EXCLUDE[tn] then return end
        local param = sdk.to_managed_object(args[3])
        local pos = p1:call("get_Transform"):call("get_Position")
        local key = body:get_address() & ADDR_MASK
        JK.list[key] = { body = body:add_ref(), param = param and param:add_ref(), type = tn, key = key,
            name = body:call("get_GameObject"):call("get_Name"),
            start = Vector3f.new(pos.x, pos.y, pos.z), frame = st.frame }
        JK.watch = { key = key, until_f = st.frame + 1800 }
    end)
end, function(r) return r end)
pcall(sdk.hook, jtd:get_method("endPlayerJack"), function(args)
    local w = JK.watch
    if w and (sdk.to_int64(args[2]) & ADDR_MASK) == w.key then w.ended = st.frame end
end, function(r) return r end)
-- (where she ends up: 10 frames after the jack ends, or 30 s at most)
function st.jack_watch_tick()
    local w = JK.watch
    if w == nil then return end
    if not (st.frame > w.until_f or (w.ended and st.frame - w.ended >= 10)) then return end
    JK.watch = nil
    local e = JK.list[w.key]
    local p1 = p1_go()
    if e == nil or p1 == nil then return end
    local xf = p1:call("get_Transform")
    local p = xf:call("get_Position")
    e.end_pos, e.end_rot = Vector3f.new(p.x, p.y, p.z), xf:call("get_Rotation")
    local dx, dz = p.x - e.start.x, p.z - e.start.z
    e.follow = math.abs(p.y - e.start.y) > 1.0 or (dx * dx + dz * dz) > 4.0
end
-- the one he's standing at
function st.find_jack()
    if st.hunk == nil then return nil end
    local hp = st.hunk:call("get_Transform"):call("get_Position")
    local best, bd = nil, 0.9
    for key, e in pairs(JK.list) do
        if e.follow then
            if not pcall(e.body.call, e.body, "get_GameObject") then
                JK.list[key] = nil
            elseif math.abs(e.start.y - hp.y) < 0.6 then
                local d = math.sqrt((e.start.x - hp.x) ^ 2 + (e.start.z - hp.z) ^ 2)
                if d < bd then best, bd = e, d end
            end
        end
    end
    return best
end
function st.jack_use(e)
    if st.jack_until and os.clock() < st.jack_until then return true end
    local ids = {}
    pcall(function()
        local rooms = e.body:call("get_MyRooms")
        for j = 0, rooms:call("get_Length") - 1 do
            local b = rooms:call("GetValue", j)
            ids[#ids + 1] = type(b) == "number" and b or b:get_field("value__")
        end
    end)
    pcall(st.area_ready, ids)
    local ok, r = false, nil
    if e.param and not e.no_jack then
        JK.replay = true
        ok, r = pcall(e.body.call, e.body, "execPlayerJack", e.param, st.hunk)
        JK.replay = false
    end
    JK.last = { name = e.name, ok = ok, r = tostring(r), frame = st.frame }
    if ok and r then
        st.jack_until = os.clock() + 2.0
        return true
    end
    e.no_jack = true   -- (warp from now on)
    if e.end_pos then
        st.warp_go(st.hunk, e.end_pos, e.end_rot)
        st.rewarp = { pos = e.end_pos, rot = e.end_rot, frame = st.frame + 2 }
        st.jack_until = os.clock() + 1.0
        return true
    end
    toast(st.p2_name() .. " can't follow there yet")
    return true
end
end

-- Player 2 opens a door the way player 1 does. Player 1's door: the door's control claims it,
-- `requestOpenByLever(side)` swings it open from her side, and it stays open while the game's
-- contact timer (`_TimerContactPl`, kept up by player 1 touching it) runs; it closes a few
-- seconds after she has gone. HUNK isn't a "player" to the door, so the same call opened it for
-- a third of a second. Here it's opened from his side (open speed set, as walking into it
-- does) and the contact timer is kept up while he is still at it: until he's through and
-- clear, or has backed off, 10 s at most. The rooms on both sides are made drawn first.
local function door_open(door)
    local hp = st.hunk:call("get_Transform"):call("get_Position")
    local side = safe(function() return door:call("calcSide", hp) end)
    if side ~= 0 and side ~= 1 then return false end
    local ids = {}
    pcall(function()
        local rooms = door:call("get_MyRooms")
        for j = 0, rooms:call("get_Length") - 1 do
            local b = rooms:call("GetValue", j)
            ids[#ids + 1] = type(b) == "number" and b or b:get_field("value__")
        end
    end)
    pcall(st.area_ready, ids)
    if safe(function() return door:call("requestOpenByLever", side) end) ~= true then return false end
    pcall(door.call, door, "setOpenSpeed", 1.0)
    st.door_hold = { door = door:add_ref(), from = st.frame, start = st.frame, until_f = st.frame + 600 }
    return true
end
function st.door_hold_tick()
    local h = st.door_hold
    if h == nil then return end
    local done = st.hunk == nil or st.frame > h.until_f
    if not done then
        local ok, d = pcall(function()
            return (st.hunk:call("get_Transform"):call("get_Position") - h.door:call("get_Center")):length()
        end)
        -- (1.5 s to start walking; then open while he's within 2.2 m of the doorway)
        if not ok or (st.frame - h.from > 90 and d > 2.2) then done = true end
    end
    if done then st.door_hold = nil; return end
    pcall(h.door.set_field, h.door, "_TimerContactPl", 1.0)
end
st.door_open = door_open   -- (dev bridge)

-- Walking into a door pushes it open for player 2, as it does for player 1 (her push comes from
-- the player's own action code, which HUNK doesn't run, and the contact timer alone doesn't
-- move the door). Each frame the nearest door is checked: HUNK within 0.75 m of its plane and
-- inside its width, facing it, and walking or running at it (moving toward it, or in a walk /
-- jog move while the closed door stops him). It's then opened from his side with door_open
-- (same as A) and held while he's in it. Locked doors are left alone (A still says locked).
local push = { last = nil, normals = {}, cool = {} }
st.door_push_state = push   -- (dev bridge)
local function door_normal(door)
    local key = door:get_address()
    local n = push.normals[key]
    if n then return n end
    local c = door:call("get_Center")
    local rot = door:call("get_GameObject"):call("get_Transform"):call("get_Rotation")
    for _, axis in ipairs({ Vector3f.new(0, 0, 1), Vector3f.new(1, 0, 0) }) do
        local v = rot * axis
        local h = math.sqrt(v.x * v.x + v.z * v.z)
        if h > 0.5 and n == nil then
            v = Vector3f.new(v.x / h, 0, v.z / h)
            local s1 = safe(function() return door:call("calcSide", Vector3f.new(c.x + v.x * 0.9, c.y, c.z + v.z * 0.9)) end)
            local s2 = safe(function() return door:call("calcSide", Vector3f.new(c.x - v.x * 0.9, c.y, c.z - v.z * 0.9)) end)
            if s1 and s2 and s1 ~= s2 and s1 ~= 2 and s2 ~= 2 then n = v end
        end
    end
    if n == nil then return nil end   -- no clear sides: not a door to push
    push.normals[key] = n
    return n
end
function st.door_lever_tick()
    -- (the AI partner too: walking her path into a closed door opens it the same way)
    if st.door_push == false or st.hunk == nil or menu.open or st.door_wait or st.pick
        or st.p2_held_only or p1_go() == nil or st.in_cutscene() then
        push.last = nil
        return
    end
    local xf = st.hunk:call("get_Transform")
    local hp = xf:call("get_Position")
    local now = os.clock()
    local vel = nil
    if push.last and now - push.last.t > 0.001 and now - push.last.t < 0.2 then
        local dt = now - push.last.t
        vel = Vector3f.new((hp.x - push.last.p.x) / dt, 0, (hp.z - push.last.p.z) / dt)
    end
    push.last = { p = hp, t = now }
    if st.frame - door_cache_frame >= 60 then find_door() end
    local door, bd = nil, 1.6
    for _, d in ipairs(door_cache) do
        local c = safe(function() return d:call("get_Center") end)
        if c and math.abs(c.y - hp.y) < 1.8 then
            local dist = math.sqrt((c.x - hp.x) ^ 2 + (c.z - hp.z) ^ 2)
            if dist < bd then door, bd = d, dist end
        end
    end
    if door == nil then return end
    local key = door:get_address()
    local h = st.door_hold
    local c = door:call("get_Center")
    local n = door_normal(door)
    if n == nil then return end
    local rx, rz = hp.x - c.x, hp.z - c.z
    local plane = rx * n.x + rz * n.z               -- signed distance from the door's plane
    local lat = math.abs(rx * n.z - rz * n.x)       -- distance along the door from its middle
    if math.abs(plane) > 0.75 or lat > 0.7 then return end
    local tox, toz = -n.x * (plane > 0 and 1 or -1), -n.z * (plane > 0 and 1 or -1)   -- toward the door
    if h and h.door:get_address() == key then
        -- already open: keep it; shut again anyway (closed under him): let it be pushed again
        local v = safe(function() return door:get_field("_PeekedWork"):call("GetValue", 0):get_field("Value") end)
        if not (type(v) == "number" and v < 0.05 and st.frame - (h.start or h.from) > 30) then
            h.from, h.until_f = st.frame, math.max(h.until_f, st.frame + 120)   -- open while he's in the doorway
            return
        end
        st.door_hold = nil
    end
    if (push.cool[key] or 0) > st.frame then return end
    local f = xf:call("get_Rotation") * Vector3f.new(0, 0, 1)
    local fh = math.max(1e-4, math.sqrt(f.x * f.x + f.z * f.z))
    if (f.x * tox + f.z * toz) / fh < 0.6 then return end   -- not facing it
    local speed = vel and (vel.x * tox + vel.z * toz) or 0
    local pushing = speed > 0.5
    if not pushing then
        local mf = comp(st.hunk, "via.motion.MotionFsm2")
        local node = mf and safe(function() return mf:call("getCurrentNodeName", 0) end) or ""
        pushing = type(node) == "string" and (node:find("WALK") ~= nil or node:find("JOG") ~= nil)
    end
    if not pushing or hunk_is_aiming() then return end
    if safe(function() return door:call("get_IsLocked") end) then push.cool[key] = st.frame + 120; return end
    push.fired = { frame = st.frame, speed = speed, plane = plane, lat = lat }
    local ok, r = pcall(door_open, door)
    if ok and r then
        -- player 2 just walking pushes it a bit slower than a run
        pcall(door.call, door, "setOpenSpeed", speed > 2.5 and 1.0 or 0.8)
        push.cool[key] = st.frame + 30
        return
    end
    -- already swinging open (player 1 went through): keep it open for him too
    local v = safe(function() return door:get_field("_PeekedWork"):call("GetValue", 0):get_field("Value") end)
    if type(v) == "number" and v > 0.2 then
        st.door_hold = { door = door:add_ref(), from = st.frame, start = st.frame, until_f = st.frame + 600 }
    end
    push.cool[key] = st.frame + 30
end

-- Player 2 pushes a door the way player 1 does (v313). Player 1's door is a "peek" door: walking
-- into it starts its peek routine (`setPeeked(true, side, PLAYER, false)`, _PeekedRno WAIT 1 ->
-- OPEN 2 -> CLOSE 3) and from then on how far it swings (`_PeekedWork[0].Value`, 0..1) follows
-- how close the player is to its plane (`calcPlDistZ`, her local z through `_Inv`), measured from
-- the player the door picks (`getNearestPlCharactor`); it stays open while its contact timer
-- (`_TimerContactPl`) is kept up and closes on its own once she's gone. HUNK isn't a player to
-- the door, so: when he walks or runs into it, the routine is started from his side, both calls
-- are answered with HUNK for that door (his distance only when he's nearer than Leon), and his
-- distance is a virtual one that keeps going down while he pushes (he can't walk into a shut
-- door) and follows him back when he steps away, so the door opens as far as he pushes it, rests
-- against him in the doorway and swings shut behind him. Doors that don't run the routine fall
-- back to door_lever_tick (opened with requestOpenByLever).
do
local DP = { nopeek = {}, cool = {} }
st.door_peek = DP   -- (dev bridge)
local dtd = sdk.find_type_definition("app.ropeway.gimmick.action.GimmickDoorBase")
local app, atd = sdk.get_native_singleton("via.Application"), sdk.find_type_definition("via.Application")
local function mine(ptr)
    return DP.vz ~= nil and DP.addr ~= nil and ptr ~= nil and (sdk.to_int64(ptr) & ADDR_MASK) == DP.addr
end
pcall(sdk.hook, dtd:get_method("calcPlDistZ"), function(args) thread.get_hook_storage().dz = args[2] end, function(r)
    if not mine(thread.get_hook_storage().dz) then return r end
    local z = DP.sign * DP.vz
    if math.abs(z) < math.abs(sdk.to_float(r)) then return sdk.float_to_ptr(z) end
    return r
end)
pcall(sdk.hook, dtd:get_method("getNearestPlCharactor"), function(args) thread.get_hook_storage().dn = args[2] end, function(r)
    if st.hunk == nil or DP.p1_nearer or not mine(thread.get_hook_storage().dn) then return r end
    return sdk.to_ptr(st.hunk)
end)
-- His arm on the door (v314). Player 1's door animations are motion-tree user variables on her
-- SurvivorUserVariablesUpdater, raised when her body touches the door: DoorWalkPass (layer 3
-- DOOR_PASS, hand pushes the door, mot 1401), DoorJogOpen (JOG_DOOR_OPEN, shoulder in at a run,
-- 1410), DoorLockedStop (LOCKED_DOOR_STOP, tries the locked handle, 1440). HUNK carries the
-- same updater and motion tree; raising one on his for a few frames plays it once (held up, it
-- replays every ~18-40 frames). Written right after the updater's own update / lateUpdate.
local AV = { set = nil, until_f = 0, addr = nil, last = {} }
st.door_anim = AV   -- (dev bridge)
local VARS = { walk = "set_DoorWalkPass", jog = "set_DoorJogOpen", locked = "set_DoorLockedStop" }
local function anim_apply(upd)
    for k, m in pairs(VARS) do pcall(upd.call, upd, m, AV.set == k and st.frame <= AV.until_f) end
    if st.frame > AV.until_f then AV.set = nil end
end
local utd = sdk.find_type_definition("app.ropeway.survivor.SurvivorUserVariablesUpdater")
for _, mn in ipairs({ "update", "lateUpdate" }) do
    pcall(sdk.hook, utd:get_method(mn), function(args) thread.get_hook_storage().uv = args[2] end, function(r)
        if AV.addr and (AV.set or AV.clear) then
            local t = thread.get_hook_storage().uv
            if t and (sdk.to_int64(t) & ADDR_MASK) == AV.addr then
                local upd = sdk.to_managed_object(t)
                if upd then pcall(anim_apply, upd); if AV.set == nil then AV.clear = nil end end
            end
        end
        return r
    end)
end
-- play one of them on HUNK (kind: walk / jog / locked); not again within `gap` frames
function st.door_anim_play(kind, gap)
    if st.p2_down then return end   -- (crawling: no arm on the door)
    if st.hunk == nil or (AV.last[kind] or -1000) + (gap or 40) > st.frame then return end
    local upd = comp(st.hunk, "app.ropeway.survivor.player.PlayerUserVariablesUpdater")
    if upd == nil then return end
    AV.addr = upd:get_address() & ADDR_MASK
    AV.set, AV.until_f, AV.clear = kind, st.frame + 2, true
    AV.last[kind] = st.frame
end
local function loc(d, p) return d:get_field("_Inv") * Vector4f.new(p.x, p.y, p.z, 1.0) end
local function peek_value(d)
    return safe(function() return d:get_field("_PeekedWork"):call("GetValue", 0):get_field("Value") end)
end
local function release() DP.vz, DP.addr, DP.door, DP.p1_nearer, DP.tries = nil, nil, nil, nil, nil end
st.door_peek_release = release
function st.door_push_tick()
    if st.door_push == false or st.hunk == nil or menu.open or st.door_wait or st.pick
        or st.p2_held_only or p1_go() == nil or st.in_cutscene() then
        release()
        return
    end
    local xf = st.hunk:call("get_Transform")
    local hp = xf:call("get_Position")
    if st.frame - door_cache_frame >= 60 then find_door() end
    -- the door he's at: the one he's pushing, else the nearest whose doorway he's in
    local d, v = nil, nil
    if DP.door then
        local ok, lv = pcall(loc, DP.door, hp)
        if ok then d, v = DP.door, lv else release() end
    end
    if d == nil then
        for _, c in ipairs(door_cache) do
            local cc = safe(function() return c:call("get_Center") end)
            if cc and math.abs(cc.y - hp.y) < 1.8 then
                local ok, lv = pcall(loc, c, hp)
                if ok and math.abs(lv.x) < 1.2 and math.abs(lv.z) < 0.75 and (v == nil or math.abs(lv.z) < math.abs(v.z)) then d, v = c, lv end
            end
        end
    end
    if d == nil then return end
    local key = d:get_address() & ADDR_MASK
    if DP.nopeek[key] or (st.door_hold and (st.door_hold.door:get_address() & ADDR_MASK) == key) then
        release()
        return st.door_lever_tick()
    end
    local f = xf:call("get_Rotation") * Vector3f.new(0, 0, 1)
    local fl = loc(d, Vector3f.new(hp.x + f.x, hp.y + f.y, hp.z + f.z))
    local sign = v.z >= 0 and 1 or -1
    local facing = (-sign * (fl.z - v.z)) > 0.6
    local mf = comp(st.hunk, "via.motion.MotionFsm2")
    local node = mf and safe(function() return mf:call("getCurrentNodeName", 0) end) or ""
    if type(node) ~= "string" then node = "" end
    local jog = node:find("JOG") ~= nil
    local moving = jog or node:find("WALK") ~= nil or (st.p2_down ~= nil and st.p2_down.crawl == true)
    local inzone = math.abs(v.x) < 1.2 and math.abs(v.z) < 0.75
    local pushing = inzone and facing and moving and not hunk_is_aiming()
    local rno = d:get_field("_PeekedRno")
    if pushing and DP.vz == nil then
        if (DP.cool[key] or 0) > st.frame then return end
        if safe(function() return d:call("get_IsLocked") end) then
            DP.cool[key] = st.frame + 90
            st.door_anim_play("locked", 90)   -- (tries the handle, as player 1)
            return
        end
        if d:get_field("_PeekedWork") == nil then DP.nopeek[key] = true; return end
        DP.door, DP.addr, DP.sign, DP.vz, DP.tries = d:add_ref(), key, sign, math.abs(v.z), 0
    end
    if DP.vz == nil then return end
    if pushing and (rno == 0 or rno == 1) then   -- (shut, or resting: he starts it swinging)
        local ids = {}
        pcall(function()
            local rooms = d:call("get_MyRooms")
            for j = 0, rooms:call("get_Length") - 1 do
                local b = rooms:call("GetValue", j)
                ids[#ids + 1] = type(b) == "number" and b or b:get_field("value__")
            end
        end)
        pcall(st.area_ready, ids)   -- (the room behind it drawn)
        pcall(d.call, d, "setPeeked", true, d:call("calcSide", hp), 1, false)
        DP.sign, DP.vz = sign, math.abs(v.z)
        st.door_anim_play(jog and "jog" or "walk", 40)   -- (his hand / shoulder on it)
    end
    -- Leon in the doorway nearer than him: the door is his
    local lp = safe(function() return p1_go():call("get_Transform"):call("get_Position") end)
    local lv = lp and safe(function() return loc(d, lp) end)
    DP.p1_nearer = lv ~= nil and math.abs(lv.x) < 1.2 and math.abs(lv.z) < DP.vz
    if pushing then
        local dt = math.min(0.05, sdk.call_native_func(app, atd, "get_ElapsedSecond") or 0.016)
        DP.vz = math.max(-0.3, math.min(DP.vz, math.abs(v.z)) - (jog and 1.6 or 0.9) * dt)   -- (his push: as if he walked on through it)
        -- a door that doesn't follow (no peek routine): opened the other way
        if rno ~= 3 then DP.tries = DP.tries + 1 end
        if DP.tries == 40 and d:get_field("_PeekedRno") ~= 2 and (peek_value(d) or 0) < 0.01 then
            DP.nopeek[key] = true
            release()
            return
        end
    elseif math.abs(v.z) > DP.vz then
        DP.vz = math.abs(v.z)   -- (stepped back: it follows him shut)
    end
    if inzone or math.abs(v.z) < 1.0 then pcall(d.set_field, d, "_TimerContactPl", 0.2) else release() end
end
end

local function door_through(door, forced)
    if safe(function() return door:call("get_IsLocked") end) then
        pcall(st.door_anim_play, "locked", 60)
        toast("That door is locked")
        return
    end
    -- a door that opens like player 1's; stepping through it is the fallback
    -- (the door he's pushing open: nothing more to do)
    if not forced and st.door_peek and st.door_peek.vz and st.door_peek.addr == (door:get_address() & ADDR_MASK) then return true end
    if not forced and st.door_real ~= false then
        local h = st.door_hold
        if h and h.door:get_address() == door:get_address() then h.from = st.frame; return true end
        local ok, r = pcall(door_open, door)
        if ok and r then pcall(st.door_anim_play, "walk", 40); return true end
    end
    local hp = st.hunk:call("get_Transform"):call("get_Position")
    local c = door:call("get_Center")
    local rot = door:call("get_GameObject"):call("get_Transform"):call("get_Rotation")
    -- the door's normal: the local axis whose two test points the door reports as
    -- different sides (falls back to its Z axis)
    local normal = nil
    for _, axis in ipairs({ Vector3f.new(0, 0, 1), Vector3f.new(1, 0, 0) }) do
        local n = rot * axis
        local h = math.sqrt(n.x * n.x + n.z * n.z)
        if h > 0.5 and normal == nil then
            n = Vector3f.new(n.x / h, 0, n.z / h)
            local s1 = safe(function() return door:call("calcSide", Vector3f.new(c.x + n.x * 0.9, c.y, c.z + n.z * 0.9)) end)
            local s2 = safe(function() return door:call("calcSide", Vector3f.new(c.x - n.x * 0.9, c.y, c.z - n.z * 0.9)) end)
            if s1 and s2 and s1 ~= s2 and s1 ~= 2 and s2 ~= 2 then normal = n end
        end
    end
    if normal == nil then
        local n = rot * Vector3f.new(0, 0, 1)
        local h = math.max(1e-4, math.sqrt(n.x * n.x + n.z * n.z))
        normal = Vector3f.new(n.x / h, 0, n.z / h)
    end
    -- The rooms on both sides are made drawn first (st.area_update keeps player 2's rooms
    -- drawn); the step happens once they are, or after a second at most.
    if not forced and st.split then
        local ids = {}
        pcall(function()
            local rooms = door:call("get_MyRooms")
            for j = 0, rooms:call("get_Length") - 1 do
                local b = rooms:call("GetValue", j)
                ids[#ids + 1] = type(b) == "number" and b or b:get_field("value__")
            end
        end)
        local ok, ready = pcall(st.area_ready, ids)
        if ok and ready == false then
            st.door_wait = { door = door, ids = ids, give_up = st.frame + 60 }
            return true
        end
    end
    -- go to the side HUNK is not on
    local sgn = ((hp.x - c.x) * normal.x + (hp.z - c.z) * normal.z) > 0 and -1 or 1
    for _, dist in ipairs({ 0.9, 1.3, 0.7 }) do
        local p = Vector3f.new(c.x + normal.x * dist * sgn, hp.y, c.z + normal.z * dist * sgn)
        local fy = floor_at(p.x, hp.y, p.z)
        if fy then
            local yaw = math.atan(normal.x * sgn, normal.z * sgn)
            local q = Quaternion.new(math.cos(yaw / 2), 0, math.sin(yaw / 2), 0)
            local dest = Vector3f.new(p.x, fy, p.z)
            warp_hunk(dest, q)
            st.rewarp = { pos = dest, rot = q, frame = st.frame + 2 }
            return true
        end
    end
    toast(st.p2_name() .. " can't get through there yet")
end

st.door_through = door_through   -- (dev bridge)
st.find_door = find_door
local function pickup_for_p1()
    if st.hunk == nil or st.pick ~= nil then return end
    -- (player 1 downed and he's at her side: he helps her up)
    if st.p1_down and st.p1_down.near and not st.p1_down.rising then st.p1_revive(); return end
    local im = sdk.get_managed_singleton("app.ropeway.gimmick.action.InteractManager")
    if im and safe(function() return im:call("get_IsTriggerLock") end) then return end
    -- (at a ladder's end: up or down it, as player 1)
    local lad, ct = st.find_ladder()
    if lad then st.ladder_climb(lad, ct); return end
    -- (where player 1 jumped / dropped down: the same way after her)
    local jk = st.find_jack()
    if jk then st.jack_use(jk); return end
    local si = find_pick_target()
    if si == nil then
        if st.p2inv and st.p2inv.box_action() then return end   -- (Rookie at an item box)
        local door = find_door()
        if door then door_through(door) else toast("Nothing for " .. st.p2_name() .. " to use here") end
        return
    end
    local t = pick_trigger(si)
    if t == nil then toast(st.p2_name() .. " can't pick that up"); return end
    -- (v444) only player 1 picks up what isn't ammo, healing or a weapon (keys, story items,
    -- files, gunpowder...): before, player 2's A opened player 1's pick-up screen for it from
    -- wherever player 2 was. st.p2_key_items = true (REFramework panel) allows it again.
    if st.p2_key_items ~= true and st.p2inv then
        local id = safe(function() return si:get_field("Type") end) or 0
        local wt = safe(function() return si:get_field("WeaponType") end) or -1
        if (id > 0 or wt > 0) and not st.p2inv.p2_item(id, wt) then toast("Only " .. st.p1_name() .. " can pick that up"); return end
    end
    if st.p2inv and not st.p2inv.before_pickup(si) then return end   -- (player 2's own inventory full)
    st.pick = { trig = t, frames = 0 }
    st.force_trig_addr = t:get_address() & ADDR_MASK
    st.force_si_addr = si:get_address() & ADDR_MASK   -- (NonRT-14)
end

local function update_pickup()
    local pk = st.pick
    if pk == nil then return end
    pk.frames = pk.frames + 1
    local p1 = p1_go()
    if p1 then pcall(function() pk.trig:call("activate", p1) end) end
    if pk.frames >= 6 or p1 == nil then
        st.pick = nil
        st.force_trig_addr = nil
    end
end

local function draw_toast()
    local t = st.toast
    if t == nil then return end
    if os.clock() > t.until_t then st.toast = nil; return end
    local sw, sh = 1920, 1080
    local ok, size = pcall(function() return imgui.get_display_size() end)
    if ok and size then sw, sh = size.x, size.y end
    local cx, ty = sw * 0.5, 80
    if p2c.active then   -- split screen: in player 2's half
        local r = (p2c.regions[st.split_layout] or p2c.regions[1]).p2
        cx, ty = (r[1] + r[3]) / 2 * sw, r[2] * sh + 80
    end
    draw.text(t.text, cx - 140, ty, 0xFFFFFFFF)
end

-- Pad 2 button combos ---------------------------------------------------------------
-- via.hid.GamePadButton bits (XInput): d-pad LUp 1 / LDown 2 / LLeft 4 / LRight 8,
-- face RUp 16 (Y) / RDown 32 (A) / RLeft 64 (X) / RRight 128 (B), LB 256, LT 512,
-- RB 1024, RT 2048, L3 4096, R3 8192, Back 16384, Start 32768.
local BTN = { DDOWN = 2, Y = 16, A = 32, X = 64, B = 128, L3 = 4096, R3 = 8192, BACK = 16384, START = 32768 }
local combo_prev = 0
-- Share / View (Back): a tap on HUNK's controller opens his inventory screen (st.ig); held
-- 1.5 s on Leon's controller it swaps who controls whom (a tap there is Leon's map).
-- Start+Back is ignored.
local share = {}   -- per controller uid: { t0, cancelled, done }
local function update_share(uid, b, is_p2)
    if uid == nil then return false end
    local s = share[uid]
    local back, start = (b & BTN.BACK) ~= 0, (b & BTN.START) ~= 0
    if back then
        if s == nil then s = { t0 = os.clock(), cancelled = start }; share[uid] = s end
        if start then s.cancelled = true end
        if not is_p2 and not s.cancelled and not s.done and os.clock() - s.t0 >= 1.5 then
            s.done = true
            return true
        end
    elseif s then
        share[uid] = nil
        if is_p2 and not s.cancelled and os.clock() - s.t0 < 0.6 then return true end
    end
    return false
end
local function update_swap(p2_only)
    if st.kbm_on then return end
    local p2b = st.p2_dev and (safe(function() return st.p2_dev:call("get_Button") end) or 0) or 0
    local p1b = st.p1_dev and (safe(function() return st.p1_dev:call("get_Button") end) or 0) or 0
    -- player 2's Back (Select) tap opens his inventory screen (st.ig); swapping is player 1's
    -- long Back hold (or the co-op menu)
    if update_share(st.p2_uid, p2b, true) and st.ig then
        if st.ig.eat_back then st.ig.eat_back = false
        elseif st.classic_controls() and st.infinite_ammo and not p2_only then
            -- (HUNK Classic with infinite ammo: no inventory; the tap swaps the
            -- controllers, as the mod first did)
            share = {}
            swap_controllers()
            combo_prev = 0xFFFFFFFF
            toast("Controllers swapped")
            return
        else pcall(st.ig.toggle) end
    end
    if p2b & BTN.BACK == 0 and st.ig and st.ig.eat_back and not share[st.p2_uid] then st.ig.eat_back = false end
    if p2_only then return end   -- (in the game's menus: no controller swap from player 1's Back)
    local hit = update_share(st.p1_uid, p1b, false)
    if hit then
        share = {}
        swap_controllers()
        combo_prev = 0xFFFFFFFF   -- don't fire pad-2 actions from buttons still held
        toast("Controllers swapped")
    end
end
local function pad2_buttons()
    local dev = st.p2_dev
    return dev and (safe(function() return dev:call("get_Button") end) or 0) or 0
end
st.P2CROSS_DIRS = { [1] = 0, [2] = 1, [4] = 2, [8] = 3 }   -- d-pad bit -> EquipmentDefine.Shortcut
local function update_combos()
    local b = pad2_buttons()
    if menu.open or menu.just_closed or menu.p2_lock then   -- buttons belong to a menu; nothing fires on close
        combo_prev = b | ((menu.just_closed or menu.p2_lock) and 0xFFFFFFFF or 0)
        menu.just_closed = nil
        st.lr_t0 = nil
        return
    end
    if st.p2_down then   -- downed: only his inventory (a heal gets him up) until player 1 helps him up
        pcall(update_swap, true)   -- (his Back tap)
        if not st.cooldowns_on() and (b & BTN.Y) ~= 0 and (combo_prev & BTN.Y) == 0 and st.ig and not st.ig.open then pcall(st.ig.toggle) end
        combo_prev = b
        st.lr_t0 = nil
        return
    end
    if st.ai_partner() then   -- AI partner: the second pad (if any) is just another pad for player 1
        combo_prev = b
        st.lr_t0 = nil
        return
    end
    local function pressed(mask) return (b & mask) == mask and (combo_prev & mask) ~= mask end
    -- the game's menus up (paused): none of pad 2's actions (heal / resupply / pick up / reload /
    -- teleport / weapon cross); only his Back tap, which opens his inventory screen when player 1
    -- is in her inventory / map / files (st.p2_inv_free)
    if p2c.menu_open() then
        combo_prev = b
        st.lr_t0 = nil
        pcall(update_swap, true)
        return
    end
    -- L3 + R3: a quick press teleports HUNK; holding it opens the co-op menu instead
    local lr = (b & (BTN.L3 | BTN.R3)) == (BTN.L3 | BTN.R3)
    if lr and st.lr_t0 == nil and (combo_prev & (BTN.L3 | BTN.R3)) ~= (BTN.L3 | BTN.R3) then st.lr_t0 = os.clock() end
    if not lr and st.lr_t0 then
        if os.clock() - st.lr_t0 < 0.5 then
            local ok, done = pcall(teleport_to_p1)
            if ok and done then say(st.p2_name() .. " teleported to " .. st.p1_name()) end
        end
        st.lr_t0 = nil
    end
    if pressed(BTN.START | BTN.BACK) then
        if st.spawn_blocked() then
            toast("Close the menu first to deploy or extract " .. st.p2_name())   -- (v411)
        elseif st.hunk then st.ai_no_spawn = true; pcall(despawn) elseif not st.pending then st.ai_no_spawn = nil; pcall(spawn) end
    end
    -- (d-pad: the game's own weapon shortcuts, like player 1: a gun on each direction, LB +
    -- d-pad for the knife / grenades.) A press pops up player 2's shortcut cross (st.p2cross)
    -- (HUNK Classic: no cross, the guns on up / left / right and d-pad down swapping the
    -- knife and grenade, as the mod first played)
    if st.classic_controls() then
        if st.hunk and pressed(BTN.DDOWN) and not st.tank.dpad_block then pcall(toggle_sub_weapon) end
    elseif st.hunk and not st.tank.dpad_block then
        for bit, sc in pairs(st.P2CROSS_DIRS) do
            if pressed(bit) then st.p2cross = { t = os.clock(), sub = (b & 256) ~= 0, dir = sc } end
        end
    end
    if pressed(BTN.A) then pcall(pickup_for_p1) end
    if st.cooldowns_on() then
        -- with the abilities: Y heal Leon, X resupply Leon, B reload
        if pressed(BTN.Y) then pcall(heal_p1) end
        if pressed(BTN.X) then pcall(resupply_p1) end
        if pressed(BTN.B) then pcall(reload_hunk) end
    else
        -- without them (split screen, not Rookie): as player 1's pad, X reload and Y his
        -- inventory screen (Back still opens it too)
        if pressed(BTN.X) then pcall(reload_hunk) end
        if pressed(BTN.Y) and st.ig and not st.ig.open then pcall(st.ig.toggle) end
    end
    combo_prev = b
    pcall(update_swap)
end

-- Experimental: split screen ------------------------------------------------------------
-- Player 1's half is Main Camera's view; player 2's half is a second live render view from
-- player 2's own camera (see "dual view" below). Both are drawn every frame and the game's
-- logic only ever sees Main Camera.
local SPLIT_REGIONS = {
    { p1 = { 0, 0, 0.5, 1 }, p2 = { 0.5, 0, 1, 1 } },   -- side by side
    { p1 = { 0, 0, 1, 0.5 }, p2 = { 0, 0.5, 1, 1 } },   -- top / bottom
}
p2c.regions = SPLIT_REGIONS   -- for the HUD code above
local split = { ro = nil, xf = nil, region = "unknown" }   -- unknown: reset on first frame

local function main_camera_parts()
    if split.ro and safe(function() return split.ro:call("get_GameObject"):call("get_Valid") end) then return true end
    local sm = sdk.get_native_singleton("via.SceneManager")
    local mv = sm and sdk.call_native_func(sm, sdk.find_type_definition("via.SceneManager"), "get_MainView")
    local cam = mv and safe(function() return mv:call("get_PrimaryCamera") end)
    local go = cam and safe(function() return cam:call("get_GameObject") end)
    if go == nil or (st.dual and st.dual.go and go:get_address() == st.dual.go:get_address()) then return false end
    split.ro = comp(go, "via.render.RenderOutput")
    split.xf = safe(function() return go:call("get_Transform") end)
    if split.ro then split.ro = split.ro:add_ref() end
    if split.xf then split.xf = split.xf:add_ref() end
    return split.ro ~= nil and split.xf ~= nil
end

local function set_region(r, key)
    if split.region == key or split.ro == nil then return end
    pcall(function()
        local reg = split.ro:call("get_Region")
        reg:set_field("l", r[1]); reg:set_field("t", r[2]); reg:set_field("r", r[3]); reg:set_field("b", r[4])
        split.ro:call("set_Region", reg)
        split.region = key
    end)
end

-- Player 2's camera uses the game's own player-camera settings, the ones Leon's camera uses
-- (app.ropeway.camera.PlayerCameraParam): normally a point 0.40 m right / 1.52 m above the
-- character's root, 1.7 m back, FOV 68; while aiming a point 0.49 m right / 0.43 m above the
-- spine_1 joint, 1.05 m back, FOV 55. p2c.zoom blends the two (0 normal, 1 aiming).
-- Defaults tuned in play: field of view 6 % wider and distance 90 % of the game's values
-- (the player 2 menu's FOV / distance settings are percentages of these).
local P2CAM = { normal = { side = 0.40, up = 1.52, dist = 1.7 * 0.9, fov = 68 * 1.06 }, hold = { side = 0.49, up = 0.43, dist = 1.05 * 0.9, fov = 55 * 1.06 } }
p2c.P2CAM = P2CAM
local function p2_pose()
    if p2c.piv == nil then return end
    local cp, sp = math.cos(p2c.pitch), math.sin(p2c.pitch)
    local fx, fy, fz = -cp * math.sin(p2c.yaw), sp, -cp * math.cos(p2c.yaw)
    local flx, flz = -math.sin(p2c.yaw), -math.cos(p2c.yaw)
    local rx, rz = -flz, flx
    local z = p2c.zoom or 0
    local N, H = P2CAM.normal, P2CAM.hold
    local dist = (N.dist + (H.dist - N.dist) * z) * (st.p2_dist_pct or 100) / 100
    local side = N.side + (H.side - N.side) * z + (st.p2_side or 0) / 100   -- p2_side: cm, + is right
    -- the aiming base is HUNK's spine_1 joint (as an offset from his root, so it moves with
    -- the same smoothing as the rest of the camera)
    local sy = (p2c.spine_off and p2c.spine_off[2] or 1.0) + H.up
    local up = N.up + (sy - N.up) * z
    local ox = p2c.spine_off and p2c.spine_off[1] * z or 0
    local oz = p2c.spine_off and p2c.spine_off[3] * z or 0
    local pivot = Vector3f.new(p2c.piv[1] + ox + rx * side, p2c.piv[2] + up, p2c.piv[3] + oz + rz * side)
    local want_pos = Vector3f.new(pivot.x - fx * dist, pivot.y - fy * dist, pivot.z - fz * dist)
    -- keep the camera out of walls
    local ok, hit = pcall(cast_ray, pivot, want_pos)
    if ok and hit then
        local dx, dy, dz = pivot.x - hit.x, pivot.y - hit.y, pivot.z - hit.z
        local l = math.sqrt(dx * dx + dy * dy + dz * dz)
        if l > 0.001 then want_pos = Vector3f.new(hit.x + dx / l * 0.25, hit.y + dy / l * 0.25, hit.z + dz / l * 0.25) end
    end
    p2c.pos = want_pos
    p2c.fwd = { fx, fy, fz }
    local qy = Quaternion.new(math.cos(p2c.yaw / 2), 0, math.sin(p2c.yaw / 2), 0)
    local qp = Quaternion.new(math.cos(p2c.pitch / 2), math.sin(p2c.pitch / 2), 0, 0)
    p2c.rot = qy * qp
end

-- a game menu is up (pause, inventory, map, files, item box, save...) or the game is paused
-- Player 1 is in the inventory / map / files in split screen, fitted into her half (the game
-- paused, player 2's half his own view): player 2 can use his own inventory screen meanwhile
-- (st.ig: move, use, combine, give...). Not under the pause menu (it covers both halves) or the
-- item box. st.p2_inv_in_menus = false: off.
function st.p2_inv_free()
    local D = st.dual
    return st.p2_inv_in_menus ~= false and st.split and p2c.active and D ~= nil and D.on == true
        and D.inv_up == true and not D.box_busy and st.split_inv_fit ~= false
end
-- (v411) a game or mod screen is up where player 2 must not be added or removed (Start + Back,
-- the co-op menu's spawn / remove): p2c.menu_open (inventory, map, files, pause), the
-- typewriter's save and load screens, the item box, dialogs, options (none of which set
-- IsGuiOpen: measured, the typewriter only sets isBusySave), the GUI switched off (cutscenes,
-- the save screen), the game not in play, a load under way, or the mod's own inventory / box
-- screens. Queries only.
-- coop_menu = true: asked from the co-op menu, which pauses time itself, so the game's pause
-- flags are left out there (the game's own menus still count).
function st.spawn_blocked(coop_menu)
    if st.unloading or st.pending then return true end
    if (st.ig and st.ig.open) or (st.ig1 and st.ig1.open) then return true end
    local gm = sdk.get_managed_singleton("app.ropeway.gui.GUIMaster")
    if coop_menu then
        if gm and safe(function() return gm:call("get_IsGuiOpen") end) == true then return true end
    elseif p2c.menu_open() then return true end
    if gm then
        for _, g in ipairs({ "isBusySave", "isBusyLoad", "isBusyItemBox", "isBusyGeneralDialog", "isBusyGeneralDialogEx",
            "isBusyFile", "isBusyOption", "isBusyCostume", "get_IsOpenPause" }) do
            if safe(function() return gm:call(g) end) == true then return true end
        end
        if safe(function() return gm:call("get_EnableGui") end) == false then return true end
    end
    if coop_menu then return false end
    local mf = sdk.get_managed_singleton("app.ropeway.gamemastering.MainFlowManager")
    if mf and safe(function() return mf:call("get_IsInGameNotPause") end) == false then return true end
    return false
end
function p2c.menu_open()
    local gm = sdk.get_managed_singleton("app.ropeway.gui.GUIMaster")
    if gm and safe(function() return gm:call("get_IsGuiOpen") end) == true then return true end
    local mf = sdk.get_managed_singleton("app.ropeway.gamemastering.MainFlowManager")
    return mf ~= nil and safe(function() return mf:call("get_IsInPause") end) == true
end

-- where player 2's camera is this frame (yaw/pitch from P2's right stick)
-- Cutscenes: event cameras (CameraSystem.IsEvent) and pre-rendered movies
-- (MovieManager.IsPlayingMovie). Checked once per frame.
-- Player 1's room going dark in split screen. The game lights one room set (light
-- GameObjects' Draw flags), meant to be player 1's. It works it out from the view's primary
-- camera, and player 2's camera sometimes wins that pick (D.update then rebuilds it);
-- seen after player 1 walked from a hallway into an office: player 1's half dark, its lamps flat
-- white, until player 2's view was rebuilt. Now, after player 1 changes room or area (EnemyManager
-- LastPlayerStaySceneID / LocationID) or player 2's camera wins the primary pick, the lights of
-- player 1's room are checked a moment later; only if none of them is drawn:
-- player 2's camera is rebuilt in place (D.rebuild: no change to player 1's half or the layout;
-- the new camera goes to the end of the scene's camera list, so Main Camera wins), up to 3 tries
-- 45 frames apart. (A full restart as the last step once left player 2's half black, and is a
-- full-screen flash, so it's no longer done automatically.)
-- "Refresh split screen" in the menus rebuilds player 2's view the same way.
function st.refresh_split()
    if st.dual and st.dual.on then pcall(st.dual.rebuild) end
end
do
    local ROOMS = nil
    local function room_name(id)
        if ROOMS == nil then
            ROOMS = {}
            local t = sdk.find_type_definition("app.ropeway.gamemastering.Map.ID")
            for _, f in ipairs(t and t:get_fields() or {}) do
                if f:is_static() then
                    local ok, v = pcall(f.get_data, f, nil)
                    if ok and type(v) == "number" then ROOMS[v] = f:get_name() end
                end
            end
        end
        return ROOMS[id]
    end
    local LIGHTS = { "via.render.SpotLight", "via.render.PointLight", "via.render.IESLight" }
    -- a room's enabled lights: how many, how many drawn. Each room's light components are
    -- collected once (scene-wide search) and kept for 20 s.
    local caches = {}
    function st.room_lights(name)
        local cache = caches[name]
        if cache == nil or st.frame - cache.at > 1200 then
            cache = { at = st.frame, list = {} }
            caches[name] = cache
            local scene = sdk.call_native_func(sdk.get_native_singleton("via.SceneManager"), sdk.find_type_definition("via.SceneManager"), "get_CurrentScene")
            for _, tn in ipairs(LIGHTS) do
                local arr = scene:call("findComponents(System.Type)", sdk.typeof(tn))
                for i = 0, arr:call("get_Length") - 1 do
                    pcall(function()
                        local c = arr:call("GetValue", i)
                        local go = c:call("get_GameObject")
                        local f, inroom = go:call("get_Folder"), false
                        while f and not inroom do inroom = f:call("get_Name") == name; f = f:call("get_Parent") end
                        if inroom then cache.list[#cache.list + 1] = { c = c:add_ref(), go = go:add_ref() } end
                    end)
                end
            end
        end
        local total, drawn = 0, 0
        for _, e in ipairs(cache.list) do
            pcall(function()
                if e.c:call("get_Enabled") then
                    total = total + 1
                    if e.go:call("get_Draw") then drawn = drawn + 1 end
                end
            end)
        end
        return total, drawn
    end
    -- the rooms the two players are in (player 1: EnemyManager; player 2: his StayAreaController)
    function st.player_rooms()
        local r = {}
        local em = sdk.get_managed_singleton("app.ropeway.EnemyManager")
        local n1 = em and room_name(em:get_field("<LastPlayerStaySceneID>k__BackingField"))
        if n1 then r[#r + 1] = n1 end
        local sa = st.hunk and comp(st.hunk, "app.ropeway.StayAreaController")
        local n2 = sa and safe(function() return room_name(sa:get_field("<StaySceneMapID>k__BackingField")) end)
        if n2 and n2 ~= n1 then r[#r + 1] = n2 end
        return r
    end
    function st.p1_room_lights()
        local r = st.player_rooms()
        if r[1] == nil then return nil end
        local t, d = st.room_lights(r[1])
        return t, d, r[1]
    end
    st.light_log = {}
    local function note(t)
        st.light_log[#st.light_log + 1] = st.frame .. " " .. t
        if #st.light_log > 40 then table.remove(st.light_log, 1) end
        log.info("[reunited] lights: " .. t)
    end
    function st.split_watch()
        local D = st.dual
        if D then
            pcall(D.probe_tick)
            pcall(D.vo_tick)
            if D.relight_at and st.frame >= D.relight_at then D.relight_at = nil; pcall(D.relight) end
        end
        if not (D and D.on) then st.light_check = nil; return end
        if st.frame % 15 == 0 then
            local em = sdk.get_managed_singleton("app.ropeway.EnemyManager")
            local k1 = em and safe(function()
                return tostring(em:get_field("<LastPlayerStayLocationID>k__BackingField")) .. "/" .. tostring(em:get_field("<LastPlayerStaySceneID>k__BackingField"))
            end)
            local k2 = safe(function()
                local sa = st.hunk and comp(st.hunk, "app.ropeway.StayAreaController")
                return tostring(sa and sa:get_field("<StaySceneMapID>k__BackingField"))
            end)
            -- player 2 into another room: re-light once; player 1: only the dark check
            if k2 and st.area_key2 and k2 ~= st.area_key2 then st.light_check = { at = st.frame + 15, step = 1, why = "player 2 room " .. k2 } end
            if k1 and st.area_key1 and k1 ~= st.area_key1 then st.light_check = st.light_check or { at = st.frame + 20, step = 3, why = "player 1 room " .. k1 } end
            if k1 then st.area_key1 = k1 end
            if k2 then st.area_key2 = k2 end
        end
        if (D.retypes or 0) ~= (st.seen_retypes or 0) then
            st.seen_retypes = D.retypes
            st.light_check = st.light_check or { at = st.frame + 10, step = 1, why = "primary camera" }
        end
        local lc = st.light_check
        if lc == nil or st.frame < lc.at then return end
        -- After player 2 changes room the renderer is made to decide the lights again (D.relight).
        -- Then, if a player's room still has none of its lights drawn, player 2's camera is
        -- rebuilt again, up to twice.
        if lc.step <= 2 then
            pcall(D.relight)
            st.light_check = { at = st.frame + 45, step = 3, why = lc.why }
            return
        end
        local okr, rooms = pcall(st.player_rooms)
        local name, total, drawn, dark
        for i, rn in ipairs(okr and rooms or {}) do
            local ok, t, d = pcall(st.room_lights, rn)
            if ok and t and t > 0 and d == 0 and not dark then
                -- player 2's room only while the game draws that room at all (its folder's Draw)
                local live = i == 1 or safe(function()
                    local sc = sdk.call_native_func(sdk.get_native_singleton("via.SceneManager"), sdk.find_type_definition("via.SceneManager"), "get_CurrentScene")
                    return sc:call("findFolder", rn):call("get_Draw")
                end) == true
                if live then name, total, drawn, dark = rn, t, d, true end
            end
        end
        if not dark then
            if lc.step > 3 then note("lit again") end
            st.light_check = nil
            return
        end
        if lc.step <= 4 then
            note(string.format("%s dark (%d / %d lights drawn) after %s: rebuilding player 2's view (try %d)", tostring(name), drawn, total, lc.why, lc.step - 2))
            pcall(D.rebuild)
            st.light_check = { at = st.frame + 45, step = lc.step + 1, why = lc.why }
        else
            note(string.format("%s still dark (%d / %d), leaving it", tostring(name), drawn, total))
            st.light_check = nil
        end
    end
end
-- Player 2's rooms (v186). The game streams and draws rooms around player 1 only
-- (EnvironmentStandbyManager: player 1's room and the rooms visible from it Active = drawn,
-- its other neighbours Standby = loaded but not drawn, the rest unloaded). Player 2's room and
-- the rooms visible from it are kept Active as well, and his other neighbours Standby, so each
-- half draws its own surroundings and player 2 can go through doors on his own. Rooms player 1
-- is in or near are untouched: statuses are only ever raised. The manager re-applies every
-- map's status each frame through EnvironmentStandbyController.setTargetStatus; a hook raises
-- it there for player 2's rooms, and a room the game hasn't listed at all is requested once
-- (changeMapLoadStatusRequest, reason DirectRequest). When a requested room is no longer wanted
-- the game is asked to re-decide its rooms (requestToRecheckArea), which drops it again.
do
    local AK = { keep = nil, ours = {}, extra = {}, recheck_at = nil }
    st.area = AK
    local ACTIVE, STANDBY = 3, 2               -- EnvironmentStandbyController.Target
    local STEP = { [3] = 11, [2] = 8 }         -- .Step Active / Standby
    pcall(function()
        sdk.hook(sdk.find_type_definition("app.ropeway.EnvironmentStandbyController"):get_method("setTargetStatus"), function(args)
            local k = AK.keep
            if k == nil then return end
            local ok = pcall(function()
                local this = sdk.to_managed_object(args[2])
                local want = this and k[this:get_field("MapID")]
                if want and (sdk.to_int64(args[3]) & 0xFFFFFFFF) < want then
                    args[3] = sdk.to_ptr(want)
                    args[4] = sdk.to_ptr(9)    -- AreaLoadReason.DirectRequest
                end
            end)
            if not ok then AK.keep = nil end
        end, function(r) return r end)
        AK.hooked = true
    end)
    local function mgr() return sdk.get_managed_singleton("app.ropeway.EnvironmentStandbyManager") end
    -- a HashSet<Map.ID>'s members, raising each to `want` in `into`
    local function set_ids(set, into, want)
        if set == nil then return end
        local slots, n = set:get_field("mSlots"), set:get_field("mLastIndex") or 0
        for i = 0, n - 1 do
            local e = slots:call("GetValue", i)
            if e and e:get_field("hashCode") >= 0 then
                local v = e:get_field("value")
                if type(v) ~= "number" then v = v and v:get_field("value__") end
                if v and v ~= 0 and (into[v] or 0) < want then into[v] = want end
            end
        end
    end
    local function release(recheck)
        AK.keep = nil
        AK.extra = {}
        if next(AK.ours) then
            AK.ours = {}
            if recheck then AK.recheck_at = AK.recheck_at or st.frame + 1 end
        end
    end
    st.area_release = release
    -- the controller of a room, when it's in player 1's location
    local function ctl(m, id, loc)
        local c = m:call("getStandbyController", id)
        if c and c:get_field("MyLocation") == loc then return c end
    end
    local function request(m, id, want, loc)
        local c = ctl(m, id, loc)
        if c == nil then return true end   -- (nothing to do for it)
        local step, req = c:get_field("<CurrentStep>k__BackingField") or 0, c:get_field("RequestedTargetStep") or 0
        if step >= STEP[want] then return true end
        if req < STEP[want] then
            m:call("changeMapLoadStatusRequest", id, want - 1, 9)   -- Status Standby 1 / Active 2
            AK.ours[id] = true
        end
        return false
    end
    AK.request = request
    -- light probe sets the renderer draws right now (enabled, in drawn rooms)
    local AREA_PROBE_BUDGET = 34
    function st.area_probe_count()
        local scene = sdk.call_native_func(sdk.get_native_singleton("via.SceneManager"), sdk.find_type_definition("via.SceneManager"), "get_CurrentScene")
        local arr = scene and scene:call("findComponents(System.Type)", sdk.typeof("via.render.LightProbes"))
        local n = 0
        for i = 0, (arr and arr:call("get_Length") or 0) - 1 do
            pcall(function()
                local c = arr:call("GetValue", i)
                if c:call("get_Enabled") and c:call("get_GameObject"):call("get_Draw") then n = n + 1 end
            end)
        end
        return n
    end
    -- player 2's neighbouring rooms, nearest first: the ones the game lists as visible from
    -- his room, then by the nearest door between the two rooms, then the rest
    function st.area_neighbour_order(m, p2, c2)
        local nb = {}
        set_ids(c2:get_field("NeighboringMapList"), nb, 1)
        nb[p2] = nil
        local vis = {}
        set_ids(c2:get_field("VisibleNeighboringMapList"), vis, 1)
        local dist = {}
        local hp = st.hunk:call("get_Transform"):call("get_Position")
        local scene = sdk.call_native_func(sdk.get_native_singleton("via.SceneManager"), sdk.find_type_definition("via.SceneManager"), "get_CurrentScene")
        local doors = scene:call("findComponents(System.Type)", sdk.typeof("app.ropeway.gimmick.action.GimmickDoorBase"))
        for i = 0, (doors and doors:call("get_Length") or 0) - 1 do
            pcall(function()
                local d = doors:call("GetValue", i)
                local rooms = d:call("get_MyRooms")
                local has2, other = false, nil
                for j = 0, rooms:call("get_Length") - 1 do
                    local b = rooms:call("GetValue", j)
                    local v = type(b) == "number" and b or b:get_field("value__")
                    if v == p2 then has2 = true elseif nb[v] then other = v end
                end
                if has2 and other then
                    local c = d:call("get_Center")
                    local dd = (c - hp):length()
                    if dist[other] == nil or dd < dist[other] then dist[other] = dd end
                end
            end)
        end
        local list = {}
        for id in pairs(nb) do list[#list + 1] = id end
        table.sort(list, function(a, b)
            local ka = (vis[a] and 0 or 1000) + (dist[a] or 500)
            local kb = (vis[b] and 0 or 1000) + (dist[b] or 500)
            if ka ~= kb then return ka < kb end
            return a < b
        end)
        return list
    end
    function st.area_update()
        local m = mgr()
        if AK.recheck_at and st.frame >= AK.recheck_at then
            AK.recheck_at = nil
            AK.ours = {}
            if m then pcall(m.call, m, "requestToRecheckArea") end
        end
        if st.frame % 10 ~= 0 and not AK.now then return end
        AK.now = nil
        local em = sdk.get_managed_singleton("app.ropeway.EnemyManager")
        local sa = st.hunk and comp(st.hunk, "app.ropeway.StayAreaController")
        if not st.split or st.keep_p2_area == false or not AK.hooked or m == nil or em == nil or sa == nil then release(true); return end
        local phase = m:get_field("CurrentPhase")
        -- (Standby 0 / OnWork 1; the others release areas or whole locations)
        if phase ~= 0 and phase ~= 1 then release(false); return end
        local p1 = em:get_field("<LastPlayerStaySceneID>k__BackingField")
        local p2 = sa:get_field("<StaySceneMapID>k__BackingField")
        local c1 = p1 and p1 ~= 0 and m:call("getStandbyController", p1)
        local loc = c1 and c1:get_field("MyLocation")
        local c2 = loc and p2 and p2 ~= 0 and ctl(m, p2, loc)
        if c2 == nil then release(true); return end
        -- Player 2's own room is made Active when it isn't player 1's, and its neighbours, so
        -- what he sees through an open doorway is there too (left Standby they showed as grey
        -- nothing). Neighbours go Active one at a time, nearest door first, only while the
        -- scene stays inside the light probe budget: past roughly 35 light probe sets the
        -- renderer drops some, and the dropped areas fall back to the moon sky light (the
        -- washed-out blue press room). A neighbour that takes it over the budget is put back
        -- (the game re-decides its rooms, which brings the right probes back) and not tried
        -- again until player 2 changes room. The rest are only loaded (Standby), for doors.
        local keep = {}
        local apart = p2 ~= p1
        if not apart then
            pcall(function()
                local a = st.hunk:call("get_Transform"):call("get_Position")
                local b = p1_go():call("get_Transform"):call("get_Position")
                apart = (a - b):length() > 10
            end)
        end
        if AK.ctx_room ~= p2 then AK.ctx_room, AK.allowed, AK.blocked, AK.order_at = p2, {}, {}, nil end
        if apart then
            if p2 ~= p1 then keep[p2] = ACTIVE end
            set_ids(c2:get_field("NeighboringMapList"), keep, STANDBY)
            if st.frame >= (AK.order_at or 0) then
                AK.order_at = st.frame + 60
                pcall(function() AK.order = st.area_neighbour_order(m, p2, c2) end)
            end
            local probes = st.area_probe_count()
            AK.probes = probes
            -- over budget: drop the last neighbour let in
            if probes > AREA_PROBE_BUDGET and #AK.allowed > 0 and st.frame >= (AK.budget_at or 0) then
                local id = table.remove(AK.allowed)
                AK.blocked[id] = true
                AK.budget_at = st.frame + 45
                AK.recheck_at = AK.recheck_at or st.frame + 2
            elseif probes <= AREA_PROBE_BUDGET - 3 and st.frame >= (AK.budget_at or 0) then
                -- room left: let the next neighbour in
                for _, id in ipairs(AK.order or {}) do
                    local have = false
                    for _, a in ipairs(AK.allowed) do if a == id then have = true end end
                    if not have and not AK.blocked[id] and id ~= p1 then
                        local c = ctl(m, id, loc)
                        if c and (c:get_field("<CurrentStep>k__BackingField") or 0) < 11 then
                            AK.allowed[#AK.allowed + 1] = id
                            AK.budget_at = st.frame + 45
                            break
                        end
                    end
                end
            end
            for _, id in ipairs(AK.allowed) do keep[id] = ACTIVE end
        else
            AK.allowed = {}
        end
        for id, until_f in pairs(AK.extra) do
            if st.frame > until_f then AK.extra[id] = nil elseif (keep[id] or 0) < ACTIVE then keep[id] = ACTIVE end
        end
        local dropped = false
        for id in pairs(AK.ours) do if keep[id] == nil then dropped = true; AK.ours[id] = nil end end
        if dropped then AK.recheck_at = AK.recheck_at or st.frame + 1 end
        AK.keep = keep
        AK.p1, AK.p2, AK.loc = p1, p2, loc
        if m:call("get_PauseLoadStatus") ~= 0 then return end   -- (timeline / survivor control)
        for id, want in pairs(keep) do pcall(request, m, id, want, loc) end
    end
    -- rooms on both sides of a door player 2 is about to go through: Active now, for 3 s.
    -- True when they're all drawn already.
    function st.area_ready(ids)
        local m = mgr()
        if m == nil or AK.loc == nil or AK.keep == nil then return true end
        local ready = true
        for _, id in ipairs(ids) do
            AK.extra[id] = st.frame + 180
            AK.keep[id] = ACTIVE
            local ok, r = pcall(request, m, id, ACTIVE, AK.loc)
            if ok and r == false then ready = false end
        end
        return ready
    end
    -- a script reset drops the hook: let the game re-decide the rooms it was holding
    if re.on_script_reset then
        re.on_script_reset(function()
            AK.keep = nil
            if next(AK.ours) or AK.p2 then
                pcall(function() mgr():call("requestToRecheckArea") end)
            end
        end)
    end
end
function st.in_cutscene()
    if st.cut_frame == st.frame then return st.cut_val end
    local v = false
    pcall(function()
        local cs = sdk.get_managed_singleton("app.ropeway.camera.CameraSystem")
        if cs and cs:call("get_IsEvent") then v = true; return end
        -- (pre-rendered movies count too in split screen mode; normal co-op as before)
        local mm = st.split and sdk.get_managed_singleton("app.ropeway.gamemastering.MovieManager")
        if mm and mm:call("get_IsPlayingMovie") then v = true end
    end)
    st.cut_frame, st.cut_val = st.frame, v
    return v
end

-- Cutscenes: player 2 is hidden (body, weapons, flashlight: every GameObject under HUNK gets
-- DrawSelf off, and only the ones we turned off are turned back on) and gets no input, so they
-- can't wander or shoot unseen. "Player 2 In Cutscenes (Fun)" (Extras, p2_cutscene_fun) leaves
-- them visible and playable instead. Either way they rejoin player 1 afterwards (st.after_cut).
do
    local H = { on = false, hidden = {} }
    st.cut_hide = H
    local function parts(go, acc, depth)
        acc[#acc + 1] = go
        if depth >= 8 then return acc end
        local xf = safe(function() return go:call("get_Transform") end)
        local c = xf and safe(function() return xf:call("get_Child") end)
        local guard = 0
        while c ~= nil and guard < 300 do
            guard = guard + 1
            local cg = safe(function() return c:call("get_GameObject") end)
            if cg then parts(cg, acc, depth + 1) end
            c = safe(function() return c:call("get_Next") end)
        end
        return acc
    end
    local function hide()
        if st.hunk == nil then return end
        for _, g in ipairs(parts(st.hunk, {}, 0)) do
            if safe(function() return g:call("get_DrawSelf") end) == true then
                safe(function() g:call("set_DrawSelf", false) end)
                H.hidden[g:get_address()] = g
            end
        end
    end
    local function show()
        for _, g in pairs(H.hidden) do
            safe(function() if g:call("get_Valid") then g:call("set_DrawSelf", true) end end)
        end
        H.hidden = {}
    end
    function st.cut_hide_tick()
        local want = st.hunk ~= nil and not st.p2_cutscene_fun and st.in_cutscene()
        if want then
            -- every 15 frames: catch anything new under him (a weapon drawn on the way in)
            if not H.on or st.frame % 15 == 0 then hide() end
            H.on = true
        elseif H.on then
            H.on = false
            show()
        end
    end
    re.on_pre_application_entry("LateUpdateBehavior", function() pcall(st.cut_hide_tick) end)
    if re.on_script_reset then re.on_script_reset(function() pcall(show) end) end
end
local function update_p2cam(dt)
    local cs = sdk.get_managed_singleton("app.ropeway.camera.CameraSystem")
    -- pause, inventory, map, files, saving...: split screen stays up under the game's menu
    -- (st.split_menu_keep, default on). Taking player 2's view down and building it again around
    -- every menu is what crashed the game (GPU device removed, v205 / v222); off = the old way
    -- (whole screen to player 1's view while a menu is up).
    local menu = st.split and p2c.menu_open()
    local keep = menu and st.split_menu_keep ~= false and p2c.active
    -- (v427) and not in the first half second after a cutscene / movie (the game's cameras and
    -- player 1 settle, player 2 is brought over) before player 2's view is built again
    if st.in_cutscene() then p2c.cut_end = st.frame end
    local want = st.split and st.hunk ~= nil and p1_go() ~= nil and cs ~= nil and (not menu or keep)
        and not st.in_cutscene() and st.frame - (p2c.cut_end or -1000) > 30
    if not want then
        if menu and p2c.active then p2c.keep_yaw = true end   -- pick up where player 2 left off
        p2c.active, p2c.pos, p2c.piv = false, nil, nil
        if st.dual then pcall(st.dual.off) end
        return
    end
    main_camera_parts()
    if not p2c.active and not p2c.keep_yaw then   -- just switched on: start behind HUNK
        local f = st.hunk:call("get_Transform"):call("get_Rotation") * Vector3f.new(0, 0, 1)
        p2c.yaw, p2c.pitch = math.atan(-f.x, -f.z), -0.1
    end
    p2c.keep_yaw = nil
    p2c.active = true
    local dev = not st.p2_lock and not menu and st.p2_dev   -- (a local "menu" shadows the menu table here)
    local ax = dev and safe(function() return dev:call("get_AxisR") end)
    if ax then
        local x = st.invert_x and -ax.x or ax.x
        local y = st.invert_y and -ax.y or ax.y
        if math.abs(x) < 0.15 then x = 0 end
        if math.abs(y) < 0.15 then y = 0 end
        p2c.yaw = p2c.yaw - x * st.aim_speed * dt
        p2c.pitch = math.max(-1.0, math.min(0.9, p2c.pitch + y * st.aim_speed * 0.6 * dt))
    end
    -- zoom in over the shoulder while aiming
    local aiming = hunk_is_aiming() or hunk_sub_holding()
    p2c.zoom = p2c.zoom + ((aiming and 1 or 0) - p2c.zoom) * (1 - math.exp(-dt / 0.12))
    -- where HUNK's spine_1 joint is, relative to his root (the aiming camera's base)
    -- (smoothed in HUNK's own frame: the joint sways with every step, most of all strafing
    -- while aiming, and the over-the-shoulder camera followed the sway: HUNK twitched in his
    -- view. Turning stays exact: the smoothed offset is turned back with his current facing.)
    pcall(function()
        local xf = st.hunk:call("get_Transform")
        local j = xf:call("getJointByName", "spine_1") or xf:call("getJointByName", "Spine_1")
        local jp, rp = j:call("get_Position"), xf:call("get_Position")
        local q = xf:call("get_Rotation")
        local w = Vector3f.new(jp.x - rp.x, jp.y - rp.y, jp.z - rp.z)
        local l = q:conjugate() * w   -- (in his own frame)
        local a = 1 - math.exp(-dt / 0.25)
        local s = p2c.spine_local
        if s == nil then s = { l.x, l.y, l.z } else
            s = { s[1] + (l.x - s[1]) * a, s[2] + (l.y - s[2]) * a, s[3] + (l.z - s[3]) * a }
        end
        p2c.spine_local = s
        local back = q * Vector3f.new(s[1], s[2], s[3])
        p2c.spine_off = { back.x, back.y, back.z }
    end)
    -- Follows HUNK exactly on the ground plane (it used to trail him by dt * 14 of the gap each
    -- frame: the frame times vary by 10-80 % from one frame to the next, and the camera, a child
    -- of HUNK, then moved 0.5x / 1.8x / 1.1x his step on alternate frames: recorded while
    -- strafing with a gun up, he twitched by 2-14 mm a frame in his own view). Height keeps a
    -- little smoothing (stairs, steps). His root moves smoothly (1.07-1.14 m/s frame to frame).
    local hp = st.hunk:call("get_Transform"):call("get_Position")
    local ky = 1 - math.exp(-dt * 14)
    if p2c.piv == nil or (p2c.piv[1] - hp.x) ^ 2 + (p2c.piv[3] - hp.z) ^ 2 > 4 then
        p2c.piv = { hp.x, hp.y, hp.z }
    else
        p2c.piv = { hp.x, p2c.piv[2] + (hp.y - p2c.piv[2]) * ky, hp.z }
    end
    p2_pose()
    -- how far player 2's view is turned from Leon's (for the movement stick)
    local d = safe(function() return cs:call("get_CameraDirection") end)
    if d then
        local delta = p2c.yaw - math.atan(-d.x, -d.z)
        p2c.delta = math.atan(math.sin(delta), math.cos(delta))
    end
end

-- Grabs on player 2 (split screen, and since v388 one screen and the AI too): the grab's camera (CameraSystem.playActionCamera, a motion
-- camera bound to the grabbed player) would take over Main Camera, i.e. player 1's half. While
-- player 2 is the one held (and player 1 isn't), it isn't played and player 1's camera carries
-- on; its stop is skipped too unless Main Camera really is on an action camera.
do
    local CS = sdk.find_type_definition("app.ropeway.camera.CameraSystem")
    local function held(go)
        local c = go and comp(go, "app.ropeway.survivor.player.PlayerCondition")
        return c ~= nil and safe(function() return c:call("get_IsJack") or c:call("get_IsJackFromEnemy") or c:call("get_InConstraint") end) == true
    end
    local function for_p2(args, idx)
        local p1 = p1_go()
        if idx then   -- the overloads with a constraint target: the grabbed player
            local ok, obj = pcall(function()
                local t = sdk.to_managed_object(args[idx])
                return t and t:get_field("<ConstObject>k__BackingField")
            end)
            if ok and obj then
                if obj:get_address() == st.hunk:get_address() then return true end
                if p1 and obj:get_address() == p1:get_address() then return false end
            end
        end
        return held(st.hunk) and not held(p1)
    end
    for _, m in ipairs(CS and CS:get_methods() or {}) do
        local nm, np = m:get_name(), m:get_num_params()
        if nm == "playActionCamera" then
            local idx = (np == 11 and 8) or (np == 9 and 6) or nil   -- ConstTargetParam (args[2] is this)
            sdk.hook(m, function(args)
                -- (v387: and the AI partner on one screen - the grab zoomed the shared view in on it;
                -- v388: every way of play, player 2 on one screen too)
                if not st.hunk then return end
                if for_p2(args, idx) then
                    st.p2_grab_cam = st.frame
                    return sdk.PreHookResult.SKIP_ORIGINAL
                end
            end, function(r) return r end)
        elseif nm == "stopActionCamera" then
            sdk.hook(m, function(args)
                if st.p2_grab_cam == nil or not st.hunk then return end
                local cs = sdk.get_managed_singleton("app.ropeway.camera.CameraSystem")
                if cs and safe(function() return cs:call("get_BusyCameraType") end) ~= 5 then
                    if not held(st.hunk) then st.p2_grab_cam = nil end
                    return sdk.PreHookResult.SKIP_ORIGINAL
                end
            end, function(r) return r end)
        end
    end
end

-- player 2's view is placed as late as possible (after every behaviour has run), from the
-- freshest pose; menus, cutscenes and split off leave one full-screen view
re.on_application_entry("LateUpdateBehavior", function()
    if p2c.active and p2c.pos then
        -- (the ground-plane pivot taken from HUNK now: update_p2cam runs in REFramework's frame
        -- callback, a frame earlier, so the camera trailed him by one step, a step whose length
        -- changes with every frame time: his model twitched in his own view while moving)
        if p2c.piv and st.hunk then
            pcall(function()
                local hp = st.hunk:call("get_Transform"):call("get_Position")
                if (p2c.piv[1] - hp.x) ^ 2 + (p2c.piv[3] - hp.z) ^ 2 < 4 then p2c.piv[1], p2c.piv[3] = hp.x, hp.z end
            end)
        end
        pcall(p2_pose); pcall(st.dual.update)
    end
end)
re.on_pre_application_entry("BeginRendering", function()
    if split.ro == nil then main_camera_parts() end
    if st.dual and st.dual.on then pcall(st.dual.pre_render)
    elseif split.region ~= "full" then set_region({ 0, 0, 1, 1 }, "full") end
end)

-- leave the screen whole if the scripts are reloaded mid split
if re.on_script_reset then
    re.on_script_reset(function()
        pcall(function()
            if st.dual then pcall(st.dual.off) end
            split.region = "unknown"
            set_region({ 0, 0, 1, 1 }, "full")
        end)
    end)
end

-- Player 1 firing (for "Fire with me"): every shell player 1's gun creates.
-- (Where player 2's shots go is set in redirect_shot_matrix above.)
do
    local td = sdk.find_type_definition("app.ropeway.weapon.generator.ShellGeneratorBase")
    for _, m in ipairs(td and td:get_methods() or {}) do
        if m:get_name() == "generateShell" then
            sdk.hook(m, function(args)
                if st.hunk == nil then return end
                local own = st.owners[sdk.to_int64(args[2])]
                if own == OWN_HUNKW then st.p2_shot_frame = st.frame end   -- enemies can hear player 2's shots
                if not ai.active then return end
                if own == OWN_P1W then ai.p1_shot_frame = st.frame end
            end, function(r) return r end)
        end
    end
end

-- Split screen, dual view: a second live render view of the same world in the same frame.
-- The engine draws one Scene layer per render output ID. Main Camera's RenderOutput is
-- narrowed to output P1_OUT (player 1's half) and player 2's camera gets its own RenderOutput on
-- output P2_OUT (player 2's half); the renderer then builds a second Scene layer (ViewID 1) for it.
-- Game logic still only sees Main Camera. A camera made at runtime as a scene root never gets
-- its world matrix updated, so player 2's camera is parented under HUNK and posed locally.
-- Output numbers: the game's own HUD (crosshair, ammo, subtitles, menus) is drawn on render
-- output 2 (via.gui.GUI RenderOutputID = 2), so player 1's half is output 2 and player 2's
-- half output 1. (Normally Main Camera draws all outputs, 31.)
st.dual = { on = false, P1_OUT = 2, P2_OUT = 1 }
;(function()
    local D = st.dual
    local function valid(o) return o ~= nil and safe(function() return o:call("get_Valid") end) == true end
    local function out_rect(ro, r)
        local reg = ro:call("get_Region")
        reg:set_field("l", r[1]); reg:set_field("t", r[2]); reg:set_field("r", r[3]); reg:set_field("b", r[4])
        ro:call("set_Region", reg)
    end
    -- Player 2's view gets Main Camera's post effects (tone mapping / exposure, bloom, fog,
    -- SSAO, SSR...): the same components with their settings copied, refreshed every few
    -- frames because the game changes them per area. Object-valued settings (textures such as
    -- the exposure metering target) are not shared; each view keeps its own.
    local POST_SKIP = { ["via.Transform"] = true, ["via.Camera"] = true, ["via.render.RenderOutput"] = true, ["via.render.CapturePlane"] = true,
        ["via.render.CaptureToTexture"] = true, ["via.render.ExperimentalRayTrace"] = true }
    local pairs_cache = {}
    local function prop_pairs(td)
        local key = td:get_full_name()
        if pairs_cache[key] then return pairs_cache[key] end
        local list = {}
        for _, m in ipairs(td:get_methods()) do
            local nm = m:get_name()
            if m:get_num_params() == 0 then
                local setn = nm:find("^get_") and ("set_" .. nm:sub(5)) or (nm:find("^get%u") and ("set" .. nm:sub(4))) or nil
                if setn and td:get_method(setn) then list[#list + 1] = { nm, setn } end
            end
        end
        pairs_cache[key] = list
        return list
    end
    function D.sync_post()
        local mgo = split.ro and split.ro:call("get_GameObject")
        if not (mgo and D.go) then return end
        for _, c in ipairs(mgo:call("get_Components"):get_elements()) do
            local td = c:get_type_definition()
            local tn = td:get_full_name()
            -- (v442, st.split_sss_fix, on by default since v443) no SubsurfaceSettings on player 2's camera: its
            -- Profile (an object: never copied) stays nil there, and with it the renderer drew
            -- materials with an SSS_ProfileNumber flat white in BOTH halves (Daniel's wrist props,
            -- profile 7; never in full screen). Left out, they draw right (A/B on / off / on).
            -- Giving it Main Camera's Profile object (set_Profile) closed the game at once.
            local skip = st.split_sss_fix ~= false and tn == "via.render.SubsurfaceSettings"
            if tn:find("^via%.render%.") and not POST_SKIP[tn] and not skip then
                local d = D.post[tn]
                if d == nil then
                    d = D.go:call("createComponent(System.Type)", sdk.typeof(tn))
                    if d then d = d:add_ref(); D.post[tn] = d end
                end
                if d then
                    for _, pr in ipairs(prop_pairs(td)) do
                        local ok, v = pcall(c.call, c, pr[1])
                        if ok and v ~= nil and not (type(v) == "userdata" and sdk.is_managed_object(v)) then pcall(d.call, d, pr[2], v) end
                    end
                end
            end
        end
    end
    -- Player 2's camera light. Main Camera carries two soft lights for the character on screen
    -- (children SweetLight and EnvironmentSweetLight: a SpotLight and a ProjectionSpotLight each,
    -- one of them on, set by SweetLightController / EnvironmentSweetLightController; the
    -- environment one follows exposure). Lights draw in every render output their
    -- RenderOutputID mask allows (31 = all), so player 2's half showed player 1's camera light
    -- and HUNK had none. In split screen player 1's are masked to her output (D.P1_OUT) and
    -- copies under player 2's camera, settings mirrored, draw only in his (D.P2_OUT).
    -- Off with st.p2_sweet = false.
    D.sweet, D.sweet_src = nil, {}
    local LIGHT_TYPES = { "via.render.SpotLight", "via.render.ProjectionSpotLight" }
    local light_props_cache = {}
    local function light_props(td)
        local key = td:get_full_name()
        if light_props_cache[key] then return light_props_cache[key] end
        local list, seen, t = {}, {}, td
        while t and t:get_full_name() ~= "via.Component" do
            for _, m in ipairs(t:get_methods()) do
                local nm = m:get_name()
                if m:get_num_params() == 0 and nm:find("^get_") and not seen[nm] and nm ~= "get_RenderOutputID" then
                    local setn = "set_" .. nm:sub(5)
                    if td:get_method(setn) then seen[nm] = true; list[#list + 1] = { nm, setn } end
                end
            end
            t = t:get_parent_type()
        end
        light_props_cache[key] = list
        return list
    end
    local function main_cam_go() return split.ro and safe(function() return split.ro:call("get_GameObject") end) end
    -- S: the state table (D for split screen, SH for shared screen); parent: the transform the
    -- copies hang under (player 2's camera, or the stand-in camera spot behind HUNK)
    local sweet_off
    local function sweet_build(S, parent)
        sweet_off(S)
        if st.p2_sweet == false or parent == nil then return end
        local mgo = main_cam_go()
        if mgo == nil then return end
        local gtd = sdk.find_type_definition("via.GameObject")
        local folder = st.hunk:call("get_Folder")
        local list = {}
        local c = mgo:call("get_Transform"):call("get_Child")
        while c do
            local g = c:call("get_GameObject")
            local nm = g and g:call("get_Name") or ""
            if nm:find("SweetLight", 1, true) then
                local ng = gtd:get_method("create(System.String, via.Folder)"):call(nil, "rcu_P2" .. nm, folder)
                if ng then
                    ng = ng:add_ref()
                    local nxf = ng:call("get_Transform"):add_ref()
                    nxf:call("set_Parent", parent)
                    local e = { go = ng, xf = nxf, src_xf = c:add_ref(), pairs = {} }
                    for _, tn in ipairs(LIGHT_TYPES) do
                        local src = comp(g, tn)
                        local dst = src and ng:call("createComponent(System.Type)", sdk.typeof(tn))
                        if dst then
                            local td = sdk.find_type_definition(tn)
                            e.pairs[#e.pairs + 1] = { src = src:add_ref(), dst = dst:add_ref(), props = light_props(td) }
                        end
                    end
                    list[#list + 1] = e
                end
            end
            c = c:call("get_Next")
        end
        S.sweet, S.sweet_at = list, 0
    end
    -- split: player 1's lights masked to her output, the copies to player 2's
    local function sweet_sync(S, split_masks)
        if S.sweet == nil then return end
        local full = st.frame >= (S.sweet_at or 0)
        if full then S.sweet_at = st.frame + 10 end
        for _, e in ipairs(S.sweet) do
            pcall(function()
                e.xf:call("set_LocalPosition", e.src_xf:call("get_LocalPosition"))
                e.xf:call("set_LocalRotation", e.src_xf:call("get_LocalRotation"))
            end)
            for _, p in ipairs(e.pairs) do
                if full then
                    for _, pr in ipairs(p.props) do
                        local ok, v = pcall(p.src.call, p.src, pr[1])
                        if ok and v ~= nil and not (type(v) == "userdata" and sdk.is_managed_object(v) and not pr[1]:find("Texture", 1, true)) then
                            pcall(p.dst.call, p.dst, pr[2], v)
                        end
                    end
                else   -- what the controllers change from frame to frame
                    for _, nm in ipairs({ "Enabled", "Visible", "Intensity", "Color" }) do
                        local ok, v = pcall(p.src.call, p.src, "get_" .. nm)
                        if ok and v ~= nil then pcall(p.dst.call, p.dst, "set_" .. nm, v) end
                    end
                end
                if split_masks then
                    local key = p.src:get_address()
                    local id = safe(function() return p.src:call("get_RenderOutputID") end)
                    if id ~= nil and id ~= D.P1_OUT then
                        if S.sweet_src[key] == nil then S.sweet_src[key] = { l = p.src, id = id } end
                        pcall(p.src.call, p.src, "set_RenderOutputID", D.P1_OUT)
                    end
                    if safe(function() return p.dst:call("get_RenderOutputID") end) ~= D.P2_OUT then pcall(p.dst.call, p.dst, "set_RenderOutputID", D.P2_OUT) end
                end
            end
        end
    end
    sweet_off = function(S)
        for _, e in ipairs(S.sweet or {}) do
            if valid(e.go) then pcall(function() e.go:call("destroy", e.go) end) end
        end
        S.sweet = nil
        for k, v in pairs(S.sweet_src or {}) do pcall(v.l.call, v.l, "set_RenderOutputID", v.id); S.sweet_src[k] = nil end
    end
    function D.sweet_build() sweet_build(D, D.xf) end
    function D.sweet_sync() sweet_sync(D, true) end
    function D.sweet_off() sweet_off(D) end
    -- Shared screen had its own copy of the soft camera light behind player 2 (v198-v206); it
    -- didn't look right and was removed. This only clears away a rig left by an older version
    -- (rcu_P2LightRig under HUNK, with the light copies under it), once after loading.
    local SH = { cleaned = false }
    function st.shared_light_tick()
        if SH.cleaned or st.hunk == nil then return end
        SH.cleaned = true
        pcall(function()
            local xf = st.hunk:call("get_Transform")
            local c = xf:call("get_Child")
            while c do
                local nxt = c:call("get_Next")
                local g = c:call("get_GameObject")
                if g and g:call("get_Name") == "rcu_P2LightRig" then g:call("destroy", g) end
                c = nxt
            end
        end)
    end
    local function build()
        local gtd = sdk.find_type_definition("via.GameObject")
        local folder = st.hunk:call("get_Folder")
        local go = gtd:get_method("create(System.String, via.Folder)"):call(nil, "rcu_P2View", folder)
        if go == nil then return false end
        D.go = go:add_ref()
        D.cam = go:call("createComponent(System.Type)", sdk.typeof("via.Camera")):add_ref()
        D.ro = go:call("createComponent(System.Type)", sdk.typeof("via.render.RenderOutput")):add_ref()
        D.ro:call("set_RenderOutputID", D.P2_OUT)
        D.xf = go:call("get_Transform"):add_ref()
        D.xf:call("set_Parent", st.hunk:call("get_Transform"))
        D.parent, D.layout, D.post, D.post_at, D.post_once = st.hunk, nil, {}, 0, nil
        pcall(D.sweet_build)
        local mro = split.ro
        if mro then
            for _, p in ipairs({ "ImageQuality", "HorizontalScreenScale", "Interleave" }) do
                pcall(function() D.ro:call("set_" .. p, mro:call("get_" .. p)) end)
            end
        end
        return true
    end
    -- Player 1's half drops the game's colour grade (LDRPostProcess ColorCorrect, an olive /
    -- green LUT) so both halves look alike; player 2's camera never has it. The game's own
    -- controller turns it back on every frame, so it's switched off right before rendering.
    local function main_grade()
        local go = split.ro and safe(function() return split.ro:call("get_GameObject") end)
        local ldr = go and comp(go, "via.render.LDRPostProcess")
        return ldr and safe(function() return ldr:call("get_ColorCorrect") end)
    end
    -- Bloom (via.render.SoftBloom, threshold 0, widest blur) turns a single over-bright pixel
    -- into a big glowing ball. With two views a few such pixels show up (seen on a dead zombie
    -- lying in the rain, prologue alley) and flicker frame to frame: a blinding, glitching
    -- light. In split screen both halves drop that bloom unless st.split_bloom is on; full
    -- screen gets it back (D.off).
    local function main_bloom()
        local go = split.ro and safe(function() return split.ro:call("get_GameObject") end)
        return go and comp(go, "via.render.SoftBloom")
    end
    function D.pre_render()
        if not D.on then return end
        local cc = main_grade()
        if cc then pcall(cc.call, cc, "set_Enabled", false); D.graded_off = true end
        local want = st.split_bloom == true
        local mb = main_bloom()
        if mb and safe(function() return mb:call("get_Enabled") end) ~= want then pcall(mb.call, mb, "set_Enabled", want) end
        local pb = D.post and D.post["via.render.SoftBloom"]
        if pb and safe(function() return pb:call("get_Enabled") end) ~= want then pcall(pb.call, pb, "set_Enabled", want) end
        D.bloom_off = not want
    end
    -- What is driving Leon's camera right now? Besides the player camera, Main Camera is driven
    -- by grabs and other actions (ActionCameraController, or player-camera kind Holded), gimmick
    -- and event cameras and the blend back from them (InterpolationCameraController). None of
    -- that may reach player 2's view, so these keep their last good values while it lasts:
    -- * FOV scale and clip planes: read only from the plain player camera (kind Normal, Jog,
    --   Damage or Hold, no overwrite, not blending);
    -- * post effects (e.g. the grab's depth of field): also not while Leon aims; fixed cameras
    --   (classic camera areas) are fine.
    -- CameraSystem BusyCameraType: 0 player, 1 sight, 2 fixed, 3 gimmick fixed, 4 gimmick motion,
    -- 5 action, 6 event, 7 inventory, 8 interpolation, 9+ title / game over / result / figure.
    local LEON_KINDS = { [0] = true, [1] = true, [2] = true, [3] = true }   -- Normal Jog Damage Hold
    local POST_TYPES = { [0] = true, [1] = true, [2] = true, [3] = true }
    function D.leon_cam_plain(post)
        if D.plain_frame ~= st.frame then
            D.plain_frame = st.frame
            local fov_ok, post_ok = false, false
            pcall(function()
                local cs = sdk.get_managed_singleton("app.ropeway.camera.CameraSystem")
                if cs:call("get_IsEvent") then return end
                local ty = cs:call("get_BusyCameraType")
                if not POST_TYPES[ty] then return end
                if ty ~= 0 then post_ok = true; return end
                local pcc = D.pcc
                local bc = cs:call("get_BusyCameraController")
                if pcc == nil or bc == nil or bc:get_address() ~= pcc:get_address() then return end
                if pcc:call("get_OverwriteParamTrigger") then return end
                local t = pcc:call("get_InterpolateTimer")
                if t and t:get_field("_Completed") == false then return end
                local kind = pcc:call("get_NowKind")
                if not LEON_KINDS[kind] then return end
                fov_ok, post_ok = true, kind ~= 3
                D.plain_kindv = kind
            end)
            D.plain_fov, D.plain_post = fov_ok, post_ok
        end
        if post then return D.plain_post end
        return D.plain_fov
    end
    -- Main Camera FOV / the FOV setting of Leon's current player-camera state (its blend of
    -- the previous and next settings), read only while his camera is the plain player camera
    -- (see above); otherwise the last good reading is kept
    D.k = 1.0
    function D.fov_scale()
        if st.frame >= (D.pcc_at or 0) then
            D.pcc_at = st.frame + 120
            local sc = sdk.call_native_func(sdk.get_native_singleton("via.SceneManager"), sdk.find_type_definition("via.SceneManager"), "get_CurrentScene")
            local go = sc and safe(function() return sc:call("findGameObject(System.String)", "PlayerCameraController") end)
            D.pcc = go and comp(go, "app.ropeway.camera.PlayerCameraController")
        end
        local pcc = D.pcc
        local mc = split.ro and safe(function() return split.ro:call("get_GameObject"):call("getComponent(System.Type)", sdk.typeof("via.Camera")) end)
        -- k is a constant of the game's FOV option and the half's shape. Leon's camera reaches
        -- its FOV setting with its own easing (and aiming adds a little zoom of its own), so k
        -- is only read with Leon standing in the plain Normal camera, settled for a moment.
        if pcc and mc and D.leon_cam_plain() and D.plain_kindv == 0 then
            local ok, f = pcall(function()
                local prm = pcc:get_field("<Param>k__BackingField")
                local function fov(info) return info:get_field("_Param"):get_field("_Param"):get_field("_FieldOfView") end
                local a = fov(prm:get_field("<PrevInfo>k__BackingField"))
                local b = fov(prm:get_field("<NextInfo>k__BackingField"))
                local r = prm:get_field("<InfoRate>k__BackingField"):get_field("<Current>k__BackingField")
                if r < 0.999 then return nil end   -- still blending (Prev keeps the old state's setting)
                return b
            end)
            local mf = safe(function() return mc:call("get_FOV") end)
            if mf and D.last_mf and math.abs(mf - D.last_mf) < 0.02 then D.mf_still = (D.mf_still or 0) + 1 else D.mf_still = 0 end
            D.last_mf = mf
            if ok and f and f > 1 and mf and D.mf_still >= 15 then
                local k = mf / f
                if k > 0.3 and k < 3.0 then D.k = k end   -- side by side halves are narrow: ~0.69
            end
            D.near = safe(function() return mc:call("get_NearClipPlane") end) or D.near
            D.far = safe(function() return mc:call("get_FarClipPlane") end) or D.far
        else
            D.mf_still, D.last_mf = 0, nil
        end
        return D.k
    end
    -- While split is on, two things the engine shares between views are pinned:
    -- * GUIs drawn on every output (GUI_Reticle, output 31) or on output 1 (now player 2's
    --   half) are moved to player 1's output, so player 1's crosshair stays in player 1's half.
    --   GUIs that draw into a texture (in-world screens) are left alone.
    -- * Light occlusion (via.render.VolumeOccludee) keeps one result per light for both views,
    --   so a light hidden from one view could switch off in the other (lights flickered in
    --   player 1's half as player 2 looked around). Rule: if either player is looking at a
    --   light (its reach overlaps that player's view), it stays on; the engine's occlusion
    --   test is set aside for it. Lights neither player looks at are left to the engine.
    --   st.split_lightfix = false turns this part off.
    D.gui_saved, D.occ_saved, D.occ_list, D.occ_seen = {}, {}, {}, {}
    local function scene_comps(tn)
        local sc = sdk.call_native_func(sdk.get_native_singleton("via.SceneManager"), sdk.find_type_definition("via.SceneManager"), "get_CurrentScene")
        local arr = sc and safe(function() return sc:call("findComponents(System.Type)", sdk.typeof(tn)) end)
        return arr and arr:get_elements() or {}
    end
    local LIGHT_TYPES = { "via.render.SpotLight", "via.render.PointLight", "via.render.IESLight" }
    local function release(key)
        local o = D.occ_saved[key]
        if o then pcall(o.call, o, "set_Enabled", true) end
        D.occ_saved[key], D.occ_seen[key] = nil, nil
    end
    -- every few seconds: the GUIs to move and the lights to watch (position and reach)
    -- Game HUD shape: each half shows the game's 1920x1080 HUD layout squeezed into a region
    -- half as wide as a normal screen (side by side) or half as tall (top / bottom). Each HUD
    -- GUI's View is scaled (pivot: layout centre) back toward its real shape, and moved so it
    -- stays pinned to its corner / edge. st.split_hud (0-100) is how much of the squeeze is
    -- undone: 0 leaves it squeezed, 100 gives the true shape. Anchors (fraction of the layout)
    -- come from where each GUI's elements sit; GUIs placed over world objects (CombatIcon),
    -- full-screen overlays (DangerScreen, fades) and menus (split is off while they're up) are
    -- left alone. Optional third value: the most it may widen (long subtitle lines).
    D.HUD_ANCHOR = {
        GUI_Reticle = { 0.5, 0.5 }, GUI_Shortcut = { 0.5, 0.5 }, GUI_Tutorial = { 0.5, 0.5 },
        GUI_RemainingBullet = { 1, 1 }, GUI_DefenseUpIcon = { 1, 1 },
        GUI_VitalHud = { 0, 0.67 }, GUI_Purpose = { 0, 0.2 }, GUI_AutoSaveIcon = { 0, 0 },
        GUI_CountDown = { 0.5, 0 }, GUI_DefenseItemGuide = { 0.5, 0.79 }, GUI_GeneralGuide = { 0.5, 1 },
        GUI_SubTitle = { 0.5, 1, 1.25 },
    }
    D.hud_list = {}   -- [address] = { g, anchor, scale, position (as found) }
    function D.hud_k()
        local r = (SPLIT_REGIONS[st.split_layout] or SPLIT_REGIONS[1]).p1
        local sq = (r[3] - r[1]) / (r[4] - r[2])   -- < 1: squeezed sideways
        local q = (1 / sq) ^ (math.max(0, math.min(100, st.split_hud or 80)) / 100)
        -- the squeezed direction grows; the other shrinks a little so nothing gets too big
        if sq < 1 then return q ^ 0.75, q ^ -0.25 end
        return q ^ 0.25, q ^ -0.75
    end
    -- The game's HUD panels anchor themselves to the edges of the (scaled) layout, but not all
    -- the same way (the crosshair's panel drifts sideways), so each GUI is steered: its top
    -- panel is kept where scaling the whole GUI about its anchor point would put it, by moving
    -- the View. (A panel's GlobalPosition follows a View change a frame later, so a GUI is only
    -- corrected on the next pass after its scale changes.)
    local function hud_entry(g, a)
        local v = g:call("get_View")
        local s, p = v:call("get_Scale"), v:call("get_Position")
        local m = v:call("get_Child")
        local m0 = m and m:call("get_GlobalPosition")
        if m0 == nil then return nil end
        return { g = g:add_ref(), a = a, s = Vector3f.new(s.x, s.y, s.z or 1), p = Vector3f.new(p.x, p.y, p.z or 0),
            m0 = { m0.x - p.x, m0.y - p.y }, pos = { p.x, p.y } }
    end
    local function hud_fit(h, kx, ky)
        local v = h.g:call("get_View")
        local a = h.a
        if a[3] then kx = math.min(kx, a[3]) end
        if h.kx ~= kx or h.ky ~= ky then
            v:call("set_Scale", Vector3f.new(kx, ky, 1))
            h.kx, h.ky = kx, ky
            return
        end
        local m = v:call("get_Child")
        local gp = m and m:call("get_GlobalPosition")
        if gp == nil then return end
        local ax, ay = a[1] * 1920, a[2] * 1080
        local tx, ty = ax + (h.m0[1] - ax) * kx, ay + (h.m0[2] - ay) * ky
        local ex, ey = tx - gp.x, ty - gp.y
        if math.abs(ex) > 0.5 or math.abs(ey) > 0.5 then
            h.pos = { h.pos[1] + ex, h.pos[2] + ey }
            v:call("set_Position", Vector3f.new(h.pos[1], h.pos[2], 0))
        end
    end
    -- every few frames (cheap: a dozen GUIs); the game doesn't move these views itself
    function D.hud_apply()
        local kx, ky = D.hud_k()
        for k, h in pairs(D.hud_list) do
            local f = D.fs[k]
            if not (f and f.on) then pcall(hud_fit, h, kx, ky) end   -- (full-size split has it)
        end
        if D.ret_gui and (D.ret_h == nil or D.ret_h.g ~= D.ret_gui) and safe(function() return D.ret_gui:call("get_Ready") end) then
            D.ret_h = safe(function() return hud_entry(D.ret_gui, D.HUD_ANCHOR.GUI_Reticle) end)
            if D.ret_h then D.ret_h.g = D.ret_gui end
        end
        if D.ret_h and D.ret_gui then pcall(hud_fit, D.ret_h, kx, ky) end
    end
    -- the grab prompt ("LB to knife", GUI_DefenseItemGuide) goes to the half of whoever is held
    function D.guide_follow()
        if D.guide == nil or not valid(D.guide) or st.frame >= (D.guide_at or 0) then
            D.guide_at = st.frame + 300
            local sc = sdk.call_native_func(sdk.get_native_singleton("via.SceneManager"), sdk.find_type_definition("via.SceneManager"), "get_CurrentScene")
            local go = sc and safe(function() return sc:call("findGameObject(System.String)", "GUI_DefenseItemGuide") end)
            local g = go and comp(go, "via.gui.GUI")
            if g and (D.guide == nil or D.guide:get_address() ~= g:get_address()) then D.guide = g:add_ref() end
        end
        if D.guide == nil then return end
        local want = st.p2_held_only and D.P2_OUT or D.P1_OUT
        if safe(function() return D.guide:call("get_RenderOutputID") end) ~= want then pcall(D.guide.call, D.guide, "set_RenderOutputID", want) end
    end
    function D.hud_restore()
        for _, h in pairs(D.hud_list) do
            pcall(function() local v = h.g:call("get_View"); v:call("set_Scale", h.s); v:call("set_Position", h.p) end)
        end
        D.hud_list = {}
    end
    function D.pin_shared()
        local hud_live = {}
        for _, g in ipairs(scene_comps("via.gui.GUI")) do
            local key = g:get_address()
            hud_live[key] = true
            if D.hud_list[key] == nil then
                local nm = safe(function() return g:call("get_GameObject"):call("get_Name") end)
                local a = nm and D.HUD_ANCHOR[nm]
                local h = a and safe(function() return hud_entry(g, a) end)
                if h then D.hud_list[key] = h end
            end
            if D.gui_saved[key] == nil then
                local id = math.tointeger(safe(function() return g:call("get_RenderOutputID") end) or 0)
                local rt = safe(function() return g:call("get_RenderTarget") end)
                if id and rt == nil and (id & D.P2_OUT) ~= 0 and not D.menu_both[key] and not (D.ret_gui and key == D.ret_gui:get_address())
                    and not (D.guide and key == D.guide:get_address()) then
                    D.gui_saved[key] = { g = g:add_ref(), id = id }
                    pcall(g.call, g, "set_RenderOutputID", (id & ~D.P2_OUT) | D.P1_OUT)
                end
            end
        end
        for key in pairs(D.hud_list) do if not hud_live[key] then D.hud_list[key] = nil end end
        local list, live = {}, {}
        for _, o in ipairs(scene_comps("via.render.VolumeOccludee")) do
            local key = o:get_address()
            local go = safe(function() return o:call("get_GameObject") end)
            local p = go and safe(function() return go:call("get_Transform"):call("get_Position") end)
            if p then
                -- occludees sit on lights and also on local cubemaps (reflections) and light
                -- probes (bounce light); both kinds follow the same rule, the probe kind can be
                -- turned off on its own (st.split_probefix = false)
                local light, r
                for _, tn in ipairs(LIGHT_TYPES) do
                    light = comp(go, tn)
                    if light then r = safe(function() return light:call("get_ReferenceEffectiveRange") end); break end
                end
                local probe = not light and (comp(go, "via.render.LocalCubemap") or comp(go, "via.render.LightProbes"))
                if light or probe then
                    list[#list + 1] = { o = o:add_ref(), key = key, p = { p.x, p.y, p.z }, probe = probe and true or nil,
                        r = light and math.max(1, math.min(r or 10, 25)) or 12 }
                    live[key] = true
                end
            end
        end
        D.occ_list = list
        for key in pairs(D.occ_saved) do if not live[key] then D.occ_saved[key], D.occ_seen[key] = nil, nil end end
    end
    -- every few frames: lights either player is looking at stay on
    function D.pin_lights()
        if st.split_lightfix == false then
            for key in pairs(D.occ_saved) do release(key) end
            return
        end
        if st.split_vofix ~= false then return end   -- (D.vo_tick switches them all off instead)
        local cams = {}
        if split.xf then
            local cp = safe(function() return split.xf:call("get_Position") end)
            local cr = safe(function() return split.xf:call("get_Rotation") end)
            if cp and cr then
                local f = cr * Vector3f.new(0, 0, -1)
                cams[#cams + 1] = { cp.x, cp.y, cp.z, f.x, f.y, f.z }
            end
        end
        if p2c.pos and p2c.fwd then
            cams[#cams + 1] = { p2c.pos.x, p2c.pos.y, p2c.pos.z, p2c.fwd[1], p2c.fwd[2], p2c.fwd[3] }
        end
        local HALF = math.rad(62)   -- a little wider than either half's view
        local probes = st.split_probefix ~= false
        for _, e in ipairs(D.occ_list) do
            local seen = false
            for _, c in ipairs((probes or not e.probe) and cams or {}) do
                local dx, dy, dz = e.p[1] - c[1], e.p[2] - c[2], e.p[3] - c[3]
                local d = math.sqrt(dx * dx + dy * dy + dz * dz)
                if d <= e.r then seen = true; break end
                if d < 80 then
                    local cosang = (dx * c[4] + dy * c[5] + dz * c[6]) / d
                    if cosang >= math.cos(math.min(math.pi, HALF + math.asin(e.r / d))) then seen = true; break end
                end
            end
            local key = e.key
            if seen then
                D.occ_seen[key] = st.frame
                if D.occ_saved[key] == nil and safe(function() return e.o:call("get_Enabled") end) then
                    D.occ_saved[key] = e.o
                    pcall(e.o.call, e.o, "set_Enabled", false)
                    pcall(e.o.call, e.o, "setVisibilityOn", 0xFFFFFFFF)
                end
            elseif D.occ_saved[key] and (st.frame - (D.occ_seen[key] or 0) > 30 or (e.probe and not probes)) then
                release(key)   -- nobody has looked at it for half a second
            end
        end
    end
    -- Game menus in split screen (pause, inventory, map, files...): the menu's GUIs are drawn on
    -- both halves (output mask P1_OUT | P2_OUT), so the menu sits over both players' views.
    -- One full-screen copy isn't possible: an output's GUIs only draw inside its own region, and
    -- player 2's output is composited over Main Camera's (Main Camera full screen = player 2's
    -- half covers the right of the menu). Each half gets the menu laid out for that half.
    -- Menus load their GUIs as they open, so it rescans every 5 frames while one is up; only
    -- GUIs seen in the last scan are kept (a closed menu's GUI may be gone), put back on close.
    -- st.split_menu_mirror = false: menus stay in player 1's half only.
    D.menu_both = {}
    D.gui_names = {}
    -- Full-size split (st.split_menu_full, default on) for the menus named in D.FULL_SPLIT: the
    -- menu laid out as on a full screen, player 1's half showing its left half and player 2's
    -- half its right half. A GUI is drawn once per frame and that one drawing is used by every
    -- output it's on (one transform for both halves), so player 2's half gets a second GUI
    -- built from the same asset on P2_OUT, kept in step with the original every frame:
    -- original:copyProperties(copy) for each pair of elements, matched by name and position
    -- among same-named siblings (A:copyProperties(B) copies A INTO B; the other way round
    -- overwrites the game's menu). Original: View scale x2 about the left edge; copy: the same,
    -- one screen width to the left. A copy is built the first time its menu opens, hidden
    -- (not destroyed) when it closes, destroyed when split screen ends.
    D.FULL_SPLIT = {}
    for _, n in ipairs({ "GUI_Pause", "GUI_GeneralGuide", "GUI_GeneralDialog", "GUI_Load",
        "GUI_Record", "GUI_RecordDialog", "GUI_Costume", "GUI_Accessory", "GUI_Option", "GUI_OptionPreset",
        "GUI_OptionResult", "GUI_KeyBind", "GUI_ScreenSetting", "GUI_ControlType", "GUI_Brightness",
        "GUI_BrightnessMax", "GUI_BrightnessMin", "GUI_HDR_Brightness", "GUI_HDR_BrightnessMax",
        "GUI_ReNetDetail", "GUI_PrivacyPolicy",
        -- inventory (and item box: GuiSlot), map, files
        "GuiCaption", "GuiBack", "GuiFront", "GuiVital", "GuiTab", "GuiSlot", "GuiSearch",
        "GUI_ItemBox", "GUI_ItemLocker", "GUI_Map", "GUI_MapBG", "GUI_MapGrid", "GUI_FileList", "GUI_File",
        -- HUD pieces the game also shows on its menus (objective, shortcuts, tutorial pop-ups)
        "GUI_Purpose", "GUI_Shortcut", "GUI_Tutorial" }) do D.FULL_SPLIT[n] = true end
    D.FULL_SPLIT_PREFIX = { "gui_floormap_" }   -- (one floor-map GUI per area)
    -- The inventory / map / files screens, fitted into player 1's half instead (fs_tick):
    -- D.INV_FIT always; D.INV_WITH (the button guide and the HUD pieces the game shows on
    -- these screens, which also show on the pause menu) only while one of D.INV_FIT is up.
    -- GuiBack (the blur and dark panels behind them) is left at its own full-half size.
    D.INV_FIT = {}
    for _, n in ipairs({ "GuiCaption", "GuiFront", "GuiVital", "GuiTab", "GuiSlot", "GuiSearch",
        "GUI_Map", "GUI_MapBG", "GUI_MapGrid", "GUI_FileList", "GUI_File" }) do D.INV_FIT[n] = true end
    D.INV_WITH = { GUI_GeneralGuide = true, GUI_Purpose = true, GUI_Shortcut = true, GUI_Tutorial = true }
    D.INV_K = 0.5
    -- Portrait layout of those screens (st.split_inv_portrait, default on): each GUI on its own
    -- scale and place so the pieces stack down player 1's narrow half instead of the 16:9
    -- layout shrunk whole. { k, ax, ay, x, y }: View scale (2k, k), the layout point (ax, ay)
    -- (full-screen layout units, 1920 x 1080) lands at (x, y) in the half's pixels as seen on a
    -- 728 x 819 half (scaled to the real size). Measured from the game's own layouts (v298):
    -- tabs list_tab 1419,128; objective 0,214; weapon cross centre 960,386; item grid top left
    -- 1234,214; item text 1234,696; heartbeat 0,722; map area 804-1880 x 172-902 (centre
    -- 1342,558); file list 770,172; file text 1225,240; button guide right end 1824,1056.
    -- GuiFront (the dark backdrop) is stretched over the whole half. GUIs not listed are
    -- fitted whole as before.
    D.PORTRAIT = {
        GuiTab = { 0.8, 1419, 128, 364, 22 },
        GUI_Purpose = { 0.75, 0, 214, 16, 48 },
        GUI_Shortcut = { 0.8, 960, 386, 230, 300 },
        GuiSlot = { 0.8, 1234, 214, 366, 155 },
        GuiCaption = { 0.8, 1234, 696, 150, 470 },
        GuiVital = { 0.8, 0, 722, 8, 620 },
        GUI_Map = { 0.85, 1342, 558, 364, 400 },
        GUI_MapBG = { 0.85, 1342, 558, 364, 400 },
        GUI_MapGrid = { 0.85, 1342, 558, 364, 400 },
        GUI_FileList = { 0.68, 770, 172, 24, 130 },
        GUI_File = { 0.68, 1225, 240, 40, 455 },
        GUI_GeneralGuide = { 0.7, 1824, 1056, 712, 795 },
    }
    -- a file opened for reading (GUI_File main/c_file_detail shown: the page / picture centred
    -- on the full-screen layout at 960,540, picture 780x780, text mask 798x700): centred in the
    -- half at full size instead of the list-preview place
    D.PORTRAIT_READ = { 1.0, 960, 540, 364, 400 }
    -- GuiBack (blur + dark panels; a ViewType 1 view) only reached about 3/4 of the way down the
    -- half at scale 1: stretched down to the bottom
    D.BACK_SY = 1.34
    function D.portrait_of(nm)
        if nm:sub(1, 13) == "gui_floormap_" then return D.PORTRAIT.GUI_Map end
        return D.PORTRAIT[nm]
    end
    function D.inv_fit_name(nm) return D.INV_FIT[nm] == true or nm:sub(1, 13) == "gui_floormap_" end
    function D.is_full_split(nm)
        if D.FULL_SPLIT[nm] then return true end
        for _, pf in ipairs(D.FULL_SPLIT_PREFIX) do if nm:sub(1, #pf) == pf then return true end end
        return false
    end
    D.fs = {}   -- [original's address] = { g, go, name, s, p, rs, rp, on, copy, copy_go, pairs, miss }
    D.FS_W = 1920   -- the GUI layouts' width
    -- Pairs (original element, copy element), matched by name and by order among same-named
    -- siblings. List rows (options, save slots...) are made by the game at run time: a
    -- ScrollList builds its rows in init() from its ItemCount, so when the original list's
    -- count differs from what the copy was built with, the copy's list gets the original's
    -- properties and init() too. (Control.duplicate can't be used: what it returns isn't
    -- reachable from Lua.) Copy elements the original doesn't have are hidden.
    local SCROLL_T = "via.gui.ScrollList"
    local function fs_pairs(a, b, out)
        if a:get_type_definition():get_full_name() == SCROLL_T then
            local n = safe(function() return a:call("get_ItemCount") end)
            local nb = 0
            local c = b:call("get_Child")
            while c do nb = nb + 1; c = c:call("get_Next") end
            local na = 0
            c = a:call("get_Child")
            while c do na = na + 1; c = c:call("get_Next") end
            local key = b:get_address()
            if na ~= nb and out.init_n[key] ~= n then   -- (once per row count: no init every frame)
                out.init_n[key] = n
                pcall(a.call, a, "copyProperties", b)
                pcall(b.call, b, "init()")
                out.inits = (out.inits or 0) + 1
            end
            out.lists[#out.lists + 1] = { a, n }
        end
        local kids, used, taken = {}, {}, {}
        local cb = b:call("get_Child")
        while cb do
            local n = cb:call("get_Name") or ""
            kids[n] = kids[n] or {}
            table.insert(kids[n], cb)
            cb = cb:call("get_Next")
        end
        local ca = a:call("get_Child")
        while ca do
            local n = ca:call("get_Name") or ""
            used[n] = (used[n] or 0) + 1
            local m = kids[n] and kids[n][used[n]]
            if m and m:get_type_definition():get_full_name() == ca:get_type_definition():get_full_name() then
                taken[m:get_address()] = true
                local i = #out + 1
                out[i] = { ca, m }
                fs_pairs(ca, m, out)
                out[i][3] = #out + 1   -- (first pair after this element's subtree)
            else
                out.miss = (out.miss or 0) + 1
            end
            ca = ca:call("get_Next")
        end
        for _, l in pairs(kids) do
            for _, c in ipairs(l) do
                if not taken[c:get_address()] then pcall(c.call, c, "set_Visible", false) end
            end
        end
        return out
    end
    -- a list in the original changed its row count since the pairs were made
    local function fs_lists_changed(e)
        for _, l in ipairs(e.pairs.lists or {}) do
            if safe(function() return l[1]:call("get_ItemCount") end) ~= l[2] then return true end
        end
        return false
    end
    -- Elements with ResolutionAdjust re-anchor themselves to the screen edges for other aspect
    -- ratios; under the x2 view they were pushed off both halves (the pause menu's clock went
    -- to x 2560 of 1920). While the full-size split is on they're laid out as on a 16:9 screen
    -- (adjust off, the copy follows via copyProperties) and put back when the menu closes.
    local function fs_noadj(e)
        e.adj = e.adj or {}
        local function walk(c)
            while c do
                if safe(function() return c:call("get_ResolutionAdjust") end) == true then
                    pcall(c.call, c, "set_ResolutionAdjust", false)
                    e.adj[#e.adj + 1] = c
                end
                walk(c:call("get_Child"))
                c = c:call("get_Next")
            end
        end
        walk(e.g:call("get_View"):call("get_Child"))
    end
    local function fs_restore(key, e)
        if not e.on then return end
        e.on = false
        if valid(e.go) then
            for _, c in ipairs(e.adj or {}) do pcall(c.call, c, "set_ResolutionAdjust", true) end
            pcall(function() local v = e.g:call("get_View"); v:call("set_Scale", e.rs); v:call("set_Position", e.rp) end)
        end
        e.adj, e.fitpos = nil, nil
        if e.copy_go and valid(e.copy_go) then pcall(e.copy_go.call, e.copy_go, "set_DrawSelf", false) end
    end
    local function fs_destroy(key, e)
        fs_restore(key, e)
        if e.copy then D.gui_saved[e.copy:get_address()] = nil end
        if e.copy_go and valid(e.copy_go) then pcall(function() e.copy_go:call("destroy", e.copy_go) end) end
        D.fs[key] = nil
    end
    -- Where things land: GUIs scale about different points (the pause menu about the left
    -- edge, the button guide about the middle...), so the views aren't placed by formula but
    -- steered like the HUD: an element's GlobalPosition (layout units, 1920 wide) should be at
    -- 2 x its full-screen x on player 1's half and 2 x - 1920 on player 2's (y unchanged).
    -- GlobalPosition follows a View change a frame later, so it's corrected every 3rd frame.
    -- A View's Position is scaled with it (moving it 1 moves the layout 2 at scale x2).
    local function fs_steer(v, m, pos, tx, ty, kx, ky)
        local gp = m and m:call("get_GlobalPosition")
        if gp == nil then return end
        local ex, ey = tx - gp.x, ty - gp.y
        if math.abs(ex) > 0.5 or math.abs(ey) > 0.5 then
            pos[1], pos[2] = pos[1] + ex / kx, pos[2] + ey / ky
            v:call("set_Position", Vector3f.new(pos[1], pos[2], 0))
        end
    end
    -- Per-menu fix-ups, run on the copy after each sync (none needed so far; see the View
    -- type note in fs_tick).
    D.FS_FIX = {}
    -- c0: where the GUI's first element sits on a full screen (layout units). Measured from its
    -- GlobalPosition after the GUI has been drawn untouched for a few frames (a GUI that has
    -- never been drawn has no layout yet), then remembered by name for this session.
    D.fs_c0 = D.fs_c0 or {}
    local function fs_tick(key, e)
        local v1 = e.g:call("get_View")
        local draw = safe(function() return e.go:call("get_DrawSelf") and e.g:call("get_Enabled") and v1:call("get_Visible") end) == true
        if not e.on then
            if not draw then return end
            local s, p = v1:call("get_Scale"), v1:call("get_Position")
            local h = D.hud_list[key]   -- the HUD code rescales some (the button guide): use the game's own
            local c0
            if h then
                c0 = { h.m0[1] + h.p.x, h.m0[2] + h.p.y }
            elseif D.fs_c0[e.name] then
                c0 = D.fs_c0[e.name]
            else
                e.wait = (e.wait or 0) + 1
                if e.wait < 4 then return end
                local m = v1:call("get_Child")
                local gp = m and m:call("get_GlobalPosition")
                if gp == nil then return end
                c0 = { gp.x, gp.y }
                D.fs_c0[e.name] = c0
            end
            e.rs, e.rp = Vector3f.new(s.x, s.y, s.z or 1), Vector3f.new(p.x, p.y, p.z or 0)
            e.s = h and h.s or e.rs
            local bp = h and h.p or e.rp
            e.c0 = c0
            e.pos1, e.pos2 = { bp.x, bp.y }, { bp.x - D.FS_W / 2, bp.y }
            e.on, e.at, e.wait = true, st.frame, nil
            pcall(fs_noadj, e)
        end
        -- Player 1's item box screen: the game doesn't pause, and player 2's copies of its GUIs
        -- were drawn with a wrong transform every other frame (a fast flicker of the screen on his
        -- half). Its GUIs are fitted whole into player 1's half instead (scale 0.66, layout
        -- x 320-1730 across it) and player 2's half keeps his own view.
        -- The inventory / map / files screens (D.INV_FIT) the same way: fitted whole into player
        -- 1's half with the right aspect (View scale 2k x k about the layout's middle), player
        -- 2's half keeps his own view. st.split_inv_fit = false: the full-size split across both
        -- halves as before. (The pause menu keeps the full-size split.)
        local fitted = st.split_inv_fit ~= false and (D.inv_fit_name(e.name) or (D.inv_up and D.INV_WITH[e.name]) or (D.inv_up and e.name == "GuiBack"))
        local pk = not D.box_busy and fitted and D.INV_K
        if pk and st.split_inv_portrait ~= false and D.inv_up then
            local P = D.portrait_of(e.name)
            if e.name == "GUI_File" then
                if e.detail == nil and st.frame >= (e.detail_at or 0) then
                    e.detail_at = st.frame + 30
                    local function kid(el, n)
                        local c = el and safe(function() return el:call("get_Child") end)
                        while c do
                            if safe(function() return c:call("get_Name") end) == n then return c end
                            c = safe(function() return c:call("get_Next") end)
                        end
                    end
                    local d = kid(kid(v1, "main"), "c_file_detail")
                    if d then e.detail = d:add_ref() end
                end
                if e.detail and safe(function() return e.detail:call("get_Visible") end) == true then P = D.PORTRAIT_READ end
            end
            if e.name == "GuiBack" then
                v1:call("set_Scale", Vector3f.new(1, D.BACK_SY, 1))
                v1:call("set_Position", Vector3f.new(0, 0, 0))
                return
            end
            if P or e.name == "GuiFront" then
                if P then
                    local k = P[1]
                    local ox, oy = P[4] * 1920 / 728, P[5] * 1080 / 819
                    v1:call("set_Scale", Vector3f.new(2 * k, k, 1))
                    v1:call("set_Position", Vector3f.new(ox - 2 * k * P[2], oy - k * P[3], 0))
                else   -- the dark backdrop over the whole half
                    v1:call("set_Scale", Vector3f.new(1, 1, 1))
                    v1:call("set_Position", Vector3f.new(0, 0, 0))
                end
                if e.copy_go and valid(e.copy_go) and safe(function() return e.copy_go:call("get_DrawSelf") end) then pcall(e.copy_go.call, e.copy_go, "set_DrawSelf", false) end
                return
            end
        end
        if pk and e.name == "GuiBack" then   -- (the backdrop: its own size, player 1's half only)
            v1:call("set_Scale", e.rs)
            v1:call("set_Position", e.rp)
            if e.copy_go and valid(e.copy_go) and safe(function() return e.copy_go:call("get_DrawSelf") end) then pcall(e.copy_go.call, e.copy_go, "set_DrawSelf", false) end
            return
        end
        if D.box_busy or pk then
            local k = pk or 0.66
            v1:call("set_Scale", Vector3f.new(2 * k, k, 1))
            if pk then
                -- (GUIs scale about different points: placed by formula first, then steered so
                -- the first element lands where the fitted full-screen layout puts it)
                e.fitpos = e.fitpos or { 960 - 1920 * k, 540 - 540 * k }
                v1:call("set_Position", Vector3f.new(e.fitpos[1], e.fitpos[2], 0))
                if (st.frame - e.at) % 3 == 2 then
                    fs_steer(v1, v1:call("get_Child"), e.fitpos, 960 + (e.c0[1] - 960) * 2 * k, 540 + (e.c0[2] - 540) * k, 2 * k, k)
                end
            else
                v1:call("set_Position", Vector3f.new(20 - 2 * k * 320, (1080 - 1080 * k) / 2, 0))
            end
            if e.copy_go and valid(e.copy_go) and safe(function() return e.copy_go:call("get_DrawSelf") end) then pcall(e.copy_go.call, e.copy_go, "set_DrawSelf", false) end
            return
        end
        local sc = Vector3f.new(e.s.x * 2, e.s.y, e.s.z)
        local steer = (st.frame - e.at) % 3 == 2
        v1:call("set_Scale", sc)
        v1:call("set_Position", Vector3f.new(e.pos1[1], e.pos1[2], 0))
        if steer and draw then fs_steer(v1, v1:call("get_Child"), e.pos1, 2 * e.c0[1], e.c0[2], sc.x, sc.y) end
        if not draw then
            if e.copy_go and valid(e.copy_go) and safe(function() return e.copy_go:call("get_DrawSelf") end) then pcall(e.copy_go.call, e.copy_go, "set_DrawSelf", false) end
            return
        end
        if e.copy_go == nil or not valid(e.copy_go) then
            local cgo = sdk.find_type_definition("via.GameObject"):get_method("create(System.String, via.Folder)"):call(nil, "rcu_P2_" .. e.name, e.go:call("get_Folder"))
            if cgo == nil then return end
            e.copy_go = cgo:add_ref()
            local c = cgo:call("createComponent(System.Type)", sdk.typeof("via.gui.GUI"))
            if c == nil then return end
            e.copy = c:add_ref()
            pcall(c.call, c, "set_Segment", e.g:call("get_Segment"))
            pcall(c.call, c, "set_RenderOutputID", D.P2_OUT)
            pcall(c.call, c, "set_Asset", e.g:call("get_Asset"))
            D.gui_saved[c:get_address()] = { g = e.copy, id = D.P2_OUT }   -- (pin_shared leaves it on P2_OUT)
            e.pairs, e.init_n, e.fix = nil, nil, nil
        end
        if safe(function() return e.copy:call("get_Ready") end) ~= true then return end
        local v2 = e.copy:call("get_View")
        if e.pairs == nil or st.frame >= (e.pairs_at or 0) or fs_lists_changed(e) then
            e.init_n = e.init_n or {}
            local ok, pr = pcall(fs_pairs, v1, v2, { lists = {}, init_n = e.init_n })
            e.pairs = ok and pr or { lists = {} }
            e.miss = e.pairs.miss or 0
            e.inits = (e.inits or 0) + (e.pairs.inits or 0)
            e.pairs_at = st.frame + ((e.pairs.inits or 0) > 0 and 1 or 30)   -- rows just built: match them next frame
            pcall(fs_noadj, e)   -- (elements the game added since)
        end
        local t0 = os.clock()
        -- A hidden element's children aren't drawn: they're skipped (the options menu has ~3600
        -- elements, mostly in the tabs not shown; syncing all of them took ~16 ms a frame).
        local ok = pcall(function()
            v1:call("copyProperties", v2)
            local P2 = e.pairs
            local i, n = 1, #P2
            while i <= n do
                local pr = P2[i]
                pr[1]:call("copyProperties", pr[2])
                if pr[1]:call("get_Visible") then i = i + 1 else i = pr[3] end
            end
        end)
        e.ms = (os.clock() - t0) * 1000   -- (sync cost, for tuning)
        -- The inventory / map / files background (GuiBack: blur + dark panels) has a View of
        -- ViewType 1, which only draws on Main Camera's output; its copy drew nothing on player
        -- 2's. As ViewType 0 it draws there, blur included.
        if ok and v2:call("get_ViewType") ~= 0 then pcall(v2.call, v2, "set_ViewType", 0) end
        local fix = D.FS_FIX[e.name]
        if fix and ok then
            local fok, ferr = pcall(fix, e, v1, v2)
            if not fok then e.fix_err = tostring(ferr) end
        end
        if not ok then e.pairs = nil end
        v2:call("set_Scale", sc)
        v2:call("set_Position", Vector3f.new(e.pos2[1], e.pos2[2], 0))
        if steer then fs_steer(v2, v2:call("get_Child"), e.pos2, 2 * e.c0[1] - D.FS_W, e.c0[2], sc.x, sc.y) end
        if safe(function() return e.copy_go:call("get_DrawSelf") end) ~= true then pcall(e.copy_go.call, e.copy_go, "set_DrawSelf", true) end
        if safe(function() return e.copy:call("get_RenderOutputID") end) ~= D.P2_OUT then pcall(e.copy.call, e.copy, "set_RenderOutputID", D.P2_OUT) end
    end
    function D.full_split(on)
        -- one of the inventory / map / files GUIs drawn this frame (D.INV_WITH follow them)
        local up = false
        if on then
            for _, e in pairs(D.fs) do
                if D.inv_fit_name(e.name) and valid(e.go) and safe(function() return e.go:call("get_DrawSelf") and e.g:call("get_Enabled") and e.g:call("get_View"):call("get_Visible") end) == true then up = true; break end
            end
        end
        if up ~= (D.inv_up or false) then
            -- switching: the followers start over (their saved scale / place) in the new mode
            for _, e in pairs(D.fs) do if D.INV_WITH[e.name] or e.name == "GuiBack" then pcall(fs_restore, nil, e) end end
        end
        D.inv_up = up
        for key, e in pairs(D.fs) do
            if not valid(e.go) then
                pcall(fs_destroy, key, e)
            elseif on then
                local ok, err = pcall(fs_tick, key, e)
                if not ok then e.err = tostring(err) end
            else
                pcall(fs_restore, key, e)
            end
        end
    end
    function D.full_split_off()
        for key, e in pairs(D.fs) do pcall(fs_destroy, key, e) end
        D.fs = {}
    end
    function D.menu_mirror(on)
        if not on then
            for k, e in pairs(D.menu_both) do pcall(e.g.call, e.g, "set_RenderOutputID", e.id); D.menu_both[k] = nil end
            return
        end
        if st.frame % 5 ~= 0 then return end
        local both = D.P1_OUT | D.P2_OUT
        local full = st.split_menu_full ~= false
        local seen = {}
        for _, g in ipairs(scene_comps("via.gui.GUI")) do
            local key = g:get_address()
            local e = D.menu_both[key]
            local id = math.tointeger(safe(function() return g:call("get_RenderOutputID") end) or 0)
            if e then
                seen[key] = e
                if id ~= both then pcall(g.call, g, "set_RenderOutputID", both) end
            elseif id == D.P1_OUT and D.fs[key] == nil
                and not (D.ret_gui and key == D.ret_gui:get_address())
                and not (D.guide and key == D.guide:get_address())
                and safe(function() return g:call("get_RenderTarget") end) == nil then
                local nm = D.gui_names[key]
                if nm == nil then
                    nm = safe(function() return g:call("get_GameObject"):call("get_Name") end) or ""
                    D.gui_names[key] = nm
                end
                if full and D.is_full_split(nm) then
                    local go = safe(function() return g:call("get_GameObject") end)
                    if go then D.fs[key] = { g = g:add_ref(), go = go:add_ref(), name = nm } end
                elseif D.hud_list[key] == nil and nm ~= "GUI_MouseCursor" and nm ~= "GUI_Save" and nm:sub(1, 4) ~= "rcu_" then   -- (the mod's own copies keep their output)
                    seen[key] = { g = g:add_ref(), id = id }
                    pcall(g.call, g, "set_RenderOutputID", both)
                end
            end
        end
        D.menu_both = seen
    end
    -- The typewriter's save screen (GUI_Save). The game doesn't pause for it (no IsGuiOpen /
    -- IsInPause), so it isn't one of the full-size split menus: it stays on player 1's half,
    -- where the full-screen layout was squeezed to half its width. It's fitted whole into the
    -- half instead, with the right aspect: View scale (2k, k) about the half's middle (layout
    -- 960,540), ResolutionAdjust off while it's up (the anchored list was pushed off the left
    -- edge), all put back when it closes or split screen ends. (It used to be in D.FULL_SPLIT:
    -- the copy on player 2's half came and went with IsGuiOpen as the screen opened and closed,
    -- a twitch of both halves.)
    D.SAVE_K = 0.68
    function D.save_fit(on)
        local S = D.save
        if S == nil or not valid(S.go) then
            S = nil
            D.save = nil
            if not on or st.frame % 30 ~= 0 then return end
            local sc = sdk.call_native_func(sdk.get_native_singleton("via.SceneManager"), sdk.find_type_definition("via.SceneManager"), "get_CurrentScene")
            local go = sc and safe(function() return sc:call("findGameObject(System.String)", "GUI_Save") end)
            local g = go and comp(go, "via.gui.GUI")
            if g == nil then return end
            S = { go = go:add_ref(), g = g:add_ref() }
            D.save = S
        end
        local v = safe(function() return S.g:call("get_View") end)
        if v == nil then return end
        local up = on and safe(function() return S.go:call("get_DrawSelf") and S.g:call("get_Enabled") and v:call("get_Visible") end) == true
        if up then
            if not S.fit then
                -- (put back to the layout's own scale 1 / position 0 on close, not to what was read
                -- here: after a script reset with the screen open that would be the fitted values)
                S.rs, S.rp = Vector3f.new(1, 1, 1), Vector3f.new(0, 0, 0)
                S.adj = {}
                local function walk(c, d)
                    while c do
                        if safe(function() return c:call("get_ResolutionAdjust") end) == true then
                            pcall(c.call, c, "set_ResolutionAdjust", false)
                            S.adj[#S.adj + 1] = c:add_ref()
                        end
                        if d < 10 then walk(safe(function() return c:call("get_Child") end), d + 1) end
                        c = safe(function() return c:call("get_Next") end)
                    end
                end
                walk(v:call("get_Child"), 0)
                S.fit = true
            end
            local k = D.SAVE_K
            local sc = v:call("get_Scale")
            if math.abs(sc.x - 2 * k) > 0.001 or math.abs(sc.y - k) > 0.001 then v:call("set_Scale", Vector3f.new(2 * k, k, 1)) end
            local p = v:call("get_Position")
            local px, py = 960 - 1920 * k, 540 - 540 * k
            if math.abs(p.x - px) > 0.5 or math.abs(p.y - py) > 0.5 then v:call("set_Position", Vector3f.new(px, py, 0)) end
        elseif S.fit then
            S.fit = false
            for _, c in ipairs(S.adj or {}) do pcall(c.call, c, "set_ResolutionAdjust", true) end
            S.adj = nil
            pcall(function() v:call("set_Scale", S.rs); v:call("set_Position", S.rp) end)
        end
    end
    function D.unpin_shared()
        pcall(D.save_fit, false)
        pcall(D.full_split_off)
        D.gui_names = {}
        pcall(D.menu_mirror, false)
        pcall(D.hud_restore)
        if D.guide then pcall(D.guide.call, D.guide, "set_RenderOutputID", D.P1_OUT); D.guide = nil end
        for _, s in pairs(D.gui_saved) do pcall(s.g.call, s.g, "set_RenderOutputID", s.id) end
        for _, o in pairs(D.occ_saved) do pcall(o.call, o, "set_Enabled", true) end
        D.gui_saved, D.occ_saved, D.occ_list, D.occ_seen, D.pin_at = {}, {}, {}, {}, nil
    end
    -- Player 2's crosshair is the game's own (the right shape for each weapon, with its spread):
    -- a second copy of the crosshair GUI (GUI_Reticle's layout, ui2011, with its own
    -- ReticleBehavior) drawn on player 2's output. HUNK's guns ask the game's crosshair to draw;
    -- in split screen those requests go to this copy instead (see the hook below the module).
    function D.ret_build()
        if D.ret_go and valid(D.ret_go) then return end
        D.ret_go, D.ret_gui, D.ret_rb = nil, nil, nil
        local sc = sdk.call_native_func(sdk.get_native_singleton("via.SceneManager"), sdk.find_type_definition("via.SceneManager"), "get_CurrentScene")
        local src = sc and safe(function() return sc:call("findGameObject(System.String)", "GUI_Reticle") end)
        local sgui = src and comp(src, "via.gui.GUI")
        if sgui == nil then return end
        local go = sdk.find_type_definition("via.GameObject"):get_method("create(System.String, via.Folder)"):call(nil, "rcu_P2Reticle", src:call("get_Folder"))
        if go == nil then return end
        D.ret_go = go:add_ref()
        local gui = go:call("createComponent(System.Type)", sdk.typeof("via.gui.GUI"))
        if gui == nil then return end
        D.ret_gui = gui:add_ref()
        pcall(gui.call, gui, "set_Segment", sgui:call("get_Segment"))
        pcall(gui.call, gui, "set_RenderOutputID", D.P2_OUT)
        pcall(gui.call, gui, "set_Asset", sgui:call("get_Asset"))
        D.ret_at = st.frame + 10   -- the behaviour is added once the layout has loaded
    end
    function D.ret_update()
        if D.ret_go == nil or not valid(D.ret_go) then return D.ret_build() end
        if D.ret_rb == nil and st.frame >= (D.ret_at or 0) and safe(function() return D.ret_gui:call("get_Ready") end) then
            local rb = safe(function() return D.ret_go:call("createComponent(System.Type)", sdk.typeof("app.ropeway.gui.ReticleBehavior")) end)
            if rb then D.ret_rb = rb:add_ref() end
        end
    end
    function D.ret_destroy()
        if D.ret_go and valid(D.ret_go) then pcall(function() D.ret_go:call("destroy", D.ret_go) end) end
        D.ret_go, D.ret_gui, D.ret_rb, D.ret_h = nil, nil, nil, nil
    end
    -- Player 2's weapon shortcut cross, the game's own look: a copy of GUI_Shortcut (same
    -- layout asset) on player 2's output in split screen (beside player 1's on a shared
    -- screen), driven by the mod: the layout's own animation states (c_shortcut FADE_IN /
    -- FADE_OUT, slots DEFAULT / DEFAULT_BLANK / DECIDE, counts FULL / EMPTY), the icons from
    -- GUIMaster.setWeaponIconTexture and the counts from player 2's inventory. A d-pad press on
    -- pad 2 (st.p2cross) opens it: his guns, or with LB held his knife / grenades.
    local SC = { go = nil, gui = nil, el = nil, shown = nil, t = nil, mode = nil }
    D.sc = SC
    local SC_DIRS = { [0] = "c_slot_top", [1] = "c_slot_bottom", [2] = "c_slot_left", [3] = "c_slot_right" }
    local SC_SHOW = 1.0   -- seconds after the last press (the game's 48 frames, a little longer)
    local function sc_child(e, name)
        local c = e and safe(function() return e:call("get_Child") end)
        local guard = 0
        while c and guard < 64 do
            guard = guard + 1
            if safe(function() return c:call("get_Name") end) == name then return c end
            c = safe(function() return c:call("get_Next") end)
        end
        return nil
    end
    local function sc_path(e, path)
        for name in path:gmatch("[^/]+") do e = sc_child(e, name); if e == nil then return nil end end
        return e
    end
    local function sc_state(e, s)
        if e and safe(function() return e:call("get_PlayState") end) ~= s then pcall(e.call, e, "set_PlayState", s) end
    end
    local function sc_vis(e, v)
        if e and safe(function() return e:call("get_Visible") end) ~= v then pcall(e.call, e, "set_Visible", v) end
    end
    function D.sc_build()
        if SC.go and valid(SC.go) then return true end
        SC.go, SC.gui, SC.el, SC.h, SC.shown = nil, nil, nil, nil, nil
        local sc = sdk.call_native_func(sdk.get_native_singleton("via.SceneManager"), sdk.find_type_definition("via.SceneManager"), "get_CurrentScene")
        local src = sc and safe(function() return sc:call("findGameObject(System.String)", "GUI_Shortcut") end)
        local sgui = src and comp(src, "via.gui.GUI")
        if sgui == nil then return false end
        -- (one left from before a script reset is used again)
        local go = safe(function() return sc:call("findGameObject(System.String)", "rcu_P2Shortcut") end)
        local gui = go and comp(go, "via.gui.GUI")
        if gui == nil then
            go = sdk.find_type_definition("via.GameObject"):get_method("create(System.String, via.Folder)"):call(nil, "rcu_P2Shortcut", src:call("get_Folder"))
            if go == nil then return false end
            gui = go:call("createComponent(System.Type)", sdk.typeof("via.gui.GUI"))
            if gui == nil then return false end
        end
        SC.go = go:add_ref()
        SC.gui = gui:add_ref()
        SC.src_out = math.tointeger(safe(function() return sgui:call("get_RenderOutputID") end) or 2) or 2
        if D.gui_saved[sgui:get_address()] then SC.src_out = D.gui_saved[sgui:get_address()].id end
        pcall(gui.call, gui, "set_Segment", sgui:call("get_Segment"))
        pcall(gui.call, gui, "set_Asset", sgui:call("get_Asset"))
        D.gui_saved[gui:get_address()] = { g = SC.gui, id = D.P2_OUT }   -- (pin_shared leaves it alone)
        SC.mode = nil
        return true
    end
    function D.sc_destroy()
        if SC.go and valid(SC.go) then pcall(function() SC.go:call("destroy", SC.go) end) end
        SC.go, SC.gui, SC.el, SC.h, SC.shown, SC.mode = nil, nil, nil, nil, nil, nil
    end
    local function sc_elements()
        local v = safe(function() return SC.gui:call("get_View") end)
        if v == nil then return nil end
        local el = { view = v }
        for _, k in ipairs({ "c_shortcut", "c_shortcut_sub" }) do
            local root = sc_child(v, k)
            if root == nil then return nil end
            local t = { root = root, key = sc_child(root, "c_key"), slots = {} }
            for sc, name in pairs(SC_DIRS) do
                local pnl = sc_child(root, name)
                if pnl then
                    t.slots[sc] = { panel = pnl, slot = sc_child(pnl, "c_slot"), icon = sc_child(pnl, "icon_item"),
                        cnum = sc_child(pnl, "c_num"), num = sc_path(pnl, "c_num/m_num"), key = sc_child(pnl, "c_shortcut"),
                        subw = sc_child(pnl, "c_subweapon"), gauge = sc_child(pnl, "c_gauge"), focus = sc_child(pnl, "c_focus") }
                end
            end
            el[k] = t
        end
        return el
    end
    local SUBW_STATE = { [46] = "KNIFE", [65] = "GRENADE", [66] = "FLASH" }
    -- fill one cross (main: guns by d-pad; sub: knife / grenades by LB + d-pad) from his inventory
    local function sc_fill(t, sub, hinv, pressed)
        local P = st.p2inv
        local gm = sdk.get_managed_singleton("app.ropeway.gui.GUIMaster")
        local sig = sub and P.SUB_SIG or "getSlot(app.ropeway.EquipmentDefine.Shortcut)"
        sc_state(t.key, "DEFAULT")
        for sc, e in pairs(t.slots) do
            local idx = safe(function() return hinv:call(sig, sc):call("get_Index") end)
            local sl = idx and idx >= 0 and P.slot_at(hinv, idx) or nil
            local wt = sl and safe(function() return sl:call("get_WeaponType") end) or -1
            sc_state(e.key, "DISABLE")
            sc_state(e.gauge, "DISABLE")
            if wt > 0 then
                sc_state(e.panel, sc == pressed and "DECIDE" or "DEFAULT")
                sc_state(e.slot, "DEFAULT")
                sc_vis(e.icon, true)
                if e.wt ~= wt then
                    local parts = safe(function() return sl:call("get_WeaponParts") end) or 0
                    if gm and e.icon then pcall(gm.call, gm, "setWeaponIconTexture", e.icon, wt, parts) end
                    e.wt = wt
                end
                sc_state(e.subw, sub and SUBW_STATE[wt] or "DEFAULT")
                local n = safe(function() return sl:call("get_Number") end) or 0
                if wt == 46 then
                    sc_vis(e.cnum, false)
                else
                    sc_vis(e.cnum, true)
                    local max = safe(function() return sl:call("get_MaxNumber") end) or 0
                    sc_state(e.cnum, n <= 0 and "EMPTY" or ((max > 0 and n >= max) and "FULL" or "DEFAULT"))
                    if e.n ~= n and e.num then   -- (Text.set_Message needs a managed string)
                        if pcall(e.num.call, e.num, "set_Message", sdk.create_managed_string(tostring(n))) then e.n = n end
                    end
                end
            else
                sc_state(e.panel, "DEFAULT_BLANK")
                sc_state(e.slot, "BLANK")
                sc_vis(e.icon, false)
                sc_vis(e.cnum, false)
                sc_state(e.subw, "DEFAULT")
                e.wt = nil
            end
        end
    end
    function D.sc_update()
        local c = st.p2cross
        local want = c ~= nil and st.hunk ~= nil and st.p2inv ~= nil and st.p2_shortcut_gui ~= false and not st.ai_partner()
            and not (p2c.menu_open and p2c.menu_open())
        if not want and not SC.shown then return end
        if not D.sc_build() then return end
        if safe(function() return SC.gui:call("get_Ready") end) ~= true then return end
        if SC.el == nil then SC.el = sc_elements(); if SC.el == nil then return end end
        -- (a copy kept from before a script reset can come back with its GameObject not drawn:
        -- the cross stayed invisible; switched back on whenever it's wanted)
        if want and safe(function() return SC.go:call("get_DrawSelf") end) ~= true then pcall(SC.go.call, SC.go, "set_DrawSelf", true) end
        -- where: player 2's half (split screen, scaled like the rest of his HUD) or beside
        -- player 1's cross on a shared screen
        local mode = p2c.active and "split" or "shared"
        local out = mode == "split" and D.P2_OUT or SC.src_out
        if st.frame % 30 == 0 and safe(function() return SC.gui:call("get_RenderOutputID") end) ~= out then
            pcall(SC.gui.call, SC.gui, "set_RenderOutputID", out)
        end
        if SC.mode ~= mode then
            SC.mode = mode
            SC.h = nil
            pcall(SC.gui.call, SC.gui, "set_RenderOutputID", mode == "split" and D.P2_OUT or SC.src_out)
            pcall(function()
                local v = SC.gui:call("get_View")
                v:call("set_Scale", Vector3f.new(1, 1, 1))
                v:call("set_Position", Vector3f.new(mode == "split" and 0 or 560, mode == "split" and 0 or 40, 0))
            end)
        end
        if mode == "split" and st.frame % 10 == 0 then
            -- his half is the same shape as player 1's: the same placement as player 1's cross
            -- (which D.hud_apply fits to her half)
            pcall(function()
                local scn = sdk.call_native_func(sdk.get_native_singleton("via.SceneManager"), sdk.find_type_definition("via.SceneManager"), "get_CurrentScene")
                local sv = comp(scn:call("findGameObject(System.String)", "GUI_Shortcut"), "via.gui.GUI"):call("get_View")
                local v = SC.gui:call("get_View")
                v:call("set_Scale", sv:call("get_Scale"))
                v:call("set_Position", sv:call("get_Position"))
            end)
        end
        local el = SC.el
        if want then
            local hinv = st.p2inv.hunk_inv()
            if hinv == nil then return end
            local which = c.sub and "c_shortcut_sub" or "c_shortcut"
            local other = c.sub and "c_shortcut" or "c_shortcut_sub"
            local fresh = SC.t ~= c.t
            local alive = os.clock() - c.t < SC_SHOW or (c.sub and (pad2_buttons() & 256) ~= 0)
            if fresh then SC.dec = c.dir end
            if alive then
                sc_state(el.view, "DEFAULT")
                if SC.shown ~= which then sc_state(el[which].root, "FADE_IN"); sc_state(el[other].root, "FADE_OUT"); SC.shown = which end
                sc_fill(el[which], c.sub, hinv, SC.dec)
                SC.t = c.t
                return
            end
            st.p2cross = nil
        end
        if SC.shown then
            sc_state(el.c_shortcut.root, "FADE_OUT")
            sc_state(el.c_shortcut_sub.root, "FADE_OUT")
            SC.shown, SC.dec = nil, nil
        end
    end
    -- Player 2's ammo count while he aims, the game's own look: a copy of GUI_RemainingBullet
    -- (same layout asset, no RemainingBulletBehavior: that one reads player 1's gun) on player
    -- 2's output in split screen (left of player 1's on a shared screen), driven by the mod.
    -- Layout: main (DISABLE / FADE_IN / FADE_OUT), main/c_type (state TYPE0..TYPE5 picks the
    -- panel): c_type0 = magazine m_num0 over the rounds he carries m_num1 (most guns),
    -- c_type2 = one number (no spare rounds: rocket launcher, Infinite ammo), c_type4 = grenade
    -- count. Recorded from player 1's: FADE_IN as the aim starts, FADE_OUT as it ends.
    -- Off with st.p2_ammo_gui = false.
    local AM = { go = nil, gui = nil, el = nil, shown = false, mode = nil, txt = {} }
    D.am = AM
    local AM_TYPES = { "c_type0", "c_type1", "c_type1_sub", "c_type2", "c_type3", "c_type4", "c_type5" }
    function D.am_build()
        if AM.go and valid(AM.go) then return true end
        AM.go, AM.gui, AM.el, AM.shown, AM.mode, AM.txt = nil, nil, nil, false, nil, {}
        local sc = sdk.call_native_func(sdk.get_native_singleton("via.SceneManager"), sdk.find_type_definition("via.SceneManager"), "get_CurrentScene")
        local src = sc and safe(function() return sc:call("findGameObject(System.String)", "GUI_RemainingBullet") end)
        local sgui = src and comp(src, "via.gui.GUI")
        if sgui == nil then return false end
        -- (one left from before a script reset is used again)
        local go = safe(function() return sc:call("findGameObject(System.String)", "rcu_P2Ammo") end)
        local gui = go and comp(go, "via.gui.GUI")
        if gui == nil then
            go = sdk.find_type_definition("via.GameObject"):get_method("create(System.String, via.Folder)"):call(nil, "rcu_P2Ammo", src:call("get_Folder"))
            if go == nil then return false end
            gui = go:call("createComponent(System.Type)", sdk.typeof("via.gui.GUI"))
            if gui == nil then return false end
        end
        AM.go = go:add_ref()
        AM.gui = gui:add_ref()
        AM.src_out = math.tointeger(safe(function() return sgui:call("get_RenderOutputID") end) or 2) or 2
        if D.gui_saved[sgui:get_address()] then AM.src_out = D.gui_saved[sgui:get_address()].id end
        pcall(gui.call, gui, "set_Segment", sgui:call("get_Segment"))
        pcall(gui.call, gui, "set_Asset", sgui:call("get_Asset"))
        pcall(go.call, go, "set_DrawSelf", true)
        D.gui_saved[gui:get_address()] = { g = AM.gui, id = D.P2_OUT }   -- (pin_shared leaves it alone)
        return true
    end
    function D.am_destroy()
        if AM.go and valid(AM.go) then pcall(function() AM.go:call("destroy", AM.go) end) end
        AM.go, AM.gui, AM.el, AM.shown, AM.mode, AM.txt = nil, nil, nil, false, nil, {}
    end
    local function am_elements()
        local v = safe(function() return AM.gui:call("get_View") end)
        local main = v and sc_child(v, "main")
        local ct = main and sc_child(main, "c_type")
        if ct == nil then return nil end
        local el = { view = v, main = main, ct = ct, types = {} }
        for _, n in ipairs(AM_TYPES) do el.types[n] = sc_child(ct, n) end
        el.n0 = sc_path(ct, "c_type0/m_num0")
        el.n1 = sc_path(ct, "c_type0/m_num1")
        el.n2 = sc_path(ct, "c_type2/m_num0")
        el.n4 = sc_path(ct, "c_type4/m_num0")
        sc_state(main, "DISABLE")
        return el
    end
    local function am_text(e, s)
        if e == nil then return end
        local k = e:get_address()
        if AM.txt[k] == s then return end
        if pcall(e.call, e, "set_Message", sdk.create_managed_string(s)) then AM.txt[k] = s end
    end
    -- what he's aiming: nil, or { kind = "TYPE0" / "TYPE2" / "TYPE4", mag, spare }
    local function am_what()
        if st.hunk == nil or st.p2inv == nil or st.p2_ammo_gui == false or st.ai_partner() then return nil end
        if st.infinite_ammo then return nil end   -- (infinite ammo: nothing to count)
        if (p2c.menu_open and p2c.menu_open()) or st.in_cutscene() or (st.cut_hide and st.cut_hide.on) then return nil end
        local sub = hunk_sub_holding()
        if not sub and not hunk_is_aiming() then return nil end
        local P = st.p2inv
        local hinv = P.hunk_inv()
        if hinv == nil then return nil end
        local idx = sub and P.sub_index(hinv) or P.main_index(hinv)
        local sl = idx and idx >= 0 and P.slot_at(hinv, idx) or nil
        local wt = sl and safe(function() return sl:call("get_WeaponType") end) or -1
        if wt <= 0 or wt == 46 then return nil end   -- (nothing / the knife)
        local mag = safe(function() return sl:call("get_Number") end) or 0
        if wt == 65 or wt == 66 then return { kind = "TYPE4", mag = mag } end
        local w = WEAPON_BY_WT[wt]
        if w == nil or w.ammo == nil then return { kind = "TYPE2", mag = mag } end
        local spare = safe(function() return hinv:call("getNumber(app.ropeway.gamemastering.Item.ID)", w.ammo) end) or 0
        return { kind = "TYPE0", mag = mag, spare = spare }
    end
    function D.am_update()
        local w = am_what()
        if w == nil and not AM.shown then return end
        if not D.am_build() then return end
        if safe(function() return AM.gui:call("get_Ready") end) ~= true then return end
        if AM.el == nil then AM.el = am_elements(); if AM.el == nil then return end end
        if w and safe(function() return AM.go:call("get_DrawSelf") end) ~= true then pcall(AM.go.call, AM.go, "set_DrawSelf", true) end
        local el = AM.el
        -- where: player 2's half (placed like player 1's, which D.hud_apply fits to her half) or
        -- left of player 1's on a shared screen
        local mode = p2c.active and "split" or "shared"
        if AM.mode ~= mode or st.frame % 30 == 0 then
            pcall(AM.gui.call, AM.gui, "set_RenderOutputID", mode == "split" and D.P2_OUT or AM.src_out)
            if AM.mode ~= mode then
                AM.mode = mode
                pcall(function()
                    local v = AM.gui:call("get_View")
                    v:call("set_Scale", Vector3f.new(1, 1, 1))
                    v:call("set_Position", Vector3f.new(mode == "split" and 0 or -300, 0, 0))
                end)
            end
        end
        if mode == "split" and st.frame % 10 == 0 then
            pcall(function()
                local scn = sdk.call_native_func(sdk.get_native_singleton("via.SceneManager"), sdk.find_type_definition("via.SceneManager"), "get_CurrentScene")
                local sv = comp(scn:call("findGameObject(System.String)", "GUI_RemainingBullet"), "via.gui.GUI"):call("get_View")
                local v = AM.gui:call("get_View")
                v:call("set_Scale", sv:call("get_Scale"))
                v:call("set_Position", sv:call("get_Position"))
            end)
        end
        if w then
            local panel = w.kind == "TYPE0" and "c_type0" or (w.kind == "TYPE2" and "c_type2" or "c_type4")
            sc_state(el.ct, w.kind)
            sc_vis(el.ct, true)
            for n, e in pairs(el.types) do sc_vis(e, n == panel) end
            if w.kind == "TYPE0" then
                am_text(el.n0, tostring(w.mag)); am_text(el.n1, tostring(w.spare))
            elseif w.kind == "TYPE2" then
                am_text(el.n2, tostring(w.mag))
            else
                am_text(el.n4, tostring(w.mag))
            end
            if not AM.shown then sc_state(el.main, "FADE_IN"); AM.shown = true end
        elseif AM.shown then
            sc_state(el.main, "FADE_OUT")
            AM.shown = false
        end
    end
    -- Player 2's interact icons, the game's own look. The game's (GUI_FloatIcon, one
    -- FloatIconBehavior GUI per icon in RopewayManagers/GUI/GuiTemporaryObjects) are placed with
    -- player 1's camera for what player 1 can reach. Player 2 gets a small pool of copies of the
    -- same layout on his output (rcu_P2Float1..N), driven by the mod: what HUNK's A would act
    -- on (an item he'd pick up for Leon, else an item box, else a door) shows the button
    -- (c_icon_sub BUTTON, m_icon "<icon R_DF>"), the other items / boxes / doors near him a marker
    -- (OBJECT). Placed with his camera's ViewProjMatrix (layout 1920 x 1080 over his half, View
    -- scale D.hud_k() so the icons keep their shape). Split screen only. st.p2_icons = false: off.
    local FI = { pool = {}, N = 6, cand = {}, scan_at = 0, box = {}, box_at = -1000 }
    D.fi = FI
    local FI_RANGE, FI_BUTTON = 4.5, "<icon R_DF>"
    local function fi_kid(e, n)
        local c = e and safe(function() return e:call("get_Child") end)
        while c do
            if safe(function() return c:call("get_Name") end) == n then return c end
            c = safe(function() return c:call("get_Next") end)
        end
    end
    local function fi_build(i)
        local slot = FI.pool[i]
        if slot and valid(slot.go) then return slot end
        local sc = sdk.call_native_func(sdk.get_native_singleton("via.SceneManager"), sdk.find_type_definition("via.SceneManager"), "get_CurrentScene")
        if sc == nil then return nil end
        local name = "rcu_P2Float" .. i
        local go = safe(function() return sc:call("findGameObject(System.String)", name) end)
        local gui = go and comp(go, "via.gui.GUI")
        if gui == nil then
            -- (the layout from one of the game's own float icons; there are always a couple)
            local l = safe(function() return sc:call("findComponents(System.Type)", sdk.typeof("app.ropeway.gui.FloatIconBehavior")) end)
            local b = l and safe(function() return l:call("get_Count") end) or 0
            if b == 0 then return nil end
            local src = l:call("get_Item", 0):call("get_GameObject")
            local sgui = comp(src, "via.gui.GUI")
            if sgui == nil then return nil end
            go = sdk.find_type_definition("via.GameObject"):get_method("create(System.String, via.Folder)"):call(nil, name, src:call("get_Folder"))
            if go == nil then return nil end
            gui = go:call("createComponent(System.Type)", sdk.typeof("via.gui.GUI"))
            if gui == nil then return nil end
            pcall(gui.call, gui, "set_Segment", sgui:call("get_Segment"))
            pcall(gui.call, gui, "set_Asset", sgui:call("get_Asset"))
        end
        pcall(gui.call, gui, "set_RenderOutputID", D.P2_OUT)
        pcall(go.call, go, "set_DrawSelf", false)
        D.gui_saved[gui:get_address()] = { g = gui:add_ref(), id = D.P2_OUT }   -- (pin_shared leaves it alone)
        slot = { go = go:add_ref(), gui = gui:add_ref(), el = nil, shown = false, kind = nil, txt = nil }
        FI.pool[i] = slot
        return slot
    end
    local function fi_elements(slot)
        if slot.el then return slot.el end
        if safe(function() return slot.gui:call("get_Ready") end) ~= true then return nil end
        local v = slot.gui:call("get_View")
        local main = fi_kid(v, "main")
        local new = fi_kid(main, "c_icon_NEW")
        if new == nil then return nil end
        local sub = fi_kid(new, "c_icon_sub")
        local rot = sub and fi_kid(fi_kid(sub, "c_icon"), "c_icon_rotate")
        slot.el = { view = v, main = main, new = new, old = fi_kid(main, "c_icon_OLD"), sight = fi_kid(main, "c_icon_SIGHT"),
            sub = sub, rot = rot, icon = rot and fi_kid(rot, "m_icon") }
        -- (the layout starts c_icon_rotate in HOLD, the "HOLD" ring of hold-to-use prompts, with
        -- the button glyph in another font slot: DEFAULT is the plain press, as the game sets it)
        sc_state(rot, "DEFAULT")
        for _, n in ipairs({ "bg_hold", "bg_hold_line", "gauge_hold", "light", "m_hold", "disable_circle", "Rect0", "Rect1" }) do
            sc_vis(fi_kid(rot, n), false)
        end
        sc_vis(slot.el.icon, true)
        return slot.el
    end
    local function fi_hide(slot)
        if slot and slot.shown then
            pcall(slot.go.call, slot.go, "set_DrawSelf", false)
            slot.shown = false
        end
    end
    function D.fi_off() for _, slot in pairs(FI.pool) do fi_hide(slot) end end
    -- what's near him: { pos = Vector3f (icon point), d = distance, key = target object address }
    local function fi_scan(hp)
        local out = {}
        local function add(obj, x, y, z, up)
            local dx, dz = x - hp.x, z - hp.z
            local d = math.sqrt(dx * dx + dz * dz)
            if d <= FI_RANGE and math.abs(y - hp.y) < 2.0 then
                local o = { pos = Vector3f.new(x, y + up, z), d = d, key = obj:get_address() }
                out[#out + 1] = o
                return o
            end
        end
        -- (item positions cached for a second: they don't move; only the ones in range are
        -- checked further. Scanning every item every few frames cost a frame-time spike.)
        if st.frame - (FI.items_at or -1000) >= 60 then
            FI.items_at = st.frame
            if st.frame - item_cache_frame >= 20 then item_cache_frame = st.frame; pcall(scan_items) end
            FI.items = {}
            for _, si in ipairs(item_cache) do
                local p = safe(function() return si:call("get_Position") end)
                if p then FI.items[#FI.items + 1] = { si = si, x = p.x, y = p.y, z = p.z } end
            end
        end
        for _, it in ipairs(FI.items or {}) do
            local dx, dz = it.x - hp.x, it.z - hp.z
            if dx * dx + dz * dz <= FI_RANGE * FI_RANGE and math.abs(it.y - hp.y) < 2.0 then
                pcall(function()
                    local si = it.si
                    local go = si:call("get_GameObject")
                    if not (go:call("get_DrawSelf") and go:call("get_UpdateSelf")) or si:call("get_DisableInteract") then return end
                    local p = si:call("get_Position")
                    local o = add(si, p.x, p.y, p.z, 0.2)
                    if o then o.item = true; o.dy = math.abs(p.y - hp.y) end
                end)
            end
        end
        if not st.infinite_ammo then
            if st.frame - FI.box_at > 120 then
                FI.box_at, FI.box = st.frame, {}
                pcall(function()
                    local sc = sdk.call_native_func(sdk.get_native_singleton("via.SceneManager"), sdk.find_type_definition("via.SceneManager"), "get_CurrentScene")
                    local l = sc:call("findComponents(System.Type)", sdk.typeof("app.ropeway.gimmick.action.GimmickItemLocker"))
                    for i = 0, l:call("get_Count") - 1 do FI.box[#FI.box + 1] = l:call("get_Item", i):add_ref() end
                end)
            end
            for _, b in ipairs(FI.box) do
                pcall(function()
                    local p = b:call("get_GameObject"):call("get_Transform"):call("get_Position")
                    add(b, p.x, p.y, p.z, 1.0)
                end)
            end
        end
        for _, lad in ipairs(st.ladder_list()) do
            pcall(function()
                if not lad:call("checkUsable") then return end
                local lo = lad:get_field("_PosLow"):call("get_Transform"):call("get_Position")
                local hi = lad:get_field("_PosHigh"):call("get_Transform"):call("get_Position")
                local o1 = add(lad, lo.x, lo.y, lo.z, 1.0); if o1 then o1.key = lad:get_address() + 1 end
                local o2 = add(lad, hi.x, hi.y, hi.z, 0.6); if o2 then o2.key = lad:get_address() + 2 end
            end)
        end
        for _, e in pairs(st.jack_follow.list) do
            if e.follow then
                local o = add(e.body, e.start.x, e.start.y, e.start.z, 0.8)
                if o then o.key = e.key + 3 end
            end
        end
        pcall(find_door)   -- (keeps door_cache fresh)
        for _, dr in ipairs(door_cache) do
            pcall(function()
                local c = dr:call("get_Center")
                add(dr, c.x, c.y, c.z, 1.1)
            end)
        end
        table.sort(out, function(a, b) return a.d < b.d end)
        return out
    end
    -- the one HUNK's A acts on (pickup_for_p1's order)
    local function fi_target(cand)
        -- (a ladder end comes first, as on his A)
        local lad, ct = st.find_ladder()
        if lad then return lad:get_address() + 1 + ct end
        local jk = st.find_jack()
        if jk then return jk.key + 3 end
        -- (find_pick_target's rule on the items already in range: nearest within pick_radius,
        -- height within 1.6)
        for _, c in ipairs(cand) do
            if c.item and c.d < (st.pick_radius or 1.6) and (c.dy or 0) <= 1.6 then return c.key end
        end
        if not st.infinite_ammo and st.p2inv and st.p2inv.near_box() then
            for _, c in ipairs(cand) do
                for _, b in ipairs(FI.box) do if b:get_address() == c.key then return c.key end end
            end
        end
        local dr = find_door()
        return dr and dr:get_address() or nil
    end
    -- Player 1's own float icons (the game's GUI_FloatIcon GUIs) were drawn at full-screen
    -- width into her half: squeezed sideways. The game places each icon by its main panel's
    -- position (screen point in layout units), so the View isn't touched; the three camera-mode
    -- panels under main (FloatIconBehavior PanelOld / New / SightCameraMode = c_icon_OLD / NEW /
    -- SIGHT) get the HUD's split-screen scale (D.hud_k) about the icon's point instead, and 1 / 1
    -- again when split screen ends. st.p1_icon_fix = false: off.
    FI.p1 = { list = {}, at = -1000, k = nil }
    local FI_P1_PANELS = { "PanelOldCameraMode", "PanelNewCameraMode", "PanelSightCameraMode" }
    function D.fi_p1()
        local P1 = FI.p1
        local on = D.on and p2c.active and st.p1_icon_fix ~= false
        if not on and P1.k == nil then return end
        if st.frame - P1.at > 30 then
            P1.at = st.frame
            local list = {}
            pcall(function()
                local sc = sdk.call_native_func(sdk.get_native_singleton("via.SceneManager"), sdk.find_type_definition("via.SceneManager"), "get_CurrentScene")
                local l = sc:call("findComponents(System.Type)", sdk.typeof("app.ropeway.gui.FloatIconBehavior"))
                for i = 0, l:call("get_Count") - 1 do
                    local b = l:call("get_Item", i)
                    for _, f in ipairs(FI_P1_PANELS) do
                        local pnl = safe(function() return b:get_field(f) end)
                        if pnl then list[#list + 1] = pnl:add_ref() end
                    end
                end
            end)
            P1.list = list
        end
        local kx, ky = 1, 1
        if on then kx, ky = D.hud_k() end
        for _, pnl in ipairs(P1.list) do
            local sc = safe(function() return pnl:call("get_Scale") end)
            if sc and (math.abs(sc.x - kx) > 0.001 or math.abs(sc.y - ky) > 0.001) then
                pcall(pnl.call, pnl, "set_Scale", Vector3f.new(kx, ky, 1))
            end
        end
        P1.k = on and kx or nil
    end
    function D.fi_update()
        pcall(D.fi_p1)
        local want = st.p2_icons ~= false and p2c.active and D.on and st.hunk ~= nil and not st.ai_partner()
            and not (p2c.menu_open and p2c.menu_open()) and not st.in_cutscene() and not (st.cut_hide and st.cut_hide.on)
            and not (st.ig and st.ig.open) and not hunk_is_aiming()
        if not want or D.cam == nil then D.fi_off(); return end
        local hp = safe(function() return st.hunk:call("get_Transform"):call("get_Position") end)
        if hp == nil then D.fi_off(); return end
        if st.frame >= FI.scan_at then
            FI.scan_at = st.frame + 6
            local ok, cand = pcall(fi_scan, hp)
            FI.cand = ok and cand or {}
            local ok2, t = pcall(fi_target, FI.cand)
            FI.target = ok2 and t or nil
        end
        local vp = safe(function() return D.cam:call("get_ViewProjMatrix") end)
        if vp == nil then D.fi_off(); return end
        local kx, ky = D.hud_k()
        local used = 0
        for _, c in ipairs(FI.cand) do
            if used >= FI.N then break end
            local a = safe(function() return vp * Vector4f.new(c.pos.x, c.pos.y, c.pos.z, 1.0) end)
            if a and a.w > 0.05 then
                local nx, ny = a.x / a.w, a.y / a.w
                if nx > -1.05 and nx < 1.05 and ny > -1.05 and ny < 1.05 then
                    used = used + 1
                    local slot = fi_build(used)
                    local el = slot and fi_elements(slot)
                    if el then
                        local X, Y = (nx + 1) * 960, (1 - ny) * 540
                        pcall(function()
                            el.view:call("set_Scale", Vector3f.new(kx, ky, 1))
                            el.view:call("set_Position", Vector3f.new(0, 0, 0))
                            el.main:call("set_Position", Vector3f.new(X / kx, Y / ky, 0))
                        end)
                        sc_state(el.main, "NEW_CAMERA")
                        sc_vis(el.main, true)
                        sc_vis(el.new, true); sc_vis(el.old, false); sc_vis(el.sight, false)
                        local kind = c.key == FI.target and "BUTTON" or "OBJECT"
                        sc_state(el.sub, kind)
                        sc_state(el.rot, "DEFAULT")
                        if kind == "BUTTON" and slot.txt ~= FI_BUTTON and el.icon then
                            if pcall(el.icon.call, el.icon, "set_Message", sdk.create_managed_string(FI_BUTTON)) then slot.txt = FI_BUTTON end
                        end
                        if not slot.shown then pcall(slot.go.call, slot.go, "set_DrawSelf", true); slot.shown = true end
                        if st.frame % 30 == 0 then pcall(slot.gui.call, slot.gui, "set_RenderOutputID", D.P2_OUT) end
                    end
                end
            end
        end
        for i = used + 1, FI.N do fi_hide(FI.pool[i]) end
    end
    -- Player 2 downed: a marker for player 1 over where he lies (v331), the game's own float icon
    -- (a copy of GUI_FloatIcon, rcu_P1DownMark, on her output), only once she's at his side
    -- and can help him up (the button, BUTTON); before that a red diamond over him (v333). Placed with her camera's ViewProjMatrix like player 2's icons; off her half
    -- (or behind her) it sits at the edge of her half, pointing the way. Under it his name and the
    -- distance, in the DOWNED red. Split screen only (one screen: the label alone, see
    -- st.draw_down_overlay). st.p2_down_mark = false: off.
    -- (v338: one marker per viewer: D.dm player 1's of downed player 2, D.dm2 player 2's of downed
    -- player 1; same look, each on its own output with its own camera)
    local DM = { slot = nil, name = "rcu_P1DownMark", out = "P1_OUT", half = "p1" }
    local DM2 = { slot = nil, name = "rcu_P2DownMark", out = "P2_OUT", half = "p2" }
    D.dm, D.dm2 = DM, DM2
    -- (v395) one screen (Shared Screen, Fixed Camera, AI): the same markers on the one view, on
    -- the game's own output: over downed player 2 for player 1, and over downed player 1 (for
    -- player 2, or the AI partner coming to help)
    local DMS = { slot = nil, name = "rcu_DownMarkS", half = "full" }
    local DMS2 = { slot = nil, name = "rcu_DownMarkS2", half = "full" }
    D.dms, D.dms2 = DMS, DMS2
    local function dm_build(M)
        local slot = M.slot
        if slot and valid(slot.go) then return slot end
        local sc = sdk.call_native_func(sdk.get_native_singleton("via.SceneManager"), sdk.find_type_definition("via.SceneManager"), "get_CurrentScene")
        if sc == nil then return nil end
        local go = safe(function() return sc:call("findGameObject(System.String)", M.name) end)
        local gui = go and comp(go, "via.gui.GUI")
        if gui == nil then
            -- (the layout from one of the game's float icons in the scene, or the one remembered
            -- from earlier: an area with nothing to interact with has none, the city street)
            pcall(D.fi_remember)
            local F = D.fi_src
            if F == nil then return nil end
            -- (made in the folder of the game's HUD, GUI_CombatIcon, which every area has;
            -- one screen: drawn on that HUD's output too)
            local hud = safe(function() return sc:call("findGameObject(System.String)", "GUI_CombatIcon") end)
            local folder = hud and safe(function() return hud:call("get_Folder") end)
            if folder == nil then return nil end
            go = sdk.find_type_definition("via.GameObject"):get_method("create(System.String, via.Folder)"):call(nil, M.name, folder)
            if go == nil then return nil end
            gui = go:call("createComponent(System.Type)", sdk.typeof("via.gui.GUI"))
            if gui == nil then return nil end
            pcall(gui.call, gui, "set_Segment", F.seg)
            pcall(gui.call, gui, "set_Asset", F.asset)
            local hgui = comp(hud, "via.gui.GUI")
            if M.out == nil and hgui then
                M.src_out = D.gui_saved[hgui:get_address()] and D.gui_saved[hgui:get_address()].id or safe(function() return hgui:call("get_RenderOutputID") end)
            end
        end
        if M.out == nil and M.src_out == nil then
            local hud = safe(function() return sc:call("findGameObject(System.String)", "GUI_CombatIcon") end)
            local hgui = hud and comp(hud, "via.gui.GUI")
            M.src_out = hgui and (D.gui_saved[hgui:get_address()] and D.gui_saved[hgui:get_address()].id or safe(function() return hgui:call("get_RenderOutputID") end))
        end
        local out = M.out and D[M.out] or M.src_out
        if out then pcall(gui.call, gui, "set_RenderOutputID", out) end
        pcall(go.call, go, "set_DrawSelf", false)
        if M.out then D.gui_saved[gui:get_address()] = { g = gui:add_ref(), id = D[M.out] } end
        slot = { go = go:add_ref(), gui = gui:add_ref(), el = nil, shown = false, txt = nil }
        M.slot = slot
        return slot
    end
    -- (v395) a float icon's layout, remembered whenever the scene has one
    function D.fi_remember()
        if D.fi_src or st.frame < (D.fi_src_check or 0) then return end
        D.fi_src_check = st.frame + 300
        local sc = sdk.call_native_func(sdk.get_native_singleton("via.SceneManager"), sdk.find_type_definition("via.SceneManager"), "get_CurrentScene")
        local l = sc and safe(function() return sc:call("findComponents(System.Type)", sdk.typeof("app.ropeway.gui.FloatIconBehavior")) end)
        if (l and safe(function() return l:call("get_Count") end) or 0) == 0 then return end
        local src = l:call("get_Item", 0):call("get_GameObject")
        local sgui = comp(src, "via.gui.GUI")
        local asset = sgui and safe(function() return sgui:call("get_Asset") end)
        if asset == nil then return end
        D.fi_src = { seg = sgui:call("get_Segment"), asset = asset:add_ref() }
    end
    local function dm_hide(M)
        local slot = M.slot
        if slot and slot.shown then pcall(slot.go.call, slot.go, "set_DrawSelf", false); slot.shown = false end
        -- (one left drawn by the script before a reset: found by name and hidden, once)
        if slot == nil and not M.swept then
            M.swept = true
            pcall(function()
                local sc = sdk.call_native_func(sdk.get_native_singleton("via.SceneManager"), sdk.find_type_definition("via.SceneManager"), "get_CurrentScene")
                local go = sc:call("findGameObject(System.String)", M.name)
                if go then go:call("set_DrawSelf", false) end
            end)
        end
    end
    local function dm_off(M) M.label = nil; dm_hide(M) end
    function D.dm_off() dm_off(DM); dm_off(DM2); dm_off(DMS); dm_off(DMS2) end
    -- M: the viewer's marker; Dn: the downed state (st.p2_down / st.p1_down); who: the downed one's
    -- GameObject; vp: the viewer's camera ViewProjMatrix
    local function mark(M, Dn, who, vp)
        local hp = who and safe(function() return who:call("get_Transform"):call("get_Position") end)
        if vp == nil or hp == nil then dm_off(M); return end
        local a = safe(function() return vp * Vector4f.new(hp.x, hp.y + 0.6, hp.z, 1.0) end)
        if a == nil then dm_off(M); return end
        local w = math.abs(a.w) > 1e-4 and a.w or 1e-4
        local nx, ny = a.x / w, a.y / w
        if a.w <= 0.05 then nx, ny = -nx, -ny; if math.abs(ny) < 0.2 then ny = -1 end end   -- (behind: the edge it's nearest, low)
        local LIM = 0.88
        local off = a.w <= 0.05 or math.abs(nx) > LIM or math.abs(ny) > LIM
        if off then
            local m = math.max(math.abs(nx), math.abs(ny), 1e-3)
            nx, ny = nx / m * LIM, ny / m * LIM
        end
        local X, Y = (nx + 1) * 960, (1 - ny) * 540
        local r = M.half == "full" and { 0, 0, 1, 1 } or (SPLIT_REGIONS[st.split_layout] or SPLIT_REGIONS[1])[M.half]
        local fx, fy = r[1] + (X / 1920) * (r[3] - r[1]), r[2] + (Y / 1080) * (r[4] - r[2])
        if off then
            -- off the viewer's half: no icon, a small arrow at the edge (st.draw_down_overlay)
            dm_hide(M)
            M.label = { off = true, fx = fx, fy = fy, dx = nx, dy = -ny }
            return
        end
        if not Dn.near then
            -- (not close enough to help them up: just the diamond over them, no button)
            dm_hide(M)
            M.label = { off = false, fx = fx, fy = fy, near = false }
            return
        end
        local slot = dm_build(M)
        local el = slot and fi_elements(slot)
        if el == nil then
            -- (no float icon layout to copy yet: the button drawn by the mod in its place)
            M.label = { off = false, fx = fx, fy = fy, near = true, glyph = true }
            return
        end
        local kx, ky = 1, 1
        if M.half ~= "full" then kx, ky = D.hud_k() end
        pcall(function()
            el.view:call("set_Scale", Vector3f.new(kx, ky, 1))
            el.view:call("set_Position", Vector3f.new(0, 0, 0))
            el.main:call("set_Position", Vector3f.new(X / kx, Y / ky, 0))
        end)
        sc_state(el.main, "NEW_CAMERA")
        sc_vis(el.main, true)
        sc_vis(el.new, true); sc_vis(el.old, false); sc_vis(el.sight, false)
        sc_state(el.sub, "BUTTON")
        sc_state(el.rot, "DEFAULT")
        if slot.txt ~= FI_BUTTON and el.icon then
            if pcall(el.icon.call, el.icon, "set_Message", sdk.create_managed_string(FI_BUTTON)) then slot.txt = FI_BUTTON end
        end
        if not slot.shown then pcall(slot.go.call, slot.go, "set_DrawSelf", true); slot.shown = true end
        if st.frame % 30 == 0 and M.out then pcall(slot.gui.call, slot.gui, "set_RenderOutputID", D[M.out]) end
        M.label = { off = false, fx = fx, fy = fy, near = true }
    end
    function D.down_mark()
        if st.frame % 120 == 7 then pcall(D.fi_remember) end
        local base = st.p2_down_mark ~= false and p2c.active and D.on and st.hunk ~= nil
            and not (p2c.menu_open and p2c.menu_open()) and not st.in_cutscene()
        -- player 1 sees downed player 2
        local Dn = st.p2_down
        if base and Dn ~= nil and not Dn.rising then
            local cam = sdk.get_primary_camera()
            mark(DM, Dn, st.hunk, cam and safe(function() return cam:call("get_ViewProjMatrix") end))
        else dm_off(DM) end
        -- player 2 sees downed player 1
        local D1 = st.p1_down
        if base and D1 ~= nil and not D1.rising and D.cam then
            mark(DM2, D1, p1_go(), safe(function() return D.cam:call("get_ViewProjMatrix") end))
        else dm_off(DM2) end
        -- (v395) one screen: both on the one view, with the main camera
        local one = st.p2_down_mark ~= false and not p2c.active and st.hunk ~= nil and not menu.open
            and not st.in_cutscene() and p1_go() ~= nil
        local cam = one and sdk.get_primary_camera()
        local vp = cam and safe(function() return cam:call("get_ViewProjMatrix") end)
        if one and vp and Dn ~= nil and not Dn.rising then mark(DMS, Dn, st.hunk, vp) else dm_off(DMS) end
        -- (not with the AI partner: nobody to show it to, the AI walks over by itself)
        if one and vp and D1 ~= nil and not D1.rising and not ai.active then mark(DMS2, D1, p1_go(), vp) else dm_off(DMS2) end
    end
    -- player 2's camera rebuilt in place: D.update builds a new one this or next frame;
    -- player 1's half, the layout, the HUD pins and the bloom / grade switches stay as they are
    function D.rebuild()
        pcall(D.sweet_off)
        if D.go and valid(D.go) then pcall(function() D.go:call("destroy", D.go) end) end
        D.go, D.cam, D.ro, D.xf, D.parent, D.layout, D.retype, D.post = nil, nil, nil, nil, nil, nil, false, nil
    end
    -- Re-light. The renderer decides which lights, light probes and cubemaps are drawn (their
    -- GameObject DrawSelf, set inside BeginRendering) only when the set of views changes, from
    -- what the views see at that moment. Player 2 walking into another room is no such change,
    -- so that room's lights stayed off (the dark rooms). Rebuilding player 2's camera is one, so
    -- it's done once right after he goes through a door (hidden by that cut). (A throwaway
    -- camera with a render output of its own also worked, but its picture covers the whole
    -- screen for those frames, and shrinking that output hung the game.)
    function D.relight()
        if not D.on or st.hunk == nil or st.frame < (D.relight_ok or 0) then return false end
        D.relight_ok = st.frame + 60
        D.rebuild()
        D.relights = (D.relights or 0) + 1
        return true
    end
    function D.probe_tick() end
    st.relight = D.relight
    -- Lights whose VolumeOccludee is switched on are culled each frame by an occlusion test,
    -- which with two views flips between the views' answers: those lights flickered on and off.
    -- In split screen they're switched off (the renderer then decides those lights with the
    -- others, above) and back on afterwards.
    D.vo_off = {}
    function D.vo_tick()
        if not D.on then
            -- (v427) only once split screen is really over (setting off or player 2 gone), and never
            -- during a cutscene / movie: a cutscene or a menu only takes the view down for a while,
            -- and switching occludees back on while a cutscene loads its set is the v147 / v205
            -- GPU removal (the freeze reported entering a cutscene in split screen, 1.4.2).
            if next(D.vo_off) and ((st.split and st.hunk ~= nil) or st.in_cutscene()) then return end
            if next(D.vo_off) then
                -- (not while the game has stored them away for an event)
                local vm = sdk.get_managed_singleton("app.ropeway.light.VolumeOccludeeManager")
                if vm and safe(function() return vm:get_field("CurrentPhase") end) ~= 0 then return end
                -- only back on where its object is still there and drawn: a room the game unloaded
                -- or put on standby meanwhile keeps it off (switching occludees on for things that
                -- aren't ready is what removed the GPU device in v147)
                for _, c in pairs(D.vo_off) do
                    pcall(function()
                        local go = c:call("get_GameObject")
                        if go and go:call("get_Valid") and go:call("get_Draw") then c:call("set_Enabled", true) end
                    end)
                end
                D.vo_off = {}
            end
            return
        end
        if st.split_lightfix == false or st.split_vofix == false or st.frame < (D.vo_at or 0) then return end
        D.vo_at = st.frame + 60
        local scene = sdk.call_native_func(sdk.get_native_singleton("via.SceneManager"), sdk.find_type_definition("via.SceneManager"), "get_CurrentScene")
        local arr = scene and scene:call("findComponents(System.Type)", sdk.typeof("via.render.VolumeOccludee"))
        local n = 0
        for i = 0, (arr and arr:call("get_Length") or 0) - 1 do
            pcall(function()
                local c = arr:call("GetValue", i)
                if c:call("get_Enabled") then
                    c:call("set_Enabled", false)
                    D.vo_off[c:get_address()] = c:add_ref()
                    n = n + 1
                end
            end)
        end
        if n > 0 then D.relight_at = st.frame + 2 end   -- (their lights decided with the others)
    end
    -- Both cameras get the same "last updated" stamp (+0x48) while rendering (BeginRendering), a
    -- tie that player 2's camera wins. Right after rendering, player 2's is set one below Main
    -- Camera's, so any pick until the next render chooses Main Camera. (Zeroing it before
    -- rendering as well left player 2's half black: the renderer reads it.)
    do
        local function lower()
            if D.cam == nil then return end
            pcall(function()
                local mc = split.ro:call("get_GameObject"):call("getComponent(System.Type)", sdk.typeof("via.Camera"))
                local m = mc:read_dword(0x48)
                if m > 0 then D.cam:write_dword(0x48, m - 1) end
            end)
        end
        pcall(re.on_application_entry, "BeginRendering", lower)
        pcall(re.on_application_entry, "EndRendering", lower)
    end
    function D.off()
        pcall(D.ret_destroy)
        pcall(D.sweet_off)
        pcall(D.unpin_shared)
        if D.graded_off then
            local cc = main_grade()
            if cc then pcall(cc.call, cc, "set_Enabled", true) end
            D.graded_off = false
        end
        if D.bloom_off then
            local mb = main_bloom()
            if mb then pcall(mb.call, mb, "set_Enabled", true) end
            D.bloom_off = false
        end
        if D.go and valid(D.go) then
            pcall(function() D.go:call("destroy", D.go) end)
            D.off_at = st.frame   -- (v427)
        end
        D.go, D.cam, D.ro, D.xf, D.parent, D.layout, D.retype, D.post = nil, nil, nil, nil, nil, nil, false, nil
        if D.on and split.ro then
            pcall(function() split.ro:call("set_RenderOutputID", D.main_id or 31) end)
            split.region = "unknown"
            set_region({ 0, 0, 1, 1 }, "full")
        end
        D.on = false
    end
    -- runs late in the frame (LateUpdateBehavior), right after player 2's pose is updated
    function D.update()
        if not (p2c.active and p2c.pos and p2c.rot and st.hunk) then D.off(); return end
        if not main_camera_parts() then return end
        -- Player 2's camera built in the same frame Main Camera's output is switched to its split
        -- id stayed black (seen every time after a script reset, and after a full restart): a
        -- camera built once the split is up works. So the first one is rebuilt a few frames in.
        if D.fresh_at and st.frame >= D.fresh_at then D.fresh_at = nil; D.rebuild() end
        if D.go == nil or D.parent ~= st.hunk or not valid(D.go) then
            if D.go then D.off() end
            -- (v427) not right after a teardown (building next to destroying is what crashed v226)
            if st.frame - (D.off_at or -1000) < 60 then return end
            if not build() then return end
        end
        local mro = split.ro
        if D.mro ~= mro then   -- new Main Camera (area change): start player 2's view over
            local had = D.mro ~= nil
            split.region = "unknown"; D.mro = mro; D.on = false
            if had then D.off(); return end
        end
        if not D.on then
            local id = safe(function() return mro:call("get_RenderOutputID") end)
            D.main_id = (id ~= nil and id ~= D.P1_OUT) and id or 31
            D.fresh_at = st.frame + 3
        end
        if safe(function() return mro:call("get_RenderOutputID") end) ~= D.P1_OUT then mro:call("set_RenderOutputID", D.P1_OUT) end
        local regions = SPLIT_REGIONS[st.split_layout] or SPLIT_REGIONS[1]
        set_region(regions.p1, "dual" .. tostring(st.split_layout))
        if D.layout ~= st.split_layout then out_rect(D.ro, regions.p2); D.layout = st.split_layout end
        -- world pose -> local under HUNK
        local pxf = st.hunk:call("get_Transform")
        local pp, pr = pxf:call("get_Position"), pxf:call("get_Rotation")
        local sc = safe(function() return pxf:call("get_LocalScale") end)
        local inv = pr:conjugate()
        local lp = inv * Vector3f.new(p2c.pos.x - pp.x, p2c.pos.y - pp.y, p2c.pos.z - pp.z)
        if sc and sc.x > 0.01 and sc.y > 0.01 and sc.z > 0.01 then lp = Vector3f.new(lp.x / sc.x, lp.y / sc.y, lp.z / sc.z) end
        D.xf:call("set_LocalPosition", lp)
        D.xf:call("set_LocalRotation", inv * p2c.rot)
        if D.sweet == nil and st.p2_sweet ~= false and st.frame % 30 == 0 then pcall(D.sweet_build) end
        if D.sweet and st.p2_sweet == false then pcall(D.sweet_off) end
        pcall(D.sweet_sync)
        if st.frame >= (D.post_at or 0) and (D.leon_cam_plain(true) or not D.post_once) then D.post_once = true; D.post_at = st.frame + 10; pcall(D.sync_post) end
        -- Player 2's own lens: the game's FOV setting for player 2's state (normal / aiming),
        -- scaled the way the game scales Leon's (its FOV option and the half's shape): that
        -- scale is Main Camera's FOV over the FOV setting Leon's camera is using right now.
        local mc = split.xf and safe(function() return split.ro:call("get_GameObject"):call("getComponent(System.Type)", sdk.typeof("via.Camera")) end)
        if mc then
            pcall(function()
                local k = D.fov_scale()
                local N, H = p2c.P2CAM.normal, p2c.P2CAM.hold
                local z = p2c.zoom or 0
                D.cam:call("set_FOV", k * (N.fov + (H.fov - N.fov) * z) * (st.p2_fov_pct or 100) / 100)
                D.cam:call("set_NearClipPlane", D.near or mc:call("get_NearClipPlane"))
                D.cam:call("set_FarClipPlane", D.far or mc:call("get_FarClipPlane"))
            end)
        end
        -- The view's "primary camera" is the most recently updated active Game camera (camera
        -- +0x48 = last updated frame), ties going to the camera listed first, which is player 2's
        -- (new cameras go first). Game systems (which room's lights to draw), our HUD and
        -- REFramework use it, so it must stay Main Camera. The view only picks again when the
        -- scene's camera list changes. So:
        -- * player 2's +0x48 is set one below Main Camera's after each render (hooks next to
        --   D.rebuild), so Main Camera wins every pick on that field;
        -- * if player 2's camera is primary anyway, it is taken out of the running for a moment
        --   (a non-Game CameraType), which makes the view pick again, then put back.
        -- Before that, the retype changed the camera list, the next pick was a tie again,
        -- player 2 won again: a retype every frame, player 2's half black (its Scene layer goes
        -- while it's not a Game camera) and player 1's room lights wrong.
        D.mv = D.mv or sdk.call_native_func(sdk.get_native_singleton("via.SceneManager"), sdk.find_type_definition("via.SceneManager"), "get_MainView")
        local pc = safe(function() return D.mv:call("get_PrimaryCamera") end)
        if pc and pc:get_address() == D.cam:get_address() then
            D.retypes = (D.retypes or 0) + 1
            D.pick_hits = D.pick_hits or {}
            table.insert(D.pick_hits, st.frame)
            while #D.pick_hits > 0 and st.frame - D.pick_hits[1] > 120 do table.remove(D.pick_hits, 1) end
            if #D.pick_hits <= 3 then
                pcall(function()
                    D.cam:write_dword(0x48, 0)
                    D.cam:call("set_CameraType", 6)
                    D.mv:call("get_PrimaryCamera")
                    D.cam:call("set_CameraType", 0)
                    D.cam:write_dword(0x48, 0)
                    D.mv:call("get_PrimaryCamera")
                end)
            end
        end
        if st.frame >= (D.pin_at or 0) then D.pin_at = st.frame + 120; pcall(D.pin_shared) end
        local menu_up = p2c.menu_open()
        D.box_busy = menu_up and safe(function() return sdk.get_managed_singleton("app.ropeway.gui.GUIMaster"):call("isBusyItemBox") end) == true
        pcall(D.menu_mirror, st.split_menu_mirror ~= false and menu_up)
        pcall(D.full_split, st.split_menu_mirror ~= false and st.split_menu_full ~= false and menu_up)
        pcall(D.save_fit, true)
        if st.frame % 4 == 0 then pcall(D.pin_lights) end
        pcall(D.ret_update)
        if st.frame % 10 == 0 then pcall(D.hud_apply) end
        pcall(D.guide_follow)
        D.on = true
    end
end)()

-- HUNK's crosshair requests go to player 2's own copy of the crosshair while split screen is on
;(function()
    local td = sdk.find_type_definition("app.ropeway.gui.ReticleBehavior")
    if td == nil then return end
    local function b(a) return (sdk.to_int64(a) & 1) == 1 end
    local function i32(a) return sdk.to_int64(a) & 0xFFFFFFFF end
    local CONV = {
        draw = function(a) return { i32(a[3]), sdk.to_float(a[4]) } end,
        drawSparkShot = function(a) return { i32(a[3]), b(a[4]), b(a[5]), b(a[6]), b(a[7]), sdk.to_float(a[8]) } end,
        drawSexyGun = function(a) return { i32(a[3]), b(a[4]), b(a[5]), b(a[6]), b(a[7]), sdk.to_float(a[8]), b(a[9]) } end,
    }
    for _, m in ipairs(td:get_methods()) do
        local name = m:get_name()
        local conv = CONV[name]
        if conv then
            sdk.hook(m, function(args)
                local D = st.dual
                local rb = D and D.on and D.ret_rb
                -- shared screen: player 2's aim never shows the game's crosshair (it sits in the middle
                -- of player 1's view, and showed for a moment as player 2 started aiming, before Free
                -- Aim had taken over); player 2 has the laser
                if current_owner() == OWN_HUNK and not (D and D.on) then return sdk.PreHookResult.SKIP_ORIGINAL end
                if not rb or current_owner() ~= OWN_HUNK then return end   -- (false when split is off)
                local this = sdk.to_managed_object(args[2])
                if this == nil or this:get_address() == rb:get_address() then return end
                local ok, list = pcall(conv, args)
                if ok then pcall(function() rb:call(name, table.unpack(list)) end) end
                return sdk.PreHookResult.SKIP_ORIGINAL
            end, function(r) return r end)
        end
    end
end)()

-- Lights the game dims by camera distance / facing (app.ropeway.DistanceAndLookAwayLightController,
-- for example some lamps by doors) only knew player 1's camera. In split screen each one is
-- worked out for both players and the brighter result is used: a light either player is
-- facing stays on.
;(function()
    local td = sdk.find_type_definition("app.ropeway.DistanceAndLookAwayLightController")
    if td == nil then return end
    local LA = { cam2 = false }
    local function active() return st.dual and st.dual.on and p2c.active and p2c.yaw ~= nil and st.split_lightfix ~= false end
    local gy, cr = td:get_method("getCameraYaw"), td:get_method("calcIntensityRate")
    if gy == nil or cr == nil then return end
    sdk.hook(gy, function() end, function(r)
        if LA.cam2 then return sdk.float_to_ptr(p2c.yaw) end
        return r
    end)
    sdk.hook(cr, function(args)
        if not LA.cam2 then LA.this = sdk.to_managed_object(args[2]) end
    end, function(r)
        if LA.cam2 or not active() or LA.this == nil then return r end
        local this = LA.this
        LA.this, LA.cam2 = nil, true
        local ok, r2 = pcall(this.call, this, "calcIntensityRate")
        LA.cam2 = false
        if ok and type(r2) == "number" and r2 > sdk.to_float(r) then return sdk.float_to_ptr(r2) end
        return r
    end)
end)()

-- crosshairs in the middle of each half while that player aims
local function draw_split_reticles()
    if not p2c.active then return end
    local ds = imgui.get_display_size()
    local regions = SPLIT_REGIONS[st.split_layout] or SPLIT_REGIONS[1]
    local function reticle(r, col)
        local cx = (r[1] + r[3]) / 2 * ds.x
        local cy = (r[2] + r[4]) / 2 * ds.y
        local k = ds.y / 1080
        draw.outline_circle(cx, cy, 14 * k, 0x90000000, 24)
        draw.outline_circle(cx, cy, 13 * k, col, 24)
        draw.filled_circle(cx, cy, 2.2 * k, col, 12)
    end
    -- player 2's crosshair; player 1 has the game's own (its HUD draws in player 1's half)
    if (hunk_is_aiming() or hunk_sub_holding()) and not (st.dual and st.dual.on and st.dual.ret_rb) then reticle(regions.p2, 0xE0FFFFFF) end
    -- divider
    local r = regions.p2
    if st.split_layout == 2 then
        draw.filled_rect(0, r[2] * ds.y - 1, ds.x, 2, 0xFF000000)
    else
        draw.filled_rect(r[1] * ds.x - 1, 0, 2, ds.y, 0xFF000000)
    end
end

-- Player 1 at the typewriter (the save screen fitted on his half: st.dual.save, see
-- D.save_fit): player 2's half dimmed, with a note in its middle. The game doesn't pause for it.
-- The inventory / map / files screens fitted into player 1's half (D.INV_FIT, fs_tick): the
-- layout covers only the middle band of the half (its 16:9 shape in a narrow half), so the
-- strips above and below it are darkened like the screen's own backdrop.
function st.draw_inv_strips()
    local D = st.dual
    if not (D and D.on and D.inv_up and not D.box_busy and st.split_inv_fit ~= false) then return end
    if st.split_inv_portrait ~= false then return end   -- (the portrait layout fills the half)
    local ds = imgui.get_display_size()
    local r = (p2c.regions[st.split_layout] or p2c.regions[1]).p1
    local x0, y0, x1, y1 = r[1] * ds.x, r[2] * ds.y, r[3] * ds.x, r[4] * ds.y
    local k = D.INV_K or 0.5
    local h = (y1 - y0) * (1 - k) / 2
    draw.filled_rect(x0, y0, x1 - x0, h, 0x80000000)
    draw.filled_rect(x0, y1 - h, x1 - x0, h, 0x80000000)
end

-- the downed marker's drawn part: a red diamond under the icon (the AI partner's order-spot
-- diamond, in the DOWNED red), or off her half a small red arrow at its edge pointing to him
function st.draw_down_mark(x, y, m)
    local k = imgui.get_display_size().y / 1080
    local RED, EDGE = 0xE05050D0, 0x90000000
    if m.off then
        local l = math.sqrt(m.dx * m.dx + m.dy * m.dy)
        if l < 1e-3 then return end
        local dx, dy = m.dx / l, m.dy / l
        local qx, qy = -dy, dx
        local s = 15 * k
        local tipx, tipy = x + dx * s, y + dy * s
        local lx, ly = x - dx * s * 0.6 + qx * s * 0.8, y - dy * s * 0.6 + qy * s * 0.8
        local rx, ry = x - dx * s * 0.6 - qx * s * 0.8, y - dy * s * 0.6 - qy * s * 0.8
        local nx, ny = x - dx * s * 0.15, y - dy * s * 0.15
        local o = 2.5 * k
        draw.filled_quad(tipx + dx * o, tipy + dy * o, lx - dx * o + qx * o, ly - dy * o + qy * o, nx - dx * o, ny - dy * o, rx - dx * o - qx * o, ry - dy * o - qy * o, EDGE)
        draw.filled_quad(tipx, tipy, lx, ly, nx, ny, nx, ny, RED)
        draw.filled_quad(tipx, tipy, nx, ny, rx, ry, rx, ry, RED)
        return
    end
    if m.glyph then
        -- (the game's button icon couldn't be copied: a ring with the button's name)
        draw.filled_circle(x, y, 17 * k, 0xB0000000, 24)
        draw.outline_circle(x, y, 17 * k, 0xFFE6E6E6, 24)
        local t = st.p1_action_label()
        local ok, sz = pcall(imgui.calc_text_size, t)
        local w = ok and sz and sz.x or 8 * #t
        draw.text(t, x - w / 2, y - 7 * k, 0xFFFFFFFF)
        return
    end
    if m.near then return end   -- (at his side: the button and the prompt say it)
    local cy = y
    draw.filled_circle(x, cy, 9 * k, EDGE, 4)
    draw.filled_circle(x, cy, 6 * k, RED, 4)
end

-- player 2 downed: his half dimmed with what's happened; player 1 told how to help him up
function st.draw_down_overlay(labels)
    local D, D1 = st.p2_down, st.p1_down
    local d2 = D ~= nil and not D.rising
    local d1 = D1 ~= nil and not D1.rising
    if not d2 and not d1 then return end
    local ds = imgui.get_display_size()
    local sz = math.floor(32 * ds.y / 1080)
    if p2c.active then
        local reg = p2c.regions[st.split_layout] or p2c.regions[1]
        local function dim(r, who_helps, can_heal)
            local x0, y0, x1, y1 = r[1] * ds.x, r[2] * ds.y, r[3] * ds.x, r[4] * ds.y
            draw.filled_rect(x0, y0, x1 - x0, y1 - y0, 0x70300000)
            labels[#labels + 1] = { x = (x0 + x1) / 2, y = (y0 + y1) / 2 - sz, text = "DOWNED", size = math.floor(sz * 1.6), col = 0xFF5050D0 }
            labels[#labels + 1] = { x = (x0 + x1) / 2, y = (y0 + y1) / 2 + sz, text = who_helps .. " can help you up" .. (can_heal and ", or heal yourself" or ""), size = sz, col = 0xFFE6E6E6 }
        end
        -- (his inventory open / her menus up: their half left clear)
        -- (Rookie has no inventory: only player 1 gets him up)
        if d2 and not (st.ig and st.ig.open) then dim(reg.p2, st.p1_name(), not st.infinite_ammo) end
        if d1 and not (p2c.menu_open and p2c.menu_open()) then dim(reg.p1, st.p2_name(), true) end
        -- each one's marker of the other (st.dual.down_mark)
        for _, M in ipairs({ st.dual and st.dual.dm, st.dual and st.dual.dm2 }) do
            local DL = M and M.label
            if DL then pcall(st.draw_down_mark, DL.fx * ds.x, DL.fy * ds.y, DL) end
        end
    else
        -- (v395) one screen, as split screen does it: the markers (st.dual.down_mark: the game's
        -- button over the downed one once the other is at their side, else a red diamond, and a
        -- red arrow at the screen edge when they're off it). The downed one's own message: player 1
        -- down dims the screen with DOWNED (it's her view, as her half in split screen); player 2
        -- down (a person, not the AI partner) gets the same two lines lower down, undimmed, since
        -- player 1 is still playing on it.
        for _, M in ipairs({ st.dual and st.dual.dms, st.dual and st.dual.dms2 }) do
            local DL = M and M.label
            if DL then pcall(st.draw_down_mark, DL.fx * ds.x, DL.fy * ds.y, DL) end
        end
        if d1 and not menu.open then
            draw.filled_rect(0, 0, ds.x, ds.y, 0x70300000)
            labels[#labels + 1] = { x = ds.x / 2, y = ds.y / 2 - sz, text = "DOWNED", size = math.floor(sz * 1.6), col = 0xFF5050D0 }
            labels[#labels + 1] = { x = ds.x / 2, y = ds.y / 2 + sz, text = st.p2_name() .. " can help you up", size = sz, col = 0xFFE6E6E6 }
        elseif d2 and not ai.active and not (st.ig and st.ig.open) then
            labels[#labels + 1] = { x = ds.x / 2, y = ds.y * 0.70, text = st.p2_name() .. " DOWNED", size = math.floor(sz * 1.2), col = 0xFF5050D0 }
            labels[#labels + 1] = { x = ds.x / 2, y = ds.y * 0.70 + sz * 1.4, text = st.p1_name() .. " can help you up" .. (not st.infinite_ammo and ", or heal yourself" or ""),
                size = math.floor(sz * 0.8), col = 0xFFE6E6E6 }
        end
    end
end

function st.draw_save_overlay(labels)
    local S = st.dual and st.dual.save
    if not (S and S.fit) then return end
    local ds = imgui.get_display_size()
    local r = (p2c.regions[st.split_layout] or p2c.regions[1]).p2
    local x0, y0, x1, y1 = r[1] * ds.x, r[2] * ds.y, r[3] * ds.x, r[4] * ds.y
    draw.filled_rect(x0, y0, x1 - x0, y1 - y0, 0x8C000000)
    labels[#labels + 1] = { x = (x0 + x1) / 2, y = (y0 + y1) / 2, text = "Player 1 is saving the game",
        size = math.floor(32 * ds.y / 1080), col = 0xFFE6E6E6 }
end

-- Experimental: AI partner ---------------------------------------------------------------
-- HUNK plays himself: he walks Leon's trail, shoots the nearest enemy he can see and uses
-- his heal / resupply when Leon needs them. He "presses" buttons through the same input
-- hooks a second controller would use (ai_route), so the game animates everything itself.

local KIND = { MOVE = 1, JOG0 = 8, JOG1 = 16, HOLD = 64, ATTACK = 256 }
local AI_AUTO = { [21] = true, [23] = true, [43] = true, [50] = true }   -- hold the trigger
-- frames between shots for semi-automatic guns (at 60 fps)
local AI_PERIOD = { [11] = 40, [2] = 30, [9] = 45, [31] = 45, [4] = 30, [42] = 70, [44] = 50, [45] = 90, [49] = 90 }
local AI_JOINTS = { "spine_2", "Spine_2", "spine_1", "Spine_1", "COG", "Hip" }

ai.state, ai.trail, ai.target = "off", {}, nil
ai.aim_t, ai.fire_n, ai.next_scan, ai.moving = 0, 0, 0, false
ai.stuck = { t = 0, pos = nil }
ai.next_tp, ai.next_spawn = 0, os.clock() + 3
ai.joint_cache = {}

local function v3(p) return { p.x, p.y, p.z } end
local function dist2(a, b) return (a[1] - b[1]) ^ 2 + (a[3] - b[3]) ^ 2 end

local function ai_stick(x, y)
    local s = st.live_stick(ai, "stick")
    if s == nil then return end
    local v = Vector2f.new(x, y)
    s:call("update", v, v)
end

-- points to shoot at on an enemy: chest, then head, then hips (whichever HUNK can see)
local AI_AIM_JOINTS = { { "spine_2", "Spine_2", "spine_1" }, { "head", "Head" }, { "COG", "hips", "Hip" } }
local function enemy_joints(go)
    local addr = go:get_address()
    local js = ai.joint_cache[addr]
    if js == nil then
        js = {}
        local xf = go:call("get_Transform")
        for i, names in ipairs(AI_AIM_JOINTS) do
            for _, n in ipairs(names) do
                local jj = safe(function() return xf:call("getJointByName", n) end)
                if jj then js[i] = jj; break end
            end
        end
        ai.joint_cache[addr] = js
    end
    return js
end
-- aim point number k (1 chest, 2 head, 3 hips) and whether the enemy is down
local function enemy_aim_point(go, k)
    local js = enemy_joints(go)
    local ep = go:call("get_Transform"):call("get_Position")
    local chest = js[1] and safe(function() return js[1]:call("get_Position") end)
    local down = chest ~= nil and chest.y - ep.y < 0.7   -- chest near the floor: knocked down or crawling
    local j = js[k or 1]
    local p = j and safe(function() return j:call("get_Position") end) or chest
    if p then return v3(p), down end
    return { ep.x, ep.y + 1.1, ep.z }, false
end

-- alive and damageable (scripted set pieces are flagged NoDamage)
local function enemy_valid(ctrl)
    if safe(function() return ctrl:call("get_IsLive") end) == false then return false end
    if safe(function() return ctrl:call("get_NoDamage") end) == true then return false end
    return true
end

local function clear_line(a, b)
    local ok, hit = pcall(cast_ray, Vector3f.new(a[1], a[2], a[3]), Vector3f.new(b[1], b[2], b[3]))
    if not ok or hit == nil then return true end
    local full = math.sqrt((b[1] - a[1]) ^ 2 + (b[2] - a[2]) ^ 2 + (b[3] - a[3]) ^ 2)
    local part = math.sqrt((hit.x - a[1]) ^ 2 + (hit.y - a[2]) ^ 2 + (hit.z - a[3]) ^ 2)
    return part >= full - 0.5   -- the wall is at (or just behind) the target itself
end

-- which enemy to shoot: the biggest threat HUNK can see. Enemies close to Leon come
-- first (one grabbing him is top priority), then ones close to HUNK; the current target
-- gets a bonus so he doesn't flick between two similar ones. An enemy hidden behind a
-- door frame or shelf can still be the pick if a short step to the side would clear it:
-- that comes back as ai.reposition.
local AI_EYE = 1.4   -- shots leave from HUNK's chest (see the generateShell hook)
local function visible_point(from, go)
    for k = 1, 3 do
        local p = enemy_aim_point(go, k)
        if clear_line(from, p) then return k, p end
    end
    return nil
end
local function ai_pick_target(hp, lp)
    local em = sdk.get_managed_singleton("app.ropeway.EnemyManager")
    local list = em and safe(function() return em:call("get_ActiveEnemyList") end)
    local n = list and (safe(function() return list:call("get_Count") end) or 0) or 0
    local eye = { hp[1], hp[2] + AI_EYE, hp[3] }
    ai.cands = {}
    local cands = {}
    for i = 0, n - 1 do
        local ctrl = safe(function() return list:call("get_Item", i) end)
        local go = ctrl and safe(function() return ctrl:call("get_GameObject") end)
        local hpc = go and comp(go, "app.ropeway.HitPointController")
        local hpv = hpc and safe(function() return hpc:call("get_CurrentHitPoint") end) or 0
        local c = { name = go and safe(function() return go:call("get_Name") end), hp = hpv }
        ai.cands[#ai.cands + 1] = c
        if hpv > 0 and enemy_valid(ctrl) then
            local p, down = enemy_aim_point(go, 1)
            local dh = math.sqrt((p[1] - eye[1]) ^ 2 + (p[2] - eye[2]) ^ 2 + (p[3] - eye[3]) ^ 2)
            local dl = math.sqrt(dist2(p, lp))
            local keep = ai.target ~= nil and ai.target.go == go
            c.dh, c.dl = dh, dl
            if dh < st.ai_range * (keep and 1.25 or 1) and math.abs(p[2] - eye[2]) < 4 then
                local s = math.min(dh, dl * 0.8)
                if down then s = s + 5 end            -- standing enemies first
                if dl < 1.5 then s = 0 end            -- on top of Leon (grab)
                if keep then s = s * 0.7 end
                cands[#cands + 1] = { go = go, ctrl = ctrl, down = down, dist = dh, s = s, c = c }
            end
        end
    end
    -- the closest standing enemy (for backing off / the knife), and (v390) the closest one
    -- down on the floor at his feet (crawling or knocked down: knifed)
    ai.close, ai.close_down = nil, nil
    for _, t in ipairs(cands) do
        local p = enemy_aim_point(t.go, 1)
        local d = math.sqrt(dist2(p, hp))
        if not t.down then
            if d < 3 and (ai.close == nil or d < ai.close.d) then ai.close = { go = t.go, ctrl = t.ctrl, pos = p, d = d } end
        elseif d < 1.8 and (ai.close_down == nil or d < ai.close_down.d) then
            ai.close_down = { go = t.go, ctrl = t.ctrl, pos = p, d = d, down = true }
        end
    end
    table.sort(cands, function(x, y) return x.s < y.s end)
    ai.reposition = nil
    for i, t in ipairs(cands) do
        if i > 4 then break end   -- rays are not free
        local k, p
        if (ai.blocked[t.go:get_address()] or 0) <= st.frame then k, p = visible_point(eye, t.go) end
        t.c.los = k ~= nil
        if k then
            t.k, t.pos, t.c = k, p, nil
            return t
        end
    end
    -- nothing in sight: would a step left, right or forward give a shot at the top threat?
    local t = cands[1]
    if t and t.dist < 10 then
        local p = enemy_aim_point(t.go, 1)
        local dx, dz = p[1] - hp[1], p[3] - hp[3]
        local l = math.max(0.01, math.sqrt(dx * dx + dz * dz))
        dx, dz = dx / l, dz / l
        for _, o in ipairs({ { -dz * 1.2, dx * 1.2 }, { dz * 1.2, -dx * 1.2 }, { dx * 1.2, dz * 1.2 }, { -dz * 2.2, dx * 2.2 }, { dz * 2.2, -dx * 2.2 } }) do
            local spot = { hp[1] + o[1], hp[2] + AI_EYE, hp[3] + o[2] }
            if clear_line(eye, spot) and visible_point(spot, t.go) then
                ai.reposition = { spot[1], hp[2], spot[3], until_frame = st.frame + 90 }
                break
            end
        end
    end
    return nil
end

-- Leon's footsteps: HUNK walks the path Leon took, which keeps him out of walls
local function update_trail(lp)
    local t = ai.trail
    local last = t[#t]
    if last and dist2(last, lp) > 25 then ai.trail = {}; t = ai.trail; last = nil end   -- door / warp
    if last == nil or dist2(last, lp) > 0.36 then
        t[#t + 1] = lp
        if #t > 80 then table.remove(t, 1) end
    end
end

-- where to walk next: the trail point after the one HUNK is nearest to
local function next_waypoint(hp, lp)
    local t = ai.trail
    local near_i, near_d = nil, 1e9
    for i, p in ipairs(t) do
        local d = dist2(p, hp)
        if d < near_d then near_i, near_d = i, d end
    end
    if near_i and near_d < 9 then
        for _ = 1, near_i - 1 do table.remove(t, 1) end
        while #t > 1 and dist2(t[1], hp) < 0.5 do table.remove(t, 1) end
        if t[1] then return t[1] end
    end
    return lp   -- off the trail: head straight for Leon
end

-- The game's own navigation mesh (what the zombies walk on): a NavigationSurface on
-- player 2 answers "how do I get from here to there" with a list of points that go round
-- furniture, through doorways and up and down stairs.
ai.nav = { comp = nil, owner = nil, path = nil, goal = nil, frame = -1000, idx = 1 }
function ai.nav_surface()
    local n = ai.nav
    local addr = st.hunk and st.hunk:get_address()
    if n.owner ~= addr then
        n.comp, n.owner, n.path = nil, addr, nil
        if addr then
            local c = comp(st.hunk, "via.navigation.NavigationSurface")
            if c == nil then
                c = safe(function() return st.hunk:call("createComponent(System.Type)", sdk.typeof("via.navigation.NavigationSurface")) end)
            end
            if c then
                safe(function() c:call("set_MapName", "") end)   -- "": whatever map covers this area
                n.comp = c:add_ref()
            end
        end
    end
    return n.comp
end
-- (NonRT-13) On Non-RT queryPathSync never finds a route (false for every start / goal, the
-- enemies' own surfaces too), and a surface left on MapName "" finds no route either. There the
-- surface is used as the game uses it for enemies: MapName set to the map the area's enemies
-- (any loaded Navigation with a valid map) use, the goal given with set_TargetPos + start(),
-- and the route read back node by node: queryNextLink() -> LinkInfo.queryToNode() ->
-- NodeInfo.get_Pos(), then queryNextLink(that node)... LinkInfo / NodeInfo are native objects
-- the TDB66 REFramework can't hand to Lua (its error names their address), so they're called
-- with sdk.call_native_func on that address. Auto-follow / auto-modify are off: it only plans.
do
    local LT = sdk.find_type_definition("via.navigation.map.LinkInfo")
    local NT = sdk.find_type_definition("via.navigation.map.NodeInfo")
    local NAV = sdk.typeof("via.navigation.Navigation")
    local function raw_of(err) return tonumber(tostring(err):match("sol_lua_push: (%d+) is not")) end
    local function native(raw, td, name, ...)
        local args = { ... }
        local ok, v = pcall(function() return sdk.call_native_func(sdk.to_ptr(raw), td, name, table.unpack(args)) end)
        if ok then return v, nil end
        return nil, raw_of(v)
    end
    -- the map name the area's own navigating characters use (looked up every 5 s)
    function ai.nrt_map(ns)
        local n = ai.nav
        if n.map_at and st.frame - n.map_at < 300 then return n.map_name end
        n.map_at = st.frame
        local counts, best, bn = {}, nil, 0
        pcall(function()
            local sc = sdk.call_native_func(sdk.get_native_singleton("via.SceneManager"), sdk.find_type_definition("via.SceneManager"), "get_CurrentScene")
            local arr = sc:call("findComponents(System.Type)", NAV)
            for i = 0, arr:call("get_Count") - 1 do
                local c = arr:call("get_Item", i)
                if c and c:get_address() ~= ns:get_address() then
                    local m = c:call("get_MapName")
                    if m and m ~= "" and c:call("hasValidMap") then counts[m] = (counts[m] or 0) + 1 end
                end
            end
        end)
        for m, k in pairs(counts) do if k > bn then best, bn = m, k end end
        if best then n.map_name = best end
        return n.map_name
    end
    function ai.nav_query_nrt(hp, goal)
        local ns = ai.nav_surface()
        if ns == nil then return nil end
        local n = ai.nav
        if not n.nrt_setup then
            pcall(function() ns:call("set_EnableAutoFollow", false) end)
            pcall(function() ns:call("set_EnableAutoModify", false) end)
            n.nrt_setup = true
        end
        local map = ai.nrt_map(ns)
        if map and map ~= n.cur_map then
            pcall(function() ns:call("set_MapName", map) end)
            n.cur_map, n.tgt = map, nil
        end
        if n.cur_map == nil then return nil end
        if n.tgt == nil or dist2(n.tgt, goal) > 0.25 or math.abs(n.tgt[2] - goal[2]) > 0.5 or st.frame - (n.tgt_frame or 0) > 60 then
            pcall(function()
                ns:call("set_TargetPos", Vector3f.new(goal[1], goal[2], goal[3]))
                ns:call("start()")
            end)
            n.tgt, n.tgt_frame = { goal[1], goal[2], goal[3] }, st.frame
        end
        local pts = {}
        local ok, e = pcall(function() return ns:call("queryNextLink()") end)
        local lraw = (not ok) and raw_of(e) or nil
        for _ = 1, 48 do
            if not lraw then break end
            local _, nraw = native(lraw, LT, "queryToNode")
            if type(nraw) ~= "number" then break end
            local p = native(nraw, NT, "get_Pos")
            if p then pts[#pts + 1] = { p.x, p.y, p.z } end
            local ok3, e3 = pcall(function() return ns:call("queryNextLink(via.navigation.map.NodeInfo)", sdk.to_ptr(nraw)) end)
            lraw = (not ok3) and raw_of(e3) or nil
        end
        -- (no links: start and goal on one stretch of mesh, or no route: the old steering walks it)
        if #pts == 0 then return nil end
        pts[#pts + 1] = { goal[1], goal[2], goal[3] }
        return pts
    end
end
-- the path's points (feet positions) from hp to goal, or nil when the mesh has no route
function ai.nav_query(hp, goal)
    if st.NON_RT then return ai.nav_query_nrt(hp, goal) end
    local ns = ai.nav_surface()
    if ns == nil then return nil end
    local pts
    pcall(function()
        local rep = sdk.create_instance("via.navigation.PathQueryReport")
        if rep == nil then return end
        rep = rep:add_ref()
        local ok = ns:call("queryPathSync(via.vec3, via.vec3, via.navigation.PathQueryReport)",
            Vector3f.new(hp[1], hp[2], hp[3]), Vector3f.new(goal[1], goal[2], goal[3]), rep)
        if ok and rep:call("get_Exist") then
            local pi = rep:call("get_PathInfo")
            pi:call("createTraceLine")
            local cnt = pi:call("get_PathPointCount") or 0
            pts = {}
            for i = 0, cnt - 1 do
                local p = pi:call("getPortalPos", i)
                if p then pts[#pts + 1] = { p.x, p.y, p.z } end
            end
            if #pts == 0 then pts = nil end
        end
        rep:release()
    end)
    return pts
end
-- next point to head for on the way to goal (re-planned when the goal moves or every
-- second); nil when there's no route (then the old steering takes over)
function ai.nav_next(hp, goal)
    local n = ai.nav
    local moved = n.goal == nil or dist2(n.goal, goal) > 1.0 or math.abs(n.goal[2] - goal[2]) > 1.0
    if moved or st.frame - n.frame > 60 or n.path == nil then
        if st.frame - n.frame >= 10 or moved then
            n.path = ai.nav_query(hp, goal)
            n.goal, n.frame, n.idx = goal, st.frame, 1
        end
    end
    local path = n.path
    if path == nil then return nil end
    -- skip points already reached (or passed: the next one is closer)
    while n.idx < #path do
        local p = path[n.idx]
        local close = dist2(p, hp) < 0.36 and math.abs(p[2] - hp[2]) < 1.2
        local passed = dist2(path[n.idx + 1], hp) < dist2(p, path[n.idx + 1])
        if close or passed then n.idx = n.idx + 1 else break end
    end
    return path[n.idx]
end

local function ai_walk_to(hp, goal, run, slow)
    local cs = sdk.get_managed_singleton("app.ropeway.camera.CameraSystem")
    local d = safe(function() return cs:call("get_CameraDirection") end)
    if d == nil then ai_stick(0, 0); return end
    local dx, dz = goal[1] - hp[1], goal[3] - hp[3]
    -- further than a couple of steps: follow the navigation mesh's route
    local routed = false
    if dx * dx + dz * dz > 2.25 or math.abs(goal[2] - hp[2]) > 0.8 then
        local wp = ai.nav_next(hp, goal)
        if wp then
            dx, dz = wp[1] - hp[1], wp[3] - hp[3]
            routed = true
            ai.nav_used = st.frame
        end
    end
    -- steer round walls and furniture (and away from drops) instead of walking into them
    if not routed and dx * dx + dz * dz > 0.5 and ai.steer_dir then
        local sx, sz = ai.steer_dir(hp, dx, dz)
        if sx then dx, dz = sx, sz end
    end
    -- stick angle = world direction yaw minus Leon's camera yaw (the game turns it back)
    local a = math.atan(-dx, -dz) - math.atan(-d.x, -d.z)
    local mag = run and 1 or (slow and 0.45 or 0.75)
    ai_stick(-math.sin(a) * mag, math.cos(a) * mag)
    ai.keys[KIND.MOVE] = true
    if run then ai.keys[KIND.JOG0] = true; ai.keys[KIND.JOG1] = true end
    ai.moving = true
end

local function ai_support(lgo)
    if st.bb_on and st.bb_on() then return end   -- (v407 Babysitting: Sherry doesn't heal / refill)
    local now = os.clock()
    if st.ai_heal_pct > 0 and now >= st.next_heal then
        local hpc = comp(lgo, "app.ropeway.HitPointController")
        local cur = hpc and safe(function() return hpc:call("get_CurrentHitPoint") end)
        local max = hpc and safe(function() return hpc:call("get_DefaultHitPoint") end)
        if cur and max and max > 0 and cur > 0 and cur * 100 < max * st.ai_heal_pct then pcall(heal_p1) end
    end
    if st.ai_resupply and now >= st.next_resupply then
        local inv = comp(lgo, "app.ropeway.survivor.Inventory")
        local main = inv and safe(function() return inv:call("get_MainSlot") end)
        if main and safe(function() return main:call("get_IsWeapon") end) then
            local max, n = safe(function() return main:call("get_MaxNumber") end), safe(function() return main:call("get_Number") end)
            if max and n and max > 0 and n == 0 then pcall(resupply_p1) end
        end
    end
end

local function ai_reset()
    ai.keys, ai.prev, ai.aim_pos, ai.target = {}, {}, nil, nil
    ai.aim_t, ai.moving = 0, false
    if ai.stick then pcall(ai_stick, 0, 0) end
end

-- Movement helpers ----------------------------------------------------------------------
-- first clear direction close to the wanted one (dx, dz): a step ahead must have no wall at
-- knee or chest height and floor under it. nil when boxed in.
function ai.steer_dir(hp, dx, dz)
    local l = math.sqrt(dx * dx + dz * dz)
    if l < 0.01 then return nil end
    dx, dz = dx / l, dz / l
    local c = ai.steer_cache
    if c and st.frame - c.frame < 4 and c.dx * dx + c.dz * dz > 0.97 then return c.rx, c.rz end
    local rx, rz
    for _, deg in ipairs({ 0, 25, -25, 50, -50, 80, -80, 115, -115 }) do
        local r = math.rad(deg)
        local cx, cz = dx * math.cos(r) - dz * math.sin(r), dx * math.sin(r) + dz * math.cos(r)
        local ax, az = hp[1] + cx * 1.0, hp[3] + cz * 1.0
        -- floor a step ahead, up or down a stair flight too (not a drop or a wall)
        local fy
        pcall(function()
            local hit = cast_ray(Vector3f.new(hp[1] + cx * 0.8, hp[2] + 1.0, hp[3] + cz * 0.8), Vector3f.new(hp[1] + cx * 0.8, hp[2] - 1.0, hp[3] + cz * 0.8))
            if hit and math.abs(hit.y - hp[2]) < 0.75 then fy = hit.y end
        end)
        local ay = fy or hp[2]
        if fy and clear_line({ hp[1], hp[2] + 0.6, hp[3] }, { ax, ay + 0.6, az })
            and clear_line({ hp[1], hp[2] + 1.3, hp[3] }, { ax, ay + 1.3, az }) then
            rx, rz = cx, cz
            break
        end
    end
    ai.steer_cache = { frame = st.frame, dx = dx, dz = dz, rx = rx, rz = rz }
    return rx, rz
end

-- is a spot (feet position) out of player 1's view: off screen or behind a wall?
function ai.offscreen(p)
    local sp = safe(function() return draw.world_to_screen(Vector3f.new(p[1], p[2] + 1.0, p[3])) end)
    local ds = imgui.get_display_size()
    if sp == nil or sp.x < -40 or sp.y < -40 or sp.x > ds.x + 40 or sp.y > ds.y + 40 then return true end
    local o = ai.p1_ray and ai.p1_ray()
    return o ~= nil and not clear_line(o, { p[1], p[2] + 1.0, p[3] })
end

-- put player 2 somewhere along Leon's path that Leon can't see, so he walks back into view
-- instead of popping up beside him
function ai.warp_offscreen(lp)
    local t = ai.trail
    for i = #t, 1, -1 do
        local p = t[i]
        local d = math.sqrt(dist2(p, lp))
        if d >= 3.5 and d <= 12 and math.abs(p[2] - lp[2]) < 2 and ai.offscreen(p) then
            warp_hunk(Vector3f.new(p[1], p[2], p[3]), nil)
            for _ = 1, i - 1 do table.remove(t, 1) end
            return true
        end
    end
    return false
end

-- Orders from player 1 (command wheel) ----------------------------------------------
function ai.say(text) if st.ai_callouts then toast(st.p2_name() .. ": " .. text) end end

-- player 1's crosshair ray (always Leon's own camera)
function ai.p1_ray()
    local cs = sdk.get_managed_singleton("app.ropeway.camera.CameraSystem")
    local p = cs and safe(function() return cs:call("get_CameraPosition") end)
    local d = cs and safe(function() return cs:call("get_CameraDirection") end)
    if p == nil or d == nil then return nil end
    return { p.x, p.y, p.z }, { d.x, d.y, d.z }
end

-- the living enemy under player 1's crosshair, if any
function ai.p1_aim_enemy()
    local o, d = ai.p1_ray()
    if o == nil then return nil end
    local em = sdk.get_managed_singleton("app.ropeway.EnemyManager")
    local list = em and safe(function() return em:call("get_ActiveEnemyList") end)
    local n = list and (safe(function() return list:call("get_Count") end) or 0) or 0
    local best, best_t
    for i = 0, n - 1 do
        local ctrl = safe(function() return list:call("get_Item", i) end)
        local go = ctrl and safe(function() return ctrl:call("get_GameObject") end)
        if go and enemy_valid(ctrl) then
            for k = 1, 3 do
                local p = enemy_aim_point(go, k)
                local q = { p[1] - o[1], p[2] - o[2], p[3] - o[3] }
                local t = q[1] * d[1] + q[2] * d[2] + q[3] * d[3]
                if t > 0.5 and t < 40 then
                    local px, py, pz = q[1] - d[1] * t, q[2] - d[2] * t, q[3] - d[3] * t
                    if px * px + py * py + pz * pz < 0.3 and (best_t == nil or t < best_t) then
                        best, best_t = { go = go, ctrl = ctrl }, t
                    end
                end
            end
        end
    end
    return best
end

-- the point under player 1's crosshair: an enemy's body, or whatever the ray hits
function ai.p1_aim_point()
    local e = ai.p1_aim_enemy()
    if e then return (enemy_aim_point(e.go, 1)), e end
    local o, d = ai.p1_ray()
    if o == nil then return nil end
    local far = { o[1] + d[1] * 40, o[2] + d[2] * 40, o[3] + d[3] * 40 }
    local ok, hit = pcall(cast_ray, Vector3f.new(o[1], o[2], o[3]), Vector3f.new(far[1], far[2], far[3]))
    if ok and hit then return { hit.x, hit.y, hit.z } end
    return far
end

-- player 1 has a gun raised (the knife / a grenade at the ready counts as holding too,
-- but the AI should only copy a raised gun)
function ai.p1_aiming()
    local go = p1_go()
    local cond = go and comp(go, "app.ropeway.survivor.player.PlayerCondition")
    if cond == nil or safe(function() return cond:call("get_IsHold") end) ~= true then return false end
    return safe(function() return cond:call("get_IsSupportHold") end) ~= true
end

-- player 1 has the knife (or a grenade) at the ready
function ai.p1_knife()
    local go = p1_go()
    local cond = go and comp(go, "app.ropeway.survivor.player.PlayerCondition")
    return cond ~= nil and safe(function() return cond:call("get_IsSupportHold") end) == true
end

-- player 1 pressing attack right now (RT on the pad, left mouse button on the keyboard)
function ai.p1_attack_pressed()
    local b = st.p1_dev and (safe(function() return st.p1_dev:call("get_Button") end) or 0) or 0
    if (b & 2048) ~= 0 then return true end
    local ok, v = pcall(function() return reframework:is_key_down(0x01) end)
    return ok and v == true
end

-- the floor spot player 1 is pointing at (for "go there")
function ai.p1_point()
    local o, d = ai.p1_ray()
    if o == nil then return nil end
    local far = { o[1] + d[1] * 30, o[2] + d[2] * 30, o[3] + d[3] * 30 }
    local ok, hit = pcall(cast_ray, Vector3f.new(o[1], o[2], o[3]), Vector3f.new(far[1], far[2], far[3]))
    local p
    if ok and hit then
        if d[2] < -0.05 and hit.y < o[2] - 0.8 then
            p = { hit.x, hit.y, hit.z }   -- pointing at the floor: exactly there
        else
            -- a wall: just in front of it
            local hl = math.max(0.01, math.sqrt(d[1] * d[1] + d[3] * d[3]))
            p = { hit.x - d[1] / hl * 0.5, hit.y, hit.z - d[3] / hl * 0.5 }
        end
    else
        p = { o[1] + d[1] * 8, o[2], o[3] + d[3] * 8 }
    end
    -- drop it onto the floor below
    local okf, fl = pcall(cast_ray, Vector3f.new(p[1], p[2] + 0.5, p[3]), Vector3f.new(p[1], p[2] - 6, p[3]))
    if okf and fl then return { fl.x, fl.y, fl.z } end
    return nil
end

ai.FIRE_NAMES = { free = "Weapons free", sync = "Fire when I fire", hold = "Hold fire" }
-- the next of her three guns after the one in her hands (d-pad up, left, right order)
-- own inventory (Operative / Veteran): reload from its ammo, change to a gun that still
-- has rounds, and with nothing left use the knife (ai.out) and say so every 20 s
function ai.ammo_check()
    if st.p2_unarmed and st.p2_unarmed() then ai.out = false; return end   -- (v407/v408: unarmed, no weapon talk)
    local Q = st.p2inv
    local hinv = st.hunk and comp(st.hunk, "app.ropeway.survivor.Inventory")
    if Q == nil or hinv == nil then return end
    local list = Q.list(hinv)
    local reserve = {}
    for _, e in ipairs(list) do if e.wt <= 0 and e.id > 0 then reserve[e.id] = (reserve[e.id] or 0) + e.num end end
    local function rounds(e)
        local b = (e.bullet or 0) > 0 and e.bullet or (WEAPON_BY_WT[e.wt] or {}).ammo
        return e.num, b and reserve[b] or 0
    end
    local main = Q.main_index(hinv)
    local cur
    local guns = {}
    for _, e in ipairs(list) do
        if e.wt > 0 and not Q.SUBW[e.wt] then guns[#guns + 1] = e; if e.i == main then cur = e end end
    end
    if cur then
        local mag, res = rounds(cur)
        if mag > 0 then ai.out = false; return end
        if res > 0 then
            if not ai.reload_until or st.frame > ai.reload_until + 60 then ai.reload_until = st.frame + 30 end
            ai.out = false
            return
        end
    end
    for _, e in ipairs(guns) do
        local mag, res = rounds(e)
        if (mag > 0 or res > 0) and e ~= cur then
            pcall(hinv.call, hinv, "equipSlot(System.Int32)", e.i)
            st.default_weapon_slot = e.i
            ai.out = false
            ai.say("Switching to the " .. e.name)
            return
        end
    end
    if not ai.out then ai.out, ai.out_said = true, 0 end
    if os.clock() - (ai.out_said or 0) > 20 then ai.out_said = os.clock(); ai.say("I'm out of ammo") end
end
function ai.next_gun()
    local guns = {}
    if not st.infinite_ammo and st.p2inv and st.hunk then
        local hinv = comp(st.hunk, "app.ropeway.survivor.Inventory")
        for _, e in ipairs(hinv and st.p2inv.list(hinv) or {}) do
            if e.wt > 0 and not st.p2inv.SUBW[e.wt] then guns[#guns + 1] = { wt = e.wt, slot = e.i, name = e.name } end
        end
    else
        for _, w in ipairs(LOADOUT) do if not w.sub and w.wt ~= 65 and w.wt ~= 66 then guns[#guns + 1] = w end end
    end
    if #guns == 0 then return nil end
    local heq = st.hunk and comp(st.hunk, "app.ropeway.survivor.Equipment")
    local cur = heq and safe(function() return heq:call("get_EquipType") end)
    for i, w in ipairs(guns) do
        if w.wt == cur then return guns[i % #guns + 1] end
    end
    return guns[1]
end
function ai.command(id)
    local o = ai.order
    local hp = st.hunk and v3(st.hunk:call("get_Transform"):call("get_Position"))
    if id == "follow" then
        -- "Stay close": top priority, drop everything and keep within the set distance
        o.move, o.attack, o.pos = "follow", nil, nil
        ai.say("Staying close")
    elseif id == "hold" and hp then
        o.move, o.pos = "hold", hp
        ai.say("Holding position")
    elseif id == "goto" or id == "guard" then
        -- go to the spot under the crosshair and hold that area (free to move about it to fight)
        local p = ai.p1_point()
        if p then
            o.move, o.pos, o.attack, o.arrived = "guard", p, nil, false
            ai.say("Moving there")
        else
            ai.say("I can't go there")
        end
    elseif id == "guard" then
        local p = ai.p1_point()
        if p then
            o.move, o.pos, o.attack, o.arrived = "guard", p, nil, false
            ai.say("Guarding that spot")
        else
            ai.say("I can't go there")
        end
    elseif id == "fire_toggle" then
        o.fire = o.fire == "hold" and "free" or "hold"
        if o.fire == "hold" then o.attack = nil end
        ai.say(ai.FIRE_NAMES[o.fire])
    elseif id == "swap" then
        local g = ai.next_gun()
        local hinv = st.hunk and comp(st.hunk, "app.ropeway.survivor.Inventory")
        if g and hinv then
            safe(function() hinv:call("equipSlot(System.Int32)", g.slot) end)
            st.default_weapon_slot = g.slot   -- and keep it after a reload / load
            ai.wt = g.wt
            ai.say("Switching to the " .. g.name)
        end
    elseif id == "regroup" then
        -- straight to player 1 (teleport), then stay close
        o.move, o.attack, o.pos = "follow", nil, nil
        ai.trail = {}
        pcall(teleport_to_p1)
        ai.say("On you")
    elseif id == "attack" then
        local e = ai.p1_aim_enemy()
        if e then
            o.attack = e
            if o.fire == "hold" then o.fire = "free" end   -- an order to shoot lifts "hold fire"
            ai.next_scan = 0
            ai.say("Attacking your target")
        else
            ai.say("No target under your crosshair")
        end
    elseif id == "fire" then
        o.fire = (o.fire == "free" and "sync") or (o.fire == "sync" and "hold") or "free"
        ai.say(ai.FIRE_NAMES[o.fire])
    elseif id == "fire_sync" and o.fire == "sync" then
        o.fire = "free"   -- a second time switches it off
        ai.say(ai.FIRE_NAMES[o.fire])
    elseif id == "fire_sync" or id == "fire_free" or id == "fire_hold" then
        o.fire = id:sub(6)
        if o.fire ~= "free" then o.attack = nil end
        ai.say(ai.FIRE_NAMES[o.fire])
    elseif id == "heal" then
        pcall(heal_p1)
    elseif id == "resupply" then
        pcall(resupply_p1)
    end
end

-- Where the current order wants him to be this frame: goal (nil = already there), far
-- (far enough to lower the gun and run, even with enemies about) and slow (nearly there).
-- Also notes arrivals. fighting: an enemy is being engaged (guarding then lets him roam
-- the area instead of standing on the spot).
function ai.move_goal(hp, lp, d_leon, o, fighting)
    if o.move == "follow" or o.move == "regroup" then
        local fd = st.ai_follow_dist or 2.0
        local go_on = ai.follow and d_leon > fd or d_leon > fd + 0.8
        ai.follow = go_on
        if go_on then
            -- straight to Leon along the navigation mesh; without a route, his footsteps
            local g = (ai.nav_next(hp, lp) ~= nil) and lp or next_waypoint(hp, lp)
            return g, d_leon > fd + 3.5, false
        end
        return nil
    end
    if o.pos == nil then return nil end
    local d = math.sqrt(dist2(o.pos, hp))
    if o.move == "goto" then
        if d <= 0.35 then o.move = "hold"; ai.say("In position"); return nil end
        return o.pos, d > 5, d < 1.2
    elseif o.move == "guard" then
        if not o.arrived and d <= 0.5 then o.arrived = true; ai.say("In position") end
        local tol = not o.arrived and 0.5 or (fighting and 4 or 1.2)
        if d > tol then return o.pos, d > 5, d < 1.2 end
    elseif o.move == "hold" and d > 1.2 then
        return o.pos, false, true
    end
    return nil
end

-- Where to fight from, by weapon: { closest, farthest } in metres. Shotguns and the
-- flamethrower close in, explosives keep well back, handguns sit in the middle.
ai.BANDS = {
    [11] = { 2.5, 6 },                                     -- W-870 shotgun
    [43] = { 2.0, 4.5 },                                   -- flamethrower
    [44] = { 3, 8 },                                       -- Spark Shot
    [21] = { 3, 10 }, [23] = { 3, 11 },                    -- SMGs
    [50] = { 4, 14 },                                      -- minigun
    [4] = { 4, 12 }, [9] = { 4, 13 }, [31] = { 4, 14 },    -- revolvers / magnum
    [42] = { 5, 15 },                                      -- grenade launcher
    [45] = { 7, 20 }, [49] = { 7, 20 },                    -- rockets
}
ai.BAND_DEFAULT = { 3.5, 12 }                              -- handguns
ai.EXPLOSIVE = { [42] = true, [45] = true, [49] = true }
-- step towards / away from the target to stay in the weapon's band, on a leash: near
-- player 1 when following, near the spot when guarding. True if he moved.
function ai.keep_range(hp, lp, o)
    local t = ai.target
    local band = ai.BANDS[ai.wt or 0] or ai.BAND_DEFAULT
    local dx, dz = t.pos[1] - hp[1], t.pos[3] - hp[3]
    local d = math.sqrt(dx * dx + dz * dz)
    if d < 0.01 then return false end
    local ux, uz = dx / d, dz / d
    local goal, why
    if d > band[2] + 0.5 then
        local step = math.min(1.5, d - band[2])
        goal, why = { hp[1] + ux * step, hp[2], hp[3] + uz * step }, "closing in"
    elseif d < band[1] - 0.3 then
        local sx, sz = ai.steer_dir(hp, -ux, -uz)
        if not sx then return false end
        goal, why = { hp[1] + sx * 1.5, hp[2], hp[3] + sz * 1.5 }, "keeping distance"
    else
        return false
    end
    local anchor, leash = lp, (st.ai_follow_dist or 2.0) + 1.5   -- staying close comes first
    if o.move == "guard" then anchor, leash = o.pos, 4 end
    local dg = dist2(goal, anchor)
    if dg > leash * leash and dg > dist2(hp, anchor) then return false end   -- too far from where he belongs
    ai_walk_to(hp, goal, false)
    ai.state = why
    return true
end

-- Does HUNK have a shot at target t right now? The line from where his bullets start
-- (chest, 0.6 m towards the target) must be clear, the target must not be one his real
-- bullets keep hitting a wall in front of, and he must be (roughly) facing it.
-- Rays are not free: the answer is kept for 4 frames.
ai.blocked = {}   -- enemy address -> frame until which HUNK treats it as out of reach
function ai.has_shot(hp, t)
    local c = ai.shot_cache
    if c and c.t == t and st.frame - c.frame < 4 then return c.ok, c.why end
    local p = t.pos
    local ex, ey, ez = hp[1], hp[2] + AI_EYE, hp[3]
    local dx, dy, dz = p[1] - ex, p[2] - ey, p[3] - ez
    local dl = math.max(0.01, math.sqrt(dx * dx + dy * dy + dz * dz))
    local ok, why = true, nil
    if t.go and (ai.blocked[t.go:get_address()] or 0) > st.frame then
        ok, why = false, "blocked"
    elseif dl > 1.0 and not clear_line({ ex + dx / dl * 0.6, ey + dy / dl * 0.6, ez + dz / dl * 0.6 }, p) then
        ok, why = false, "wall"
    else
        local hl = math.sqrt(dx * dx + dz * dz)
        local f = hl > 0.5 and safe(function() return st.hunk:call("get_Transform"):call("get_Rotation") * Vector3f.new(0, 0, 1) end)
        if f then
            local fl = math.max(0.01, math.sqrt(f.x * f.x + f.z * f.z))
            if (f.x * dx + f.z * dz) / (fl * hl) < 0.85 then ok, why = false, "turning" end
        end
    end
    ai.shot_cache = { t = t, frame = st.frame, ok = ok, why = why }
    return ok, why
end
-- learn from HUNK's real bullets: two in a row hitting a wall well short of the enemy
-- (geometry the line check doesn't see: railings, props, door frames) and he stops
-- shooting at it for a few seconds
function ai.learn_hit(sh)
    local t = ai.target
    if t == nil or t.go == nil or st.hunk == nil then return end
    local p = sh:get_field("HitTerrainInfo"):get_field("Position")
    local hp = st.hunk:call("get_Transform"):call("get_Position")
    local cy = hp.y + AI_EYE
    local hit = math.sqrt((p.x - hp.x) ^ 2 + (p.y - cy) ^ 2 + (p.z - hp.z) ^ 2)
    local full = math.sqrt((t.pos[1] - hp.x) ^ 2 + (t.pos[2] - cy) ^ 2 + (t.pos[3] - hp.z) ^ 2)
    local addr = t.go:get_address()
    if hit < full - 1.0 then
        ai.wall_hits = ai.wall_hit_go == addr and (ai.wall_hits or 0) + 1 or 1
        ai.wall_hit_go = addr
        if ai.wall_hits >= 2 then
            ai.blocked[addr] = st.frame + 150
            ai.wall_hits = 0
        end
    elseif ai.wall_hit_go == addr then
        ai.wall_hits = 0
    end
end
;(function()
    -- (NonRT-3) On Non-RT (TDB 66) checkHitTerrain can't be hooked (REFramework: "Failed to
    -- hook ... unknown exception"). There the bullet's own onHitTerrain() (BulletShellBase`6, called
    -- once its HitTerrainInfo is filled in) is hooked instead. RT keeps checkHitTerrain.
    if st.NON_RT then
        local seen2 = {}
        for _, sn in ipairs({ "BulletDefault", "BulletSpark" }) do
            local t = sdk.find_type_definition("app.ropeway.weapon.shell." .. sn)
            while t and not t:get_full_name():find("^via%.") do
                local m = t:get_method("onHitTerrain")
                if m and safe(function() return m:get_declaring_type():get_full_name() end) == t:get_full_name() then
                    if not seen2[t:get_full_name()] then
                        seen2[t:get_full_name()] = true
                        sdk.hook(m, function(args)
                            if not ai.active or st.hunk == nil or ai.target == nil or ai.target.go == nil then return end
                            -- (BulletDefault's and BulletSpark's onHitTerrain can be one function with
                            -- two hooks on it: a shell is counted once a frame)
                            local key = sdk.to_int64(args[2])
                            if ai.last_terrain_shell == key and ai.last_terrain_frame == st.frame then return end
                            ai.last_terrain_shell, ai.last_terrain_frame = key, st.frame
                            local sh = sdk.to_managed_object(args[2])
                            if sh and safe(function() return sh:call("get_AttackOwner") end) == st.hunk then pcall(ai.learn_hit, sh) end
                        end, function(r) return r end)
                        st.nonrt_hooks = (st.nonrt_hooks or "") .. "onHitTerrain(" .. sn .. ") "
                    end
                    break
                end
                t = t:get_parent_type()
            end
        end
        return
    end
    local cur, seen = nil, {}
    for _, sn in ipairs({ "BulletDefault", "BulletSpark" }) do
        local td = sdk.find_type_definition("app.ropeway.weapon.shell." .. sn)
        local gp = td and td:get_parent_type()
        gp = gp and gp:get_parent_type()
        if gp and not seen[gp:get_full_name()] then
            seen[gp:get_full_name()] = true
            for _, m in ipairs(gp:get_methods()) do
                if m:get_name() == "checkHitTerrain" then
                    sdk.hook(m, function(args)
                        cur = nil
                        if not ai.active or st.hunk == nil or ai.target == nil or ai.target.go == nil then return end
                        local sh = sdk.to_managed_object(args[2])
                        if sh and safe(function() return sh:call("get_AttackOwner") end) == st.hunk then cur = sh end
                    end, function(r)
                        local sh = cur
                        cur = nil
                        if sh ~= nil and (sdk.to_int64(r) & 1) == 1 then pcall(ai.learn_hit, sh) end
                        return r
                    end)
                end
            end
        end
    end
end)()

-- Player 2 for fixed cameras (a person on a pad, not the AI) -------------------------
-- Player 2 with the Fixed Camera mod (Classic Cameras by alphaZomega) ----------------
-- When that mod is installed and enabled, player 2 follows its control settings:
-- tank or camera-relative walking, d-pad movement (its "Allow D-pad Shortcuts" button
-- for the weapon shortcuts), its turn speeds, no running backwards, run button + back for
-- a quick turn, and its auto-aim (lock-on type, head / legs targeting, enemies behind,
-- a half-pulled LT or its Disable Autoaim button to aim by hand). Its settings are read
-- from its own saved file, so nothing here duplicates them.
-- The game walks every player relative to player 1's camera (which the mod points
-- along Leon's facing), so for HUNK the camera yaw he reads is swapped for his own
-- heading (st.tank.frame) and his facing goes into his action orderer (st.tank.dir).
st.cc = { next_read = 0, installed = nil, s = nil,
    DEF = { enabled = true, walk_type = 3, run_type = 5, turn_speed = 1.0, turn_speed_jog = 1.0,
        use_dpad_controls = true, tank_walk_bwd_invert = false, do_autoaim = true, autoaim_all = true,
        lock_on_type = 2, do_detect_behind = true,
        hotkeys = { ["Allow D-pad Shortcuts"] = "RStickPush", ["Disable Autoaim"] = "A (X)", ["Disable Autoaim_$"] = "LT (L2)" } },
    -- the mod's gamepad button names -> player 2's pad bits
    PAD = { ["A (X)"] = 32, ["B (Circle)"] = 128, ["X (Square)"] = 64, ["Y (Triangle)"] = 16,
        ["LB (L1)"] = 256, ["LT (L2)"] = 512, ["RB (R1)"] = 1024, ["RT (R2)"] = 2048,
        LStickPush = 4096, RStickPush = 8192, Select = 16384, Start = 32768,
        LUp = 1, LDown = 2, LLeft = 4, LRight = 8 } }
-- the mod's settings, or nil when it isn't installed / is switched off
function st.cc.get()
    local C = st.cc
    -- (dev bridge: st.cc.force_absent = true acts as if the mod weren't installed)
    if C.force_absent then C.installed = false; C.s = nil; return nil end
    if st.frame >= C.next_read then
        C.next_read = st.frame + 120
        local s = safe(function() return json.load_file("ClassicCams\\CCSettings.json") end)
        if type(s) == "table" then
            C.installed = true
        elseif C.installed == nil then
            -- never saved yet: the mod runs on its defaults if its data folder is there
            C.installed = safe(function() return json.load_file("ClassicCams\\Presets\\Controls\\Controls 3 - Tank controls.json") end) ~= nil
        end
        local m = {}
        for k, v in pairs(C.DEF) do m[k] = v end
        if type(s) == "table" then for k, v in pairs(s) do m[k] = v end end
        C.s = m
    end
    if not C.installed or not C.s then return nil end
    -- (v374) on or off is read from the game, not the saved file: its Enabled box isn't saved
    -- when ticked (only its hotkey saves it), so the file said off with the fixed cameras on
    local live = C.live_on()
    if live == nil then live = C.s.enabled ~= false end
    if not live then return nil end
    return C.s
end
-- the mod running right now: it places the camera by moving the main camera's joint, which
-- otherwise sits on the camera object itself (measured: 7.5 m apart with its fixed cameras,
-- 0.000 with the mod switched off). Seen within the last 3 s = on. nil when unreadable.
function st.cc.live_on()
    local C = st.cc
    if C.live_at == nil or st.frame - C.live_at >= 15 or st.frame < C.live_at then
        C.live_at = st.frame
        local d = safe(function()
            local cam = sdk.get_primary_camera()
            local xf = cam:call("get_GameObject"):call("get_Transform")
            return (xf:call("get_Joints")[0]:call("get_Position") - xf:call("get_Position")):length()
        end)
        C.live_ok = d ~= nil
        if d and d > 0.3 then C.live_seen = st.frame end
    end
    if not C.live_ok then return nil end
    return C.live_seen ~= nil and st.frame - C.live_seen < 180 and st.frame >= C.live_seen
end
function st.cc.btn(s, name)
    local h = type(s.hotkeys) == "table" and s.hotkeys[name] or nil
    return h and st.cc.PAD[h] or nil
end
-- yaw of the camera actually on screen (the mod moves the camera's joint, not its object)
function st.cc.view_yaw()
    local cam = sdk.get_primary_camera()
    local j = cam and safe(function() return cam:call("get_GameObject"):call("get_Transform"):call("get_Joints")[0] end)
    local m = j and safe(function() return j:call("get_WorldMatrix") end)
    if m == nil then return nil end
    local f = m[2]
    return math.atan(-f.x, -f.z)
end

st.tank = { on = false, override = false, stick = nil, aim_pos = nil, move_on = false, move_was = false }
function st.tank.release(T, yaw)
    T.on, T.override, T.aim_pos, T.move_on, T.dpad_block, T.block_jog, T.fa_aim, T.no_qt = false, false, nil, false, false, false, nil, false
    T.frame, T.dir, T.qt, T.cam_hold, T.lock, T.lock_block, T.aim_yaw = nil, nil, nil, nil, nil, nil, nil
    T.yaw = yaw
end
-- auto-aim: the nearest live enemy HUNK can see, in front (or anywhere close when the
-- mod's "detect behind" is on and he has just raised his gun)
function st.tank.pick(eye, yaw, behind)
    local em = sdk.get_managed_singleton("app.ropeway.EnemyManager")
    local list = em and safe(function() return em:call("get_ActiveEnemyList") end)
    local fx, fz = math.sin(yaw), math.cos(yaw)
    local best, bs
    for i = 0, (list and (safe(function() return list:call("get_Count") end) or 0) or 0) - 1 do
        local ctrl = safe(function() return list:call("get_Item", i) end)
        local go = ctrl and safe(function() return ctrl:call("get_GameObject") end)
        local hpc = go and comp(go, "app.ropeway.HitPointController")
        if go and hpc and (safe(function() return hpc:call("get_CurrentHitPoint") end) or 0) > 0 and enemy_valid(ctrl) then
            local p = enemy_aim_point(go, 1)
            local dx, dz = p[1] - eye[1], p[3] - eye[3]
            local d = math.sqrt(dx * dx + dz * dz)
            local front = d > 0.01 and (dx * fx + dz * fz) / d or 1
            if (d < 20 and front > 0.3) or (behind and d < 12) then
                local score = d - front * 2
                if best == nil or score < bs then
                    if visible_point(eye, go) then best, bs = go, score end
                end
            end
        end
    end
    return best and best:get_address() or nil
end
-- where to shoot the locked enemy: chest, or head / legs with the stick when the mod's
-- "Autotarget head/legs" is on. nil once it is dead or out of sight
function st.tank.lock_point(addr, eye, s, y)
    local em = sdk.get_managed_singleton("app.ropeway.EnemyManager")
    local list = em and safe(function() return em:call("get_ActiveEnemyList") end)
    for i = 0, (list and (safe(function() return list:call("get_Count") end) or 0) or 0) - 1 do
        local ctrl = safe(function() return list:call("get_Item", i) end)
        local go = ctrl and safe(function() return ctrl:call("get_GameObject") end)
        if go and go:get_address() == addr then
            local hpc = comp(go, "app.ropeway.HitPointController")
            if not (hpc and (safe(function() return hpc:call("get_CurrentHitPoint") end) or 0) > 0 and enemy_valid(ctrl)) then return nil end
            local k = (s.autoaim_all and y > 0.5 and 2) or (s.autoaim_all and y < -0.5 and 3) or 1
            local p = enemy_aim_point(go, k)
            if k == 3 then p = { p[1], p[2] - 0.35, p[3] } end
            if clear_line(eye, p) then return p end
            local _, vp = visible_point(eye, go)
            return vp
        end
    end
    return nil
end

function st.tank.update(dt)
    local T = st.tank
    T.move_was = T.move_on
    local s = st.cc.get()
    -- Fixed Camera Mode needs that mod running; Free Aim is the mod's own (that mod's
    -- settings when it's there, else its defaults)
    local cc_mode = st.p2_cc and s ~= nil
    local fa_mode = st.p2_free_aim == true
    if not ((cc_mode or fa_mode) and not ai.active and not p2c.active and st.hunk ~= nil and st.unit2 ~= nil and not menu.open and not menu.p2_lock) then T.release(T, nil); return end
    s = s or st.cc.s or st.cc.DEF
    local xf = st.hunk:call("get_Transform")
    local cur = xf:call("get_EulerAngle").y
    if hunk_sub_holding() then T.release(T, cur); return end   -- knife / grenade: the usual sub-weapon aim
    -- (v381) in a gimmick's hands (ladder, jump-down, door...): the game moves him; motion layer 0
    -- still reads STAND.IDLE through a climb, so the steering below would fight it
    local jd = comp(st.hunk, "app.ropeway.JackDominator")
    if jd and safe(function() return jd:call("get_Jacked") end) == true then T.release(T, cur); return end
    T.on = true
    T.fa_aim = nil
    local dev = st.p2_dev
    local b = dev and (safe(function() return dev:call("get_Button") end) or 0) or 0
    local ax = dev and safe(function() return dev:call("get_AxisL") end)
    local x, y = ax and ax.x or 0, ax and ax.y or 0
    -- d-pad movement unless the mod's shortcut button (R3) is held
    local sc = st.cc.btn(s, "Allow D-pad Shortcuts") or 8192
    T.dpad_block = cc_mode and s.use_dpad_controls == true and (b & sc) ~= sc
    local dx = ((b & 8) ~= 0 and 1 or 0) - ((b & 4) ~= 0 and 1 or 0)
    local dy = ((b & 1) ~= 0 and 1 or 0) - ((b & 2) ~= 0 and 1 or 0)
    local dpad = T.dpad_block and (dx ~= 0 or dy ~= 0)
    if dpad then x, y = dx, dy end
    local mf = comp(st.hunk, "via.motion.MotionFsm2")
    local node = mf and safe(function() return mf:call("getCurrentNodeName", 0) end) or ""
    if type(node) ~= "string" then node = "" end
    local aiming = hunk_is_aiming()
    if not cc_mode and not aiming then
        -- Free Aim only: walking and running stay the game's own
        T.release(T, cur)
        T.on = true
        return
    end
    st.live_stick(T, "stick")
    local fx, fy = 0, 0
    T.no_qt = false
    -- Classic Cameras' "Strafe / Classic Aim" button (A): strafe while walking, classic aim
    -- (stand still, the left stick turns the aim) while aiming
    local cab = cc_mode and st.cc.btn(s, "Strafe / Classic Aim") or nil
    local ca_held = cab ~= nil and (b & cab) ~= 0
    local downb = safe(function() return dev:call("get_ButtonDown") end) or 0
    local arx = 0
    do
        local ar0 = dev and safe(function() return dev:call("get_AxisR") end)
        arx = ar0 and ar0.x or 0
    end

    if not aiming then
        T.aim_pos, T.aim_yaw, T.lock, T.lock_block = nil, nil, nil, nil
        T.yaw = T.yaw or cur
        -- quick turn (run button + back): the game's quick-turn move, or a plain 180 if
        -- this body has none
        if T.qt then
            T.qt.t = T.qt.t + dt
            if node:find("QUICK") then T.qt.native = true end
            if T.qt.native then
                if not node:find("QUICK") and T.qt.t > 0.1 then T.qt = nil end
                T.yaw = cur
            elseif T.qt.t > 0.08 then
                local k = math.min(1, (T.qt.t - 0.08) / 0.3)
                T.yaw = T.qt.from + math.pi * k
                if k >= 1 then T.qt = nil end
            end
            if T.qt and T.qt.native then
                T.override, T.frame, T.dir, T.move_on = false, nil, nil, false
                return
            end
        end
        -- only steer while standing, walking or running: doors, ladders, grabs and hit
        -- reactions are the game's
        local free = node:find("^STAND") ~= nil or node:find("WALK") ~= nil or node:find("JOG") ~= nil
        if not free and not T.qt then
            T.yaw, T.override, T.frame, T.dir, T.move_on, T.block_jog, T.cam_hold = cur, false, nil, nil, false, false, nil
            return
        end
        local jog = node:find("JOG") ~= nil
        local tank = dpad or (s.walk_type >= 3 and (x * x + y * y) > 0.01)
        -- (v374, as player 1 under Classic Cameras) running quick turn: its button (B) while
        -- running turns him round mid-run; the game's own quick turn is off while running
        T.no_qt = jog and s.use_quickturn_button ~= false
        local rqt = st.cc.btn(s, "Running Quick Turn")
        if T.no_qt and rqt and (downb & rqt) ~= 0 and not T.qt and node == "JOGGING" then
            -- (his heading flips at once, so forward on the stick now runs the other way; his body
            -- comes round with the game's own run-turn rather than snapping)
            T.yaw = T.yaw + math.pi
            T.rqt_until = os.clock() + 0.7
            local layer = mf and safe(function() return mf:call("getLayer", 0) end)
            if layer and st.cc.set_node then pcall(st.cc.set_node.call, st.cc.set_node, layer, "JOG_TURN", st.cc.setn, st.cc.interp) end
        end
        -- strafe: the button held while walking moves him along the stick without turning
        local strafe = ca_held and not dpad and not jog and (x * x + y * y) > 0.01
        if T.qt then
            fy = 0
        elseif strafe then
            T.cam_hold = nil
            fx, fy = x, y
        elseif tank then
            T.cam_hold = nil
            local turn = (dpad or math.abs(x) > 0.2) and x or 0
            if s.tank_walk_bwd_invert and y < -0.25 then turn = -turn end
            -- the mod's rates: 0.057 (walk) / 0.045 (run, capped 0.04) radians per 60th of a second
            local rate = jog and math.min(2.4, 2.7 * (s.turn_speed_jog or 1)) or 3.42 * (s.turn_speed or 1)
            T.yaw = T.yaw - turn * rate * dt   -- right turns clockwise
            fy = (y > 0.25 and 1) or (y < -0.25 and -1) or 0
        elseif x * x + y * y > 0.04 then
            -- camera relative: keep the camera the input started under until the stick is let go
            T.cam_hold = T.cam_hold or st.cc.view_yaw() or cur
            local want = T.cam_hold - math.atan(x, y)
            local diff = math.atan(math.sin(want - T.yaw), math.cos(want - T.yaw))
            local step = 10 * dt
            T.yaw = T.yaw + math.max(-step, math.min(step, diff))
            fy = math.min(1, math.sqrt(x * x + y * y))
        else
            T.cam_hold = nil
            -- look turn: standing (or walking) with the left stick let go, the right stick
            -- turns him on the spot
            if cc_mode and not jog and math.abs(arx) > 0.33 then
                T.yaw = T.yaw - arx * 3.42 * (s.turn_speed or 1) * dt
            end
        end
        -- run button + back: quick turn
        if not T.qt and fy < 0 and not jog then
            local down = safe(function() return dev:call("get_ButtonDown") end) or 0
            local function kmask(k)
                local m = st.kind_btn[k]
                if m == nil then m = safe(function() return st.unit2:call("getGamePadButton", k) end) or 0; st.kind_btn[k] = m end
                return m
            end
            local run = (down & (kmask(16) | kmask(8))) ~= 0
            if run then
                T.qt = { t = 0, from = T.yaw }
                local layer = mf and safe(function() return mf:call("getLayer", 0) end)
                if layer and st.cc.set_node then
                    pcall(st.cc.set_node.call, st.cc.set_node, layer, "QUICK_TURN_EX", st.cc.setn, st.cc.interp)
                end
                fy = 0
            end
        end
        T.block_jog = (s.run_type == 5 and fy < 0) or T.qt ~= nil   -- no running backwards
        T.yaw = math.atan(math.sin(T.yaw), math.cos(T.yaw))
        -- turn the body itself too: standing still the game would only turn him once he walks
        if math.abs(math.atan(math.sin(T.yaw - cur), math.cos(T.yaw - cur))) > 0.002 and not (T.rqt_until and os.clock() < T.rqt_until) then
            xf:call("set_Rotation", Quaternion.new(math.cos(T.yaw / 2), 0, math.sin(T.yaw / 2), 0))
            local pc = comp(st.hunk, "app.ropeway.survivor.player.PlayerController")
            local ca = pc and safe(function() return pc:get_field("<CharAngle>k__BackingField") end)
            if ca then pcall(function() ca:set_field("<Current>k__BackingField", T.yaw); ca:set_field("_Target", T.yaw) end) end
        end
        T.frame = T.yaw + math.pi
        T.dir = { math.sin(T.yaw), math.cos(T.yaw) }
        T.override = true
    elseif (fa_mode and not cc_mode) or (cc_mode and not (ca_held ~= (s.do_classic_aim == true))) then
        -- (v374) Shared Screen's Free Aim, and Fixed Camera's own aim, which is player 1's under
        -- Classic Cameras: the right stick aims, the left stick walks him (along his aim, the way
        -- her aim camera sits behind her), auto-aim locks on while drawing / aiming (its
        -- lock-on type, head / legs, enemies behind) until the right stick is pushed, and comes
        -- back on what he's pointing at once it's let go. A half-pulled LT or its Disable
        -- Autoaim buttons aim by hand. Holding its Classic Aim button (A) aims the old way below.
        local normal = cc_mode
        -- Free Aim, the split screen way: the right stick aims anywhere (all the way round, up
        -- and down; aim speed and invert from the settings), the left stick keeps walking him
        -- (the game's own walk while aiming, screen-relative). He faces, aims and fires along
        -- it (st.tank.aim_pos -> target_point; T.fa_aim also steers his body turn and upper
        -- body look-at, as player 2's camera does in split screen).
        T.frame, T.dir, T.qt, T.block_jog, T.cam_hold = nil, nil, nil, false, nil
        if not normal then T.lock, T.lock_block = nil, nil end
        T.override = false
        T.fa_aim = true
        local starting = T.aim_yaw == nil
        if starting then T.aim_yaw, T.aim_pitch, T.lock, T.manual, T.aim_t = cur, 0, nil, nil, 0 end
        T.aim_t = (T.aim_t or 0) + dt
        local ar = dev and safe(function() return dev:call("get_AxisR") end)
        local rx, ry = ar and ar.x or 0, ar and ar.y or 0
        if st.invert_x then rx = -rx end
        if st.invert_y then ry = -ry end
        local hp = xf:call("get_Position")
        local lockp
        if normal then
            local eye = { hp.x, hp.y + AI_EYE, hp.z }
            -- (with head / legs on, a straight up / down push picks the head / legs instead)
            local vert = s.autoaim_all and math.abs(ry) > 0.5 and math.abs(rx) < 0.3
            local push = rx * rx + ry * ry
            if push > 0.09 and not (vert and T.lock) then T.manual, T.lock = true, nil
            elseif T.manual and push < 0.0225 then T.manual = nil end
            local auto = s.do_autoaim or st.p2_autoaim == true
            local off = false
            local lt = dev and safe(function() return dev:call("get_AnalogL") end)
            if type(lt) == "number" and lt > 0.05 and lt <= 0.835 then off = true end   -- LT half pulled
            local dk, dm = st.cc.btn(s, "Disable Autoaim"), st.cc.btn(s, "Disable Autoaim_$")
            if dk and (b & dk) ~= 0 and (dm == nil or (b & dm) ~= 0) then off = true end
            local drawing = T.aim_t < 0.4
            if T.manual or off or not auto or (s.lock_on_type == 1 and not drawing) then T.lock = nil end
            if auto and not off and not T.manual and T.lock == nil and (s.lock_on_type ~= 1 or drawing) then
                T.lock = T.pick(eye, T.aim_yaw, starting and s.do_detect_behind ~= false)
            end
            lockp = T.lock and T.lock_point(T.lock, eye, s, vert and ry or 0)
            if T.lock and lockp == nil then T.lock = nil end
            if lockp then
                -- turn onto it quickly rather than snapping
                local ddx, ddy, ddz = lockp[1] - eye[1], lockp[2] - eye[2], lockp[3] - eye[3]
                local wy = math.atan(ddx, ddz)
                local wp = math.atan(ddy, math.sqrt(ddx * ddx + ddz * ddz))
                local k = math.min(1, dt * 12)
                local dyaw = math.atan(math.sin(wy - T.aim_yaw), math.cos(wy - T.aim_yaw))
                T.aim_yaw = T.aim_yaw + dyaw * k
                T.aim_pitch = T.aim_pitch + (wp - T.aim_pitch) * k
                if math.abs(dyaw) > 0.05 then lockp = nil end   -- (still turning: the aim ray below)
            end
        end
        if not (normal and T.lock) then
            local spd = st.aim_speed or 2.2
            if math.abs(rx) > 0.15 then T.aim_yaw = T.aim_yaw - rx * spd * dt end
            if math.abs(ry) > 0.15 then
                local mp = st.max_pitch or 1.0
                T.aim_pitch = math.max(-mp, math.min(mp, T.aim_pitch + ry * spd * 0.6 * dt))
            end
        end
        T.aim_yaw = math.atan(math.sin(T.aim_yaw), math.cos(T.aim_yaw))
        if lockp then
            T.aim_pos = lockp
        else
            local eye = Vector3f.new(hp.x, hp.y + 1.45, hp.z)
            local cp = math.cos(T.aim_pitch)
            local far = Vector3f.new(eye.x + math.sin(T.aim_yaw) * cp * 30, eye.y + math.sin(T.aim_pitch) * 30, eye.z + math.cos(T.aim_yaw) * cp * 30)
            local ok, hit = pcall(cast_ray, Vector3f.new(eye.x + math.sin(T.aim_yaw) * cp * 0.5, eye.y + math.sin(T.aim_pitch) * 0.5, eye.z + math.cos(T.aim_yaw) * cp * 0.5), far)
            local t = (ok and hit) or far
            T.aim_pos = { t.x, t.y, t.z }
        end
        T.yaw = cur
        if normal then
            -- walking while aiming, along his aim (stick forward walks the way he aims)
            T.override = true
            T.frame = T.aim_yaw + math.pi
            T.dir = { math.sin(T.aim_yaw), math.cos(T.aim_yaw) }
            if x * x + y * y > 0.01 then fx, fy = x, y end
            pcall(function() T.stick:call("update", Vector2f.new(fx, fy), Vector2f.new(fx, fy)) end)
            T.move_on = fx ~= 0 or fy ~= 0
            return
        end
        T.move_on = false
        return
    else
        -- aiming: he stands still and the left stick (or d-pad) turns the aim, as in the
        -- old games; auto-aim locks on as the mod does
        T.frame, T.dir, T.qt, T.block_jog, T.cam_hold = nil, nil, nil, false, nil
        T.override = true
        -- (v373) his body, upper-body look-at and spine follow this aim (as Free Aim / split
        -- screen do), not player 1's crosshair
        T.fa_aim = true
        local hp = v3(xf:call("get_Position"))
