-- Player 2's laser sight, the Fixed Camera mod's way: a laser taken from the wp0200 prefab
-- rides on HUNK's gun muzzle while he aims. On / off in Extras; color and intensity are
-- that mod's.
-- (v385) the same laser for player 1 too (st.p1_laser, off by default): a second unit,
-- "CoopP1LaserSight", on her gun, pointing along her muzzle. Left off while Classic Cameras
-- is on with its own laser sight (that one is hers already).
st.laser = { go = nil, ctrl = nil, owner = nil, next_find = 0 }
st.laser1 = { go = nil, ctrl = nil, owner = nil, next_find = 0 }
;(function()   -- own function: the main chunk is at Lua's local-variable limit
local LASER_SPAWN = { by = nil }   -- one wp0200 spawn at a time between the two units
-- (NonRT-9) where a laser from a to b first meets a body other than its owner's: player 1, player 2
-- and live enemies as upright capsules (players 0.28 m wide from 0.1 m to 1.8 m, enemies 0.35 m to
-- 1.85 m). Returns the distance along a -> b (or nil).
function st.laser_body_hit(a, b, owner)
    local dx, dy, dz = b.x - a.x, b.y - a.y, b.z - a.z
    local len = math.sqrt(dx * dx + dy * dy + dz * dz)
    if len < 0.05 then return nil end
    dx, dy, dz = dx / len, dy / len, dz / len
    local best = nil
    local function test(p, r, y0, y1)
        -- the ray against an upright cylinder at p (x, z), height p.y + y0 .. p.y + y1
        local ox, oz = a.x - p.x, a.z - p.z
        local A = dx * dx + dz * dz
        if A < 1e-6 then return end
        local B = 2 * (ox * dx + oz * dz)
        local C = ox * ox + oz * oz - r * r
        local D = B * B - 4 * A * C
        if D < 0 then return end
        local t = (-B - math.sqrt(D)) / (2 * A)
        if t < 0.15 then return end   -- (inside it, or right at the muzzle)
        if t > len or (best and t >= best) then return end
        local y = a.y + dy * t
        if y >= p.y + y0 and y <= p.y + y1 then best = t end
    end
    local oaddr = owner and owner:get_address()
    for _, go in ipairs({ p1_go(), st.hunk }) do
        if go and go:get_address() ~= oaddr then
            local p = safe(function() return go:call("get_Transform"):call("get_Position") end)
            if p then test(p, 0.28, 0.1, 1.8) end
        end
    end
    local em = sdk.get_managed_singleton("app.ropeway.EnemyManager")
    local list = em and safe(function() return em:call("get_ActiveEnemyList") end)
    for i = 0, (list and safe(function() return list:call("get_Count") end) or 0) - 1 do
        pcall(function()
            local c = list:call("get_Item", i)
            if c:call("get_IsLive") == false then return end
            local p = c:call("get_GameObject"):call("get_Transform"):call("get_Position")
            test(p, 0.35, 0.0, 1.85)
        end)
    end
    return best
end
-- (NonRT-11) the views on screen now: player 1's (the main camera; Classic Cameras moves its
-- joint, not its object) and, in split screen, player 2's. For a point: whether each view sees it
-- (no body and no wall between that camera and the point), with each view's ViewProj and screen
-- part for drawing.
function st.laser_dot_views(tip)
    local views = {}
    if tip == nil then return false, views end
    local cam = sdk.get_primary_camera()
    local c1 = cam and safe(function()
        local xf = cam:call("get_GameObject"):call("get_Transform")
        local j = xf:call("get_Joints")[0]
        return j and j:call("get_Position") or xf:call("get_Position")
    end)
    local vp1 = cam and safe(function() return cam:call("get_ViewProjMatrix") end)
    if p2c.active and st.dual and st.dual.on then
        local reg = p2c.regions[st.split_layout] or p2c.regions[1]
        views[#views + 1] = { c = c1, vp = vp1, r = reg.p1, who = p1_go() }
        local D = st.dual
        local vp2 = D.cam and safe(function() return D.cam:call("get_ViewProjMatrix") end)
        views[#views + 1] = { c = p2c.pos, vp = vp2, r = reg.p2, who = st.hunk }
    else
        views[#views + 1] = { c = c1, vp = vp1, r = { 0, 0, 1, 1 }, who = p1_go() }
    end
    for _, v in ipairs(views) do
        v.vis = false
        if v.c then
            local d = tip - v.c
            local dist = d:length()
            if dist < 0.2 then
                v.vis = true
            else
                -- (the view's own player is left out, the camera looks past their shoulder, unless
                -- the dot is on them: then their body hides it from their own camera behind them)
                local skip = v.who
                local wp = v.who and safe(function() return v.who:call("get_Transform"):call("get_Position") end)
                if wp and (tip.x - wp.x) ^ 2 + (tip.z - wp.z) ^ 2 < 0.45 * 0.45 and tip.y > wp.y - 0.1 and tip.y < wp.y + 2.0 then skip = nil end
                local bt = st.laser_body_hit(v.c, tip, skip)
                local ok, wall = pcall(cast_ray, v.c, tip)
                local blocked = (bt and bt < dist - 0.1) or (ok and wall and (wall - v.c):length() < dist - 0.2)
                v.vis = not blocked
            end
        end
    end
    return true, views
end
re.on_frame(function()
    if not st.NON_RT then return end
    pcall(function()
        local ds = imgui.get_display_size()
        for _, L in ipairs({ st.laser1, st.laser }) do
