local function laser_unit(L, NAME, for_p1)
    local function scene()
        return sdk.call_native_func(sdk.get_native_singleton("via.SceneManager"), sdk.find_type_definition("via.SceneManager"), "get_CurrentScene")
    end
    local function find(sc, n) return safe(function() return sc:call("findGameObject(System.String)", n) end) end
    local function hide()
        L.dot2d = nil
