            pcall(function() L.ctrl:set_field("WeaponPartsBits", 9999) end)
            pcall(function() L.ctrl:get_field("<Light>k__BackingField"):call("set_DrawSelf", false) end)
        end
    end
    -- find our laser, or make one: load wp0200, take its LaserSight, throw the gun away
    local function get_laser(sc)
        if st.frame >= L.next_find or L.go == nil then
            L.next_find = st.frame + 30
            local go = find(sc, NAME)
            if go == nil then L.go, L.ctrl, L.owner = nil, nil, nil end
            if go and go ~= L.go then
                L.go, L.owner = go, nil
                L.ctrl = comp(go, "app.ropeway.LaserSightController")
            end
        end
        if L.ctrl then return L.ctrl end
        -- wait for the Classic Cameras mod's own laser first, so the two spawns never cross (5 s
        -- at most: switched off, that mod may never make one)
        L.wait_since = L.wait_since or st.frame
        if st.cc.installed and find(sc, "CCLaserSight") == nil and st.frame - L.wait_since < 300 then return nil end
        if L.pfb == nil then
            if LASER_SPAWN.by and LASER_SPAWN.by ~= L then return nil end
            LASER_SPAWN.by = L
            L.pfb = sdk.create_instance("via.Prefab"):add_ref()
            L.pfb:call("set_Path", "objectroot/prefab/character/weapon/wp0200.pfb")
            L.pfb:call("set_Standby", true)
            L.before = find(sc, "wp0200")
            L.spawned = false
            return nil
        end
        if not L.spawned then
            local r = safe(function() return L.pfb:call("instantiate(via.vec3)", Vector3f.new(0, -50, 0)) end)
            L.spawned = r ~= nil
            if not L.spawned then return nil end
            L.spawn_go = safe(function() return r:get_type_definition():get_full_name() == "via.GameObject" and r or nil end)
        end
        local gun = L.spawn_go or find(sc, "wp0200")
        if gun == nil or gun == L.before then return nil end
        local xf = safe(function() return gun:call("get_Transform"):call("find", "LaserSight") end)
        if xf then
            pcall(function()
                xf:call("get_GameObject"):call("set_Name", NAME)
                xf:call("set_LocalEulerAngle", Vector3f.new(0, 0, 0))
                xf:call("set_Parent", nil)
            end)
        end
        pcall(function() gun:call("destroy", gun) end)
        L.pfb, L.spawned, L.before, L.next_find, L.spawn_go = nil, nil, nil, 0, nil
        if LASER_SPAWN.by == L then LASER_SPAWN.by = nil end
