        if s == nil then s = (st.cc and st.cc.installed and st.cc.s) or {} end
        local body
        if for_p1 then body = p1_go() else body = st.hunk end
        local want
        if for_p1 then
            -- (Classic Cameras on with its laser: hers is that one)
            local cs = st.cc and st.cc.get()
            want = st.p1_laser == true and not (cs and cs.use_lasersight ~= false)
        else
            want = st.p2_laser == true
        end
        if not (want and body) then hide(); return end
        local sc = scene()
        if sc == nil then return end
        local ctrl = get_laser(sc)
        if ctrl == nil then return end
        local eq = comp(body, "app.ropeway.survivor.Equipment")
        local wp = eq and safe(function() return eq:get_field("<EquipWeapon>k__BackingField") end)
        local gun = wp and safe(function() return wp:get_type_definition():is_a("app.ropeway.implement.Gun") end)
        local et = eq and safe(function() return eq:get_field("<EquipType>k__BackingField") end)
        local cond = comp(body, "app.ropeway.survivor.player.PlayerCondition")
        local aiming = cond and (safe(function() return cond:call("get_IsHold") end) or safe(function() return cond:call("get_IsHoldStart") end))
