                local locked = (for_p1 and not cc_now) or (not for_p1 and ((st.tank and st.tank.lock) or (ai.active and ai.aim_pos)))
                if locked and dl < (tip - mp):length() then tip = Vector3f.new(tp[1], tp[2], tp[3]) end
                -- (NonRT-9) the beam stops on a body: the other player or an enemy in its way (the
                -- terrain ray goes through characters, so the beam and dot went on through them)
                L.on_body = nil
                if st.NON_RT then
                    local hit_t = st.laser_body_hit(mp, tip, body)
                    if hit_t then tip = Vector3f.new(mp.x + dx * hit_t, mp.y + dy * hit_t, mp.z + dz * hit_t); L.on_body = true end
                end
                pcall(function() wp:set_field("<LaserSightTipPosition>k__BackingField", tip) end)
            end
        end
        -- (NonRT-8) The laser object stays on the mod's own mount (the muzzle joint, 5 cm under,
        -- its mount angle), as on RT. On Non-RT player 1's sometimes drifted off it (seen ~5 m
        -- away): more than 0.5 m from the muzzle, it's mounted again on the next frame. The beam
        -- itself is placed below (NonRT-8b), from wherever the object is to the dot.
        if st.NON_RT and mp then
            local rp = safe(function() return L.go:call("get_Transform"):call("get_Position") end)
            if rp and (rp - mp):length() > 0.5 then L.owner = nil end
        end
        pcall(function() ctrl:call("lateUpdate") end)
        -- (NonRT-8b) and the line itself: on Non-RT the controller sometimes stopped moving it for
        -- a while (left at an old length while the dot moved on). Set here as the controller
        -- would: at the tip, facing back to the muzzle, 90 % of the distance long.
        if st.NON_RT and tip and mp then
            pcall(function()
                local line = ctrl:get_field("<Line>k__BackingField")
                local lx = line and line:call("get_Transform")
                local o = L.go:call("get_Transform"):call("get_Position")
                local dx, dy, dz = o.x - tip.x, o.y - tip.y, o.z - tip.z
                local dl = math.sqrt(dx * dx + dy * dy + dz * dz)
                if lx == nil or dl < 0.01 then return end
                local yaw = math.atan(dx, dz)
                local pitch = -math.asin(math.max(-1, math.min(1, dy / dl)))
                lx:call("set_Position", tip)
                lx:call("set_Rotation", Quaternion.new(math.cos(yaw / 2), 0, math.sin(yaw / 2), 0) * Quaternion.new(math.cos(pitch / 2), math.sin(pitch / 2), 0, 0))
                lx:call("set_LocalScale", Vector3f.new(1, 1, dl * 0.9))
            end)
        end
        local light = safe(function() return ctrl:get_field("<Light>k__BackingField") end)
        tip = tip or safe(function() return wp:get_field("<LaserSightTipPosition>k__BackingField") end)
        if light then
            pcall(function()
                if tip then light:call("get_Transform"):call("set_Position", tip) end
                -- (the dot is drawn over everything: with player 1 standing between the camera
                -- and where it lands it showed on her back. Hidden then; the beam itself is
                -- hidden behind her by the game.)
                if st.NON_RT then
                    -- (NonRT-11) the dot is drawn through everything (no depth test): on a body it
                    -- showed through to the far side, and through walls. Checked against each view
                    -- that's on screen (player 1's camera; player 2's in split screen): seen in all of
                    -- them -> the game's dot; in none -> hidden; in some -> hidden, and a dot is drawn
                    -- in just those views (L.dot2d, drawn below).
                    L.dot2d = nil
                    local vis, views = st.laser_dot_views(tip)
                    local n_vis = 0
                    for _, v in ipairs(views) do if v.vis then n_vis = n_vis + 1 end end
                    light:call("set_DrawSelf", tip ~= nil and n_vis == #views and n_vis > 0)
                    if tip and n_vis > 0 and n_vis < #views then
                        L.dot2d = { p = tip, views = views, col = s.laser_color or 0xFF0000FF }
                    end
                else
                    light:call("set_DrawSelf", for_p1 or not (tip and L.dot_hidden_by_p1(tip)))
                end
            end)
        end
    end
    -- player 1's body between the camera that's looking (player 2's in split screen, else the
    -- main one) and the laser's dot: a 0.33 m wide upright capsule from her feet to 1.8 m
    function L.dot_hidden_by_p1(tip)
        local p1 = p1_go()
        if p1 == nil then return false end
        local c
        if p2c.active and p2c.pos then c = p2c.pos
        else
            -- (the view's own spot: Classic Cameras moves the camera's joint, not its object, which
            -- stays behind player 1, so the line from there ran through her and hid the dot)
            local cam = sdk.get_primary_camera()
            c = cam and safe(function()
                local xf = cam:call("get_GameObject"):call("get_Transform")
                local j = xf:call("get_Joints")[0]
                return j and j:call("get_Position") or xf:call("get_Position")
            end)
        end
        if c == nil then return false end
        local f = p1:call("get_Transform"):call("get_Position")
        local dx, dy, dz = tip.x - c.x, tip.y - c.y, tip.z - c.z
        local len = math.sqrt(dx * dx + dy * dy + dz * dz)
        if len < 0.2 then return false end
        local n = math.max(8, math.floor(len / 0.1))
        for i = 1, n - 1 do
            local t = i / n
            if len * (1 - t) < 0.15 then break end   -- (right at the dot: that's where it lands)
            local x, y, z = c.x + dx * t, c.y + dy * t, c.z + dz * t
            if y > f.y and y < f.y + 1.8 and (x - f.x) ^ 2 + (z - f.z) ^ 2 < 0.33 * 0.33 then return true end
        end
        return false
    end
    re.on_application_entry("LateUpdateBehavior", function() pcall(update) end)
end
laser_unit(st.laser, "CoopP2LaserSight", false)
laser_unit(st.laser1, "CoopP1LaserSight", true)
end)()

-- (v384, the AI partner only) player 1 up or down a ladder, or down a drop / ledge (any gimmick
-- player jack): once she's off it, he's brought to her (teleport_to_p1) if it left them on
-- different levels (1 m up or down) or far apart (6 m). He doesn't climb after her himself.
ai.p1_jack = { owner = nil, start = nil, done_at = nil }
function ai.p1_jack_follow(lgo, hp, lp)
    local J = ai.p1_jack
    local jd = comp(lgo, "app.ropeway.JackDominator")
    local jacked = jd and safe(function() return jd:call("get_Jacked") end) == true
    local gb = nil
    if jacked then
        local own = safe(function() return jd:get_field("<JackOwner>k__BackingField") end)
        gb = own and safe(function() return own:get_field("<GimmickBody>k__BackingField") end)
        if gb and not safe(function() return gb:get_type_definition():is_a("app.ropeway.gimmick.action.PlayerJackBase") end) then gb = nil end
    end
    if gb then
        if J.owner == nil then J.owner, J.start = gb:get_address(), lp end
        J.done_at = nil
        return
    end
    if J.owner and not jacked then
        J.owner = nil
        J.done_at = os.clock() + 0.4   -- (let her finish stepping off first)
    end
    if J.done_at and os.clock() >= J.done_at then
        J.done_at = nil
        local dy = math.abs(hp[2] - lp[2])
        if dy > 1.0 or math.sqrt(dist2(hp, lp)) > 6.0 then
            pcall(teleport_to_p1)
            ai.trail, ai.nav.path = {}, nil
            ai.stuck.t, ai.stuck.pos = 0, nil
        end
    end
end

function ai.knife_refill()
    local hinv = comp(st.hunk, "app.ropeway.survivor.Inventory")
    local l = hinv and safe(function() return hinv:get_field("_Slots") end)
    for i = 0, (l and safe(function() return l:call("get_Count") end) or 0) - 1 do
        local sl = safe(function() return l:call("get_Item", i) end)
        if sl and safe(function() return sl:call("get_WeaponType") end) == 46 then
            local n = safe(function() return sl:call("get_Number") end) or 0
            local mx = safe(function() return sl:call("get_MaxNumber") end) or 0
            if mx <= 0 then mx = 1000 end
            if n < mx then safe(function() sl:call("set_Number", mx) end) end
        end
    end
end
-- (v399) Player 2's magazine reloads with his own inventory (Infinite ammo off). The game
-- reloads a magazine gun with Inventory.reloadMainSlot(-1) on HUNK - "fill it" - and for him
-- that fills it from nowhere (traced: LE 5 3 -> 32, its 100 rounds untouched); the shotgun calls
-- reloadMainSlot(1) per shell, which takes the shell from his stack. So for him a -1 becomes the
-- rounds the magazine is short, capped at what he carries of its ammo; with none it doesn't
-- reload at all. Even with a count the game's method only filled the magazine (LE 5: 29 asked,
-- 3 -> 32, stack still 100), so whatever it put in that his stacks didn't lose is taken off
-- them afterwards (the shotgun's shells it does take itself: nothing more is taken there).
;(function()
    local m = sdk.find_type_definition("app.ropeway.survivor.Inventory"):get_method("reloadMainSlot")
    if m == nil then return end
    local function stacks(hinv, bullet)
        local out, have = {}, 0
        local l = safe(function() return hinv:get_field("_Slots") end)
        for i = 0, (l and safe(function() return l:call("get_Count") end) or 0) - 1 do
            local sl = safe(function() return l:call("get_Item", i) end)
            if sl and safe(function() return sl:call("get_ItemID") end) == bullet then
                local n = safe(function() return sl:call("get_Number") end) or 0
                out[#out + 1] = { sl = sl, n = n }
                have = have + n
            end
        end
        return out, have
    end
    sdk.hook(m, function(args)
        thread.get_hook_storage().rl = nil
        if st.infinite_ammo or st.hunk == nil then return end
        local hinv = comp(st.hunk, "app.ropeway.survivor.Inventory")
        if hinv == nil or sdk.to_int64(args[2]) ~= hinv:get_address() then return end
        local want = sdk.to_int64(args[3]) & 0xFFFFFFFF
        if want ~= 0xFFFFFFFF then return end   -- (a set count, the shotgun's 1: the game's own)
        local main = safe(function() return hinv:call("get_MainSlot") end)
        local cur = main and safe(function() return main:call("get_Number") end)
        local max = main and safe(function() return main:call("get_MaxNumber") end)
        local bullet = main and safe(function() return main:call("get_BulletID") end)
        if not (cur and max and bullet and bullet > 0) then return end
        local _, have = stacks(hinv, bullet)
        local n = math.min(math.max(0, max - cur), have)
        st.p2_reload_note = { frame = st.frame, cur = cur, max = max, have = have, n = n }
        if n <= 0 then return sdk.PreHookResult.SKIP_ORIGINAL end
        args[3] = sdk.to_ptr(n)
        thread.get_hook_storage().rl = { hinv = hinv, main = main, cur = cur, bullet = bullet, have = have }
    end, function(r)
        local R = thread.get_hook_storage().rl
        if R == nil then return r end
        pcall(function()
            local now = R.main:call("get_Number") or R.cur
            local list, have = stacks(R.hinv, R.bullet)
            local owe = (now - R.cur) - (R.have - have)   -- put in, minus what the game already took
            for _, e in ipairs(list) do
                if owe <= 0 then break end
                local k = math.min(owe, e.n)
                if e.n - k > 0 then e.sl:call("set_Number", e.n - k)
                else R.hinv:call("removeSlot(app.ropeway.inventory.Slot, System.Boolean)", e.sl, false) end
                owe = owe - k
            end
            if st.p2_reload_note then st.p2_reload_note.took = (now - R.cur) end
        end)
        return r
    end)
end)()
-- (v429) Reloads that play but load nothing ("stuck" guns: the animation, no rounds, until the
-- ammo is combined by hand). Reported for both players, irregular.
-- * Logger: every Inventory.reloadMainSlot call (whose inventory it ran on, the gun, its ammo
--   type, rounds before / after, that ammo in that inventory, who is in a reload right now) goes
--   to reunited_p2_log.txt (st.p2log), so a report shows which way it went wrong.
-- * Watchdog (st.reload_guard, default on), a backup only: each player's reload is followed by
--   its motion (an fsm node with RELOAD in its name: layer 3 IDLE.RELOAD.RELOAD / MULTI_RELOAD /
--   END_RELOAD). When one ends after at least 0.7 s, the game having called reloadMainSlot
--   during it (it reached its loading step, so it wasn't cut short), with the same gun
--   equipped, its magazine not fuller and not full, while that player carries rounds for it,
--   the mod loads it from that player's own
--   stacks (as a combine would): whatever went wrong - the call landing on the other player's
--   inventory, or the gun's ammo type (Slot.BulletID) not matching its rounds - the reload
--   still loads and nobody stays stuck. A wrong ammo type is corrected first (from the weapon
--   type, st WEAPONS table).
;(function()
    local INV = sdk.find_type_definition("app.ropeway.survivor.Inventory")
    local m = INV and INV:get_method("reloadMainSlot")
    st.reload_guard = st.reload_guard ~= false
    local R = { p = {} }
    st.rl = R
    local function inv_of(go) return go and comp(go, "app.ropeway.survivor.Inventory") or nil end
    local function who(addr)
        local a = inv_of(p1_go()); local b = inv_of(st.hunk)
        if a and a:get_address() == addr then return "P1" end
        if b and b:get_address() == addr then return "P2" end
        return "other"
    end
    local function count_of(inv, id)
        local have, list = 0, {}
        if inv == nil or id == nil or id <= 0 then return 0, list end
        local l = safe(function() return inv:get_field("_Slots") end)
        for i = 0, (l and safe(function() return l:call("get_Count") end) or 0) - 1 do
            local sl = safe(function() return l:call("get_Item", i) end)
            if sl and safe(function() return sl:call("get_ItemID") end) == id then
                local n = safe(function() return sl:call("get_Number") end) or 0
                have = have + n
                list[#list + 1] = { sl = sl, n = n }
            end
        end
        return have, list
    end
    R.count_of = count_of
    local function reload_node(go)
        local fsm = go and comp(go, "via.motion.MotionFsm2")
        if fsm == nil then return nil end
        for l = 0, 4 do
            local nm = safe(function() return fsm:call("getCurrentNodeName", l) end)
            if nm and tostring(nm):find("RELOAD", 1, true) then return tostring(nm) end
        end
        return nil
    end
    local function gun(inv)
        local main = inv and safe(function() return inv:call("get_MainSlot") end)
        if main == nil then return nil end
        local wt = safe(function() return main:call("get_WeaponType") end) or -1
        if wt <= 0 or wt == 46 or wt == 65 or wt == 66 then return nil end
        return main, wt
    end
    -- the logger
    if m then
        sdk.hook(m, function(args)
            local s = thread.get_hook_storage()
            s.rlog = nil
            pcall(function()
                local addr = sdk.to_int64(args[2])
                local inv = sdk.to_managed_object(args[2])
                local main, wt = gun(inv)
                local want = sdk.to_int64(args[3]) & 0xFFFFFFFF
                local cur = main and safe(function() return main:call("get_Number") end)
                local mx = main and safe(function() return main:call("get_MaxNumber") end)
                local b = main and safe(function() return main:call("get_BulletID") end)
                local have = count_of(inv, b)
                s.rlog = { who = who(addr), main = main, wt = wt, b = b, cur = cur, mx = mx, have = have,
                    want = want == 0xFFFFFFFF and "fill" or tostring(want) }
            end)
        end, function(r)
            local L = thread.get_hook_storage().rlog
            R.last_call = st.frame   -- (the game reached the point of loading: see watch)
            if L and st.p2log then
                pcall(function()
                    local after = L.main and safe(function() return L.main:call("get_Number") end)
                    local ok = WEAPON_BY_WT[L.wt or -1] and WEAPON_BY_WT[L.wt].ammo
                    st.p2log(string.format("reload call on %s's inventory: %s, ammo type %s%s, %s/%s -> %s (%s), that ammo carried %s; reloading now: P1 %s, P2 %s",
                        L.who, tostring(WEAPON_BY_WT[L.wt or -1] and WEAPON_BY_WT[L.wt].name or L.wt), tostring(L.b),
                        (ok and L.b ~= ok) and (" (expected " .. ok .. ")") or "", tostring(L.cur), tostring(L.mx), tostring(after), L.want,
                        tostring(L.have), tostring(reload_node(p1_go()) ~= nil), tostring(reload_node(st.hunk) ~= nil)))
                end)
            end
            return r
        end)
    end
    -- the watchdog
    local function rescue(tag, go, inv, main, wt, cur)
        local w = WEAPON_BY_WT[wt]
        local b = safe(function() return main:call("get_BulletID") end) or 0
        local have = count_of(inv, b)
        local fixed_type
        if have <= 0 and w and w.ammo and w.ammo ~= b then
            local h2 = count_of(inv, w.ammo)
            if h2 > 0 then
                pcall(main.call, main, "set_BulletID", w.ammo)
                fixed_type = b
                b, have = w.ammo, h2
            end
        end
        local mx = safe(function() return main:call("get_MaxNumber") end) or 0
        local n = math.min(math.max(0, mx - cur), have)
        if n <= 0 then
            if st.p2log then st.p2log(string.format("reload loaded nothing for %s (%s %d/%d), and no rounds for it carried (ammo type %s)", tag, tostring(w and w.name or wt), cur, mx, tostring(b))) end
            return
        end
        local _, list = count_of(inv, b)
        local owe = n
        for _, e in ipairs(list) do
            if owe <= 0 then break end
            local k = math.min(owe, e.n)
            if e.n - k > 0 then pcall(e.sl.call, e.sl, "set_Number", e.n - k)
            else pcall(inv.call, inv, "removeSlot(app.ropeway.inventory.Slot, System.Boolean)", e.sl, false) end
            owe = owe - k
        end
        pcall(main.call, main, "set_Number", cur + (n - owe))
        R.rescues = (R.rescues or 0) + 1
        if st.p2log then
            st.p2log(string.format("reload loaded nothing for %s (%s %d/%d): loaded %d from their own ammo%s", tag, tostring(w and w.name or wt), cur, mx, n - owe,
                fixed_type and (" (its ammo type was " .. tostring(fixed_type) .. ", set to " .. tostring(b) .. ")") or ""))
        end
    end
    local function watch(tag, go)
        local P = R.p[tag] or {}
        R.p[tag] = P
        if go == nil then R.p[tag] = {}; return end
        local inv = inv_of(go)
        local main, wt = gun(inv)
        local node = reload_node(go)
        if node and not P.on then
            P.on, P.t0, P.f0, P.node = true, os.clock(), st.frame, node
            P.main = main and main:get_address() or nil
            P.cur = main and safe(function() return main:call("get_Number") end) or nil
        elseif node and P.on and main and P.main == main:get_address() then
            local n = safe(function() return main:call("get_Number") end)
            if n and P.cur and n > P.cur then P.loaded = true end
        elseif not node and P.on then
            P.on = false
            local long = os.clock() - (P.t0 or os.clock()) >= 0.7
            -- only a reload the game carried through to its loading step (it called
            -- reloadMainSlot during it, on whichever inventory): a reload cut short by a hit, a
            -- grab or the player before that point is not stuck and gets nothing
            local reached = R.last_call ~= nil and P.f0 ~= nil and R.last_call >= P.f0
            if main and P.main == main:get_address() and long and reached and not P.loaded and P.cur then
                local n = safe(function() return main:call("get_Number") end) or 0
                local mx = safe(function() return main:call("get_MaxNumber") end) or 0
                if n <= P.cur and n < mx then
                    if st.p2log then st.p2log(string.format("%s's reload (%s) ended with nothing loaded", tag, tostring(P.node))) end
                    if st.reload_guard and not (tag == "P2" and st.infinite_ammo) then pcall(rescue, tag, go, inv, main, wt, n) end
                end
            end
            P.loaded, P.main, P.cur = nil, nil, nil
        end
    end
    re.on_frame(function()
        pcall(watch, "P1", p1_go())
        pcall(watch, "P2", st.hunk)
    end)
end)()
