        local p1 = np >= 1 and safe(function() return m:get_param_types()[1]:get_full_name() end)
        if (n == "reduceSlot" or n == "removeSlot") and p1 == "app.ropeway.inventory.Slot" then
            sdk.hook(m, function(args)
                if not ai.active then return end
                return keep(args, safe(function() return sdk.to_managed_object(args[3]) end), n == "removeSlot")
            end, function(r) return r end)
        elseif n == "removeSubSlot" and np == 0 then
