    local ER = sdk.find_type_definition("app.ropeway.enemy.EnemySupportItemReceiver")
    local ak = ER and ER:get_method("addKnifeInfo")
    if ak then
        sdk.hook(ak, function(args)
            if ai.knife_kept and st.frame - ai.knife_kept <= 2 then
                ai.knife_saves = (ai.knife_saves or 0) + 1
                return sdk.PreHookResult.SKIP_ORIGINAL
            end
        end, function(r) return r end)
    end
end)()
-- (v390) the game's grab prompt (GUI_DefenseItemGuide, "press to counter") is hidden while
-- the AI partner alone is held: nobody presses it, the AI counters by itself
function st.ai_guide_hide()
    local G = st.ai_guide or {}
    st.ai_guide = G
    local hide = ai.active and st.p2_held_only == true
    if not hide and not G.hidden then return end
    if G.go == nil or safe(function() return G.go:call("get_Valid") end) ~= true then
        if st.frame < (G.next_find or 0) then return end
        G.next_find = st.frame + 60
        local sc = sdk.call_native_func(sdk.get_native_singleton("via.SceneManager"), sdk.find_type_definition("via.SceneManager"), "get_CurrentScene")
        local go = sc and safe(function() return sc:call("findGameObject(System.String)", "GUI_DefenseItemGuide") end)
        G.go = go and go:add_ref() or nil
        if G.go == nil then G.hidden = false; return end
    end
    if hide then
        if not G.hidden then G.was = safe(function() return G.go:call("get_DrawSelf") end); G.hidden = true end
        pcall(function() G.go:call("set_DrawSelf", false) end)
    else
        pcall(function() G.go:call("set_DrawSelf", G.was ~= false) end)
        G.hidden = false
    end
end
-- the knife as HUNK's sub weapon (knifing, and the counter when grabbed); true when he has
-- it in hand. (A knife used to counter a grab stays stuck in the enemy, as in the game:
-- without one he doesn't raise an empty hand to knife with.)
function ai.knife_sub()
    if st.p2_unarmed and st.p2_unarmed() then return false end   -- (v407/v408: unarmed)
    local heq = comp(st.hunk, "app.ropeway.survivor.Equipment")
    if heq == nil then return false end
    if safe(function() return heq:call("get_SubType") end) == 46 then return true end
    local hinv = comp(st.hunk, "app.ropeway.survivor.Inventory")
    local ks = KNIFE_SLOT
    if not st.infinite_ammo and st.p2inv and hinv then
        ks = nil
        for _, e in ipairs(st.p2inv.list(hinv)) do if e.wt == 46 then ks = e.i; break end end
    end
    if hinv and ks then safe(function() hinv:call("set_SubSlot", hinv:call("getSlot(System.Int32)", ks)) end) end
    return safe(function() return heq:call("get_SubType") end) == 46
end
-- (v390) the knife fight, one frame. kn: { pos (aim point), d (flat distance), down }.
-- Knife up and turned square on as it closes in; swung (a short tap every 12 frames) only
-- inside reach and within ~25 degrees of facing it: swings from 2 m used to whiff, and the
-- zombie grabbed him as it arrived. Returns false (nothing done) without a knife.
function ai.knife_frame(hp, kn, dt)
    if not ai.knife_sub() then return false end
    ai.aim_pos = kn.pos
    ai.keys[128] = true   -- SUPPORT_HOLD: knife up
    ai_stick(0, 0)
    local want = math.atan(kn.pos[1] - hp[1], kn.pos[3] - hp[3])
    pcall(st.split_turn, want)
    local f = safe(function() return st.hunk:call("get_Transform"):call("get_Rotation") * Vector3f.new(0, 0, 1) end)
    local err = f and math.abs(math.atan(math.sin(want - math.atan(f.x, f.z)), math.cos(want - math.atan(f.x, f.z)))) or 0
    ai.melee_t = (ai.melee_t or 0) + dt
    -- (standing: from 1.35 m. Hits land at 0.9 - 1.1 m; swinging from 1.75 m whiffed and
    -- left him mid-swing as it walked in and grabbed him)
    local reach = kn.down and 1.35 or 1.35
    if ai.melee_t > 0.15 and kn.d < reach and err < 0.45 then
        ai.knife_n = (ai.knife_n or 0) + 1
        if ai.knife_n % 12 < 2 then ai.keys[KIND.ATTACK] = true end
    else
        ai.knife_n = 0
    end
    -- right on top of him (under 0.8 m, standing): a step back between swings, so it isn't
    -- grabbing range the whole time (it closed to 0.4 m and grabbed after three hits)
    if not kn.down and kn.d < 0.8 then
        local ax, az = hp[1] - kn.pos[1], hp[3] - kn.pos[3]
        local l = math.max(0.01, math.sqrt(ax * ax + az * az))
        local sx, sz = ai.steer_dir(hp, ax / l, az / l)
        if sx then ai_walk_to(hp, { hp[1] + sx * 1.2, hp[2], hp[3] + sz * 1.2 }, false, true) end
    end
    ai.state = kn.down and "knifing (on the floor)" or "knifing"
    return true
end
local function update_ai(dt)
    -- last frame's buttons become "previous" so isDown / isUp see the edges
    ai.prev = ai.keys
    ai.keys = {}
    ai.moving = false
    local lgo = p1_go()
    local event = st.in_cutscene()
    local want = st.ai and st.hunk ~= nil and lgo ~= nil and not event and not p2c.active
    if not want then
        if ai.active then ai.active = false; ai_reset(); ai.order = { move = "follow", fire = "free" } end
        ai.state = not st.ai and "off" or (st.hunk == nil and "no HUNK" or "waiting")
        return
    end
    ai.active = true
    -- (v395) his knife's wear put back (the hit / counter wear doesn't go through the
    -- Inventory calls hooked below: a counter cost ~230, a hit ~10-15)
    if st.frame % 20 == 0 then pcall(ai.knife_refill) end
    -- (v390) grabbed (and player 1 isn't): the counter. The game's defense-item button
    -- (InputDefine.Kind 4096) is read through route while player 2 alone is held (see the
    -- InputSystem hook); tapped every 8 frames with the knife as sub weapon.
    if st.p2_held_only then
        ai.held_n = (ai.held_n or 0) + 1
        -- (v407) Biohazard Babysitting: she waits; the flash grenade counter only once player 1
        -- has hit the zombie (st.bb.press)
        if st.bb_on and st.bb_on() then
            if st.bb.press and ai.held_n % 8 < 2 then ai.keys[4096] = true end
            ai_stick(0, 0)
            ai.state = st.bb.press and "grabbed: rescued" or "grabbed: waiting for rescue"
            return
        end
        if ai.held_n == 1 then pcall(ai.knife_sub) end
        if ai.held_n > 6 and ai.held_n % 8 < 2 then ai.keys[4096] = true end
        ai_stick(0, 0)
        ai.state = "grabbed: countering"
        return
    end
    ai.held_n = 0
    local hp = v3(st.hunk:call("get_Transform"):call("get_Position"))
    local lp = v3(lgo:call("get_Transform"):call("get_Position"))
    update_trail(lp)
    if ai.order.move == "follow" or ai.order.move == "regroup" then pcall(ai.p1_jack_follow, lgo, hp, lp) end
    local d_leon = math.sqrt(dist2(hp, lp))
    local now = os.clock()

    local o = ai.order
    local with_p1 = o.move == "follow" or o.move == "regroup"
    -- (distance catch-up teleport switched off for now: he walks Leon's path instead, and
    -- only hops when stuck, to a spot out of Leon's view)

    pcall(ai_support, lgo)

    -- Fire with me + knife: each knife swing of player 1 counts as a shot to fire along with
    local knife = o.fire == "sync" and ai.p1_knife()
    if knife and ai.p1_attack_pressed() then ai.p1_shot_frame = st.frame end
    -- ...and so does each pull of the trigger with a gun up, even with an empty gun
    -- (held down with an automatic: every frame, like the real shots)
    if o.fire == "sync" and not knife and ai.p1_aiming() then
        local pr = ai.p1_attack_pressed()
        if pr and (not ai.p1_pr or ai.p1_auto) then ai.p1_shot_frame = st.frame end
        ai.p1_pr = pr
    else
        ai.p1_pr = false
    end

    -- a gun in hand (after a load HUNK can come back holding nothing)
    if st.frame >= (ai.next_equip or 0) then
        ai.next_equip = st.frame + 30
        local heq = comp(st.hunk, "app.ropeway.survivor.Equipment")
        local wt = heq and safe(function() return heq:call("get_EquipType") end)
        ai.wt = wt
        local peq = comp(lgo, "app.ropeway.survivor.Equipment")
        ai.p1_auto = AI_AUTO[peq and safe(function() return peq:call("get_EquipType") end) or 0] == true
        if (wt == 0 or wt == 46 or wt == 65 or wt == 66) and not ai.out then
            local hinv = comp(st.hunk, "app.ropeway.survivor.Inventory")
            if hinv then safe(function() hinv:call("equipSlot(System.Int32)", st.default_weapon_slot) end) end
        end
    end
    if st.infinite_ammo then
        ai.out, ai.reload_until = false, nil
    else
        if st.frame >= (ai.next_ammo or 0) then ai.next_ammo = st.frame + 10; pcall(ai.ammo_check) end
        if ai.reload_until and st.frame < ai.reload_until then ai.keys[512] = true; ai.state = "reloading" end   -- RELOAD
    end

    -- targets (rescanned a few times a second; line-of-sight rays are not free)
    if st.frame >= ai.next_scan then
        ai.next_scan = st.frame + 8
        local eye = { hp[1], hp[2] + AI_EYE, hp[3] }
        local function aim_at(e)
            local k, p = visible_point(eye, e.go)
            if not k then return nil end
            return { go = e.go, ctrl = e.ctrl, pos = p, k = k,
                dist = math.sqrt((p[1] - eye[1]) ^ 2 + (p[2] - eye[2]) ^ 2 + (p[3] - eye[3]) ^ 2) }
        end
        if o.attack and not enemy_valid(o.attack.ctrl) then
            o.attack = nil
            ai.say("Target down")
        end
        if o.attack then
            ai.target = aim_at(o.attack)   -- player 1's pick, as soon as it's in sight
        elseif o.fire == "hold" then
            ai.target = nil
        else
            -- holding a spot: fight whatever comes near him, wherever player 1 is
            ai.target = (not with_p1 or d_leon < 10) and ai_pick_target(hp, lp) or nil
            if o.fire == "sync" then   -- shooting together: player 1's target first
                local e = ai.p1_aim_enemy()
                local t = e and aim_at(e)
                if t then ai.target = t end
            end
        end
        -- player 1 raises a gun: raise ours and cover the same spot (when he isn't busy
        -- with an enemy of his own, or always when firing together), as long as he
        -- doesn't have to walk to keep up
        local settled = (o.move == "follow" and d_leon < (st.ai_follow_dist or 2.0) + 1.5) or (o.move == "hold" and o.pos and dist2(o.pos, hp) < 1.5)
            or (o.move == "guard" and o.pos and dist2(o.pos, hp) < 16)
        if settled and not o.attack and o.fire ~= "hold" and (ai.p1_aiming() or knife) and (ai.target == nil or o.fire == "sync")
            and (st.ai_mirror or o.fire == "sync") then
            local p, e = ai.p1_aim_point()
            if p and not (e and ai.target and ai.target.go == e.go) then ai.target = { pos = p, p1aim = true } end
        end
    elseif ai.target and ai.target.p1aim then
        if not (ai.p1_aiming() or knife) then
            ai.target = nil
        elseif st.frame % 2 == 0 then
            local p = ai.p1_aim_point()
            if p then ai.target.pos = p end
        end
    elseif ai.target and ai.target.go then
        local ok, p, down = pcall(enemy_aim_point, ai.target.go, ai.target.k)
        if ok and p and enemy_valid(ai.target.ctrl) then
            ai.target.pos, ai.target.down = p, down
            ai.target.dist = math.sqrt((p[1] - hp[1]) ^ 2 + (p[2] - hp[2] - AI_EYE) ^ 2 + (p[3] - hp[3]) ^ 2)
        else
            ai.target = nil   -- died: next scan picks a new one
        end
    end

    -- keep out of player 1's line of fire while he aims
    if st.ai_dodge and ai.p1_aiming() and not o.attack then
        local ro, rd = ai.p1_ray()
        if ro then
            local q = { hp[1] - ro[1], hp[2] + 1.2 - ro[2], hp[3] - ro[3] }
            local along = q[1] * rd[1] + q[2] * rd[2] + q[3] * rd[3]
            local px, py, pz = q[1] - rd[1] * along, q[2] - rd[2] * along, q[3] - rd[3] * along
            if along > 0.5 and along < 30 and px * px + py * py + pz * pz < 0.55 then
                -- step sideways, away from the line
                local sx, sz = rd[3], -rd[1]
                local sl = math.max(0.01, math.sqrt(sx * sx + sz * sz))
                sx, sz = sx / sl, sz / sl
                if sx * px + sz * pz < 0 then sx, sz = -sx, -sz end
                ai_walk_to(hp, { hp[1] + sx * 1.4, hp[2], hp[3] + sz * 1.4 }, false)
                if ai.target then ai.aim_pos = ai.target.pos; ai.keys[KIND.HOLD] = true end
                ai.state = "out of your line of fire"
                return
            end
        end
    end

    -- an enemy right on top of him: back off while shooting; boxed in, use the knife
    local close = ai.close
    if close and close.go then
        local okc, cp = pcall(enemy_aim_point, close.go, 1)
        if okc and cp and enemy_valid(close.ctrl) then
            close.pos, close.d = cp, math.sqrt(dist2(cp, hp))
        else
            ai.close, close = nil, nil
        end
    end
    -- (out of ammo: the knife from further off, whatever's around)
    if (st.ai_knife or ai.out) and close and close.d < (ai.out and 2.5 or 1.5) and o.fire ~= "hold" then
        local ax, az = hp[1] - close.pos[1], hp[3] - close.pos[3]
        local sx, sz = ai.steer_dir(hp, ax, az)
        local cornered = sx == nil or (sx * ax + sz * az) / math.max(0.01, math.sqrt(ax * ax + az * az)) < 0.2
        -- (v390: from 1.3 m, not 0.9: a zombie at 0.9 m is already grabbing)
        if (cornered or close.d < 1.3 or ai.out) and ai.knife_frame(hp, close, dt) then return end
    end
    -- (v390) one down at his feet (crawling, knocked over): knife it while it's down
    local cdn = ai.close_down
    if cdn and cdn.go and (st.ai_knife or ai.out) and o.fire ~= "hold" then
        local okd, dp = pcall(enemy_aim_point, cdn.go, 2)
        if okd and dp and enemy_valid(cdn.ctrl) then
            cdn.pos, cdn.d = dp, math.sqrt(dist2(dp, hp))
            if cdn.d < (ai.out and 1.8 or 1.4) and ai.knife_frame(hp, cdn, dt) then return end
        else
            ai.close_down = nil
        end
    end
    ai.melee_t = 0

    -- orders first: walk where he's been told, fighting on the way; a long way to go, he
    -- lowers the gun and runs (handled with the plain moving further down)
    local mg, mfar, mslow = ai.move_goal(hp, lp, d_leon, o, ai.target ~= nil)
    if ai.target and not (mg and mfar) then
        ai.aim_pos = ai.target.pos
        ai.keys[KIND.HOLD] = true
        ai_stick(0, 0)
        local moved = false
        if mg then
            ai_walk_to(hp, mg, false, mslow)
            moved = true
        end
        -- give ground to anything closing in (shooting as he goes)
        if st.ai_backoff and not moved and close and close.d < 2.3 and o.move ~= "hold" then
            local ax, az = hp[1] - close.pos[1], hp[3] - close.pos[3]
            local sx, sz = ai.steer_dir(hp, ax, az)
            if sx then
                ai_walk_to(hp, { hp[1] + sx * 1.5, hp[2], hp[3] + sz * 1.5 }, false)
                moved = true
            end
        end
        ai.aim_t = ai.aim_t + dt
        ai.state = mg and "moving, shooting" or "shooting"
        -- fight from the weapon's range (not when told to stay put)
        if st.ai_ranges and not moved and ai.target.go and not ai.target.p1aim and o.move ~= "hold" and o.move ~= "goto" then
            local ok, m = pcall(ai.keep_range, hp, lp, o)
            moved = ok and m
        end
        -- Leon in the line of fire: hold fire and step to the side
        local t = ai.aim_pos
        local ex, ey, ez = hp[1], hp[2] + 1.4, hp[3]
        local dx, dy, dz = t[1] - ex, t[2] - ey, t[3] - ez
        local len = math.max(0.01, math.sqrt(dx * dx + dy * dy + dz * dz))
        dx, dy, dz = dx / len, dy / len, dz / len
        local lx, ly, lz = lp[1] - ex, lp[2] + 1.0 - ey, lp[3] - ez
        local along = lx * dx + ly * dy + lz * dz
        local blocked = false
        if along > 0 and along < len then
            local px, py, pz = lx - dx * along, ly - dy * along, lz - dz * along
            blocked = px * px + py * py + pz * pz < 0.36
        end
        if blocked then
            -- sidestep perpendicular to the shot, away from Leon
            local side = (dx * lz - dz * lx) > 0 and -1 or 1
            ai_walk_to(hp, { hp[1] - dz * side * 1.5, hp[2], hp[3] + dx * side * 1.5 }, false)
            ai.state = "Leon in the way"
            ai.stuck.t = 0
            return
        end
        -- a knocked-down enemy far away mostly eats floor: keep aiming, shoot once it's close
        local hold_fire = ai.target.down and (ai.target.dist or 0) > 6
        if hold_fire then ai.state = "watching a downed enemy" end
        -- "fire when I fire": aim and wait, pull the trigger only right after player 1 shoots
        local p1_shot = st.frame - (ai.p1_shot_frame or -1000) <= 15
        if o.fire == "sync" and not o.attack and not p1_shot then
            hold_fire = true
            ai.state = "waiting for your shot"
        end
        if ai.target.p1aim then
            -- covering player 1's aim: only shoot it when firing together and he shoots
            if not (o.fire == "sync" and p1_shot) then hold_fire = true end
            ai.state = p1_shot and o.fire == "sync" and "firing with you" or "aiming with you"
        end
        if o.fire == "hold" then hold_fire = true end
        if ai.out then hold_fire = true; ai.state = "out of ammo" end
        if ai.EXPLOSIVE[ai.wt or 0] and len < 3 then hold_fire = true; ai.state = "too close for explosives" end
        -- only shoot with a shot; firing together, player 1 calls it
        if st.ai_clear_shot and not hold_fire and not ai.target.p1aim and not (o.fire == "sync" and p1_shot) then
            local ok, why = ai.has_shot(hp, ai.target)
            if ok then
                ai.noshot_t = 0
            else
                hold_fire = true
                ai.state = why == "turning" and "turning to aim" or "no clear shot"
                if why ~= "turning" then
                    ai.noshot_t = (ai.noshot_t or 0) + dt
                    if ai.noshot_t > 0.8 then   -- give up on it: another target, or a step to the side
                        if ai.target.go then ai.blocked[ai.target.go:get_address()] = math.max(ai.blocked[ai.target.go:get_address()] or 0, st.frame + 90) end
                        ai.noshot_t = 0
                        ai.next_scan = st.frame
                    end
                end
            end
        end
        -- short-range guns (shotgun, flamethrower, Spark Shot) don't waste shots on far enemies
        local band = ai.BANDS[ai.wt or 0]
        if st.ai_ranges and not hold_fire and band and band[2] <= 8 and not ai.target.p1aim and len > band[2] + 3
            and not (o.fire == "sync" and p1_shot) then
            hold_fire = true
            if not moved then ai.state = "out of range" end
        end
        if ai.aim_t > 0.4 and not hold_fire and hunk_is_aiming() then
            local heq = comp(st.hunk, "app.ropeway.survivor.Equipment")
            local wt = heq and safe(function() return heq:call("get_EquipType") end) or 0
            if AI_AUTO[wt] then
                ai.keys[KIND.ATTACK] = true
            elseif o.fire == "sync" and not o.attack then
                -- one shot for each of player 1's, as soon as he's ready
                if ai.sync_fired ~= ai.p1_shot_frame then
                    ai.sync_fired = ai.p1_shot_frame
                    ai.sync_until = st.frame + 3
                end
                if st.frame < (ai.sync_until or 0) then ai.keys[KIND.ATTACK] = true end
            else
                ai.fire_n = ai.fire_n + 1
                if ai.fire_n % (AI_PERIOD[wt] or 18) < 3 then ai.keys[KIND.ATTACK] = true end
            end
        end
        ai.stuck.t = 0
        return
    end
    ai.aim_pos, ai.aim_t, ai.fire_n = nil, 0, 0

    -- hold / go to a spot
    if o.move == "hold" or o.move == "goto" or o.move == "guard" then
        local guard = o.move == "guard"
        -- guarding: free to step around the spot for a clear shot
        local r = guard and ai.reposition
        if r and st.frame < r.until_frame and dist2(r, o.pos) < 16 and dist2(r, hp) > 0.16 then
            ai_walk_to(hp, r, false)
            ai.state = "getting a clear shot"
            return
        end
        ai.reposition = nil
        local d = math.sqrt(dist2(o.pos, hp))
        local off = (o.move == "goto" and d > 0.35) or (o.move == "hold" and d > 1.2)
            or (guard and d > (o.arrived and 1.2 or 0.5))
        if off then
            ai_walk_to(hp, o.pos, o.move ~= "hold" and d > 4, d < 1.2)
            ai.state = o.move == "goto" and "moving to position" or (guard and not o.arrived and "moving to guard spot")
                or "returning to position"
            local s = ai.stuck
            if s.pos == nil or dist2(s.pos, hp) > 0.25 then
                s.pos, s.t = hp, 0
            else
                s.t = s.t + dt
                if s.t > 3 then
                    s.t, s.pos = 0, nil
                    if guard then
                        o.pos, o.arrived = hp, true
                        ai.say("Can't get there, guarding here")
                    else
                        o.move, o.pos = "hold", hp
                        ai.say("Can't get there, holding here")
                    end
                end
            end
        else
            if o.move == "goto" then o.move = "hold"; ai.say("In position") end
            if guard and not o.arrived then o.arrived = true; ai.say("Guarding") end
            ai_stick(0, 0)
            ai.stuck.t, ai.stuck.pos = 0, nil
            ai.state = guard and "guarding" or "holding position"
        end
        return
    end
    if o.move == "regroup" and d_leon < 2.5 then o.move = "follow" end

    -- an enemy is close but blocked: step to where HUNK can see it
    local r = ai.reposition
    if r and st.frame < r.until_frame and not ai.follow and dist2(r, lp) < ((st.ai_follow_dist or 2.0) + 2) ^ 2
        and dist2(r, hp) > 0.16 then
        ai_walk_to(hp, r, false)
        ai.state = "getting a clear shot"
        return
    end
    ai.reposition = nil

    -- follow: start walking past 3 m, stop inside 2 m ("stay close": 1.8 m / 1.1 m)
    local go_on = mg ~= nil   -- ai.move_goal: past the set distance (with a little slack)
    if not go_on then
        ai_stick(0, 0)
        ai.stuck.t, ai.stuck.pos = 0, nil
        ai.state = "following"
        return
    end
    ai_walk_to(hp, mg, d_leon > (st.ai_follow_dist or 2.0) + 2.5 or o.move == "regroup")
    ai.state = o.move == "regroup" and "regrouping" or "following"
    -- (v383) a door between him and player 1: through it the way player 2's A does it
    -- (st.door_through: opened like player 1's door, else a step to the other side once the
    -- rooms there are in). Only at a door he's next to, with her on its other side.
    if d_leon > 2.0 and now >= (ai.next_door or 0) and st.find_door then
        local door = safe(st.find_door)
        if door and safe(function() return door:call("get_IsLocked") end) == false then
            local sh = safe(function() return door:call("calcSide", Vector3f.new(hp[1], hp[2], hp[3])) end)
            local sl = safe(function() return door:call("calcSide", Vector3f.new(lp[1], lp[2], lp[3])) end)
            if sh ~= nil and sl ~= nil and sh ~= sl and sh ~= 2 and sl ~= 2 then
                ai.next_door = now + 1.5
                if safe(function() return st.door_through(door) end) then
                    ai.trail, ai.nav.path = {}, nil
                    ai.stuck.t, ai.stuck.pos = 0, nil
                    ai.state = "through a door"
                end
            end
        end
    end
    -- stuck on something: hop over to Leon
    local s = ai.stuck
    if s.pos == nil or dist2(s.pos, hp) > 0.25 then
        s.pos, s.t, s.replanned = hp, 0, nil
    else
        s.t = s.t + dt
        if s.t > 1.0 and not s.replanned then ai.nav.path, s.replanned = nil, true end   -- caught on something: plan again
        if s.t > 2.5 and now >= ai.next_tp then
            ai.next_tp = now + 3
            s.t, s.pos = 0, nil
            if not st.ai_unstuck then
                ai.state = "stuck"
            elseif ai.warp_offscreen(lp) then
                ai.state = "unstuck"
            else
                s.long = (s.long or 0) + 1
                if s.long >= 4 then   -- ~10 s with nowhere hidden to go: last resort
                    s.long = 0
                    pcall(teleport_to_p1)
                    ai.trail = {}
                end
            end
        end
    end
end

-- with the AI on, HUNK comes back on his own (start of play, after the game unloads him)
local function update_ai_spawn()
    if not st.ai or st.hunk ~= nil or st.pending ~= nil or st.ai_no_spawn or st.unloading then return end
    if os.clock() < ai.next_spawn or p1_go() == nil then return end
    if st.in_cutscene() then return end
    ai.next_spawn = os.clock() + 5
    pcall(refresh_owners)   -- after a script reset HUNK may still be in the scene: adopt him
    if st.hunk == nil then pcall(spawn) end
end

-- Unarmed Sherry (v408) ------------------------------------------------------------------------
-- Player 2 > Character > Unarmed (st.sherry_unarmed, only offered for Sherry): she carries
-- nothing in either hand. Every equip call on her inventory is refused (the hook in the
-- Babysitting block below, which Babysitting shares), whatever is in her hands is put away
-- every 10 frames (only when something is: unequipping an empty hand restarted her action and
-- she glided on), and the AI partner holds fire, has no knife and doesn't talk about guns. Her
-- inventory itself is untouched; turning it off lets the AI pick its gun up again (fire order
-- back to "free"), a person equips as usual. She stays invincible and can't be grabbed.
function st.p2_unarmed()
    if st.bb_on and st.bb_on() then return true end
    return st.sherry_unarmed == true and st.p2_model == "sherry" and st.p2_child()
end
function st.unarmed_tick()
    local on = st.p2_unarmed() and not (st.bb_on and st.bb_on())
    if not on then
        if st.unarmed_was then
            st.unarmed_was = nil
            if ai.order and ai.order.fire == "hold" then ai.order.fire = "free" end
        end
        return
    end
    st.unarmed_was = true
    if st.ai_partner() and ai.order then ai.order.fire = "hold"; ai.order.attack = nil end
    if st.frame % 10 ~= 0 or st.pending or st.hunk == nil then return end
    local hinv = comp(st.hunk, "app.ropeway.survivor.Inventory")
    local heq = comp(st.hunk, "app.ropeway.survivor.Equipment")
    if hinv == nil or heq == nil then return end
    local et = safe(function() return heq:call("get_EquipType") end)
    if et and et ~= 0 and et ~= -1 then
        pcall(function() local m = hinv:call("get_MainSlot"); if m then hinv:call("unequipMainSlot(app.ropeway.inventory.Slot)", m) end end)
    end
    local sub = safe(function() return heq:call("get_SubType") end)
    if sub and sub ~= 0 and sub ~= -1 then
        pcall(function() local m = hinv:call("get_SubSlot"); if m then hinv:call("unequipSubSlot(app.ropeway.inventory.Slot)", m) end end)
    end
end

-- Biohazard Babysitting (v407, experimental) --------------------------------------------------
-- (v408: ON THE BACKLOG. st.BB_ENABLED = false hides it from Ways to play and keeps it off; a
-- config saved with it falls back to AI Companion, and its leftovers are cleared.)
-- A way of play (st.WAYS "babysit"): the AI partner is always Sherry, unarmed, and the
-- enemies go for her. It's the only time she can be grabbed. Anything that would hurt her ends
-- the game (the game's own game over, MainFlowManager.goGameOver); she never takes damage.
-- A grab: the moment it starts (her IsJackFromEnemy), she and the enemy are frozen (motion layer
-- 0 speed 0), before any bite. Player 1 has the rescue window (st.bb_window: Forgiving 4 s,
-- Standard 2.5 s, Pushing 1.2 s) to hit that enemy: the hit does no damage, they're unfrozen and
-- she breaks free with the game's own flash grenade counter. (The game only lets a grab be
-- countered with a defense item in the off hand when it starts, so she always holds one hidden
-- flash grenade, put back after each use and taken out when the mode ends. Releasing a grab any
-- other way, even killing the enemy, leaves the victim stuck with the grab camera.) The window
-- running out is a game over, with the pair still frozen.
-- Unarmed: every equip call on her inventory is refused (only this block's own grenade hand-over
-- goes through) and her main hand is emptied; the AI holds fire, has no knife and doesn't heal or
-- refill player 1. Her character can't be changed while the mode is on; the one she had before
-- comes back when another way is chosen.
;(function()
    local BB = { held = false, press = false, own_equip = false, failed = false, log = {} }
    st.bb = BB
    -- (what happened, newest last: reframework/data/reunited_bb_log.txt)
    function BB.note(t)
        BB.log[#BB.log + 1] = string.format("[%s f%d] %s", os.date("%H:%M:%S"), st.frame or 0, t)
        if #BB.log > 60 then table.remove(BB.log, 1) end
        pcall(fs.write, "reunited_bb_log.txt", table.concat(BB.log, "\n"))
    end
    local WIN = { forgiving = 4.0, standard = 2.5, pushing = 1.2 }
    local WIN_IDS = { "forgiving", "standard", "pushing" }
    local WIN_NAMES = { forgiving = "Forgiving", standard = "Standard", pushing = "Pushing" }
    BB.WIN = WIN
    function st.bb_on() return st.BB_ENABLED and st.play_mode == "babysit" and st.ai_partner() and st.p2_child() end
    local function her() return st.hunk end
    local function layer(go)
        local mo = go and comp(go, "via.motion.Motion")
        return mo and mo:call("getLayer", 0)
    end
    local function set_speed(go, v) local ly = layer(go); if ly then pcall(ly.call, ly, "set_Speed", v) end end
    local function flash_entry(hinv)
        for _, e in ipairs(st.p2inv.list(hinv)) do if e.wt == 66 then return e end end
    end
    function BB.window_row(indent)
        local cur = WIN[st.bb_window] and st.bb_window or "standard"
        local function flip(d)
            local i = 1
            for k, id in ipairs(WIN_IDS) do if id == cur then i = k end end
            st.bb_window = WIN_IDS[(i - 1 + (d or 1)) % #WIN_IDS + 1]
            pcall(st.save_config)
        end
        return { label = indent .. "Rescue window", value = string.format("%s (%.1f s)", WIN_NAMES[cur], WIN[cur]), change = flip, press = function() flip(1) end,
            help = "How long you have to hit an enemy that grabs Sherry before it's game over. Forgiving 4 s, Standard 2.5 s, Pushing 1.2 s." }
    end
    -- the mode starts / ends (Play > Ways to play)
    function BB.enter()
        if st.p2_model ~= "sherry" then
            st.bb_prev_model = st.p2_model
            st.p2_model = "sherry"
            if st.hunk then pcall(apply_model) end
        end
        BB.failed, BB.held, BB.press = false, false, false
        pcall(st.save_config)
    end
    function BB.leave()
        BB.held, BB.press = false, false
        -- the hidden flash grenades go
        pcall(function()
            local hinv = st.hunk and comp(st.hunk, "app.ropeway.survivor.Inventory")
            while hinv and (st.bb_flash or 0) > 0 do
                local e = flash_entry(hinv)
                if e == nil then break end
                local sl = hinv:call("getSlot(System.Int32)", e.i)
                if e.num > 1 and sl then sl:call("set_Number", e.num - 1) else hinv:call("removeSlot(System.Int32)", e.i) end
                st.bb_flash = st.bb_flash - 1
            end
        end)
        st.bb_flash = 0
        -- (and the pouch slots it added, if they're empty)
        pcall(function()
            local hinv = st.hunk and comp(st.hunk, "app.ropeway.survivor.Inventory")
            local n = st.p2inv.size(hinv)
            local used = {}
            for _, e in ipairs(st.p2inv.list(hinv)) do used[e.i] = true end
            while (st.bb_grew or 0) > 0 and n > 8 and not used[n - 1] do
                n = n - 1; st.bb_grew = st.bb_grew - 1
                hinv:set_field("_CurrentSlotSize", n)
            end
        end)
        st.bb_grew = 0
        if st.bb_prev_model ~= "" and st.p2_model == "sherry" then
            st.p2_model = st.bb_prev_model
            if st.hunk then pcall(apply_model) end
        end
        st.bb_prev_model = ""
        pcall(st.save_config)
    end
    -- the game over
    function BB.fail(why)
        if BB.failed then return end
        BB.failed, BB.fail_at, BB.why = true, os.clock(), tostring(why)
        BB.log_fail = (BB.log_fail or 0) + 1
        BB.note("GAME OVER: " .. BB.why .. (BB.held and (" (held, " .. string.format("%.1f", os.clock() - (BB.t0 or 0)) .. " s in, rescued " .. tostring(BB.press) .. ")") or ""))
        set_speed(her(), 0.0)
        if BB.ego then set_speed(BB.ego, 0.0) end
        local mf = sdk.get_managed_singleton("app.ropeway.gamemastering.MainFlowManager")
        if mf then pcall(mf.call, mf, "goGameOver", nil) end
    end
    -- unarmed: equip calls on her inventory refused (not this block's own)
    do
        local EQUIP = { equipMainSlot = true, equipSubSlot = true, equipSlot = true, equipSlotAnyway = true,
            equipMainSlotLastWeapon = true, equipSubSlotLastWeapon = true }
        local td = sdk.find_type_definition("app.ropeway.survivor.Inventory")
        for _, m in ipairs(td and td:get_methods() or {}) do
            if EQUIP[m:get_name()] then
                pcall(sdk.hook, m, function(args)
                    if BB.own_equip or not st.p2_unarmed() then return end
                    local hinv = st.hunk and comp(st.hunk, "app.ropeway.survivor.Inventory")
                    if hinv and (sdk.to_int64(args[2]) & 0xFFFFFFFFFFFF) == (hinv:get_address() & 0xFFFFFFFFFFFF) then
                        BB.refused = (BB.refused or 0) + 1
                        return sdk.PreHookResult.SKIP_ORIGINAL
                    end
                end, function(r) return r end)
            end
        end
    end
    -- (v407) what touches her: PlayerCondition.onHitDamage(DamageInfo). A grab's lunge (zombie
    -- HOLD_WALK) arrives with Damage 0 and goes on (that's how the grab happens); a hit with
    -- damage is refused and ends the game; player 1's own shots never count (refused quietly).
    do
        local td = sdk.find_type_definition("app.ropeway.survivor.player.PlayerCondition")
        pcall(sdk.hook, td:get_method("onHitDamage"), function(args)
            if not st.bb_on() or st.hunk == nil then return end
            local cond = comp(st.hunk, "app.ropeway.survivor.player.PlayerCondition")
            if cond == nil or (sdk.to_int64(args[2]) & 0xFFFFFFFFFFFF) ~= (cond:get_address() & 0xFFFFFFFFFFFF) then return end
            local di = sdk.to_managed_object(args[3])
            if di == nil then return end
            local owner = safe(function() return di:get_field("<AttackOwnerObject>k__BackingField") end)
            local p1 = p1_go()
            if owner and p1 and owner:get_address() == p1:get_address() then
                BB.ff = (BB.ff or 0) + 1
                return sdk.PreHookResult.SKIP_ORIGINAL
            end
            local dmg = safe(function() return di:get_field("<Damage>k__BackingField") end) or 0
            local odmg = safe(function() return di:get_field("<OriginalDamage>k__BackingField") end) or 0
            if dmg > 0 or odmg > 0 then
                local aud = safe(function() return di:get_field("<AttackUserData>k__BackingField") end)
                local an = aud and safe(function() return aud:call("get_Name") end)
                BB.fail(string.format("hit %d by %s (%s)", math.max(dmg, odmg), tostring(owner and safe(function() return owner:call("get_Name") end)), tostring(an)))
                return sdk.PreHookResult.SKIP_ORIGINAL
            end
            BB.touches = (BB.touches or 0) + 1
        end, function(r) return r end)
    end
    -- a hit on the enemy holding her (during the window): counted as the rescue, no damage
    do
        local td = sdk.find_type_definition("app.ropeway.HitPointController")
        pcall(sdk.hook, td:get_method("addDamage"), function(args)
            if not BB.held or BB.press or BB.ehpc_addr == nil then return end
            if (sdk.to_int64(args[2]) & 0xFFFFFFFFFFFF) == BB.ehpc_addr then
                BB.hit = true
                return sdk.PreHookResult.SKIP_ORIGINAL
            end
        end, function(r) return r end)
    end
    -- the hidden flash grenade: there, and in her off hand (not while held)
    local function ensure_flash(hinv)
        local e = flash_entry(hinv)
        if e == nil then
            -- (a full inventory: her pouch grows by two slots, shrunk back when the mode ends)
            if not st.p2inv.weapon_room(hinv, 66, 0) then
                local cap = safe(function() return hinv:get_field("_Slots"):call("get_Count") end) or 8
                local from = st.p2inv.size(hinv)
                if from + 2 <= cap then
                    pcall(hinv.set_field, hinv, "_CurrentSlotSize", from + 2)
                    for k = from, from + 1 do pcall(hinv.call, hinv, SETSLOT_SIG, k, -1, 0, 0, -1, nil) end
                    st.bb_grew = (st.bb_grew or 0) + 2
                end
            end
            if st.p2inv.put_weapon(hinv, { wt = 66, num = 1 }) then st.bb_flash = 1 end   -- (one hidden grenade at a time; a reload can restore her saved kit without it)
            pcall(st.save_config)
            e = flash_entry(hinv)
        end
        if e == nil then return false end
        local heq = comp(st.hunk, "app.ropeway.survivor.Equipment")
        if heq and safe(function() return heq:call("get_SubType") end) ~= 66 then
            BB.own_equip = true
            pcall(st.p2inv.equip_sub, hinv, e.i)
            BB.own_equip = false
        end
        return true
    end
    -- the prompt while she's held
    re.on_frame(function()
        if not BB.held or BB.press or BB.failed then return end
        pcall(function()
            local ds = imgui.get_display_size()
            local k = ds.y / 1080
            local left = math.max(0, BB.window - (os.clock() - BB.t0))
            local w, h = 520 * k, 14 * k
            local x, y = ds.x / 2 - w / 2, ds.y * 0.2
            draw.filled_rect(x - 4 * k, y - 4 * k, w + 8 * k, h + 8 * k, 0xA0000000)
            draw.filled_rect(x, y, w * left / BB.window, h, 0xFF3A3AE0)
            HUD.flush_labels({ { x = ds.x / 2, y = y - 30 * k, text = "Sherry has been grabbed! Hit the enemy!", size = math.floor(26 * k), col = 0xFFFFFFFF } })
        end)
    end)
    -- every frame (main tick, player 2 in the game)
    function st.bb_tick()
        -- (v408) leftovers of a shelved Babysitting (its grenade, pouch slots, the previous
        -- character) are cleared once, with player 2 in the game
        if not st.bb_on() and (st.bb_cleanup or (st.bb_flash or 0) > 0 or (st.bb_grew or 0) > 0) and st.hunk and not st.pending then
            st.bb_cleanup = nil
            pcall(BB.leave)
        end
        if not st.bb_on() then
            if BB.held then
                -- (the mode ended mid-grab: let go of the freeze)
                set_speed(her(), 1.0); if BB.ego then set_speed(BB.ego, 1.0) end
                BB.held, BB.press = false, false
            end
            return
        end
        local go = her()
        if go == nil or st.pending then return end
        -- (a new player 2 after a reload: a fresh start)
        if BB.addr ~= go:get_address() then BB.addr, BB.failed, BB.held, BB.press = go:get_address(), false, false, false end
        if BB.failed then
            -- (the game over didn't start: once more, the plain one)
            if BB.fail_at and os.clock() - BB.fail_at > 3 and not BB.retried then
                BB.retried = true
                local mf = sdk.get_managed_singleton("app.ropeway.gamemastering.MainFlowManager")
                local over = mf and safe(function() return mf:call("get_IsInGameOver") end)
                if mf and not over then pcall(mf.call, mf, "goGameOverSimple", nil) end
            end
            return
        end
        BB.retried = nil
        if st.p2_model ~= "sherry" then st.p2_model = "sherry"; pcall(apply_model); return end
        -- the AI holds fire
        if ai.order then ai.order.fire = "hold"; ai.order.attack = nil end
        local hinv = comp(go, "app.ropeway.survivor.Inventory")
        local cond = comp(go, "app.ropeway.survivor.player.PlayerCondition")
        local held = cond ~= nil and safe(function() return cond:call("get_IsJackFromEnemy") end) == true
        -- her hit points never drop (and if they somehow did, it's over)
        local hpc = comp(go, "app.ropeway.HitPointController")
        local cur = hpc and safe(function() return hpc:call("get_CurrentHitPoint") end)
        local def = hpc and safe(function() return hpc:call("get_DefaultHitPoint") end)
        if cur and def and cur < def then BB.fail("hit points " .. cur .. " / " .. def); return end
        if not held then
            if BB.held then
                -- free again (the counter played out)
                BB.note(BB.press and "free: the counter played out" or "free without a rescue (the grab ended by itself)")
                BB.held, BB.press, BB.hit, BB.ego, BB.ehpc_addr = false, false, false, nil, nil
                BB.rescues = (BB.rescues or 0) + 1
            end
            if hinv and st.frame % 10 == 0 then
                pcall(ensure_flash, hinv)
                -- (main hand empty: only when something is in it. Unequipping an empty hand every
                -- 10 frames restarted her action each time, so a jog never stopped: she glided on
                -- past player 1 and back)
                pcall(function()
                    local heq = comp(go, "app.ropeway.survivor.Equipment")
                    local et = heq and safe(function() return heq:call("get_EquipType") end)
                    if et and et ~= 0 and et ~= -1 then
                        local m = hinv:call("get_MainSlot")
                        if m then hinv:call("unequipMainSlot(app.ropeway.inventory.Slot)", m) end
                    end
                end)
            end
            return
        end
        if not BB.held then
            -- grabbed: freeze both, the window starts
            BB.held, BB.press, BB.hit, BB.t0 = true, false, false, os.clock()
            BB.window = WIN[st.bb_window] or WIN.standard
            BB.grabs = (BB.grabs or 0) + 1
            BB.ego, BB.ehpc_addr, BB.ehp0 = nil, nil, nil
            pcall(function()
                local own = comp(go, "app.ropeway.JackDominator"):call("get_JackOwner")
                BB.ego = own and own:get_field("<Object>k__BackingField")
                local ehpc = BB.ego and comp(BB.ego, "app.ropeway.HitPointController")
                if ehpc then BB.ehpc_addr = ehpc:get_address() & 0xFFFFFFFFFFFF; BB.ehp0 = ehpc:call("get_CurrentHitPoint") end
            end)
            local heq = comp(go, "app.ropeway.survivor.Equipment")
            BB.counterable = heq ~= nil and safe(function() return heq:call("get_SubType") end) == 66
            BB.note(string.format("grabbed by %s (flash grenade ready %s, window %.1f s)", tostring(BB.ego and safe(function() return BB.ego:call("get_Name") end)), tostring(BB.counterable), BB.window))
        end
        if not BB.press then
            set_speed(go, 0.0)
            if BB.ego then set_speed(BB.ego, 0.0) end
            -- (a hit that got past the hook still counts)
            if not BB.hit and BB.ehp0 and BB.ego then
                local ehpc = comp(BB.ego, "app.ropeway.HitPointController")
                local eh = ehpc and safe(function() return ehpc:call("get_CurrentHitPoint") end)
                if eh and eh < BB.ehp0 then BB.hit = true end
            end
            if BB.hit and BB.counterable then
                -- rescued: unfreeze, she counters (the AI presses the defense button: see update_ai)
                set_speed(go, 1.0); if BB.ego then set_speed(BB.ego, 1.0) end
                BB.press, BB.press_at = true, os.clock()
                ai.held_n = 6
                BB.note(string.format("rescued %.1f s in: counter", os.clock() - BB.t0))
            elseif os.clock() - BB.t0 > BB.window then
                BB.fail(BB.hit and "grabbed without a counter" or "rescue window ran out")
            end
            return
        end
        -- (the counter didn't happen: rather the game over than a bite)
        if os.clock() - BB.press_at > 8 then BB.fail("counter timed out") end
    end
end)()

-- Development only: the dev bridge script (not shipped) sets REUNITED_DEV before this loads
if _G.REUNITED_DEV then
    _G.reunited = { st = st, comp = comp, players = players, p1_go = p1_go, spawn = spawn, despawn = despawn,
        teleport_to_p1 = teleport_to_p1, give_loadout = give_loadout, loadout = function() return LOADOUT, AMMO end, fix_costume = fix_costume,
        toggle_sub_weapon = toggle_sub_weapon, heal_p1 = heal_p1, resupply_p1 = resupply_p1,
        reload_hunk = reload_hunk, pickup_for_p1 = pickup_for_p1, play_sfx = play_sfx,
        swap_controllers = swap_controllers, refresh_unit = refresh_unit, current_owner = current_owner,
        apply_model = apply_model, survivor_type = survivor_type, split = split, p2c = p2c, ai = ai, clear_line = clear_line, enemy_aim_point = enemy_aim_point }
end

-- Player 1's camera: field of view and left / right ---------------------------------------
-- Leon's camera is the game's (Main Camera), driven by its camera controllers every frame. The
-- settings are applied to Main Camera only for drawing and put back after rendering
-- (EndRendering), so the game's own logic (aiming, player 2's FOV match in split screen) never
-- sees them:
-- * left / right: moved st.p1_side cm along its right axis (not into walls) after the game's
--   cameras have updated (LateUpdateBehavior). Setting the position any later (BeginRendering)
--   does nothing: the world matrices are already final by then. Fades out while player 1 aims,
--   because the game aims along its own camera's centre line, which then has to be the middle
--   of the screen.
-- * distance: moved along its own view line (same LateUpdateBehavior step) so the distance to
--   player 1 is st.p1_dist_pct of the game's; the centre line doesn't change, so aiming is
--   unaffected and it stays on while aiming. Pulling back stops 0.15 m short of walls.
-- * field of view: scaled by st.p1_fov_pct right before rendering (BeginRendering).
-- Cutscenes and the game's fixed / scripted cameras are left alone.
do
    local P1C = { pos = nil, fov = nil, w = 0, pcc = nil, pcc_at = 0 }
    st.p1cam = P1C
    local function main_cam()
        local c = sdk.get_primary_camera()
        return c and c:call("get_GameObject") and c
    end
    local function aiming()
        if st.frame >= P1C.pcc_at then
            P1C.pcc_at = st.frame + 120
            local sc = sdk.call_native_func(sdk.get_native_singleton("via.SceneManager"), sdk.find_type_definition("via.SceneManager"), "get_CurrentScene")
            local go = sc and safe(function() return sc:call("findGameObject(System.String)", "PlayerCameraController") end)
            P1C.pcc = go and comp(go, "app.ropeway.camera.PlayerCameraController")
        end
        local k = P1C.pcc and safe(function() return P1C.pcc:call("get_NowKind") end)
        return k == 3 or k == 4   -- Hold / Holded
    end
    local function restore()
        local a, f = P1C.pos, P1C.fov
        P1C.pos, P1C.fov = nil, nil
        if f then pcall(function() f.cam:call("set_FOV", f.v) end) end
        if a then pcall(function() a.xf:call("set_Position", a.v) end) end
    end
    P1C.restore = restore
    local function wall_clip(from, want)
        local ok, hit = pcall(cast_ray, from, want)
        if not (ok and hit) then return want end
        local dx, dy, dz = hit.x - from.x, hit.y - from.y, hit.z - from.z
        local l = math.sqrt(dx * dx + dy * dy + dz * dz)
        local keep = math.max(0, l - 0.15)
        return l > 0.001 and Vector3f.new(from.x + dx / l * keep, from.y + dy / l * keep, from.z + dz / l * keep) or from
    end
    local function apply_side()
        restore()   -- (in case EndRendering didn't run)
        if not st.split then return end   -- (split screen mode only)
        local side = (st.p1_side or 0) / 100
        local dp = (st.p1_dist_pct or 100) / 100
        local target = aiming() and 0 or 1
        P1C.w = P1C.w + (target - P1C.w) * 0.2
        if math.abs(P1C.w - target) < 0.01 then P1C.w = target end
        if (side == 0 or P1C.w == 0) and dp == 1 then return end
        local p1 = p1_go()
        if p1 == nil or st.in_cutscene() then return end
        local cs = sdk.get_managed_singleton("app.ropeway.camera.CameraSystem")
        local busy = cs and safe(function() return cs:call("get_BusyCameraType") end)
        if busy ~= 0 and busy ~= 1 then return end   -- player / sight camera only
        local cam = main_cam()
        if cam == nil then return end
        local xf = cam:call("get_GameObject"):call("get_Transform")
        local p0 = xf:call("get_Position")
        local rot = xf:call("get_Rotation")
        local p = p0
        if dp ~= 1 then
            -- the game's distance: from the camera to player 1's chest, along the view line
            local f = rot * Vector3f.new(0, 0, -1)
            local c = p1:call("get_Transform"):call("get_Position")
            local d0 = (c.x - p.x) * f.x + (c.y + 1.3 - p.y) * f.y + (c.z - p.z) * f.z
            if d0 > 0.3 and d0 < 8 then
                local pivot = Vector3f.new(p.x + f.x * d0, p.y + f.y * d0, p.z + f.z * d0)
                local d1 = d0 * dp
                local want = Vector3f.new(pivot.x - f.x * d1, pivot.y - f.y * d1, pivot.z - f.z * d1)
                p = dp > 1 and wall_clip(pivot, want) or want
            end
        end
        if side ~= 0 and P1C.w > 0 then
            local r = rot * Vector3f.new(1, 0, 0)
            local d = side * P1C.w
            p = wall_clip(p, Vector3f.new(p.x + r.x * d, p.y + r.y * d, p.z + r.z * d))
        end
        P1C.pos = { xf = xf, v = p0 }
        xf:call("set_Position", p)
    end
    local function apply_fov()
        if P1C.fov then pcall(function() P1C.fov.cam:call("set_FOV", P1C.fov.v) end); P1C.fov = nil end
        local fp = st.p1_fov_pct or 100
        if not st.split or fp == 100 or p1_go() == nil or st.in_cutscene() then return end
        local cam = main_cam()
        if cam == nil then return end
        local f = cam:call("get_FOV")
        P1C.fov = { cam = cam, v = f }
        cam:call("set_FOV", math.max(10, math.min(150, f * fp / 100)))
    end
    re.on_application_entry("LateUpdateBehavior", function() pcall(apply_side) end)
    re.on_pre_application_entry("BeginRendering", function() pcall(apply_fov) end)
    re.on_application_entry("EndRendering", function() pcall(restore) end)
    if re.on_script_reset then re.on_script_reset(function() pcall(restore) end) end
end

-- Networking (re2r_mp) ------------------------------------------------------------
-- Talks to our re2r_mp.dll through a RAM block whose address AND field offsets the plugin
-- publishes to re2r_mp_net.txt (same mechanism as the reference pads / sfx plugins).
-- Wrapped in an IIFE so it does not eat the main chunk's local-variable budget: the module
-- keeps its own locals in its own scope and exposes everything through the global RE2R_MP_NET.
RE2R_MP_NET = (function(safe, p1_go, comp, st, say)
    local fs, sdk = fs, sdk
    local Vector3f, Quaternion = Vector3f, Quaternion
    local CMD_HOST, CMD_JOIN, CMD_DISCONNECT, CMD_SCAN = 1, 2, 3, 4
    -- PlayerSnapshot field offsets (pos[3], rot[4] (w,x,y,z), motion, flags, health)
    local S_POS, S_ROT, S_MOTION, S_FLAGS, S_HP = 0, 12, 28, 32, 36
    local NET = {
        on = false, role = nil, addr = nil, off = {}, next_read = 0,
        ip = "127.0.0.1", port = 27099, state = 0, peer = 0, tick = 0, rvalid = 0,
        last_rseq = 0, smooth = 0.5, status = "", sync_health = true,
    }

    local function g(txt, key) return tonumber(txt:match(key .. " (%d+)")) end

    function NET.refresh_layout()
        if st.frame < NET.next_read then return end
        NET.next_read = st.frame + 30
        local ok, txt = pcall(fs.read, "re2r_mp_net.txt")
        if not ok or type(txt) ~= "string" or txt == "" then return end
        local a = tonumber(txt:match("addr (%d+)"))
        if a then NET.addr = a end
        local o = NET.off
        o.cmd = g(txt, "off_cmd"); o.port = g(txt, "off_port"); o.ip = g(txt, "off_ip")
        o.state = g(txt, "off_state"); o.error = g(txt, "off_error"); o.peer = g(txt, "off_peer")
        o.tick = g(txt, "off_tick"); o.status = g(txt, "off_status")
        o.lpos = g(txt, "off_local_pos"); o.lrot = g(txt, "off_local_rot")
        o.lmotion = g(txt, "off_local_motion"); o.lflags = g(txt, "off_local_flags")
        o.lhealth = g(txt, "off_local_health")
        o.remote = g(txt, "off_remote"); o.rvalid = g(txt, "off_remote_valid"); o.rseq = g(txt, "off_remote_seq")
        o.laim = g(txt, "off_local_aim"); o.laim_valid = g(txt, "off_local_aim_valid")
        o.raim = g(txt, "off_remote_aim"); o.raim_valid = g(txt, "off_remote_aim_valid")
        o.lin_buttons = g(txt, "off_local_input_buttons"); o.lin_axes = g(txt, "off_local_input_axes")
        o.rin_buttons = g(txt, "off_remote_input_buttons"); o.rin_axes = g(txt, "off_remote_input_axes")
        o.rin_valid = g(txt, "off_remote_input_valid")
        o.dout_valid = g(txt, "off_door_out_valid"); o.dout_state = g(txt, "off_door_out_state"); o.dout_name = g(txt, "off_door_out_name")
        o.din_valid = g(txt, "off_door_in_valid"); o.din_seq = g(txt, "off_door_in_seq"); o.din_state = g(txt, "off_door_in_state"); o.din_name = g(txt, "off_door_in_name")
        o.iout_valid = g(txt, "off_item_out_valid"); o.iout_name = g(txt, "off_item_out_name"); o.iout_pos = g(txt, "off_item_out_pos")
        o.iin_valid = g(txt, "off_item_in_valid"); o.iin_seq = g(txt, "off_item_in_seq"); o.iin_name = g(txt, "off_item_in_name"); o.iin_pos = g(txt, "off_item_in_pos")
        o.found_count = g(txt, "off_found_count"); o.found = g(txt, "off_found")
    end

    local function base()
        if not NET.addr or not NET.off.cmd then return nil end
        local ok, vt = pcall(sdk.to_valuetype, NET.addr, "via.mat4")
        if not ok then return nil end
        return vt
    end

    local function write_dword(vt, off, v) vt:write_dword(off, v & 0xFFFFFFFF) end
    local function write_str(vt, off, s)
        local n = #s
        local i = 0
        while i < n do
            local a = string.byte(s, i + 1) or 0
            local b = string.byte(s, i + 2) or 0
            local c = string.byte(s, i + 3) or 0
            local d = string.byte(s, i + 4) or 0
            vt:write_dword(off + i, a | (b << 8) | (c << 16) | (d << 24))
            i = i + 4
        end
        if n % 4 == 0 then vt:write_dword(off + n, 0) end
    end
    local function read_cstr(vt, off, max)
        local out = {}
        for i = 0, max - 1, 4 do
            local d = vt:read_dword(off + i)
            for k = 0, 3 do
                local b = (d >> (8 * k)) & 0xFF
                if b == 0 then return table.concat(out) end
                out[#out + 1] = string.char(b)
            end
        end
        return table.concat(out)
    end

    function NET.ensure()
        NET.refresh_layout()
        return base()
    end

    function NET.start_host(port)
        local vt = NET.ensure()
        if not vt then say("net: re2r_mp.dll not loaded"); return end
        NET.port = port or NET.port
        write_dword(vt, NET.off.port, NET.port)
        write_dword(vt, NET.off.cmd, CMD_HOST)
        NET.role, NET.on = "host", true
        local is = sdk.get_managed_singleton("app.ropeway.InputSystem")
        if is then NET.ensure_p2(is, st.pads) else say("net: warning, InputSystem not found") end
        say("net: hosting on udp " .. NET.port)
    end

    function NET.start_join(ip, port)
        local vt = NET.ensure()
        if not vt then say("net: re2r_mp.dll not loaded"); return end
        NET.ip = ip or NET.ip
        NET.port = port or NET.port
        write_str(vt, NET.off.ip, NET.ip)
        write_dword(vt, NET.off.port, NET.port)
        write_dword(vt, NET.off.cmd, CMD_JOIN)
        NET.role, NET.on = "client", true
        local is = sdk.get_managed_singleton("app.ropeway.InputSystem")
        if is then NET.ensure_p2(is, st.pads) else say("net: warning, InputSystem not found") end
        say("net: joining " .. NET.ip .. ":" .. NET.port)
    end

    function NET.scan()
        local vt = NET.ensure()
        if not vt then return end
        write_dword(vt, NET.off.cmd, CMD_SCAN)
    end

    function NET.stop()
        local vt = NET.ensure()
        if vt then write_dword(vt, NET.off.cmd, CMD_DISCONNECT) end
        NET.on, NET.role, NET.rvalid = false, nil, 0
        if NET.reset_world then NET.reset_world() end
        -- give player 2 back to a real controller (if any), not the net virtual pad
        local is = sdk.get_managed_singleton("app.ropeway.InputSystem")
        if is and st.p2_src and st.p2_src.uid == "net" and st.pad.choose_p2 then
            st.set_p2(is, st.pads, st.pad.choose_p2(st.p1_uid, false))
        end
        say("net: stopped")
    end

    local STATE_NAMES = { [0] = "idle", [1] = "hosting", [2] = "connecting", [3] = "connected", [4] = "error" }
    function NET.status_text()
        if not NET.addr or not NET.off.state then return "plugin not loaded (re2r_mp.dll)" end
        local vt = base()
        if not vt then return "block unreadable" end
        NET.state = vt:read_dword(NET.off.state)
        NET.peer = vt:read_dword(NET.off.peer)
        return (STATE_NAMES[NET.state] or tostring(NET.state))
            .. (NET.role and ("  [" .. NET.role .. "]") or "")
            .. (NET.peer == 1 and "  peer: yes" or "  peer: no")
    end

    function NET.found_count()
        local vt = base()
        if not vt or not NET.off.found_count then return 0 end
        return vt:read_dword(NET.off.found_count)
    end
    function NET.found(i)
        local vt = base()
        if not vt or not NET.off.found then return nil end
        return read_cstr(vt, NET.off.found + 64 * (i - 1), 64)
    end

    -- per-frame: publish our local player, apply the remote player to HUNK
    -- the net player is wired in as player 2's virtual pad (st.set_p2 below), so the whole
    -- existing input path -- route()'s InputSystem hooks, update_p2cam, the co-op combos,
    -- the wheel -- reads the RECEIVED remote input with no further changes.
    local NET_P2_SRC = { kind = "game", key = "game", uid = "net", name = "network player" }
    function NET.ensure_p2(is, pads)
        if not NET.on then return end
        if not (st.p2_src and st.p2_src.uid == "net") then
            st.set_p2(is or st.pads, pads or st.pads, NET_P2_SRC)
        end
    end

    -- the remote player, as the receiving machine's virtual pad. Called from st.pad.update
    -- (once per frame): fills the virtual pad from the block and skips the physical pad.
    function NET.apply_remote_input(V)
        if not NET.on then return false end
        if NET.off.rin_valid == nil then return false end
        local vt = base()
        if not vt then return false end
        if vt:read_dword(NET.off.rin_valid) ~= 1 then return false end
        local b = vt:read_dword(NET.off.rin_buttons)
        local o = NET.off.rin_axes
        V.b, V.prev = b, V.prev
        V.lx, V.ly = vt:read_float(o), vt:read_float(o + 4)
        V.rx, V.ry = vt:read_float(o + 8), vt:read_float(o + 12)
        V.lt, V.rt = vt:read_float(o + 16), vt:read_float(o + 20)
        return true
    end

    -- HUNK aims at the remote player's crosshair point (see target_point()):
    -- the world point our peer is aiming at, or nil when we have none.
    function NET.remote_aim_point()
        if not NET.on then return nil end
        if NET.off.raim_valid == nil then return nil end
        local vt = base()
        if not vt then return nil end
        if vt:read_dword(NET.off.raim_valid) ~= 1 then return nil end
        local o = NET.off.raim
        return { vt:read_float(o), vt:read_float(o + 4), vt:read_float(o + 8) }
    end

    -- this machine's OWN player-1 crosshair point, for sending: lifts it through the same
    -- st.target_point, with the net override momentarily switched off (st.net_local_ask).
    function NET.local_aim_point()
        if type(st.target_point) ~= "function" then return nil end
        st.net_local_ask = true
        local ok, p = pcall(st.target_point)
        st.net_local_ask = false
        if not ok or p == nil then return nil end
        local okx, x = pcall(function() return p[1] or p.x end)
        local oky, y = pcall(function() return p[2] or p.y end)
        local okz, z = pcall(function() return p[3] or p.z end)
        if not (okx and oky and okz) then return nil end
        if x == nil or y == nil or z == nil then return nil end
        return x, y, z
    end

    -- ---- door state sync (world sync, phase 1) --------------------------------------------
    -- Doors stay KEEP'd in sync: when either player opens one the other machine replays the
    -- open by name. Capture is observe-only -- we hook the two managed open methods the game
    -- itself calls (requestOpenByLever for the lever/push doors, setPeeked for the peek-routine
    -- doors), so player 1's native opens AND the mod's own opens are caught with no side
    -- effects. On receipt we open ours from the remote player's side (his mirrored position
    -- through calcSide, the same path the mod's door_open uses) and hold it open a beat with
    -- the game's contact timer. Echoes are muted per door for a few seconds after applying.
    -- The stable id is the GameObject name (identical map asset on both machines).
    local ADDR_MASK = 0xFFFFFFFFFFFF
    local DOOR_TD = sdk.find_type_definition("app.ropeway.gimmick.action.GimmickDoorBase")
    local door_hits, door_sent = {}, {}        -- key{48} -> frame opened / last-frame guard
    local door_list, door_addr, door_at = {}, {}, 0   -- name -> door, key -> name, refresh timer
    local door_q = {}                          -- opens queued for the plugin's shipping slot
    local door_prev = {}                       -- name -> last polled open state (fallback)
    local door_suppress = {}                   -- name -> frame until local capture is muted
    local door_holds = {}                      -- name -> frame until we hold it visibly open
    local function door_key(ptr) return sdk.to_int64(ptr) & ADDR_MASK end

    local function door_refresh()
        if st.frame - door_at < 60 then return end
        door_at = st.frame
        door_list, door_addr = {}, {}
        if DOOR_TD == nil then return end
        pcall(function()
            local scene = sdk.call_native_func(sdk.get_native_singleton("via.SceneManager"),
                sdk.find_type_definition("via.SceneManager"), "get_CurrentScene")
            local l = scene and scene:call("findComponents(System.Type)",
                sdk.typeof("app.ropeway.gimmick.action.GimmickDoorBase"))
            for i = 0, (l and l:call("get_Count") or 0) - 1 do
                local d = safe(function() return l:call("get_Item", i) end)
                if d then
                    local nm = safe(function() return d:call("get_GameObject"):call("get_Name") end)
                    if type(nm) == "string" and nm ~= "" and not door_list[nm] then
                        local ref = safe(function() return d:add_ref() end)
                        if ref then door_list[nm] = ref; door_addr[door_key(d)] = nm end
                    end
                end
            end
        end)
    end

    local function door_queue(name)
        if door_suppress[name] and st.frame < door_suppress[name] then return end
        for _, q in ipairs(door_q) do if q.name == name then return end end
        door_q[#door_q + 1] = { name = name }
    end

    -- capture A: observe-only hooks (the call passes through untouched). This is safe as long
    -- as we never touch the mod's own door hooks (it hooks dynamic input, not these methods).
    for _, mn in ipairs({ "requestOpenByLever", "setPeeked" }) do
        if DOOR_TD then
            pcall(sdk.hook, DOOR_TD:get_method(mn), function(args)
                pcall(function()
                    local d = args[1]
                    if d then
                        local k = door_key(d)
                        if k ~= 0 then door_hits[k] = st.frame end
                    end
                end)
            end, function(r) return r end)
        end
    end

    -- capture B (fallback): a door whose open path our hooks miss shows up through the peak
    -- work value door_peek already reads (_PeekedWork.GetValue(0).Value, 0..1, >0.5 = open).
    local function door_poll()
        for name, d in pairs(door_list) do
            local v = safe(function() return d:get_field("_PeekedWork"):call("GetValue", 0):get_field("Value") end)
            if v then
                local open = v > 0.5
                if open and not door_prev[name] then door_queue(name) end
                door_prev[name] = open
            end
        end
    end

    local function door_resolve_hits()
        for k, f in pairs(door_hits) do
            door_hits[k] = nil
            if st.frame - f < 30 then
                local name = door_addr[k]
                if name and (not door_sent[k] or st.frame - door_sent[k] > 300) then
                    if not door_suppress[name] or st.frame >= door_suppress[name] then
                        door_sent[k] = st.frame
                        door_queue(name)
                    end
                end
            end
        end
    end

    -- ship one queued open to the plugin's send-slot (a new one frees up every ~16 ms).
    local function door_flush(vt)
        if not (NET.off.dout_valid and NET.off.dout_name and NET.off.dout_state) then return end
        if vt:read_dword(NET.off.dout_valid) ~= 0 then return end
        local q = door_q[1]
        if q == nil then return end
        write_str(vt, NET.off.dout_name, q.name)
        vt:write_dword(NET.off.dout_state, 2)
        vt:write_dword(NET.off.dout_valid, 1)
        table.remove(door_q, 1)
    end

    -- replay a remote open: look it up by name, open it from the remote player's side, hold it
    -- open via the game's contact timer, and mute our own capture so it isn't echoed back.
    local function door_apply(vt)
        if not (NET.off.din_valid and NET.off.din_name and NET.off.din_state) then return end
        if vt:read_dword(NET.off.din_valid) ~= 1 then return end
        local name = read_cstr(vt, NET.off.din_name, 64)
        vt:write_dword(NET.off.din_valid, 0)
        if name == "" then return end
        local door = door_list[name]
        if door == nil then return end
        -- make the rooms on both sides drawn first, exactly as the mod's door_open does, so the
        -- remote player's mirrored approach doesn't cross an unloaded room.
        local ids = {}
        pcall(function()
            local rooms = door:call("get_MyRooms")
            for j = 0, rooms:call("get_Length") - 1 do
                local b = rooms:call("GetValue", j)
                ids[#ids + 1] = type(b) == "number" and b or b:get_field("value__")
            end
        end)
        pcall(st.area_ready, ids)
        local side = 0
        if NET.off.rvalid and vt:read_dword(NET.off.rvalid) == 1 then
            local ro = NET.off.remote
            local rx, ry, rz = vt:read_float(ro), vt:read_float(ro + 4), vt:read_float(ro + 8)
            side = safe(function() return door:call("calcSide", Vector3f.new(rx, ry, rz)) end) or 0
        end
        if side ~= 0 then side = 1 end
        local ok = safe(function() return door:call("requestOpenByLever", side) end)
        if ok == true then
            pcall(function() door:call("setOpenSpeed", 1.0) end)
            door_holds[name] = st.frame + 120
            door_suppress[name] = st.frame + 150
        end
    end

    -- keep a remote-opened door ajar a beat so the mirrored player walks through cleanly.
    local function door_holds_tick()
        for name, until_f in pairs(door_holds) do
            if st.frame > until_f then
                door_holds[name] = nil
            else
                local d = door_list[name]
                if d then pcall(d.set_field, d, "_TimerContactPl", 1.0) end
            end
        end
    end

    local function door_tick(vt)
        if not (NET.off.dout_valid and NET.off.din_valid) then return end
        door_refresh()
        door_resolve_hits()
        door_poll()
        door_flush(vt)
        door_apply(vt)
        door_holds_tick()
    end

    -- ---- world-item sync (world sync, phase 2) --------------------------------------------
    -- A world item taken by either player is removed on the other machine, so it can't be
    -- collected twice. Items are app.ropeway.gimmick.action.SetItem gimmicks; the id is the
    -- GameObject name plus its position (prefab names are not unique). Capture is observe-only:
    -- a hook on SetItem.setVanish records the item the moment it leaves the world, but only when
    -- it was at a player (a pick-up), so streaming an area out can't be mistaken for one. On
    -- receipt we find the matching SetItem (same name, nearest position) and setVanish it.
    local ITEM_TD = sdk.find_type_definition("app.ropeway.gimmick.action.SetItem")
    local item_hits = {}       -- key{48} -> { name = .., pos = {x,y,z} }
    local item_q = {}          -- removals queued for the plugin's shipping slot
    local item_list, item_at = {}, 0
    local item_suppress = {}   -- name -> frame until local capture is muted (echo guard)
    local item_sent = {}       -- key -> last frame sent (spam guard)

    local function item_near_player(p)
        if p == nil then return false end
        local function close(pos)
            if pos == nil then return false end
            local dx, dy, dz = pos.x - p.x, pos.y - p.y, pos.z - p.z
            return dx * dx + dy * dy + dz * dz < 12.25          -- within 3.5 m
        end
        local p1 = p1_go()
        if p1 and close(safe(function() return p1:call("get_Transform"):call("get_Position") end)) then return true end
        if st.hunk and close(safe(function() return st.hunk:call("get_Transform"):call("get_Position") end)) then return true end
        return false
    end

    local function item_refresh()
        if st.frame - item_at < 30 then return end
        item_at = st.frame
        item_list = {}
        if ITEM_TD == nil then return end
        pcall(function()
            local scene = sdk.call_native_func(sdk.get_native_singleton("via.SceneManager"),
                sdk.find_type_definition("via.SceneManager"), "get_CurrentScene")
            local l = scene and scene:call("findComponents(System.Type)",
                sdk.typeof("app.ropeway.gimmick.action.SetItem"))
            for i = 0, (l and l:call("get_Count") or 0) - 1 do
                local d = safe(function() return l:call("get_Item", i) end)
                if d then
                    local nm = safe(function() return d:call("get_GameObject"):call("get_Name") end)
                    local p = safe(function() return d:call("get_Position") end)
                    if type(nm) == "string" and nm ~= "" and p then
                        item_list[#item_list + 1] = { name = nm, pos = { p.x, p.y, p.z }, ref = safe(function() return d:add_ref() end) }
                    end
                end
            end
        end)
    end

    local function item_queue(name, pos)
        if item_suppress[name] and st.frame < item_suppress[name] then return end
        for _, q in ipairs(item_q) do if q.name == name then return end end
        if #item_q > 32 then table.remove(item_q, 1) end
        item_q[#item_q + 1] = { name = name, pos = pos }
    end

    -- capture: observe-only hook (the call passes through untouched). Only a vanish at a player
    -- counts, so area streaming can't be mistaken for a pick-up.
    if ITEM_TD then
        local m = ITEM_TD:get_method("setVanish")
        if m then
            pcall(sdk.hook, m, function(args)
                pcall(function()
                    local d = args[1]
                    if d == nil then return end
                    local key = sdk.to_int64(d) & ADDR_MASK
                    if key == 0 then return end
                    local nm = safe(function() return d:call("get_GameObject"):call("get_Name") end)
                    if type(nm) ~= "string" or nm == "" then return end
                    local p = safe(function() return d:call("get_Position") end)
                    if p and item_near_player(p) then
                        item_hits[key] = { name = nm, pos = { p.x, p.y, p.z } }
                    end
                end)
            end, function(r) return r end)
        end
    end

    local function item_resolve_hits()
        for k, hit in pairs(item_hits) do
            item_hits[k] = nil
            if hit.name and (not item_sent[k] or st.frame - item_sent[k] > 60) then
                if not item_suppress[hit.name] or st.frame >= item_suppress[hit.name] then
                    item_sent[k] = st.frame
                    item_queue(hit.name, hit.pos)
                end
            end
        end
    end

    local function item_flush(vt)
        if not (NET.off.iout_valid and NET.off.iout_name and NET.off.iout_pos) then return end
        if vt:read_dword(NET.off.iout_valid) ~= 0 then return end
        local q = item_q[1]
        if q == nil then return end
        write_str(vt, NET.off.iout_name, q.name)
        local p = q.pos or { 0, 0, 0 }
        vt:write_float(NET.off.iout_pos, p[1])
        vt:write_float(NET.off.iout_pos + 4, p[2])
        vt:write_float(NET.off.iout_pos + 8, p[3])
        vt:write_dword(NET.off.iout_valid, 1)
        table.remove(item_q, 1)
    end

    local function item_apply(vt)
        if not (NET.off.iin_valid and NET.off.iin_name and NET.off.iin_pos) then return end
        if vt:read_dword(NET.off.iin_valid) ~= 1 then return end
        local name = read_cstr(vt, NET.off.iin_name, 64)
        local x = vt:read_float(NET.off.iin_pos)
        local y = vt:read_float(NET.off.iin_pos + 4)
        local z = vt:read_float(NET.off.iin_pos + 8)
        vt:write_dword(NET.off.iin_valid, 0)
        if name == "" then return end
        item_refresh()
        local best, bd = nil, 4.0                          -- nearest same-named item within 2 m
        local have_pos = (x ~= 0 or y ~= 0 or z ~= 0)
        for _, it in ipairs(item_list) do
            if it.name == name and it.ref then
                if not have_pos then best = it; break end
                local dx, dy, dz = it.pos[1] - x, it.pos[2] - y, it.pos[3] - z
                local d2 = dx * dx + dy * dy + dz * dz
                if d2 < bd then best, bd = it, d2 end
            end
        end
        if best then
            item_suppress[name] = st.frame + 120
            pcall(function() best.ref:call("setVanish") end)
        end
    end

    local function item_tick(vt)
        if not (NET.off.iout_valid and NET.off.iin_valid) then return end
        item_resolve_hits()
        item_flush(vt)
        item_apply(vt)
    end

    -- defined here (after the door/item state locals) so these are true upvalue writes; NET.stop
    -- is declared earlier in this chunk, where the same names would resolve to globals.
    function NET.reset_world()
        door_q, door_hits, door_prev, door_suppress, door_holds, door_sent = {}, {}, {}, {}, {}, {}
        item_q, item_hits, item_suppress, item_sent = {}, {}, {}, {}
    end
    -- for a game pad (default layout, ignoring any custom "Map player 2" remap), so buttons
    -- keep their physical identity no matter whose controller is on the other side.
    local function capture_p1_input()
        local dev = st.p1_dev
        if dev == nil then return nil end
        local raw = st.pad.raw({ kind = "game", key = "game", dev = dev })
        if raw == nil then return nil end
        local m = st.pad.maps_default.game
        local lv = st.pad.level
        local function stick(pos, neg) return lv(raw, m[pos]) - lv(raw, m[neg]) end
        local bits = 0
        for _, c in ipairs(st.pad.CTRLS) do
            if c.bit and lv(raw, m[c.id]) > 0.5 then bits = bits | c.bit end
        end
        local lt, rt = lv(raw, m.LT), lv(raw, m.RT)
        if lt > 0.35 then bits = bits | 512 end
        if rt > 0.35 then bits = bits | 2048 end
        return { b = bits, lx = stick("LRIGHT", "LLEFT"), ly = stick("LUP", "LDOWN"),
                 rx = stick("RRIGHT", "RLEFT"), ry = stick("RUP", "RDOWN"), lt = lt, rt = rt }
    end
    function NET.send_input(vt)
        if NET.off.lin_buttons == nil then return end
        local n = capture_p1_input()
        if n == nil then return end
        vt:write_dword(NET.off.lin_buttons, n.b)
        local o = NET.off.lin_axes
        vt:write_float(o, n.lx); vt:write_float(o + 4, n.ly)
        vt:write_float(o + 8, n.rx); vt:write_float(o + 12, n.ry)
        vt:write_float(o + 16, n.lt); vt:write_float(o + 20, n.rt)
    end
    function NET.tick()
        if not NET.on then return end
        NET.refresh_layout()
        local vt = base()
        if not vt or not NET.off.lpos then return end
        door_tick(vt)
        item_tick(vt)
        local p1 = p1_go()
        if p1 then
            local xf = safe(function() return p1:call("get_Transform") end)
            local p = xf and safe(function() return xf:call("get_Position") end)
            local r = xf and safe(function() return xf:call("get_Rotation") end)
            if p and r then
                vt:write_float(NET.off.lpos, p.x)
                vt:write_float(NET.off.lpos + 4, p.y)
                vt:write_float(NET.off.lpos + 8, p.z)
                vt:write_float(NET.off.lrot, r.w)
                vt:write_float(NET.off.lrot + 4, r.x)
                vt:write_float(NET.off.lrot + 8, r.y)
                vt:write_float(NET.off.lrot + 12, r.z)
            end
            if NET.sync_health and NET.off.lhealth and NET.off.lflags then
                local hpc = comp(p1, "app.ropeway.HitPointController")
                local hp = hpc and safe(function() return hpc:call("get_CurrentHitPoint") end)
                if hp then
                    vt:write_dword(NET.off.lhealth, hp)
                    vt:write_dword(NET.off.lflags, (vt:read_dword(NET.off.lflags) or 0) | 2)   -- bit 1: health valid
                end
            end
        end
NET.send_input(vt)
        if NET.off.laim then
            local ax, ay, az = NET.local_aim_point()
            if ax then
                vt:write_float(NET.off.laim, ax)
                vt:write_float(NET.off.laim + 4, ay)
                vt:write_float(NET.off.laim + 8, az)
                vt:write_dword(NET.off.laim_valid, 1)
            else
                vt:write_dword(NET.off.laim_valid, 0)
            end
        end
        NET.rvalid = vt:read_dword(NET.off.rvalid)
        if NET.rvalid == 1 and st.hunk and not st.climbing(st.hunk) then
            -- With the remote input driving HUNK's own locomotion the position sync only
            -- corrects drift: HUNK walks himself (feet/hitboxes real), and we nudge him toward
            -- the remote snapshot when they part company (8 m+: hard snap for loads/warps,
            -- 2-8 m: converge, under 2 m: a subtle pull that keeps him in step).
            local ro = NET.off.remote
            local x, y, z = vt:read_float(ro), vt:read_float(ro + 4), vt:read_float(ro + 8)
            local qw, qx, qy, qz = vt:read_float(ro + 12), vt:read_float(ro + 16), vt:read_float(ro + 20), vt:read_float(ro + 24)
            if x == 0 and y == 0 and z == 0 then return end   -- no data / not sent yet
            local cur = st.hunk:call("get_Transform"):call("get_Position")
            local dx, dy, dz = x - cur.x, y - cur.y, z - cur.z
            local dist2 = dx * dx + dy * dy + dz * dz
            local pos
            if dist2 > 64 then                       -- > 8 m: snap (load screens, warps)
                pos = Vector3f.new(x, y, z)
            elseif dist2 > 4 then                    -- 2-8 m: converge
                pos = Vector3f.new(cur.x + dx * 0.5, cur.y + dy * 0.5, cur.z + dz * 0.5)
            elseif dist2 > 0.01 then                 -- < 2 m: stay in step under the input
                pos = Vector3f.new(cur.x + dx * 0.02, cur.y + dy * 0.02, cur.z + dz * 0.02)
            end
            if pos then
                st.warp_go(st.hunk, pos, Quaternion.new(qw, qx, qy, qz))
            end
            -- Health mirror (milestone 4, damage): keep the puppet's hit points in step with the
            -- remote player's, so the peer's real damage shows on our HUNK and downing him there
            -- brings him down here. A deadband + clamp so it can't spike; skipped while
            -- HUNK is downed/immune/child, and only every 10th frame. Toggle: net menu.
            if NET.sync_health and NET.off.lhealth and st.hunk and not st.p2_down
                and not (st.p2_child and st.p2_child()) and not st.invulnerable and st.frame % 10 == 0 then
                local rf = vt:read_dword(ro + S_FLAGS) or 0
                if (rf & 2) ~= 0 then
                    local rhp = vt:read_dword(ro + S_HP)
                    local hpc = comp(st.hunk, "app.ropeway.HitPointController")
                    local cur = hpc and safe(function() return hpc:call("get_CurrentHitPoint") end)
                    if cur and rhp then
                        local d = rhp - cur
                        if d <= -1 or d >= 2 then
                            d = math.max(-150, math.min(150, d))
                            pcall(function() hpc:call("addDamage", d) end)
                        end
                    end
                end
            end
        end
    end

    return NET
end)(safe, p1_go, comp, st, say)

-- The network menu lives in its own function so its many locals can't exhaust the
-- co-op menu function's local-variable budget. Called from the menu with pcall(RE2R_MP_MENU).
RE2R_MP_MENU = (function()
    local NET = RE2R_MP_NET
    return function()
        imgui.spacing()
        imgui.text("Raccoon City: Reunited — Network")
        imgui.text("  status: " .. NET.status_text())
        imgui.set_next_item_width(180)
        local ci, iv = imgui.input_text("peer ip (internet)", NET.ip, 0)
        if ci and iv and iv ~= "" then NET.ip = iv end
        imgui.set_next_item_width(180)
        local cp, pv = imgui.slider_int("udp port", NET.port, 1024, 65535)
        if cp and pv then NET.port = pv end
        if imgui.button("Host") then NET.start_host() end
        imgui.same_line()
        if imgui.button("Join") then NET.start_join() end
        imgui.same_line()
        if imgui.button("Scan LAN") then NET.scan() end
        imgui.same_line()
        if imgui.button("Stop") then NET.stop() end
        local ch, cv = imgui.checkbox("sync health (damage)", NET.sync_health)
        if ch then NET.sync_health = cv end
        local fcnt = NET.found_count()
        if fcnt > 0 then
            imgui.text("  hosts found (click to join):")
            for i = 1, fcnt do
                local f = NET.found(i)
                if f and f ~= "" then
                    if imgui.small_button("join " .. f) then
                        local ip, pt = f:match("([^:]+):(%d+)")
                        NET.start_join(ip, tonumber(pt))
                    end
                end
            end
        end
    end
end)()

-- Frame loop --------------------------------------------------------------------

re.on_frame(function()
    st.frame = st.frame + 1
    pcall(RE2R_MP_NET.tick)
    pcall(st.pad.update_capture)
    if st.pending and safe(function() return st.pending:call("get_Ready") end) then
        local ok, err = pcall(finish_spawn)
        if not ok then say("Spawn failed: " .. tostring(err)) end
    elseif st.pending and st.pending_rig ~= "pl4000" and os.clock() - (st.pending_t or 0) > 12 then
        -- that character's prefab never loaded: use the stand-in rig
        st.rig_failed = st.rig_failed or {}
        st.rig_failed[st.pending_rig] = true
        st.pending = nil
        pcall(spawn)
    end
    pcall(st.load_watch)
    if st.fix_at and st.frame >= st.fix_at then st.fix_at = nil; pcall(fix_costume) end
    if st.frame % 30 == 0 then pcall(st.model_fixups) end
    local now = os.clock()
    local dt = st.last_clock and math.min(now - st.last_clock, 0.1) or 0.016
    st.last_clock = now
    -- (player 2's camera follows HUNK with the game's own frame time: os.clock has 1 ms steps
    -- and is read when REFramework draws, not when the game steps HUNK, so the follow lag
    -- wobbled from frame to frame: HUNK twitched in his own view while moving)
    local gdt = safe(function() return sdk.call_native_func(sdk.get_native_singleton("via.Application"), sdk.find_type_definition("via.Application"), "get_ElapsedSecond") end)
    if gdt and gdt > 0 and gdt < 0.1 then dt = gdt end
    if st.frame % 60 == 0 then clear_comp_cache() end
    -- no controllable P1 (title, loading, some cutscenes): leave HUNK alone
    local p1_ok = p1_go() ~= nil
    pcall(update_p2cam, dt)
    pcall(update_ai, dt)
    if st.frame % 30 == 0 then pcall(update_ai_spawn) end
    split.fps = split.fps and (split.fps * 0.95 + (1 / math.max(dt, 0.001)) * 0.05) or 60
    if p1_ok and st.hunk then
        pcall(st.tank.update, dt)
        pcall(update_vaim, dt)
        if st.infinite_ammo and st.frame % 6 == 0 then pcall(refill_ammo) end
        pcall(st.p2inv.tick)
        if st.frame % 60 == 30 and st.loadout_given and not st.pending then
            -- (slots missing after a load: set the inventory up and hand the weapons out again)
            pcall(function()
                local hinv = comp(st.hunk, "app.ropeway.survivor.Inventory")
                local sl = hinv and hinv:get_field("_Slots")
                if sl and sl:call("get_Count") == 0 then st.loadout_given = false; give_loadout(nil, true) end
            end)
        end
        if st.frame % 10 == 0 or st.p2_child() then pcall(keep_invulnerable) end
        if st.bb_tick then pcall(st.bb_tick) end   -- (v407) Biohazard Babysitting
        if st.unarmed_tick then pcall(st.unarmed_tick) end   -- (v408) unarmed Sherry
        -- (v387: the AI partner too - it used to be left out, from when the AI was always
        -- invisible, so with Invisible off enemies still only went for player 1)
        -- (v427) not during cutscenes / movies: telling a cutscene's scripted enemies about player 2
        -- can derail what the game does with them when the cutscene ends
        if not st.in_cutscene() then
            if st.frame % 10 == 5 then pcall(st.update_enemy_sense) end
            pcall(st.refresh_engaged)
            pcall(st.refresh_hunters)
        end
        -- player 2 held by an enemy while player 1 isn't (grab camera, prompt, counter button)
        st.p2_held_only = false
        pcall(function()
            local function held(go)
                local c = go and comp(go, "app.ropeway.survivor.player.PlayerCondition")
                return c ~= nil and (c:call("get_IsJack") or c:call("get_IsJackFromEnemy")) == true
            end
            st.p2_held_only = held(st.hunk) and not held(p1_go())
        end)
        pcall(st.ai_guide_hide)
    elseif st.vaim.active then
        st.vaim.active = false
        st.spine_w = 0
    end
    pcall(update_combos)
    if st.dual and st.dual.sc_update then pcall(st.dual.sc_update) end
    if st.dual and st.dual.am_update then pcall(st.dual.am_update) end
    if st.dual and st.dual.fi_update then pcall(st.dual.fi_update) end
    if st.dual and st.dual.down_mark then pcall(st.dual.down_mark) end
    for _, I in ipairs({ st.ig, st.ig1 }) do
        local ok, err = pcall(I.tick)
        if not ok then I.tick_err = tostring(err) end
    end
    pcall(update_reload)
    pcall(update_pickup)
    pcall(update_rewarp)
    pcall(st.split_watch)
    pcall(st.area_update)
    pcall(st.door_push_tick)
    pcall(st.grab_guard_tick)
    pcall(st.p1_release_tick)
    pcall(st.shared_light_tick)
    if st.frame % 3 == 0 then pcall(st.unloaded_watch) end
    pcall(st.door_hold_tick)
    pcall(st.p2_down_tick)
    pcall(st.p1_down_tick)
    pcall(st.jack_watch_tick)
    if st.door_wait then   -- player 2 at a door, waiting for the rooms behind it to be drawn
        local w = st.door_wait
        local ok, ready = pcall(st.area_ready, w.ids)
        if st.hunk == nil then
            st.door_wait = nil
        elseif (ok and ready) or st.frame >= w.give_up then
            st.door_wait = nil
            pcall(door_through, w.door, true)
        end
    end
    if st.pin then   -- keep a rebuilt player 2 where the old one stood
        if st.hunk == nil or st.frame > st.pin.until_frame then
            st.pin = nil
        else
            local pin = st.pin
            pcall(function()
                local hp = st.hunk:call("get_Transform"):call("get_Position")
                if (hp - pin.pos):length() > 0.3 then warp_hunk(pin.pos, pin.rot) end
            end)
        end
    end
    pcall(update_gear)
    if next(flame.last) then pcall(update_flame) end
    if st.frame % 30 == 0 then pcall(update_tracers) end
    if st.frame % 45 == 0 and st.anim then pcall(st.anim.check) end
    if st.cleanup_at and st.frame >= st.cleanup_at then st.cleanup_at = nil; pcall(st.cleanup_parts) end
    -- cutscenes: player 2's HUD is hidden (their menu can't open: p2m_can_open), and when one
    -- that lasted a second or more ends, HUNK is brought to player 1 (the cutscene may have
    -- moved player 1 anywhere). Waits for player 1 to be back after any loading.
    local cut = st.in_cutscene()
    if cut then
        st.cut_start = st.cut_start or st.frame
        st.after_cut = nil
    elseif st.cut_start then
        if st.frame - st.cut_start >= 60 then st.after_cut = { at = st.frame + 20, give_up = st.frame + 900 } end
        st.cut_start = nil
    end
    local ac = st.after_cut
    if ac and st.frame >= ac.at then
        if st.hunk and p1_ok then
            st.after_cut = nil
            pcall(function()
                local hp = st.hunk:call("get_Transform"):call("get_Position")
                local lp = p1_go():call("get_Transform"):call("get_Position")
                if (hp - lp):length() > 2.5 then teleport_to_p1() end
            end)
        elseif st.frame > ac.give_up then
            st.after_cut = nil
        end
    end
    pcall(draw_toast)
    if not (cut and st.split) then
        local labels = {}
        pcall(draw_hud, labels)
        pcall(st.draw_down_overlay, labels)
        if p1_ok and not p2c.active and not st.cut_hide.on then pcall(draw_offscreen) end
        if p2c.active then pcall(draw_split_reticles); pcall(st.draw_save_overlay, labels); pcall(st.draw_inv_strips) end
        pcall(HUD.flush_labels, labels)
    end
    if st.verify_at and st.frame >= st.verify_at then st.verify_at = nil; pcall(verify_costume) end

    if st.frame % 10 == 0 then pcall(refresh_unit) end
    if st.frame % 30 == 0 then
        pcall(refresh_owners)
        if st.hunk and not safe(function() return st.hunk:call("get_Valid") end) then
            -- GameObject destroyed by the game (area change, reload): forget it
            st.hunk = nil
            forget_weapons()
            st.loadout_given = false
            st.owners = {}
            clear_comp_cache()
            -- (brought back once play is steady again: st.load_watch)
            st.reload = { human = not st.ai }
            st.unloading, st.back_frames = true, 0
            say("Player 2 was unloaded by the game; bringing them back")
        end
        if not context_installed then
            local go = p1_go()
            if go then pcall(install_context_hooks, go) end
        end
    end
    -- guard against unbalanced stacks
    for id, s in pairs(st.stacks) do
        if #s > 64 then st.stacks[id] = {} end
    end
end)

-- Settings (saved to reframework/data/reunited_config.json) -------------------------

local CONFIG_FILE = "reunited_config.json"
st.play_mode = ""        -- the way of play: "shared" / "fixed" / "split" / "ai" (co-op menu > Play > Ways to play)
st.ai_cam = "shared"     -- AI Companion's camera: "shared" (the game's own) or "fixed" (Classic Cameras)
st.p2_abilities = true   -- player 2's heal (Y) / refill (X) abilities: set by the difficulty (st.DIFF_SETS)
st.aim_defaults = 0      -- 1 once Free aim / laser on by default (v1.4) has been applied to a saved config
st.bb_window = "standard"   -- (v407) Biohazard Babysitting's rescue window: "forgiving" / "standard" / "pushing"
st.bb_prev_model = ""       -- player 2's character before Babysitting (put back when it ends)
st.bb_flash = 0             -- flash grenades Babysitting put in Sherry's inventory (taken out when it ends)
st.bb_grew = 0              -- pouch slots Babysitting added to make room for it
st.BB_ENABLED = false       -- (v408) Biohazard Babysitting is on the backlog: hidden and off
st.sherry_unarmed = false   -- (v408) Sherry as player 2 carries nothing (Player 2 > Character)
st.p2_silent = false   -- (v425) player 2 makes no voice sounds (Player 2 > Character)
st.p2_flash_bright = 100   -- (v432) player 2's flashlight brightness, % of player 1's (REFramework panel)
st.friendly_fire = false   -- (v438) Extras > Experimental: players' attacks hurt each other (st.ff)
st.ff_pct = 50   -- (v438) a friendly hit, % of what it does to an enemy
st.shared_inv = false   -- (v441) Extras > Experimental: the players share one inventory (st.shared)
st.p2_key_items = false   -- (v444) player 2 may pick up key / story items (to player 1's inventory); REFramework panel
st.split_sss_fix = true   -- (v442; v443 on by default, off only in the REFramework panel) no SubsurfaceSettings on player 2's camera (white skin / props in split)
st.p2_beam_pct = 100   -- (v433) player 2's visible flashlight beam (light shaft density), % of player 1's
st.p2_wheel = true         -- (v419) player 2's quick menu on held RB
local SAVED = { "play_mode", "ai_cam", "p2_abilities", "show_hud", "hud_alpha", "heal_amount", "heal_cooldown", "resupply_cooldown",
    "infinite_ammo", "invulnerable", "no_grab", "p2_invisible", "sub_aim", "offscreen_ind", "sfx", "sfx_abilities",
