local function load_config()
    local ok, t = pcall(json.load_file, CONFIG_FILE)
    if not ok or type(t) ~= "table" then return end
    for _, k in ipairs(SAVED) do
        if t[k] ~= nil and type(t[k]) == type(DEFAULTS[k]) then st[k] = t[k] end
    end
end
