-- (NonRT-7) No controller rumble from a downed player. On Non-RT a player held down on the floor
-- (the fall motion stopped at its landing frame) kept setting the controllers vibrating: the
-- motion's vibration track fires again and again at that frame. While a player is down, their
-- body's vibration requests are dropped (VibrationController.canRequest -> false, and the
-- VibrationManager's requests naming their GameObject are skipped), and anything already
-- running is stopped once when they go down.
;(function()
    if not st.NON_RT then return end
    local function downed_go_addr(go_addr)
        if go_addr == nil or go_addr == 0 then return false end
        if st.p2_down and st.hunk and (st.hunk:get_address() & 0xFFFFFFFFFFFF) == go_addr then return true end
        if st.p1_down then
            local p1 = p1_go()
            if p1 and (p1:get_address() & 0xFFFFFFFFFFFF) == go_addr then return true end
        end
        return false
    end
    local function any_down() return (st.p2_down ~= nil and st.p2_down ~= false) or (st.p1_down ~= nil and st.p1_down ~= false) end
    st.vib_blocked = 0
    local vc = sdk.find_type_definition("app.ropeway.VibrationController")
    local cr = vc and vc:get_method("canRequest(app.ropeway.tracks.VibrationTrack, System.String)")
    if vc and cr == nil then
        for _, m in ipairs(vc:get_methods()) do if m:get_name() == "canRequest" then cr = m end end
    end
    if cr then
        pcall(sdk.hook, cr, function(args)
            if not any_down() then return end
            local ok, own = pcall(function() return sdk.to_managed_object(args[2]):call("get_GameObject") end)
            if ok and own and downed_go_addr(own:get_address() & 0xFFFFFFFFFFFF) then
                thread.get_hook_storage().nv = true
                st.vib_blocked = st.vib_blocked + 1
                return sdk.PreHookResult.SKIP_ORIGINAL
            end
            thread.get_hook_storage().nv = nil
        end, function(r)
            if thread.get_hook_storage().nv then thread.get_hook_storage().nv = nil; return sdk.to_ptr(0) end
            return r
        end)
    end
    local vm = sdk.find_type_definition("app.ropeway.VibrationManager")
    for _, m in ipairs(vm and vm:get_methods() or {}) do
        local n = m:get_name()
        local gi = nil   -- which argument is the GameObject
        if n == "requestVibrationSS" or n == "requestVibrationS" or n == "requestVibrationM" or n == "requestVibrationL" then gi = 3
        elseif n == "requestAdd" and m:get_num_params() == 3 then gi = 5 end
        if gi then
            pcall(sdk.hook, m, function(args)
                if not any_down() then return end
                if downed_go_addr(sdk.to_int64(args[gi]) & 0xFFFFFFFFFFFF) then
                    st.vib_blocked = st.vib_blocked + 1
                    return sdk.PreHookResult.SKIP_ORIGINAL
                end
            end, function(r) return r end)
        end
    end
    -- when someone goes down: stop what's already rumbling, once
    local was = false
    re.on_frame(function()
        local now = any_down()
        if now and not was then
            pcall(function()
                local mgr = sdk.get_managed_singleton("app.ropeway.VibrationManager")
                if mgr then mgr:call("requestStop") end
            end)
        end
        was = now
    end)
end)()

-- Co-op menu ------------------------------------------------------------------------------
-- A controller-driven overlay for the couch: hold L3 + R3 on any controller (about a
-- second) or press F2. D-pad or left stick moves, left / right changes a value, A picks,
-- B goes back. The game is paused and gets no pad input while it is open. Any connected
-- controller can drive it.
;(function()   -- own function: the main chunk is at Lua's local-variable limit

local MENU_HOLD = 0.8
local MB = { UP = 1, DOWN = 2, LEFT = 4, RIGHT = 8, A = 32, B = 128, LB = 256, RB = 1024, START = 32768 }
local VK = { F2 = 0x71, UP = 0x26, DOWN = 0x28, LEFT = 0x25, RIGHT = 0x27, ENTER = 0x0D, ESC = 0x1B, BACKSPACE = 0x08, SPACE = 0x20, Q = 0x51, E = 0x45 }
local menu_hold = {}   -- controller uid -> time L3 + R3 went down
local key_prev = {}

local function key_down(vk)
    local ok, v = pcall(function() return reframework:is_key_down(vk) end)
    return ok and v == true
end
local function key_pressed(vk)
    local d = key_down(vk)
    local was = key_prev[vk]
    key_prev[vk] = d
    return d and not was
end

local function pad_by_uid(uid)
    for _, p in ipairs(st.menu_pads()) do if p.uid == uid then return p end end
    return nil
end
-- (player 1's action button by name, for prompts: her controller's A, else "Action")
function st.p1_action_label()
    if st.p1_lbl and st.frame - st.p1_lbl.at < 120 then return st.p1_lbl.text end
    local p = st.p1_uid and pad_by_uid(st.p1_uid)
    local text = p and (BTN_NAMES[p.style or "xbox"] or BTN_NAMES.xbox).A or "Action"
    st.p1_lbl = { at = st.frame, text = text }
    return text
end
-- (player 1's controller brand, for button names)
function st.p1_pad_style()
    local p = (st.p1_uid and pad_by_uid(st.p1_uid)) or (st.menu_pads() or {})[1]
    return p and p.style or "xbox"
end
local function pad_buttons(p)
    return p and p.dev and (safe(function() return p.dev:call("get_Button") end) or 0) or 0
end
local function cycle(list, cur, dir)
    local i = 1
    for k, v in ipairs(list) do if v == cur then i = k end end
    return list[(i - 1 + dir) % #list + 1]
end

local function current_scene()
    return safe(function()
        return sdk.call_native_func(sdk.get_native_singleton("via.SceneManager"), sdk.find_type_definition("via.SceneManager"), "get_CurrentScene")
    end)
end
local function set_paused(on)
    local sc = current_scene()
    if sc == nil then return end
    if on then
        if menu.saved_ts == nil then
            menu.saved_ts = safe(function() return sc:call("get_TimeScale") end) or 1.0
            safe(function() sc:call("set_TimeScale", 0.0) end)
        end
    elseif menu.saved_ts ~= nil then
        safe(function() sc:call("set_TimeScale", menu.saved_ts) end)
        menu.saved_ts = nil
    end
end

local function menu_close()
    menu.open = false
    menu.just_closed = true
    menu.blocking = true   -- keep the game blind until the menu buttons are let go
    menu.assign = nil
    set_paused(false)
    if menu.dirty_model then menu.dirty_model = false; pcall(apply_model) end
    save_config()
end

local function menu_open(uid, kb)
    if p1_go() == nil or st.in_cutscene() then
        toast("The co-op menu can't open during cutscenes or loading")
        return
    end
    menu.open, menu.page, menu.idx, menu.uid, menu.stack = true, "t_play", 1, uid, {}
    menu.tab, menu.scroll, menu.kb, menu.items = 1, 0, kb == true, nil
    menu.pending_p1, menu.pending_p2 = false, false
    menu.held = 0xFFFFFFFF   -- ignore the buttons still down from opening it
    menu.rep = {}
    set_paused(true)
end

-- controllers: make P1's pad the game's own and re-route HUNK
local function apply_pads()
    local p1 = pad_by_uid(st.p1_uid)
    local is = sdk.get_managed_singleton("app.ropeway.InputSystem")
    if p1 and is then safe(function() is:call("changeActiveUserDevice", p1.dev) end) end
    pcall(refresh_unit)
end
local function set_pad_role(p)
    if st.kbm_on then   -- player 1 is on the keyboard: a controller can only be player 2
        st.p2_uid = p.uid
        pcall(refresh_unit)
        return
    end
    if p.uid == st.p1_uid or p.uid == st.p2_uid then
        if st.p2_uid and pad_by_uid(st.p2_uid) then st.p1_uid, st.p2_uid = st.p2_uid, st.p1_uid end
    else
        st.p2_uid = p.uid   -- a third controller takes over player 2
    end
    apply_pads()
end

-- (player 2's starter kit when Infinite ammo is off: see "Player 2's own inventory")
local DIFFS = { { id = "boy", name = "Rookie" }, { id = "friend", name = "Operative" }, { id = "war", name = "Veteran" } }
local function start_kit_item()
    local cur = 2
    for i, k in ipairs(DIFFS) do if k.id == st.p2_difficulty then cur = i end end
    local function step(d) cur = (cur - 1 + (d or 1)) % #DIFFS + 1; st.p2_difficulty = DIFFS[cur].id end
    return { label = "  Difficulty (loadout when nothing is saved)", value = DIFFS[cur].name, change = step, press = function() step(1) end }
end
st.start_kit_item = start_kit_item
-- Difficulty page (player 2's menu, Co-op > Play and Co-op > Player 2): the difficulty as set for
-- the current way of play (st.DIFF_SETS). Choosing one gives player 2 that loadout now (it
-- replaces what he carries); choosing the current one again resets it
local DIFF_SHORT = { boy = "Casual", friend = "Balanced", war = "Hardcore" }
local function diff_value()
    if st.play_mode == "classic" then return st.CLASSIC_DIFF end
    if st.play_mode == "babysit" then return "Biohazard Babysitting" end
    for _, k in ipairs(DIFFS) do if k.id == st.p2_difficulty then return k.name end end
    return "?"
end
st.diff_value = diff_value
local function diff_page()
    local it = {}
    if st.play_mode == "classic" then   -- (its own difficulty only)
        it[#it + 1] = { label = st.CLASSIC_DIFF, value = "Active", disabled = true,
            help = st.DIFF_SETS.classic.boy.about .. ". HUNK Classic always plays this way; the other ways keep their own difficulty." }
        return it, "Difficulty"
    end
    for _, k in ipairs(DIFFS) do
        local set = st.diff_set(k.id)
        local cur = st.p2_difficulty == k.id
        it[#it + 1] = { label = k.name .. " (" .. DIFF_SHORT[k.id] .. ")", value = cur and "Active" or nil,
            help = (set and set.about or "") .. ". Replaces " .. st.p2_name() .. "'s inventory with this loadout.", press = function()
                st.apply_diff(k.id, true)
                toast(st.hunk and (st.p2_name() .. "'s loadout reloaded: " .. k.name)
                    or (k.name .. ": " .. st.p2_name() .. " gets this loadout when he spawns"))
            end }
    end
    return it, "Difficulty"
end
st.diff_page = diff_page
local function toggle_item(label, key, after)
    -- (v406) locked on for a child player 2 (st.child_guard)
    if (key == "invulnerable" or key == "no_grab") and st.p2_child and st.p2_child() then
        if st.bb_on and st.bb_on() then   -- (v407) Biohazard Babysitting
            return { label = label, value = key == "invulnerable" and "Hurt = game over" or "Off: rescue her", disabled = true, locked = true,
                lhelp = key == "invulnerable" and "Biohazard Babysitting: if Sherry would be hurt, it's game over."
                    or "Biohazard Babysitting: enemies can grab Sherry. Hit the enemy within the rescue window and she breaks free." }
        end
        return { label = label, value = "On", disabled = true, locked = true }
    end
    local function flip() st[key] = not st[key]; if after then after() end end
    return { label = label, value = st[key] and "On" or "Off", change = flip, press = flip }
end

local function num_item(label, key, step, lo, hi, fmt)
    local v = st[key]
    return { label = label, value = type(fmt) == "function" and fmt(v) or string.format(fmt, v),
        change = function(d) st[key] = math.max(lo, math.min(hi, st[key] + d * step)) end }
end

-- Menu look: RE2's own pause / options screens. A dark see-through panel, off-white type, thin
-- rules, the selected row lit by a white bar fading to the right, category tabs along the top
-- (LB / RB) with an icon each, a line of help for the highlighted row, and the controller's own
-- button glyphs in the footer. Shared by the co-op menu and player 2's menu. Shapes go through
-- draw.* (under the window), words through imgui in a borderless window on top.
local UI = { k = 1 }
UI.C = {
    shade = 0xB8000000, panel = 0xE60C0C0C, band = 0xF0060606, rule = 0x34FFFFFF,
    text = 0xFFECECEC, soft = 0xFFA6A6A6, dim = 0xFF5A5A5A, head = 0xFF808080, shadow = 0xC0000000,
    key = 0xFF2C2C2C, key_edge = 0x90FFFFFF,
    accent = 0xFFD61E26,
}
function UI.push(px) return pcall(imgui.push_font_size, math.max(8, math.floor(px * UI.k + 0.5))) end
function UI.tw(s, px)
    local p = UI.push(px)
    local w = imgui.calc_text_size(s).x
    if p then imgui.pop_font_size() end
    return w
end
-- text at (x, top y); align "r" = x is the right edge, "c" = x is the middle
function UI.text(s, x, y, col, px, align)
    local p = UI.push(px)
    local tx = x
    if align then
        local w = imgui.calc_text_size(s).x
        tx = align == "r" and x - w or x - w / 2
    end
    imgui.set_cursor_screen_pos(Vector2f.new(tx + 1, y + 1))
    imgui.text_colored(s, UI.C.shadow)
    imgui.set_cursor_screen_pos(Vector2f.new(tx, y))
    imgui.text_colored(s, col)
    if p then imgui.pop_font_size() end
end
function UI.line(x1, y1, x2, y2, w, c)
    local dx, dy = x2 - x1, y2 - y1
    local l = math.max(0.001, math.sqrt(dx * dx + dy * dy))
    local nx, ny = -dy / l * w / 2, dx / l * w / 2
    draw.filled_quad(x1 + nx, y1 + ny, x2 + nx, y2 + ny, x2 - nx, y2 - ny, x1 - nx, y1 - ny, c)
end
function UI.tri(x1, y1, x2, y2, x3, y3, c) draw.filled_quad(x1, y1, x2, y2, x3, y3, x3, y3, c) end
function UI.rule(x, y, w, c) draw.filled_rect(x, y, w, math.max(1, UI.k), c or UI.C.rule) end
-- white light fading out to the right (the game's highlight)
function UI.fade(x, y, w, h, a0)
    local n = 24
    local xa = math.floor(x)
    for i = 0, n - 1 do
        local xb = math.floor(x + w * (i + 1) / n)
        local a = math.floor(a0 * (1 - i / n) ^ 1.5)
        if a > 0 and xb > xa then draw.filled_rect(xa, y, xb - xa, h, (a << 24) | 0xFFFFFF) end
        xa = xb
    end
end
function UI.box(x, y, w, h, c, wl)   -- outlined rectangle
    wl = wl or math.max(1, UI.k)
    draw.filled_rect(x, y, w, wl, c); draw.filled_rect(x, y + h - wl, w, wl, c)
    draw.filled_rect(x, y, wl, h, c); draw.filled_rect(x + w - wl, y, wl, h, c)
end

-- icons, drawn in a box s wide centred on (x, y); bg = the colour behind (for cut-outs)
UI.ICON = {
    play = function(x, y, s, c) UI.tri(x - s * 0.32, y - s * 0.42, x + s * 0.44, y, x - s * 0.32, y + s * 0.42, c) end,
    person = function(x, y, s, c)
        draw.filled_circle(x, y - s * 0.24, s * 0.21, c, 16)
        draw.filled_quad(x - s * 0.44, y + s * 0.46, x - s * 0.28, y + s * 0.04, x + s * 0.28, y + s * 0.04, x + s * 0.44, y + s * 0.46, c)
    end,
    radar = function(x, y, s, c, bg)   -- a sweep: the partner keeping watch
        draw.outline_circle(x, y, s * 0.44, c, 24); draw.outline_circle(x, y, s * 0.44 - UI.k, c, 24)
        draw.outline_circle(x, y, s * 0.22, c, 20)
        UI.line(x, y, x + s * 0.31, y - s * 0.31, math.max(1.5, 2 * UI.k), c)
        draw.filled_circle(x - s * 0.16, y + s * 0.12, s * 0.07, c, 8)
    end,
    screen = function(x, y, s, c)   -- a screen split in two
        local w, h = s * 0.9, s * 0.62
        UI.box(x - w / 2, y - h / 2, w, h, c, math.max(1.5, 2 * UI.k))
        draw.filled_rect(x - math.max(1, UI.k), y - h / 2, math.max(2, 2 * UI.k), h, c)
        draw.filled_rect(x - s * 0.2, y + h / 2 + s * 0.06, s * 0.4, math.max(1.5, 2 * UI.k), c)
    end,
    pad = function(x, y, s, c, bg)   -- a controller
        draw.filled_rect(x - s * 0.36, y - s * 0.22, s * 0.72, s * 0.3, c)
        draw.filled_circle(x - s * 0.3, y + s * 0.02, s * 0.2, c, 14)
        draw.filled_circle(x + s * 0.3, y + s * 0.02, s * 0.2, c, 14)
        draw.filled_rect(x - s * 0.38, y - s * 0.07, s * 0.16, s * 0.05, bg)
        draw.filled_rect(x - s * 0.325, y - s * 0.13, s * 0.05, s * 0.17, bg)
        draw.filled_circle(x + s * 0.27, y - s * 0.1, s * 0.04, bg, 6)
        draw.filled_circle(x + s * 0.35, y - s * 0.02, s * 0.04, bg, 6)
    end,
    star = function(x, y, s, c)
        local ro, ri = s * 0.48, s * 0.2
        local function pt(i, r) local a = -math.pi / 2 + i * math.pi / 5; return x + math.cos(a) * r, y + math.sin(a) * r + s * 0.04 end
        for i = 0, 4 do
            local ox, oy = pt(i * 2, ro)
            local ax, ay = pt(i * 2 - 1, ri)
            local bx, by = pt(i * 2 + 1, ri)
            draw.filled_quad(x, y + s * 0.04, ax, ay, ox, oy, bx, by, c)
        end
    end,
    ammo = function(x, y, s, c)   -- three rounds
        for _, dx in ipairs({ -0.3, 0, 0.3 }) do
            local bx = x + dx * s
            draw.filled_circle(bx, y - s * 0.2, s * 0.1, c, 10)
            draw.filled_rect(bx - s * 0.1, y - s * 0.2, s * 0.2, s * 0.6, c)
        end
    end,
    camera = function(x, y, s, c, bg)
        draw.filled_rect(x - s * 0.44, y - s * 0.24, s * 0.88, s * 0.56, c)
        draw.filled_rect(x - s * 0.16, y - s * 0.36, s * 0.3, s * 0.14, c)
        draw.filled_circle(x, y + s * 0.04, s * 0.19, bg, 16)
        draw.filled_circle(x, y + s * 0.04, s * 0.11, c, 12)
    end,
    aim = function(x, y, s, c)
        local w = math.max(1.5, 2 * UI.k)
        draw.outline_circle(x, y, s * 0.3, c, 20); draw.outline_circle(x, y, s * 0.3 - UI.k, c, 20)
        UI.line(x, y - s * 0.5, x, y - s * 0.18, w, c); UI.line(x, y + s * 0.18, x, y + s * 0.5, w, c)
        UI.line(x - s * 0.5, y, x - s * 0.18, y, w, c); UI.line(x + s * 0.18, y, x + s * 0.5, y, w, c)
    end,
    box = function(x, y, s, c, bg)   -- an item box
        draw.filled_rect(x - s * 0.44, y - s * 0.16, s * 0.88, s * 0.5, c)
        draw.filled_rect(x - s * 0.48, y - s * 0.34, s * 0.96, s * 0.14, c)
        draw.filled_rect(x - s * 0.07, y - s * 0.12, s * 0.14, s * 0.16, bg)
    end,
}
function UI.icon(name, x, y, s, c, bg)
    local f = UI.ICON[name]
    if f then pcall(f, x, y, s, c, bg or UI.C.band) end
end

-- button glyphs. style: "xbox" / "ps" / "nin" / "kb". Draws with its left edge at x, centred on
-- cy; returns the width
local FACE = { A = true, B = true, X = true, Y = true }
local XB = { A = 0xFF3CB45F, B = 0xFF3C3CD8, X = 0xFFD8822E, Y = 0xFF2CC0EA }
local PSC = { A = 0xFFE8B27C, B = 0xFF6A6AFF, X = 0xFFC684D6, Y = 0xFFA0E240 }
local PILL = {
    xbox = { LB = "LB", RB = "RB", LT = "LT", RT = "RT", START = "MENU", BACK = "VIEW", L3 = "LS", R3 = "RS", DPAD = "D-PAD" },
    ps = { LB = "L1", RB = "R1", LT = "L2", RT = "R2", START = "OPTIONS", BACK = "SHARE", L3 = "L3", R3 = "R3", DPAD = "D-PAD" },
    nin = { LB = "L", RB = "R", LT = "ZL", RT = "ZR", START = "+", BACK = "-", L3 = "LS", R3 = "RS", DPAD = "D-PAD" },
}
local KEYS = { LB = "Q", RB = "E", A = "Enter", B = "Esc", START = "F2", LR = "< >", UD = "Up / Dn" }
function UI.glyph(id, x, cy, style)
    local k = UI.k
    local r = 11 * k
    if style == "kb" then
        local lbl = KEYS[id] or id
        local w = math.max(2 * r, UI.tw(lbl, 13) + 14 * k)
        draw.filled_rect(x, cy - r, w, 2 * r, UI.C.key)
        UI.box(x, cy - r, w, 2 * r, UI.C.key_edge)
        UI.text(lbl, x + w / 2, cy - 8 * k, UI.C.text, 13, "c")
        return w
    end
    if id == "LR" then   -- d-pad left / right
        UI.tri(x, cy, x + 8 * k, cy - 7 * k, x + 8 * k, cy + 7 * k, UI.C.text)
        draw.filled_rect(x + 9 * k, cy - 3 * k, 6 * k, 6 * k, UI.C.soft)
        UI.tri(x + 24 * k, cy, x + 16 * k, cy - 7 * k, x + 16 * k, cy + 7 * k, UI.C.text)
        return 24 * k
    end
    if FACE[id] then
        local cx = x + r
        if style == "ps" then
            draw.filled_circle(cx, cy, r, 0xFF262626, 24)
            local c, s, w = PSC[id], r * 0.5, math.max(1.5, 2 * k)
            if id == "A" then UI.line(cx - s, cy - s, cx + s, cy + s, w, c); UI.line(cx - s, cy + s, cx + s, cy - s, w, c)
            elseif id == "B" then draw.outline_circle(cx, cy, s, c, 16); draw.outline_circle(cx, cy, s - k, c, 16)
            elseif id == "X" then UI.box(cx - s, cy - s, 2 * s, 2 * s, c, w)
            else UI.line(cx, cy - s, cx + s, cy + s * 0.7, w, c); UI.line(cx + s, cy + s * 0.7, cx - s, cy + s * 0.7, w, c); UI.line(cx - s, cy + s * 0.7, cx, cy - s, w, c) end
        elseif style == "nin" then
            draw.filled_circle(cx, cy, r, 0xFF2E2E2E, 24)
            local lbl = ({ A = "B", B = "A", X = "Y", Y = "X" })[id]
            UI.text(lbl, cx, cy - 8 * k, UI.C.text, 15, "c")
        else
            draw.filled_circle(cx, cy, r, XB[id], 24)
            UI.text(id, cx, cy - 8 * k, 0xFF141414, 15, "c")
        end
        return 2 * r
    end
    local lbl = (PILL[style] or PILL.xbox)[id] or id
    local w = math.max(2 * r, UI.tw(lbl, 12) + 16 * k)
    draw.filled_rect(x + r * 0.6, cy - r * 0.8, w - r * 1.2, r * 1.6, 0xFF3A3A3A)
    draw.filled_circle(x + r * 0.8, cy, r * 0.8, 0xFF3A3A3A, 16)
    draw.filled_circle(x + w - r * 0.8, cy, r * 0.8, 0xFF3A3A3A, 16)
    UI.text(lbl, x + w / 2, cy - 7 * k, UI.C.text, 12, "c")
    return w
end
-- the footer: { { ids = { "A" }, label = "Select" }, ... }, right-aligned ending at x_right
function UI.footer(list, x_right, cy, style)
    local k = UI.k
    local x = x_right
    for i = #list, 1, -1 do
        local e = list[i]
        x = x - UI.tw(e.label, 15)
        UI.text(e.label, x, cy - 9 * k, UI.C.soft, 15)
        x = x - 8 * k
        for j = #e.ids, 1, -1 do
            -- (measure by drawing off-screen once: glyph widths depend on the label)
            local w = UI.glyph_w(e.ids[j], style)
            x = x - w
            UI.glyph(e.ids[j], x, cy, style)
            x = x - 4 * k
        end
        x = x - 22 * k
    end
end
function UI.glyph_w(id, style)
    local k = UI.k
    local r = 11 * k
    if style == "kb" then return math.max(2 * r, UI.tw(KEYS[id] or id, 13) + 14 * k) end
    if id == "LR" then return 24 * k end
    if FACE[id] then return 2 * r end
    return math.max(2 * r, UI.tw((PILL[style] or PILL.xbox)[id] or id, 12) + 16 * k)
end

-- word wrap to a width (at most max_lines)
function UI.wrap(s, w, px, max_lines)
    local lines, cur = {}, ""
    for word in tostring(s):gmatch("%S+") do
        local try = cur == "" and word or (cur .. " " .. word)
        if UI.tw(try, px) > w and cur ~= "" then
            lines[#lines + 1] = cur
            cur = word
            if #lines >= max_lines then return lines end
        else
            cur = try
        end
    end
    if cur ~= "" and #lines < max_lines then lines[#lines + 1] = cur end
    return lines
end

-- rows: full width, or (items marked grid) two columns side by side; headings take a row
function UI.slots(items)
    local slots, row, gi, grid = {}, 0, 0, false
    for i, e in ipairs(items) do
        if e.grid and not e.head then
            grid = true
            if gi % 2 == 0 then row = row + 1 end
            slots[i] = { col = gi % 2 + 1, row = row }
            gi = gi + 1
        else
            row, gi = row + 1, 0
            slots[i] = { col = 0, row = row }
        end
    end
    return slots, row, grid
end
-- the next row that can be picked (headings can't), from i going dir (wrapping)
function UI.next_sel(items, i, dir)
    local n = #items
    if n == 0 then return 1 end
    for _ = 1, n do
        i = (i - 1 + dir) % n + 1
        if not items[i].head and not items[i].info then return i end
    end
    return 1
end
function UI.first_sel(items)
    for i, e in ipairs(items) do if not e.head and not e.info then return i end end
    return 1
end
-- a reference row (a control and its button): shown, never picked
function UI.info(label, value, glyphs) return { label = label, value = value, info = true, glyphs = glyphs } end
-- page items as shown: "Back" rows dropped (B / Esc goes back)
function UI.clean(items)
    local out = {}
    for _, e in ipairs(items) do if not e.back then out[#out + 1] = e end end
    return out
end
-- what the help line says when a row has no help of its own
local function help_of(e)
    if e == nil then return "" end
    if e.help then return e.help end
    if e.sub then return "Open " .. e.label:gsub("^%s+", "") .. "." end
    if e.change then return "Left / right to change." end
    return ""
end

-- the whole menu. S = {
--   area = { x, y, w, h } (dimmed), W, H (panel), kicker, title, tabs = { { label, icon } }, tab,
--   in_sub, items, idx, st (keeps .scroll), footer = { ... }, style, win, body = function(x, y, w)
-- }
function UI.render(S)
    local k = UI.k
    local C = UI.C
    local ax, ay, aw, ah = S.area[1], S.area[2], S.area[3], S.area[4]
    local W, H = S.W, S.H
    local x0, y0 = math.floor(ax + (aw - W) / 2), math.floor(ay + (ah - H) / 2)
    local PAD = 34 * k
    draw.filled_rect(ax, ay, aw, ah, C.shade)
    draw.filled_rect(x0, y0, W, H, C.panel)
    UI.rule(x0, y0, W, 0x50FFFFFF)
    UI.rule(x0, y0 + H - 1, W, 0x50FFFFFF)
    imgui.set_next_window_pos(Vector2f.new(ax, ay), 1, Vector2f.new(0, 0))
    imgui.set_next_window_size(Vector2f.new(aw, ah), 1)
    if not imgui.begin_window(S.win, true, LABEL_FLAGS) then return end
    -- heading
    UI.text(S.kicker or "", x0 + PAD, y0 + 18 * k, C.accent, 14)
    UI.text(string.upper(S.title or ""), x0 + PAD, y0 + 36 * k, C.text, 32)
    local y = y0 + 84 * k
    -- tabs
    local tabs = S.tabs
    if tabs and #tabs > 0 then
        local TBH = 46 * k
        draw.filled_rect(x0, y, W, TBH, C.band)
        UI.rule(x0, y, W)
        UI.rule(x0, y + TBH - 1, W)
        local cy = y + TBH / 2
        local gl = UI.glyph_w("LB", S.style)
        UI.glyph("LB", x0 + PAD - 10 * k, cy, S.style)
        local gr = UI.glyph_w("RB", S.style)
        UI.glyph("RB", x0 + W - PAD + 10 * k - gr, cy, S.style)
        local tx0, tx1 = x0 + PAD + gl + 6 * k, x0 + W - PAD - gr - 6 * k
        local cw = (tx1 - tx0) / #tabs
        local ICO = 20 * k
        for i, t in ipairs(tabs) do
            local sel = i == S.tab
            local col = sel and C.text or C.soft
            if not sel and S.in_sub then col = C.dim end
            local px = 16
            local lw = UI.tw(string.upper(t.label), px)
            while ICO + 8 * k + lw > cw - 10 * k and px > 11 do px = px - 1; lw = UI.tw(string.upper(t.label), px) end
            local show_label = ICO + 8 * k + lw <= cw - 6 * k
            local full = ICO + (show_label and (8 * k + lw) or 0)
            local cx = tx0 + cw * (i - 1) + (cw - full) / 2
            if sel then
                draw.filled_rect(cx - 12 * k, y + 2 * k, full + 24 * k, TBH - 4 * k, 0x16FFFFFF)
                draw.filled_rect(cx - 4 * k, y + TBH - 4 * k, full + 8 * k, 3 * k, C.accent)
            end
            UI.icon(t.icon, cx + ICO / 2, cy, ICO, col, C.band)
            if show_label then UI.text(string.upper(t.label), cx + ICO + 8 * k, cy - px * k * 0.62, col, px) end
        end
        y = y + TBH
    else
        UI.rule(x0 + PAD, y, W - 2 * PAD)
    end
    -- footer and help
    local FOOT, HELP = 50 * k, 66 * k
    local yf = y0 + H - FOOT
    local yh = yf - HELP
    UI.rule(x0 + PAD, yh, W - 2 * PAD)
    UI.rule(x0, yf, W)
    draw.filled_rect(x0, yf + 1, W, FOOT - 2, C.band)
    if S.footer then UI.footer(S.footer, x0 + W - PAD, yf + FOOT / 2, S.style) end
    if S.note then UI.text(S.note, x0 + PAD, yf + FOOT / 2 - 8 * k, C.dim, 13) end
    -- list
    local ly0, ly1 = y + 14 * k, yh - 8 * k
    if S.body then
        S.body(x0 + PAD, ly0, W - 2 * PAD)
        imgui.end_window()
        return
    end
    local items = S.items or {}
    local slots, nrows, grid = UI.slots(items)
    local RH = (grid and 34 or 38) * k
    local FS = grid and 17 or 19
    local vis = math.max(1, math.floor((ly1 - ly0) / RH))
    local stt = S.st
    stt.scroll = stt.scroll or 0
    local sel_sl = slots[S.idx]
    if sel_sl then
        local r = sel_sl.row
        if r <= stt.scroll then
            stt.scroll = r - 1
            -- (keep the heading above it in view)
            for i, e in ipairs(items) do if e.head and slots[i].row == r - 1 then stt.scroll = r - 2 end end
        elseif r > stt.scroll + vis then
            stt.scroll = r - vis
        end
    end
    -- (on the last row that can be picked: show the reference rows below it too)
    local last
    for i, e in ipairs(items) do if not e.head and not e.info then last = i end end
    if last and S.idx == last then stt.scroll = math.max(stt.scroll, nrows - vis) end
    stt.scroll = math.max(0, math.min(stt.scroll, math.max(0, nrows - vis)))
    local function slot_x(sl)
        local lx, lw = x0 + PAD - 12 * k, W - 2 * PAD + 24 * k
        if sl.col == 0 then return lx, lw end
        local half = (lw - 12 * k) / 2
        if sl.col == 1 then return lx, half end
        return lx + half + 12 * k, half
    end
    for i, e in ipairs(items) do
        local sl = slots[i]
        local row = sl.row - stt.scroll
        if row >= 1 and row <= vis then
            local rx, rw = slot_x(sl)
            local ry = ly0 + (row - 1) * RH
            if e.head then
                local hy = ry + RH - 22 * k
                local t = string.upper(e.label)
                UI.text(t, rx + 12 * k, hy, C.head, 13)
                local tw = UI.tw(t, 13)
                UI.rule(rx + 24 * k + tw, hy + 8 * k, rw - 36 * k - tw)
            else
                local sel = i == S.idx
                local live = e.press or e.change or e.sub
                local lab = e.label
                local ind = 0
                local lead = lab:match("^(%s+)")
                if lead then ind = 22 * k; lab = lab:sub(#lead + 1) end
                if sel then
                    UI.fade(rx, ry + 2 * k, rw, RH - 4 * k, 0x2C)
                    UI.fade(rx, ry + 2 * k, rw, math.max(1, k), 0x90)
                    UI.fade(rx, ry + RH - 3 * k, rw, math.max(1, k), 0x90)
                    draw.filled_rect(rx, ry + 2 * k, 3 * k, RH - 4 * k, C.text)
                end
                if e.lit then draw.filled_rect(rx + 6 * k, ry + 9 * k, 6 * k, RH - 18 * k, C.text) end
                local col = (e.info and C.soft) or (e.lit and C.text) or (e.disabled and C.dim) or (sel and C.text) or (e.muted and C.dim) or (live and C.soft) or C.dim
                local ty = ry + (RH - FS * k * 1.15) / 2
                if ind > 0 then
                    draw.filled_rect(rx + 16 * k, ry + RH / 2, 10 * k, math.max(1, k), C.dim)
                    draw.filled_rect(rx + 16 * k, ry + 4 * k, math.max(1, k), RH / 2 - 4 * k, C.dim)
                end
                UI.text(lab, rx + 16 * k + ind, ty, col, FS)
                local vx = rx + rw - 16 * k
                local my = ry + RH / 2
                if e.sub then
                    UI.tri(vx - 7 * k, my - 6 * k, vx, my, vx - 7 * k, my + 6 * k, sel and C.text or C.dim)
                    vx = vx - 20 * k
                end
                if e.glyphs then   -- buttons drawn as the controller's own glyphs
                    for j = #e.glyphs, 1, -1 do
                        local gw = UI.glyph_w(e.glyphs[j], S.style)
                        vx = vx - gw
                        UI.glyph(e.glyphs[j], vx, my, S.style)
                        vx = vx - 6 * k
                    end
                elseif e.value and e.value ~= "" then
                    local v = tostring(e.value)
                    local vc = (e.info and C.text) or (e.lit and C.text) or (e.disabled and C.dim) or (sel and C.text) or (e.muted and C.dim) or (v == "Off" and C.dim) or ((v == "On" or v == "Active") and C.text) or C.soft
                    if sel and e.change then
                        UI.tri(vx, my, vx - 8 * k, my - 7 * k, vx - 8 * k, my + 7 * k, C.text)
                        vx = vx - 18 * k
                    end
                    local vw = UI.tw(v, FS)
                    UI.text(v, vx, ty, vc, FS, "r")
                    if sel and e.change then
                        local lx = vx - vw - 10 * k
                        UI.tri(lx - 8 * k, my, lx, my - 7 * k, lx, my + 7 * k, C.text)
                    end
                    if v == "Active" then draw.filled_quad(vx - vw - 18 * k, my, vx - vw - 13 * k, my - 5 * k, vx - vw - 8 * k, my, vx - vw - 13 * k, my + 5 * k, C.text) end
                end
            end
        end
    end
    -- scroll bar
    if nrows > vis then
        local tx, th = x0 + W - 14 * k, ly1 - ly0
        draw.filled_rect(tx, ly0, 3 * k, th, 0x30FFFFFF)
        local h = math.max(18 * k, th * vis / nrows)
        draw.filled_rect(tx, ly0 + (th - h) * stt.scroll / (nrows - vis), 3 * k, h, 0xC0FFFFFF)
    end
    -- help for the highlighted row
    local lines = UI.wrap(help_of(items[S.idx]), W - 2 * PAD, 17, 2)
    for i, l in ipairs(lines) do UI.text(l, x0 + PAD, yh + (12 + (i - 1) * 22) * k, C.soft, 17) end
    imgui.end_window()
end

local PAGES = {}
-- Ways to play (st.WAYS: Shared Screen, Fixed Camera, Split Screen) and the AI companion setup.
-- (set = the settings it applies; needs_cc = needs the Classic Cameras mod installed;
-- after = run once the settings are in)
-- the difficulty for the current way (st.DIFF_SETS): its settings, then the loadout. reissue:
-- give the loadout even when the ammo kind didn't change (choosing a difficulty does; changing
-- the way only when Infinite ammo flips, so an own inventory isn't wiped)
local function apply_diff(d, reissue)
    local set = st.diff_set(d)
    if set == nil then return end
    local was_inf = st.infinite_ammo
    st.p2_difficulty = d
    for k, v in pairs(set) do if k ~= "about" then st[k] = v end end
    -- the cooldown boxes come on with the abilities and go off without them (a setting: Screen >
    -- Co-op HUD can turn them back on)
    st.hud_cooldowns = st.cooldowns_on()
    if reissue or was_inf ~= st.infinite_ammo then
        if st.infinite_ammo then pcall(st.give_infinite_kit) else pcall(st.p2inv.rekit) end
    end
    pcall(save_config)   -- (the difficulty is kept across sessions)
end
st.apply_diff = apply_diff
local PRESETS = {}
for _, w in ipairs(st.WAYS) do
    PRESETS[#PRESETS + 1] = { label = w.label, about = w.about, needs_cc = w.needs_cc, set = w.set, way = w.id,
        after = function()
            local was_bb = st.play_mode == "babysit"
            st.play_mode = w.id
            if was_bb and w.id ~= "babysit" and st.bb then pcall(st.bb.leave) end
            if w.id == "babysit" then
                st.ai_no_spawn = nil
                if st.bb then pcall(st.bb.enter) end
            end
            if w.id == "ai" then
                st.ai_no_spawn = nil   -- (the partner joins on its own, as the AI partner switch does)
                if st.ai_cam == "fixed" and st.cc.get() == nil then toast("Fixed camera: turn on Classic Cameras (its Enabled box)") end
            end
            apply_diff(st.p2_difficulty, false)
        end }
end
st.presets = PRESETS
local function way_preset(id) for _, pr in ipairs(PRESETS) do if pr.way == id then return pr end end end
local function preset_active(pr)
    if pr.way == "ai" then return st.play_mode == "ai" and st.ai_partner() end
    if pr.way == "babysit" then return st.play_mode == "babysit" and st.ai_partner() end
    if pr.way then return st.play_mode == pr.way and not st.ai and (pr.way == "split") == (st.split == true) end
    for k, v in pairs(pr.set) do if (st[k] or false) ~= v then return false end end
    return true
end
local function apply_preset(pr)
    for k, v in pairs(pr.set) do st[k] = v end
    if pr.after then pcall(pr.after) end
    save_config()
    toast(pr.label .. " set")
    if pr.needs_cc and st.cc.get() == nil then
        toast(pr.label .. " set: turn on Classic Cameras (its Enabled box) for the fixed cameras")
    end
end
st.apply_preset = apply_preset
function st.side_text(v)
    if v == 0 then return "Default" end
    return string.format("%s %d cm", v < 0 and "Left" or "Right", math.abs(v))
end
local function H(e, help) e.help = e.locked and (e.lhelp or "Sorry, can't hurt children pal! ;)") or help; return e end   -- (v408: Sherry's locked rows)
local function HEAD(t) return { label = t, head = true } end
-- the co-op menu's tabs (LB / RB, keyboard Q / E): each opens on its own first page
local TABS = {
    { label = "Play", icon = "play", page = "t_play" },
    { label = "Player 2", icon = "person", page = "t_p2" },
    { label = "AI Partner", icon = "radar", page = "t_ai" },
    { label = "Screen", icon = "screen", page = "t_screen" },
    { label = "Controls", icon = "pad", page = "controllers" },
    { label = "Extras", icon = "star", page = "t_extras" },
}
menu.tabs = TABS
local function preset_row(pr)
    if pr.needs_cc and not st.cc.installed then
        return { label = pr.label, value = "Needs Classic Cameras", disabled = true,
            help = pr.about .. ". Needs the Classic Cameras mod installed and enabled." }
    end
    return { label = pr.label, value = preset_active(pr) and "Active" or nil, press = function() apply_preset(pr) end,
        help = pr.about .. (pr.way and ". Keeps " .. st.p2_name() .. "'s difficulty, as set for this way." or ".") }
end
PAGES.t_play = function()
    local it = {}
    st.cc.get()
    it[#it + 1] = H({ label = "Resume", press = menu_close }, "Close this menu and carry on playing.")
    if st.hunk then
        it[#it + 1] = H({ label = "Bring " .. st.p2_name() .. " to " .. st.p1_name(), press = function() menu_close(); pcall(teleport_to_p1) end },
            "Teleport player 2 to player 1's side, if they're stuck or lost.")
        it[#it + 1] = H({ label = "Remove player 2", press = function()
            if st.spawn_blocked(true) then toast("Close the game's menu first"); return end   -- (v411)
            menu_close(); st.ai_no_spawn = true; pcall(despawn) end },
            "Take player 2 out of the game. You can spawn them again from here.")
    elseif st.pending == nil then
        it[#it + 1] = H({ label = "Spawn player 2", press = function()
            if st.spawn_blocked(true) then toast("Close the game's menu first"); return end   -- (v411)
            menu_close(); st.ai_no_spawn = nil; pcall(spawn) end },
            "Bring player 2 into the game beside player 1.")
    end
    it[#it + 1] = HEAD("Ways to play")
    for _, pr in ipairs(PRESETS) do
        if pr.way then
            it[#it + 1] = preset_row(pr)
            if pr.way == "babysit" and st.play_mode == "babysit" and st.bb then it[#it + 1] = st.bb.window_row("  ") end
            if pr.way == "ai" and st.play_mode == "ai" then
                local cc = st.cc.installed
                local function flip()
                    if not cc then return end
                    st.ai_cam = st.ai_cam == "fixed" and "shared" or "fixed"
                    if st.ai_cam == "fixed" and st.cc.get() == nil then toast("Fixed camera: turn on Classic Cameras (its Enabled box)") end
                end
                it[#it + 1] = H({ label = "  Camera", value = (st.ai_cam == "fixed" and cc) and "Fixed Camera" or "Shared Screen",
                    change = cc and flip or nil, press = cc and flip or nil, disabled = not cc },
                    cc and "The game's own camera, or Classic Cameras' fixed angles (turn on that mod's Enabled box for them)."
                        or "Fixed angles need the Classic Cameras mod installed.")
            end
        end
    end
    local wl = "Shared Screen"
    for _, w in ipairs(st.WAYS) do if w.id == st.play_mode then wl = w.label end end
    it[#it + 1] = HEAD(st.p2_name() .. " difficulty  (" .. wl .. ")")
    for _, r in ipairs((st.diff_page())) do it[#it + 1] = r end
    local n2 = BTN_NAMES[(pad_by_uid(st.p2_uid) or {}).style or "xbox"] or BTN_NAMES.xbox
    local n1 = BTN_NAMES[(pad_by_uid(st.p1_uid) or {}).style or "xbox"] or BTN_NAMES.xbox
    it[#it + 1] = HEAD("Shortcuts")
    it[#it + 1] = UI.info("This menu", n1.L3 .. " + " .. n1.R3 .. " (hold), or F2")
    it[#it + 1] = UI.info("Player 2's own menu", n2.START .. " on player 2's controller")
    if not st.infinite_ammo then it[#it + 1] = UI.info("Player 2's inventory", n2.BACK .. " on player 2's controller") end
    it[#it + 1] = UI.info("Add / remove player 2", n2.START .. " + " .. n2.BACK .. " on player 2's controller")
    return it, "Play"
end
-- player 2: who they are, what they carry, how tough they are
PAGES.t_p2 = function()
    local it = {}
    local keys, names = {}, {}
    for _, m in ipairs(MODELS) do keys[#keys + 1] = m.key; names[m.key] = m.label end
    it[#it + 1] = HEAD("Character")
    if st.play_mode == "babysit" then   -- (v407)
        it[#it + 1] = { label = "Character", value = names[st.p2_model] or st.p2_model, disabled = true,
            help = "Biohazard Babysitting: player 2 is always Sherry. Pick another way of play to change it." }
    else
    it[#it + 1] = H({ label = "Character", value = names[st.p2_model] or st.p2_model,
        change = function(d) st.p2_model = cycle(keys, st.p2_model, d); menu.dirty_model = true end },
        "Who player 2 plays as. The new model loads when this menu closes.")
    end
    local cl = COSTUMES[st.p2_model]
    if cl then
        local ids, cn = {}, {}
        for _, c in ipairs(cl) do ids[#ids + 1] = c[1]; cn[c[1]] = c[2] end
        local cur = model_costume(st.p2_model)
        it[#it + 1] = H({ label = "Costume", value = cn[cur],
            change = function(d) st["costume_" .. st.p2_model] = cycle(ids, cur, d); menu.dirty_model = true end },
            "Player 2's outfit. It loads when this menu closes.")
    end
    if st.p2_model == "sherry" then   -- (v408)
        it[#it + 1] = H(toggle_item("Unarmed", "sherry_unarmed"),
            "On: Sherry carries no weapons (the AI partner holds fire). Off: she's armed like the others. She can never be hurt or grabbed either way.")
    end
    it[#it + 1] = H(toggle_item("Silent", "p2_silent", function() st.voice_dirty = true; menu.dirty_model = true end),   -- (v425)
        "On: player 2 makes no voice sounds (grunts, shouts, pain). Footsteps and weapons still sound. Applies when this menu closes.")
    it[#it + 1] = HEAD("Gear")
    if not st.infinite_ammo and st.hunk then
        it[#it + 1] = H({ label = "Inventory", sub = "inventory" },
            "What player 2 carries: equip, set d-pad shortcuts, hand things to player 1 or take from them.")
    end
    -- (v440) Inventory Modifier (was Weapons, Rookie only)
    it[#it + 1] = H({ label = "Inventory Modifier", sub = "invmod" },
        "Change what player 2 carries: add or take out items, change amounts, the pouch size and the guns on their d-pad."
            .. (st.infinite_ammo and " Rookie: the d-pad guns and grenade rebuild the infinite-ammo kit." or ""))
    if st.play_mode == "classic" then
        it[#it + 1] = { label = "Difficulty", value = st.CLASSIC_DIFF, disabled = true,
            help = "HUNK Classic has its own difficulty, the original HUNK. It can't be changed in this way of play." }
    elseif st.play_mode == "babysit" and st.bb then
        it[#it + 1] = st.bb.window_row("")
    else it[#it + 1] = H({ label = "Difficulty", value = diff_value(), sub = "difficulty" },
        "How tough player 2's game is, as set for the current way of play. Rookie: infinite ammo; the others: their own inventory.") end
    if not st.infinite_ammo then
        it[#it + 1] = H(toggle_item("  Their pickups are theirs", "p2_pickups"),
            "Ammo, healing and weapons player 2 picks up go into their own inventory instead of player 1's.")
    end
    pcall(st.lo_rows, it, "player 2")
    it[#it + 1] = HEAD("Survival")
    it[#it + 1] = H(toggle_item("Invincible", "invulnerable"),
        "On: player 2 takes no damage. Off: they get hurt, and are downed when their health runs out.")
    it[#it + 1] = H(toggle_item("Can't be grabbed", "no_grab"), "Enemies can't grab or bite player 2.")
    it[#it + 1] = H(toggle_item("Invisible to enemies", "p2_invisible"), "Enemies ignore player 2 and only go after player 1.")
    it[#it + 1] = st.aggro_row("player 2")
    it[#it + 1] = H({ label = "Ability cooldowns", sub = "cooldowns" },
        "How much player 2's heal (Y) gives player 1, and how long heal and magazine refill (X) take to come back."
            .. (st.split and " In split screen the abilities come with Rookie." or ""))
    return it, "Player 2"
end
-- (v388) Enemy attention row (player 2 page and AI page: one setting)
function st.aggro_row(who)
    local e = H(num_item("Enemy attention", "p2_aggro", 1, 1, 4, function(v) return st.AGGRO_NAMES and st.AGGRO_NAMES[v] or tostring(v) end),
        "How much enemies go for " .. who .. " instead of player 1. Less: only when much closer. Normal: when closer. More: further and wider, even a little farther away. Most: whenever they notice them.")
    if st.p2_invisible then e.muted = true; e.help = e.help .. " Turn off Invisible to enemies to use it." end
    return e
end
PAGES.t_ai = function()
    local it = {}
    it[#it + 1] = HEAD("Partner")
    local function flip_ai()
        apply_preset(way_preset(st.play_mode == "ai" and (st.ai_cam == "fixed" and st.cc.installed and "fixed" or "shared") or "ai"))
    end
    it[#it + 1] = H({ label = "AI partner (experimental)", value = st.play_mode == "ai" and "On" or "Off", change = flip_ai, press = flip_ai },
        "The computer plays player 2 and fights alongside player 1. Same as picking AI Companion in Play > Ways to play; its difficulty is set there.")
    it[#it + 1] = H(num_item("Stays within", "ai_follow_dist", 0.5, 1.0, 6.0, "%.1f m of player 1"),
        "How far player 1 can get before the partner follows.")
    it[#it + 1] = H(num_item("Engage range", "ai_range", 1, 5, 30, "%d m"), "How far away the partner starts shooting enemies.")
    it[#it + 1] = HEAD("Support")
    it[#it + 1] = H(num_item("Heal player 1 below", "ai_heal_pct", 10, 0, 90, function(v) return v <= 0 and "Never" or (v .. " / 100 health") end),
        "The partner heals player 1 when their health drops below this.")
    it[#it + 1] = H(toggle_item("Refill player 1's empty magazine", "ai_resupply"), "The partner reloads player 1's gun for them when it runs dry.")
    it[#it + 1] = HEAD("Combat")
    it[#it + 1] = H(toggle_item("Fight at their gun's best range", "ai_ranges"), "The partner keeps to the distance their gun works best at.")
    it[#it + 1] = H(toggle_item("Back off from close enemies", "ai_backoff"), "The partner steps away from enemies that get too close.")
    it[#it + 1] = H(toggle_item("Knife when cornered", "ai_knife"), "The partner uses the knife when an enemy is right on them.")
    it[#it + 1] = H(toggle_item("Step out of your line of fire", "ai_dodge"), "The partner moves aside when player 1 aims through them.")
    it[#it + 1] = H(toggle_item("Only shoot with a clear shot", "ai_clear_shot"), "The partner holds fire when player 1 or a wall is in the way.")
    it[#it + 1] = st.aggro_row("the partner")
    it[#it + 1] = H(toggle_item("Raise their gun when you aim", "ai_mirror"), "The partner aims when player 1 aims.")
    it[#it + 1] = H(toggle_item("Get unstuck (hop out of view)", "ai_unstuck"), "When the partner gets stuck, they move to player 1 while out of sight.")
    it[#it + 1] = HEAD("Command wheel")
    it[#it + 1] = H(toggle_item("Command wheel (hold RB / Z)", "ai_wheel"),
        "Hold RB (keyboard: Z) to give orders: follow, hold, go there, attack, heal and more. With the stick left in the middle, A opens the partner's inventory (Operative / Veteran).")
    it[#it + 1] = H(toggle_item("Slow time while choosing", "wheel_slow"), "Time slows down while the wheel is open.")
    it[#it + 1] = H(toggle_item("Button hints", "wheel_hint"), "Shows which button opens the wheel.")
    it[#it + 1] = H(toggle_item("Order markers (spot / guard area)", "ai_markers"), "Marks the spot or area you sent the partner to.")
    it[#it + 1] = H(toggle_item("Callouts (\"Moving there\" ...)", "ai_callouts"), "The partner's short replies to your orders, on screen.")
    -- (with the partner off the rest is greyed: it still changes, but does nothing until it's on)
    if not st.ai then
        for i = 3, #it do
            local e = it[i]
            if not e.head then e.muted = true; e.help = (e.help or "") .. " Only used with the AI partner on." end
        end
    end
    return it, "AI Partner"
end
PAGES.t_screen = function()
    local it = {}
    it[#it + 1] = HEAD("Split screen")
    local function flip_split()
        local to = st.split and (st.p2_cc and "fixed" or "shared") or "split"
        for _, pr in ipairs(PRESETS) do if pr.way == to then apply_preset(pr) end end
    end
    it[#it + 1] = H({ label = "Split screen (experimental)", value = st.split and "On" or "Off", change = flip_split, press = flip_split },
        "Each player gets their own half of the screen and their own camera. Same as picking Split Screen in Play > Ways to play.")
    if st.split then
        local function flip() st.split_layout = st.split_layout == 2 and 1 or 2 end
        it[#it + 1] = H({ label = "  Layout", value = st.split_layout == 2 and "Top / bottom" or "Side by side", change = flip, press = flip },
            "Halves side by side, or one above the other.")
        it[#it + 1] = H(num_item("  Game HUD shape", "split_hud", 10, 0, 100, function(v) return v <= 0 and "Squeezed" or (v >= 100 and "True shape" or (v .. " / 100")) end),
            "How the game's own HUD fits in a half: squeezed to fit, or its true shape.")
        it[#it + 1] = H(toggle_item("  Bloom", "split_bloom"), "The game's glow. It can flare up as a bright ball in split screen: turn it off if it does.")
        it[#it + 1] = H(toggle_item("  Draw player 2's rooms when apart", "keep_p2_area"),
            "Keeps the rooms around player 2 drawn when the players are far apart.")
        it[#it + 1] = H({ label = "  Refresh split screen", press = function() menu_close(); st.refresh_split() end },
            "Rebuilds both views. Use it if a half looks wrong.")
        it[#it + 1] = HEAD(st.p1_name() .. "'s camera")
        it[#it + 1] = H(num_item("Field of view", "p1_fov_pct", 5, 60, 150, function(v) return v == 100 and "Default" or string.format("%+d", v - 100) end),
            "How wide player 1's view is.")
        it[#it + 1] = H(num_item("Camera distance", "p1_dist_pct", 10, 50, 200, function(v) return v == 100 and "Default" or (v .. " %") end),
            "How far behind player 1 their camera sits.")
        it[#it + 1] = H(num_item("Camera left / right", "p1_side", 5, -100, 100, st.side_text), "Moves player 1's camera to their left or right.")
        it[#it + 1] = H({ label = "Default camera", press = function() st.p1_fov_pct, st.p1_side, st.p1_dist_pct = 100, 0, 100 end },
            "Puts player 1's camera back the way the game has it.")
    end
    it[#it + 1] = HEAD("Co-op HUD")
    it[#it + 1] = H(toggle_item("Co-op HUD (top right)", "show_hud"), "Player 2's health and status in the top right corner.")
    it[#it + 1] = H(toggle_item("Heal / reload cooldowns", "hud_cooldowns"), "Shows how long until player 2's heal and refill are ready again.")
    it[#it + 1] = H(toggle_item("Player 2's weapons", "hud_weapons"), "Player 2's weapon icons in the corner.")
    it[#it + 1] = H(num_item("HUD opacity", "hud_alpha", 16, 64, 255, function(v) return math.floor(v * 100 / 255 + 0.5) .. " / 100" end),
        "How solid the co-op HUD is.")
    it[#it + 1] = H(toggle_item("Arrow to player 2 when off screen", "offscreen_ind"),
        "An arrow at the edge of the screen pointing to player 2 when they're out of view.")
    return it, "Screen"
end
-- extras: fun, player 2's aiming, and Fixed Camera's auto-aim (only on that way)
PAGES.t_extras = function()
    local it = {}
    st.cc.get()
    local inst = st.cc.installed
    it[#it + 1] = HEAD("Fun")
    it[#it + 1] = H(toggle_item("Player 2 in cutscenes", "p2_cutscene_fun"),
        "Player 2 stays visible and can move during cutscenes instead of being hidden. For laughs: it isn't meant to look right.")
    it[#it + 1] = HEAD("Player 2 aiming")
    it[#it + 1] = H(toggle_item("Free aim", "p2_free_aim"), "Player 2 aims anywhere with the right stick instead of where player 1 aims.")
    it[#it + 1] = H(toggle_item("Laser sight", "p2_laser"), "A laser from player 2's gun shows where they're aiming.")
    it[#it + 1] = HEAD("Player 1 aiming")
    it[#it + 1] = H(toggle_item("Laser sight", "p1_laser"),
        "A laser from player 1's gun shows where they're aiming. With Classic Cameras on, its own laser sight is used instead.")
    -- (Fixed Camera gives player 2 tank controls itself: no switch for them)
    if inst and st.play_mode == "fixed" then
        it[#it + 1] = HEAD("Fixed Camera")
