                else P.clear_dir(hinv, old_sc) end
            end
        end
        pcall(P.saved)
    end
    local function amount_text(e)
        if e.wt == 46 then return nil end
        if e.wt > 0 and e.wt ~= 65 and e.wt ~= 66 then return e.num .. " loaded" end
        return "x" .. e.num
    end
