PAGES.invmod = function()
    local it = {}
    local P = st.p2inv
    local hinv = P and P.hunk_inv()
    if hinv == nil then
        it[#it + 1] = { label = st.p2_name() .. " isn't here", disabled = true, help = "Player 2 has to be in the game to change what they carry." }
        it[#it + 1] = { label = "Back", back = true }
        return it, "Inventory Modifier"
    end
    it[#it + 1] = HEAD("D-pad guns")
    if st.infinite_ammo then
        -- Rookie: the old Weapons page (its kit is rebuilt from these)
        local ids = {}
        for _, w in ipairs(WEAPONS) do ids[#ids + 1] = w.wt end
        for _, m in ipairs(MAIN_SLOTS) do
            local w = WEAPON_BY_WT[st[m.key]]
            it[#it + 1] = { label = m.label, value = w and w.name or "?", help = "Rookie's gun on " .. m.label .. ". Changing it rebuilds the infinite-ammo kit (item changes below are reset).", change = function(d)
                local new = cycle(ids, st[m.key], d)
                for _, o in ipairs(MAIN_SLOTS) do
                    if o.key ~= m.key and st[o.key] == new then st[o.key] = st[m.key] end
                end
                st[m.key] = new
                if st.hunk then pcall(give_loadout, m.slot, true) else build_loadout() end
            end }
        end
        local tids = {}
        for _, t in ipairs(THROWABLES) do tids[#tids + 1] = t.wt end
        it[#it + 1] = { label = "Throwable", value = throwable_name(st.throwable), help = "Rookie's grenade on LB.", change = function(d)
            st.throwable = cycle(tids, st.throwable, d)
            if st.hunk then pcall(give_loadout, false, true) else build_loadout() end
        end }
        it[#it + 1] = { label = "Default weapons", help = "Back to Rookie's standard guns.", press = function()
            st.weapon_up, st.weapon_left, st.weapon_right, st.throwable = 11, 7, 23, 66
            if st.hunk then pcall(give_loadout) else build_loadout() end
        end }
    else
        local byi = {}
        for _, e in ipairs(P.list(hinv)) do byi[e.i] = e end
        for _, sc in ipairs(P.SC_ORDER) do
            local cur
            for _, e in ipairs(P.list(hinv)) do if P.shortcut_of(hinv, e.i) == sc then cur = e end end
            local nm = P.SC_NAMES[sc]
            it[#it + 1] = H({ label = nm:sub(1, 1):upper() .. nm:sub(2), value = cur and cur.name or "(none)", change = function(d) IM.dpad(sc, d) end },
                "Which of player 2's guns is on " .. nm .. ". Left / right to change.")
        end
    end
    local list = P.list(hinv)
    local main, sub = P.main_index(hinv), P.sub_index(hinv)
    it[#it + 1] = HEAD("Items  (" .. #list .. " in " .. P.size(hinv) .. " slots)")
    -- (items the game has no name for, e.g. the rocket launcher's internal round, are left out)
    for k = #list, 1, -1 do
        if lo_valid({ wt = list[k].wt > 0 and list[k].wt or nil, id = list[k].id }) == false then table.remove(list, k) end
    end
    for _, e in ipairs(list) do
        local tag = e.i == main and "  (in hand)" or (e.i == sub and "  (off hand)" or "")
        it[#it + 1] = { label = e.name .. tag, value = IM.amount_text(e), sub = "invmod_entry", enter = function() IM.sel = e.i end,
            help = "Change this item or how many, or take it out." }
    end
    if #list == 0 then it[#it + 1] = UI.info("Nothing: add items below") end
    it[#it + 1] = H({ label = "Add an item", press = function()
        local i = IM.add()
        if i then IM.sel = i; menu_push_sub("invmod_entry") end
    end }, "Adds handgun ammo to a free slot; change it to anything else on the next page.")
    local n = P.count(hinv)
    it[#it + 1] = H({ label = "Pouch size", value = P.size(hinv) .. " slots", change = function(d) IM.pouch(d) end },
        "How many slots player 2's inventory has (8 to " .. math.min(20, n) .. ").")
    it[#it + 1] = { label = "Back", back = true }
    return it, "Inventory Modifier"
end
PAGES.invmod_entry = function()
    local it = {}
    local P = st.p2inv
    local hinv = P and P.hunk_inv()
    local e
    for _, x in ipairs(hinv and P.list(hinv) or {}) do if x.i == IM.sel then e = x end end
    if e == nil then return { UI.info("Gone"), { label = "Back", back = true } }, "Item" end
    local cat = lo_cat()
    it[#it + 1] = H({ label = "Item", value = e.name, change = function(dir)
        local k = 1
        for j, c in ipairs(cat) do if lo_same(c, e) then k = j end end
        local c = cat[(k - 1 + dir) % #cat + 1]
        local to = IM.change(e.i, { wt = c.wt, id = c.id, num = c.num, name = lo_iname(c) })
        if to then IM.sel = to end
    end }, "Left / right goes through every gun, the knife, grenades, ammo, healing items and wooden boards.")
    local amt = IM.amount_text(e)
    if amt then
        it[#it + 1] = H({ label = "Amount", value = amt, change = function(dir) IM.amount(e.i, dir) end },
            (e.wt > 0 and e.wt ~= 65 and e.wt ~= 66) and "Rounds loaded in the gun." or "How many.")
    end
    it[#it + 1] = H({ label = "Take it out", press = function() IM.remove(e.i); menu_pop_sub() end }, "Removes it from player 2's inventory.")
    it[#it + 1] = { label = "Back", back = true }
    return it, e.name
end
-- (v441, v441b, v441c) Shared Inventory (Extras > Experimental: st.shared_inv, off by default). Player 1 and
-- player 2 carry one inventory: player 2's Inventory is kept slot for slot the same as player
-- 1's (the game's, which the item box, saves and the inventory screen use). Every few frames
-- both are read and merged against the last merged state (SH.base): a slot only one side
-- changed takes that side's change (pickups, rounds fired, reloads, items used, moved, boxed);
-- a stack both changed gets both changes (two reloads at once); anything else, player 1's
-- wins. The result is written to whichever side differs. Nothing in the existing systems
-- changes: player 2's own inventory is put aside when this goes on (SH.own) and given back
-- when it goes off; meanwhile anything that keeps player 2's inventory (the live record, save
-- records) keeps that own record (P.capture wrapped), and whatever puts a record into player 2
-- (a load, a respawn, a difficulty kit: P.apply wrapped) becomes the new own record, after which
-- player 2 takes the shared inventory again. Not with infinite ammo (Rookie).
