        if not w then
            -- (switched off: his own back; a load / respawn in the middle: just wait)
            if SH.active and st.shared_inv ~= true then pcall(stop) end
            if SH.active and st.infinite_ammo then pcall(stop) end
            return
        end
        local a, b = p1_inv(), p2_inv()
        if a == nil or b == nil then return end
        if not SH.active then start(a, b) end
        if SH.base == nil or SH.b_addr ~= b:get_address() or SH.a_addr ~= a:get_address() then
            if adopt(a, b) then SH.adopted = (SH.adopted or 0) + 1; SH.a_addr, SH.b_addr = a:get_address(), b:get_address() end
            return
        end
        if st.frame % 3 ~= 0 or st.frame < (SH.wait_until or 0) then return end
        local n = SH.n
        if count_of(a) ~= n or count_of(b) ~= n then SH.base = nil; return end
        local A, B = snap(a, n), snap(b, n)
        local S = SH.base
        local changed = false
        local m1, s1, m2, s2 = main_of(a), sub_of(a), main_of(b), sub_of(b)
        -- (what player 1 holds is hers: player 1's side always wins there. A change that would
        -- put something else under player 2's hands waits until they're empty.)
        local plan = {}
        for i = 0, n - 1 do
            local s, x, y = S[i], A[i], B[i]
            local new
            if i == m1 or (i == s1 and not sharable(x)) then new = x
            elseif same(x, s) and same(y, s) then new = s
            elseif same(y, s) then new = x
            elseif same(x, s) then new = y
            elseif kind(x, s) and kind(y, s) and s ~= nil then
                new = { id = s.id, wt = s.wt, parts = s.parts, bullet = s.bullet, num = s.num + (x.num - s.num) + (y.num - s.num) }
                if new.num <= 0 and new.wt <= 0 then new = nil elseif new.num < 0 then new.num = 0 end
            else new = x end
            plan[i] = new
        end
        local under_main, under_sub = false, false
        for i = 0, n - 1 do
            if not kind(B[i], plan[i]) then
                if i == m2 then under_main = true end
                if i == s2 then under_sub = true end
            end
        end
        if under_main or under_sub then empty_hands(b, under_main, under_sub); return end
        for i = 0, n - 1 do
            local x, y, new = A[i], B[i], plan[i]
            if not same(x, new) then put(a, i, new); changed = true end
            if not same(y, new) then put(b, i, new); changed = true end
            S[i] = new
        end
        -- (the pouch: player 1's size; a pouch player 2 grew in the Inventory Modifier counts too)
        local sa, sb = size_of(a), size_of(b)
        if sa ~= sb then
            if sb > sa and sb ~= (SH.size or sa) then pcall(a.set_field, a, "_CurrentSlotSize", sb); sa = sb end
            pcall(b.set_field, b, "_CurrentSlotSize", sa)
        end
        SH.size = sa
        m2 = main_of(b)
        local e2 = m2 and m2 >= 0 and S[m2]
        if e2 and e2.wt > 0 then SH.p2_wt = e2.wt end
        if changed or (m2 and m2 >= 0 and m2 == main_of(a) and not sharable(e2)) or (m2 and m2 >= 0 and not e2) then
            pcall(settle_p2, a, b)
            pcall(P.fix_shortcuts, b)
        end
    end
    re.on_frame(function() local ok, err = pcall(SH.tick); if not ok then SH.err = tostring(err) end end)
    -- equipping: not what the other player holds
    local EQ = { equipMainSlot = true, equipSubSlot = true, equipSlot = true, equipSlotAnyway = true }
    local td = sdk.find_type_definition("app.ropeway.survivor.Inventory")
    for _, m in ipairs(td and td:get_methods() or {}) do
        if EQ[m:get_name()] and m:get_num_params() == 1 then
            local pt = m:get_param_types()[1]:get_full_name()
            local by_slot = pt == "app.ropeway.inventory.Slot"
            if by_slot or pt == "System.Int32" then
                pcall(sdk.hook, m, function(args)
                    if not SH.active or SH.own_equip then return end
                    local a, b = p1_inv(), p2_inv()
                    if a == nil or b == nil then return end
                    local self = sdk.to_int64(args[2]) & 0xFFFFFFFFFFFF
                    local mine, other, who
                    if self == (a:get_address() & 0xFFFFFFFFFFFF) then mine, other, who = a, b, st.p2_name()
                    elseif self == (b:get_address() & 0xFFFFFFFFFFFF) then mine, other, who = b, a, st.p1_name()
                    else return end
                    local idx
                    if by_slot then
                        local sl = sdk.to_managed_object(args[3])
                        idx = sl and safe(function() return sl:call("get_Index") end)
                    else
                        idx = sdk.to_int64(args[3]) & 0xFFFFFFFF
                        if idx >= 0x80000000 then idx = idx - 0x100000000 end
                    end
                    if idx == nil or idx < 0 then return end
                    local e = read_slot(slot(mine, idx))
                    if e == nil or sharable(e) then return end
                    if idx == main_of(other) or idx == sub_of(other) then
                        SH.refused = (SH.refused or 0) + 1
                        if st.frame - SH.msg_at > 90 then
                            SH.msg_at = st.frame
                            toast(who .. " has it equipped")
                        end
                        return sdk.PreHookResult.SKIP_ORIGINAL
                    end
                end, function(r) return r end)
                SH.hooked = (SH.hooked or 0) + 1
            end
        end
    end
end)()
-- one screen: how player 2 aims (free aim and the laser are the mod's own; Fixed Camera adds
-- its auto-aim switch)
P2PAGES.aim = function()
    local it = {}
    st.cc.get()
    local inst = st.cc.installed
    it[#it + 1] = HEAD("Gun aim")
    it[#it + 1] = H(toggle_item("Free aim", "p2_free_aim"), "Aim anywhere with the right stick instead of where " .. st.p1_name() .. " aims.")
    it[#it + 1] = H(toggle_item("Laser sight", "p2_laser"), "A laser from your gun shows where you're aiming.")
    if inst and st.play_mode == "fixed" then
        it[#it + 1] = HEAD("Fixed Camera")
        it[#it + 1] = H(toggle_item("Tank controls", "p2_cc"),
            "Move and aim as " .. st.p1_name() .. " does with Classic Cameras, on the same buttons: tank walking and running, d-pad movement, quick turns, strafing, auto-aim and classic aim.")
        if st.p2_cc then it[#it + 1] = H(toggle_item("  Auto-aim", "p2_autoaim"), "Your gun turns to the nearest enemy, even with Classic Cameras' own auto-aim off.") end
    end
    it[#it + 1] = HEAD("Knife and grenade")
    it[#it + 1] = H(toggle_item("Aim with the right stick", "sub_aim"), "Aim the knife and grenades with the right stick instead of where you face.")
    it[#it + 1] = H(num_item("Aim speed", "aim_speed", 0.25, 0.5, 5.0, "%.2f"), "How fast the right stick turns your aim.")
    it[#it + 1] = H(toggle_item("Invert left / right", "invert_x"), "Flips the right stick's left / right.")
    it[#it + 1] = H(toggle_item("Invert up / down", "invert_y"), "Flips the right stick's up / down.")
    it[#it + 1] = { label = "Back", back = true }
    return it, "Aiming"
end

local function p2m_can_open()
    if menu.open or st.ai_partner() or st.hunk == nil then return false end
    if p2c.menu_open() then return false end   -- the game's own pause / menus
    return not st.in_cutscene()
end
-- open player 2's menu on a page (the item box station)
function st.open_p2_page(page)
    if p2m.open or not p2m_can_open() then return false end
    p2m.open, p2m.page, p2m.idx, p2m.stack, p2m.rep = true, page, 1, {}, {}
    p2m.tab, p2m.tabbed, p2m.scroll, p2m.items = nil, false, 0, nil
    p2m.held = 0xFFFFFFFF
    return true
end

local function update_p2menu()
    local pad = st.p2_uid and pad_by_uid(st.p2_uid)
    local b = pad and pad_buttons(pad) or 0
    local now = os.clock()
    if st.ig and st.ig.open then   -- his inventory screen has pad 2
        menu.p2_lock, st.p2_lock = true, true
        local ok, err = pcall(st.ig.input, st.ig.by_p1 and st.p1_uid and pad_by_uid(st.p1_uid) or pad)
        if not ok then st.ig.err = err end
        return
    end
    if not p2m.open then
        if p2m.blocking and b & (MB.A | MB.B | MB.START) == 0 then p2m.blocking = false end
        -- Start alone opens it on release; with Back held at any point it was the add / remove combo
        if b & MB.START ~= 0 then
            -- (a Start that went down while closing a menu doesn't open his menu on release)
            if not p2m.start_down then p2m.start_down, p2m.combo = true, p2m.blocking == true end
            if b & 16384 ~= 0 then p2m.combo = true end
        elseif p2m.start_down then
            p2m.start_down = false
            if not p2m.combo and not p2m.blocking and p2m_can_open() then
                p2m.open, p2m.page, p2m.idx, p2m.stack, p2m.rep = true, P2TABS[1].page, 1, {}, {}
                p2m.tab, p2m.tabbed, p2m.scroll, p2m.items = 1, true, 0, nil
                p2m.held = 0xFFFFFFFF
            end
        end
        menu.p2_lock = p2m.blocking == true
        st.p2_lock = menu.p2_lock
        return
    end
    menu.p2_lock, st.p2_lock = true, true
    -- the game paused, a cutscene, the shared co-op menu or player 2 leaving: close
    if not p2m_can_open() or pad == nil then p2m_close(); return end
    local ax = pad and safe(function() return pad.dev:call("get_AxisL") end)
    if ax then
        if ax.y > 0.6 then b = b | MB.UP elseif ax.y < -0.6 then b = b | MB.DOWN end
        if ax.x < -0.6 then b = b | MB.LEFT elseif ax.x > 0.6 then b = b | MB.RIGHT end
    end
    local prev = p2m.held or 0
    p2m.held = b
    local function hit(m)
        if b & m == 0 then p2m.rep[m] = nil; return false end
        if prev & m == 0 then p2m.rep[m] = now + 0.35; return true end
        if m <= 8 and p2m.rep[m] and now >= p2m.rep[m] then p2m.rep[m] = now + 0.11; return true end
        return false
    end
    local items = p2m.items or {}
    if hit(MB.START) then p2m_close(); return end
    if p2m.tabbed and (hit(MB.LB) or hit(MB.RB)) then
        local d = (b & MB.LB ~= 0 and prev & MB.LB == 0) and -1 or 1
        p2m.tab = ((p2m.tab or 1) - 1 + d) % #P2TABS + 1
        p2m.page, p2m.stack, p2m.scroll = P2TABS[p2m.tab].page, {}, 0
        items = UI.clean((P2PAGES[p2m.page])())
        p2m.items, p2m.idx = items, UI.first_sel(items)
    end
    if hit(MB.UP) and #items > 0 then p2m.idx = UI.next_sel(items, p2m.idx, -1) end
    if hit(MB.DOWN) and #items > 0 then p2m.idx = UI.next_sel(items, p2m.idx, 1) end
    local cur = items[p2m.idx]
    if cur then
        if hit(MB.LEFT) and cur.change then cur.change(-1); save_config() end
        if hit(MB.RIGHT) and cur.change then cur.change(1); save_config() end
        if hit(MB.A) then
            if cur.sub then
                if cur.enter then cur.enter() end
                p2m.stack[#p2m.stack + 1] = { page = p2m.page, idx = p2m.idx, scroll = p2m.scroll }
                p2m.page, p2m.idx, p2m.scroll = cur.sub, 0, 0
            elseif cur.back then
                local top = table.remove(p2m.stack)
                p2m.page, p2m.idx, p2m.scroll = top and top.page or P2TABS[p2m.tab or 1].page, top and top.idx or 1, top and top.scroll or 0
            elseif cur.press then
                cur.press(); save_config()
            end
        end
    end
    if p2m.open and hit(MB.B) then
        local top = table.remove(p2m.stack)
        if top then p2m.page, p2m.idx, p2m.scroll = top.page, top.idx, top.scroll or 0 else p2m_close() end
    end
    if p2m.open then
        local its, title = (P2PAGES[p2m.page] or P2PAGES[P2TABS[p2m.tab or 1].page])()
        its = UI.clean(its)
        p2m.items, p2m.title = its, title
        if p2m.idx > #its then p2m.idx = #its end
        if p2m.idx < 1 then p2m.idx = UI.first_sel(its) end
        if its[p2m.idx] and (its[p2m.idx].head or its[p2m.idx].info) then p2m.idx = UI.next_sel(its, p2m.idx, 1) end
    end
end

-- Player 2's inventory screen (Back on pad 2): the game's own inventory layout (GuiSlot grid,
-- GuiCaption, GuiVital, GuiBack) built as copies on player 2's half (split screen) or the
-- right half of a shared screen, filled from his inventory and driven by the mod: the layout's
-- animation states (slots DEFAULT / SELECT / BLANK / DECIDE / _W for two-slot items, counts
-- FULL / EMPTY, E for what's in his hands, d-pad markers), icons from GUIMaster and the
-- names / descriptions from ItemManager. The game keeps running: HUNK stands still while it's
-- open. Commands: Equip, Use (heals him), Use on player 1, Combine (the game's own
-- Inventory.combineSlots: herbs, ammo into a gun...), Shortcut (then a d-pad direction), Give
-- to player 1.
-- (one instance per player: st.ig is player 2's inventory / item box screen, st.ig1 player 1's
-- item box screen in split screen, which replaces the game's: C.p1)
local function make_ig(C)
    local IG = { open = false, cur = 0, mode = "grid", ci = 1, cmds = {}, g = {}, rep = {}, held = 0, txt = {}, uvq = {}, p1 = C.p1 }
    local PFX = C.p1 and "rcu_P1Inv_" or "rcu_P2Inv_"
    local function OUT(D) return C.p1 and D.P1_OUT or D.P2_OUT end
    local function who() return C.p1 and st.p1_name() or st.p2_name() end
    -- (no GuiBack: its blurred backdrop drew as a black box in the room, not behind the screen;
    -- his view stays clear behind the inventory)
    local GUIS = { slot = "GuiSlot", cap = "GuiCaption", vital = "GuiVital", box = "GUI_ItemBox" }
    local DIR_STATE = { [0] = "TOP", [1] = "BOTTOM", [2] = "LEFT", [3] = "RIGHT" }
    local CMD_ICON = { equip = 7, use = 6, use_p1 = 6, combine = 10, shortcut = 9, give = 13, move = 13 }   -- (icon_command UV patterns)
    local function scene()
        return sdk.call_native_func(sdk.get_native_singleton("via.SceneManager"), sdk.find_type_definition("via.SceneManager"), "get_CurrentScene")
    end
    local function valid(o) return o ~= nil and safe(function() return o:call("get_Valid") end) == true end
    local function child(e, name)
        local c = e and safe(function() return e:call("get_Child") end)
        local guard = 0
        while c and guard < 80 do
            guard = guard + 1
            if safe(function() return c:call("get_Name") end) == name then return c end
            c = safe(function() return c:call("get_Next") end)
        end
        return nil
    end
    local function path(e, p)
        for name in p:gmatch("[^/]+") do e = child(e, name); if e == nil then return nil end end
        return e
    end
    local function state(e, s)
        if e and s and safe(function() return e:call("get_PlayState") end) ~= s then pcall(e.call, e, "set_PlayState", s) end
    end
    local function vis(e, v)
        if e and safe(function() return e:call("get_Visible") end) ~= v then pcall(e.call, e, "set_Visible", v) end
    end
    local function text(e, s)
        if e == nil then return end
        local k = e:get_address()
        if IG.txt[k] == s then return end
        if pcall(e.call, e, "set_Message", sdk.create_managed_string(s)) then IG.txt[k] = s end
    end
    local function pos(e, x, y) if e then pcall(e.call, e, "set_Position", Vector3f.new(x, y, 0)) end end
    local function draw(g, on)
        if g and g.go and safe(function() return g.go:call("get_DrawSelf") end) ~= on then pcall(g.go.call, g.go, "set_DrawSelf", on) end
    end

    -- the copies (built once, hidden while closed)
    local function build()
        local D = st.dual
        local ok = true
        for k, name in pairs(GUIS) do
            local g = IG.g[k]
            if not (g and valid(g.go)) then
                IG.g[k] = nil
                local sc = scene()
                local src = sc and safe(function() return sc:call("findGameObject(System.String)", name) end)
                local sgui = src and comp(src, "via.gui.GUI")
                if sgui == nil then return false end
                local cname = PFX .. name
                local go = safe(function() return sc:call("findGameObject(System.String)", cname) end)
                local gui = go and comp(go, "via.gui.GUI")
                if gui == nil then
                    go = sdk.find_type_definition("via.GameObject"):get_method("create(System.String, via.Folder)"):call(nil, cname, src:call("get_Folder"))
                    gui = go and go:call("createComponent(System.Type)", sdk.typeof("via.gui.GUI"))
                    if gui == nil then return false end
                    pcall(gui.call, gui, "set_Segment", sgui:call("get_Segment"))
                    pcall(gui.call, gui, "set_Asset", sgui:call("get_Asset"))
                end
                pcall(go.call, go, "set_DrawSelf", false)
                -- (a copy kept from before a script reset may have been switched off: back on)
                pcall(gui.call, gui, "set_Enabled", true)
                pcall(go.call, go, "set_UpdateSelf", true)
                g = { go = go:add_ref(), gui = gui:add_ref(), el = nil, mode = nil,
                      src_out = math.tointeger(safe(function() return sgui:call("get_RenderOutputID") end) or 2) or 2 }
                if D.gui_saved[sgui:get_address()] then g.src_out = D.gui_saved[sgui:get_address()].id end
                D.gui_saved[gui:get_address()] = { g = g.gui, id = OUT(D) }   -- (pin_shared leaves it alone)
                IG.g[k] = g
            end
            if safe(function() return g.gui:call("get_Ready") end) ~= true then ok = false end
        end
        return ok
    end
    -- the layouts pin some panels to the screen edges (ResolutionAdjust), which on player 2's
    -- narrower half pushes them aside: these copies are placed by hand instead
    local function noadj(g)
        if g.noadj then return end
        g.noadj = true
        local function walk(c, d)
            local guard = 0
            while c and guard < 200 do
                guard = guard + 1
                if safe(function() return c:call("get_ResolutionAdjust") end) == true then pcall(c.call, c, "set_ResolutionAdjust", false) end
                if d < 6 then walk(safe(function() return c:call("get_Child") end), d + 1) end
                c = safe(function() return c:call("get_Next") end)
            end
        end
        walk(safe(function() return g.gui:call("get_View"):call("get_Child") end), 0)
    end
    local function elements()
        local G = IG.g
        for _, g in pairs(G) do noadj(g) end
        if G.slot.el == nil then
            local v = G.slot.gui:call("get_View")
            local mode = path(v, "main/mode")
            local list = child(mode, "c_list")
            if list == nil then return false end
            local el = { main = child(v, "main"), mode = mode, list = list, slots = {},
                pointer_move = child(mode, "c_pointer_move"), pointer = path(mode, "c_pointer_move/c_pointer/pointer"),
                command = child(mode, "c_command"), lc = path(mode, "c_command/c_list_command_pos/list_command"), si = {} }
            el.cmd_bg = child(el.lc, "c_command_bg")
            -- the "moving an item" slot (an extra tile that follows the cursor while an item is
            -- being moved) shows its placeholder over the first slot in a copy: hidden
            vis(child(list, "c_dup_slot_move"), false)
            for i = 0, 19 do
                local p = child(list, string.format("c_slot_item%02d", i))
                if p then
                    local s = { panel = p, slot = child(p, "c_slot"), item = child(p, "c_item"), icon = path(p, "c_item/icon_item"),
                        cnum = path(p, "c_item/c_num"), num = path(p, "c_item/c_num/m_num"), gauge = path(p, "c_item/c_gauge"),
                        equip = path(p, "c_item/c_equip"), info = path(p, "c_item/c_info"), sc = child(p, "c_shortcut"),
                        cursor = child(p, "c_cursor"), cover = path(p, "c_cover_compoe/cover"), wide = "?", x = 0, y = 0 }
                    -- the wide backdrop of a two-slot item is masked by the one-slot "mask" in a
                    -- copy (only one block of it showed): unmasked
                    for _, nm in ipairs({ "slot_w", "slot_select_w" }) do
                        local w = path(p, "c_slot/" .. nm)
                        if w then pcall(w.call, w, "set_MaskType", 0) end
                    end
                    local pp = safe(function() return p:call("get_Position") end)
                    if pp then s.x, s.y = pp.x, pp.y end
                    el.slots[i] = s
                end
            end
            for k = 0, 5 do
                local it = child(el.lc, string.format("si_command%02d", k))
                if it then el.si[k] = { item = it, icon = child(it, "icon_command"), text = child(it, "m_command"), sel = child(it, "c_selector") } end
            end
            G.slot.el = el
        end
        if G.cap.el == nil then
            local v = G.cap.gui:call("get_View")
            G.cap.el = { main = child(v, "main"), cap = path(v, "main/c_caption"), name = path(v, "main/c_caption/m_item"),
                cat = path(v, "main/c_caption/m_category"), detail = path(v, "main/c_caption/m_caption") }
        end
        if G.box.el == nil then
            -- the item box list: sl_itembox (a ScrollList) with rows si_itembox, item1..item10, 60 apart
            local v = G.box.gui:call("get_View")
            local sl = path(v, "main/sl_itembox")
            if sl == nil then return false end
            local el = { main = child(v, "main"), sl = sl, sb = child(sl, "sb_itembox"), bar = path(sl, "sb_itembox/Bar"), rows = {} }
            for k = 0, 10 do
                local r = child(sl, k == 0 and "si_itembox" or ("item" .. k))   -- (the first row is the template, si_itembox)
                if r then
                    el.rows[k] = { item = r, name = child(r, "m_name"), icon = path(r, "c_item/icon_item"), cnum = child(r, "c_num"),
                        num = path(r, "c_num/m_num"), cursor = child(r, "c_cursor"), slot = child(r, "c_slot"), gauge = path(r, "c_item/c_gauge"),
                        info = path(r, "c_item/c_info") }
                end
            end
            G.box.el = el
        end
        if G.vital.el == nil then
            local v = G.vital.gui:call("get_View")
            G.vital.el = { main = child(v, "main"), gauge = path(v, "main/c_gauge"), disp = path(v, "main/c_gauge/disp_condition"),
                g2 = path(v, "main/c_gauge/gauge") }
        end
        return true
    end
    -- where the copies sit: split screen = player 2's half, his HUD scale (the grid and caption
    -- centred in it, the heartbeat at its left); shared screen = the right half
    local function place()
        local D = st.dual
        local split = p2c.active
        local kx, ky = 1, 1
        if split then kx, ky = D.hud_k() end
        for k, g in pairs(IG.g) do
            local out = split and OUT(D) or g.src_out
            if safe(function() return g.gui:call("get_RenderOutputID") end) ~= out then pcall(g.gui.call, g.gui, "set_RenderOutputID", out) end
            local sx, sy, px, py = kx, ky, 0, 0
            if IG.box then
                -- item box: the list on the left of his half, his grid (and caption) on its right
                if not split then sx, sy, kx = 0.8, 0.8, 0.8 end
                -- (one screen: player 2's box on the right half; player 1 trading with the AI
                -- companion in the middle of the screen)
                local x0 = split and 40 or ((IG.box.kind == "trade" or C.p1) and 488 or 970)
                py = 540 - 540 * sy
                if k == "box" then px = x0 - 335 * kx
                else px = x0 + 770 * kx + 30 + 185 * kx - 1400 * kx end
            elseif split then
                if k == "vital" then px, py = 0, 540 - 540 * ky
                else px, py = 960 - 1400 * kx, 540 - 540 * ky end
            elseif k == "back" then
                sx, px = 0.5, 960
            end
            pcall(function()
                local v = g.gui:call("get_View")
                v:call("set_Scale", Vector3f.new(sx, sy, 1))
                v:call("set_Position", Vector3f.new(px, py, 0))
            end)
        end
        draw(IG.g.vital, IG.open and split and not IG.box)
        draw(IG.g.box, IG.open and IG.box ~= nil)
    end

    local P = function() return st.p2inv end
    local function inv()
        if C.p1 then return st.p2inv and st.p2inv.leon_inv() end
        return st.p2inv and st.p2inv.hunk_inv()
    end
    local function item_at(hinv, i)
        for _, e in ipairs(P().list(hinv)) do if e.i == i then return e end end
        return nil
    end
    local function im() return sdk.get_managed_singleton("app.ropeway.gamemastering.ItemManager") end
    local function item_type(id) return safe(function() return im():call("getItemType", id) end) end
    local CAT = { [1] = "Recovery", [2] = "Ammunition", [3] = "Key Item" }
    local function caption(e)
        if e == nil then return "", "", "" end
        local name, cat, det = e.name or "", "", ""
        if e.wt > 0 then
            det = safe(function() return im():call("getWeaponDetail", e.wt, 0) end) or ""
            cat = safe(function()
                local guid = im():call("getWeaponCategoryMsgId", e.wt)
                return sdk.find_type_definition("via.gui.message"):get_method("get(System.Guid)"):call(nil, guid)
            end) or "Weapon"
        else
            det = safe(function() return im():call("getItemDetail", e.id, 0) end) or ""
            cat = CAT[item_type(e.id) or 0] or "Item"
        end
        return tostring(name), tostring(cat), tostring(det)
    end
    -- the commands for an item
    local function commands(hinv, e)
        local c = {}
        local p1 = st.p1_name and st.p1_name() or "player 1"
        local SUBW = P().SUBW
        if e.wt > 0 then
            local held = SUBW[e.wt] and P().sub_index(hinv) or P().main_index(hinv)
            if held ~= e.i then c[#c + 1] = { id = "equip", label = "Equip" } end
            if not SUBW[e.wt] then
                c[#c + 1] = { id = "combine", label = "Combine" }
                c[#c + 1] = { id = "shortcut", label = "Shortcut" }
            end
        else
            local ty = item_type(e.id)
            if ty == 1 then
                c[#c + 1] = { id = "use", label = "Use" }
                c[#c + 1] = { id = "use_p1", label = "Use on " .. p1 }
            end
            c[#c + 1] = { id = "combine", label = "Combine" }
        end
        c[#c + 1] = { id = "move", label = "Move" }
        c[#c + 1] = { id = "give", label = "Give to " .. p1 }
        return c
    end

    -- The item box (the game's ItemLockerManager: gameSaveData.SaveData._Items, 400 ItemData,
    -- shared by every box). IG.box = { kind = "box" (take / store) or "boy" (Rookie's
    -- station), side = "list" / "grid", row, top, rows, picker }.
    local function locker_items()
        local lm = sdk.get_managed_singleton("app.ropeway.gamemastering.ItemLockerManager")
        return lm and safe(function() return lm:get_field("gameSaveData"):get_field("SaveData"):get_field("_Items") end)
    end
    -- (player 1 has the game's item box screen open: it works on a copy of the box and writes
    -- it back when it closes, so player 2 keeps out meanwhile)
    local function p1_in_box()
        local gm = sdk.get_managed_singleton("app.ropeway.gui.GUIMaster")
        return gm ~= nil and safe(function() return gm:call("isBusyItemBox") end) == true
    end
    local function box_rows()
        local items = locker_items()
        local out = {}
        if items == nil then return out end
        local n = safe(function() return items:call("get_Count") end) or 0
        for i = 0, n - 1 do
            local d = items:call("get_Item", i)
            if d and not safe(function() return d:call("isBlank") end) then
                local wt = safe(function() return d:call("get_WeaponId") end) or -1
                out[#out + 1] = { act = "take", bi = i, wt = wt, id = safe(function() return d:call("get_ItemId") end) or 0,
                    parts = safe(function() return d:call("get_WeaponParts") end) or 0, num = safe(function() return d:call("get_Count") end) or 0,
                    bullet = safe(function() return d:call("get_BulletId") end) or 0, label = tostring(safe(function() return d:call("getName") end) or "?") }
                out[#out].name = out[#out].label
            end
        end
        return out
    end
    local SUPPORT = { 1, 2, 5 }
    local function iname(id) return tostring(safe(function() return im():call("getItemName", id) end) or "?") end
    local function boy_rows()
        local Q, hinv = P(), inv()
        local r = {}
        if st.infinite_ammo then
            -- (v411) Infinite ammo: the d-pad guns and the grenade are settings (st.weapon_*,
            -- st.throwable), applied with give_loadout as Player 2 > Weapons does; nothing to
            -- restock and no support item
            for _, m in ipairs(MAIN_SLOTS) do
                local w = WEAPON_BY_WT[st[m.key]]
                local nm = w and tostring(safe(function() return im():call("getWeaponName", w.wt, 0) end) or w.name) or "(none)"
                r[#r + 1] = { act = "gun", sc = m.shortcut, label = "Gun on " .. m.label .. ":   " .. nm, wt = st[m.key], name = nm }
            end
            r[#r + 1] = { act = "grenade", label = "Grenades:   " .. throwable_name(st.throwable), wt = st.throwable, name = throwable_name(st.throwable) }
            r[#r + 1] = { act = "close", label = "Close", name = "Close" }
            return r
        end
        if hinv == nil then return r end
        local list = Q.list(hinv)
        for _, sc in ipairs(Q.SC_ORDER) do
            local cur
            for _, e in ipairs(list) do if Q.shortcut_of(hinv, e.i) == sc then cur = e end end
            local dn = Q.SC_NAMES[sc]:gsub("^d", "D")
            r[#r + 1] = { act = "gun", sc = sc, label = "Gun on " .. dn .. ":   " .. (cur and cur.name or "(none)"),
                wt = cur and cur.wt, parts = cur and cur.parts, num = cur and cur.num, name = cur and cur.name or dn }
        end
        local g
        for _, e in ipairs(list) do if e.wt == 65 or e.wt == 66 then g = e end end
        r[#r + 1] = { act = "grenade", label = "Grenades:   " .. (g and g.name or "(none)"), wt = g and g.wt, num = g and g.num, name = g and g.name }
        r[#r + 1] = { act = "support", label = "Support item:   " .. iname(st.p2_support or 2), id = st.p2_support or 2, name = iname(st.p2_support or 2) }
        r[#r + 1] = { act = "restock", label = "Restock (full guns, spare rounds, grenades, support item)", id = 15, name = "Restock" }
        r[#r + 1] = { act = "close", label = "Close", name = "Close" }
        return r
    end
    local function picker_rows(row)
        local r = {}
        local Q, hinv = P(), inv()
        if row.act == "gun" then
            local where = {}
            if st.infinite_ammo then
                for _, m in ipairs(MAIN_SLOTS) do if st[m.key] then where[st[m.key]] = m.shortcut end end
            else
                for _, e in ipairs(Q.list(hinv)) do local sc = Q.shortcut_of(hinv, e.i); if sc then where[e.wt] = sc end end
            end
            for _, w in ipairs(WEAPONS) do
                local nm = tostring(safe(function() return im():call("getWeaponName", w.wt, 0) end) or w.name)
                local on = where[w.wt]
                local tag = on == row.sc and "   (here now)" or (on and ("   (on " .. Q.SC_NAMES[on]:gsub("^d", "D") .. ")") or "")
                r[#r + 1] = { act = "pick_gun", sc = row.sc, wt = w.wt, parts = 0, label = nm .. tag, name = nm, num = w.num }
            end
        elseif row.act == "grenade" then
            for _, t in ipairs(THROWABLES) do
                local nm = tostring(safe(function() return im():call("getWeaponName", t.wt, 0) end) or t.name)
                r[#r + 1] = { act = "pick_grenade", wt = t.wt, label = nm .. (row.wt == t.wt and "   (carried)" or ""), name = nm, num = 3 }
            end
        elseif row.act == "support" then
            for _, id in ipairs(SUPPORT) do
                r[#r + 1] = { act = "pick_support", id = id, label = iname(id) .. ((st.p2_support or 2) == id and "   (chosen)" or ""), name = iname(id) }
            end
        end
        return r
    end
    -- the AI companion's inventory opened by player 1 (kind "trade"): the list is what player 1
    -- carries that player 2 can use (A hands it over), the grid is the AI's (A hands it back)
    local function trade_rows()
        local Q = P()
        local leon = Q.leon_inv()
        local out = {}
        local main, sub = leon and Q.main_index(leon), leon and Q.sub_index(leon)
        for _, e in ipairs(leon and Q.list(leon) or {}) do
            if Q.p2_item(e.id, e.wt) and e.i ~= main and e.i ~= sub then
                out[#out + 1] = { act = "give_p2", i = e.i, wt = e.wt, id = e.id, parts = e.parts, num = e.num, label = e.name, name = e.name }
            end
        end
        if #out == 0 then out[1] = { act = "none", label = st.p1_name() .. " has nothing to hand over", name = "" } end
        return out
    end
    local function box_refresh()
        local B = IG.box
        if B == nil then return end
        if B.picker then B.rows = picker_rows(B.picker)
        elseif B.kind == "boy" then B.rows = boy_rows()
        elseif B.kind == "trade" then B.rows = trade_rows()
        else B.rows = box_rows() end
        local n = #B.rows
        if B.row >= n then B.row = math.max(0, n - 1) end
        if B.row < B.top then B.top = B.row elseif B.row >= B.top + 10 then B.top = B.row - 9 end
        if B.top > math.max(0, n - 10) then B.top = math.max(0, n - 10) end
        B.sig = nil
        local parts = {}
        for _, e in ipairs(B.rows) do parts[#parts + 1] = (e.label or "") .. ":" .. tostring(e.num) end
        B.rsig = table.concat(parts, "|")
    end
    local function box_take(e)
        local Q, hinv = P(), inv()
        local items = locker_items()
        local d = items and safe(function() return items:call("get_Item", e.bi) end)
        if d == nil or hinv == nil then return end
        if not C.p1 and not Q.p2_item(e.id, e.wt) then toast(st.p2_name() .. " can't use that"); return end
        if e.wt > 0 then
            if not Q.weapon_room(hinv, e.wt, e.parts) then toast("No room for that"); return end
            Q.put_weapon(hinv, { wt = e.wt, parts = e.parts, bullet = e.bullet, num = e.num })
            pcall(d.call, d, "setBlank")
            if not C.p1 and st.anim and st.anim.check then pcall(st.anim.check) end
            toast(who() .. " took the " .. e.name)
        else
            local moved = Q.put_item(hinv, e.id, e.num)
            if (moved or 0) <= 0 then toast("No room for that"); return end
            if moved >= e.num then pcall(d.call, d, "setBlank") else pcall(d.call, d, "set_Count", e.num - moved) end
            toast(who() .. " took " .. e.name .. " x" .. moved)
        end
        if not C.p1 then pcall(Q.fix_shortcuts, hinv); pcall(Q.saved) end
    end
    local function box_store(i)
        local Q, hinv = P(), inv()
        local items = locker_items()
        if hinv == nil or items == nil then return end
        local e = item_at(hinv, i)
        if e == nil then return end
        local n = safe(function() return items:call("get_Count") end) or 0
        local target
        if e.wt <= 0 then   -- (the same item already in the box: added to it)
            for k = 0, n - 1 do
                local d = items:call("get_Item", k)
                if d and not safe(function() return d:call("isBlank") end) and (safe(function() return d:call("get_WeaponId") end) or -1) <= 0
                    and safe(function() return d:call("get_ItemId") end) == e.id then target = d; break end
            end
            if target then
                pcall(target.call, target, "set_Count", (safe(function() return target:call("get_Count") end) or 0) + e.num)
            end
        end
        if target == nil then
            for k = 0, n - 1 do
                local d = items:call("get_Item", k)
                if d and safe(function() return d:call("isBlank") end) then target = d; break end
            end
            if target == nil then toast("The item box is full"); return end
            if e.wt > 0 then pcall(target.call, target, "setWeapon", e.wt, e.parts or 0, e.num, e.bullet or 0, nil)
            else pcall(target.call, target, "setItem(app.ropeway.gamemastering.Item.ID, System.Int32)", e.id, e.num) end
        end
        local was_main = Q.main_index(hinv) == i
        pcall(hinv.call, hinv, "removeSlot(System.Int32)", i)
        if was_main then   -- (his hands are empty now: the next gun he has)
            for _, x in ipairs(Q.list(hinv)) do
                if x.wt > 0 and not Q.SUBW[x.wt] then pcall(hinv.call, hinv, "equipSlot(System.Int32)", x.i); break end
            end
        end
        if not C.p1 then pcall(Q.fix_shortcuts, hinv); pcall(Q.saved) end
        toast(who() .. " put " .. e.name .. " in the item box")
    end
    local function box_press(e)
        local B = IG.box
        if e == nil or B == nil then return end
        local Q = P()
        if e.act == "take" then box_take(e)
        elseif e.act == "give_p2" then
            local n, why = Q.take_from_p1(e.i)
            toast((n or 0) > 0 and (st.p1_name() .. " gave " .. e.name .. " to " .. st.p2_name()) or ("Can't give that: " .. tostring(why)))
            if st.anim and st.anim.check then pcall(st.anim.check) end
        elseif e.act == "none" then return
        elseif e.act == "gun" or e.act == "grenade" or e.act == "support" then
            B.picker, B.back_row = e, B.row
            B.row, B.top = 0, 0
            for k, x in ipairs(picker_rows(e)) do
                if (e.wt and x.wt == e.wt) or (e.id and x.id == e.id) then B.row = k - 1 end
            end
        elseif e.act == "pick_gun" and st.infinite_ammo then
            -- (v411) as Player 2 > Weapons: a gun already on another direction swaps with this one
            local mine
            for _, m in ipairs(MAIN_SLOTS) do if m.shortcut == e.sc then mine = m end end
            if mine then
                for _, o in ipairs(MAIN_SLOTS) do if o.key ~= mine.key and st[o.key] == e.wt then st[o.key] = st[mine.key] end end
                st[mine.key] = e.wt
                if st.hunk then pcall(give_loadout, mine.slot, true) else build_loadout() end
                pcall(save_config)
                if st.anim and st.anim.check then pcall(st.anim.check) end
            end
        elseif e.act == "pick_grenade" and st.infinite_ammo then
            st.throwable = e.wt
            if st.hunk then pcall(give_loadout, false, true) else build_loadout() end
            pcall(save_config)
        elseif e.act == "pick_gun" then pcall(Q.station_set_gun, e.sc, e.wt); if st.anim and st.anim.check then pcall(st.anim.check) end
        elseif e.act == "pick_grenade" then pcall(Q.station_set_grenade, e.wt)
        elseif e.act == "pick_support" then st.p2_support = e.id; pcall(save_config)
        elseif e.act == "restock" then if Q.restock() then toast(st.p2_name() .. " restocked at the item box") end
        elseif e.act == "close" then IG.close(); return
        end
        if e.act:find("^pick_") then B.picker, B.row = nil, B.back_row or 0 end
        box_refresh()
    end
    -- the list on screen
    local function fill_box()
        local B, el = IG.box, IG.g.box.el
        local gm = sdk.get_managed_singleton("app.ropeway.gui.GUIMaster")
        if not B.sl_quiet and el.sl then
            -- sl_itembox is a via.gui.ScrollList that reads the game's own input (InputType 1,
            -- UseFocus): with a copy open it scrolled itself and moved its SELECT highlight with
            -- whichever pad pressed up / down (both players' lists drifting, rows hidden above the
            -- top). Its input is switched off and its scroll reset; the rows are placed by hand.
            B.sl_quiet = true
            local sl = el.sl
            pcall(sl.call, sl, "set_InputType", 0)
            pcall(sl.call, sl, "set_UseFocus", false)
            pcall(sl.call, sl, "set_MouseSelectType", 0)
            pcall(sl.call, sl, "set_ScrollTime", 0.0)
            pcall(sl.call, sl, "setCursorIndex", 0, false)
            pcall(sl.call, sl, "setSelectedIndex", 0, false)
        end
        state(el.main, "DEFAULT")
        local n = #B.rows
        for k = 0, 10 do
            local r = el.rows[k]
            if r then
                if k >= 10 then vis(r.item, false)
                else
                    local e = B.rows[B.top + k + 1]
                    local sel = B.side == "list" and B.row == B.top + k
                    vis(r.item, true)
                    pos(r.item, 0, 60 * k)
                    state(r.gauge, "DISABLE")   -- (its default state draws a bar under the icon)
                    vis(r.info, false)          -- (an equip / checkbox mark the selected row showed)
                    state(r.item, sel and "SELECT" or "DEFAULT")
                    text(r.name, e and e.label or "")
                    local key = e and ((e.wt and e.wt > 0) and ("w" .. e.wt .. ":" .. (e.parts or 0)) or (e.id and e.id > 0 and ("i" .. e.id))) or nil
                    vis(r.icon, key ~= nil)
                    vis(r.slot, key ~= nil)
                    if key and r.key ~= key and gm and r.icon then
                        if e.wt and e.wt > 0 then pcall(gm.call, gm, "setWeaponIconTexture", r.icon, e.wt, e.parts or 0)
                        else pcall(gm.call, gm, "setItemIconTexture", r.icon, e.id) end
                    end
                    r.key = key
                    local shown = e and e.num and e.wt ~= 46 and (B.kind == "box" or B.kind == "trade")
                    vis(r.cnum, shown == true)
                    if shown then
                        text(r.num, tostring(e.num))
                        state(r.cnum, e.num <= 0 and "EMPTY" or "DEFAULT")
                    end
                    vis(r.cursor, sel)
                    if sel then state(r.cursor, "DEFAULT") end
                end
            end
        end
        -- the scroll bar
        if el.bar then
            if n > 10 then
                vis(el.sb, true)
                pcall(function()
                    local z = el.bar:call("get_Size"); z.h = 600 * 10 / n; el.bar:call("set_Size", z)
                    pos(el.bar, 0, 600 * B.top / n)
                end)
            else vis(el.sb, false) end
        end
    end

    -- filling the grid / caption / heartbeat (only when something changed)
    local function sig(hinv)
        local s = { IG.cur, IG.mode, IG.ci, IG.from or -1, P().main_index(hinv) or -1, P().sub_index(hinv) or -1, P().size(hinv), p2c.active and 1 or 0 }
        for _, e in ipairs(P().list(hinv)) do s[#s + 1] = e.i .. ":" .. e.wt .. ":" .. e.id .. ":" .. e.num end
        for sc = 0, 3 do s[#s + 1] = tostring(safe(function() return hinv:call("getSlot(app.ropeway.EquipmentDefine.Shortcut)", sc):call("get_Index") end)) end
        local B = IG.box
        if B then s[#s + 1] = B.side .. B.row .. ":" .. B.top .. ":" .. tostring(B.rsig) end
        return table.concat(s, ",")
    end
    local function fill(hinv)
        local el = IG.g.slot.el
        local gm = sdk.get_managed_singleton("app.ropeway.gui.GUIMaster")
        local size = P().size(hinv)
        local rows = math.max(2, math.min(5, math.ceil(size / 4)))
        local lm = rows == 2 and "DEFAULT" or ("LINE" .. rows)
        state(el.mode, lm); state(el.list, lm); state(el.main, "DEFAULT")
        local main, sub = P().main_index(hinv), P().sub_index(hinv)
        local dir_of = {}
        for sc = 0, 3 do
            local idx = safe(function() return hinv:call("getSlot(app.ropeway.EquipmentDefine.Shortcut)", sc):call("get_Index") end)
            if idx and idx >= 0 then dir_of[idx] = sc end
        end
        local items = {}
        for _, e in ipairs(P().list(hinv)) do items[e.i] = e end
        -- c_cover_compoe/cover (an 80x80 black rect at 80%) is the game's "can't combine with
        -- this" dimmer, drawn OVER the icon: it made his icons dark (and looked like a one-slot
        -- backdrop under two-slot items). Hidden, as in the game's own menu.
        local function cover_w(s)
            if s.cover and s.wide ~= "off" then
                pcall(s.cover.call, s.cover, "set_Visible", false)
                s.wide = "off"
            end
        end
        for i = 0, 19 do
            local s = el.slots[i]
            if s then
                local e = items[i]
                local dead = i < size and safe(function() return hinv:call("isDeadSlot", i) end) == true and e == nil
                local focus = i == IG.cur and not (IG.box and IG.box.side == "list")
                -- (beyond his slots, or the right half of a two-slot item: hidden; a state alone
                -- leaves what the slot showed before drawn under the wide item)
                vis(s.panel, not (i >= size or dead))
                if i >= size or dead then
                    state(s.panel, "DISABLE"); state(s.slot, "DISABLE")
                    s.key = nil
                    cover_w(s)
                elseif e == nil then
                    state(s.panel, focus and (IG.mode == "combine" and "BLANK_FOCUS" or "BLANK_SELECT") or "BLANK")
                    state(s.slot, "BLANK")
                    cover_w(s)
                    vis(s.icon, false); vis(s.cnum, false)
                    state(s.sc, "DEFAULT")
                else
                    local sl = P().slot_at(hinv, i)
                    local fat = sl and safe(function() return sl:call("get_IsFatSlot") end) == true
                    local w = fat and "_W" or ""
                    local decided = (IG.mode == "cmd" and focus) or ((IG.mode == "combine" or IG.mode == "move") and IG.from == i)
                    state(s.panel, (decided and "DECIDE" or (focus and "SELECT" or "DEFAULT")) .. w)
                    state(s.slot, (decided and "DECIDE" or "DEFAULT") .. w)
                    state(s.item, fat and "ITEM_W" or "DEFAULT")
                    cover_w(s)
                    vis(s.icon, true)
                    local key = e.wt > 0 and ("w" .. e.wt) or ("i" .. e.id)
                    if s.key ~= key and gm and s.icon then
                        if e.wt > 0 then pcall(gm.call, gm, "setWeaponIconTexture", s.icon, e.wt, e.parts or 0)
                        else pcall(gm.call, gm, "setItemIconTexture", s.icon, e.id) end
                        s.key = key
                    end
                    if e.wt == 46 then
                        vis(s.cnum, false)
                    else
                        vis(s.cnum, true)
                        local max = sl and safe(function() return sl:call("get_MaxNumber") end) or 0
                        state(s.cnum, e.num <= 0 and "EMPTY" or ((e.wt > 0 and max > 0 and e.num >= max) and "FULL" or "DEFAULT"))
                        text(s.num, tostring(e.num))
                    end
                    state(s.gauge, "DISABLE")
                    if i == main or i == sub then state(s.sc, "EQUIPE")
                    elseif dir_of[i] then state(s.sc, DIR_STATE[dir_of[i]])
                    else state(s.sc, "DEFAULT") end
                end
            end
        end
        -- the hand pointer on the slot under the cursor
        local cs = el.slots[IG.cur]
        local lp = safe(function() return el.list:call("get_Position") end)
        if cs and lp and el.pointer then
            local ce = items[IG.cur]
            local sl = ce and P().slot_at(hinv, IG.cur)
            local fat = sl and safe(function() return sl:call("get_IsFatSlot") end) == true
            pos(el.pointer, lp.x + cs.x - 2 + (fat and 45 or 0), lp.y + cs.y + 1)
            state(el.pointer_move, "DEFAULT")
        end
        -- the command list
        if IG.mode == "cmd" and cs and lp then
            local ce = items[IG.cur]
            local sl = ce and P().slot_at(hinv, IG.cur)
            local fat = sl and safe(function() return sl:call("get_IsFatSlot") end) == true
            -- (FADE_IN only as the list opens: once its fade has played the panel's state moves
            -- on, and setting FADE_IN again on every cursor move replayed the fade, a flicker)
            if not IG.cmd_up then state(el.command, "FADE_IN"); IG.cmd_up = true end
            pos(el.lc, lp.x + cs.x + 70 + (fat and 90 or 0), lp.y + cs.y)
            local n = #IG.cmds
            state(el.cmd_bg, "size_" .. math.max(1, math.min(6, n)))
            for k = 0, 5 do
                local it = el.si[k]
                if it then
                    local c = IG.cmds[k + 1]
                    if c then
                        vis(it.item, true)
                        pos(it.item, 0, 48 * k)
                        state(it.item, (k + 1 == IG.ci) and "SELECT" or "DEFAULT")
                        text(it.text, c.label)
                        if it.icon then pcall(it.icon.call, it.icon, "set_UVPatternNo", CMD_ICON[c.id] or 6) end
                        vis(it.sel, false)
                    else
                        vis(it.item, false)
                    end
                end
            end
        else
            state(el.command, "FADE_OUT")
            IG.cmd_up = false
        end
        if IG.box then local ok, err = pcall(fill_box); if not ok then IG.box_err = tostring(err) end end
        -- caption: what's under the cursor (in combine mode, the target; in the item box, the
        -- box row under the cursor)
        local ce = items[IG.cur]
        if IG.box and IG.box.side == "list" then
            local be = IG.box.rows[IG.box.row + 1]
            ce = be and (be.wt or be.id) and { name = be.name, wt = be.wt or -1, id = be.id or 0 } or nil
        end
        local cel = IG.g.cap.el
        state(cel.main, "DEFAULT")
        vis(cel.cap, ce ~= nil)
        local nm, cat, det = caption(ce)
        text(cel.name, nm); text(cel.cat, cat); text(cel.detail, det)
        -- heartbeat: his health
        local vel = IG.g.vital.el
        local hp = st.hunk and comp(st.hunk, "app.ropeway.HitPointController")
        local cur, max = hp and safe(function() return hp:call("get_CurrentHitPoint") end), hp and safe(function() return hp:call("get_DefaultHitPoint") end)
        local r = (cur and max and max > 0) and cur / max or 1
        local cond = r > 0.66 and "FINE" or (r > 0.33 and "CAUTION" or "DANGER")
        state(vel.main, "DEFAULT"); state(vel.gauge, cond)
    end

    function IG.tick()
        if C.p1 then
            -- player 1's pad drives it (Leon gets nothing meanwhile: st.p1_block, see the
            -- InputSystem hooks); after it closes, until the buttons are let go
            local pad = st.p1_uid and pad_by_uid(st.p1_uid)
            if IG.open then
                local ok, err = pcall(IG.input, pad)
                if not ok then IG.err = err end
            elseif st.p1_block == "release" then
                if pad == nil or (pad_buttons(pad) & 0xFFFF) == 0 then st.p1_block = nil end
            end
            if st.p1_box_req then
                st.p1_box_req = nil
                if not IG.open then
                    IG.held = 0xFFFFFFFF
                    pcall(IG.open_box, "box")
                end
            end
        end
        if not C.p1 then
            -- His inventory opens with player 1's inventory / map / files (split screen, fitted
            -- into her half: st.p2_inv_free) and closes with it, when it was opened there.
            -- (Debounced: the screens' GUIs flicker off for a frame or two between tabs.)
            -- st.p2_inv_auto = false: only by hand (Select).
            local free = st.p2_inv_free() and st.p2_inv_auto ~= false and st.hunk ~= nil and not st.ai_partner()
            IG.free_n = free and math.max(1, (IG.free_n or 0) + 1) or math.min(-1, (IG.free_n or 0) - 1)
            if IG.free_n == 6 and not IG.open and not IG.auto_done then
                IG.auto_done = true
                pcall(IG.toggle)
                if IG.open then IG.menu_auto = true end
            elseif IG.free_n == -12 or (IG.free_n < 0 and IG.menu_auto and IG.open and not p2c.menu_open()) then
                -- (her menu closed for good, the game no longer paused: at once; still in a menu
                -- (a tab change, the pause menu): after the debounce)
                IG.auto_done = nil
                if IG.open and IG.menu_auto then IG.close() end
            end
            if not IG.open then IG.menu_auto = nil end
        end
        if not IG.cleaned then
            -- copies left drawn by a script reset while it was open: hidden until it opens again
            IG.cleaned = true
            pcall(function()
                local sc = scene()
                for _, name in ipairs({ "GuiBack", "GuiSlot", "GuiCaption", "GuiVital", "GUI_ItemBox" }) do
                    local go = sc:call("findGameObject(System.String)", PFX .. name)
                    if go then go:call("set_DrawSelf", false) end
                end
            end)
        end
        if not IG.open then
            if IG.shown then
                for _, g in pairs(IG.g) do draw(g, false) end
                IG.shown = false
            end
            return
        end
        local hinv = inv()
        if hinv == nil or not st.p2inv then IG.close(); return end
        IG.stage = "build"
        if not build() then return end
        IG.stage = "elements"
        if not elements() then return end
        IG.stage = "fill"
        if not IG.shown or st.frame % 15 == 0 then pcall(place) end
        if not IG.shown then
            for k, g in pairs(IG.g) do if k ~= "vital" and k ~= "box" then draw(g, true) end end
            draw(IG.g.vital, p2c.active and not IG.box)
            IG.shown, IG.sig = true, nil
        end
        draw(IG.g.box, IG.box ~= nil)
        if IG.box then
            if IG.box.kind == "box" and not C.p1 and p1_in_box() then
                toast(st.p1_name() .. " opened the item box")
                IG.close()
                return
            end
            if st.frame % 30 == 0 then box_refresh() end
        end
        local s = sig(hinv)
        if s ~= IG.sig then
            IG.sig = s
            local ok, err = pcall(fill, hinv)
            if not ok then IG.err = err end
        end
    end

    function IG.toggle()
        if IG.open then IG.close() return end
        if C.p1 then
            if st.p2inv == nil or menu.open or p2c.menu_open() or st.in_cutscene() then return end
        elseif st.hunk == nil or st.p2inv == nil or (st.ai_partner() and not IG.by_p1) or menu.open or (p2c.menu_open() and not st.p2_inv_free()) or st.in_cutscene() then return
        elseif st.infinite_ammo and not IG.allow_boy then return end   -- (Rookie: no inventory to manage; its station is the exception)
        IG.open, IG.mode, IG.ci, IG.from, IG.cmd_up = true, "grid", 1, nil, false
        IG.held = 0xFFFFFFFF
        IG.rep = {}
        local hinv = inv()
        local size = hinv and P().size(hinv) or 8
        if IG.cur >= size then IG.cur = 0 end
        if C.p1 or IG.by_p1 then st.p1_block = true end
        if not C.p1 then menu.p2_lock, st.p2_lock = true, true end
        if not C.p1 and st.p2_inv_free() then IG.menu_auto = true end   -- (closes with her menu)
    end
    -- the item box screen (kind "box": take and store; "boy": Rookie's station)
    function IG.open_box(kind)
        if IG.open then IG.close() end
        -- (one screen: one box screen at a time, both would sit in the middle)
        if not p2c.active then
            local other = C.p1 and st.ig or st.ig1
            if other and other.open then
                toast(C.p1 and (st.p2_name() .. " is using the inventory") or (st.p1_name() .. " is using the item box"))
                return false
            end
        end
        if (st.hunk == nil and not C.p1) or st.p2inv == nil or menu.open or st.in_cutscene() then return false end
        if kind == "box" and not C.p1 and p1_in_box() then toast(st.p1_name() .. " is using the item box"); return false end
        IG.allow_boy = kind == "boy"
        IG.toggle()
        IG.allow_boy = nil
        if not IG.open then return false end
        IG.box = { kind = kind, side = "list", row = 0, top = 0, rows = {} }
        box_refresh()
        IG.sig = nil
        pcall(place)
        return true
    end
    -- player 1 opens the AI companion's inventory (command wheel, A; st.ai_trade_ok)
    function IG.open_trade()
        if C.p1 or IG.open then return false end
        IG.by_p1 = true
        IG.toggle()
        if not IG.open then IG.by_p1 = nil; return false end
        IG.held = 0xFFFFFFFF
        IG.box = { kind = "trade", side = "list", row = 0, top = 0, rows = {} }
        box_refresh()
        IG.sig = nil
        pcall(place)
        return true
    end
    function IG.close()
        IG.box = nil
        if IG.by_p1 then
            IG.by_p1 = nil
            st.p1_block = "release"
        end
        if C.p1 then
            -- (player 1's buttons stay away from Leon until they're let go: the A that closed
            -- it would open the box again)
            IG.open, IG.mode, IG.sig = false, "grid", nil
            st.p1_block = "release"
            return
        end
        -- (closed with Back still down: its release would count as a tap and open it again)
        local pb = st.p2_dev and safe(function() return st.p2_dev:call("get_Button") end) or 0
        IG.eat_back = (pb & 16384) ~= 0
        IG.open, IG.mode = false, "grid"
        IG.sig = nil
        if st.p2cross and st.p2cross.hold then st.p2cross = nil end
        menu.p2_lock, st.p2_lock = false, false
        p2m.blocking = true   -- (buttons still held don't reach HUNK or open his menu)
    end

    local function move(dx, dy, hinv)
        local size = P().size(hinv)
        local rows = math.ceil(size / 4)
        local c, r = IG.cur % 4, IG.cur // 4
        local i = IG.cur
        for _ = 1, 4 do
            if dx ~= 0 then c = (c + dx) % 4 end
            if dy ~= 0 then r = (r + dy) % rows end
            i = r * 4 + c
            -- the right half of a two-slot item: skip over it
            local dead = safe(function() return hinv:call("isDeadSlot", i) end) == true and item_at(hinv, i) == nil
            if IG.mode == "move" then dead = false end   -- (moving: any slot can be the target)
            if not dead then break end
            if dy ~= 0 then i = i - 1; break end
        end
        IG.cur = math.max(0, math.min(size - 1, i))
    end
    local function heal_self(e)
        local hp = comp(st.hunk, "app.ropeway.HitPointController")
        if hp == nil then return false, "" end
        local cur, max = hp:call("get_CurrentHitPoint"), hp:call("get_DefaultHitPoint")
        if cur >= max then return false, st.p2_name() .. " is already at full health" end
        local v = safe(function() return im():call("getItemEffectiveValue", e.id) end) or 0
        -- (v413) getItemEffectiveValue is a float (green herb 400.0): a float handed to the
        -- game's Int32 set_CurrentHitPoint arrives as 0, which downed him. Whole numbers only.
        local amount = math.floor(math.min(v > 0 and v or (st.heal_amount or 400), max - cur))
        hp:call("set_CurrentHitPoint", math.floor(cur + amount))
        local hinv = inv()
        local sl = P().slot_at(hinv, e.i)
        if sl and e.num > 1 then pcall(sl.call, sl, "set_Number", e.num - 1) else pcall(hinv.call, hinv, "removeSlot(System.Int32)", e.i) end
        return true, string.format("%s used %s (+%d HP)", st.p2_name(), e.name, amount)
    end
    local function run(c, e, hinv)
        if c.id == "equip" then
            P().equip(e.i)
        elseif c.id == "use" then
            local _, msg = heal_self(e)
            if msg and msg ~= "" then toast(msg) end
        elseif c.id == "use_p1" then
            local _, msg = P().use_on_p1(e.i)
            if msg then toast(msg) end
        elseif c.id == "give" then
            local n, why = P().give_to_p1(e.i)
            toast((n or 0) > 0 and (st.p2_name() .. " gave " .. e.name .. " to " .. st.p1_name()) or ("Can't give that: " .. tostring(why)))
            if (n or 0) > 0 and st.refresh_p1_inv then pcall(st.refresh_p1_inv) end
        elseif c.id == "move" then
            IG.mode, IG.from = "move", e.i
            return
        elseif c.id == "combine" then
            IG.mode, IG.from = "combine", e.i
            return
        elseif c.id == "shortcut" then
            IG.mode, IG.from = "shortcut", e.i
            st.p2cross = { t = os.clock() + 3600, sub = false, dir = nil, hold = true }
            return
        end
        IG.mode = "grid"
    end
    -- combining: the game's own Inventory.combineSlots refuses everything for player 2
    -- (enableCombineSlot is false even for shells + shotgun), so the rules are the mod's:
    -- rounds into a gun that takes them (a reload), and herbs mixed as in the game
    local HERB = { [12] = 2, [13] = 3, [14] = 4 }   -- (the second set of herb ids)
    local MIX = {}
    local function mix(a, b, r) MIX[a .. "+" .. b] = r; MIX[b .. "+" .. a] = r end
    mix(2, 2, 5); mix(2, 3, 6); mix(2, 4, 7); mix(3, 4, 11)
    mix(5, 2, 9); mix(5, 4, 8); mix(7, 2, 8)
    mix(6, 4, 10); mix(7, 3, 10); mix(11, 2, 10)
    local function take(hinv, e, n)
        local sl = P().slot_at(hinv, e.i)
        if sl == nil then return end
        if e.num - n > 0 then pcall(sl.call, sl, "set_Number", e.num - n)
        else pcall(hinv.call, hinv, "removeSlot(System.Int32)", e.i) end
    end
    local function combine(i, j, hinv)
        local a, b = item_at(hinv, i), item_at(hinv, j)
        if a == nil or b == nil then return end
        local done, msg = false, nil
        -- rounds + gun
        local gun, ammo = a, b
        if not (gun.wt > 0) then gun, ammo = b, a end
        if gun.wt > 0 and not P().SUBW[gun.wt] and ammo.wt <= 0 and ammo.id > 0 then
            local sl = P().slot_at(hinv, gun.i)
            local takes = (sl and safe(function() return sl:call("get_BulletID") end)) or 0
            local w = WEAPON_BY_WT[gun.wt]
            if takes <= 0 and w then takes = w.ammo or 0 end
            if takes == ammo.id then
                local max = sl and safe(function() return sl:call("get_MaxNumber") end) or 0
                local n = math.min(math.max(0, max - gun.num), ammo.num)
                if n <= 0 then msg = gun.name .. " is already full"
                else
                    pcall(sl.call, sl, "set_Number", gun.num + n)
                    take(hinv, ammo, n)
                    done, msg = true, string.format("%s reloaded (+%d)", gun.name, n)
                end
            end
        end
        -- herbs
        if not done and msg == nil and a.wt <= 0 and b.wt <= 0 then
            local r = MIX[(HERB[a.id] or a.id) .. "+" .. (HERB[b.id] or b.id)]
            if r then
                take(hinv, b, 1)
                local sl = P().slot_at(hinv, a.i)
                if a.num > 1 then
                    pcall(sl.call, sl, "set_Number", a.num - 1)
                    P().put_item(hinv, r, 1)
                else
                    pcall(hinv.call, hinv, SETITEM_SIG, a.i, r, 1, nil, nil)
                end
                done = true
                msg = safe(function() return im():call("getItemName", r) end)
            end
        end
        if not done and msg == nil then
            -- (whatever the game itself allows)
            local before = sig(hinv)
            pcall(hinv.call, hinv, "combineSlots(System.Int32, System.Int32)", i, j)
            done = sig(hinv) ~= before
        end
        pcall(P().fix_shortcuts, hinv)
        pcall(P().repair, hinv)
        IG.last = { i = i, j = j, done = done, msg = msg }
        if msg then toast(msg) elseif not done then toast("Those can't be combined") end
    end
    IG.combine = combine

    -- pad 2 while it's open (from update_p2menu)
    function IG.input(pad)
        if not IG.open then return end
        if pad == nil or (st.hunk == nil and not C.p1) or menu.open or (p2c.menu_open() and (C.p1 or not st.p2_inv_free())) or st.in_cutscene() then IG.close(); return end
        local hinv = inv()
        if hinv == nil then IG.close(); return end
        local b = pad_buttons(pad) | (IG.fake or 0)   -- (IG.fake: buttons pressed by the dev bridge)
        local ax = safe(function() return pad.dev:call("get_AxisL") end)
        if ax then
            if ax.y > 0.6 then b = b | MB.UP elseif ax.y < -0.6 then b = b | MB.DOWN end
            if ax.x < -0.6 then b = b | MB.LEFT elseif ax.x > 0.6 then b = b | MB.RIGHT end
        end
        local now = os.clock()
        local prev = IG.held or 0
        IG.held = b
        local function hit(m)
            if b & m == 0 then IG.rep[m] = nil; return false end
            if prev & m == 0 then IG.rep[m] = now + 0.32; return true end
            if m <= 8 and IG.rep[m] and now >= IG.rep[m] then IG.rep[m] = now + 0.1; return true end
            return false
        end
        local BACK = 16384
        local B = IG.box
        if B then
            -- the item box: the list (up / down, A takes or picks, right to his grid) and his
            -- grid (A stores what's under the cursor, left from the first column back to the list)
            if hit(BACK) or hit(MB.START) then IG.close(); return end
            if B.side == "list" then
                local n = #B.rows
                if hit(MB.UP) and n > 0 then B.row = (B.row - 1) % n end
                if hit(MB.DOWN) and n > 0 then B.row = (B.row + 1) % n end
                if B.row < B.top then B.top = B.row elseif B.row >= B.top + 10 then B.top = B.row - 9 end
                if hit(MB.RIGHT) and (B.kind == "box" or B.kind == "trade") then B.side = "grid"; return end
                if hit(MB.A) then box_press(B.rows[B.row + 1]); return end
                if hit(MB.B) then
                    if B.picker then B.picker, B.row = nil, B.back_row or 0; box_refresh() else IG.close() end
                end
                return
            end
            if hit(MB.LEFT) then
                if IG.cur % 4 == 0 then B.side = "list"; return end
                move(-1, 0, hinv)
            end
            if hit(MB.RIGHT) then move(1, 0, hinv) end
            if hit(MB.UP) then move(0, -1, hinv) end
            if hit(MB.DOWN) then move(0, 1, hinv) end
            if hit(MB.A) then
                local x = item_at(hinv, IG.cur)
                if x and B.kind == "trade" then
                    local n, why = P().give_to_p1(IG.cur)
                    toast((n or 0) > 0 and (st.p2_name() .. " gave " .. x.name .. " to " .. st.p1_name()) or ("Can't give that: " .. tostring(why)))
                    box_refresh()
                elseif x then box_store(IG.cur); box_refresh() end
                return
            end
            if hit(MB.B) then IG.close() end
            return
        end
        if IG.mode == "shortcut" then
            -- the next d-pad press picks the direction for the gun
            for bit, sc in pairs({ [1] = 0, [2] = 1, [4] = 2, [8] = 3 }) do
                if b & bit ~= 0 and prev & bit == 0 then
                    P().assign(IG.from, sc)
                    pcall(P().fix_shortcuts, hinv)
                    st.p2cross = { t = os.clock(), sub = false, dir = sc }
                    IG.mode = "grid"
                    return
                end
            end
            if hit(MB.B) or hit(BACK) then IG.mode = "grid"; st.p2cross = nil end
            return
        end
        if IG.mode == "cmd" then
            local n = #IG.cmds
            if hit(MB.UP) and n > 0 then IG.ci = (IG.ci - 2) % n + 1 end
            if hit(MB.DOWN) and n > 0 then IG.ci = IG.ci % n + 1 end
            if hit(MB.A) then
                local e = item_at(hinv, IG.cur)
                local c = IG.cmds[IG.ci]
                if e and c then pcall(run, c, e, hinv) else IG.mode = "grid" end
            elseif hit(MB.B) then
                IG.mode = "grid"
            end
            if hit(BACK) or hit(MB.START) then IG.close() end
            return
        end
        if hit(MB.LEFT) then move(-1, 0, hinv) end
        if hit(MB.RIGHT) then move(1, 0, hinv) end
        if hit(MB.UP) then move(0, -1, hinv) end
        if hit(MB.DOWN) then move(0, 1, hinv) end
        if IG.mode == "move" then
            if hit(MB.A) then
                if IG.cur ~= IG.from then
                    local ok, why = P().move_item(hinv, IG.from, IG.cur)
                    if not ok then toast(why or "It doesn't fit there") end
                end
                IG.mode, IG.from = "grid", nil
            elseif hit(MB.B) then
                IG.cur, IG.mode, IG.from = IG.from or IG.cur, "grid", nil
            end
            if hit(BACK) or hit(MB.START) then IG.close() end
            return
        end
        if IG.mode == "combine" then
            if hit(MB.A) then
                if IG.cur ~= IG.from and item_at(hinv, IG.cur) then combine(IG.from, IG.cur, hinv) end
                IG.mode, IG.from = "grid", nil
            elseif hit(MB.B) then
                IG.cur, IG.mode, IG.from = IG.from or IG.cur, "grid", nil
            end
            if hit(BACK) or hit(MB.START) then IG.close() end
            return
        end
        if hit(MB.A) then
            local e = item_at(hinv, IG.cur)
            if e then IG.cmds, IG.ci, IG.mode = commands(hinv, e), 1, "cmd" end
        end
        if hit(MB.B) or hit(BACK) or hit(MB.START) or (not C.p1 and not st.cooldowns_on() and hit(16)) then IG.close() end   -- (16: Y, his menu button without the abilities)
    end
    return IG
end
st.ig = make_ig({ p1 = false })
st.ig1 = make_ig({ p1 = true })
-- AI Companion with an inventory (Operative / Veteran): player 1 opens it from the
-- command wheel (hold RB, stick left in the middle, A: see update_wheel) -> st.ig.open_trade
function st.ai_trade_ok()
    return st.ai_partner() and st.hunk ~= nil and not st.infinite_ammo and not st.p2_down and st.ig ~= nil
end
-- Player 1 at an item box in split screen: the mod's box screen on player 1's half instead of
-- the game's (which pauses the whole game and couldn't be drawn across both halves). Leon's
-- interact on a box runs GimmickControl.lockForTrigger (-> bool) on "ItemLocker_*_control",
-- then tryOccupy / GimmickBody.occupyStart, which opens the game's screen. lockForTrigger is
-- skipped and answers false (the box counts as busy, nothing else starts) and st.ig1 opens next
-- frame. Also on one screen (Shared Screen, Fixed Camera, HUNK Classic: the game's own
-- box could freeze the game there), drawn in the middle. The AI companion and a keyboard player 1
-- keep the game's box. st.box_replace = false: always the game's box.
function st.box_replace_on()
    if st.box_replace == false or st.kbm_on or st.hunk == nil then return false end
    if st.split then return p2c.active == true end
    return not st.ai_partner() and (st.play_mode == "shared" or st.play_mode == "fixed" or st.play_mode == "classic")
