st.box_replace = true
do
    local function locker(this)
        local n = this and safe(function() return this:call("get_GameObject"):call("get_Name") end)
        return n ~= nil and n:find("ItemLocker") ~= nil
    end
    local td = sdk.find_type_definition("app.ropeway.gimmick.action.GimmickControl")
    local m = td and td:get_method("lockForTrigger")
    if m then
        local skipped = false
        sdk.hook(m, function(args)
            skipped = false
            if not st.box_replace_on() then return end   -- (keyboard player 1, the AI companion: the game's own screen)
            local this = sdk.to_managed_object(args[2])
            if not locker(this) then return end
            st.locker_hits = (st.locker_hits or 0) + 1
            skipped = true
            if st.ig1 and not st.ig1.open then st.p1_box_req = true end
            return sdk.PreHookResult.SKIP_ORIGINAL
        end, function(r)
            if skipped then skipped = false; return sdk.to_ptr(0) end
            return r
        end)
    end
end

