    end
    local function rows_for(leon, e)
        local r = {}
        if e == nil or st.hunk == nil or st.despawned then return r end
        local h = own_inv()
        local p2 = st.p2_name()
        local held = P().main_index(leon) == e.i or P().sub_index(leon) == e.i
        if h and not held and P().p2_item(e.id, e.wt) then r[#r + 1] = { id = "give", label = "Give to " .. p2 } end
        local ty = e.wt <= 0 and safe(function() return im():call("getItemType", e.id) end) or -1
        if ty == 1 then r[#r + 1] = { id = "use_p2", label = "Use on " .. p2 } end
        if (st.ai_partner() or LC.force_ai) and h then
            if e.wt <= 0 and e.id > 0 and reload_target(h, e.id) then r[#r + 1] = { id = "reload", label = "Reload " .. p2 } end
            if #P().list(h) > 0 then r[#r + 1] = { id = "take", label = "Take from " .. p2 } end
        end
        return r
    end
    local function take_rows(page)
        local h = own_inv()
        local list = h and P().list(h) or {}
