        local r = {}
        for k = page * per + 1, math.min(#list, page * per + per) do
            local x = list[k]
            local n = (x.wt > 0 or x.num <= 1) and "" or (" x" .. x.num)
            r[#r + 1] = { id = "take_item", i = x.i, label = x.name .. n }
        end
        if pages > 1 then r[#r + 1] = { id = "more", label = "More..." } end
