    end
    -- our rows on screen, from list row `from` on (the game's rows before it are left alone)
    local function paint(b, rows, from)
        local cl = b:get_field("CommandList")
        local n = from + #rows
        local bg = child(cl, "c_command_bg")
        if bg then pcall(bg.call, bg, "set_PlayState", "size_" .. math.max(1, math.min(6, n))) end
        for k = from, 5 do
            local it = child(cl, string.format("si_command%02d", k))
            local r = rows[k - from + 1]
            if it and r then
                it:call("set_Visible", true)
                local p = it:call("get_Position"); p.y = 48 * k; it:call("set_Position", p)
                local m = child(it, "m_command")
                if m then m:call("set_Message", sdk.create_managed_string(r.label)) end
                local ic = child(it, "icon_command")
                if ic then pcall(ic.call, ic, "set_UVPatternNo", ICON[r.id] or 13) end
