            -- (v417) an empty slot: the list is only ours ("Take from HUNK")
            local slot = b:get_field("SelectSlotNo")
            local dc = b:get_field("DispCommand")
            dc:call("clearData")
            local rows = { { id = "take", label = "Take from " .. st.p2_name() } }
            dc:call("addData", CARRIER, true)
