    end
    local function heal_p2(e, leon)
        local hp = st.hunk and comp(st.hunk, "app.ropeway.HitPointController")
        if hp == nil then return st.p2_name() .. " isn't here" end
        local cur, max = hp:call("get_CurrentHitPoint"), hp:call("get_DefaultHitPoint")
        if cur >= max then return st.p2_name() .. " is already at full health" end
        local v = safe(function() return im():call("getItemEffectiveValue", e.id) end) or 0
        -- (v413) getItemEffectiveValue is a float (green herb 400.0): a float handed to the
        -- game's Int32 set_CurrentHitPoint arrives as 0, which downed him. Whole numbers only.
        local amount = math.floor(math.min(v > 0 and v or (st.heal_amount or 400), max - cur))
        hp:call("set_CurrentHitPoint", math.floor(cur + amount))
        local sl = P().slot_at(leon, e.i)
        if sl and e.num > 1 then pcall(sl.call, sl, "set_Number", e.num - 1) else pcall(leon.call, leon, "removeSlot(System.Int32)", e.i) end
        return string.format("%s used %s on %s (+%d HP)", st.p1_name(), e.name, st.p2_name(), amount)
    end
    local function run(b, r)
