            return true
        elseif r.id == "more" then
            show_take(b, (LC.page or 0) + 1)
            return true
        elseif r.id == "take_item" then
            local h = own_inv()
            local x = h and item_of(h, r.i)
            local n, why = P().give_to_p1(r.i)
            msg = (n or 0) > 0 and (st.p1_name() .. " took " .. (x and x.name or "it") .. " from " .. st.p2_name()) or ("Can't take that: " .. tostring(why))
        end
