        -- the rows are then replaced with ours (LC.after_display, LC.blank).
        local gs
        for _, m in ipairs(td:get_methods()) do
            if m:get_name() == "getStock" and m:get_num_params() == 2 then gs = m end
        end
        if gs then
            sdk.hook(gs, function(args)
                if LC.fake then thread.get_hook_storage().fake = true end
            end, function(r)
                if thread.get_hook_storage().fake then
