            if LC.force_decide then LC.force_decide = nil; return true end   -- (dev bridge)
            local p1b = st.p1_dev and (safe(function() return st.p1_dev:call("get_ButtonDown") end) or 0) or 0
            if (p1b & 32) ~= 0 then return true end   -- A
