            if not (st.ai_partner() or LC.force_ai) or st.hunk == nil or st.despawned then return end
            if b:call("get_SelectMode") ~= 0 or b:call("get_IsOpenItemBox") or b:call("get_IsDispCommand") then return end
            local h = own_inv()
            if h == nil or #P().list(h) == 0 then return end
