        local sc_m = td:get_method("updateSlotControl")
        if sc_m then
            local scb
            sdk.hook(sc_m, function(args) scb = sdk.to_managed_object(args[2]) end,
                function(r) if scb then local ok, err = pcall(LC.blank_take, scb); if not ok then LC.err = err end end; return r end)
        end
    end
end)()

local function draw_p2menu()
    if not p2m.open or p2m.items == nil then return end
    local ds = imgui.get_display_size()
    -- player 2's area: their half in split screen, else the whole screen
    local rx, ry, rw, rh = 0, 0, ds.x, ds.y
    if p2c.active and st.dual and st.dual.on then
        local r = (p2c.regions[st.split_layout] or p2c.regions[1]).p2
        rx, ry, rw, rh = r[1] * ds.x, r[2] * ds.y, (r[3] - r[1]) * ds.x, (r[4] - r[2]) * ds.y
    end
    local k = math.min(ds.y / 1080, rh / 640, rw / 640)
    UI.k = k
    local style = (pad_by_uid(st.p2_uid) or {}).style or "xbox"
    local tabs
    if p2m.tabbed then
        tabs = {}
        for i, t in ipairs(P2TABS) do tabs[i] = t end
        if not st.split then tabs[3] = { label = "Aiming", icon = "aim", page = "t_cam" } end
    end
    local cur = p2m.items[p2m.idx]
    local foot = {}
    if tabs then foot[#foot + 1] = { ids = { "LB", "RB" }, label = "Tab" } end
    if cur and cur.change then foot[#foot + 1] = { ids = { "LR" }, label = "Change" } end
    foot[#foot + 1] = { ids = { "A" }, label = "Select" }
    foot[#foot + 1] = { ids = { "B" }, label = #p2m.stack > 0 and "Back" or "Close" }
    UI.render({
        area = { rx, ry, rw, rh }, W = math.min(700 * k, rw - 24 * k), H = math.min(800 * k, rh - 20 * k),
        kicker = "PLAYER 2   " .. string.upper(st.p2_name()), title = p2m.title, tabs = tabs, tab = p2m.tab or 1,
        in_sub = #p2m.stack > 0, items = p2m.items, idx = p2m.idx, st = p2m, style = style, win = "reunited_p2menu", footer = foot,
    })
end

re.on_frame(function()
    local ok2, err2 = pcall(update_p2menu)
    if not ok2 then p2m.open = false; p2m.blocking = true; menu.p2_lock, st.p2_lock = false, false; log.info("[reunited] player 2 menu error: " .. tostring(err2)) end
    pcall(draw_p2menu)
end)
re.on_frame(function()
    local ok, err = pcall(update_menu)
    if not ok then menu.open = false; set_paused(false); log.info("[reunited] menu error: " .. tostring(err)) end
    pcall(draw_menu)
end)
if re.on_script_reset then re.on_script_reset(function() set_paused(false) end) end
end)()

-- Command wheel (AI partner) ---------------------------------------------------------------
-- With the AI partner on, player 1 holds RB (keyboard: Z) to open a radial menu of orders,
