    { id = "follow", label = "Stay close" },
    { id = "goto", label = "Go there" },
    { id = "regroup", label = "Regroup" },
    { id = "hold", label = "Hold here" },
    { id = "swap", label = "Switch weapon" },
    { id = "fire_toggle", label = "Hold fire" },
    { id = "heal", label = "Heal me" },
    { id = "resupply", label = "Reload me" },
