local function close(run)
    if W.open and run and W.sel then pcall(ai.command, ITEMS[W.sel].id) end
    if W.open then mouse_look(false) end
    W.open, W.sel, W.t0 = false, nil, nil
    slow(false)
end
-- every kind the game reads from the right stick (it isn't only WATCH while aiming)
local function learn_rstick()
    local is = sdk.get_managed_singleton("app.ropeway.InputSystem")
    local au = is and safe(function() return is:call("getActiveUserInputUnit") end)
    local sd = au and safe(function() return au:get_field("<StickDictionary>k__BackingField") end)
    local keys = sd and safe(function() return sd:call("get_Keys") end)
    local en = keys and safe(function() return keys:call("GetEnumerator") end)
    local guard = 0
    while en and guard < 64 and safe(function() return en:call("MoveNext") end) do
        guard = guard + 1
        local k = safe(function() return en:call("get_Current") end)
        if k and safe(function() return sd:call("get_Item", k) end) == 2 then W.rstick_kinds[k] = true end
    end
end
local function p1_aiming() return ai.p1_aiming() end

local function update_wheel()
    -- (not in the game's own menus either: inventory, map, files, pause; RB is theirs there)
    if not ai.active or menu.open or p2c.active or not st.ai_wheel or p2c.menu_open() then
        W.block_rb = false
        if W.open then close(false) end
        W.t0 = nil
        return
    end
    -- the AI's inventory (or player 1's item box screen) open: no wheel until it's closed and
    -- RB has been let go
    if (st.ig and st.ig.open) or (st.ig1 and st.ig1.open) or st.p1_block then
        if W.open then close(false) end
        W.t0, W.wait_release = nil, true
        return
    end
    local aiming = p1_aiming()
    -- player 1's RB, or Z on the keyboard (either works)
    local b = st.p1_dev and (safe(function() return st.p1_dev:call("get_Button") end) or 0) or 0
    local rb = (b & 1024) ~= 0
    local held = rb or key_down(VK_Z) or W.fake_hold == true   -- (fake_hold / fake_a: dev bridge)
    W.block_rb = st.p1_dev ~= nil
    local now = os.clock()
    if not held then
        W.wait_release = nil
        if W.open then
            close(true)
        elseif W.t0 and aiming and now - W.t0 < 0.15 then
            W.tap_frame = st.frame   -- a quick tap: let the game change ammo type
        end
        W.t0 = nil
        return
    end
    if W.wait_release then return end
    if not W.open then
        W.t0 = W.t0 or now
        if now - W.t0 >= 0.15 then
            ITEMS = aiming and ITEMS_AIM or ITEMS_MOVE
            W.aim_wheel = aiming
            W.open, W.sel = true, nil
            W.a_prev = (b & 32) ~= 0   -- (an A already down doesn't count)
            pcall(learn_rstick)
            mouse_look(true)
            if st.wheel_slow then slow(true) end
        end
        return
    end
    -- choosing
    for i = 1, #ITEMS do
        if key_down(0x30 + i) then W.sel = i end
    end
    -- nothing pointed at: A opens the AI's inventory (its own ammo: Operative / War)
    local a_on = (b & 32) ~= 0 or W.fake_a == true
    if a_on and not W.a_prev and W.sel == nil and st.ai_trade_ok() then
        W.a_prev = true
        close(false)
        pcall(st.ig.open_trade)
        return
    end
    W.a_prev = a_on
    local a = st.p1_dev and safe(function() return st.p1_dev:call("get_AxisR") end)
    if a and (a.x * a.x + a.y * a.y) > 0.36 then
        local ang = math.atan(a.x, a.y)   -- 0 = up, clockwise
        W.sel = math.floor(((ang + 2 * math.pi + math.pi / #ITEMS) % (2 * math.pi)) / (2 * math.pi / #ITEMS)) + 1
    end
end

-- Look: Resident Evil 2's menus. Near-black translucent panels, thin grey rules, off-white
-- type and a muted green for the selection (the "Fine" green of the ECG). Colours 0xAABBGGRR.
local C = {
    shade = 0x70000000, panel = 0xD80C0C0C, panel_sel = 0xE6283A2A, rule = 0x60C8C8C8,
    text = 0xFFE4E4E4, soft = 0xFFAEAEAE, dim = 0xFF6E6E6E, acc = 0xFF9ED6A2, warn = 0xFF4C64C8,
    core = 0xF0080808,
}
local function tline(x1, y1, x2, y2, w, c)   -- a line with thickness
    local dx, dy = x2 - x1, y2 - y1
    local l = math.max(0.001, math.sqrt(dx * dx + dy * dy))
    local nx, ny = -dy / l * w / 2, dx / l * w / 2
    draw.filled_quad(x1 + nx, y1 + ny, x2 + nx, y2 + ny, x2 - nx, y2 - ny, x1 - nx, y1 - ny, c)
end
local function tri(x1, y1, x2, y2, x3, y3, c) draw.filled_quad(x1, y1, x2, y2, x3, y3, x3, y3, c) end
local function sector(cx, cy, r1, r2, a0, a1, c)
    local n = 6
    for i = 0, n - 1 do
        local b0, b1 = a0 + (a1 - a0) * i / n, a0 + (a1 - a0) * (i + 1) / n
        local s0, c0, s1, c1 = math.sin(b0), math.cos(b0), math.sin(b1), math.cos(b1)
        draw.filled_quad(cx + s0 * r2, cy - c0 * r2, cx + s1 * r2, cy - c1 * r2,
            cx + s1 * r1, cy - c1 * r1, cx + s0 * r1, cy - c0 * r1, c)
    end
end
local function crosshair(x, y, s, c, w)
    draw.outline_circle(x, y, s * 0.5, c, 24)
    draw.outline_circle(x, y, s * 0.5 - 1, c, 24)
    tline(x, y - s * 0.8, x, y - s * 0.3, w, c); tline(x, y + s * 0.3, x, y + s * 0.8, w, c)
    tline(x - s * 0.8, y, x - s * 0.3, y, w, c); tline(x + s * 0.3, y, x + s * 0.8, y, w, c)
end
local ICONS = {
    follow = function(x, y, s, c, w)   -- a person
        draw.filled_circle(x, y - s * 0.42, s * 0.27, c, 16)
        draw.filled_quad(x - s * 0.6, y + s * 0.62, x - s * 0.36, y - s * 0.04, x + s * 0.36, y - s * 0.04, x + s * 0.6, y + s * 0.62, c)
    end,
    ["goto"] = function(x, y, s, c, w)   -- a map pin
        draw.filled_circle(x, y - s * 0.25, s * 0.42, c, 20)
        tri(x - s * 0.36, y - s * 0.05, x + s * 0.36, y - s * 0.05, x, y + s * 0.72, c)
        draw.filled_circle(x, y - s * 0.25, s * 0.16, C.panel, 12)
    end,
    guard = function(x, y, s, c, w)   -- a shield
        draw.filled_quad(x - s * 0.55, y - s * 0.62, x + s * 0.55, y - s * 0.62, x + s * 0.55, y + s * 0.05, x - s * 0.55, y + s * 0.05, c)
        tri(x - s * 0.55, y + s * 0.05, x + s * 0.55, y + s * 0.05, x, y + s * 0.75, c)
        tline(x, y - s * 0.45, x, y + s * 0.45, w, C.panel)
    end,
    regroup = function(x, y, s, c, w)   -- arrows closing in on a point
        draw.filled_circle(x, y, s * 0.16, c, 12)
        for _, d in ipairs({ { 0, -1 }, { 1, 0 }, { 0, 1 }, { -1, 0 } }) do
            local dx, dy = d[1], d[2]
            local tx, ty = x + dx * s * 0.34, y + dy * s * 0.34
            tline(x + dx * s * 0.75, y + dy * s * 0.75, tx, ty, w, c)
            tri(tx - dy * s * 0.16 + dx * s * 0.16, ty + dx * s * 0.16 + dy * s * 0.16,
                tx + dy * s * 0.16 + dx * s * 0.16, ty - dx * s * 0.16 + dy * s * 0.16, tx, ty, c)
        end
    end,
    hold = function(x, y, s, c, w)   -- a stop sign
        draw.filled_circle(x, y, s * 0.62, c, 8)
        draw.filled_rect(x - s * 0.36, y - s * 0.09, s * 0.72, s * 0.18, C.panel)
    end,
    swap = function(x, y, s, c, w)   -- two arrows, opposite ways
        tline(x - s * 0.6, y - s * 0.28, x + s * 0.3, y - s * 0.28, w, c)
        tri(x + s * 0.3, y - s * 0.52, x + s * 0.7, y - s * 0.28, x + s * 0.3, y - s * 0.04, c)
        tline(x + s * 0.6, y + s * 0.28, x - s * 0.3, y + s * 0.28, w, c)
        tri(x - s * 0.3, y + s * 0.04, x - s * 0.7, y + s * 0.28, x - s * 0.3, y + s * 0.52, c)
    end,
    fire_toggle = function(x, y, s, c, w, o)   -- crosshair, struck through for "hold fire"
        crosshair(x, y, s, c, w)
        if o.fire ~= "hold" then tline(x - s * 0.7, y + s * 0.7, x + s * 0.7, y - s * 0.7, w * 1.4, C.warn) end
    end,
    heal = function(x, y, s, c, w)   -- a cross
        draw.filled_rect(x - s * 0.18, y - s * 0.62, s * 0.36, s * 1.24, c)
        draw.filled_rect(x - s * 0.62, y - s * 0.18, s * 1.24, s * 0.36, c)
    end,
    resupply = function(x, y, s, c, w)   -- three rounds
        for _, dx in ipairs({ -0.45, 0, 0.45 }) do
            local bx = x + dx * s
            draw.filled_circle(bx, y - s * 0.3, s * 0.15, c, 10)
            draw.filled_rect(bx - s * 0.15, y - s * 0.3, s * 0.3, s * 0.85, c)
        end
    end,
    fire_sync = function(x, y, s, c, w)   -- two sights together
        draw.outline_circle(x - s * 0.25, y, s * 0.42, c, 20); draw.outline_circle(x - s * 0.25, y, s * 0.42 - 1, c, 20)
        draw.outline_circle(x + s * 0.25, y, s * 0.42, c, 20); draw.outline_circle(x + s * 0.25, y, s * 0.42 - 1, c, 20)
        draw.filled_circle(x - s * 0.25, y, s * 0.08, c, 8); draw.filled_circle(x + s * 0.25, y, s * 0.08, c, 8)
    end,
    attack = function(x, y, s, c, w)   -- a sight on a target
        crosshair(x, y, s, c, w)
        draw.filled_circle(x, y, s * 0.14, c, 10)
    end,
}
-- what picking each one does now (shown in the middle)
local function describe(it, o)
    if it.id == "follow" then return string.format("Come back and keep within %.1f m of you", st.ai_follow_dist or 2) end
    if it.id == "goto" then return "Move to the spot under your crosshair and hold that area" end
    if it.id == "regroup" then return "Come straight to you, right now" end
    if it.id == "hold" then return "Stay right here" end
    if it.id == "swap" then local g = ai.next_gun(); return g and ("Change to the " .. g.name) or "No other gun" end
    if it.id == "fire_toggle" then return o.fire == "hold" and "Shoot any threat" or "Only shoot when told to" end
    if it.id == "heal" then return "Heal player 1" end
    if it.id == "resupply" then return "Refill player 1's magazine" end
    if it.id == "fire_sync" then return o.fire == "sync" and "Back to shooting on her own" or "Shoot when you shoot" end
    if it.id == "attack" then return "Focus the enemy under your crosshair" end
    return ""
end
local MOVES = { follow = "Staying close", hold = "Holding", ["goto"] = "Moving", guard = "Holding an area", regroup = "Regrouping" }
local function draw_wheel()
    local ds = imgui.get_display_size()
    local k = ds.y / 1080
    local o = ai.order
    -- the spot he holds / guards (and the area he covers)
    if ai.active and st.ai_markers ~= false and (o.move == "hold" or o.move == "goto" or o.move == "guard") and o.pos then
        local sp = safe(function() return draw.world_to_screen(Vector3f.new(o.pos[1], o.pos[2] + 0.05, o.pos[3])) end)
        if sp then
            draw.filled_circle(sp.x, sp.y, 9 * k, 0x90000000, 4)
            draw.filled_circle(sp.x, sp.y, 6 * k, 0xD09ED6A2, 4)
        end
    end
    if not W.open then return end
    local cx, cy = ds.x / 2, ds.y / 2
    local R1, R2 = 118 * k, 262 * k
    local n = #ITEMS
    local step = 2 * math.pi / n
    local gap = 0.022
    draw.filled_rect(0, 0, ds.x, ds.y, C.shade)
    local now = os.clock()
    local labels = {}
    for i, it in ipairs(ITEMS) do
        local a = (i - 1) * step
        local sel = W.sel == i
        sector(cx, cy, R1, R2, a - step / 2 + gap, a + step / 2 - gap, sel and C.panel_sel or C.panel)
        if sel then sector(cx, cy, R2 - 4 * k, R2, a - step / 2 + gap, a + step / 2 - gap, C.acc) end
        -- on cooldown: greyed, with the seconds left
        local wait = (it.id == "heal" and st.next_heal - now) or (it.id == "resupply" and st.next_resupply - now) or 0
        local active = (it.id == "follow" and o.move == "follow") or (it.id == "goto" and (o.move == "goto" or o.move == "guard"))
            or (it.id == "hold" and o.move == "hold")
            or (it.id == "fire_sync" and o.fire == "sync")
        local rm = (R1 + R2) / 2
        local ix, iy = cx + math.sin(a) * (rm - 6 * k), cy - math.cos(a) * (rm - 6 * k) - 14 * k
        local col = wait > 0 and C.dim or (sel and C.acc or C.text)
        pcall(ICONS[it.id] or function() end, ix, iy, 22 * k, col, 3 * k, o)
        if active then   -- a small mark on the rim: this is the standing order
            local ax, ay = cx + math.sin(a) * (R2 - 14 * k), cy - math.cos(a) * (R2 - 14 * k)
            draw.filled_circle(ax, ay, 4.5 * k, C.acc, 12)
        end
        local text = it.label
        if it.id == "fire_toggle" and o.fire == "hold" then text = "Weapons free" end
        if it.id == "fire_sync" and o.fire == "sync" then text = "Stop firing with me" end
        if wait > 0 then text = text .. string.format("  %ds", math.ceil(wait)) end
        labels[#labels + 1] = { x = ix, y = iy + 34 * k, text = text, size = math.floor(17 * k),
            col = wait > 0 and C.dim or (sel and C.text or C.soft) }
    end
    -- thin rules round the ring and the core
    draw.outline_circle(cx, cy, R2 + 7 * k, C.rule, 96)
    draw.filled_circle(cx, cy, R1 - 8 * k, C.core, 64)
    draw.outline_circle(cx, cy, R1 - 8 * k, C.rule, 64)
    -- the middle: what the highlighted order does, or what she's doing now
    local it = W.sel and ITEMS[W.sel]
    local name = string.upper(st.p2_name())
    labels[#labels + 1] = { x = cx, y = cy - 52 * k, text = name, size = math.floor(14 * k), col = C.dim }
    if it then
        local t = it.label
        if it.id == "fire_toggle" and o.fire == "hold" then t = "Weapons free" end
        if it.id == "fire_sync" and o.fire == "sync" then t = "Stop firing with me" end
        labels[#labels + 1] = { x = cx, y = cy - 10 * k, text = t, size = math.floor(24 * k), col = C.text }
        labels[#labels + 1] = { x = cx, y = cy + 24 * k, text = describe(it, o), size = math.floor(13 * k), col = C.soft, wrap = (R1 - 20 * k) * 2 }
    elseif st.ai_trade_ok and st.ai_trade_ok() then
        local nm = (BTN_NAMES[st.p1_pad_style and st.p1_pad_style() or "xbox"] or BTN_NAMES.xbox).A
        labels[#labels + 1] = { x = cx, y = cy - 22 * k, text = "Access " .. st.p2_name() .. "'s inventory",
            size = math.floor(18 * k), col = C.text, wrap = (R1 - 24 * k) * 2 }
        labels[#labels + 1] = { x = cx, y = cy + 30 * k, text = nm .. "   select", size = math.floor(14 * k), col = C.acc }
    else
        labels[#labels + 1] = { x = cx, y = cy - 10 * k, text = "ORDERS", size = math.floor(24 * k), col = C.text }
        labels[#labels + 1] = { x = cx, y = cy + 22 * k, text = (MOVES[o.move] or o.move) .. "  /  " .. (ai.FIRE_NAMES[o.fire] or ""),
            size = math.floor(13 * k), col = C.acc }
    end
    if st.wheel_hint ~= false then
        labels[#labels + 1] = { x = cx, y = cy + R2 + 40 * k, text = "RIGHT STICK  or  1-8   choose          RELEASE RB  or  Z   confirm"
            .. ((st.ai_trade_ok and st.ai_trade_ok()) and ("          " .. string.upper((BTN_NAMES[st.p1_pad_style()] or BTN_NAMES.xbox).A) .. "  (stick in the middle)   inventory") or ""),
            size = math.floor(15 * k), col = C.soft }
    end
    imgui.set_next_window_pos(Vector2f.new(0, 0), 1, Vector2f.new(0, 0))
    imgui.set_next_window_size(Vector2f.new(ds.x, ds.y), 1)
    if imgui.begin_window("reunited_wheel", true, LABEL_FLAGS) then
        for _, l in ipairs(labels) do
            local pushed = pcall(imgui.push_font_size, l.size)
            local lines = { l.text }
            if l.wrap then   -- break long descriptions over two lines
                local ts = imgui.calc_text_size(l.text)
                if ts.x > l.wrap then
                    local mid = math.floor(#l.text / 2)
                    local cut = l.text:find(" ", mid, true) or l.text:sub(1, mid):match(".*() ")
                    if cut then lines = { l.text:sub(1, cut - 1), l.text:sub(cut + 1) } end
                end
            end
            for li, line in ipairs(lines) do
                local ts = imgui.calc_text_size(line)
                local y = l.y - ts.y / 2 + (li - 1) * ts.y * 1.15
                imgui.set_cursor_screen_pos(Vector2f.new(l.x - ts.x / 2 + 1, y + 1))
                imgui.text_colored(line, 0xFF000000)
                imgui.set_cursor_screen_pos(Vector2f.new(l.x - ts.x / 2, y))
                imgui.text_colored(line, l.col)
            end
            if pushed then imgui.pop_font_size() end
        end
        imgui.end_window()
    end
end

-- (v419) Player 2's wheel. A person playing player 2 holds RB on their controller for a small
-- radial menu in their own view (their half in split screen): Ping (a marker where player 2
-- aims, shown to both for a few seconds), Go to player 1 and Laser sight on / off. (A
-- flashlight item (v419) and Lure enemies (v420) were tried and taken out again.) Right stick
-- to choose, let go of RB to confirm, nothing chosen does nothing. RB is held back from the
-- game meanwhile; a quick tap (under 0.15 s) is handed on, so changing ammo
-- while aiming still works. Time doesn't slow (player 1 is still playing). st.p2_wheel = false:
-- off.
local P2W = { open = false, sel = nil, t0 = nil, hide_rb = false, inj = nil }
st.p2w = P2W
st.p2_wheel = st.p2_wheel ~= false
local P2_ITEMS = {
    { id = "p2_ping", label = "Ping" },
    { id = "p2_tele", label = "Go to player 1" },
    { id = "p2_laser", label = "Laser sight" },
}
ICONS.p2_laser = function(x, y, s, c, w)   -- a beam ending in a dot
    tline(x - s * 0.7, y + s * 0.35, x + s * 0.35, y - s * 0.18, w, c)
    draw.filled_circle(x + s * 0.45, y - s * 0.23, s * 0.18, c, 12)
end
ICONS.p2_tele = ICONS.regroup
ICONS.p2_ping = ICONS["goto"]
local function p2_state(it)
    if it.id == "p2_laser" then return st.p2_laser == true end
    return nil
end
-- where player 2 is aiming (their crosshair in split screen, Free Aim or tank aim on one
-- screen; else straight ahead of them)
local function p2_aim_point()
    if p2c.active then return target_point() end
    if st.tank and st.tank.aim_pos then return st.tank.aim_pos end
    local hp = st.hunk:call("get_Transform"):call("get_Position")
    local o = Vector3f.new(hp.x, hp.y + 1.45, hp.z)
    local d
    if st.vaim and st.vaim.active then
        local x, y, z = vaim_dir()
        d = Vector3f.new(x, y, z)
    else
        local f = st.hunk:call("get_Transform"):call("get_Rotation") * Vector3f.new(0, 0, 1)
        d = Vector3f.new(f.x, 0, f.z)
    end
    local b = Vector3f.new(o.x + d.x * 40, o.y + d.y * 40, o.z + d.z * 40)
    local ok, hit = pcall(cast_ray, o, b)
    local q = (ok and hit) or b
    return { q.x, q.y, q.z }
end
local function p2_run(id)
    if id == "p2_laser" then
        st.p2_laser = not (st.p2_laser == true)
        if st.save_config then pcall(st.save_config) end
        toast(st.p2_name() .. "'s laser sight " .. (st.p2_laser and "on" or "off"))
    elseif id == "p2_tele" then
        local ok, done = pcall(teleport_to_p1)
        if ok and done then say(st.p2_name() .. " teleported to " .. st.p1_name()) end
    elseif id == "p2_ping" then
        local ok, pt = pcall(p2_aim_point)
        if ok and pt then
            st.p2_ping = { p = pt, t = os.clock() }
            toast(st.p2_name() .. " marked a spot")
        end
    end
end
local function p2_wheel_ok()
    return st.p2_wheel ~= false and st.hunk ~= nil and not st.pending and not ai.active and st.p2_dev ~= nil
        and st.p2_dev.raw ~= nil and not menu.open and not menu.p2_lock and not (p2m and p2m.open)
        and not (st.ig and st.ig.open) and not p2c.menu_open() and not (st.cut_hide and st.cut_hide.on)
        and st.p2_down == nil and not st.in_cutscene()
end
local function p2_wheel_close(run)
    if P2W.open and run and P2W.sel then pcall(p2_run, P2_ITEMS[P2W.sel].id) end
    P2W.open, P2W.sel = false, nil
end
local function update_p2_wheel()
    if not p2_wheel_ok() then
        if P2W.open then p2_wheel_close(false) end
        P2W.hide_rb, P2W.t0 = false, nil
        return
    end
    P2W.hide_rb = true
    local b, rx, ry = st.p2_dev.raw()
    local held = (b & 1024) ~= 0 or P2W.fake_hold == true   -- (fake_hold / fake_stick: dev bridge)
    if P2W.fake_stick then rx, ry = P2W.fake_stick[1], P2W.fake_stick[2] end
    local now = os.clock()
    if not held then
        if P2W.open then
            p2_wheel_close(true)
        elseif P2W.t0 then
            -- a quick tap: hand it on to the game (ammo change while aiming, or whatever RB is)
            P2W.inj = { on = st.frame + 1, off = st.frame + 3 }
        end
        P2W.t0 = nil
        return
    end
    if not P2W.open then
        P2W.t0 = P2W.t0 or now
        if now - P2W.t0 >= 0.15 then P2W.open, P2W.sel = true, nil end
        return
    end
    if (rx * rx + ry * ry) > 0.36 then
        local ang = math.atan(rx, ry)   -- 0 = up, clockwise
        local n = #P2_ITEMS
        P2W.sel = math.floor(((ang + 2 * math.pi + math.pi / n) % (2 * math.pi)) / (2 * math.pi / n)) + 1
    end
end
local function p2_describe(it)
    if it.id == "p2_laser" then return st.p2_laser and "Hide the laser sight" or "Show the laser sight on the gun" end
    if it.id == "p2_tele" then return "Teleport next to " .. st.p1_name() end
    if it.id == "p2_ping" then return "Mark where you're aiming for both players" end
    return ""
end
local function draw_text_labels(win, labels)
    local ds = imgui.get_display_size()
    imgui.set_next_window_pos(Vector2f.new(0, 0), 1, Vector2f.new(0, 0))
    imgui.set_next_window_size(Vector2f.new(ds.x, ds.y), 1)
    if imgui.begin_window(win, true, LABEL_FLAGS) then
        for _, l in ipairs(labels) do
            local pushed = pcall(imgui.push_font_size, l.size)
            local ts = imgui.calc_text_size(l.text)
            local y = l.y - ts.y / 2
            imgui.set_cursor_screen_pos(Vector2f.new(l.x - ts.x / 2 + 1, y + 1))
            imgui.text_colored(l.text, 0xFF000000)
            imgui.set_cursor_screen_pos(Vector2f.new(l.x - ts.x / 2, y))
            imgui.text_colored(l.text, l.col)
            if pushed then imgui.pop_font_size() end
        end
        imgui.end_window()
    end
end
-- the ping: a green diamond with the distance, in each player's view (off their view: at its edge)
local function draw_ping(labels)
    local P = st.p2_ping
    if P == nil then return end
    local age = os.clock() - P.t
    if age > 6 then st.p2_ping = nil; return end
    local ds = imgui.get_display_size()
    local k = ds.y / 1080
    local views = {}
    local cam = sdk.get_primary_camera()
    local vp1 = cam and safe(function() return cam:call("get_ViewProjMatrix") end)
    if p2c.active then
        local reg = p2c.regions[st.split_layout] or p2c.regions[1]
        views[#views + 1] = { vp = vp1, r = reg.p1, who = p1_go() }
        local D = st.dual
        local vp2 = D and D.cam and safe(function() return D.cam:call("get_ViewProjMatrix") end)
        views[#views + 1] = { vp = vp2, r = reg.p2, who = st.hunk }
    else
        views[#views + 1] = { vp = vp1, r = { 0, 0, 1, 1 }, who = p1_go() }
    end
    local alpha = age > 5 and math.max(0, 6 - age) or 1
    local a8 = math.floor(0xFF * alpha) << 24
    for _, v in ipairs(views) do
        if v.vp then
            local a = safe(function() return v.vp * Vector4f.new(P.p[1], P.p[2] + 0.1, P.p[3], 1.0) end)
            if a then
                local w = math.abs(a.w) > 1e-4 and a.w or 1e-4
                local nx, ny = a.x / w, a.y / w
                if a.w <= 0.05 then nx, ny = -nx, -ny; if math.abs(ny) < 0.2 then ny = -1 end end
                local LIM = 0.9
                local off = a.w <= 0.05 or math.abs(nx) > LIM or math.abs(ny) > LIM
                if off then
                    local m = math.max(math.abs(nx), math.abs(ny), 1e-3)
                    nx, ny = nx / m * LIM, ny / m * LIM
                end
                local r = v.r
                local x = (r[1] + (nx + 1) / 2 * (r[3] - r[1])) * ds.x
                local y = (r[2] + (1 - ny) / 2 * (r[4] - r[2])) * ds.y
                local s = (off and 9 or 13) * k
                draw.filled_quad(x, y - s - 3 * k, x + s + 3 * k, y, x, y + s + 3 * k, x - s - 3 * k, y, (0x000000 | (math.floor(0x90 * alpha) << 24)))
                draw.filled_quad(x, y - s, x + s, y, x, y + s, x - s, y, (C.acc & 0x00FFFFFF) | a8)
                if not off then
                    local wp = v.who and safe(function() return v.who:call("get_Transform"):call("get_Position") end)
                    local dist = wp and math.sqrt((wp.x - P.p[1]) ^ 2 + (wp.y - P.p[2]) ^ 2 + (wp.z - P.p[3]) ^ 2)
                    labels[#labels + 1] = { x = x, y = y + s + 14 * k, text = string.format("%s%s", string.upper(st.p2_name()), dist and string.format("  %dm", math.floor(dist + 0.5)) or ""),
                        size = math.floor(14 * k), col = (C.text & 0x00FFFFFF) | a8 }
                end
            end
        end
    end
end
local function draw_p2_wheel()
    local labels = {}
    pcall(draw_ping, labels)
    if P2W.open then
        local ds = imgui.get_display_size()
        local r = { 0, 0, 1, 1 }
        if p2c.active then r = (p2c.regions[st.split_layout] or p2c.regions[1]).p2 end
        local x0, y0, x1, y1 = r[1] * ds.x, r[2] * ds.y, r[3] * ds.x, r[4] * ds.y
        local cx, cy = (x0 + x1) / 2, (y0 + y1) / 2
        local k = math.min(ds.y / 1080, math.min(x1 - x0, y1 - y0) / 760)
        local R1, R2 = 92 * k, 214 * k
        local n = #P2_ITEMS
        local step = 2 * math.pi / n
        local gap = 0.03
        draw.filled_rect(x0, y0, x1 - x0, y1 - y0, C.shade)
        for i, it in ipairs(P2_ITEMS) do
            local a = (i - 1) * step
            local sel = P2W.sel == i
            sector(cx, cy, R1, R2, a - step / 2 + gap, a + step / 2 - gap, sel and C.panel_sel or C.panel)
            if sel then sector(cx, cy, R2 - 4 * k, R2, a - step / 2 + gap, a + step / 2 - gap, C.acc) end
            local rm = (R1 + R2) / 2
            local ix, iy = cx + math.sin(a) * (rm - 6 * k), cy - math.cos(a) * (rm - 6 * k) - 12 * k
            local on = p2_state(it)
            pcall(ICONS[it.id] or function() end, ix, iy, 20 * k, sel and C.acc or C.text, 3 * k, {})
            if on ~= nil then
                local ax, ay = cx + math.sin(a) * (R2 - 14 * k), cy - math.cos(a) * (R2 - 14 * k)
                if on then draw.filled_circle(ax, ay, 4.5 * k, C.acc, 12) else draw.outline_circle(ax, ay, 4.5 * k, C.dim, 12) end
            end
            local text = it.label
            if it.id == "p2_tele" then text = "Go to " .. st.p1_name() end
            if on ~= nil then text = text .. (on and "  ON" or "  OFF") end
            labels[#labels + 1] = { x = ix, y = iy + 30 * k, text = text, size = math.floor(16 * k), col = sel and C.text or C.soft }
        end
        draw.outline_circle(cx, cy, R2 + 6 * k, C.rule, 96)
        draw.filled_circle(cx, cy, R1 - 7 * k, C.core, 64)
        draw.outline_circle(cx, cy, R1 - 7 * k, C.rule, 64)
        local it = P2W.sel and P2_ITEMS[P2W.sel]
        labels[#labels + 1] = { x = cx, y = cy - 42 * k, text = string.upper(st.p2_name()), size = math.floor(13 * k), col = C.dim }
        if it then
            labels[#labels + 1] = { x = cx, y = cy - 6 * k, text = it.id == "p2_tele" and ("Go to " .. st.p1_name()) or it.label, size = math.floor(21 * k), col = C.text }
            labels[#labels + 1] = { x = cx, y = cy + 22 * k, text = p2_describe(it), size = math.floor(12 * k), col = C.soft }
        else
            labels[#labels + 1] = { x = cx, y = cy - 6 * k, text = "QUICK MENU", size = math.floor(21 * k), col = C.text }
        end
        if st.wheel_hint ~= false then
            labels[#labels + 1] = { x = cx, y = cy + R2 + 30 * k, text = "RIGHT STICK   choose          RELEASE RB   confirm",
                size = math.floor(14 * k), col = C.soft }
        end
    end
    if #labels > 0 then draw_text_labels("reunited_p2wheel", labels) end
end
re.on_frame(function()
    local ok, err = pcall(update_p2_wheel)
    if not ok then p2_wheel_close(false); P2W.hide_rb = false; log.info("[reunited] player 2 wheel error: " .. tostring(err)) end
    pcall(draw_p2_wheel)
end)

re.on_frame(function()
    local ok, err = pcall(update_wheel)
    if not ok then close(false); log.info("[reunited] wheel error: " .. tostring(err)) end
    pcall(draw_wheel)
end)
if re.on_script_reset then re.on_script_reset(function() slow(false); mouse_look(false) end) end
end)()

