re.on_draw_ui(function()
    if not imgui.tree_node("Raccoon City: Reunited") then return end
    local changed = false
    local function check(label, key)
        if (key == "invulnerable" or key == "no_grab") and st.p2_child() then
            -- (v406) locked on for a child player 2: shown, can't be changed
            local dis = imgui.begin_disabled ~= nil and pcall(imgui.begin_disabled, true)
            local bb = st.bb_on and st.bb_on()
            imgui.checkbox(label .. (bb and " (Biohazard Babysitting rules)" or " (Sorry, can't hurt children pal! ;))"), not bb or key == "invulnerable")
            if dis then pcall(imgui.end_disabled) end
            return
        end
        local c, v = imgui.checkbox(label, st[key])
        if c then st[key] = v; changed = true end
    end
    local function slider_i(label, key, lo, hi)
        local c, v = imgui.slider_int(label, st[key], lo, hi)
        if c then st[key] = v; changed = true end
    end
    local function slider_f(label, key, lo, hi)
        local c, v = imgui.slider_float(label, st[key], lo, hi)
        if c then st[key] = v; changed = true end
    end

    imgui.text("Status: " .. st.msg)
    imgui.text("Co-op menu: hold L3 + R3 on any controller, or press F2")
    imgui.text("Presets:")
