        imgui.same_line()
        if imgui.button(pr.label) then st.apply_preset(pr) end
    end
    if st.hunk == nil then
        if st.pending == nil and imgui.button("Deploy HUNK") then st.ai_no_spawn = nil; pcall(spawn) end
    else
        if imgui.button("Rally HUNK to your side") then pcall(teleport_to_p1) end
        imgui.same_line()
        if imgui.button("Extract HUNK") then st.ai_no_spawn = true; pcall(despawn) end
    end
    -- controllers: a list per player, and player 2's button mapping
