            local labels, idx = {}, 1
            for i, c in ipairs(list) do labels[i] = c[2]; if c[1] == cur then idx = i end end
            imgui.set_next_item_width(220)
            local c, v = imgui.combo(label, idx, labels)
            if c and list[v] then set(list[v][1]); changed = true end
