            imgui.tree_pop()
        end
        imgui.set_next_item_width(160)
        slider_i("heal Leon below HP % (0 = never)", "ai_heal_pct", 0, 90)
        check("Refill Leon's magazine when it runs empty", "ai_resupply")
        if st.split then imgui.text("  (the AI pauses while split screen is on)") end
    end
    check("Split Screen Mode (Experimental)", "split")
    check("Player 2 In Cutscenes (Fun): seen and playable in cutscenes (off: hidden and still)", "p2_cutscene_fun")
    if st.split then
        imgui.same_line()
        imgui.set_next_item_width(140)
        local cl, vl = imgui.combo("layout", st.split_layout, { "Side by side", "Top / bottom" })
        if cl then st.split_layout = vl; changed = true end
        imgui.set_next_item_width(160)
        slider_i("player 1 field of view (100 = default)", "p1_fov_pct", 60, 150)
        imgui.set_next_item_width(160)
        slider_i("player 1 camera left / right (cm, + right)", "p1_side", -100, 100)
        imgui.set_next_item_width(160)
        slider_i("player 1 camera distance (100 = default)", "p1_dist_pct", 50, 200)
        if p2c.active and split.fps then imgui.text(string.format("  %.0f fps", split.fps)) end
        imgui.set_next_item_width(160)
        slider_i("game HUD shape (0 squeezed, 100 true shape)", "split_hud", 0, 100)
        check("bloom in split screen (off: no blinding light balls)", "split_bloom")
        -- (v443) the white skin / props fix, on by default (st.split_sss_fix)
        local csf, vsf = imgui.checkbox("white skin fix (things drawn flat white in split screen)", st.split_sss_fix ~= false)
        if csf then st.split_sss_fix = vsf; changed = true; pcall(st.refresh_split) end
        check("draw player 2's rooms when apart", "keep_p2_area")
        imgui.set_next_item_width(160)
        slider_i("player 2 field of view (100 = default)", "p2_fov_pct", 60, 150)
        imgui.set_next_item_width(160)
        slider_i("player 2 camera distance (100 = default)", "p2_dist_pct", 50, 200)
        imgui.set_next_item_width(160)
        slider_i("player 2 camera left / right (cm, + right)", "p2_side", -100, 100)
        if imgui.button("Refresh split screen") then st.refresh_split() end
        imgui.text("  P2 right stick turns the camera; HUNK aims and shoots where P2 looks.")
        imgui.text("  Both players are drawn every frame (the game renders a second view).")
    end

    imgui.spacing()
    if imgui.button("Reset settings to defaults") then
        local old = { st.weapon_up, st.weapon_left, st.weapon_right, st.throwable }
        for _, k in ipairs(SAVED) do st[k] = DEFAULTS[k] end
        changed = true
        pcall(apply_model)
        if old[1] ~= st.weapon_up or old[2] ~= st.weapon_left or old[3] ~= st.weapon_right or old[4] ~= st.throwable then
            if st.hunk then pcall(give_loadout) else build_loadout() end
        end
    end
    if changed then save_config() end
    imgui.tree_pop()
end)
